INSERT INTO Definition (word_id, language_id, pos_id, definition, example)
VALUES
(6456,3,1,'တစ်ဆယ့်ရှစ်လုံးမြောက်မွန်ဗျည်း။',NULL)
,(6457,3,9,'ပါဠိဘာသာမှ မွန်ဘာသာပြန်ရာတွင်သုံးသော ကတ္တားပုဒ်နောက် နာမဝိသေသနပုဒ်ရှေ့­ လာသောစကားလုံး။ (‘ဒ’ ကိုတွေ့လျှင် ၄င်းနောက်­ နာမဝိသေသနပုဒ်လာတော့မည်ဟုသိနိုင်သည်။ ‘ဒ’ ကို ဖြုတ်လိုက်လျှင်လည်း အဓိပ္ပါယ်မပြောင်းသွားပါ။)','“ရာဇာဓိရာဇံ၊ တဳလဂှ်ဒ မစိုန်ဒှ်တဴသၟိၚ်မွဲ မပြဲနူသၟိၚ်ဂမၠိုၚ်။ အဂ္ဂမုနိန္ဒံ၊ န်ကျာ်တြဲသၟိၚ်ခမဳ မစိုန်ဒှ်တဴကၞတ်ညးမပြဲဂှ်။ အဟံ၊ ၚ်အဲ။ နမာမိ၊ ပ္ဍံလ္ၚောဝ်ရအဴ။” = “မင်းတကာတို့ထက် မြတ်သောမင်းတစ်ပါးဖြစ်တော်မူထသော သူမြတ်တကာတို့၏အထွတ်အမြတ် ရဟန်းမင်းဖြစ်တော်မူထသော မြတ်စွာဘုရားကို အကျွန်ုပ်သည် ရှိခိုးပါ၏။” (မှတ်ချက်။ ‘တဳလဂှ်ဒ’ ကို ‘တဳလဂဒ္ဒ’ ဟုလည်းရေးကြောင်း တွေ့ရသည်။)')
,(6458,3,9,'စာအရေးအသားပြေပြစ်အောင် ထောက်ကူသောစကားလုံး။','(မွန်ဘာသာတွင် နာမဝိသေသနဝါကျကဏ္ဍကို ‘ဍေံ’ ဖြင့်အစချီဖွဲ့၍ ထိုဝါကျကဏ္ဍတွင် ကံလိုသောကြိယာကို သုံးသောအခါ ‘ညး’ က လိုက်လာတတ်သည်။ ထိုအခါ ‘ဍေံ’ နှင့် ‘ညး’ ကြားတွင် ခွဲခြားလို၍ ‘ဒ’ ကို ကြားခံပစ္စည်းအဖြစ် သုံးနိုင်သည်။ ဝေါဆရာတော်၏စာပေတွင် အထူးသဖြင့်တွေ့ရသည်။) || “ယွံမၞးတံ၊ ဍေံမသ္ကေက်လောန်၊ ဍေံဒညးမကလှန်လဝ်ပးမဒးရး၊ ဍေံမသွတ်လောန်ဗၞတ် တၟာမုဟ်သော်၊ ဍေံမထ္ၜောံလောန်၊ ဍေံဒညးမတက်စုတ်ပ္ဍဲလ္ပးမ္ဂး လ္ပးဂှ်မဒးကၠိုဟ်အာ၊ ဍေံဂတဝ်တဴပ္ဍဲဍာ်ဂှ်တဏိၚ်မၞုံဂုန်မဖှ်သာ်ဂှ် မူရဴညးမွဲမဒးဂၞပ် မရာန်တဏိၚ်အဲဝွံရော။” = (ဇ—၃၈၇။ အစွောံ။) || (ဤဝါကျတစ်ခုလုံးတွင် ‘ဍေံ’ ဖြင့်အစချီဖွဲ့ထားသော နာမဝိသေသနပုဒ်ပေါင်း (၆) ခုရှိသည့်အနက် (၂) ခုတို့တွင် ‘ညး’ ပါလာသဖြင့် ‘ဒ’ ကိုသုံးထားသည်။)')
,(6459,3,1,'ဒန်ပူ။','(ကြိ) တွန်းကန်သည်။')
,(6459,3,1,'ဒန်ပူ။','‘ထက’ ရှု။')
,(6460,3,1,'ဘီလူး။',NULL)
,(6461,3,1,'ဒါယိကာ။ ဒကာ။','ဒကာဇြပ် = ဇရပ်ဒါယိကာ။ ဇရပ်ဒကာ။ || ဒကာဘာ= ကျောင်းဒါယိကာ။ ကျောင်းဒကာ။ || ဒကာကျာ် = ဘုရားဒါယိကာ။ ဘုရားဒကာ။ || ဒကာတြုံ = ဒါယိကာ။ ဒကာ။ || ဒကာဗြဴ = ဒါယိကာမ။ ဒကာမ။')
,(6462,3,1,'ဒါယိကာမ။ ဒကာမ။','‘ဒါယိကာဗျန်’ နှင့်အတူတူ။')
,(6463,3,1,'ထောင့်။ အစွန်း။ အစွန်။','“ထေရ်ဇၞော်ၜါ ဒၟံၚ်ပ္ဍဲဘာသၟတ် ဒကဴဘာဇေတဝန်ဂှ်ရ။” (ဇ—၂၈၃။ အစွောံ။) = “နှစ်ပါးကုန်သော အိုမင်းကုန်သော မထေရ်တို့သည် (ဇေတဝန်) ကျောင်း၏အစွန်ဖြစ်သောကျောင်း­ နေကုန်၏။” (ညောင်ကန်)')
,(6463,3,1,'ထောင့်။ အစွန်း။ အစွန်။','“ပ္ဍဲဒကဴဘာဇေတဝန်ဂှ်—။” (ဇ—၃၄၄။အစွောံ။) = “ဇေတဝန်ကျောင်းတော်အစွန်းဝယ်—။” (ညောင်ကန်) || “ဒကဴဗ္ၚဂှ် တၞံတာနွံ။” (ဇ—၃၈၉။ အစွောံ။) = “လယ်၏အစွန်း­ တစ်ခုသော (ထန်းပင်ရှိ၏။)” (ညောင်ကန်)')
,(6464,3,1,'ရန်သူ့လက်ခုပ်။ ရန်သူ့လက်တွင်း။','အာစိုပ်ဒကဴတဲသတြု၊ လုပ်ဒကဴတဲသတြု (ဇ—၄၂။ အစွောံ။) = ရန်သူ့လက်ခုပ်တွင်းသို့ ဝင်ရောက်သည်။')
,(6465,3,1,'မျက်ထောင့်။ (ပါဠိ—အပါၚ်္ဂ)',NULL)
,(6466,3,4,'ကွဲသည်။','ဖျုန်ဂြိုဟ်ဒကး = နှလုံးကွဲသည်။')
,(6467,3,4,'ကွဲပြီးပြန့်ကြဲသည်။ ကွဲပြဲသည်။',NULL)
,(6468,3,1,'‘ထကေၚ်’ ရှု။',NULL)
,(6469,3,1,'အနှံ။','ဒကောင်ယဴ = မုရောစပါးနှံ။ || ဒကောင်သြောအ် = စပါးနှံ။ || “သၟိၚ်တ္ၚေက်မွဲတုန် သြောံသာလဳမဂၠိုၚ်ဒကောင်ဂှ် ပ္ကောံကေတ်ဂိုၚ်ဖျဴ သွက်မိကဵုမၜါရ။” (ဇ—၄၈၄။အစွောံ။) = “ကျေးမင်းသည်ကား များစွာကုန်သော သလေးနှံတို့ကို တပေါင်းတည်းပြု၍ — ဆောင်၍ မိဘတို့အားပေး၏” (ညောင်ကန်)')
,(6469,3,9,'အနှံ။ အလုံး။ အပွင့်။','သြောံၜါဒကောင် = စပါးနှစ်နှံ။ || မတ်မွဲဒကောင် = ကျောက်မျက်ရတနာတစ်လုံး။')
,(6470,3,1,'ဆောင်းရာသီ။',NULL)
,(6470,3,4,'ထုံးသည်။ ဖွဲ့ချည်သည်။','“မဂဒူသရိတ်ကေတ်မခါ ပ္ဍဲလပုဟ်တဲ ထကတ်ပ္ဍဲမုဟ်ယာတ် စဴအာရ။” (အကြီုရာဇာဓိရာဇ်) = “မဂဒူးသည် လက်ချောင်းတွင်တင်သော ဟင်းနုနွယ်စေ့များကို ဆွတ်ယူ၍ ပုဆိုးစွန်း­ ထုံးချည်၍ ပြန်သွား၏။” || ဒကတ်သော် = ဆံပင်ထုံးသည်။')
,(6471,3,1,'ဆံရစ်။',NULL)
,(6472,3,1,'ဖြတ်ထားသောအပိုင်း။','ဒကုတ်ဆု၊ ဆုဒကုတ် = သစ်ပိုင်း။')
,(6472,3,4,'ပြတ်သည်။ ဖြတ်သည်။ ပြတ်စေသည်။','“ဗောဓိသတ် (ဒြာဲထဝ်) မွဲဂှ် အာဂတတုဲ သရတ်ဒးစုတ်ပးဓနက်ဂှ်ရ။ ‘အဲရုန်ဒကုတ်ကၠေံညိ’ ရဴဝွံချပ်တုဲ ရုန်တရဲဓဇက်မွဲလစုတ်ဂှ် စၞာံဇိုၚ်ဂှ် ထကုတ်အာရ။ရုန်မွဲလစုတ်ပၠန် ဖျုန်ဇိုၚ်ထကုတ်အာရ။ ရုန်ဓဇက်မွဲလစုတ်ပၠန် လတေၚ်ထကုတ်အာတုဲ ဇုက်စၞာံဂှ်ဒွံဒၟံၚ်ဇုတ်ဂှ်ရ။” (ဇ—၃၅၉။ အစွောံ။) = “ဘုရားလောင်းသည် သမင်တို့၏ရှေ့မှသွားလတ်သော်ခြေ­ကျော့ကွင်းမိ၍ ‘ကျော့ကွင်းကိုဖြတ်အံ့’ ဟုငင်၏။ အရေသည် ပြတ်၏။ တစ်ဖန်ငင်လတ်သော် အသားသည် ပြတ်၏။ တစ်ဖန်ငင်လတ်သော် အကြောသည် ပြတ်၏။ ကျော့ကွင်းသည်အရိုးသို့ဆိုက်၍တည်၏။” (ညောင်ကန်)')
,(6472,3,9,'အပိုင်း။၊','ဒုန်မွဲဒကုတ် = ဝါးတစ်ပိုင်း။ || ဆုပန်ထကုတ် = သစ်လေးပိုင်း။')
,(6473,3,4,'စိတ်ကိုစင်ကြယ်အောင် ပြုပြင်သည်။','“ပ္ဍဲသရာံပါပ်လေဝ် က္ဍုဟ်မၠေံစိုတ်အိုတ် ဒကုတ်ၚးစိုတ်ညိ။” (ဇ—၄ဝ။ အစွောံ။) = “မကောင်းမှု­လည်း ရွံရှာမုန်းတီး၍ စိတ်ကိုစင်ကြယ်အောင် ပြုပြင်သုတ်သင်လော့။”')
,(6474,3,4,'တပ်မက်သောစိတ်ကိုဖြတ်ပစ်သည်။','“ယွံမတံ၊ အဲဒကုတ်စိုတ်ကဵုဇွစိၚ်ရ။ ပတွဵုနူဝွံ — အဲဟွံလုပ်ဇွစိၚ်ရ” ကၠဵုဂး။ (ဇ—၁၄၈။ အစွောံ။) = “အိုသင်တို့၊ ငါသည် ဆင်သေကောင်နှင့် တပ်မက်သောစိတ်ကို ဖြတ်အပ်ပြီ။ ယခုမှစ၍ ဆင်သေကောင်ထဲသို့ ငါမဝင်တော့ပြီ”ဟုမြေခွေးဆို၏။')
,(6475,3,4,'အပိုင်းပိုင်းပြတ်သည်။ အပိုင်းပိုင်းဖြစ်အောင်ဖြတ်သည်။','“ဗြဲလွဟ်မဂဵုတဴသီုသၞပၟတ်ဂှ် ဒတုံစှ်ေဒးဇကုဍေံတံတုဲ ဇကုဍေံတံဂှ် ဒကုတ်ဒကန်အာအိုတ်ရ။” (ဇ—၅၂၂။ အစွောံ။) =“အလျှံတဝင်းဝင်းတောက်သော လက်နက်မိုးသည် သူတို့ကိုယ်ကိုထိ၍ သူတို့ကိုယ်သည် အပိုင်းပိုင်းပြတ်ကုန်၏။” || “(စိၚ်ဇေဟ်စုတ်တုဲ) ကြုတ်မလေဝ် တသဵုတိတ်အာ၊ ဗြံက်က္ဍိုပ်မလေဝ် လကောတ်အာ၊ ဇုတ်သ္ကဲသီုဖအိုတ်လေဝ် ဒကုတ်ဒကန်အာ” ဇာဒိသိုၚ်ဂးကဵုကၠဵုသမၠီု။ (ဇ—၁၄၃။ အစွောံ။) = “ဆင်နင်းသဖြင့် သင့်အူတို့သည်လည်း ပြန့်ကြဲထွက်ကုန်၏။ သင့်ဦးခေါင်းခွံသည်လည်း ကြေမွကုန်၏။ သင့်နံရိုးတို့သည်လည်း အပိုင်းပိုင်းပြတ်ကုန်၏။” || “ပ္ဍဲဗပါတ်တၟံမၞုံသၠုၚ်ကၠံဖိဟ်ဂှ် (တြုံကမၠတ်) ဒတုံစှ်ေ ဒကုတ်ဒကန်ချိုတ်အာရ။” (ဇ—၄၁၉။ အစွောံ။) = “ခိုးသူသည် (အသူတစ်ရာနက်သော) ချောက်­လျှင် မှုန့်မှုန့်ညက်ညက်ကြေ၍ သေ၏။” (ညောင်ကန်) || “ဗှ်ေတတ်ကၠေံက္ဍိုပ်သၟိၚ်တုဲ ဗှ်ေကလောအ်ဒကုတ်ဒကန်ကၠေံတုဲ တိုပ်ကၠေံဇွသၟိၚ်ရ။” (ဇ—၄၁၆။အစွောံ။) = “မင်းကို သင်ခေါင်းဖြတ်၍ အတုံးတုံးအပိုင်းပိုင်းဖြစ်အောင် ခုတ်ပိုင်းဖြတ်ပစ်ပြီးလျှင်မင်း၏အလောင်းကို မြေမြှုပ်ပစ်လော့။”')
,(6476,3,1,'ဖွတ်။','ခၟာဲဒကောတ် = ဖွတ်ဥ။ || “ဗောဓိသတ်ပိုဲ ဒှ်ဒကောတ်—။” (ဇ—၃၂၅။ အစွောံ။) = “ဘုရားလောင်းသည် ဖွတ်မျိုး­ဖြစ်၍—။” (ညောင်ကန်)')
,(6477,3,1,'ဖွတ်မိကျောင်း။ (ပါဠိ—ဂေါဓိကာ)',NULL)
,(6478,3,3,'(ဆံပင်) တွန့်သော။ ကောက်ကွေးသော။ စုတ်ဖွားဖြစ်သော။ (ပါဠိ—ဝလိတကေသဳ)','“လၟသောနုတ္တရဂှ် တမတ်တၞဴဍေံဇၞော် သော်ဍေံဒကာန်။” (ဇ—၅၁၄။ အစွောံ) = “သောနုတ္တရမုဆိုးသည် ကြီးသောသလုံးသားရှိ၍ တွန့်သောဆံပင်ရှိ၏။” || ‘နွံကုသဵုမဇၞော်၊မၞိဟ်သော်ထကာန်။’ (အကြီုရာဇာဓိရာဇ်) = ‘ဆံပင်စုတ်ဖွားနှင့်လူသည် ပြုခဲ့ဖူးသောကုသိုလ်ကြီးမား၏။’ || “က္ဍိုပ်လကိုဟ်ဂှ်ပၠန်လေဝ် သော်ဓကာန်ဓကာန် ပၟတ်ကၠာန်ဒးတူသၠောတ်။” (သၠပတ်စန္ဒဝတဳ) = “ထိုဘီလူးဦးခေါင်းသည်လည်း ဆံပင်တွန့်တွန့်ဖြင့် မီးရှိန်ဟပ်၍ လောင်ကျွတ်သွားရ၏။”')
,(6479,3,16,'‘သကေပ်’ ရှု။',NULL)
,(6480,3,1,'၁။ ခေါင်းဆောင်။ အကြီးအကဲ။','ဒကိုပ်က္ၜၚ် = သင်္ဘောသူကြီး။ || ဒကိုပ်ဂၠုၚ် = လှေသူကြီး။ || ဒကိုပ်အ္စာဘာ = ကျောင်းအုပ်ဆရာ။')
,(6480,3,1,'၂။ အဖုံး။','ဒကိုပ်ပလၚ် = ပုလင်းအဖုံး။')
,(6480,3,1,'၃။ ဒုကုဋ်သင်္ကန်း။ နှစ်ထပ်သင်္ကန်း။', NULL)
,(6481,3,1,'မြို့ဝန်။',NULL)
,(6482,3,1,'စစ်ဦးစီး။ စစ်သူကြီး။ စစ်သေနာပတိ။','‘သကိုပ်ပၞာန်’ ရှု။')
,(6483,3,1,'တရားစစ်သူကြီး။ ဓမ္မသေနာပတိ။ (အရှင်သာရိပုတ္တရာ)','“တိပိုန်သာရိပိုတ်ဒကိုပ်ပၞာန်ဓဝ်ဂှ် ကေုာံခမဳမသုန်ကၠံ ပဒတဴပ္ဍဲဘာဝေဠုဝိုန်—။” (ဇ—၂၂၁။ အစွောံ။) = “တရားစစ်သူကြီးဖြစ်သော အရှင်သာရိပုတ္တရာသည် ငါးရာကုန်သော ရဟန်းအပေါင်းနှင့်တကွ ဝေဠုဝန်ကျောင်းတော်­နေ၏။” (ညောင်ကန်) || ‘သကိုပ်ပၞာန်ဓဝ်’ ဟုလည်းရေးသည်။')
,(6484,3,1,'တရားဆုံးဖြတ်သူ။ တရားသူကြီး။ (ပါဠိ—အက္ခဒဿ)','ညးမကေၚ်ဒှ်ဒကိုပ်ဗစာပ္ဍဲကိုပ်ကၠာ = ရှေး­တရားသူကြီးဖြစ်ခဲ့ဖူးသောသူ။ (ပါဠိ—ပုရာဏဝေါဟာရက) ‘နာဲဗစာ’ နှင့်အတူတူ။')
,(6485,3,1,'ခရီးသွားခေါင်းဆောင်။ ကုန်သည်မှူး။','“ဗောဓိသတ်ပိုဲ ဒှ်ဒကိုပ်သာကွဳ စဳရေၚ်ကွဳတုဲ အာဗၞိက်ရ။” (ဇ—၄၉၃။ အစွောံ။) = “ဘုရားလောင်းသည် လှည်းကုန်သည်မှူးဖြစ်၍ လှည်းတို့ကိုစီရင်၍ ကုန်အရောင်းအဝယ်သွား၏။”')
,(6486,3,1,'လှည်းပုံတောင်း။ ရထားပုံတောင်း။','“ယၚ်ဗြုကွဳမစုတ်လဝ်ကၠေၚ် ပ္ဍဲဒကောမ်ကွဳကီု။” (ဇ—နာရဒ။ အစွောံ။) = “သင်၏ဝမ်းကို ဆီဖြင့်သွန်းအပ်သော ရထားပုံတောင်းသဖွယ်မှတ်အပ်၏။” (မင်းပူးဦးသြဘာသ)')
,(6487,3,1,'ပုတ်သင်။ ပုတ်သင်ညို။','“ဗောဓိသတ် (ဒေဝတဴ) ပရုပ်ဒကုဲမွဲတုဲ ဂတမုက်ဝဍ္ဎကဳ ဒြေပ်အာ။” (ဇ—၁၂၁။ အစွောံ။) = “(ဘုရားလောင်းနတ်သည်) ပုတ်သင်အသွင်ဖန်ဆင်း၍ ဤလက်သမားတို့၏ရှေ့မှသွား၍—။” (ညောင်ကန်)')
,(6488,3,1,'ပုတ်သင်ပျံ။ (ပါဠိ—ပမ္ပက)',NULL)
,(6489,3,4,'အိပ်ငိုက်သည်။','“ညးၜါအစောံကွာ်ဂၠိုၚ် ကွိုၚ်ကွုဲအာတုဲ ဂၠုညိထကုဲလှိၚ်အာရ။” (သၠပတ်စန္ဒဝတဳ) = “နှစ်ဦးသားတို့သည် လျှောက်ပါများ၍ ညောင်းညာသွားကာ အနည်းငယ်ညမှောင်သောအခါ အိပ်ငိုက်အိပ်ပျော်သွားကြ၏။”')
,(6489,3,4,'အိပ်ငိုက်သည်။','“တၠအဲကွာ်ဂၠိုၚ် ကွိုၚ်ကွုဲဒကုဲ တိက်ရောဟွံၚုဟ်။” (သၠပတ်စန္ဒဝတဳ) ဒကုဲဒညံက် (ကြိ) ငိုက်မျဉ်းသည်။')
,(6490,3,1,'ဖျာ။','“လးကဵုထကဝ် လးယာတ်တုဲ ကဵုသ္တိက်ရ။” (ဇ—၃ဝ၂။ အစွောံ။) =“ဖျာကို၄င်း အဝတ်ကို၄င်း ခင်းပေးပြီးလျှင် အိပ်စေ၏။” || “စဵုဗိုၚ်လဝ်ဇၞိက် လးလဝ်ဒကဝ်အိုတ်ရ။” (သၠပတ်ဝၚ်သီသၟိၚ်ဓမ္မစေတဳ) = “တင်းတိမ်ကာရံ၍ ဖျာခင်းထားကုန်၏။”')
,(6491,3,1,'သင်ဖြူးဖျာ။',NULL)
,(6492,3,1,'ပိုးထည်လွှမ်း၍ ချုပ်လုပ်ထားသောအခင်း၊ ဖုံ။',NULL)
,(6493,3,1,'သပေါ့ဖျာ။',NULL)
,(6494,3,1,'အိပ်ရာထိုင်ခင်းအဖြစ်သုံးသော ဖျာအမျိုးအစားအားလုံးကို ချုံခေါ်သောအသုံး။',NULL)
,(6495,3,1,'ကျပ်။ တစ်ကျပ်သား။','ထဝ်မွဲဒကေဝ် = ရွှေတစ်ကျပ်သား။ || သြန်စှ်ဒကေဝ် = ငွေတစ်ဆယ်ကျပ်။ || “လိၚ်ဇိုၚ်အဲအဴ၊ တြဴထကေဝ်တုန်။ ၚုဟ်ဂဥုဲစိ၊ ပိထကေဝ်ပၠန်။” (လိက်သုပိဏ္ဏကုမ္မာ။ မၚ်သၚ်ကြာ။) = “ငါ့ခြေကြွခကား ခြောက်ကျပ်၊ ဆေးဖိုးကား သုံးကျပ်။”')
,(6496,3,1,'လေ၏တိုက်ခတ်နှုန်း။ လေတိုက်နှုန်း။','“စှ်ေဍိုက်က္ၜၚ်ရ၊ တုဲပယာတြာ။ ဓရိုက်မှာလီ၊ တီဒကေဝ်ကျာ။ သ္ၚေဝ်ဒကေဝ်ကျာ၊ ဂၚ်ဂါသရုၚ်။” (လိက်ဗောဓိသတ်စှ်။ ပဏ္ဍိတ။) =“သင်္ဘောသို့ဆင်း၍စီးသော လေတိုက်နှုန်းကိုသိသော မာလိန်မှူးသည် လေတိုက်နှုန်းကိုကြည့်၍ပင်လယ်ကိုဖြတ်ကူး၏။”')
,(6497,3,1,'၁။ (သစ်ပင်၏) အခေါက်။','ဒကောဝ်ဆု = သစ်ခေါက်။ || ‘သကောဝ်’ ဟုလည်းရေးသည်။')
,(6497,3,1,'၂။ ခဲသတ္တု။', NULL)
,(6498,3,4,'မွှေသည်။','‘ထကဵု’ ရှု။')
,(6499,3,4,'၁။ မွှေနှောက်သည်။',NULL)
,(6499,3,4,'၂။ စိတ်ဆင်းရဲအောင်လုပ်သည်။',NULL)
,(6500,3,1,'ပဒုမာကြာ။','ဒကှ်မသုန် = ပဒုမာကြာငါးမျိုး။ || “ပ္ဍဲလစဂှ် သွာၜါ၊ ဥပ္ပဵုပိ၊ ဒကှ်မသုန်နွံ။” (ဇ—၅၈။ အစွောံ။) = “ထိုကန်­ ကုမုဒြာကြာနှစ်မျိုး၊ ဥပ္ပလကြာသုံးမျိုး၊ ပဒုမာကြာငါးမျိုးရှိ၏။”')
,(6501,3,4,'ရွေသည်။ ပါးပါးလွှာလွှာခုတ်ထစ်သည်။ (to whittle)','ဍဒကောဟ်ကၞောတ် =တံစို့ကိုရွေသည်။ (to whittle a spit) || “ကဂှ် ပိုဲဖအၚ်ကဵုလ္ၚပၟတ်ဂှ်တုဲ ပိုဲစကဵုပုၚ်ရ” ဍေံချပ်တုဲဍေံဒကောဟ်ကၞောတ် ဗဒှ်ပၟတ်ရ။ (ဇ—၃၄။ အစွောံ။) = “ဤငါးကို မီးကျီး­ကင်၍ ထမင်းနှင့်စားကုန်အံ့” ဟု မီးမွှေးကုန်၏၊ တံစို့ကိုရွေကုန်၏။ || ‘သကောဟ်’ (ကြိ) ရှု။')
,(6502,3,1,'(စာရေးရန်) ကျောက်တံ။',NULL)
,(6503,3,1,'ကျည်တောက်။','ဒကောအ်ကံလဴ = မျှားကျည်တောက်။ || ဒကောအ်တၞိၚ် = အပ်ထည့်သောကျည်တောက်။ || ဒကိုအ်ယန်မတ် = မျက်စဉ်းကျည်။ (ပါဠိ—အဥ္ဇနိ) || သူရာဒကောအ် (ဇ—၇၈။ အစွောံ။) = သုရာထည့်သောကျည်တောက်။ ||“တဏိၚ်ဂှ်စုတ်ပ္ဍဲဒကိုအ်တုဲ—။” (ဇ—၃၈၇။ အစွောံ။) = “ထိုအပ်ကို အပ်ကျည်­ထည့်၍—။” (ညောင်ကန်) || “ညံၚ်ဝိုဟ်ညးမထဏက်လဝ် ပ္ဍဲဒကောအ်ရ။” (ဇ—၅၃ဝ။ အစွောံ။) = “ကျည်တောက်­ ထောင်းသိပ်ထားသော မုန့်ညက်ကဲ့သို့။”')
,(6503,3,9,'သေနတ်အရေအတွက်ကို ရေတွက်ရာတွင်သုံးသောစကားလုံး။ အလက်။','သေနာတ်ၜါဒကိုအ် = သေနတ်နှစ်လက်။')
,(6504,3,1,'လှည်းပုံတောင်း။',NULL)
,(6505,3,1,'မီးထောင်းဆုံ။ မီးဖွတ်ဆုံ။',NULL)
,(6506,3,1,'‘ဒကောအ်’ ရှု။',NULL)
,(6507,3,4,'ခွဲပစ်သည်။ ချိုးသည်။ (?) (ပါဠိ—ဘိန္ဒိတ)',NULL)
,(6508,3,1,'ရင်ခတ်ပင်။ ရင်ခတ်သီး။',NULL)
,(6509,3,4,'၁။ ဖြောင့်သည်။ ဖြောင့်တန်းသည်။ တည့်တည့်ဖြစ်သည်။ တူရူဖြစ်သည်။ ရှေးရှုသည်။','“ဆုဗောဓိပလောဟ်ကျာ်ဂှ် — နွံကဵုလမှဳမဒ္ဂူ။” (သၠပတ်ဂမ္စာဲဓါတ်) = “ဘုရားပွင့်တော်မူရာဗောဓိပင်သည် ဖြောင့်တန်းသောပင်စည်ရှိ၏။” || “ဂၠဴဥဿဘမွဲ မဒှ်ဇၞော်မကွာ်ဂတဂှ် ဗွဲမဒ္ဂူဂှ် ယဝ်ဍေံသ္အာမ္ဂး ဂၠဴကၟက်ဂမၠိုၚ်ဝုန်ဒၚ်တံဂှ် ဗွဲမဒ္ဂူဂှ် ဍေံအာဒ္ဂူတဴကီုရ။” (ဇ—၃၃၄။ အစွောံ။) = “ရှေ့ဆောင်နွာလားသည် ဖြောင့်စွာအကယ်၍သွားအံ့၊ ခပ်သိမ်းသော နောက်နွားများလည်း ဖြောင့်စွာလိုက်ကုန်၏။” || “ဗွဲဒိုဟ်တြၚ်ပလိုတ်ဂှ် တိတ်အာတုဲ ဗွဲမဒ္ဂူဂှ်အာတုဲ ညာတ်ကေသရာဇာဒိသိုၚ်မွဲရ။” (ဇ—၄၂၂။ အစွောံ။) = “အနောက်တံခါးဖြင့်ထွက်၍ ဖြောင့်စွာသွားသည်ရှိသော် ကေသရာဇာခြင်္သေ့ကို မြင်လတ္တံ့။” (ညောင်ကန်) || “မၚ်ဗၠာဲလၞုဟ်ဂှ် ဒွါန်တိုန်ဆုဗလဲ ရပ်ကၞာၚ်မွဲ ဗလဲဖျေံမဒ္ဂူကဵုဇကု။” (ဇ—၇၁။ အစွောံ။) = “ပျင်းရိသောလုလင်သည် ရေခံတက်ပင်သို့တက်၍တစ်ခုသောအကိုင်းကိုကိုင်၍ မိမိဘက်သို့ ဆွဲငင်ချ၏။” || “ပူဂဵုအရဳတံဂှ် မၞုံတရဴမဒ္ဂူကဵုစဴနိဗ္ဗာန်အိုတ်ရ။” = “အရိယာပုဂ္ဂိုလ်တို့သည် နိဗ္ဗာန်သို့ ရှေးရှုကြကုန်၏။”')
,(6509,3,4,'၁။ ဖြောင့်သည်။ ဖြောင့်တန်းသည်။ တည့်တည့်ဖြစ်သည်။ တူရူဖြစ်သည်။ ရှေးရှုသည်။','“အိုတ်သတ်ပန်ဟဳအာပ္ဍဲဆုဂှ် စိုပ်သ္ဂာဗတံ စိုပ်ဋ္ဌာန်မဒ္ဂူကဵုဘာဣသိ။” (ဇ—၇၃။ အစွောံ။) = “လေးယောက်ကုန်သောသူတို့သည် သစ်တုံး­မျောပါသွားရာ ညဉ့်သန်းခေါင်အချိန်­ ရသေ့ကျောင်းအနီး တူရူအရပ်သို့ရောက်၏။”')
,(6509,3,4,'၂။ ဖြောင့်မတ်သည်။ ဖြောင့်မှန်သည်။ ရိုးသားသည်။ သစ္စာရှိသည်။ သစ္စာစောင့်သိသည်။ || ဗြဴမဒ္ဂူကဵုတၠသ္ၚိ = လင်ယောကျ်ား­ သစ္စာရှိသောမိန်းမ။ || ဍိက်မဒ္ဂူကဵုတၠ =သခင်အား သစ္စာစောင့်သိသောကျွန်။ || “တၠပညာတမၠာတေံ ဆီက္ၜံၚ်ၜိုန်ကဵုဗြဴသုၚ်ကီု ဒဵုကဵုလမျီုၜိုန်ဇိုန်ကဵုဍေံကီုလေဝ် ဗြဴမဒ္ဂူကဵုဇကု ဟွံကလိဂွံ။” (ဇ—၁၉၃။ အစွောံ။) = “ရှေးပညာရှိတို့သည် မယားအား မိမိပုဆစ်ဒူးသွေးကို သောက်စေကုန်၍ ဇီဝိတဒါနတိုင်အောင် ပေးကုန်သော်လည်း မိမိအား သစ္စာရှိသောမိန်းမကို မရကုန်။” || “အဲဍိက်ဗြဴဒ္ဂူကဵုတၠသ္ၚိရောၚ်အဴ။” (ဇ—၅၁၉။အစွောံ။) = “ကျွန်တော်မသည် လင်ယောကျာ်အား သစ္စာစောင့်သိပါ၏။”')
,(6509,3,4,'၃။ (တိရစ္ဆာန်) ယဉ်ပါးသည်။ အကပ်ခံသည်။ မရိုင်း။','“ကၞုဲဂှ် ဍေံပြာပ်အာပ္ဍဲရုၚ်စိၚ်တုဲ ပ္ဍဲစးစိၚ်မွဲမဒ္ဂူတဴဂှ် ဍေံဂ္ဇံဒၟံၚ်တုဲ ဍေံအာစုတ်သ္ၚိဍာ်ပဿဴ ပ္ဍဲစးစိၚ်ဂှ်ရ။” (ဇ—၂၇၈။ အစွောံ။) = “ထိုမျောက်သည် ဆင်တင်းကုပ်သို့သွား၍ တစ်ခုသောယဉ်ပါးသောဆင်၏ ကျောက်ကုန်းထက်­ ထိုင်နေပြီးလျှင် ဆင်ကျောက်ကုန်း­ ကျင်ကြီးကျင်ငယ်ကိုစွန့်၏။”')
,(6510,3,4,'ဖြောင့်မတ်မှန်ကန်သည်။ တရားစောင့်သည်။','‘ညးမဒ္ဂူစၟတ်’ = ‘ဖြောင့်မှန်သောသူ။ တရားစောင့်သောသူ။’ || “အဲမပ္တေဟ်ညးမဒဂူစၟတ်တုဲ အဲမဒးဟုဲဟာဲမဒးဒက်မိတ်—။” (ဇ—၅၁၈။ အစွောံ။) = “သူတရားစောင့်ဖြောင့်မှန်၏ဟု ငါယုံမိသဖြင့် ပေါင်းဖက်မိတ်ဖွဲ့မိ၏။” || “တိတ်နူပါၚ်ကီု၊ သီုမဒ္ဂူစၟတ်။” (လိက်ပယးအနိစ္စ) = “ဖြောင့်မှန်စွာ နှုတ်မှထွက်ဆို၏။” || ‘လဂူစၟတ်’ နှင့်အတူတူ။')
,(6511,3,5,'ဖြောင့်မတ်စွာ။ တည့်မတ်စွာ။ ရှေးရှုလျက်။ ရှေ့တည့်တည့်။','“(တၟာတ်မွဲဂှ်ဍေံစဂၠိုၚ်အာတုဲ) ဇကုဍေံသ္ဇိုၚ်တုဲ ဍေံပဝ်တိုန်ဓဝ်ဂှ်ဟွံမာန်တုဲ ပဝ်အာဒ္ဂူဒ္ဂူတုဲ ဒးစုတ်ဇာဂှ်ရ။” (ဇ—၅ဝ၉။ အစွောံ။) = “ထိုလင်းတသည် များလွန်းစွာစား၍ ကိုယ်လေးလံသည်ဖြစ်၍ အပေါ်သို့မပျံတက်နိုင်ဘဲ ရှေ့တည့်တည့်ပျံသွားသည်ရှိသော် ကွန်­မိ၏။”')
,(6512,3,4,'ဖြောင့်မတ်သည်။ ဖြောင့်မှန်သည်။','“ပတၠသမ္တီ တဴပ္ဍဲဋ္ဌာန်ပ္တေဟ်ညး လ္ပသ္ၚဳမုက်ညိ။ ဂွံဗော်သွး ညာတ်သဳဖဵုတုဲ စိုတ်ကဵုဒ္ဂူဓဝ်ဗိုန်ညိ။” (ဇ—၇၈။ အစွောံ။) = “ဆင်ခြင်တုံတရားရှိသော၊ ယုံကြည်အပ်သောသူမည်သည် မျက်နှာမလိုက်ပါလေနှင့်။ အခြံအရံကို ရ၍လည်းကောင်း၊တံစိုးလာဘ်ကို မြင်၍လည်းကောင်း စိတ်ကိုဖြောင့်မှန်ခိုင်မြဲစွာ ထားပါလေ။”')
,(6513,3,4,'ပဲ့ကိုင်ထိန်းကျောင်းပေးသည်။ ကူညီတည့်မတ်ပေးသည်။ စောင်မသည်။','“အိုဿီုညးတ္ၜေဟ်လက်တြဴစွံ သီုဖအိုတ်ဝွံဂှ် ဟိုတ်နူဒေဝတဴမုက် မဒှ်ဗောဓိသတ်ဂှ် ဒဂူသဏေဝ်ဏာတုဲ သၟိၚ်ကဵုပြောဟိတ် မဂွံမိၚ်မဂွံတီရောၚ်။” (ဇ—၅၂ဝ။ အစွောံ။) = “ဤသို့ ခြောက်ပါးသောဋ္ဌာနတို့­ ကျိန်ဆိုဆဲရေးခြင်းသည် ဘုရားလောင်းဖြစ်သော တည်ပင်စောင့်နတ်ကထိန်းကျောင်းတည့်မတ်ပေးခြင်းကြောင့်သာ မင်းနှင့်ပုရောဟိတ်တို့သည် ကြားရသိရခြင်းဖြစ်၏။” || “ဂွံဇိုန်ပိုန်ကဵုဒေဝတဴတံဂှ်တုဲ ဒေဝတဴတၠဣဓိတံဂှ် ဂွံမၚ်မွဲဒဂူသၞေဝ်တုဲ ပိုန်ဟာန်ဂွံဇၞော်မောဝ်အာရ။” (ဇ—၅၂၁။ အစွောံ။) = “နတ်တို့ကိုအမျှပေးဝေသည်ရှိသော် တန်ခိုးကြီးသောနတ်တို့ကစောင့်ရှောက်စောင်မ၍ စီးပွားဥစ္စာ ကြီးပွားတိုးတက်ရာ၏။” || “ယွံဒေဝတဴ ဒဒှ်ပၟၚ်က္ဍိုၚ်ဗ္တာၚ်၊ လေပ်အဲမှာရာအာဂှ် ဒဂူသၞေဝ်အဲညိ။ ကဵုအဲဂွံဇၞးမပြဲညိ” သၟိၚ်ဂး။ (ဇ—ဝိဓုရ။ အစွောံ။) = “အိုထီးဖြူစောင့်နတ်၊ ငါချွတ်ချော်မှားယွင်းသည်ရှိသော် ငါ့အားစောင့်မပါလော့။ ငါ့အား မြတ်သောအောင်ခြင်းကို ပေးပါလော့။” || “ဓဝ်သစ္စဂှ် မဒးဒ္ဂူသနေဝ်ဒေံမရာတ်ညးမသုန်ရ။” (အာန်ဇုနာန်) = “ထိုသစ္စာတရားက အရှင်မင်းမြတ်၏ ညီတော်ငါးယောက်တို့ကို စောင်မရလိမ့်မည်။” || ‘လ္ဂူသၞေဝ်’ (ကြိ) နှင့်အတူတူ။')
,(6514,3,4,'၁။ ဖြောင့်တန်းသည်။ ဖြောင့်မတ်သည်။ ဖြောင့်မှန်သည်။','“တြဴကၠံယောဇနာဂှ်တြဴဒ္ဂူသတပ်ဒၟံၚ်ရ။” (ဇ—၉၆။ အစွောံ။) = “ထိုယူဇနာတစ်ရာခရီးသည် ခရီးအဖြောင့်ဖြစ်၏။” || “ဂၠဴဥဿဘဇၞော်ဂတဂှ် ဍေံအာဒ္ဂူသတပ်မ္ဂး ဂၠဴလက်ကရဴဂမၠိုၚ်တံဂှ် ဗက်အာဒ္ဂူသတပ်အိုတ်ရ။” (ဇ—၃၃၄။ အစွောံ။) = “ရှေ့သွားနွားလားဥဿဘသည် ဖြောင့်တန်းစွာသွားလျှင် နောက်လိုက်နွားများလည်း ဖြောင့်တန်းစွာလိုက်ကြကုန်၏။”')
,(6514,3,4,'၂။ (အကျင့်၊ စရိုက်စသည် ပျက်စီးချွတ်ယွင်းနေရာမှ) ပကတိပြန်ကောင်းသွားသည်။','“(စိၚ်ဂှ် မိၚ်ဂလာန်ကမၠတ်တံတုဲ စိုတ်ဒြိုဟ်သ္ကာတ်အာ။မိၚ်ဂလာန်ဓဝ်သဳလပၠန်တုဲ) စိၚ်ဂှ် ဒ္ဂူသတပ်ခိုဟ်အာရ။” (ဇ—၂၆။ အစွောံ။) = “ထိုဆင်သည်ခိုးသူတို့၏စကားကိုကြား၍ ကြမ်းကြုတ်သွား၏။ သီလတရားစကားကို ကြားပြန်လတ်သော် မူလပကတိအတိုင်း ယဉ်ကျေးပြန်ကောင်းသွား၏။”')
,(6514,3,4,'၃။ (တိရစ္ဆာန်) ယဉ်ပါးသည်။ ရိုင်းစိုင်းထိတ်လန့်ခြင်းမရှိ။','(ဣသိ) ညာတ်စိၚ်ဂှ် သီုအပေါတ်သၟိၚ်ရောၚ်။ “စိၚ်ဝွံ ဒ္ဂူသတပ်ဒၟံၚ်ရ။ မူဟိုတ်ဒှ်ဟွံတီရ” ဣသိချပ်။ (ဇ—၂၅၉။ အစွောံ။) = (ရသေ့သည် မင်းတန်ဆာနှင့်တကွ ဆင်ကိုမြင်၍ “ဤဆင်သည် ယဉ်ပါး၏။ ဘာကြောင့်များလည်းမသိ” ဟုတွေး၏။)')
,(6515,3,1,'ရောင်ရမ်းနာ။','‘ယဲဂုဟ်ဒဂေါ်။’ (ဓမ္မဒဳပနဳ။ မာံရွှေငိုး။) = ‘ရောင်ရမ်းနာ။’ || “ဒဂေါ်ယဲကအ်။” (လိက်ပယးအနိစ္စ) = “လည်ပင်းရောင်ရမ်းနာ။”')
,(6516,3,4,'ထိုင်းသည်။ ထုံထိုင်းသည်။',NULL)
,(6517,3,1,'၁။ ရက်မ။',NULL)
,(6517,3,1,'၂။ တကောင်း။ (လည်တံရှည်အိုးတစ်မျိုး)','ဒဂံၚ်ဍာ် = ရေတကောင်း။ || “(တြုံဂှ် သွက်ထေရ်ၜါဂှ်) ကၠုၚ်လးသၞာကီု ပြိုက်ဍာ်ဒဂံၚ်ကီု ဒ္ဂေတ်ဒၟံၚ်ရ။” (ဇ—၃၅၉။ အစွောံ။) = “ထိုယောကျာ်းသည် ထိုမထေရ်နှစ်ပါးအတွက် နေရာထိုင်ခင်းကို လာ၍ခင်းပေးခြင်း ရေတကောင်း­ ရေဖြည့်ပေးခြင်းတို့ကို ပြုလျက်နေ၏။” || “ကၠိက်ဂမၠိုၚ် ဂၠာဲဍာ်ဒဂေါၚ် (သွက်ဂွံစဝ်ဍာ်ပသေက်ကဵုသၟိၚ်ကၠိက်—။)” (ဇ—၄၉၂။ အစွောံ။) = “ဝက်တို့သည် ဝက်မင်းအားအဘိသိက်ရေသွန်းလောင်းရန် ရေတကောင်းကို ရှာကြကုန်၏။” ‘ထဂံၚ်’ ဟုလည်းတွေ့ရသည်။')
,(6518,3,4,'(သစ်ပင်) အရွက်မဲ့သည်။ ကျိုးတိုးကျဲတဲဖြစ်သည်။ စနောင့်စနင်းဖြစ်သည်။','“တၞံဆုဏံဒဂါတ်အိုတ်ရ။” = “ဤသစ်ပင်သည် အရွက်ကျိုးတိုးကျဲတဲဖြစ်ကုန်ပြီ။” || ခရံၚ်ဒဂါတ်= အရွက်မဲ့အကိုင်းကျိုးဖြစ်သည်၊ စနောင့်စနင်းဖြစ်သည်။ || “ကၞာၚ်သၠဒဂါတ်၊ ဟွံညာတ်တၞး။” (လိက်လက္ခဏပိ) = “အခက်အရွက်စနောင့်စနင်းဖြင့် အရွက်များမမြင်ရ။” || “ညာတ်သၠဇြဲအဴ၊ဒဂါတ်တဴရ။ သၟိၚ်သၟာန်တိုန်ပြဟ်၊ ညးဂှ်ပထောၚ်ရော။ လၟေန်ဝွံရောၚ်၊ ပထောၚ်ရအဴ။” (လိက်မ္ၚဵုပိစှ်ောဒစာံ။ မာံထဝ်စိုပ်။) = “အရွက်ကျိုးတိုးကျဲတဲဖြစ်နေသော ညောင်ပင်ကိုမြင်၍ မင်းသည် မြန်စွာမေး၏၊ မည်သူသည် ညောင်ရွက်တို့ကို ပေါက်အောင်ဖောက်ထားပါသနည်း။ ဤသူဆွံ့သည်သာ ဖောက်ထားပါ၏။”')
,(6519,3,1,'ကြမ်းပိုး။','“စၟဟွံကဵုကိတ်၊ ဒ္ဂိတ်ဟွံကဵုစတ်။” (လိက်မိဍောၚ်ကှ်ေထဝ်။) =“ပိုးမကိုက်စေ ကြမ်းပိုးမထိုးစေဘဲ။”')
,(6520,3,4,'ဆစ်သည်။ ဈေးဆစ်သည်။','“ရာန်ဖျာမ္ဂး ဒဂုတ်တုဲရာန်ညိ။”= “ဈေးဝယ်လျှင် ဈေးဆစ်ပြီးမှဝယ်ပါ။”')
,(6521,3,1,'အကျင့်။','ဒ္ဂေတ်ပဋိပတ်မဆာဲ = ကောင်းမြတ်သောအကျင့်စရိုက်။ || ဒ္ဂေတ်မုတ် = မှားယွင်းသောအကျင့်။')
,(6521,3,4,'ကျင့်သည်။ ကျင့်သုံးသည်။ လိုက်နာသည်။','“သဘဴတြုံတၠပညာမ္ဂးဂှ် ဒ္ဂေတ်ဍာန်သဗာန်တၠပညာဂှ် မဒ္ဂေတ်ဗက်အာရ။” (ဇ—၅၃၄။ အစွောံ။) =“ပညာရှိသောယောကျာ်းမည်သည် ပညာရှိတို့၏အကျင့်လမ်းစဉ်ကို လိုက်နာကျင့်သုံး၏။”')
,(6522,3,4,'ယှဉ်သည်။ အတူတကွဖြစ်ပေါ်သည်။ ယှဉ်တွဲဖြစ်ပေါ်သည်။','“ယွံတဳလပိုန်၊ ဓဝ်သဳလမသုန်မဒ္ဂေတ်တဴ မွဲဟာန်ကေုာံသရဏပိဂှ် အဲဍိက်အာတ်ရအဴ။” (နရသာသန။ သဳလဝန္တထေရ်။) = “အရှင်ဘုရား၊ သရဏဂုံသုံးပါးနှင့်ယှဉ်သော ငါးပါးသီလကို တပည့်တော်တောင်းခံပါ၏။” || “ဂစိုတ်မဒ္ဂေတ်တဴကေုာံပရိုက်ဂှ် တြုံဂှ်မဒးအာစိုပ်ရ။” (ဇ—၃၉၇။ အစွောံ။) = “ ထိုယောကျာ်းသည် ဘေးဥပဒ်နှင့်ယှဉ်သောသေခြင်းသို့ ရောက်ရ၏။” (သေခြင်းဆိုးဖြင့်သေခြင်းကို ဆိုလိုသည်။)')
,(6523,3,1,'စိတ်နေသဘောထား။ စိတ်ထား။','‘နဒ္ဂေတ်စိုတ်မသကာတ် ဒဇန်သဟာသဳ။’ (ဇ—၁၄၉။ အစွောံ။) = ‘ရက်စက်ကြမ်းကြုတ်သောစိတ်ထား။’')
,(6524,3,1,'မှန်ကန်သောအကျင့်။ မွန်မြတ်သောအကျင့်။','“ဒ္ဂေတ်မုတ်သွံ၊ ဟွံကေတ်သ္အးကၠာ။ဒ္ဂေတ်ဒွးမာ၊ လအာဒးရး။” (လိက်သောဝိန်ဇဲယ။ မာံရောဂေါ။) = “မှားယွင်းသောအကျင့်ကိုအလျှင်းမယူဘဲ မှန်ကန်မွန်မြတ်သောအကျင့်ကိုသာ ယူ၏။”')
,(6525,3,1,'အပြုအမူ။ အကျင့်။','“သမ္ဘာဥပ္ပးဂှ် ကျာ်တြဲတီကေတ် ဒ္ဂေတ်ပွအဲတုဲရဂးတုဲ ဖေက်ဂွပါပ်တုဲ ပွမုတ်မယုတ်မာတံဂှ် ဟွံပသက်သက်ပၠန်ရ။” (ဇ—၆၅။ အစွောံ။) = “သီတင်းသည်၏မယားသည်လည်း မြတ်စွာဘုရားသည် ငါ၏အကျၚ့့်အပြုအမူကို သိလေပြီဟုဆိုကာအရှက်အကြောက်ဖြစ်ပေါ်၍ မှားယွင်းယုတ်မာသောအမှုကို လုံးဝမပြုတော့။” || “ဒဒှ်ဒ္ဂေတ်ပြဝအဲဟွံခိုဟ်ဂှ် အ္စာတီကေတ် (တုဲ) ရ” ဗြဴဂှ်ဂး။ (ဇ—၆၅။ အစွောံ။) = “ငါ၏အကျင့်မကောင်းကြောင်းကို ဆရာသိသွားလေပြီ။” || “ညံၚ်ဒ္ဂေတ်ပွသာ်ဝွံဂှ် အဲဟွံပကြဴရ။” (ဇ—၃၇၄။ အစွောံ။) =“ဤသို့သောအပြုအကျင့်မျိုးကို နောင်ငါမပြုတော့ပါ။”')
,(6526,3,4,'လိုက်နာသည်။ ကျင့်သုံးသည်။','ဒ္ဂေတ်ဗက်ဂလာန်ကျာ်တြဲ = မြတ်စွာဘုရား၏အဆုံးအမကို လိုက်နာကျင့်သုံးသည်။ || ဒ္ဂေတ်ဗက်သၞောဝ် = စည်းမျဉ်းစည်းကမ်းကို လိုက်နာသည်။ || “အဂတိပန် လ္ပဒ္ဂေတ်ဗက်ညိ။” (ဇ—၄ဝ၇။ အစွောံ။) = “အဂတိလေးပါးသို့ မလိုက်ပါနှင့်။” || “ဒ္ဂေတ်ဗက်ဂလာန်တၠပညာညိ။” = “ပညာရှိစကားကို လိုက်နာပါ။”')
,(6527,3,1,'မှားယွင်းသောအကျင့်။ ဖောက်ပြန်သောအကျင့်။','“ဒ္ဂေတ်မုတ်သွံ၊ ဟွံကေတ်သ္အးကၠာ။ ဒ္ဂေတ်ဒွးမာ၊ လအာဒးရး။” (လိက်သောဝိန်ဇဲယ။ မာံရောဂေါ။) = “မှားယွင်းဖောက်ပြန်သောအကျင့်ကို လုံးဝမယူဘဲ မှန်ကန်လျောက်ပတ်သောအကျင့်ကိုသာ ယူ၏။”')
,(6528,3,1,'၁။ ရွာသူတို့အကျင့်။ မေထုန်အကျင့်။ (ပါဠိ—ဂါမဓမ္မ)','“ယွံကောန်ဗြဴ — ပ္ဍဲဓဝ်မေထုန်ဒ္ဂေတ်လိုက်ဂှ် ဗှ်ေဟွံတီမွဲလှ်ေဏီ။” (ဇ—၂၁၇။ အစွောံ။) = “ချစ်သမီး၊ သင်သည် ရွာသူတို့အကျင့်ဖြစ်သော မေထုန်အကျင့်ကို မသိဖူးသေး။”')
,(6528,3,1,'၂။ လောကကျင့်စဉ်။—ကျင့်ထုံး။','“ယွံသောမဒတ္တ၊ မၞးဒှ်ကောန်ၚာ်တုဲ ဒ္ဂေတ်လိုက် မၞးဟွံတီတဴရောၚ်။” (ဇ—ဘူရိဒတ်။ အစွောံ။) = “ချစ်သားသောမဒတ္တ၊ သင်သည် ကလေးဖြစ်သဖြင့် လောကကျင့်ထုံးကို မသိခြင်းဖြစ်၏။”')
,(6529,3,1,'ကျင့်စဉ်။ ကျင့်ထုံး။ အကျင့်။','ဒ္ဂေတ်လ္ၚတ်ဗောဓိသတ် = ဘုရားလောင်း၏ကျင့်စဉ်။ || “သုဗ္ဗတာ၊ ၚ်ညးမၞုံဒ္ဂေတ်လ္ၚတ်မဆာဲဒးရးဂမၠိုၚ်။” (သြဝါဒဒဳပနဳ) = “ကောင်းသောအကျင့်ရှိသူများ။”')
,(6529,3,4,'ကျင့်ကြံသည်။ ကျင့်သုံးသည်။','“ဓဝ်သဳလ တၠဝါသနာသာတုဇန်တံ ဂွံဒ္ဂေတ်လ္ၚတ်မၚ်မွဲလဝ် ဗွဲမဒးရး—။” (ဓမ္မဒေသနာ။ မာံရွှေငိုး။) = “ဝါသနာရှင်သူတော်ကောင်းတို့ ကောင်းစွာကျင့်သုံးစောင့်စည်းထားသော သီလတရား။”')
,(6530,3,1,'အကျင့်စာရိတ္တ။ အကျင့်စရိုက်။','“ဒ္ဂေတ်လၟေတ်ဍေံဟွံခိုဟ်။” = “သူ့အကျင့်စာရိတ္တက မကောင်း။”')
,(6531,3,1,'ၚုံးငှက်။','“ဗောဓိသတ်ပိုဲ ဒှ်ဂစေံဒဂိုတ် ဒၟံၚ်ပ္ဍဲဂြိုပ်။” (ဇ—၃၉၄။ အစွောံ။) = “ဘုရားလောင်းသည် ငုံးမျိုး­ဖြစ်၍ တော­—နေ၏။” (ညောင်ကန်) || ‘ဒဂိတ်’ ဟုလည်းကောင်း ‘အဃိုတ်’ ဟုလည်းကောင်း အချို့သူတို့ ရေးသားပြောဆိုကြသည်။')
,(6532,3,1,'တောင်ခါးပန်း။',NULL)
,(6533,3,1,'ဝါဆိုလ။','‘အသာတ်’ ဟုလည်းခေါ်သည်။')
,(6533,3,4,'၁။ (သီလစသည်) ခံယူသည်။ ဆောက်တည်သည်။','“ဒကာတံဒဂိုန်ကေတ်သဳဒစာံတုဲ မၚ်သဳဥပုဟ်အိုတ်ရ။” = “ဒကာများသည် ရှစ်ပါးသီလကိုခံယူ၍ ဥပုဟ်စောင့်ကြသည်။”')
,(6533,3,4,'၂။ (ဘုရား၊ ရဟန်း) နေထိုင်သည်။ သီတင်းသုံးသည်။','“တရဴဝှ်တုန်၊ ပ္ဍုန်ဝေလုဝိုန်။ ကျာ်တြဲဒဂိုန်၊ လမိုန်ဟွံခၠန်။” (လိက်ရတနပဇ္ဇောတ) = “ဝါတော် (၆) ဝါတွင် မြတ်စွာဘုရားသည် ဝေဠုဝန်ကျောင်းတော်­ အမြဲမပြတ် သီတင်းသုံးတော်မူ၏။” || ဒ္ဂိုန်ဒ္ဂေတ်ညးသပ္ပရိုဟ် = သူတော်ကောင်းတို့၏ကျင့်စဉ်။')
,(6534,3,1,'အကျင့်။ ကျင့်စဉ်။',NULL)
,(6534,3,4,'ကျင့်သည်။ ကျင့်ကြံအားထုတ်သည်။','“သ္ဂောံဒ္ဂိုန်ဒ္ဂေတ်မၚ်မွဲကေတ်မာန်ဂှ်မ္ၚိုလ် (၃၈) ကျာ်တြဲတွံပျးလဝ်ကီုရ။” (ပြကိုဟ်မ္ၚိုလ်ပိစှ်ောဒစာံ) = “ကျင့်ကြံအားထုတ်စောင့်စည်းနိုင်ရန် မင်္ဂလာတရား (၃၈) ဖြာကို မြတ်စွာဘုရား ဟောကြားညွန်ပြထားတော်မူ၏။”')
,(6535,3,4,'ဓုတင်ဆောက်တည်သည်။',NULL)
,(6536,3,4,'ရုက္ခမူဓုတင်ဆောက်တည်သည်။ သစ်ပင်ရင်း­ သီတင်းသုံးသည်။ (ပါဠိ—ရုက္ခမူလိက)',NULL)
,(6537,3,4,'ဝါဆိုသည်။ ဝါကပ်သည်။','“ပ္ဍဲဆိုက်ပယာံမဒဂိုန်ဝှ် ပ္ဍဲကွာန်ဗ္ငမွဲဂှ် ဂွံသ္ၚာလှဲလး မိၚ်ပရိုၚ်တုဲ ပြာပ်အာဒဂိုန်ဝှ် ပ္ဍဲကွာန်ရးဗ္ၚဂှ်ရ။” (ဇ—၃၁၂။ အစွောံ။) = “ဝါဆိုခါနီးကာလ­ သင်္ကန်းပစ္စည်း ရလွယ်သည်၏အဖြစ်ကိုကြား၍ တခုသောရွာကျောင်းသို့သွား၍ — ဝါဆိုကုန်၍—။” (ညောင်ကန်)')
,(6538,3,4,'သီလခံယူသည်။','“(ထေရ်သာရိပိုတ်တုန်) ဆမညာတ်ညးတုဲ ကဵုဒဂိုန်သဳမသုန်အိုတ်ရ။” (ဇ—၃၅၆။ အစွောံ။) = “အရှင်သာရိပုတ္တရာမထေရ်သည် မြင်တိုင်းမြင်တိုင်းကုန်သောသူတို့အား ငါးပါးသီလကို ခံယူစေ၏။”')
,(6539,3,4,'လေထဲတွင်လွင့်မျောသည်။','‘ဂဂုဲ’ ရှု။')
,(6540,3,1,'သစ်ပင်အၚုတ်။ ၚုတ်တို။','ဒဂဵုဆု = သစ်ၚုတ်။ || “တၞံဝိဂှ် ဆဒဂဵုသၟးမသှ်ေရ။” (ဇ—၄၂၉။ အစွောံ။) = “ထိုသဖန်းပင်သည် အၚုတ်မျှသာ ကျန်၏။” || ‘ဂဂဵု’ ဟုလည်းရေးသည်။')
,(6541,3,5,'တုံးလုံးပက်လက်။','“ကအ်ကဝ်ဖ္ဍိုပ်၊ ချိုတ်မိုပ်ဒဂြ။” (လိက်ကောန်သၟိၚ်ပိ။ မာံခစုန်အံက်။) = “လည်ကျိုးခေါက်၍ တုံးလုံးပက်လက် မှောက်လျက်သေ၏။”')
,(6542,3,4,'ခေါင်းညိတ်သည်။','“(ဒကုဲဂှ်) လတ်ပ္တိတ်က္ဍိုပ်တုဲ ဒၚိက်တုဲမာဒၟံၚ်ရ။” (ဇ—၁၂၁။အစွောံ။) = “ထိုပုတ်သင်သည် ခေါင်းကိုထုတ်ပြူ၍ ခေါင်းညိတ်၍ဝပ်နေ၏။”')
,(6543,3,1,'မှန်။','ရံၚ်ဒ္ၚောဝ် = မှန်ကြည့်သည်။')
,(6544,3,1,'စံတိုင်။ စံနှုန်း။ (?)','“ဂုန်မိမပၠန်၊ ပြဲသန်မဂၠိုၚ်။ အဲဂိုၚ်ပ္တေဝ်လဝ်၊ ပဒၚောဝ်တိုၚ်။” (လိက်တရဳသံသာ) = “မြတ်လှများလှစွာသော မိဘတို့၏ဂုဏ်ကျေးဇူးကို အကျွန်ုပ်သည် စံနှုန်းစံတိုင်ပြု၍ တည်ထားပါအံ့။” || “နဓမ္မဒေသနာ မပဒၚောဝ်တိုၚ်ထဝ် လဝ်ဂတမုက်ကီုရ—။” (သၠပတ်သတိပထာန်) = “ဓမ္မဒေသနာတော်ကို ရွှေစံတိုၚ်စံနှုန်းပြုကာ မျက်နှာရှေ့­ထားသကဲ့သို့။”')
,(6545,3,1,'မျက်မှန်။',NULL)
,(6546,3,4,'၁။ ဆန့်ကျင်ဖက်အရပ်မှလာသည်။ ခရီးရင်ဆိုင်အရပ်မှလာသည်။ မျက်နှာချင်းဆိုင်အရပ်မှလာသည်။','“ဗောဓိသတ်သီုကွဳမသုန်ကၠံ ကာလမအာစိုပ်ကန္တာကလော်ဂှ် ဍေံပကလော်မဒစးကၠုၚ် ထ္ၜးဇကုကဵုဗောဓိသတ်ရ။” (ဇ—၁။ အစွောံ။) = “ဘုရားလောင်းသည် လှည်းငါးရာတို့ ဖြင့် ကန္တာရကိုသွား၏။ ဘီလူးတို့သည် ခရီးရင်ဆိုင်မှလာဟန်ပြု၍ ဘုရားလောင်းအား ကိုယ်ထင်ပြ၏။” || “(ခမဳဂှ်) ရံၚ်ညးၜါဂှ်ဟွံစိုပ်တုဲ ကေတ်မိန်ရှောတဴၜံၚ်တုဲ ဒစးကၠုၚ်တုဲ ဂွံညးၜါဂှ်ရ။” (ဇ—၃၁၂။ အစွောံ။) = “(ထိုရဟန်းသည်) ထိုသူနှစ်ဦးတို့လာသည်ကိုမမြင်၍ မီးရှူးကိုင်လျက်ထိုသူတို့ရှိရာဆီ ခရီးရင်ဆိုင်မှလာ၍ ထိုသူနှစ်ဦးကိုတွေ့၏။”')
,(6546,3,4,'၂။ ဆန့်ကျင်သည်။','“ခမဳမွဲမဒစးဂလာန်ကျာ်။” (ဇ—၁၈၄။ အစွောံ။) = “ဘုရား၏စကားတော်ကို ဆန့်ကျင်သောရဟန်း။” || “ပါၚ်သၟိၚ်ဓဝ်ကောတၠဂုန်ရောၚ် အဲဂံၚ်ဒစးဟာ။” (အာန်ဇုနာန်) = “ကျေးဇူးရှင်နောင်တော်တရားမင်း၏စကားတော်ကို အကျွန်ုပ်ဆန့်ကျင်ဖီဆန်ဝံ့ပါမည်လော။”')
,(6546,3,4,'၃။ (တစ်စုံတစ်ဦးရှိရာ) လိုက်သွား၍ ခေါ်ဆောင်လာသည်။ လိုက်ခေါ်သည်။','“ဒေံအဲအာဒၟံၚ်အလဵုရော။ ယဝ်မၞးတီဒၞာဲဍေံအာမ္ဂး အာဒစးဍေံမွဲတဲညိ။” = “ငါ့ညီဘယ်သွားနေသလဲ။ သူသွားသည့်နေရာကို သင်သိလျှင်တဆိတ်လောက် လိုက်ခေါ်ပေးစမ်းပါ။”')
,(6546,3,4,'၄။ ဆန်သည်။ ဆန်တက်သည်။','“ဍာ်ကြုၚ်ဂမၠိုၚ်ဂှ်သကဵုဇွောဝ်ဒစးတိုန်ကီုရ အဲသၟိၚ်နာ်စမ္ပေယျဂှ် ဟီုတုဲ ဟွံဂွံဂတးကၠေံဟေၚ်ရ။” (ဇ—၅ဝ၆။ အစွောံ။) = “မြစ်များသည်ဆန်တက်၍ စီးသည်လည်းဖြစ်ပါစေဦး၊ စမ္ပေယျနဂါးမင်းဖြစ်သောငါသည် ပြောပြီးသောစကားကို ပြောင်းပြန်ပြုရိုးမရှိ။” || “(သၟိၚ်) ပြေၚ်ဗဵုဍိုက်ဂၠုၚ်ဖံၚ်တုဲ ဒစးတိုန်အာကၞောတ်ကြုၚ်တေံ—။” (ဇ—၁၅၆။ အစွောံ။) = “မင်းသည် စစ်သည်တို့ကိုစုရုံး၍ လှေဖောင်စီးကာ ချောင်းဖျားဆီသို့ ဆန်တက်သွား၏။”')
,(6546,3,4,'၅။ ဆီးကြိုသည်။','“ဒစးဒုၚ်တၠုၚ်အ္စာ။”= “ဆရာ့ကို ခရီးဦးကြိုဆိုသည် (ဆီးကြိုသည်။)” || “(သၟိၚ်ကောသလရး မဇက်ကၠုၚ်ပၞာန်ဂှ်) ပိုဲဍိက်ဇက်ဒစးအာတုဲ ဗတိုက်ဗပေက်ကၠေံရ” ညးဂၟံၚ်တံဂှ်ဂး။ (ဇ—၅၁။ အစွောံ။) = “စစ်ချီ၍လာသော ကောသလပြည်မင်းကို အကျွန်ုပ်တို့သည် ချီတက်ဆီးကြို၍ တိုက်ခိုက်ထွက်ပြေးစေကုန်အံ့” ဟုသူရဲတို့ဆိုကုန်၏။')
,(6547,3,4,'နားကြားပြင်းကတ်သည်။ နားကလောသည်။','“ဂလာန်မွဲ ပူဂဵုသတြုမဟီုဂှ်ဒစးကတောဝ်ရ။” (ဇ—၁၉၇။ အစွောံ။) = “ရန်သူဖြစ်သောပုဂ္ဂိုလ်၏ ပြောစကားကို (မကြားချင်) နားကြားပြင်းကတ်၏။”')
,(6548,3,1,'လေဆန်။','“ရပ်ခနိက်တိတုဲ ပက်ဏာဗွဲဒစးကျာဂှ်တုဲ ရဴခနှိက်တိဂှ် မကလေၚ်ကၠုၚ်ဒးမတ်ဇကုကီု။” (ဇ—၃၆၇။ အစွောံ။) = “မြေမှုန့်ကိုကိုင်၍ လေညာသို့ ပက်လိုက်သည်ရှိသော်ထိုမြေမှုန့်သည် ပြန်လာ၍ မိမိမျက်စိကို ထိဘိသကဲ့သို့။” || “နထးထဝ်အနဂ္ဃၚုဟ်ဂှ် ကဵုစုတ်လဝ်ပုၚ် ညံၚ်ခၟောမ်မၠဵုတုဲ သီုကဵုအမာဲမဒးရး မောဝ်ပ္ဍးတမှာဲဒၟံၚ် ဒစးကျာဗလောဲကျာဂှ်ဒှ်တုဲ—။” (ဇ—၂၆ဝ။ အစွောံ။) = “အဘိုးအနဂ္ဃထိုက်သောရွှေခွက်­ စံပယ်ၚုံနှင့်တူသောထမင်းကို ထည့်ထားစေ၍ ကောင်းသောဟင်းလျာအမည်များနှင့်တကွ လေဆန်လေစုန်အရပ်တို့­ အလွန်မွှေးနေ၏။”')
,(6549,3,1,'ရေဆန်။',NULL)
,(6550,3,4,'ဆီးကြိုသည်။',NULL)
,(6551,3,4,'ခရီးဦးကြိုသည်။','‘ဒစးဒုၚ်တၠုၚ်’ နှင့် အဓိပ္ပါယ်အတူတူ။ (ပါဠိ—ပစ္စုဂ္ဂမန)')
,(6552,3,1,'နေအပူရှိန်။ ထိုးသောနေရောင်။','“(ဗမၞးမုဟ်ပိုတ်ဂှ်) တိုန်သဳကၠဳ (သၟိၚ်) ဂှ် ဒးဒၟံၚ်ဒစးပသာန်တ္ၚဲဂှ်တုဲ ကြေက်မဖျပ်ပ္တုပ်လဝ်မုဟ်ဂှ် တလှ်ဒတုံစှ်ေအာရ။” (ဇ—၁၂၆။ အစွောံ။) =“နှာခေါင်းပြတ်သောပုဏ္ဏားသည် မင်းအားခစားစဉ် ထိုးသောနေအပူရှိန်ကြောင့် ချိပ်ဖြင့်လုပ်ထားသောနှာခေါင်းတုသည် ကျွတ်၍ပြုတ်ကျသွား၏။”')
,(6553,3,4,'(စကားကို) ဆန့်ကျင်သည်။','“ယွံမၞးတံ၊ ဒေဝဒတ်ဝွံ ကရဴကၠေံအ္စာရောၚ်။ ဒစးကၠေံပါၚ်ကျာ်တြဲရောၚ်” ခမဳတံဂး။ (ဇ—၂၃၁။ အစွောံ။) = “ငါ့သျှင်တို့ ဒေဝဒတ်သည် ဆရာကို ကျောခိုင်းစွန့်ပယ်၏။ မြတ်စွာဘုရားစကားကို ဆန့်ကျင်၏။”')
,(6554,3,4,'ခရီးဦးကြိုဆိုသည်။','“ပယတ်တေံ ကာလအဲကၠုၚ်စိုပ်ဂှ်လေဝ် ဒစးဝေၚ်ဒုၚ်အဲတုဲ သၟာန်သၟုက်တဴအဲရောၚ်သွံကောန်။” (ဇ—၅၂၆။ အစွောံ။) =“ချစ်သား၊ အခါတိုင်းဆိုလျှင် ငါပြန်ရောက်သောအခါ ငါ့ကိုခရီးဦးကြိုဆို၍ ပြောဆိုမေးမြန်းပေ၏။” || “သၟိၚ်ကလေၚ်စဴဂှ် ဗဵုပၞာန်တံဂှ်ညာတ်တုဲ ဒစးဝေၚ်ဒုၚ်တၠုၚ်တုဲ လုပ်ဍုၚ်ရ။” (ဇ—၃ဝ၂။အစွောံ။) = “ဗိုလ်ပါတို့သည် မင်းပြန်လာသည်ကိုမြင်၍ ခရီးဦးကြိုဆို၍ မြို့သို့ဝင်၏။” || “ပွမဒစးဝေၚ်ဒုၚ်တၠုၚ်တရဴ။” (ပြကိုဟ်ဒ္ဂေတ်ပဋိပတ်သာမဏဳ။ မာံရွှေငိုး။)')
,(6555,3,4,'၁။ ဆုတ်ဖြဲသည်။','“ဒစာ်ထောံစက္ခူ။” = “စက္ကူကို ဆုတ်ဖြဲပစ်သည်။”')
,(6555,3,4,'၂။ နုတ်ပယ်သည်။ ဖယ်ရှားသည်။','“ကျာဲဒုန်ဓလဂှ် ဍေံကြံၚ်ခိုၚ်ဗိုန်တာန်မာန်အာတုဲ ကြာန်ကၠောံအာတုဲသ္ဇိုၚ်ညးမဒစာ်ထောံကၠေံဍေံဟွံမာန်ဟေၚ်။” (ဇ—၅ဝ၅။ အစွောံ။) = “ဆူးဝါးပင်သည် ရင့်မာခိုင်ခံ့၍ ပွားများလတ်သော် ဖယ်ရှားနုတ်ပယ်နိုင်ခဲလှ၏။”')
,(6556,3,1,'ဆူး။ ငြောင့်။','ဒးဒစုက် = ဆူးစူးသည်။ || “ပွမဗဵုကလၚ်လှ်ေဒယှ်ေတိၚ်တိုက်မဒှ်ပွမစှ်ေဒးကဵုသာသနာ ဒစုက်သာသနာဂှ်။” (ပြကိုဟ်ဒ္ဂေတ်ပဋိပတ်သာမဏဳ။ မာံရွှေငိုး။) =“သာသနာတော်၏ဆူးငြောင့်ဖြစ်သော သာသနာတော်နှင့်ဆန့်ကျင်ခြင်းဖြစ်သော အက၊ အဆို၊အတီးအမှုတ်တို့ကို ကြည့်ရှုနားဆင်ခြင်း။”')
,(6557,3,4,'တို့မီးရှို့မီးလုပ်သည်။ တိုင်တန်းသည်။',NULL)
,(6558,3,1,'ဆူးငြောင့်။ ခလုတ်ကန်သင်း။',NULL)
,(6559,3,1,'ဆူးငြောင့်။',NULL)
,(6560,3,4,'တို့မီးရှို့မီးလုပ်သည်။ ကုန်းချောသည်။ ရန်တိုက်သည်။','“ဂလာန်ဒစုက်ဒလူသာ်ဝွံ ပၠောပ်နၚ်ပ္ဍဲသ္ၚိတုဲ လ္ပဟီုညိ။” (သုဓမ္မဒေသနာ။ ဂရိုက်သာံ။) = “ဤသို့သောရန်တိုက်သောစကားကို အိမ်သို့ယူဆောင်လာပြီး မဆိုလေနှင့်။”')
,(6561,3,4,'၁။ ပြိုးပြိုးပြက်ပြက်သောအရောင်ရှိသည်။ ထွန်းလင်းတောက်ပသည်။','လျးသာ်ဒစၚ်ဗၜၚ် = ပြိုးပြိုးပြက်သောရောင်ခြည်တော်။ (မြတ်စွာဘုရား၏ ရောင်ခြည်တော်ခြောက်သွယ်အနက် တစ်ခုအပါအဝင်။) || “ယွံဗမၞး၊ ကွဳရတ်ဍေံမတၟုဲတဴ နထဝ်သက်သက် ဍေံမၞုံအရံၚ်မဒစၚ်ဗၜၚ် တယောဝ်ကွဳမဖှ်သာ်ဂှ် ကုအဲသၟိက်ဂွံရ။” (ဇ—၄၄၉။ အစွောံ။) = “ဖခင်ပုဏ္ဏား၊ ငါ့အား ရွှေဖြင့်ပြီးသော ပြိုးပြိုးပြက်သောအရောင်ရှိသော ရထားချိုင့် (ကို အလိုရှိ၏။)” (ညောင်ကန်) || “လွဳမာန်သၟိၚ်နာ်ဂှ် မတၟုဲတဴနမၞိက်ထဝ်သြန်တုဲ ဒစၚ်ဗၜၚ်တဴ ရဴလျးသာ်သၟိၚ်တ္ၚဲ ပ္ဍဲအကာသကီု ရဴလျးလလဳမစဳပျးတဴဇၟာပ်ဒိုဟ်ကီု မဒှ်ရ။” (ဇ—၅၂၄။ အစွောံ။) = “နဂါးမင်း၏ဗိမာန်သည်ပတ္တမြား၊ ရွှေ၊ ငွေဖြင့်ပြီးသည်ဖြစ်၍ ပြိုးပြိုးပြက်ထွက်သော အရောင်အဆင်းဖြင့် ကောင်းကင်ပြင်­ နေမင်း၏အလင်းရောင်ကဲ့သို့၄င်း လျှပ်စီးရောင်ကဲ့သို့၄င်း ထွန်းတောက်ပ၏။”')
,(6561,3,4,'၂။ (ရုပ်အဆင်း၊ အရောင်အသွေး၊ အသားအရေ) ကြည်လင်သန့်ရှင်းသည်။ ဖြူစင်လှပသည်။','“တၠအဲမၞုံကဵုရုပ်မဒစၚ်ဗ္ၜၚ်တဴ—။” (ဇ—၃၈၃။ အစွောံ။) = “သင်သည် ဖြူစင်လှပသောရုပ်အဆင်းရှိ၏။” || “မုက္ခဝါကောန်အဲ သ္ဇုၚ်ဒစၚ်ဗၜၚ်သန်။” (သၠပတ်ဗုဒ္ဓဃောသာ) = “ငါ့သား၏မျက်နှာသည် ကြည်စင်လှပ၏။” || “ယွံတၠ၊ ကၠာတေံဂှ် တၠအဲမၞုံအိန်ရဳမသ္ဇုၚ်ဒစၚ်ဗ္ၜၚ်တဴရောၚ်သွံ။ လၟုဟ်ဝွံဂှ် တၠအဲမၞုံအဝဲမကၠိုက်လ္ၚေၚ်ဖျိုဟ်ဂတးအာဂှ် တၠအဲယဲအာဟာ။” (ဇ—၅၂၇။ အစွောံ။) = “ငါ့ရှင်၊ သင်သည်ရှေး­ ကြည်လင်သန့်ရှင်းသော ဣန္ဒြေအဆင်းရှိ၏။ ယခုတစ်မူကား အဆင်းပျက်၍ ကြုံလှီဖျော့တော့လျက်ရှိသည်မှာ သင်ဖျားနာသွားလေသလော။” || “ဂစေံဒြၚ်ဂံက်ဝွံမွဲဂှ် မဂပ်ဂဝ်ဒစၚ်ဗၜၚ်တဴ၊ ညးဒြၚ်ဂံက်ဝွံသဂးရော။” (ဇ—၂၇၅။ အစွောံ။) = “ဖြူစင်သောအဆင်းရှိသောဤဗျိုင်းသည် အဘယ်သို့သဘောရှိသောဗျိုင်းနည်း။” (ညောင်ကန်) || “ပွမၞုံကဵုလျးသာ်ဇကုမဒစၚ်ဗၜၚ်။” (ဓမ္မဒဳပနဳ။ မာံရွှေငိုး။) = “စင်ကြယ်သန့်ရှင်းသော ကိုယ်အဆင်းအရောင်ရှိခြင်း။” || “ဍာ်မလျုၚ်မဒစၚ်ဗၜၚ်ဒၟံၚ်ကီု။” (သ္ကေံမိလိန္ဒဝတ္ထု) = “ရေသည် ကြည်လင်စင်ကြယ်နေ၏။”')
,(6561,3,4,'၃။ (အတတ်ပညာ) အပြီးတိုင်ရောက်သည်။ ကျွမ်းကျင်လိမ္မာသည်။','“ဗောဓိသတ်ဒှ်ဂကူသၟာတၟံအာစိုပ်ဒဒှ်ဗၠာဲ နွံကွတ်ဒစၚ်ဗ္ၜၚ်ဆိုက်ဗ္ဒက်သန်။” (ဇ—၁၃၇။ အစွောံ။) = “ဘုရားလောင်းသည်ကျောက်သွေးအမျိုး­ဖြစ်၍ အရွယ်သို့ရောက်သည်ရှိသော် အပြီးတိုင်အောင်သောအတတ်ရှိ၏။” (ညောင်ကန်)')
,(6562,3,4,'စေ့စေ့စပ်စပ်ကြည့်၍ရှာသည်။','“ပွမဂြးသော်ဇွိတ်သော်ဒစုၚ်စဲလ္ပပ။” (လိက်သၚ်္ခါရလိုက်) = “ဆံပင်ဖြီးခြင်း၊ ဆံပင်ပွတ်သပ်ခြင်း၊ သန်းရှာခြင်းမပြုရ။”')
,(6563,3,4,'စောင်းသည်။ တစောင်းဖြစ်သည်။','“(ဇြုံၜံက်တုဲ ဗမၞးဂှ်) လောတ်ဒစေၚ်စှ်ေဒၞာဲဂှ်ရ။” (ဇ—၃၈၉။ အစွောံ) = “မြွေကိုက်၍ ပုဏ္ဏားသည် ထိုနေရာ­ တစောင်းလဲကျသွား၏။” || တိက်လက်ဒစေၚ် = ဘေးစောင်းအနေအထားဖြင့် အိပ်သည်။ || “ဖျဝ်သူစရိုတ်၊စိုတ်ပဒစေၚ်။” (လိက်ပယးအနိစ္စ) = “သုစရိုက်ကိုနှိမ့်ချ၍ စိတ်ကိုမတိမ်းစောင်းစေနှင့်။”')
,(6564,3,4,'တိမ်းစောင်းသည်။ စွေစောင်းသည်။','“သ္ၚိဒစေၚ်ဒလိန်အာ။” (သၚ်္ခါရလိုက်) = “အိမ်စွေစောင်းသွားသည်။” || “အဂတိ (၄) မ္ဂးဂှ် ပွထစေၚ်ဒလိန်အာ ပဟိုတ်နူဆာန်တုဲ ကဵုဒုၚ်ယၟုဆန္ဒာဂတိမွဲ။ ပွထစေၚ်ဒလိန်အာ ပဟိုတ်နူပၞောတ်တုဲ ကဵုဒုၚ်ယၟုဒေါသာဂတိမွဲ။ပွထစေၚ်ဒလိန်အာ ပဟိုတ်ဟွံတီဂုဏ်ဒုသ်တုဲ ကဵုဒုၚ်ယၟုမောဟာဂတိမွဲ။ ပွထစေၚ်ဒလိန်အာ ပဟိုတ်နူဖေက်တုဲ ကဵုဒုၚ်ယၟုဘယာဂတိမွဲ။” (ဓမ္မဝိဘာဂ။ မန်ဍုၚ်သေံ။) = “အဂတိတရားလေးပါးကား ချစ်ခြင်း၊ အမျက်ထွက်ခြင်း၊ အကျိုးအပြစ်ကိုမသိခြင်း၊ ကြောက်ခြင်းစသည်ကြောင့်ဖြစ်သော တိမ်းစောင်းခြင်းများပင်တည်း။”')
,(6565,3,4,'တိမ်းစောင်းသည်။','“တၟံတိုၚ်ဣန္ဒခဳ ဂပ်ဂဝ်တဵုလဝ် ဗွဲမဗိုန်ဇၟအ်ဂှ် ဟိုတ်နူကျာပန်ဒိုဟ်တံ သၟးညံၚ်ရဴဟွံဂွံချဳဒရာၚ်ယောၚ်ယာ ဇောဲဇာဲဒစေၚ်ဒလာဲအာကီု။” (သုဓမ္မဒေသနာ။ဂရိုက်သာံ။) = “ခိုင်ခံ့စွာစိုက်ထူထားအပ်သော မုခ်ဦးကျောက်တိုင်သည် လေးဘက်လေးတန်မှတိုက်ခတ်လာသောလေကြောင့် မတုန်လှုပ် မချွတ်ယွင်း မယိမ်းယိုင် မတိမ်းစောင်းသကဲ့သို့။”')
,(6566,3,4,'ငုံ့သည်။','“အာအကြာမၞိဟ်ဇၞော်ဇၞော် ဒစိုၚ်က္ဍိုပ်တုဲအာဂှ် ဒှ်ယေန်သၞာၚ်ပိုဲမန်ရ။”= “လူကြီးများအကြား ခေါင်းငုံ့၍သွားခြင်းသည် ကျွန်တော်တို့မွန်၏ ယဉ်ကျေးမှုဖြစ်သည်။” || “ဗမၞးဂွကဵုညးတုဲ ဒစိုၚ်ဒၟံၚ်ရ။” (ဇ—၁၂၆။ အစွောံ။) = “ပုဏ္ဏား သူတကာတို့နှင့်ရှက်သဖြင့် ငုံ့၍နေ၏။” || “ဂၞကျာ်ဂွပ္ညပ်၊ ဒစိုၚ်အောပ်မာ။” (လိက်ဇိဝှစက္က) = “မိဖုရားသည် ရှက်သည်ဖြစ်၍ငုံ့လျက်တုပ်ဝပ်လျက်နေ၏။”')
,(6567,3,16,'ကိုး။','ဒစိတ်လ္ၚီ = ကိုးထောင်။')
,(6568,3,4,'‘ဂစာန်’ ရှု။',NULL)
,(6569,3,1,'တောင်ဝှေး။','“(လဗြဴဗျုဂှ်) ရပ်ဒစုန်တုဲ ကွာ်စဴရ။” (ဇ—၃၈၈။ အစွောံ။) =“အဖွားအိုသည် တောင်ဝှေးကိုကိုင်လျက် လျှောက်ပြန်လာ၏။”')
,(6570,3,1,'ငါးရံ့ပဒူပင်။',NULL)
,(6571,3,16,'ရှစ်။','ဒစာံစှ်ော = ရှစ်ဆယ်။ || ဒစာံကၠံ = ရှစ်ရာ။')
,(6572,3,4,'ဖုံးသည်။ ဖုံးလွှမ်းသည်။ ဖုံးကွယ်သည်။','“ယွံဗမၞး၊ (သၟာန်ဝွံဂှ်) ပ္ဍဲဘဝမတုဲတေံ တၠပညာတံ ဟီုကဵုဗမၞးမွဲဝါတြသွံ။ ဟိုတ်မဒစဵုအာဘဝတၞဟ်တုဲ ဗမၞးဗှ်သၞာဟွံဒးရောၚ်” ကျာ်တြဲဂး။ (ဇ—၂ဝဝ။ အစွောံ။) = “ပုဏ္ဏား၊ ဤမေးခွန်းကို ရှေး­လည်း ပညာရှိတို့သည် သင့်အား တစ်ကြိမ်ဖြေဘူးကုန်ပြီ။ ဘဝတစ်ပါးဖြင့် ဖုံးလွှမ်းသည်၏အဖြစ်ကြောင့် သင်သည် မှတ်အံ့သောငှာမစွမ်းနိုင်” ဟု မြတ်စွာဘုရားမိန့်တော်မူ၏။ || “ယွံမၞးတံညးၜါ၊ ပ္ဍဲအတိက်တေံလေဝ် သၟာန်ဝွံ အဲသှ်ကဵုမၞးတံတုဲရသွံ။ ဒစဵုအာဘဝတၞဟ်တုဲ မၞးတံစၟတ်ဟွံဒးရောၚ်” ကျာ်တြဲဂး။ (ဇ—၁၇။ အစွောံ။) || “ထာန်မဒစဵု” (သၠပတ်ဒ္ၚောဝ်သၜေံါ) = “ဖုံးကွယ်ရာအရပ်။”')
,(6573,3,1,'အကြား။ စပ်ကြား။ (ပါဠိ—အန္တရ)','ဒစဵုဒဵု = တောင်ကြား။ (ပါဠိ—ပဗ္ဗတန္တရ) || ဒစဵုဂြိုပ် = တောအကြား။ တောအတွင်း။ (ပါဠိ—ဝနန္တရ) || ဒစဵုသပိုဟ် = ချုံကြား။ (ပါဠိ—ဂုမ္ဗန္တရ) (တြာဲဝိနယသၚ်ရိုဟ်ဂြဳ။ စန္ဒိမာ။)')
,(6574,3,4,'ဆန့်ကျင်သည်။ ဆန့်ကျင်ဘက်လုပ်သည်။','“ပွမဗဵုကလၚ်လှ်ေဒယှ်ေ တိၚ်တိုက်အခိုက်တၞဟ်ဟ် မဒှ်ပွဒစဵုဒစးကဵုသာသနာ။” (ပြကိုဟ်နရသာသန။ သဳလဝန္တ။) = “သာသနာတော်နှင့်ဆန့်ကျင်ဘက်ဖြစ်သော အမျိုးမျိုးသော သီဆိုတီးမှုတ်ကခုန်ခြင်းကို နားထောင်ကြည့်ရှုခြင်း။” || “ပူဂဵုမွဲစွံတုန် ဆာန်သၟိန်သၟဟ်သၟန်တဴရၚ်သ္ကံရ။ နွံကာလမွဲတ္ၚဲ ဒစဵုဒစးကဵုရၚ်သ္ကံတုဲ ညးစုတ်ဒုဟ်အဲ အဲစုတ်ဒုဟ်ညး—။” (ဇ—မဟောဟ်သဓ။ အစွောံ။) = “တစ်မျိုးသောသူတို့သည် အချင်းချင်းချစ်ခင်ညီညွတ်ကုန်၏။ တစ်နေ့သ­ အချင်းချင်းဆန့်ကျင်ကုန်၍ အပြစ်တင်ကြကုန်၏။” || “သဘဴဓဝ်မဒစဵုဒစးကဵုကုသဵုဂှ် အကုသဵုမ္ဂးယၟုရ။” (အဘိဓမ္မတ္ထဒဳပနဳ။ ဂရိုက်သာံ။) = “ကုသိုလ်နှင့်ဆန့်ကျင်သော တရားသဘောကို အကုသိုလ်ဟုခေါ်ဆို၏။”')
,(6575,3,1,'၁။ (ညီအစ်ကိုမောင်နှမ) တိုက်ရိုက်အထက်အောက် အငယ်ဖြစ်သူ။','“ညးမသုန်ကောကဵုဒေံ မၞုံယၟုကောဇၞော်ဂှ် အဇ္ဇုန၊ ဒစှ်ေဂှ် နကုလ၊ ဒစှ်ေဂှ် ဘိမ္မသေဏ၊ ဒစှ်ေဂှ် ယုဓိတ္ထိလ၊ ဒစှ်ေဂှ် သဟဒေဝ။” (ဇ—၅၃၆။ အစွောံ။) = “ညီအစ်ကိုငါးယောက်ရှိရာ အစ်ကိုကြီးအမည်မှာအဇ္ဇုနဖြစ်၏။ ထိုအောက်အငယ်သည် နကုလ၊ ထိုအောက်အငယ်သည် ဘိမ္မသေဏ၊ ထိုအောက်အငယ်သည် ယုဓိတ္ထိလ၊ ထိုအောက်အငယ်သည် သဟဒေဝဖြစ်၏။”')
,(6575,3,1,'၂။ လက်ထောက်။','“ညးဒှ်ဒစှ်ေအ္စာဘာဇၞော်ရ။” = “သူသည် ကျောင်းအုပ်ဆရာကြီး၏ လက်ထောက်ဖြစ်သည်။”')
,(6576,3,5,'သေလုနီးပါး။ သေလုမြောပါး။','“ကမၠတ်ဂှ် ညးဂမၠိုၚ်ရပ်ဂွံတုဲ တက်ၜုၚ်လဝ် ဒစှ်ေချိုတ်ရ။” = “သူခိုးအား လူများဖမ်းမိပြီး သေလုနီးပါးမျှ ရိုက်နှက်ထုထောင်းထားသည်။”')
,(6577,3,4,'ဆန့်ကျင်သည်။ ဆန့်ကျင်ဘက်လုပ်သည်။','“တၠညးအၚ်ဝဖရၚ်မၚ်ဂံၚ်ဂွံမိၚ် ဒဒှ်တၠညးဟံသာဝတဳ တီအတိက်အနာဂတ် ဟွံဒစှ်ေဒစး ပတိုန်မာန်စံၚ်ကီုရဂှ် အိုဟ်တၟိုဟ်စိုတ်ဗွဲမလောန်။” (အကြီုရာဇာဓိရာဇ်) = “ဟံသာဝတီပြည့်ရှင်က အတိတ်အနာဂတ်ကိုသိ၍ မဆန့်ကျင် မာနမထောင်သည်ကို အင်းဝပြည့်ရှင်ဘုရင်မင်းခေါင် ကြားသိရသဖြင့် အလွန်ဝမ်းမြောက်၏။”')
,(6578,3,1,'လှံတံဖျား။ အဖျားချွန်ထက်သောအချောင်း။ (?)','“(နစၟဴခဍာ်မတုပ်တဴ) ညံၚ်ဒဆပ်ပသဲဂှ်ဒှ်တုဲ—။” (ဇ—၂၉၂။ အစွောံ။) = “သံလှံတံဖျားနှင့်တူသော ကျီး၏ချွန်ထက်သောနှုတ်သီး ဖြင့်—။”')
,(6579,3,1,'‘တဆိပ်','တဆိပ်တဲ’ ရှု။')
,(6580,3,1,'‘တဆိပ်ကြာ’ ရှု။',NULL)
,(6581,3,1,'ဆန်ခါ။','“ပ္ဍဲကၟံၚ်ဂေါဝ်ဂပ်၊ ဂြောပ်လဝ်ဓဇာ။” (လိက်ဗြရတ်ဣဏၚ်ကၚ်ရဳ) =“(ဆင်၏) တင့်တယ်လှသောဦးကင်း­ ဆန်ခါဖုံးထား၏။”')
,(6582,3,4,'‘ဓဇဳဓဇောတ်’ ရှု။',NULL)
,(6583,3,4,'ယိုသည်။','ကမဳဓဇူ = အိမ်အမိုးယိုသည်။ || “မဒးပဒတဴကေုာံထဴဗျု ဒဇူတဴနဍာ်ပါၚ်ဂှ် ပ္ဍံဟွံဆာဲသွံ။” (ဇ—ဝေသန္တဝ်။ အစွောံ။) = “တံတွေးယိုသော ယောကျာ်းအိုနှင့်တကွ ပေါင်းသင်းနေရခြင်းသည် မကောင်းပါတကား။”')
,(6584,3,4,'ခေါင်က မိုးယိုသည်။','ကြီးသူက စည်းမျဉ်းစည်းကမ်းကို ချိုးဖောက်သည်။')
,(6585,3,1,'၁။ လက်သမား။','“ဓဇဲတံတုန်လေဝ် ကာလမဟာပ်ပုၚ် ညးမွဲမွဲ ပုၚ်မွဲမွဲထမှတ် —က္ၜတ်ကဵုစိၚ်ရ။” (ဇ—၁၅၆။ အစွောံ။) = “လက်သမားတို့သည်လည်း ထိုဆင်အား ထမင်းစားသောအခါ­ တဆုပ်တဆုပ်စီသော — ထမင်းဆုပ်တို့ကို ပေးကုန်၏။” (ညောင်ကန်) || “ဒဇဲဂၞိၚ်ကွိုၚ်၊ ဂိုၚ်ဝါစဳမြ။” (လိက်သောဝိန်ဇဲယ။ မာံရောဂေါ။) = “လက်သမားသည် ခါးညောင်း၍ပဲခွပ်ဓါးတို့ကို သိမ်း၏။”')
,(6585,3,1,'၂။ သစ်တောက်ငှက်။ ခေါက်ရှာငှက်။','“ဗောဓိသတ်ပိုဲ ဒှ်ဂစေံဒဇဲဒၟံၚ်ပ္ဍဲဟေမဝန်—။” (ဇ—၃ဝ၈။ အစွောံ။) = “ဘုရားလောင်းသည် ဟိမဝန္တာ­ သစ်တောက်လောက်ငှက်ဖြစ်၏။” (ညောင်ကန်)')
,(6586,3,4,'ဆွဲသည်။','“ဇွကၠဵုဂှ် ညးဒဇက်ဏာကဵုဇုက်ရ။” = “ခွေးသေကောင်ကို ကြိုးနှင့် သူတရွတ်တိုက်ဆွဲသွားသည်။” || “ဂၞကျာ်ရပ်ဂွံသော်ပါၚ်ဣသိတုဲ ဂြဲဒဇက်နၚ်ဒဇက်ဏာ ဂတမုက်ဂှ်ရ။” (ဇ—၆၆။ အစွောံ။) = “မိဖုရားသည် ရသေ့၏ကျင်စွယ်မုတ်ဆိတ်ကိုကိုင်၍ ဤဘက်သို့၄င်း ထိုဘက်သို့၄င်း အပြန်ပြန်အလှန်လှန်ဆွဲ၏။”')
,(6587,3,1,'တစ်ချောင်းငင်။ မွန်အုသရအသံအတွက် ဗျည်းအက္ခရာအောက်တွင် ရေးသောသင်္ကေတ။ —ု။',NULL)
,(6588,3,1,'နှစ်ချောင်းငင်။ မွန်အူသရအသံအတွက် ဗျည်းအက္ခရာအောက်တွင် ရေးသောသင်္ကေတ။ —ူ။',NULL)
,(6589,3,1,'သဇင်ပန်း။','ယခုအခါ ‘သဇေၚ်’ ဟု အများအားဖြင့်ရေးကြသည်။')
,(6590,3,4,'‘ဓဇောတ်’ ရှု။',NULL)
,(6591,3,4,'ရက်စက်သည်။','“မူရဴညးမွဲမဒဇန် သတုပ်ဨကရာတ်ပိုဲ ဟၟဲသွံလေဝ်ဒေဝတဴတံ။” (ဇ—၃၅၈။ အစွောံ။) = “ငါတို့၏မင်းနှင့်တူသော ရက်စက်သောသူဟူ၍ မရှိပါလားနတ်အပေါင်းတို့။” || “အဵုရာဟူလ၊ အံက်မဓဇန်။” (လိက်ထေအနန်) = “အိုရာဟုလာ၊ သင့်ခမည်းတော်သည် ရက်စက်၏။”')
,(6591,3,1,'ရက်စက်ခြင်း။ ရက်စက်မှု။','“နူကဵုဗြာန်လၟတမ္ၚာမိစ္ဆာတံဂှ် ဓဇန်တၠညးမွဲဂှ် လောန်က္ဍၚ်အာကၠံဆ လ္ၚီဆ မွဲလက်ဆရောၚ်သွံအဴ။” (ဇ—၃၅၈။ အစွောံ။) = “အရှင်မင်းကြီး၏ရက်စက်မှုသည်ကား မုဆိုးတံငါ လူ့မိစ္ဆာတို့ထက် အဆပေါင်းရာထောင်သောင်းမျှ ပိုလွန်ကဲလှ၏။” || “ဒဇန်အံက်မ၊ လောန်ထောန်ရကောန်။” (လိက်သၚ်ဂဒါ။ သဳလဝန္တ။) =“ချစ်သား၊ သင့်ဖခင်၏ရက်စက်မှုသည် အလွန်တရာလွန်ကဲလှ၏။”')
,(6592,3,4,'ရက်စက်သည်။ ကြမ်းကြုတ်သည်။ ရုန့်ရင်းသည်။','“တလတံ၊ ဒေဝဒတ်ဝွံ သ္အဵုသ္အာ်သ္ကာတ်မြဟ် ဓဇန်သဳလောန်။” (ဇ—၂၂၂။ အစွောံ။) = “ငါ့သျှင်တို့၊ ဒေဝဒတ်သည်ကြမ်းတန်း၏၊ ရုန့်ရင်း၏၊ နိုင်ထက်ကလူမူတတ်၏။” (ညောင်ကန်)')
,(6593,3,4,'တုန်လှုပ်သည်။ လှုပ်ရှားသည်။','“(ညာတ်ပြဘာတ်ဗြဴဂှ် မၞုံကဵုရုပ်သာ်တုဲ) စိုတ်သၟိၚ်ချဳသမြပ်ဒဇပ်တဴရ။” (ဇ—၄၄၃။ အစွောံ။) = “မင်းသည် ရုပ်အဆင်းလှသော ပရိဗိုဇ်မကိုမြင်၍စိတ်တုန်လှုပ်၏။” || “မိသာဲနူကောန်၊ ကၠၚ်ကၠောန်ဟောံဇြ။ ဖျုန်ဂြိုဟ်ဖြပ်ဖြပ်၊ ဒဇပ်ယဲသြ။” (လိက်ဟတ္ထိပါလ။ အစွောံ။) = “သားမှကွေကွင်းသောမိခင်သည် အထီးကျန်ပူဆွေးကာ နှလုံးဆတ်ဆတ်တုန်လျက် အလွန်အမင်းတုန်လှုပ်၏။”')
,(6594,3,4,'တုန်လှုပ်သည်။','“ဘိမ္ဗသေဏ မိၚ်ဗရုအသံဖံမံၚ်ပၞာန်ညးတေံတုဲ ဖေက်ဒဇပ်ဇတဝ်တဴရ။” (ဇ—၈ဝ။ အစွောံ။) = “ဘီမသေနသည် ရန်သူ၏စစ်ထိုးသော စည်သံကိုကြား၍ကြောက်ရွံ့တုန်လှုပ်၏။” || “ကၞုဲဂမၠိုၚ် ညာတ်မၞိဟ်ဂမၠိုၚ်ဗိုၚ်သြပ်ဒၟံၚ်—ဂှ်တုဲ တြဴမွဲသ္ဂောံဒဴအာဂှ် ဟွံညာတ်တုဲ သီုမဖေက်ဒဇပ်ဇတဝ်တဴ—။” (ဇ—၄ဝ၇။ အစွောံ။) = “လူများဝိုင်းရံနေသည်ကိုမျောက်များမြင်သော် ပြေးရန်လမ်းကို မမြင်သဖြင့် ကြောက်ရွံ့တုန်လှုပ်ကုန်၏။” || “သၟတ်ကောန်ဗြဴဓမာတ်ဂှ် ချိုန်မမိၚ်ပါၚ်ဗောဓိသတ်ဗက်ဂှ်ရ ပ္ဍဲဂၠံဟဒယဖျုန်ဂြိုဟ်တေံဂှ် ဒဇပ်ဇတဝ်တဴတုဲ ဒၟံၚ်ဟွံပိုၚ် ပခိုၚ်စိုတ်ဟွံမာန်တုဲ ကွာ်တိတ်ကၠုၚ်ကၟေၚ်သ္ၚိရ။” (ဇ—၃၈၇။ အစွောံ။) = “ပန်းဘဲသူကြီး၏သမီးသည် ဘုရားလောင်း၏အသံကို ကြားရသည်နှင့် နှလုံးသည်းပွတ်­ လှုပ်ရှားလျက်မနေသာဘဲ စိတ်ကိုခိုင်အောင်မထားနိုင်ဘဲ အိမ်ကပြင်သို့ လျှောက်ထွက်လာ၏။”')
,(6595,3,1,'စဉ်းသွား။ မြားလက်နက်၏အသွား။',NULL)
,(6596,3,1,'နေစာမြက်။','“မသတိက်ဒၟံၚ် အကြာကၟတ်ဒဇိပ်ဂှ်တုဲ—။” (ဇ—၅၁၃။ အစွောံ။) = “နေဇာမြက်ပေါ်­နေ၍ အတန်ငယ်အပန်းဖြေပြီးလျှင်—။” (ညောင်ကန်)')
,(6596,3,4,'ညစ်ညူးသည်။ လွှမ်းမိုးသည်။ (?)','“ပုဏ္ဏကမဒဇိပ်ဒၟံၚ် နဓဝ်ရာဂဒေါသမာန—။” (ဇ—ဝိဓုရ။ အစွောံ) = “ရာဂဒေါသမာနတရားတို့ဖြင့် ညစ်ညူးနေသောပုဏ္ဏက။”')
,(6597,3,4,'ခုတ်စဉ်းသည်။ နုပ်နုပ်စဉ်းသည်။ စဉ်းကောလုပ်သည်။','“ဖျုန်ဍေံဒဇီစဂြိုဟ်ကြုတ်ဍေံ ၜိုဟ်ကဵုမြေက်—။” (ဇ—မဟောဟ်သဓ။ အစွောံ။) = “အသားကိုခုတ်စဉ်း၍ စဉ်းကောလုပ်စားမည်။ အသည်းအူတို့ကို ငရုတ်သီးနှင့်ပြုတ်စားမည်။” || “ဖျုန်ဍေံခပ်သီ၊ ဂွံဓဇီစ။” (လိက်နဲယသမုဒ္ဒြဳ။ အစွောံ။) = “အလုံးစုံသောသူ့အသားကို စဉ်းကောလုပ်စားမည်။”')
,(6597,3,1,'စဉ်းကော။ စိမ်းကော။','ဒဇီကၠိက် = ဝက်စဉ်းကော။')
,(6598,3,4,'(မျက်ရည်) ဖြိုင်ဖြိုင်ကျသည်။','“ဒဒှ်ကောသၟတ်၊ ဗြဲမတ်ဒဇီ။ ဒဇန်မှာယျ၊ နာဲဟွံပတီ။ ကောသုၚ်လၞီ၊ မိဟွံတီဟာ။” (လိက်သၟိၚ်ဇဲယဒတ္တ) = “မောင့်အဖြစ်က မျက်ရည်မိုးဖြိုင်ဖြိုင်ကျ၏၊ ချစ်သူမယ်သည် မသိကျိုးကျွံပြုကာ ရက်စက်နိုင်လွန်းလှ၏၊ မောင့်ခမျာ ဗျာသင့်နေသည်ကို ချစ်သူမယ်မသိလေသလော။”')
,(6599,3,1,'ကစော်ရည်။ စိမ်ရည်။',NULL)
,(6600,3,4,'(မနှစ်သက်သည့်အမူအရာဖြင့်) နှုတ်ခမ်းကိုလှုပ်သည်။ နှုတ်ခမ်းကိုကိုက်သည်။ (to curl one’s lip)','“သၟတ်ကောန်သၟိၚ်ဝွံ ဒဇဵုတဴနသၟန်ပါၚ်—။” (ဇ—၂၄၇။ အစွောံ။) = “ဤမင်းသားငယ်သည် နှုတ်ခမ်းကိုကိုက်၏။”')
,(6601,3,4,'တံတွေးယိုသည်။','“ဨဠမုခေါဝါ။ ညးမဒဇဵုတဴဍာ်ပါၚ်ဒမၠိကီု။” (တြာဲဝိနယသၚ်ရိုဟ်ဂြဳ။ စန္ဒိမာ။) = “တံတွေးယိုသော ခံတွင်းရှိသောလူမိုက်။” ||“မပ္တံက္ဍိုၚ်နူဂဝ်၊ ကၠဴနူဂဝ်၊ကၠက်နူဂဝ်၊ ဒဇဵုဍာ်ပါၚ်နူဂဝ်တံဂှ် ဒးက္တဵုဒှ်ရ။” (သ္ဂုတ်သွာတ်သဳမသုန်။ နာဲမန်ၜိုပ်ထဝ်။) = “မွေးရာပါနားပင်းခြင်း၊ မွေးရာပါအ၊ခြင်း၊ မွေးရာပါကန်းခြင်း၊ မွေးရာပါတံတွေးယိုခြင်း အစရှိသည်တို့ဖြစ်ရ၏။” || “ဍာ်ပါၚ်တုန်သွံ၊ ဟွံဇွောဝ်ဒဇဵု။” (လိက်ပယးအနိစ္စ) = “တံတွေးသည်လည်း မယိုစီး။”')
,(6602,3,1,'သပွတ်သီး။',NULL)
,(6603,3,4,'စိုးရွံ့သည်။ ရိုသေသည်။','“ဇၞတ်သမ္ဘာမဟီု (တြုံဂှ်) အစောံကျကိလေသ ဒညဇြဟာန်လီု ယိုက်ကေတ်ဂလာန်သမ္ဘာ—။” (ဇ—၁၄၇။ အစွောံ။) = “မယားပြောဆိုတိုက်တွန်းသည်ရှိသော် ထိုယောကျာ်းသည် ကိလေသာကို ရှုံးသည်၏အစွမ်းအားဖြင့် အချစ်ပျက်အံ့သည်မှစိုးသောကြောင့် မယားစကားကို နာယူ၏။”')
,(6604,3,4,'ထိတ်လန့်သည်။ ကြောက်လန့်သည်။','“သၟိၚ်ညာတ်ဒေဝတဴတုဲ ဖေက်ဒညကမၠတဴတုဲ—။” (ဇ—၄၆၅။ အစွောံ။) = “မင်းသည် ထိုနတ်ကိုမြင်လျှင် ကြောက်လန့်သည်ဖြစ်၍—။” (ညောင်ကန်) || “တြုံမနၚ်ပုၚ်တ္ၚဲဝွံဂှ် တၟေၚ်တၟဟ်လောန်သန်သွံ” ချပ်တုဲ ကလော်ဒညကမၠတဴပ္ဍဲစိုတ်ရ။ (ဇ—၃၉၈။ အစွောံ။) = “ယနေ့ထမင်းလာပို့သောယောကျာ်းသည် အလွန်ထူးဆန်းပါလား” ဟုတွေး၍ ဘီလူးသည် စိတ်­ထိတ်လန့်၏။ || “သၟတ်ကောန်တြုံသၟိၚ်ဝွံဂှ် ဖေက်ဂၟံက်ဒညကမၠ ဟၟဲသက်သက်ရောၚ်သွံ။ အသဝ်တြုံရောၚ်” ကလော်ချပ်။ (ဇ—၅၁၃။ အစွောံ။) = “ဤမင်းသားသည် ကြောက်ရွံ့ထိတ်လန့်ခြင်း အလျှင်းမရှိ။ အာဂယောကျာ်းပေတည်း” ဟုဘီလူးကြံ၏။')
,(6605,3,4,'ခေါင်းညိတ်သည်။','“သၟိၚ်ဇိပ်ဗြာဲဂး ဂလာန်ဂှ်ဂွံမိၚ်တုဲ ဗညာဒညိက်တိုန် စဴအာသ္ၚိရ။” (အကြီုရာဇာဓိရာဇ်) = “သမိန်ဇိပ်ဗြဲပြောသောစကားကို ကြားရသောအခါဗညားနွဲ့သည် ခေါင်းညိတ်၍ အိမ်ပြန်သွား၏။”')
,(6606,3,4,'ငိုက်မျဉ်းသည်။ (?)','“ညာတ်ဒိုၚ်ညာတ်ပံက်၊ ဒညံက်ဇိုၚ်လှာ။” (လိက်ဇိဝှစက္က) =“အိုၚ်အနီး­ ဘုမ္မတီး၊ ဥဗျိုင်းတို့ ငိုက်မျဉ်းနေကြသည်ကိုမြင်၍။”')
,(6607,3,4,'စိုးရိမ်သည်။ ကြောင့်ကြသည်။','“အိုတ်သီုဒိုက်ယဲ၊ လယိုင်အဲအိၚ်။ နာဲပဒညိၚ်၊ ညိပဒွိၚ်ဒွဲါ။” (လိက်သောဝိန်ဇဲယ။ မာံရောဂေါ။) = “အလုံးစုံသောဖျားနာခြင်းအတွက် ငါ့တာဝန်ထားပါ၊ သင်မကြောင့်ကြမပူပန်လေနှင့်။”')
,(6608,3,12,'(န) ဆွေမျိုး။','ကလောဒညာတ် = ဆွေမျိုးညာတိ။')
,(6609,3,4,'မာန်ဖီသည်။ မာန်စောင်သည်။','“ပြေၚ်ဂၠဴကၠဗြန်၊ ဒညန်ဟဳဟဳ။” (လိက်ပတ္တစာရဳ။ နာဲထဝ်စိုပ်။) = “ကျွဲနွားကျားသစ်တို့သည် တဟီဟီအသံပြုလျက် မာန်ဖီနေကုန်၏။” || “ဟွံဂံၚ်ဇူရ၊ ကၠဗြုဒညန်။” (လိက်သုပိဏ္ဏကုမ္မာ။ မၚ်သၚ်ကြာ။) = “ကျားမာန်ဖီအော်နေသဖြင့် မနားနေဝံ့။”')
,(6610,3,4,'(သေသောက်ရာတွင်) ချင်ခြင်းကိုတိုးစေရန် သောက်မြိန်စေရန် တစ်ခုခုကို တွဲဖက်၍စားသည်။ (?) (to eat as a whet)','“ကာလလဗၚ်တံမသုၚ်သုရာဂှ် မဒညဝ်ပအဵုသ္အာၚ်ဂှ် ကွးညးဗၞိက်ဂှ်ညာတ်။” (ဇ—၄၇။ အစွောံ။) = သေသောက်ကြူးတို့ သေသောက်ကြသောအခါ ဆားကိုသေနှင့်တွဲဖက်စားသည်ကို ကုန်သည်တပည့်သည်မြင်၍—။')
,(6611,3,1,'ကြောင်ပန်းရွက်ပင်။',NULL)
,(6612,3,4,'တွန့်သည်။',NULL)
,(6613,3,1,'ပင်ပန်းခြင်း။ ပူလောင်ခြင်း။ ပူပန်ခြင်း။ (ပါဠိ—ဍာဟ/ဒါဟ)','ဒတူတလာဲကာယ = ကိုယ်၏ပူလောင်ခြင်း။ (ပါဠိ—ကာယဒါဟ) || ဒတူတလာဲစိုတ် =စိတ်နှလုံးပူပန်ခြင်း။ (ပါဠိ—မနောတာပ) || “ဂမှဳမွဲဂှ် စိုတ်စပ်အာကဵုဗြဴမွဲတုဲ ဒတူတလှာဲရာဂဂှ်တုဲဇြေဟ်ဇြာဲဖျိုဟ်ဂတးတုဲ လတေၚ်ကြာန်ဓမာန်တဴရ။” (ဇ—၅၂၇။ အစွောံ။) = “ထိုရဟန်းသည်တစ်ယောက်သောမိန်းမကိုမြင်လေလျှင် တပ်စွန်းသောစိတ်ရှိ၍ ရာဂပူလောင်ခြင်းကြောင့် ကြုံလှီဖျော့တော့၍ အကြောပြိုင်းပြိုင်းထလျက်ရှိ၏။” || “အဲဍောၚ်တုဲ အဲစှ်ေဟုံဍာ်လစဂှ်တုဲ ဗၠးနူဒတူတလာဲတုဲ (အဲတိုန်ကၠုၚ်နူဍာ်ရ။)” (ဇ—၅၂၆။ အစွောံ။) = “အကျွန်ုပ်သည်ပင်ပန်း၍ ရေအိုင်­ရေဆင်းချိုးသဖြင့် အပင်ပန်းငြိမ်းလေလျှင် ရေမှတက်လာ၏။” || “ကိလေသဒရာထာနံ၊ န်ဒလိုက်ဒလာၚ် ဒတူတလာဲ ဂမ္တဴဂမ္တာန်ကိလေသဂမၠိုၚ်။” (ဓမ္မဒဳပနဳ။ မာံရွှေငိုး။) = “ကိလေသာ၏ဆင်းရဲခြင်း၊ ပူပန်ခြင်း၊ ပူလောင်ခြင်းများ။”')
,(6613,3,1,'ပူလောင်သည်။ ပူပန်သည်။','“ယွံသၟိၚ်မပြဲ၊ယာံရတၠညးထောံကၠေံအဲဍိက်ဗြဴ မသက္ကုစ္ၜုဲစ္ၜော်ဝွံတုဲဂှ် ဖျုန်ဂြိုဟ်အဲဍိက်ဗြဴဒတူဒလာဲအာရအဴ။—”ဂၞကျာ်ဂး။ (ဇ—၄၁၁။ အစွောံ။) = “မြတ်သောမင်းကြီး၊ အကျွန်ုပ်အား အရှင်စွန့်ခွါသွားပါမူ အကျွန်ုပ်သည် အားကိုးရာမဲ့၍ နှလုံးပူလောင်ရလတ္တံ့” မိဖုရားဆို၏။ || “မဂွံဒတူတၠာဲကဵုစိုတ်ညးမၞုံဂလာန်မဂွံတ္ၜန်တ္ၜောဲ ဂွံဟီုနၚ်ဟီုဏာဂှ်လေဝ်ကီု—။” (ဇ—၂၈၇။ အစွောံ) = “သူတစ်ပါး၏စိတ်ကို ပူလောင်ပင်ပန်းစေရအောင် ဖရိုဖရဲရှုပ်ထွေးသောစကားဖြင့် အပြန်ပြန်အလှန်လှန် ပြောဆိုခြင်းကို၄င်း။” || “ဍေံသကာတ်မြဟ်၊ တွံဂးဒေါသ။ ဒတူတလာဲ၊ လောန်ကာဲက္ဍၚ်ပြ။” (လိက်မ္ၚဵုပိစှ်ောဒစာံ။ မာံထဝ်စိုပ်။) = “ကြမ်းကြုတ်သောဒေါသသည် အလွန်အမင်းပူလောင်၏။”')
,(6614,3,4,'ပူဆွေးသည်။ ပူပန်သည်။','“ဒတူဒစာ်၊ ပၠဳဍာ်ရမတ်။” (လိက်မာဃဒေဝါန်) =“ပူဆွေးပူပန်၍ မျက်ရည်ယို၏။” || “ဒတူဒစာ်၊ နှဳဍာ်ရမတ်။” (လိက်မေဃသန်)')
,(6615,3,4,'၁။ လက်ဆွဲခေါ်ဆောင်သည်။ တွဲခေါ်သည်။','“သၟိၚ်ရပ်တဲသဟာဲဂှ်တုဲ ဒတဲပ္တိုန်ဏာပြာသာဒ်ရ။” (ဇ—၃ဝ၂။ အစွောံ။) = “မင်းသည် အဆွေခင်ပွန်း၏လက်ကိုကိုင်၍ နန်းပြာသာဒ်သို့တွဲခေါ်တင်သွား၏။” || “(တြုံကမၠတ်ဂှ်) ရပ်တဲသဳရိမာဂှ်တုဲ ဒတဲပၠောပ်ဏာ ပ္ဍဲကၟဵုတၞံပ္ကဴဇဗဂှ်—။” (ဇ—၃၁၈။ အစွောံ။) = “ထိုခိုးသူယောကျာ်းသည် သာမာ၏လက်ကိုကိုင်၍ ကုလားဇလပ်ပန်းချုံသို့ လက်တွဲခေါ်သွင်း၏။” || “ကောန်တြုံမွဲဂှ် ဒတဲရ။ ကောန်တြုံမွဲဂှ် လေၚ်လဝ်ရ။” (ဇ—၅ဝ၉။ အစွောံ။) = “သားတစ်ယောက်ကို လက်ဆွဲခေါ်ဆောင်၏။ သားတစ်ယောက်ကို ခါး­ချီ၏။”')
,(6615,3,4,'၂။ အပ်နှင်းသည်။ ဆောက်နှင်းသည်။','“ပတၠလဟီု ဟီုကဵုဒးကတောဝ် ဗြဴဂေါဝ်ညးဒတဲကဵု။” (သၠပတ်ဒ္ၚောဝ်သၜောံ) = “အပြောတတ်သူအဖြစ် နားဝင်ချိုအောင်ပြောခြင်းဖြင့် သူတစ်ပါးတို့က မိမိအား မိန်းမလှကို ဆောက်နှင်းပေးအပ်ပေလိမ့်မည်။”')
,(6615,3,4,'၃။ (ကြိုးစသည်ဖြင့်) သီသည်။ သီကုံးသည်။ (to string)','“မၞိဟ်မွဲဂှ် ဍေံဍန်ဂွံကထပှ်တုဲ ဍေံစတ်ဒတဲကဵုဇုက်တုဲ—။” (ဇ—၃၁၆။ အစွောံ။) = “တယောက်သောတံငါသည်သည် ငါးကြင်းခုနစ်ကောင်တို့ကိုဆယ်၍နွယ်ဖြင့်သီ၍—။” (ညောင်ကန်)')
,(6616,3,4,'လက်တွဲခေါ်ဆောင်သည်။ လမ်းပြသည်။','“ကောန်ဇာတ်ဇကု ညံၚ်ဂွံစဳကၠးယေန်သၞာၚ်ဂှ် ဒးဒတဲကဝါ်လဝ် နူဍောတ်တ်ရောၚ်။” = “မိမိ၏သားသမီးများ လိမ္မာယဉ်ကျေးအောင်ငယ်စဉ်ကတည်းက လမ်းပြပေးထားရပါမည်။”')
,(6617,3,1,'နေထိုင်ရာ။ တည်နေရာ။','သ္ပဒတဴ = နေထိုင်သည်။ ‘တဴ’ (ကြိ) လည်းရှု။ || ဋ္ဌာန်ဒတဴ = နေရာ။ နေထိုင်ရာနေရာ။ || “(ယွံခမဳ) ၊ ဋ္ဌာန်ဒတဴမၞုံကဵုဂုန်ကီု ဟၟဲကဵုဂုန်ကီု ဟွံဂွံတီတုဲဂှ်မူပဂွံပဒတဴပ္ဍဲဋ္ဌာန်ဂှ်ဒှ်ရော” ကျာ်တြဲဂး။ (ဇ—၃၇၉။ အစွောံ။) = “သင်သည် မိမိ၏ကျေးဇူးရှိမရှိကို မသိရာအရပ်­ အဘယ်ကြောင့်နေသနည်း။” (ညောင်ကန်) || “ညံၚ်တိဇၞော်မဒှ်ဒတဴသတ္တံဂမၠိုၚ်။” (သ္ကေံမိလိန္ဒဝတ္ထု) = “ကမ္ဘာမြေကြီးသည် သတ္တဝါအပေါင်းတို့၏တည်နေရာဖြစ်သကဲ့သို့။”')
,(6618,3,4,'မတ်တတ်ရပ်သည်။','“ခါဒတဴဒၟံၚ်ဇိုၚ်ပန်ဂှ် တိဒုၚ်လယိုင်အဲဟွံမာန်။ ဟိုတ်ဂှ်ရ အဲဒတဴဒၟံၚ်ဆဇိုၚ်မွဲဝွံရောၚ်” ကၠဵုစၞာဲဂး။ (ဇ—၁၂၈။ အစွောံ။) = “ငါသည် ခြေလေးချောင်းတို့ဖြင့်ရပ်သည်ရှိသော် မြေသည် ငါ၏ခန္ဓာဝန်ကို မခံနိုင်လတ္တံ့။ ထို့ကြောင့် ခြေတစ်ချောင်းဖြင့်သာလျှင်ရပ်၏” ဟုမြေခွေးစဉ်းလဲဆို၏။ || “ကျာ်တြဲပြာပ်အာဒတဴဒၟံၚ် ပ္ဍဲပါၚ်တရၚ်သ္ၚိအမာတ်တေံမွဲဂှ်ပၠန်ရ။” (ဇ—၁၅၄။ အစွောံ။) = “မြတ်စွာဘုရားသည် ကြွသွားတော်မူ၍ နောက်အမတ်တစ်ယောက်၏ အိမ်တံခါးဝ­ ရပ်နေတော်မူပြန်၏။”')
,(6619,3,4,'ကြက်သီးမွေးညှင်းထသည်။ (ပါဠိ—လောမဟံသ)','“နအနုဘဴပရိုတ်မန်ဂါထာတုဲ တ္ၚဲကီု ဗ္တံကီု ပရိုက်ဘဲအန္တရာဲ ဟွံမွဲကဵုသၟိၚ်မြာ်ထဝ်ရ၊ ဒတဴနရဴသော်ဇကုလေဝ် ဟွံဒှ်ရ။” (ဇ—၁၅၉။ အစွောံ။) = “ရွှေဥဒေါင်းမင်းအား ညဉ့်­၄င်း နေ့­၄င်း ပရိတ်၏အာနုဘော်ကြောင့်ဘေးသည်လည်း မဖြစ်သည်သာလျှင်တည်း။ ကြက်သီးမွေးညှင်းထခြင်းသည်လည်း မဖြစ်သည်သာလျှင်တည်း။” (ညောင်ကန်) || “အဲညာတ်အသဝ်စိုတ်ဒြာဲၜါ (တၠသဳလ) ဂှ်တုဲ အဲဍိက်သမ္ၚံက်သမ္ၚာတ်စိုတ် ဒတဴနရဴသော်ဇကုဂှ်ဒှ်တုဲ ဗဟေက်ဗွဲမလောန် က္တဵုဒှ်ကုအဲရအဴ” လၟဂး။ (ဇ—၅ဝ၁။ အစွောံ။) = “အကျင့်သီလရှင်ဖြစ်သော နှစ်ခုသောသမင်တို့၏ အံ့ဖွယ်ထူးမြတ်သောစိတ်ကိုမြင်၍အကျွန်ုပ်သည် ထိတ်လန့်တုန်လှုပ်လျက် ကြက်သီးမွေးညှင်းထသည်ဖြစ်၍ အလွန်ကြောက်ခြင်းသည်ဖြစ်ပေါ်၏။” || “အဲညာတ်ဂမှဳဂှ်ယာံတုဲ အဲသမ္ၚာတ်ပ္ဍဲစိုတ်အဲတုဲ သော်ဇကုအဲ ဒတဴနရဴအာရောၚ်အဴ” ဒေဝတဴဗြဴဂး။ (ဇ—၅၂၃။ အစွောံ။) = “အကျွန်ုပ်သည် ထိုရဟန်းငိုသည်ကိုမြင်၍ထိတ်လန့်တုန်လှုပ်လျက် ကြက်သီးမွေးညှင်းထပေ၏။” || “ကလော်ဂှ် ဖေက်ဂၟံက်ဒတဴနရဴသော်ဇကုဂှ်ဒှ်တုဲ မၠာ်မွဲဗဵုတဴဒ္ဂေတ်ပြဝကောန်တြုံသၟိၚ်ဂှ်ရ။” (ဇ—၅၁၃။ အစွောံ။) = “(ဘီလူးသည်) ကြက်သီးမွေးညှင်းထခြင်းဖြစ်သဖြင့် မင်းသားကို အဖန်တလဲလဲ ကြည့်လျက်နေ၏။” (ညောင်ကန်)')
,(6620,3,4,'ရပ်တည်သည်။ ရပ်လျက်နေသည်။','“ရာဟုလတုန် ပြာပ်အာဇရေၚ်ကျာ်တြဲတုဲ ဂလာန်မထေက်ကြိုက်ကဵုဇကု ဗွဲမဂၠိုၚ်ဟီုတုဲ ဒတဴလိုၚ်ဒၟံၚ်ရ။” (ဖဵုသ္ပထပိုဲခမဳ။ ဂရိုက်သာံ။) (ဒတဴ= လိုၚ်) = “ရာဟုလာလည်း မြတ်စွာဘုရားထံ ချဉ်းကပ်သွားပြီးလျှင် မိမိနှင့်လျောက်ပတ်သောစကားတို့ကို များစွာပြောဆို၍ မတ်တတ်ရပ်လျက်နေ၏။”')
,(6621,3,1,'အိမ်ထောင်။ အိမ်ရာထောင်ခြင်း။','“ကောန်ဗမၞးဂှ် ပ္ဍဲဒတဴသ္ၚိကၟိန် တန်ဒၟံၚ်တုဲ မပ္တံကောန်သမ္ဘာ၊ ပြေၚ်ဂၠဴ၊ တိဗ္ၚကၠအ်သွဝ်တံ—ဂှ် ချပ်စံၚ်တူတဴရ။” (ဇ—၁၈၅။ အစွောံ။) = “ထိုပုဏ္ဏားသတို့သားသည် အိမ်ထောင်­တည်နေ၍ သားမယား၊ ကျွဲနွား၊ လယ်ယာခြံမြေ အစရှိသည်တို့ကို တွေးကြံပူပန်၏။” || “ပ္ဍဲကာလကြဴဝွံ ဗမၞးဂိုၚ်ကေတ်ဒတဴသ္ၚိကၟိန်တုဲ ဟိုတ်နူမချပ်တဴကေၚ်ကာသ္ၚိကၟိန်ဂှ်တုဲ စိုတ်တဍိုက်လ္ၚေၚ်အာ။” (ဇ—၁၈၅။ အစွောံ။) = “ထိုပုဏ္ဏားသည်နောင်အခါ­ အိမ်ထောင်ခြင်းကိုပြု၍ အိမ်ထောင်မှုကိုကြံသဖြင့် နောက်ကျုသောစိတ်ရှိသည်ဖြစ်၍—။” (ညောင်ကန်) || ‘ပဒတဴသ္ၚိကၟိန်’ (ကြိ) လည်းရှု။')
,(6622,3,4,'အတွဲဖြစ်အောင်တွဲသည်။',NULL)
,(6622,3,9,'အတွဲ။','ကြုက်ၜါဒတိုက် = သရက်သီးနှစ်တွဲ။')
,(6623,3,1,'၁။ ထွက်ခြင်း။ (ရသေ့ရဟန်းပြုရန်) တောထွက်ခြင်း။','“ယွံဂမှဳတံ၊ ဆလၟုဟ်ဝွံ အဲကျာ်မဂွံတိတ်ဂြိုပ်ဂှ်ဟွံသေၚ်၊ ပ္ဍဲကာလအတိက်တေံကီုလေဝ် ဒတိတ်ဇမၞော်ဂှ် အဲသ္ဂောံတိတ်ကၠုၚ်တုဲရ” ကျာ်ဂး။ (ဇ—၅၁ဝ။ အစွောံ။) = “ရဟန်းတို့၊ ယခုအခါ­သာလျှင် ငါဘုရားသည် မြတ်သောတောထွက်တော်မူခြင်းကို တောထွက်တော်မူသည်မဟုတ်သေး၊ ရှေး­လည်း မြတ်သောတောထွက်ခြင်းကို တောထွက်တော်မူဖူးသည်သာလျှင်တည်း။” (ညောင်ကန်)')
,(6623,3,1,'၂။ ထွက်ရှိခြင်း။ထွက်ရှိသောကုန်ပစ္စည်း။ အထွက်နှုန်း။','“သၞာံဏအ် ဒတိတ်သြောအ်ခိုဟ်ဒၟံၚ်ဟာ။” = “ဤနှစ်စပါးအထွက်နှုန်းကောင်းပါသလား။” || ‘တိတ်’ (ကြိ) လည်းရှု။')
,(6624,3,1,'၁။ (ဘုရားလောင်း၏) အခြံအရံနှင့်တကွ တောထွက်ခြင်း။ ကြီးစွာသောတောထွက်ခြင်း။ မြတ်သောတောထွက်ခြင်း။ (Great Renunciation)','“(ဗောဓိသတ်တုန် သီုကဵုဒေံဂမၠိုၚ်ဂှ်) ဂိုၚ်ကေတ်တုဲ ဒဒှ်ဒတိတ်ဇၞော်မပြဲဂှ် တိတ်အာတုဲ လုပ်အာဂြိုပ်ဟေမဝန်တေံရ။” (ဇ—၄၈၈။ အစွောံ။) = “(ဘုရားလောင်းသည် ညီတော်များကိုဆောင်၍) မြတ်သောတောထွက်ခြင်းဖြင့် ဟိမဝန္တာသို့ဝင်၏။” (ညောင်ကန်) || “ယွံဂမှဳတံ၊ ဆလၟုဟ်ဝွံ အဲကျာ်မဂွံတိတ်ဂြိုပ်ဂှ်ဟွံသေၚ်။ ပ္ဍဲကာလအတိက်တေံကီုလေဝ် ဒတိတ်ဇမၞော်ဂှ် အဲသ္ဂောံတိတ်ကၠုၚ်တုဲရ”ကျာ်တြဲဂး။ (ဇ—၅၁ဝ။ အစွောံ။) = “ရဟန်းတို့၊ ယခုအခါ­သာလျှင် ငါဘုရားသည် မြတ်သောတောထွက်တော်မူခြင်းကို တောထွက်တော်မူသည်မဟုတ်သေး။ ရှေး­လည်း မြတ်သောတောထွက်ခြင်းကို တောထွက်တော်မူဘူးသည်သာလျှင်တည်း။” (ညောင်ကန်)')
,(6624,3,1,'၂။ အသက်ကြီးမှ ထွက်၍ရဟန်းပြုသူ။','“ပဟိုတ်ကဵုခမဳဒတိတ်ဇၞော်ၜါဂှ်တုဲ မာလုတဇာတ် ကျာ်တြဲမတွံရ။” (ဇ—၁၇။ အစွောံ။) = “ဤမာလုတဇာတ်ကို — တောထွက်ရဟန်းကြီးနှစ်ယောက်တို့ကို အကြောင်းပြု၍ ဟောတော်မူ၏။” (ညောင်ကန်) || “ဂမှဳဒတိတ်ဇမၞော်မွဲ မနွံယၟုသုဘဒ္ဓ။” (သၠပတ်ဓမ္မသံဂိတိ) = “သုဘဒ္ဓအမည်ရှိသော ကြီးမှရဟန်းပြုသူ ရဟန်းကြီးတစ်ပါး။”')
,(6625,3,1,'အဖြစ်သနစ်။ ဖြစ်စဉ်။ ဖြစ်ကြောင်း။ အကြောင်းရင်း။','“ဒတိတ်ဒဒှ်နူတၞံ မစံၚ်တူတုဲဂှ် မဂွံက္တဵုဒှ်ယဲဂှ် သၟိၚ်ဟီုကဵုဗောဓိသတ်ရ။” (ဇ—၄၆၇။ အစွောံ။) = “မင်းသည် အစမှစိုးရိမ်ပူပန်သဖြင့် ရောဂါဖြစ်ပေါ်လာရသော ဖြစ်စဉ်အကြောင်းရင်းကို ဘုရားလောင်းအား ပြောပြ၏။” || “သၟိၚ်မှာသဳလဝပၠန်တုန်လေဝ် အတိုၚ်ဒတိတ်ဒဒှ်ဇကု နူတံဒဵုကၞတ်ဂှ် ဗွဲတရး ဟီုကဵုသၟိၚ်ဗပုန်ဂှ်ရ။” (ဇ—၅၁။ အစွောံ။) = “မဟာသီလဝမင်းသည် မိမိ၏ဖြစ်စဉ်အကြောင်းကို အစမှအဆုံးတိုင် အကျယ်အားဖြင့် ခိုးသူမင်းအားပြောပြ၏။” || “ဒတိတ်ဒဒှ်သၟတ်ဂှ် ကောန်တၠဟီုညိရ။” (အကြီုရာဇာဓိရာဇ်) = “ထိုသူငယ်၏အဖြစ်သနစ်ကို အရှင့်သားပြောပါလော့။”')
,(6626,3,4,'လွတ်မြောက်စေသည်။ ကယ်ချွတ်သည်။ ကယ်လွှတ်သည်။ ကယ်ထုတ်သည်။','“တၞဟ်နဒတိတ်ဗလးမိ နူဒဒိုက်ဝဋ်သံၚ်သာ မှာထေရ်သာရိပိုတ် တွံဓဝ်ကဵုမိရ။” = “မိခင်အားသံသရာဝဋ်ဆင်းရဲမှ လွတ်မြောက်စေခြင်းငှာ ရှင်သာရိပုတ္တရာသည် မိခင်ကိုတရားဟော၏။” || “တဳလမၞုံကုပိုန် လုကဴ (၇) တ္ၚဲ ပဒတဴပ္ဍဲဍုၚ်သဓီု တွံဓဝ်ဒတိတ်ဗလးသတ်ဗွဲမဂၠိုၚ်။” (ပြကိုဟ်ဂဝမ္ပတိ) = “မြတ်စွာဘုရားသည် (၇) ရက်တိုင်တိုင် သထုံပြည်­ နေတော်မူ၍ များစွာကုန်သောသတ္တဝါတို့အား တရားဟောကယ်ချွတ်တော်မူ၏။” || “သၟတ်ကောန်တြုံသၟိၚ်လေဝ် အဲသ္ဂောံဒတိတ်ဗလးနူသရာံပါပ်ညိ” ဗောဓိသတ်ချပ်။ (ဇ—၅၂၈။ အစွောံ။) = “ထိုမင်းသားကိုလည်း မကောင်းမှုပြုခြင်းမှ လွတ်မြောက်စေအံ့” ဟုဘုရားလောင်းကြံ၏။ || “(ကုသတ်မဒးသ္ၚိစာတ်တံဂှ်) နူကဵုသ္ၚိစာတ် ကဵုအဲဂွံဒတိတ်ဗလးညိ။” (ဇ—ဝေသန္တဝ်။ အစွောံ။) = “အကျွန်ုပ်သည် အကျဉ်းထောင်ကျခံနေရသော သတ္တဝါတို့အား အကျဉ်းထောင်မှ ကယ်လွှတ်ရပါစေသတည်း။” || ‘ပတိတ်ဗလး’ (ကြိ) နှင့်အတူတူ။')
,(6627,3,4,'တွန့်ရှုံ့သည်။',NULL)
,(6628,3,4,'မျက်နှာရှုံ့သည်။ မကြည်သာသည့် သဘောကိုပြသည်။','“(သၟိၚ်ဝေသန္တဝ် မကဵုဒါန်ဂၞကျာ်မဒ္ဒဳ ကုဗမၞးအိန်ဂှ်) ဂၞကျာ်မဒ္ဒဳဟွံဂွံပၞတ် ဟွံဂွံကရောတ် ဟွံဂွံဒတောတ်မုက္ခဝါ—။” (ဇ—ဝေသန္တဝ်။ အစွောံ။) = “ဝေဿန္တရာမင်းက မဒ္ဒီမိဖုရားကို သိကြားပုဏ္ဏားအား ပေးလှူသောအခါ မဒ္ဒီမိဖုရားသည် အမျက်မထွက် မညည်းညူ မျက်နှာမရှုံ့။”')
,(6629,3,1,'၁။ နေထိုင်ရာ။ တည်နေရာ။ ရှိတည်ရာ။','“ညးသ္ပဒတန်ပ္ဍဲဘာဏအ် ဗွဲမလအ်ရ။” =“ဤကျောင်းတွင် သူနေထိုင်သည်မှာ အလွန်ကြာပြီ။” || “တိဗ္ၚမ္ဂးဂှ် ဍေံမဒှ်ဒတန်မတဵုလွဳရ။” =“လယ်မြေမည်သည်ကား စိုက်ပျိုးမှုတည်ရာဖြစ်သည်။” || “တၞံဆုမွဲဂှ် ဍေံမၞုံကဵုဂါပ်ကၞာၚ် ဍေံမစိုန်ဒှ်တဴကေုာံပ္ကဴသတ်တုဲ ဒှ်ဒတန်ဂစေံဂမၠိုၚ်ရ။” (ဇ—၄၃၂။ အစွောံ။) = “တစ်ခုသောသစ်ပင်သည် အခက်အခွနှင့်ပြည့်စုံ၍ အသီးအပွင့်နှင့်တကွ ငှက်များ၏နေထိုင်ရာဖြစ်၏။” || “ပွမဂွံပဒတဴပ္ဍဲဋ္ဌာန်မဒးရး မၞုံကဵုဒတန်သာသနာ။” (ပြကိုဟ်မ္ၚိုလ်ပိစှ်ောဒစာံ) = “သာသနာတော်တည်ရာဖြစ်သော လျောက်ပတ်သောအရပ်­ နေထိုင်ရခြင်း။” || “ဓဝ်သဳလဝွံ ဒှ်ဒတန်သာသနာကျာ်ဂမျိုၚ်ရောၚ်။” (သ္ကေံမိလိန္ဒဝတ္ထု) = “သီလတရားသည် ဘုရားရှင်သာသနာတော်၏တည်မှီရာဖြစ်၏။” || “ဒတန်ဂှ်လေဝ် အပိုၚ်ညးဟွံမွဲဏီ။” (ရာဇာထ္ၜုတ်) = “ဤတည်နေရာ (ဒေသ) သည်လည်း သူတစ်ပါးပိုင်ဆိုင်ခြင်းမရှိသေး။”')
,(6629,3,1,'၂။ တည်တံ့ခြင်း။ တည်ငြိမ်ခြင်း။','“ပၞာန်တၠညးရာဇာဓိရာဇ် ကၠုၚ်တရပ်မံၚ်ဍုၚ်အၚ်ဝ အိုတ်ဂမဳအရဳညးရးနိဂီုဂမၠိုၚ် ဒတန်သမာဓိလေဝ်ဟွံတန်။” (အကြီုရာဇာဓိရာဇ်) = “ဘုရင်ရာဇာဓိရာဇ်၏စစ်တပ်က အင်းဝမြို့ကို အနီးကပ်ဝိုင်းရံထားသဖြင့်အားလုံးသောရဟန်းရှင်လူပြည်သူများသည် စိတ်သမာဓိတည်ငြိမ်ခြင်းကို မရကြကုန်။” || ‘တန်’ (ကြိ) လည်းရှု။')
,(6630,3,1,'ကမ္ဘာတည်သည့်ကာလ။ ကမ္ဘာတည်ခြင်း။','“ခ္ဍာ်ကဵုကၠၚ်ဟိုက်ဒှ်တဴသၞရၚ်သ္ကအ် နူဒတန်ကဝ်တေံဟာ။” = “ကျီးနှင့်ခင်ပုပ်တို့သည် ကမ္ဘာဦးအစကတည်းက ရန်ဘက်ဖြစ်ကြလေသလား။” || “(ပ္ဍဲရနက်ဇၞော်မွဲမွဲဂှ်) ပၟတ်နူဒတန်ကဝ် ဟွံဂွံပၠိုတ်သက်က်ရ။” (ဇ—နေမိ။ အစွောံ။) = “ငရဲကြီးတစ်ခုစီ­ ငရဲမီးတို့သည် ကမ္ဘာတည်ကတည်းကဖြစ်၍ ငြိမ်းခြင်းအလျှင်းမရှိ။”')
,(6631,3,1,'စိတ်ငြိမ်ခြင်း။ စိတ်တည်ငြိမ်ခြင်း။ သမာဓိ။','“သတ်တၠလောဘရောၚ် ဒတန်စိုတ်ညိကီု တန်ဟွံဂွံ၊ စိုတ်ဒးချဳတဴလၟိုန်ဟေၚ်။” (သၠပတ်သတိပထာန်) = “လောဘကြီးသောသတ္တဝါသည် အနည်းငယ်မျှသော စိတ်တည်ငြိမ်ခြင်းကိုမရ၊ စိတ်သည် အမြဲလှုပ်ရှားနေရ၏။” || “မွဲခဍတ်တဲ၊ တဝှဲပၞိက်ရ။ ဒတန်စိုတ်ဂှ်၊ ဟွံသၟဟ်ရထ။” (လိက်တလိၚ်ပန်) = “တစ်လက်ဖျစ်တီးတစ်ယပ်ခတ်မျှလည်း စိတ်၏တည်ငြိမ်ခြင်းကိုမရ။”')
,(6632,3,1,'သာသနာတော်တည်ရာ။ သာသနာထွန်းကားရာ။ သာသနာတည်ခြင်း။','“ထာန်ဝွံ အနာဂတ်သဒှ်ဍုၚ်မွဲ — မသ္ဂောံဒှ်ဒတန်သာသနာမ္ဂးဂှ် မူကာလရော။” (ရာဇာထ္ၜုတ်) = “ဤအရပ်သည် အနာဂတ်­ မြို့တစ်မြို့ဖြစ်၍ သာသနာတော်ထွန်းကားရာဖြစ်မည်ဆိုသည်မှာအဘယ်ကာလပါနည်း။”')
,(6633,3,1,'သက်တမ်း။',NULL)
,(6634,3,1,'တက်ခြင်း။ တင်မြှောက်ခြင်း။','‘တိုန်’ (ကြိ) လည်းရှု။')
,(6635,3,1,'ကျက်သရေတိုးခြင်း။ ဂုဏ်သရေတက်ခြင်း။','“ပ္ဍဲဝေလုဝိုန်၊ ဒတိုန်စရာဲ။ ဘာသၟိၚ်မပြဲ၊ ကျာ်တြဲဓလာဲ။” (လိက်ဇမ္ဗူပတိ။ မာံဒေံဍောတ်။) = “မင်းပေးလှူသော ဂုဏ်ကျက်သရေတက်သော ဝေဠုဝန်ကျောင်းတော်ဝယ် မြတ်စွာဘုရားစံတော်မူ၏။”')
,(6636,3,1,'တက်နေ။ နေတက်ခြင်း။','“လျးယာတ်ဂှ် ဂဵုလဟဵုတဴ ညံၚ်ရဴလျးဒတိုန်တ္ၚဲကီုမဒှ်ရ။” (ဇ—၅၂၇။ အစွောံ။) = “ထိုအဝတ်သည် တက်သစ်သောနေရောင်ခြည်ကဲ့သို့ ထွန်းတောက်၏။” || “(သၟိၚ်) သ္ဍိုက်မၠိုက်လောန်ထောန်၊ ပ္ဍဲကောန်တ္ၚေက်ဗၠာဲ။ သၟဟ်ဒတိုန်တ္ၚဲ၊ အဝဲစရာဲ။” (လိက်ကောန်သၟိၚ်ပိ။ မာံခစုန်အံက်။) = “တက်နေပမာ ကိုယ်အင်္ဂါအသရေရှိသောကျေးသားကိုမင်းသည် အလွန်တရာချစ်နှစ်သက်၏။” || “ဒိုဟ်ဒတိုန်တ္ၚဲ။” (လိက်ပဒုမ္မဝတဳ) = “နေတက်ရာအရပ်မျက်နှာ။”')
,(6637,3,1,'စန်းထခြင်း။ အကျိုးပေးသည့်ကံ။','“စသ္ကဂတဒိုဟ်ပလိုတ် ဒတိုန်တွိုန်ဟွံမွဲရ၊ကၠောန်စဟွံတိုန်။” (သၠပတ်ဒ္ၚောဝ်သၜောံ) = “အနောက်အရပ်သို့ မျက်နှာမူ၍ တံပူစား (သွားတိုက်) သောသူအား စန်းထခြင်းမရှိ၊ လုပ်စား၍စီးပွားမဖြစ်။”')
,(6638,3,1,'နုပျိုသောအရွယ်။','“ကောန်ပိုဲၜါဝွံဂှ် ဃောဒတိုန်ဗၠာဲ ဃောဝေၚ်ဂြိုၚ်ကျိုၚ်ကျဝ် ဃောစသိုၚ်အရီုရောၚ်။” (ဇ—၅၃၂။ အစွောံ။) = “ငါတို့၏သားနှစ်ယောက်တို့သည် နုပျိုတုန်းအရွယ်ဖြစ်၏။ ဝတ်စားဆင်ယင် ကစားရွှင်တုန်းအရွယ်ဖြစ်၏။ ကာမဂုဏ်အာရုံကို ခံစားအပ်တုန်းအရွယ်ဖြစ်၏။” || “ဃောဒတိုန်ဗၠာဲ၊ ဃောဂၠာဲမိတ်ပြဝါ။” (လိက်ပထမဗောဓိ။မၚ်ဍိက်လ။) = “နုပျိုတုန်းအရွယ် ကြင်ဖော်ရှာတုန်းအရွယ်။” || “ယွံသၟိၚ်မပြဲ၊ တၠအဲဃောဒတိုန်တွိုန်ဗၠာဲ မဂပ်ဂဝ်ဗဵုဒ္ၚေါဝ် မဂပ်ဂဝ်ရာၚ်ဆာဲရောၚ်အဴ။” (ဇ—၄၁၁။ အစွောံ။) = “မင်းမြတ်၊သင်မင်းကြီးသည် ပျိုနုတုန်းဖြစ်၍ ရှုချင်စဖွယ် တင့်တယ်လှပေ၏။”')
,(6639,3,1,'ဘုန်းကံတက်ခြင်း။','‘ဗြဴဒတိုန်ဘက်။’ (လိက်ဗောဓိသတ်စှ်။ ပဏ္ဍိတ။) = ‘ဘုန်းကံရှင်မိန်းမ။ ဘုန်းကံတက်သောမိန်းမ။’ || “တြုံဒတိုန်ဘက်။” (လိက်သောဝါနနဟောၚ်) =“ဘုန်းကံရှင်ယောကျာ်း။” || ‘ဘက်’ (န) လည်းရှု။')
,(6640,3,1,'အရုဏ်တက်ချိန်။ အရုဏ်တက်ခြင်း။','“ပ္ဍဲပယာံဒတိုန်အရှိုန်—။” (ဇ—၁၉၃။ အစွောံ။) = “အရုဏ်တက်ချိန်­—။” || “ခမဳမသုန်ကၠံဂှ် ဂွံဒှ်အရှန်တုဲ ပ္ဍဲပယာံဒတိုန်အရှိုန်ဂှ် သီုခမဳမသုန်ကၠံဂှ် ကလာၚ်ပေက်စဴကၠုၚ် ဘာဝေဠုဝိုန်ရ။” (ဇ—၁၁။ အစွောံ။) = “ထိုရဟန်းငါးရာတို့သည် ရဟန္တာဖြစ်ပြီးနောက် အရုဏ်တက်သောအခါ­ ဝေဠုဝန်ကျောင်းတော်သို့ ကောင်းကင်ခရီးဖြင့် ပြန်ကြွလာကြကုန်၏။”')
,(6641,3,1,'‘ဂတိုပ်’ ရှု။',NULL)
,(6642,3,1,'‘ဂတိုပ်မတ်’ ရှု။',NULL)
,(6643,3,4,'ကျသည်။ လဲကျသည်။ ပြုတ်ကျသည်။','“သတ်ကြုက်လၟုဟ်ဂှ် ပြဟ်ဒတုံစှ်ေတိရ။” = “သရက်သီးမှည့်သည် မြေခကြွေကျခဲ့သည်။”')
,(6644,3,1,'အထူ။ အထု။ အစု။','‘သတီု’ ရှု။ || “ဒတီုဗဵုပၞာန်တြဴဍုၚ်ဂှ် ဗပေက်ကၠေံတုဲ သၟိၚ်တြဴက္ဍိုၚ်ဗ္တာၚ်ဂှ် ဂွံကေတ်ဂျိုၚ်ၚ်ရ။” (ဇ—၂၄။ အစွောံ။) = “ခြောက်ခုသောဗိုလ်စုကို ဖျက်ဆီး၍ ခြောက်ယောက်သောမင်းတို့ကို (အရှင်) ဖမ်း၏။” (ညောင်ကန်)')
,(6645,3,1,'အကျိုး။ ပြီးစီးခြင်း။ ပြီးမြောက်ခြင်း။','‘တုဲ’ (ကြိ) လည်းရှု။ || “တြုံဂှ်မၞုံကဵုလွဳဂှ် ဂွံညာတ်ဒတုဲလွဳရ။” (ဇ—မှာဇနက်။ အစွောံ။) = “လုံ့လရှိသောယောကျာ်းသည် လုံ့လ၏အကျိုးကို မြင်ရ၏။” || “ကာလယဲက္ဍၚ် သၟိက်ဂွံပ္ကောံဂဥုဲ အိုတ်ပွအိုဿီုဝွံ ဟွံဂွံဒှ်ဒတုဲကိစ္စသက်က်ရ။” (ဓမ္မဒေသနာ။ မာံရွှေငိုး။) = “ရောဂါသည်းသောအခါမှ ဆေးဖော်စပ်ခြင်း ဤအပြုအမူအားလုံးတို့သည် အလုပ်ကိစ္စပြီးမြောက်ခြင်း မဖြစ်နိုင်။”')
,(6646,3,1,'အကျိုးအမြတ်။','“ကလောန်ဂှ် မူဒတုဲကၟဝ်ဍေံနွံရော။” = “ထိုအလုပ်သည် ဘာအကျိုးအမြတ်ရှိသနည်း။”')
,(6647,3,1,'၁။ အတတ်ပြီးမြောက်ခြင်း။','အာစိုပ်ဒတုဲကွတ် = အတတ်ပညာအပြီးသို့ရောက်သည်။')
,(6647,3,1,'၂။ အတတ်ပညာ၏အစွမ်းသတ္တိ။','“ညးကၠောန်ခိုဟ်ကီု ဟွံခိုဟ်ကီု ပ္ဍဲဒတုဲကွတ်အိုဿီုဂှ်အ္စာမပြဲတံဂှ် ညးတီရောၚ်။” (ဇ—၃၈၇။ အစွောံ။) = “ကောင်းစွာလုပ်သည်ကို၄င်း မကောင်းစွာလုပ်သည်ကို၄င်း အတတ်ပညာ၏အစွမ်းသတ္တိကို မြတ်ကုန်သောဆရာတို့သည် သိကုန်၏။”')
,(6648,3,1,'စိတ်အလို။ စိတ်အကြံအစည်။','“ယွံတဳလမၞုံပိုန်၊ ပိုဲဍိက်အာဗၞိက်ဝွံဂှ် — ပိုဲကလေၚ်စဴလေဝ် ကဵုဍိုက်ပေၚ် ကဵုစိုပ်ဒတုဲစိုတ်ပိုဲဍိက်ညိအဴ။” (ဇ—၂၅၆။ အစွောံ။) = “ဘုန်းတော်ကြီးသော အရှင်ဘုရား၊ တပည့်တော်တို့သည် ကုန်သွယ်ရန်သွားအံ့။ ပြန်သောအခါ­လည်း တပည့်တော်တို့၏ စိတ်အလိုပြည့်စုံပြီးမြောက်ခြင်းသို့ ရောက်ပါစေသတည်း။” || “လၟုဟ်ဝွံ ဍိုက်ပေၚ်ကဵုဒတုဲစိုတ်ပိုဲတုဲရ။” (ဇ—၂၅၆။ အစွောံ။) = “ယခုအခါ ငါတို့၏စိတ်အကြံအစည် ပြည့်စုံပေပြီ။” || “ဟိုတ်မပလွဳဂှ် မဂွံအာစိုပ်ဒတုဲစိုတ်ဇကု မဂွံဗၠးဒဒိုက်တုဲ မကလိဂွံတသိုက်—။” (ဇ—၅၂။ အစွောံ။) = “လုံ့လပြုခြင်းကြောင့် မိမိစိတ်အလိုပြီးမြောက်ခြင်းသို့ရောက်၍ ဒုက္ခမှလွတ်မြောက်သဖြင့် ချမ်းသာကိုရရှိ၏။” || “အတိုၚ်ဒတုဲစိုတ်အဲ သၟိက်ဂွံဒှ်သၟိၚ်ဂှ် အဲဂွံဒှ်သၟိၚ်ကွေံရ။” (ဇ—မှာဇနက်။ အစွောံ။) = “ဘုရင်ဖြစ်လိုသော ငါ၏စိတ်အလိုအတိုင်းပင် ငါတကယ်ဘုရင်ဖြစ်ခဲ့ပြီ။” || “ယွံသၟိၚ်မပြဲ၊ ညံၚ်ပၟိက်ဒတုဲစိုတ်မရာတ်ဂှ် စိုပ်ဒတုဲတုဲရ။” (ဇ—စန္ဒကုမာ။ အစွောံ။) = “မြတ်သောမင်းကြီး၊ အရှင်မင်းကြီး၏စိတ်အလိုသည် အပြီးသို့ရောက်ခဲ့ပြီ။”')
,(6649,3,4,'လူသားကောင်းကျိုး။ လူ့ကောင်းကျိုး။','‘ပညာဒှ်တၟုဲ ပညာနွံတုဲ ဒှ်ဒတုဲဇန်။’ (လောကသိဒ္ဓိ။ အစွောံ) = ‘ပညာသည် အနှစ်သာရဖြစ်၏။ ပညာရှိက လူ့ကောင်းကျိုးအတွက် အကျိုးပြုနိုင်၏။’ || “ညးမရၚ်တၠုၚ်သွက်ဒတုဲဇန်တံဂှ် ဒှ်သၟာပရဟိတအိုတ်ရ။” = “လူသားကောင်းကျိုးအတွက် အကျိုးဆောင်သောသူတို့သည် ပရဟိတသမားများဖြစ်ကြသည်။” || “လမေတ်လိုက်ဗာ၊ ဗတ်ဝေါဟာမန်။ သွက်ဒတုဲဇန်၊ ပ္ဍဲရးမည။” (လိက်ဓနဥ္ဇယျကုမ္မာ။ အစွောံ။) =“လောကအဆုံးအမစာကို မွန်ဘာသာဖြင့် ရာမညတိုင်း­ လူ့ကောင်းကျိုးအတွက် စီကုံးထားရှိ၏။”')
,(6650,3,1,'အကျိုး။ ကောင်းကျိုး။','“အဲရဂွံအာကၠာမ္ဂး ဂၠံၚ်တြဴလေဝ် ဟွံဂတာပ်လီုဏီ၊ဍာ်အှ်ောသဏေဝ် ပိုဲဟွံဒိုက်ရ၊ အနှေန်ဗၞိက်လေဝ် သ္ဂုတ်သွာတ်ပ္တိုန်ဖျေံ ညံၚ်စိုတ်ပိုဲဂှ် ဂွံသွံစရ၊ ပ္ဍဲမအာကၠာဝွံဂှ် ဒတုဲဖဵုဂၠိုၚ်သန်” ညးဗၞိက်သမၠီုချပ်။ (ဇ—၁။ အစွောံ။) = “ငါသည် ရှေ့မှသွားသည်ရှိသော် မပျက်သည်သာလျှင်ဖြစ်သောခရီးဖြင့် သွားရအံ့။ ရေ၊ ထင်း၊ ဟင်းရွက်စသည်လည်း ရရန်မခက်လတ္တံ့၊ ကုန်ဈေးနှုန်းလည်း အလိုရှိတိုင်း အဘိုးသတ်မှတ်၍ ရောင်းရလတ္တံ့။ရှေ့မှသွားခြင်း­ များစွာသောအကျိုးရှိ၏” ဟုလှည်းကုန်သည်မိုက်ကြံ၏။ || ‘ဂလာန်ဒတုဲဖဵုကုသဵု။’ (ဇ—၁၃၈။ အစွောံ။) = ‘ကုသိုလ်အကျိုးနှင့်စပ်သောစကား။’ || “(ပွမစံၚ်ပူဇဴပၟတ်ယတ်ဂှ်) မူဒၞာဲဖဵုနွံရော။ ဒတုဲဖဵုဟွံမွဲရ။” (ဇ—၁၆၂။ အစွောံ။) = “မီးပူဇော်ခြင်းသည် အဘယ်အကျိုးရှိအံ့နည်း။ကောင်းကျိုးမရှိ။” || “ယွံသေဋ္ဌဳ၊ တၠအဲပ္တုဲဒါန်ဂှ် မူဒတုဲဖဵုမွဲမွဲ တၠအဲမရာဒနာမိက်ဂှ်ရော။” (ဇ—၃၄ဝ။ အစွောံ။) = “သူဋ္ဌေးကြီး၊ သင်အလှူပေးသည်မှာ အဘယ်အကျိုးကို လိုချင်တောင့်တလေသနည်း။”')
,(6651,3,1,'အကျိုးစီးပွား။ ကောင်းကျိုး။','“တၞဟ်နဒတုဲမြမောဝ်ညးဍုၚ်ရးဟံၚ်သာဝတဳတအ်ညးဂမၠိုၚ် ကျာ်ဇၞော်အစွောံ ခၞံဗဒှ်လဝ်လိက်ဘာသာမန် ဗွဲမဂၠိုၚ်ရ။” = “ဟံသာဝတဳပြည်သားများ၏ အကျိုးစီးပွားအလို့ငှာ ဝေါဆရာတော်သည် မွန်ဘာသာစာပေများစွာကို ပြုစုစီရင်ခဲ့၏။” || “အဲ (ဇက်ပၞာန်) သ္အာလၟုဟ်ဝွံဂှ် ဒှ်ဒတုဲမြမောဝ်ကီု ဒှ်လဟုတ်ကီု ကျာ်တြဲမတီရောၚ်” သၟိၚ်ချပ်။ (ဇ—၁၇၆။ အစွောံ။) = “ယခုငါစစ်ချီထွက်ရာ­ အကျိုးစီးပွားဖြစ်ခြင်းကို၄င်း အကျိုးယုတ်ခြင်းကို၄င်း မြတ်စွာဘုရားသည် သိတော်မူလတ္တံ့” ဟုမင်းကြံ၏။')
,(6651,3,4,'အကျိုးပြုသည်။ အကျိုးစီးပွားကိုဖြစ်စေသည်။','“ယွံခမဳတံ၊ အဲဒတုဲမြမောဝ်ဟံၚ်ပြာ်ညးၜါဝွံဂှ် ဆလၟုဟ်ဟွံသေၚ်၊ ပ္ဍဲကာလအတိက်တေံလေဝ် အဲဂွံဟံၚ်ပြာ်ညးၜါဝွံတုဲရ” ကျာ်တြဲဂး။ (ဇ—၁၂။ အစွောံ။) = “ရဟန်းတို့၊ငါဘုရားသည် ယခုအခါ­သာလျှင် ဤနှစ်ယောက်ကုန်သောသူတို့၏ အကျိုးစီးပွားကိုဖြစ်စေ၍ကယ်တော်မူသည်မဟုတ်သေး၊ ရှေး­လည်း ကယ်ဖူးးသည်သာလျှင်တည်း။”')
,(6652,3,1,'လောကကောင်းကျိုး။','“ညးမရၚ်တၠုၚ်ဒတုဲဇန် ဒတုဲလိုက်တံဂှ် ဒှ်ညးမပြဲရ။” =“လူသားကောင်းကျိုး လောကကောင်းကျိုး သယ်ပိုးဆောင်ရွက်သူတို့သည် သူမြတ်များဖြစ်၏။”')
,(6653,3,1,'ဆိုးကျိုး။ အကျိုးမဲ့။','“ပူဂဵုသမၠီုမ္ဂးဂှ် ဍေံမဇၞော်ပၟဝ်ကဵုဒတုဲလေၚ်ဇကုရောၚ်။” (ဇ—၄ဝ၄။ အစွောံ။) = “သူမိုက်မည်သည်ကား မိမိ၏အကျိုးမဲ့ကိုသာ ပွားစေ၏။”')
,(6654,3,1,'လုံ့လ၏အကျိုးကျေးဇူး။',NULL)
,(6655,3,1,'ဆွေမျိုးစဉ်ဆက်။ အဆက်အနွယ်။','“ဗဗွဲလွေၚ် အလုံဂကူဂှ် အာစိုပ်ပလိုက်တုဲဒတောဝ်သ္ဂုတ်အာ။” (ဇ—၁၃၇။ အစွောံ။) = “ဤသို့အစဉ်သဖြင့် ထိုအမျိုးသည် ပျက်စီးခြင်းသို့ရောက်၏။ အနွယ်သည်ပြတ်၏။” (ညောင်ကန်) || “မကဵုမ္ၚဵုစိၚ်သၟိၚ်မ္ဂးဝွံ ဒဵုကဵုထပှ်ဒတောဝ်တၞောဝ်ပိုဲမကြက်ကၠုၚ်ရောၚ်။” (ဇ—၁၆၃။ အစွောံ။) = “မင်း၏ဆင်မင်္ဂလာပြုခြင်းမည်သည်ကားအမျိုးခုနစ်ဆက်တိုၚ် ငါတို့၏အနွယ်သည် မပြတ်ဆက်လာခဲ့၏။”')
,(6656,3,4,'အဆက်ဆက်စုံစမ်းသည်။','“ယွံသၟိၚ်တ္ၜိုၚ်ထဝ်၊ — (အဲ) သၟာန်ဒတောဝ်ဗက်ကၠုၚ်တုဲ မဂွံကၠုၚ်စိုပ်ဒမံၚ်သၟိၚ်တ္ၜိုၚ်ထဝ်ဒၞာဲဝွံရ” သၟိၚ်ဂး။ (ဇ—၄၈၂။ အစွောံ။) = “အသင်ရွှေဆတ်မင်း၊ အဆက်ဆက်မေးမြန်းစုံစမ်းလာ၍ သင်၏ဤနေရာအရပ်သို့ ငါရောက်လာပါ၏” ဟုမင်းဆို၏။ || “ဒတောဝ်ဗက်ဂၠာဲ၊ ဒၞာဲဇိုၚ်အရာ။” (လိက်ကောန်သၟိၚ်ပိ။ မာံခစုန်အံက်။) = “ခြေရာစဉ်အတိုင်း အဆက်ဆက်စုံစမ်းရှာ၏။”')
,(6657,3,4,'ရန်ငြိုးဖွဲ့သည်။','“ပွမဒတောဝ်ဝဲကဵုရၚ်သ္ကံဂှ် ဟွံဂပ်ဂဝ်သဒှ်ဟေၚ်။” (ဇ—၅၃၆။ အစွောံ။) = “အချင်းချင်းရန်ငြိုးဖွဲ့ခြင်းသည် မဖြစ်သင့်။” || “ဣသိစဏာဲဝွံ အဲဟွံဂွံကဵုစကၠာသွံ။ တိရစ္ဆာန်ရောၚ် မကဵုစကၠာသွံ” ကောန်သၟိၚ်ချပ်တုဲ ဒတောဝ်ဝဲရ။ (ဇ—၇၃။ အစွောံ။) = “ဤရသေ့စဉ်းလဲသည် ငါ့ကို အလျင်မကျွေးဘဲ တိရစ္ဆာန်ကို အလျင်ကျွေး၏” မင်းသားကြံ၍ ရန်ငြိုးဖွဲ့၏။ || “ပြောဟိတ်တံဝွံဂှ် ညးမၞုံကဵုဣဿရအဝဵုအသဳရောၚ်။ ညးမၞုံကဵုဣဿရတံဝွံဂှ် ညးဂၠာဲဒတောဝ်လဝ်ဝဳဝဲရောၚ်။” (ဇ—၁၄ဝ။ အစွောံ။) = “ပုရောဟိတ်တို့မည်သည်ကားအာဏာရှိသူများဖြစ်ကုန်၏။ အာဏာရှိကုန်သောသူတို့သည် ရန်ငြိုးဖွဲ့တတ်ကြကုန်၏။” || “တဳလလ္ပဒတောဝ်ဝဳဝဲကဵုအဲဍိက်ညိရအဴ။” (ဇ—၄၂၅။ အစွောံ။) = “အရှင်ဘုရား၊ တပည့်တော်မအား ရန်ငြိုးမဖွဲ့ပါနှင့်။” || ‘သတောဝ်ဝဲ’ ဟုလည်း အချို့ရေးသည်။')
,(6658,3,4,'ထုသည်။',NULL)
,(6659,3,1,'ဖထိုင်။ ထိုင်စရာဖုံ။ (?) (ပါဠိ—ကောစ္ဆ)',NULL)
,(6660,3,6,'ပိုင်ဆိုင်ခြင်းကိုပြသောစကားလုံး။ ၏။','“ပ္ဍဲဇရေၚ်ဒဒက်တဴရသိ။” (ရာဇာဝံသကထာ) = “ရသေ့၏အထံ­။” || “ဗုဒ္ဓဿ၊ ဒဒက်တဴကဵုကျာ်။ ဝစနံ၊ ၚ်ဂလာန်တဝှ်ကျာ်။သစ္စံ၊ ဒှ်စၟတ်ဨကန္တရ။” (လိက်သၚ်္ခါရလိုက်) = “မြတ်စွာဘုရား၏ ဟောကြားအပ်သောတရားတော်သည် ဧကန္တမှန်ကန်၏။”')
,(6661,3,1,'ယုတ်ခြင်း။ နည်းခြင်း။','‘ဗွဲဒဒေက်/ဗွဲတဒေက်’ (ကြိဝိ) လည်းရှု။')
,(6662,3,1,'ဒုက္ခ။ ဆင်းရဲခြင်း။',NULL)
,(6663,3,1,'စိတ်ဆင်းရဲခြင်း။ စိတ်ဒုက္ခ။','“(ယွံကောန်ဗြဴ၊ သၟိၚ်ဟွံဒးဂၞပ်တုဲ) မဒးမံၚ်ပ္ဍဲသ္ၚသၟိၚ်ဝွံ ဒဒိုက်ပရိုက်စိုတ်ဇၞော်ဟေၚ် မဒးဒှ်ရ။” (ဇ—၂၂၃။ အစွောံ။) = “ချစ်သမီး၊မင်းသည် မိမိအားမနှစ်သက်ပါက မင်းအိမ်­နေခြင်းသည် ကြီးစွာသောစိတ်ဆင်းရဲခြင်းဖြစ်ရာ၏။”')
,(6664,3,1,'ဆင်းရဲဒုက္ခ။','“မိအဲဟွံဂွံစအဟာတုဲ သီုကဵုဒဒိုက်သၞာဂှ်ဒှ်တုဲ မဒးကၠောဝ်အဟာဗျဵုထၚ်တုဲ မဒးပကာဂစိုတ်ရသွံ” သၟိၚ်စိၚ်ဂး။ (ဇ—၄၅၅။ အစွောံ။) = “ငါ၏မိခင်သည် အစာအာဟာရကို မရလေသဖြင့် ဆင်းရဲဒုက္ခဖြင့် ဆာလောင်ငတ်မွတ်၍ သေရလေတော့မည်တကား။”')
,(6664,3,1,'ဆင်းရဲဒုက္ခ။','“တြုံကၠောန်နၚ်ကီု၊ သီုဒဒိုက်သၞာ။ ဗြဴတအ်ရပ်ပၠေၚ်၊ ဝေၚ်ဂြိုၚ်အိုတ်အာ။” (လိက်သၠပတ်သၟိၚ်ပဿိုန်) = “ဆင်းရဲငြိုငြင်သဖြင့် လင်အလုပ်လုပ်၍ရလာသည်ကို မယားတို့က ပျော်ပါးဖြုန်းတီးပစ်ကုန်၏။”')
,(6665,3,1,'တံတား။','ဒဒန်ဆု = သစ်တံတား။')
,(6666,3,1,'ဖြစ်ခြင်း။ အဖြစ်။ အကြောင်း။','ဒဒှ်မဗျု = အိုခြင်း။ || ဒဒှ်စိုတ်မဂၠိၚ် = စိတ်ရှည်ခြင်း။ || ဒဒှ်မတီ = သိခြင်း။ သိသည်၏အဖြစ်။ || ဒဒှ်မဆာန်ကၟိန် = ချစ်ခြင်း။ ချစ်သည်၏အဖြစ်။ || ဒဒှ်ကျာ် = ဘုရားအဖြစ်။ || ဒဒှ်သမ္ဘာ = မယားအဖြစ်။ || “ဒဒှ်အဲယဲ ညးဟွံတီရ။” = “ကျွန်တော်ဖျားနေကြောင်း သူမသိပါ။” || “ဒဒှ်ဂှ် လဴထ္ၜးကဵုညးညိ။” = “ထိုအကြောင်းကို သူ့အားပြောပြပါ။” || ‘ဒှ်’ (ကြိ) လည်းရှု။')
,(6667,3,1,'၁။ လူ၏အဖြစ်။',NULL)
,(6667,3,1,'၂။ လူဖြစ်ခြင်း။ မွေးဖွားလာခြင်း။','“(ဗောဓိသတ်) ပၟတ်ဂဝ်နူဒဒှ်မၞိဟ်ဂှ် ဂိုၚ်ကေတ်တုဲ လုပ်အာဂြိုပ်ရ။” (ဇ—၁၄၄။ အစွောံ။) = “ဘုရားလောင်းသည် ဖွားသောနေ့မီးကိုယူ၍ တောသို့ဝင်သွား၏။”')
,(6668,3,4,'၁။ သိကျွမ်းသည်။ ယဉ်ပါးသည်။ ရင်းနှီးကျွမ်းဝင်သည်။ ခင်မင်ရင်းနှီးသည်။','“အဲဒဒှ်ေဒၟံၚ်ကဵုအ္စာဘာဂှ်ရ။” = “ထိုကျောင်းဆရာနှင့် ကျွန်တော်ခင်မင်ရင်းနှီးသည်။” || “ဗောဓိသတ်တုန် သတ်ဝိဂှ် ကဵုဒကောတ်ဂှ်စရ။ ဒကောတ်ဂှ် ဒဒှ်ေအာကဵု (ဗောဓိသတ်) ။” (ဇ—၁၉၃။ အစွောံ။) = “ဘုရားလောင်းသည် ထိုဖွတ်အား ရေသဖန်းသီးကို ကျွေး၏။ ထိုဖွတ်သည် ဘုရားလောင်းနှင့် အကျွမ်းဝင်သွား၏။”')
,(6668,3,4,'၂။ ခင်မင်ရင်းနှီးအောင်ပြုသည်။ ယဉ်ပါးအောင်လုပ်သည်။','“မၚ်ဗၠာဲမွဲဂှ် တိတ်ဂၠာဲၚဳအှ်ော ပ္ဍဲဂြိုပ်သုသာန် ညာတ်စာၚ်မွဲ ရပ်ဖျဴကြိုင်ဒဒှ်ေလဝ်ရ။” (ဇ—၁၁၉။အစွောံ။) = “တယောက်သောလုလင်ငယ်သည် သုသာန်တော­ ထင်းခွေလတ်သော် တခုသောကြက်ကိုမြင်၍ ဆောင်ခဲ့ပြီးလျှင် ချိုင့်­ (လှောင်) ထား၍ (ယဉ်ပါးအောင်) မွေး၏။” (ညောင်ကန်) || “လမာဲမွဲဂှ် ဍေံဒဒှ်ေလဝ်ကၞုဲမွဲရ။” (ဇ—၃၆၅။ အစွောံ။) = “တစ်ယောက်သောအလမ္ပာယ်သည်တစ်ခုသောမျောက်ကို ယဉ်ပါးအောင်သင်ထား၏။”')
,(6668,3,1,'ခင်မင်ရင်းနှီးမှု။ အသိအကျွမ်း။ အသိမိတ်ဆွေ။','“အမူသၟတ်ဗြဴဂှ် ဒဒှ်ေအဲရ။” = “ထိုသူငယ်မ၏ဦးလေးသည် ငါ၏အသိအကျွမ်းဖြစ်သည်။”')
,(6669,3,1,'ရင်းနှီးခြင်း။ အကျွမ်းဝင်ခြင်း။ အသိမိတ်ဆွေ။','“(ကၠဵုစၞာဲဂှ်) သ္ပဒဒှ်ေဒယှ်ကဵုသတ် မပ္တေဟ်ဇကုတုဲ ကြဴဝွံရပ်ဂစိုတ်စကၠေံရ။” (ဇ—၁၂၈။ အစွောံ။) = “ထိုမြေခွေးစဉ်းလဲသည် မိမိကိုယုံသောသတ္တဝါနှင့် အကျွမ်းဝင်ခြင်းကိုပြုပြီး ထိုနောက်­ ဖမ်း၍သတ်စား၏။”')
,(6669,3,4,'ရင်းနှီးသည်။ အကျွမ်းဝင်သည်။ ပေါင်းဖော်သည်။','“ပ္ဍဲဗြဴကမၠောန်ပ္ဍဲသ္ၚိသၟိၚ်ဂှ် အမာတ်ဒဒှ်ေယှ်ဏှဴရဴအာရ။” (ဇ—၁၉၅။ အစွောံ။) = “ထိုအမတ်သည် နန်းတွင်းသူတစ်ယောက်နှင့် အကျွမ်းဝင်ရောနှော၏။” || “ၜိုပ်ဗၠာဲၜါ ဂ္ၚေၚ်အာဂၠာဲစ ပ္ဍဲလစဂှ်တုဲ ဒဒှ်ေယှ်အာကဵုကၞုဟ်ရ။” (ဇ—၂၁၅။ အစွောံ။) = “ဟင်္သာငယ်နှစ်ခုတို့သည် ထိုအိုင်­ အစာရှာလှည့်သည်ရှိသော် ထိုလိပ်နှင့်တကွ အကျွမ်းဝင်သွား၏။”')
,(6670,3,5,'ခင်မင်ရင်းနှီးသောအားဖြင့်။ အကျွမ်းဝင်သောအားဖြင့်။','“တၠကေတ်ဒြပ်အဲဂှ် မူပဟွံပ္တီအဲရော” ဥပဇ္ဇျာဲဂး။ “အဲကေတ်ဗွဲဒဒှ်ေယှ်ရောၚ်” ခမဳဂှ်ဂး။ (ဇ—၁၉၇။အစွောံ။) = “ငါ့ကိုအသိမပေးဘဲ ငါ့ဥစ္စာကို အဘယ်ကြောင့်ယူသနည်း။” “အကျွန်ုပ်သည်အကျွမ်းဝင်သောအားဖြင့် ယူပါ၏။” || “ဝေၚ်ဒဒိုဟ်ရၚ်သ္ကအ်။” = “စကားထာဝှက်တမ်းကစားသည်။” || ဂလာန်ဂဒိုဟ် = စကားထာ။')
,(6671,3,3,'အထွေးဆုံးဖြစ်သော။','ကောန်ဒဒေအ် = အထွေးဆုံးသားသမီး။')
,(6672,3,1,'‘ဂဒိုအ်’ ရှု။',NULL)
,(6673,3,10,'(န) နို့ဓမ်း။ နို့ချဉ်။ ဒိန်ခဲ။',NULL)
,(6674,3,4,'‘ဒၞာ’ ရှု။',NULL)
,(6675,3,1,'‘ဒၞး’ ရှု။',NULL)
,(6676,3,1,'ကျော့ကွင်း။ ထောင်ချောက်။','ပံါဓနက် = ကျော့ကွင်းထောင်သည်။ || ပးဒနက် = ကျော့ကွင်း။')
,(6676,3,4,'ကျော့ကွင်းထောင်ဖမ်းသည်။','“လၟဂမၠိုၚ်ဒနက်မြာ်ထဝ် ကေတ်ဟွံဂွံ။” (သၠပတ်ဒ္ၚောဝ်သၜောံ) = “မုဆိုးများသည် ရွှေဥဒေါင်းအား ကျော့ကွင်းထောင်ဖမ်း၍မမိ။”')
,(6677,3,1,'တလင်း။ ကောက်နယ်တလင်း။ (ပါဠိ—ခလ/ဓညကာရဏ)','‘ဒြာၚ်’ လည်းရှု။')
,(6678,3,1,'ဒညင်းသီး။',NULL)
,(6679,3,16,'‘ဂၞံၚ်ဂၞာတ်’ ရှု။',NULL)
,(6680,3,1,'‘ဒၞန်’ ရှု။',NULL)
,(6681,3,4,'မိုက်ရိုင်းသည်။ လူပါးဝသည်။','“(ယွံဝိဓူရ) ပဟွံလ္ၚောဝ်၊ လမျီုဆောဝ်ပါန်။ ဟွံပၠောတ်သိသ၊ ပါဒသဗာန်။ မူဟိုတ်စံၚ်မာန်၊ ဒနာန်ဒှ်ရော။” (လိက်ဝိဓူရ) = “ဟယ်ဝိဓူရ၊ ငါ့ခြေဖဝါးအောက်တွင် အဘယ်ကြောင့်ဦးမချမဝပ်စင်းဘဲ ငါ့ကိုမရှိခိုးဘဲ သင့်အသက်ချမ်းသာရန်အသနားမခံမတောင်းပန်ဘဲ မာန်စောင်တက်၍ မိုက်ရိုင်းလေသနည်း။” (နဂါးမင်းဆို၏။)')
,(6682,3,1,'ဘိနပ်။ ခြေနင်း။','လိုန်ဓနပ် = ဘိနပ်စီးသည်။ || ဒၞပ်မွဲဂၠး၊ ဒၞပ်ပလး =တစ်လွှာဖိနပ်။ || ‘ဒနပ်ပလးမွဲဆော။’ (ဇ—၃၂၃။ အစွောံ။) = ‘တစ်လွှာဖိနပ်တစ်ရန်။’ || “က္ဍိုၚ်ဂှ်မွဲ ဒၞပ်မွဲဂၠးဂှ်ဂွံမွဲဆော အဲဒးအာတ်နူသၟိၚ်ညိရောၚ်” ဣသိချပ်။ (ဇ—၃၂၃။ အစွောံ။) = “ထီးတစ်လက်နှင့် တစ်လွှာဖိနပ်တစ်ရန် မင်းထံမှ ငါတောင်းအံ့” ဟုရသေ့ကြံ၏။')
,(6683,3,1,'အသိုက်အမြုံ။ အိပ်တန်း။','‘ဓနီ’ ရှု။')
,(6684,3,11,'(န) ‘ဒၞိဟ်’ ရှု။',NULL)
,(6685,3,1,'ဖနောင့်။',NULL)
,(6686,3,1,'ဂုံညင်း။','ဝေၚ်ဒနေအ် = ဂုံညင်းကစားသည်။')
,(6687,3,4,'‘ထပက်’ ရှု။',NULL)
,(6688,3,4,'(ထမင်းစသည်) ပျော့လွန်းသည်။','“ပုၚ်ဍုန်လဝ်ဂှ် ဍာ်ဂၠိုၚ်အာတုဲ ဒပေက်အာရ။” = “ချက်ထားသောထမင်းသည် ရေများ၍ ပျော့လွန်သွားပြီ။”')
,(6689,3,4,'ဖြတ်သည်။','‘ထပိုတ်’ ရှု။')
,(6690,3,1,'‘တိပိုန်','တဳလပိုန်’ နှင့်အတူတူ။ || ဒပိုန်ဒေဝဒတ် (ဇ—၁၂။ အစွောံ။) = အရှင်ဒေဝဒတ်။')
,(6691,3,1,'ခရာ။ တံပိုး။ (တူရိယာ)',NULL)
,(6692,3,4,'ဟိုဘက်သည်ဘက် ဝှေ့ယမ်းသည်။ လှုပ်ရှားသည်။',NULL)
,(6693,3,4,'‘ဂဗ’ ရှု။',NULL)
,(6694,3,4,'‘ဂဗဆဵု’ ရှု။',NULL)
,(6695,3,4,'အလျင်စလိုလုပ်သည်။','‘ဂဗက်’ ရှု။')
,(6696,3,4,'(သစ်ပင်) ခုတ်လှဲသည်။','“ညးဂမၠိုၚ်ဂှ် ဍေံတံကေတ်မုဲကွာန်တုဲ သွက်ဂွံကုတ်ဒဗိုၚ်တၞံဇြဲဂှ်။” (ဇ—၄၉၃။ အစွောံ။) = “လူအများသည် ညောင်ပင်ကိုခုတ်လှဲရန် ပေါက်ဆိန်တံစည်းတို့ကို ယူ၏။” || “တၞံဇြဲဝွံဂှ် သီုရိုဟ်ဟေၚ် ကဵုထဗိုၚ်ကုတ်ဒန်ကၠေံရ။” (ဇ—၅ဝ၉။အစွောံ။) = “ဤညောင်ပင်ကို အမြစ်ပါ ခုတ်လှဲဖြတ်ပစ်မည်။” || “ညံၚ်တၞံတာမဂဗိုၚ်ကၠေံက္ဍိုပ်တုဲ ရဴမဟွံတိုန်ပၠန်ဂှ်ကီု။” = “ခေါင်းကိုခုတ်လှဲ၍ ပြန်မတက်နိုင်သော ထန်းပင်ကဲ့သို့။”')
,(6697,3,4,'တိုက်သည်။ ခတ်သည်။ ထိသည်။','“(ကၠိက်ဂှ်) ဒိတၞံဝိ ဒဗတ်ကဵုက္ဍိုပ်တုဲ ကၠိက်ဒးပကာဂစိုတ်ရ။” (ဇ—၁၈၆။ အစွောံ။) = “ထိုဝက်သည် ရေသဖန်းပင်ကို ဦးခေါင်းနှင့်တိုက်၍သေရလေ၏။” || “—၊ တဲဍေံစှ်ေဒဗတ်ဒးတိထတ်အာတုဲ တဲဍေံသအုဲအာရောၚ်အဴ။” (ဇ—၄၆၃။အစွောံ။) = “သူ့လက်သည် ပြင်းထန်စွာမြေကျထိခတ်မိသဖြင့် လက်နာသွားခြင်းဖြစ်၏။”')
,(6698,3,4,'ပစ်သည်။ လွှင့်ပစ်သည်။','“နဣဓိကလော်ဂှ် ရပ်ဇိုၚ်မၚ်ဗၠာဲတုဲ ဒဗိုတ်ဏာစိုပ်ဍုၚ်ဗာရာဏသဳတေံရ။” (ဇ—၄၁။ အစွောံ။) = “ဘီလူးမသည် ဘီလူးအာနုဘော်ဖြင့် လုလင်၏ခြေကို ကိုင်၍ပစ်လိုက်ရာ ဗာရာဏသီပြည်သို့ရောက်၏။” || “ရပ်လဗိုန်လဝ် (ဇြုံဂှ်) တုဲ ဗွဲပြဟ်ဒဗိုတ်ဏာရ။” (ဇ—၃၆၇။ အစွောံ။) = “ထိုမြွေကို မြဲစွာကိုင်၍ လျင်မြန်စွာလွှင့်ပစ်လိုက်၏။” || “လၟသီုမဂ္ဇအ်ဒၟံၚ်ပ္ဍဲသွက် ၜှ်သတ်ချတုဲ ဂဗိုတ်ဖျေံ ဂတမုက်ဗောဓိသတ် (တ္ၜိုၚ်) ရ။” (ဇ—၂၁။ အစွောံ။) = “မုဆိုးသည် လင့်­ထိုင်လျက် ယမနေသီးကိုခူး၍ ဘုရားလောင်းဆတ်၏ရှေ့­ ပစ်ချ၏။”')
,(6699,3,1,'ကျောက်ခဲဖြင့် ပစ်ခတ်သောအကွာအဝေး။ ခဲတစ်ပစ်။','မွဲဒဗိုတ်တၟအ် = ခဲတစ်ပစ်အကွာအဝေး။ || ၜါဒဗိုတ်တၟအ် = ခဲနှစ်ပစ်အကွာအဝေး။ || ‘လဗိုတ်တၟအ်’ ဟုလည်းရေးသည်။')
,(6700,3,4,'ကပ်သည်။','ဒဗာန်စက္ခော = စက္ကူကပ်သည်။')
,(6701,3,1,'ဗုံ။ ပတ်မ။','“သြဳသြဳဂြိၚ်ဂြိၚ်၊ ဒဗိုန်ပိၚ်မၚ်။” (လိက်ဗြရတ်ဣဏၚ်ကၚ်ရဳ) =“ဗုံကြီးဗုံသေးသံတို့သည် သာယာစွာမြည်နေကုန်၏။”')
,(6702,3,12,'(န) ဒဗ္ဗဂုဏ်ဆေးကျမ်း။ ဒြဗျဂုဏ်းဆေးကျမ်း။','“ဟောရာတီယဲ၊ ဘဲဝေဒနာ။ ပြကိုဟ်ကၞပ်၊ တဗျဂုန်ကၠာ။” (လိက်သုပိဏ္ဏကုမ္မာ။ မၚ်သၚ်ကြာ။) = “ဆေးသမားသည် ရောဂါဝေဒနာနှင့် ဒြဗျဂုဏ်းဆေးကျမ်းကို သိနားလည်၏။”')
,(6703,3,4,'(ဆံပင်၊ အဝတ်စသည်) ဖိုးရိုးဖားရားဖြစ်သည်။','“ယွီုဒဟက်၊ ပလက်ဇွောဝ်ဍေၚ်။သော်လာဲဒဗြိုဟ်၊ ဂြိုဟ်ဒှ်ထေၚ်ထေၚ်။” (လိက်ပတ္တစာရဳ။ နာဲထဝ်စိုပ်။) = “မောလုံးဆို့သောအသက်ရှူသံဖြင့် ချွေးထွက်လျက် ဆံပင်ဖိုးရိုးဖားရားပြေကျ၍ အသည်းထိတ်၏။”')
,(6704,3,1,'သူယုတ်။ သူယုတ်မာ။','‘ဒၟိက်’ ရှု။')
,(6705,3,1,'၁။ သက်တန့်။',NULL)
,(6705,3,1,'၂။ ဓမင်း။ (ငါးဖမ်းကိရိယာ)','ဖရံက်ဒမၚ် = ဒမင်းငပိ။ (မြန်မာဝေါဟာရ ‘ဓမင်း’ သည် မွန်ဝေါဟာရ ‘ဓမၚ်’ မှ ဆင်းသက်သည်။)')
,(6705,3,1,'၃။ ထုပ်လျှောက်။ခေါင်လျှောက်။ (ပါဠိ—တုလာ)','“ပ္ဍဲဂြောန်၊ ပ္ဍဲနာၚ်၊ ပ္ဍဲတရၚ်၊ ပ္ဍဲဓမၚ်သ္ၚိတံဂှ်။” (ဇ—ဘူရိဒတ်။အစွောံ။) = “ပစ္စည်းတင်ရန်စင်­၄င်း၊ ကျပ်ခိုးစင်­၄င်း၊ တံခါး­၄င်း၊ အိမ်ထုပ်လျောက်တို့­၄င်း။” || “ကလော်ဂှ် — ဍေံမံၚ်တဴပ္ဍဲဒမၚ်ဇြပ်ရ။” (ဇ—၁၅၅။ အစွောံ။) = “ထိုဘီလူးသည်ခေါင်အုပ်ဝါး၏ ဖွဲ့ရာလျောက်­နေ၏။” (ညောင်ကန်)')
,(6706,3,1,'ပရိက္ခရာရှစ်ပါးအနက် တစ်ခုဖြစ်သောရေစစ်။',NULL)
,(6707,3,1,'သက်တံ။','“မုဟ်ကၞေၚ်နေၚ်မတ်ရ၊ အဇဒမၚ်ဍာ်။” (လိက်ဂၞကျာ်ဝိသာခါ) = “နဖူးစွန်းမျက်ခုံးသည် သက်တံကဲ့သို့ဖြစ်၏။”')
,(6708,3,1,'ယက်ကန်းစင်။',NULL)
,(6709,3,1,'အိမ်၏ထုပ်လျောက်။ ခေါင်လျောက်။ ရက်မ။',NULL)
,(6710,3,1,'အခံ။ ခံခြင်း။','“(မၚ်ဗၠာဲသဥ္ဇိဝတုန် ပၟန်မက္တဵုဇွဂှ်ဟေၚ်ကတ်တုဲ) ပၟန်ဒမုၚ်မဆေဝ်ဒဝ်ဂှ် ဟွံကတ်—။” (ဇ—၁၅ဝ။ အစွောံ။) = “သဥ္ဇိဝလုလင်သည် အသေကောင်ကိုထစေသော မန္တရားကိုသာလျှင်သင်၍ တားမြစ်သောအခံမန္တရားကို မသင်ခဲ့။” || “ဍာ်လေဝ်သ္ဇိုဟ်ကြုၚ်လေဝ်လှဲ ဒၞာဲဝွံ ဒှ်ဓမုၚ်ဒပ်ပိုဲဍိက် ခိုၚ်ကၠိုက်လအိတ်ရ။” (အကြီုရာဇာဓိရာဇ်) = “ရေလည်းနက်၏၊ ချောင်းလည်းကျယ်၏။ ဤနေရာသည် အထူးခိုင်ခံ့သော ကျွန်ုပ်တို့၏ခံတပ်ဖြစ်၏။” || ‘ဒုၚ်’ (ကြိ) လည်းရှု။')
,(6711,3,1,'ဖားဖို။','ဒမုၚ်ကွဵု = လက်လှည့်ဖားဖို။ || ဒမုၚ်ဒဇက် = လက်ဆွဲဖားဖို။')
,(6712,3,1,'တံခါးခုံ။ တံခါးတပ်ရာ အခြေခံခုံ။ (ပါဠိ—ဣန္ဒခဳလ)',NULL)
,(6713,3,1,'သားရေလက်အိတ်။',NULL)
,(6714,3,1,'ပန်းထိမ်—ပန်းပဲလေဖို။','“မတုပ်တဴညံၚ်ရဴဒမုၚ်ဒမာတ်ဂှ်ကီု။” (လိက်ပရေၚ်ခန္ဓ)')
,(6715,3,1,'ကိုယ်ဝန်။ ပဋိသန္ဓေ။','ဗြဴမၞုံကဵုဒမုၚ်ဒလေၚ် = ကိုယ်ဝန်ဆောင်အမျိုးသမီး။ (ပါဠိ—ဂဗ္ဘဣတ္ထိ)')
,(6716,3,1,'အလှူခံ၊ အလှူခံသူ။','“ကဵုဒါန်မ္ဂး ရုဲစှ်ဒၟုၚ်ဒါန်မယုတ်မပြဲတုဲ ကဵုဒါန်ညိ။” =“အလှူပေးလျှင် အလှူခံပုဂ္ဂိုလ်အယုတ်အမြတ်ကို ရွေးခြယ်၍ အလှူပေးပါ။”')
,(6717,3,1,'ရက်ကန်းစင်။','‘ဒမၚ်ယန်’ နှင့်အတူတူ။')
,(6718,3,1,'သက်သေထွက်ဆိုချက်။',NULL)
,(6719,3,1,'နေရာ။ တည်နေရာ။ တည်ရှိရာ။','ဒမံၚ်သတိက် = အိပ်ရာ။ || “တောံပုၚ်သၟဝ်တ္ၚဲတုဲ ဒၟံၚ်ဂွံသတိက်ဒီုဂှ် သၟာန်ညးရ။” (ဇ—၁၅၅။ အစွောံ။) = “ညနေစာထမင်းကိုချက်ပြီးလျှင် အိပ်စက်တည်းခိုစရာနေရာကို သူတစ်ပါးတို့အားမေး၏။” || “ဒၟံၚ်ဒြပ်ဂှ် ဟီုကဵုသမ္ဘာဇကုကီုဟာ။” (ဇ—၄ဝ၂။ အစွောံ။) (ဒမံၚ်ဒြပ်၊ ဒၟံၚ်ဒြပ် = ဥစ္စာတည်နေရာ။ ဥစ္စာမြှုပ်ထားရာနေရာ။) = “ထိုဥစ္စာတည်နေရာကို မိမိဇနီးသည်အား ပြောပြထားပါသလား။” || “(ဒြပ်ဂှ်) အဲစွံလဝ်ပ္ဍဲတံဆုဂှ်ပၠန်ရ။ အဲတၟေၚ်ကၠေံဒမံၚ်ညိတုဲ အဲတိုပ်လဝ်ရ” ဗမၞးဂး။ (ဇ—၄ဝ၂။ အစွောံ။) =“ထိုဥစ္စာကို ထိုသစ်ပင်ရင်းပင် ထားပြန်၏။ တည်နေရာအနည်းငယ်ပြောင်း၍ အကျွန်ုပ်မြှုပ်ထားပါ၏။” || “ယဲကျာမ္ဂးဂှ်ရောၚ်လေဝ် သာ်ဇကုစၞာံဇကုလေဝ် ခိုဟ်ရိုဟ်ဒၟံၚ်၊ ဒၟံၚ်ယဲဂှ်လေဝ် ဟွံပြာကတ်ညိအဴ။” (ဇ—၁၃ဝ။ အစွောံ။) (ဒမံၚ်ယဲ၊ ဒၟံၚ်ယဲ = ရောဂါရှိတည်နေမှု။ ရောဂါလက္ခဏာ။) = “လေထိုးကျင့်နာဟုဆိုသော်လည်း အသားအရေလည်း ပကတိကောင်းမွန်၏။ ရောဂါရှိသောလက္ခဏာသည် မထင်ရှား။” || “သၟိၚ်ဣန်တိုန်အာဍုၚ်သွဝ်ဒၟံၚ်ဇကုတေံရ။” (ဇ—၃၇၂။အစွောံ။) = “သိကြားမင်းသည် မိမိနေရာနတ်ပြည်သို့ တက်သွား၏။”')
,(6720,3,4,'နေစေသည်။ တည်နေစေသည်။ နေရာထိုင်ခင်းပေးသည်။','“သၟိၚ်ပဿိုန်က္ညပ္တိုန်ဏာကျာ်တြဲတုဲ ပ္ဍဲသၞာမပြဲဂှ် ဒမံၚ်လဝ်ကျာ်တြဲ သီုသၚ်ဂမၠိုၚ်ရ။” (ဇ—၃ဝ၆။ အစွောံ။) = “ကောသလမင်းသည် မြတ်စွာဘုရားအား နန်းပေါ်သို့ပင့်ဆောင်၍ မြတ်စွာဘုရားနှင့်တကွ သံဃာတော်များကို မြတ်သောနေရာထိုင်ခင်း­ နေစေ၏။” || “ပ္ဍဲဗတၚ်ဂၞတ်ရုပ်ဇာဒိသိုၚ်ဂှ်ပိုဲဒၟံၚ်လဝ်သၟိၚ်တုဲ သဘၚ်ၚိတ်သၞာ်ဂှ် ပိုဲသ္ကဵုသၟိၚ်ဗဵုရ။” (ဇ—၄ဝ၁။ အစွောံ။) = “ငါတို့သည် မင်းကို ခြင်္သေ့ရုပ်ခံသောလေသာပြတင်း­ နေစေ၍ သံလျက်မျိုသောပွဲသဘင်ကို ကြည့်စေအံ့။” || “(ဇာဒိသိုၚ်) ဖျဴနၚ်ကၠဵု ပ္ဍဲဂိုဟ်တၟံထဝ် ဒၟံၚ်လဝ်ရ။” (ဇ—၁၄၃။ အစွောံ။) = “ခြင်္သေ့သည် မြေခွေးကို ရွှေဂူသို့ ခေါ်ဆောင်လာပြီးလျှင် နေရာပေး၍ နေစေ၏။” || “ကောန်တၠအဲမကဵုအဲဝွံထာန်ဂၞကျာ်ဇၞော် လတူဂၞကျာ်ဂမၠိုၚ် အဲဓမံၚ်လဝ်ရ။” (အာန်ဇုနာန်) = “ငါ့ကိုပေးသောသင့်သမီးကို မိဖုရားများ၏အထက် မိဖုရားကြီးအရာ­ ငါထားရှိတည်နေစေပါမည်။”')
,(6721,3,1,'၁။ တည်နေပုံ။ တည်ရှိပုံ။ အနေအထား။','“ဒၟံၚ်ဒတဴလပံက်လမာဲပၞာန်ညး။” (ဇ—၂၂၆။ အစွောံ။) = “ရန်သူစစ်၏တည်နေပုံအနေအထားနှင့် ပျော့ကွက်အားနည်းချက်။”')
,(6721,3,1,'၂။ တည်ရာမှီရာ။ မှီခိုရာ။ နေထိုင်ရာ။','“ဒေဝတဴဝဳမာန်ဆုဒေါမ်အာတံဂှ် သက္ကုဒမံၚ်ဒတဴဟေၚ်။” (သၠပတ်ကုလဇာတ်) = “သစ်ပင်ဗိမာန်ပြိုလဲသွားသော နတ်တို့သည် တည်ရာမှီရာမဲ့သွား၏။” || “နွံသဒ္ဓာသၟိက်ဂွံခၞံပဒှ်လဝ်ဘုတ်ကျာ် ဒမံၚ်ဒတန်ဒးရးမွဲညိကၠာ။” (အကြီုရာဇာဓိရာဇ်) = “သဒ္ဓာတရားစိတ်ရှိ၍ လျောက်ပတ်သောတည်နေရာ­ ဝတ်ပြုကျောင်းနှင့်ဘုရားတစ်ဆူ တည်ထားပါရစေဦး။” || “ဒမံၚ်ဒတန်သဘာဝတိဍာ်ဂြိုပ်ဆုဒုန်တံဂှ်ညံၚ်ဍေံဟွံဂွံလီုလာ်အာ ပိုဲမၞိဟ်တံဂပ်ဂဝ်မၚ်မွဲရ။” = “သဘာဝရေမြေတောတောင်တို့ တည်နေပုံအတိုင်း မပျက်မစီးအောင် တို့လူသားများ ထိန်းသိမ်းစောင့်ရှောက်သင့်သည်။”')
,(6723,3,1,'မြင့်မြတ်သောနေရာ။','“ထာန်ဒမံၚ်သမၠုၚ် ကောလၟတိုန်ဒၟံၚ်တုဲ ကောလၟတွံကဵုသၟိၚ်ကေုာံဂၞကျာ်ဂှ်ညိ။” (သၠပတ်ဗြဟ္မဒတ္တ ဂၞကျာ်ခေမာဝတဳ) = “မြင့်မြတ်သောနေရာ­ နောင်တော်မုဆိုးတက်နေ၍ ထိုမင်းနှင့်မိဖုရားအား နောင်တော်မုဆိုးဟောကြားလော့။” || “မိမမ္ဂးဂှ် ကောန်တံဒးစွံဒမံၚ်သမၠုၚ်ရ။” = “မိဘတို့မည်သည်ကို သားသမီးများက မြင့်မြတ်ရာ­ထားရပါမည်။”')
,(6724,3,1,'နေရာ။ တည်ရာ။ နေရာထိုင်ခင်း။ နေထိုင်ရာနေရာ။','“ညးဗၞိက်ချေံမသုန်ကၠံဂှ် ကၠုၚ်စိုပ်တုဲ ဂၠာဲဒၟံၚ်အရာ ညာတ်သ္ၚိဂှ်—။” (ဇ—၂၅၄။ အစွောံ။) = “ငါးရာကုန်သောမြင်းကုန်သည်တို့သည် လာရောက်၍ တည်းခိုရာနေရာကို ရှာသည်ရှိသော် ထိုအိမ်ကိုမြင်၏။” || “(ဂွံမခါတုဲ) မဂဒူစိုပ်ဒၟံၚ်အရာဇကု ထဂုဲဖဍာ်တိဝဲါအိက်စိၚ် ဂြာတ်မခါ—။” (အကြီုရာဇာဓိရာဇ်) = “မဂဒူးသည် ဟင်းနုနွယ်စေ့တို့ကိုရပြီးနောက် မိမိနေရာသို့ပြန်လာကာ မြေကျက်ဆင်ချေးဝဲတို့ကို ပြင်ဆင်ရေလောင်းကာ ဟင်းနုနွယ်စေ့ကို ကြဲ၍စိုက်ပျိုး၏။” || “ဍေံတံညးပိစှ်ော စှ်ေအာဍုၚ်ကွာန်ဒမံၚ်အရာဣတံရ။” (အကြီုရာဇာဓိရာဇ်) = “သုံးကျိပ်ကုန်သောသူတို့သည် သူတို့နေရာမြို့ရွာများသို့ ပြန်သွားကြ၏။” || “သေဋ္ဌဳဗြဴလးလဝ်ကဵုဒၟံၚ်အရာ ကဵုပစ္စေဂဗုတ်ဂ္ဇံတုဲ—။” (ဇ—၃၉ဝ။ အစွောံ။) = “သူဋ္ဌေးမသည် နေရာထိုင်ခင်းကိုခင်းပေး၍ ပစ္စေကဗုဒ္ဓာအား ထိုင်စေ၏။” || “(လၟ) အာညာတ်ဒြာဲထဝ်ဂှ်ရ။ ညာတ်တုဲ ၚဳရံၚ်ဒမံၚ်အရာမထံၚ်ပးဂှ်—။” (ဇ—၅ဝ၁။ အစွောံ။) = “မုဆိုးသည် ရွှေသမင်ကိုမြင်၍ ကျော့ကွင်းထောင်ရန်နေရာကို စူးစမ်း၏။”')
,(6725,3,1,'၁။ ပန်းထိမ်၊ ပန်းပဲအစရှိသော သတ္တုထည်လုပ်ငန်း။','ဓမာတ်ထဝ် = ရွှေပန်းထိမ်။ || ဒမာတ်ပသဲ = ပန်းပဲ။ || ဓမာတ်သြန် = ငွေပန်းထိမ်။ || ဒမာတ်ပသဲဍာ် = သံဖြူပန်းပဲဆရာ။ || “ဗောဓိသတ်ပိုဲ — ဒှ်ပ္ဍဲဂကူဒမာတ်ပသဲ—။” (ဇ—၃၈၇။ အစွောံ။) = “ဘုရားလောင်းသည် — ပန်းပဲအမျိုး­ဖြစ်၍—။” (ညောင်ကန်)')
,(6725,3,1,'၂။ အမည်မဖော်နိုင်သောငှက်တစ်မျိုး။','“မပ္တံကဵုဂစေံ ဓဇဲ၊ ဓမာတ်၊ စာၚ်ဍာ်၊ စာၚ်ကၠိုက်၊ လိုက်ထောဝ်၊ ဗဂေါဝ်၊ ဖဝ်ရဂုတ်—။” (ဇ—ဝေသန္တဝ်။ အစွောံ။)')
,(6726,3,4,'ယောင်ယမ်းသည်။ မြည်တမ်းသည်။ အလိုလျောက်ပြောမိသည်။','ကြာန်ဒမာန် = ရမ်းကားသည်။ သွေးရူးသွေးတန်းဖြစ်သည်။ || ယာံဒမာန် = ငိုကြွေးမြည်တမ်းသည်။ || “(သာဂတထေဂှ်) မသ္ဍိုက်ကဵုသူရာဗ္ၜူအာ တိတ်နူဍုၚ်ကောသမ္ဗဳ ပ္ဍဲအကြာတရၚ်ဍုၚ်လောတ်အာ သီုမဒမာန်တဴမသတိက်ဒၟံၚ်။” (ဇ—၈၁။ အစွောံ။) = “သာဂတမထေရ်လည်းသောက်၍ သုရာယစ်ခြင်းဖြင့်ယစ်၍ မြို့မှထွက်သည်ရှိသော် တံခါးကြား­လဲ၍ ယောင်ယမ်းလျက်အိပ်၏။” (ညောင်ကန်) || “ဗမၞးဂှ် ဗှ်သၞာသမ္ဘာဇကုတုဲ ရဴမဒၟာန်တဴကီုပတုဲ—။” (ဇ—၄၁၆။အစွောံ) = “ပုရောဟိတ်သည် မိမိပုဏ္ဏေးမကိုအောက်မေ့၍ မြည်တမ်းသကဲ့သို့ (ပြု၍) —။” (ညောင်ကန်) || “ပ္ဍဲကာလသၟိၚ်မဟီုဒမာန်တိုန် ‘ကၟတ်ကၟတ်’ ဂှ် ပထမဂလာန်ဂှ် ဗောဓိသတ်သ္ဂးရ။” (ဇ—၃၃၆။ အစွောံ။) = “မင်းသည် (‘မြက်မြက်’ဟူ၍) မြည်တမ်းသောကာလ­ ဘုရားလောင်းသည် ရှေးဦးစွာသော ဤဂါထာကိုဆို၏။” (ညောင်ကန်) || “ဂၞကျာ်ပကၠေံကာဂစိုတ်တုဲဆသၟိၚ်မယာံဒမာန်ဒၟံၚ် လုကဴထပှ်တ္ၚဲ ကလိအာရ။” (ဇ—၂ဝ၇။ အစွောံ။) = “(မိဖုရားသေ၍) ထိုအဿကမင်း၏ ငိုကြွေးမြည်တမ်းစဉ်ပင်လျှင် ခုနစ်ရက်တို့သည် လွန်ကုန်၏။” (ညောင်ကန်) || “သၟိၚ်နာဲပိုဲ ဟွံဂွံတိတ်ဝေၚ်သဘၚ်တုဲ ကလေၚ်စဴအာ လုပ်အာပ္ဍဲဂၠံကျာ်သြဳတုဲ ဒမာန်နရိုအ်ဒၟံၚ်ရ။” (ဇ—၅၂၇။ အစွောံ။) = “ငါတို့အရှင်မင်းမြတ်သည် မြို့တော်ပွဲသဘင်ခံသည်ရှိသော် ကြည့်ရှုရွှင်မြူးတော်မမူဘဲလျှင် ကျက်သရေရှိသော အိပ်ရာတိုက်ခန်းသို့ဝင်၍ ယောင်ယမ်းမြည်တမ်းတော်မူလျက် လျောင်းတော်မူ၏။” (ညောင်ကန်)')
,(6727,3,4,'ယောင်ယမ်းမြည်တမ်းသည်။','“(ဣသိဝွံ) မကြအ်ဥမတ်ဒှ်တုဲ မဟီုဒမာန်ကြာန်အာသ္ဂးဟာ။” (ဇ—၄၃၆။ အစွောံ။) = “ဤရသေ့သည် ရူးသွပ်သည်ဖြစ်၍ (တွေးမိတွေးရာ) ယောင်ယမ်းပြောဆိုလေသလော။” || ‘ကြာန်ဒမာန်’ လည်းရှု။')
,(6728,3,4,'ကြောက်ရွံ့သည်။',NULL)
,(6729,3,4,'ယောင်ယမ်းမြည်တမ်းသည်။','“(ဂစေံဂန္ဒကဂှ် ၜံက်ဆုကြက်လကံ) စမဴဂှ်ပါ်အာတုဲ ခဍောၚ်မတ် ညံၚ်မဗၠတ်တိတ်အာ က္ဍိုပ်ညံၚ်ဒကးအာကီုဒှ်တုဲ — နဂလာန်မွဲ ဟီုဒမာန်ဒရံၚ်တဴရ။” (ဇ—၂၁ဝ။ အစွောံ။) = “ဂန္ဒကငှက်သည် ရှားပင်ကို နှုတ်သီးဖြင့်ပေါက်သည်ရှိသော် နှုတ်သီးသည်ပြတ်၏။ မျက်လုံးတို့သည် ပြုတ်ထွက်ဘိသကဲ့သို့ ဦးခေါင်းသည် ကွဲဘိသကဲ့သို့ဖြစ်၍ တစ်ခုသောစကားကို ယောင်ယမ်းမြည်တမ်း၏။”')
,(6730,3,1,'သိုလှောင်ရုံ။ သိုလှောင်ခန်း။ သိမ်းဆည်းထားရာနေရာ။','ဂၠံဒမေပ် = သိုလှောင်ခန်း။ ဥစ္စာတိုက်။ || “ဣန်ကဵုပံက်ကၠေံ ဂၠံဒမေပ်ရတ်ထပှ်ပြကာ—။” (ဇ—၇၈။ အစွောံ။) = “သိကြားသည် ရတနာခုနစ်ပါးတို့ဖြင့် ပြည့်ကုန်သောတိုက်တို့ကို ဖွင့်စေ၍—။” (ညောင်ကန်) || ‘ဋ္ဌာန်ဒၟေပ်ကျာ်ပန်။’ (အကြီုရာဇာဓိရာဇ်) = ‘ဘုရားလေးဆူတို့၏ အသုံးအဆောင်တော်၊ ဓါတ်တော်စသည် ဋ္ဌာပနာသိမ်းဆည်းထားရာအရပ်။’ (ရွှေတဂုံစေတီကို ဆိုလိုသည်။)')
,(6730,3,1,'သိုလှောင်ရုံ။ သိုလှောင်ခန်း။ သိမ်းဆည်းထားရာနေရာ။','‘ဒေပ်’ (ကြိ) လည်းရှု။ || ဒယိကၠေၚ် = ခေါင်းလိမ်းဆီကို ဆံပင်တွင်လိမ်းသည်။')
,(6731,3,4,'(ခေါင်းလိမ်းဆီကို) လိမ်းသည်။','“ဒးဒယိကၠေၚ်။” (သ္ကေံမိလိန္ဒဝတ္ထု)')
,(6732,3,1,'တံစက်မြိတ်။','ဒယူသ္ၚိ = အိမ်တံစက်မြိတ်။ || “ဒယူကဝ်သ္အိုဟ်၊ ကၟဳစရိုဟ်အာ။” (လိက်ပုညကာရဳ) = “တံစက်မြိတ်ဆွေးမြည့်ကျိုး၍ အမိုးပြိုသွားသည်။”')
,(6733,3,1,'၁။ တောင်စလဲပင်။','သတ်ဓယာ် = တောင်စလဲသီး။')
,(6733,3,1,'၂။ သိင်္ဂလငှက်။ စာပေါင်းသောင်း။ (ပါဠိ—သိၚ်္ဂလ)','“ဗောဓိသတ်ပိုဲ ဒှ်ဂစေံဒယာ်—။” (ဇ—၃၂၁။ အစွောံ။) =“ဘုရားလောင်းသည် သိင်္ဂလငှက်မျိုး­ဖြစ်၍—။” (ညောင်ကန်)')
,(6734,3,1,'လောင်းရိပ်။','ဒးဒယံက်၊ ဒးဒမျံက် = လောင်းရိပ်မိသည်။')
,(6735,3,1,'တိုင်။',NULL)
,(6736,3,1,'တံခွန်တိုင်။',NULL)
,(6737,3,1,'ဇော်ဂျီတောင်ဝှေးပင်။ (ဆေးဖက်ဝင်)',NULL)
,(6738,3,1,'ရွက်တိုင်။ လင်းယဉ်တိုင်။',NULL)
,(6739,3,1,'အိမ်တိုင်။',NULL)
,(6740,3,1,'ကြငှန်းတိုင်။ တစ်ပင်တိုင်နန်းပြာသာဒ်တိုင်။','“ဒယိုင်အတှ်ပြာသာဒ်သၟိၚ်မွဲဂှ်လီုအာ။” (ဇ—၁၂၁။ အစွောံ။) = “မင်း၏တစ်ဆောင်သော တစ်ပင်တိုင်နန်းပြာသာဒ်သည်ပျက်သွား၏။”')
,(6741,3,4,'အခေါက်ပေါင်းများစွာ သယ်ယူသည်။','“သေဋ္ဌဳပကာဂစိုတ်တုဲ သေဋ္ဌဳဟိုတ်ဟၟဲကဵုကောန်တြုံကောန်ဗြဴဂှ်ရ ဒြပ်တံဂှ် ဒးဒှ်အရာသၟိၚ်ရဂးတုဲ လုကဴဗ္တံတ္ၚဲဟေၚ် ဒယိုန်ပၠောပ်ပ္ဍဲသ္ၚိသၟိၚ်ရ။” (ဇ—၃၉ဝ။ အစွောံ။) = “သူဋ္ဌေးသေပြီးနောက် သူဋ္ဌေးတွင် သားသမီးမရှိခြင်းကြောင့်သူဋ္ဌေး၏ဥစ္စာတို့သည် မင်း၏အရာသာဖြစ်၏ဟု မင်းအိမ်သို့ နေ့ရောညပါ အခေါက်ပေါင်းများစွာသယ်ဆောင်သွင်းကုန်၏။” || “ထပှ်တ္ၚဲဟေၚ် သီုညးဍုၚ်ရးတံဂှ် ကၠုၚ်ဒယိုန်ကေတ် ပိုန်ဟာန်ထဝ်ဒြပ်တံဂှ်ရ။” (ဇ—၃၂၈။ အစွောံ။) = “ခုနစ်ရက်တိုင်တိုင် တိုင်းနိုင်ငံသူတို့သည် ထိုဥစ္စာရွှေငွေတို့ကို လာသယ်ယူကြကုန်၏။” || “ယွံနာဲပိုဲ၊ ပတွဵုနူကဝ်မတန် ပံက်မစံၚ်တူသောသၞာ ဒၟာနူကမ္ဂးဝွံ ဟၟဲမွဲလှ်ေသွံ။ နာဲပိုဲသၟိက်ဒယိုန်စပိုဲ မွဲမွဲရောၚ်သဒှ်” ကဂမၠိုၚ်ဂးကဵုပံက်ရ။ (ဇ—၃၈။ အစွောံ။) = “အရှင်၊ ကမ္ဘာဦးမှစ၍ ငါးတို့အတွက်ကြောင့် စိုးရိမ်ပူပန်သောဗျိုင်းမည်သည် မရှိစဖူး။ သင်သည် ငါတို့တွင် တစ်ကောင်တစ်ကောင်ကို ယူစားလိုသည်ဖြစ်လတ္တံ့” ဟုငါးများက ဗျိုင်းအားပြော၏။')
,(6742,3,4,'စစ်ပွဲအတွင်း ဥစ္စာပစ္စည်းကို လုယက်သိမ်းပိုက်ရယူသည်။',NULL)
,(6743,3,4,'၁။ ချိန်ရွယ်သည်။ ရည်ရွယ်သည်။','“ပိုဲဒယာပ်ဒၟံၚ် သွက်ဂွံအာသဘၚ်ကျာ်ရ။”= “ဘုရားပွဲသွားရန်အတွက် ကျွန်တော်တို့ချိန်ရွယ်နေသည်။” || “ညံၚ်မၚ်ဗၠာဲတလဒြဟတ်အစောံမွဲဂှ် ရပ်သၞာ်ဇကေက် ညးမချူလဝ်ဂှ်တုဲ ရဴမဒယာပ်ဗာ်အဲကီုရ၊—။” (ဇ—၂၅၃။ အစွောံ။) =“တစ်ယောက်သော ခွန်အားဗလရှင်လုလင်ပျိုသည် ကျောက်­သွေးထားအပ်သော ထက်စွာသောသန်လျက်ကို ကိုင်စွဲလျက် ငါ့အားခုတ်ရန် ချိန်ရွယ်သကဲ့သို့။”')
,(6743,3,4,'၂။ တုံ့ပြန်ဆွဲဆောင်သည်။','“ပူဂဵုမတုပ်စိုတ်ဒးမတ် ထပှ်လဂံါကီု လအာမွဲစွံ မေတ္တာဒယာပ်မေတ္တာ ဒှ်မိတ်ရ။” (ဇ—၈၃။ အစွောံ။) = “စိတ်တူသောသူနှင့် အတူတကွ ခုနစ်ဖဝါးလှမ်း၍ သွားဖူးသဖြင့် တစ်ဦးမေတ္တာတစ်ဦးမှာ တုံ့ပြန်ဆွဲဆောင်သည်ဖြစ်၍ အဆွေခင်ပွန်းဖြစ်၏။”')
,(6744,3,1,'(ရေ၊ အအေးဓါတ်) စိမ့်ခြင်း။ ပျံ့နှံ့ခြင်း။ (?)','“(ပ္ဍဲတရဴကန္တာဗတဳဂှ် ဗောဓိသတ်ညာတ်ကၟတ်ဓဇိပ်မွဲကၟဵု) ‘ကၟတ်ဓဇိပ်ဝွံ ပဟိုတ်ဒယာပ်ဍာ်တုဲရောၚ် မတိုန်တန်ဒှ်ရ’ ချပ်တုဲ (ကဵုၜံက်ခဲါကမၠိုၚ်ဒၞာဲဂှ်ရ။)” (ဇ—၂။ အစွောံ။) = “သဲကန္တာရခရီး­ ဘုရားလောင်းသည် တစ်ခုသောနေစာမြက်စုကိုမြင်၍ ‘ဤနေဇာမြက်စုသည် ရေဓါတ်စိမ့်ခြင်းကြောင့် ပေါက်သည်ဖြစ်လတ္တံ့’ဟုကြံ၍ ထိုနေရာ­ လူများကို ရေတွင်းတူးစေ၏။”')
,(6745,3,4,'ညိုမှိုင်းသည်။ အုံ့မှိုင်းသည်။','“တ္ၚဲဏအ်ဗြဲဒယောမ်ဒၟံၚ် ဟွံဂွံညာတ်တ္ၚဲရ။” = “ယနေ့မိုးမှောင်နေသည် (အုံ့မှိုင်းနေသည်) ၊ နေကိုမမြင်ရပါ။” || “ဒေံဗြဴမၞုံကဵုဒွက်သော်လမ္စံက်ဓယောံ။” (သုဓမ္မဒေသနာ။ ဂရိုက်သာံ။) = “နှမငယ်သည် မည်းနက်ညိုမှိုင်းသော ဆံထုံးရှိ၏။” || “ညံၚ်ရဴတြုံမွဲ — မဒယီုဒၟံၚ်လွဟ်ဂှ်ကီု။” (ဇ—၃၇ဝ။ အစွောံ။) = “လက်နက်ကိုဝင့်သောယောကျာ်းကဲ့သို့။” || “လၟတုန် သီုမဂ္ဇအ်ဒၟံၚ်ပ္ဍဲသွက် ဒယီုဗၞုဟ်သြဲဖျေံ (ကုဗောဓိသတ်တ္ၜိုၚ်) ။” (ဇ—၂၁။အစွောံ။) = “မုဆိုးသည် လင့်­ထိုင်လျက်လျှင် လှံကိုဝင့်ချီ၍ ဘုရားလောင်းဆတ်အား ပစ်ချ၏။” || “(စးအသံအဲဝွံမ္ဂး) နသၞာ်အဲဝွံ အဲသကဵုဗာ်ဂစိုတ်ကၠေံရဂးတုဲ ရိုဟ်ရိုဟ်မတိတ်ဒုၚ်စမုက်ဂှ် (သၟိၚ်) ဟီုဒယီုဒၟံၚ်သၞာ်ဂှ်လၟိုန်ရ။” (ရာဇာဝံသသံခိပ်။ အစွောံ။) = “ငါ့အမိန့်ကို ဖီဆန်သောသူများကို ဤငါ့သန်လျက်ဖြင့် ခုတ်သတ်ပစ်စေမည်ဟု မင်းသည် အခစားခံသောအခါတိုင်း သန်လျက်ကိုဝင့်လျက် (ခြိမ်းခြောက်) ပြောဆိုနေ၏။”')
,(6747,3,1,'လက်ရမ်းလက်ဆ။ လက်အချိန်အဆ။','“ညံၚ်ဗီုသၠဒကေဝ် မဟွံပ္တေဟ်ဒယီုဂတာတဲဂှ်ကီု မိၚ်ဂလာန်ညးဂှ် လ္ပပ္တေဟ်ပြဟ်ညိ။” (ဇ—၁၁၃။ အစွောံ။) = “ချိန်ခွင်သည် လက်ရမ်းလက်ဆကို မယုံသကဲ့သို့ သူတစ်ပါးစကားကိုကြား၍ အယုံမစောပါလေနှင့်။”')
,(6748,3,4,'(ငှက်) တောင်ပံဖြန့်သည်။ ပျံသန်းသည်။','“တ္ၚေက်ထဝ်ဂှ် ကြုက်မွဲထ္ၜောမ်ဂှ်ဂိုၚ်ကေတ်တုဲ ဒယီုသၞေၚ်တုဲ ပဝ်စဴရ။” (ဇ—၂၈၁။ အစွောံ။) = “ထိုရွှေကျေးသားသည် ထိုသရက်သီးကိုကိုက်ချီလျက် တောင်ပံဖြန့်၍ ပျံသန်း၍ပြန်လာ၏။”')
,(6749,3,4,'ကျော်ကြားသည်။','“(ဗောဓိသတ်) ဂွံဒှ်ပြောဟိတ်တၠပညာ — ဒယှ်ပြာကတ်ဒၟံၚ် ညံၚ်ရဴဂိတုတ္ၚဲကီုမဒှ်။” (ဇ—၄ဝ၁။ အစွောံ။) = “ဘုရားလောင်းသည် ပညာရှိပုရောဟိတ်ဖြစ်၍ နေလပမာကျော်ကြားထင်ရှား၏။”')
,(6749,3,1,'ကျော်ကြားခြင်း။ အကျော်အစော။','“တ္ၚဲဝွံညးသ္ဂောံတီဒယှ်အဲရ” ဗောဓိသတ်ဂး။ (ဇ—၈ဝ။ အစွောံ။) = “ယနေ့ငါ၏အကျော်အစောကို သိရအံ့။”')
,(6750,3,4,'ကျော်ကြားသည်။','“ညးက္တဵုဗဒှ်သဘၚ်မဇၞော် ဒယှ်ကမြဴ အလုံဍုၚ်ဗာရာဏသဳရ။” (ဇ—၁၅၄။ အစွောံ။) = “ကြီးစွာသောပွဲသဘင်ဆင်နွှဲရာ ဗာရာဏသီပြည်လုံးအနှံ့ ကျော်ကြား၏။” || “သၟိၚ်ဝွံ ပတၠပညာလောန်ထောန်ရောၚ်။ ဒယှ်ကမြဴဒၟံၚ် အလုံဇမ္မုဒိပ်ရ။” (ဇ—၂၅၇။ အစွောံ။) = “ဤမင်းသည်ကား ကြီးစွာသောပညာရှိပေတည်း။ အလုံးစုံသောဇမ္ဗူဒိပ်­ ကျော်ကြား၏။” || “အလုံဒိုဟ်စှ်၊ ဒယှ်ကမြဴ။” (လိက်ဗြရတ်ဣဏၚ်ကၚ်ရဳ) = “အရပ်ဆယ်မျက်နှာအလုံးကျော်ကြား၏။”')
,(6751,3,4,'ကျော်ကြားသည်။ ကျော်စောသည်။','“ဟာဲပြဘာဝတဳ၊ သၟိၚ်ကုသဝွံဂှ် — မဒှ်ကောန်တြုံတွဵုသၟိၚ်အိန်တၠသွဝ်ဂှ် ဒယှ်ကျဝ်ဒၟံၚ်ဂှ် ဗှ်ေသဒိုဟ် ဗှ်ေဟွံတီ” ခုဇ္ဇာဟီုတ္ၜေဟ်ရ။ (ဇ—၅၃၁။ အစွောံ။) = “ဟယ်ပဘာဝတီ၊ ကုသမင်းသည်ကား နတ်ပြည့်ရှင်သိကြားမင်းက ပေးထားသောသားဖြစ်၍ ထင်ရှားကျော်စောနေသည်ကို သင်မိုက်သဖြင့် သင်မသိလေ။”')
,(6752,3,4,'ကျော်စောသည်။ အနှံ့ကျော်ကြားသည်။','“ဂုတ္တိလသၟာတွိၚ်မ္ဂးဂှ် ဒယှ်တမ္ညဝ်ဒၟံၚ်အလုံဂတာဇမ္မုဒိတ်ရ။” (ဇ—၂၄၃။ အစွောံ။) = “စောင်းသမားဂုတ္တိလသည် ဇမ္ဗူဒိပ်ကျွန်းအလုံး­ ကျော်စော၏။”')
,(6753,3,4,'ကျော်ကြားသည်။ ကျော်စောသည်။','“(ပူဂဵုမတီဂုန်ညး မခၠေဝ်ဂုန်ညး မဗှ်ဗၞုဟ်ဂုန်ညးလၟိုန်ဂှ်) ဂွံဒယှ်တှ်ပြာကတ်အာ အလုံဂတာဇမ္ဗုဒိပ်ရ။” (ဇ—၃ဝ၂။ အစွောံ။) = “သူ့ကျေးဇူးကိုသိသော သူ့ကျေးဇူးကိုဆပ်သော သူ့ကျေးဇူးကို အစဉ်အောက်မေ့သောသူသည် ဇမ္ဗူဒိပ်အလုံး­ ကျော်စောထင်ရှား၏။” || “ဟိုတ်ညးဒယှ်တှ် မၞးတံမစောန်စိုတ်ရောၚ်။” (ဇ—မဟောဟ်သဓ။ အစွောံ။) = “သူတစ်ပါးကျော်စောသဖြင့် သင်တို့မနာလိုဖြစ်၏။”')
,(6753,3,1,'ကျော်ကြားခြင်း။အကျော်အစော။','“ယွံကောန်၊ မပတၠဂၟံၚ်ရောၚ်သွံ။ မၞးမၞုံပက္ကတိမဂ္ၚေၚ်ဋ္ဌာန်စၞေဟ်ရောၚ်သွံ။ ပ္ဍဲဋ္ဌာန်စၞေဟ် မဂွံဒုၚ်ဒယှ်တှ်ဒေါဝ်ပေဲါရောၚ်” အ္စာစိၚ်ဂးကဵုစိၚ်မ္ၚဵုဂှ်ရ။ (ဇ—၁၈၂။ အစွောံ။) =“ချစ်သား၊ သင်သည် ရဲရင့်၏။ စစ်မြေပြင်­ ကျက်စားသောအလေ့ရှိ၏။ စစ်မြေပြင်­ ပွဲလယ်­အကျော်အစောခံသောဆင်တော်တည်း။” || “သၟိၚ်ဂှ် ယဿပတ်တွဳဝါရကီု ဒယှ်တှ်ဂှ်လေဝ်ကီုဇၞော်မောဝ်အာရ။” (ဇ—၃၃၂။ အစွောံ။) = “ထိုမင်းအား စည်းစိမ်အခြံအရံသည်၄င်း အကျော်အစောသည်၄င်း တိုးပွား၏။” || “တလကြဳဇှ်၊ ကျာ်ဒယှ်ဘဴ။” (လိက်ဝိဓူရ) = “အစွမ်းအာနုဘော်အရှင်ဖြစ်သော ကျော်စောသောမြတ်စွာဘုရား။” || “မွဲဟွံတုပ်သၟဟ်၊ကျာ်ဒယှ်ဘဴ။” (လိက်သုဝဏ္ဏသာံ။ မာံသေၚ်။) = “တုပြိုင်တူညီသူမရှိသော ကျော်စောသော မြတ်စွာဘုရား။”')
,(6754,3,4,'ကျော်ကြားသည်။ ကျော်စောသည်။','“ညးနွံညာန်ဂှ်၊ တြုံဓယှ်ဘဴ။” (လိက်ဓနဥ္ဇယျကုမ္မာ။ အစွောံ။) || “ကပ္ပဳလဝှ်၊ ဋ္ဌာန်ဒယှ်ဘဴ။” (လိက်ပထမဗောဓိ။ မၚ်ဍိက်လ။) = “ကျော်ကြားသောအရပ်ဖြစ်သော ကပ္ပိလဝတ်ပြည်။”')
,(6755,3,4,'သီဆိုသည်။','ဒယှ်ေဒွက် = သီချင်းဆိုသည်။ || “ဒွက်သၟိၚ်မဒယှ်ေဂှ်ဟေၚ် ဍေံတံဒယှ်ေတဴအိုတ်ရ။” (ဇ—၄၁၅။ အစွောံ။) = “မင်းသီဆိုသောသီချင်းကိုသာလျှင် သူတို့သီဆိုကြကုန်၏။”')
,(6756,3,1,'အင်တုံ။','‘ဇရ’ ရှု။')
,(6757,3,1,'ရက်ကန်းတွင်သုံးသောဒညင်းလုံး။',NULL)
,(6757,3,4,'ဒညင်းလုံးလှိမ့်သည်။','ဒရာတောဝ် = ဒညင်းလုံးလှိမ့်သည်။')
,(6758,3,1,'အကန့်။ အကန့်အကွက်။','“(ကျာ်တြဲ) ဟိုတ်မပကၚ်ရၚ်လဝ် စက်ၜါ၊ဒရာလ္ၚီ၊ ရုပ်ကၠံဒစာံတုဲ အလုံပိစှ်ောမွဲဘုံ ဟၟဲကဵုညးပ္တောအ်ၜတ်ပြိုၚ်ပ္ကာန်။” (ဗုဒ္ဓဝၚ်) = “စက်တော် (ခြေတော်) အစုံ၊ ခြေဖဝါးတော်အပြင်တို့­ အကန့်တစ်ထောင်တို့ဖြင့် တန်ဆာဆင်အပ်သောတစ်ရာ့ရှစ်ကွက်သော စက်အင်္ဂါအမှတ်အသား ပါရှိခြင်းကြောင့် အလုံးစုံသော (၃၁) ဘုံ­ တုပြိုင်မည့်သူမရှိသော မြတ်စွာဘုရား။” || “ဒၞာဲဇိုၚ်ကျာ်မလိုန်လဝ် သီုစက်ၜါ၊ ဒရာလ္ၚီ၊ ရုပ်ကၠံဒစာံစၞောန်ထ္ၜးတဴ။” (ဓမ္မဒေသနာ။ မာံရွှေငိုး။) || ‘မၞုံဓရာစက်သံသာဂပ်ဂဝ်ပၠေၚ်ကၠေံတုဲ။’ (ပါဠိ—ဟတသံသာရစက္ကာရ) = ‘ပယ်ဖျက်အပ်သောသံသရာစက်အကန့်ရှိသည်။’ (ပါဠိမြန်မာအဘိဓါန်။ ဦးဟုတ်စိန်။) || “သဗ္ဗညုလိုန်ပပြာကတ်ပါဒလက်သန် သီုစက်ၜါဇရာလ္ၚီ ရုပ်ကၠံဒစာံ။” (ပြကိုဟ်ဂဝမ္ပတိ) || ‘ဒရာစက်ကွဳ’ (န) ၊ ‘ဒရာစက်သံသာ’ (န) တို့လည်းရှု။')
,(6759,3,1,'ကိလေသာ၏အစိတ်အပိုင်းများ။ (?)',NULL)
,(6760,3,1,'လှည်းဘီးဒေါက်။ လှည်းဘီးကန့်ဒေါက်။','“ဍေံမအာဂၠာဲၚဳ ဆုမသ္ပဒရာကွဳရ။” (သၠပတ်ကုလဇာတ်) = “လှည်းဘီးဒေါက်လုပ်ရန်သစ်ကို သူလိုက်ရှာသည်။”')
,(6761,3,1,'စက်အကန့်။ ဘီးအကန့်။ (ပါဠိ—စက္ကာရ)',NULL)
,(6762,3,1,'သံသရာစက်၏အကန့်။ အစိတ်အပိုင်း။','“အရဟတော၊တဳလမကုတ်ကၠေံ ဒရာစက်သံသာရတုဲ မထိုက်ဒုၚ်ပူဇဴမၞိဟ်ဒေဝတဴဂမၠိုၚ်။” = “သံသရာစက်၏အကန့်တို့ကို ဖြတ်တောက်ပစ်တော်မူပြီး၍ လူနတ်တို့၏ပူဇော်အထူးကို ခံယူတော်မူထိုက်သော မြတ်စွာဘုရား။” || ‘မၞုံဓရာစက်သံသာ ဂပ်ဂဝ်ပၠေၚ်ကၠေံတုဲ။’ (ပါဠိ—ဟတသံသာရစက္ကာရ) =‘ပယ်ဖျက်အပ်သော သံသရာစက်အကန့်ရှိသည်။’ || (မှတ်ချက်။ ‘ဇရာစက်သံသာ’ ဟုလည်းတွေ့ရသည်။)')
,(6763,3,1,'စဉ့်အိုးကြီး။','‘ဇရဳ’ ရှု။')
,(6764,3,4,'ကြက်သီးထသည်။','ဖေက်ဇကုဒရဴ = ကြောက်၍ ကြက်သီးမွေးညှင်းထသည်။')
,(6765,3,4,'အလျင်စလိုလုပ်သည်။ အလျင်လိုသည်။','“ဒရေက်အာအလဵုရော။”= “အလျင်စလိုဘယ်ကိုသွားသနည်း။” || “ဆဵုဂၠံၚ်ဇၞော်ဗက်၊ ဂရက်ကွာ်အာ။” (လိက်ဇိဝှစက္က) =“လမ်းမကြီးကိုတွေ့သည်နှင့် အလျင်စလိုလျှောက်သွား၏။” || ‘ဂရေက်’ နှင့်အတူတူ။')
,(6766,3,4,'အလျင်စလိုလုပ်သည်။ အလောတစ်ကြီးလုပ်သည်။','‘ဂရေက်ဂဗေက်’ နှင့်အတူတူ။')
,(6767,3,4,'လှုပ်သည်။','‘ဂရိုက်’ ရှု။')
,(6768,3,4,'‘ဂရိုက်ဂရာၚ်’ ရှု။',NULL)
,(6769,3,4,'၁။ ထစ်ချုန်းသည်။','ဂဂဵုဒရိၚ် = မိုးချုန်းသည်။')
,(6769,3,4,'၂။ စီတန်းသည်။ စီရရီဖြစ်သည်။','“ပၞာန်တိုက်ချေံစိၚ်၊ ဇက်ဒရိၚ်ဗဝ်။” (လိက်ရတနပဇ္ဇောတ) = “ခြေသည်တပ်၊ မြင်းတပ်၊ ဆင်တပ်တို့သည် စီရရီပြည့်နှက်လျက် ချီလာကုန်၏။”')
,(6770,3,1,'အနီးအနား။ ဝန်းကျင်အရပ်။','“ကောန်တ္ၚေက်ဂှ်တုန်လေဝ် ပဝ်စှ်ေအာဒရိၚ်ဇိုၚ်ကြုၚ်ဂှ်တုဲ ပ္ဍုန်ဒၟံၚ်ပ္ဍဲကၞာၚ်ဆုဝိမွဲရ။” (ဇ—၁၂၇။ အစွောံ။) = “ကျေးသားငယ်သည် ထိုမြစ်ကမ်းနားသို့ ပျံဆင်းသွားပြီးလျှင် တစ်ခုသောရေသဖန်းခက်­ နားနေ၏။” || “ပ္ဍဲဂၠံဂဝ်စိၚ်၊ ဒရိၚ်ဟေမာ။ မက္တဵုဒှ်ရ၊ ခဏဂှ်ကၠာ။” (လိက်သၟိၚ်စိၚ်ဆဒ္ဒန်။ နာဲထဝ်စိုပ်။) = “တောအရပ်ဝန်းကျင်­ဆင်အဖြစ်ပဋိသန္ဓေနေ၍ ထိုခဏ­ မွေးဖွားလာ၏။” || “နွံဂၞပ်ဒြၚ်စိၚ်၊ ဒမြိၚ်ဟေမာ။” (လိက်သၟိၚ်စိၚ်ဆဒ္ဒန်။ နာဲထဝ်စိုပ်။) = “တောအရပ်ဝန်းကျင်မှ ဆင်စွယ်ကို အလိုရှိ၏။” || “လုဲကၠောံထုၚ်ထုၚ်၊ ဍာ်ကြုၚ်ဆဂၞိၚ်။ မိဟွံဒးၜိၚ်၊ စိုပ်ဒရိၚ်သြၚ်။” (လိက်ပတ္တစာရဳ။ နာဲထဝ်စိုပ်။) = “ခါးလောက်သာနက်သောချောင်းရေ­ လျှောက်၍ဖြတ်ကူးသွားရာ မယ်ပဋာစာရီသည် ရေကူးစရာမလိုဘဲ ကမ်းစပ်အရပ်ဝန်းကျင်သို့ရောက်၏။” || “ကလော်ကၠုၚ်စိုပ်၊ ပ္ဍဲဂြိုပ်ဒမၠု။ ဍေံကၠုၚ်ဂၠာဲသၟိၚ်၊ကြာဒမြိၚ်ဆု။” (လိက်သၟိၚ်ဇဲယဒတ္တ) = “ဘီလူးသည် မှောက်မိုက်သောတောသို့ လာရောက်ကာ မင်းကို သစ်တောဝန်းကျင်ကြားတွင် လိုက်ရှာ၏။”')
,(6771,3,1,'(ငါး၏) ကျောရိုးဆူးတောင်။','ဒရံၚ်က = ငါးဆူးတောင်။ ငါးကျောရိုးဆူးတောင်။')
,(6772,3,1,'(တောင်၏) အထွတ်။ ထိပ်။ အစွန်း။ (ပါဠိ—ကူဋ)',NULL)
,(6773,3,1,'တောင်အထွတ်။ တောင်အစွန်း။ တောင်ထိပ်။ (‘တၟအ်’ ကို ‘တောင်’ ဟုယူပါ။)','ဇာဒိသိုၚ်ဟီုကဵုကၠဵု “မတိုန်လ္တူဒရံၚ်တၟံတေံတုဲ မၠာ်မွဲပ္ဍဲဇရေၚ်ဇိုၚ်တၟံ ပၞောဝ်မပ္တံပြေၚ်ဂၠဴစိၚ်ချေံ မဂ္ၚေၚ်အာတံဂှ်ညိ။” (ဇ—၁၄၃။ အစွောံ။) = “မြေခွေး၊ သွားချေ။ တောင်ထိပ်­ရပ်၍တောင်ခြေရင်း­ လှည့်လည်ကုန်သော ဆင်၊ မြင်း၊ ကျွဲအစရှိသည်တို့ကို ကြည့်လော့။” (ညောင်ကန်) || “တေတေံဒရံၚ်တၟံလစံက်ဍာပ်ဍဴဂှ် နွံတဴ။” (ဇ—၄၈၅။ အစွောံ။) = “ဟိမဝန္တာတောင်၏ညိုသောပတ္တမြားဖြင့်ပြီးကုန်သော ရှုချင်ဘွယ်ရှိကုန်သော အထွဋ်တို့သည်ရှိကုန်၏။” (ညောင်ကန်) || “ကာလကောန်သၟိၚ်ဒကောတ် မဆင်ဍိုက်မဖက်ကဵုဒကုဲဂှ်တုဲ ညံၚ်ဒရံၚ်တၟံမဒေါမ်ဍိုက်ကီုဒကုဲဍောၚ်ၜိုတ်ဗွဲမလောန်။” (ဇ—၁၄၁။ အစွောံ။) = “ဖွတ်သည် ပုတ်သင်ကိုဖက်အံ့ဟု ရံခါဖိသလျှင်ကတည်း။ ပုတ်သင်အား တောင်ထွဋ်ဖြင့် ဖိသကဲ့သို့ဖြစ်၏။ ပုတ်သင်သည် ပင်ပန်းသည်ဖြစ်၍—။” (ညောင်ကန်)')
,(6774,3,4,'(အရိုး) ပြိုင်းပြိုင်းထသည်။','“မၞိဟ်ယဲဂှ် ဇြာဲဇြေဟ်တဴလောန် ဇုတ်သကဲဂမၠိုၚ် ဒရံၚ်ဒၟံၚ်ရ။” = “ထိုလူနာသည် အလွန်ပိန်လှီ၏၊ နံရိုးများပြိုင်းပြိုင်းထလျက်ရှိ၏။” || ‘ဃရံၚ်’ ဟုလည်းရေးသည်။')
,(6775,3,4,'(နားရွက်ကို) ကားသည်။','“စိၚ်ဇၟူဂှ် ညးဗလးနၚ်ရ။ စိၚ်ဇၟူဂှ် ကရေဲယဵုဒပှ်လပိုက်တိ ဓရံၚ်ကတောဝ်ၜါတုဲ ဒြေပ်သရဲကၠုၚ်ရ။” (ဇ—တေမဳ။ အစွောံ။) = “ထိုဆင်ပြောင်ကိုလွှတ်၏။ ဆင်ပြောင်သည် ဟစ်အော်၍ နှာမောင်းပင့်လျက် မြေကိုဆောင့်ခတ်ကာ နားရွက်နှစ်ဖက်ကိုကားလျက် အတင်းပြေးဝင်လာ၏။”')
,(6776,3,4,'(ကိုယ်ကို) မာအောင်တောင့်ခံသည်။','‘ဒြံၚ်’ ရှု။')
,(6777,3,4,'အနိုင်ကျင့်သည်။ အထက်တင်စီးပြုမူသည်။ စီးပိုးသည်။','“တြုံဝွံမဂံၚ်၊ ဒရံၚ်ဒရဴ။ကၠာဟွံမံၚ်စ၊ ပကြံကြတဴ။ ယာံမံၚ်စအဴ၊ ပညံၚ်ရဴဍိက်။” (လိက်နဲယသမုဒ္ဒြဳ။ အစွောံ။) = “ဤယောကျာ်းသည် အတင့်ရဲ၍ အထက်တင်စီးနိုင်လှ၏။ အတူမပေါင်းဖက်ရသေးဘဲလျက် အနိုင်ကျင့်၏။ အတူနေပေါင်းဖက်လျှင်ကား ကျွန်သဖွယ်ပြုလိမ့်မည်။”')
,(6778,3,4,'(လေ) တိုက်ခတ်သည်။','“ဗြဲသီုကျာမဇၞော် ဒရာတ်က္တဵုဒှ်—။” (ဇ—၄။ အစွောံ။) =“မိုးနှင့်တကွ လေပြင်းတိုက်ခတ်သည်။”')
,(6779,3,4,'(လည်နေသောအရာနှင့်) ပွတ်သည်။',NULL)
,(6780,3,16,'‘ဒရေပ်’ ရှု။',NULL)
,(6781,3,1,'အပြေးနှုန်း။ အမြန်နှုန်း။','“ပၞောဝ်ကဵုမၞိဟ်ဂမၠိုၚ် ဒရေပ်ဍေံဂှ် ခိုဟ်အိုတ်ရ။” =“လူများအနက် သူ၏အပြေးနှုန်းသည် အကောင်းဆုံးဖြစ်သည်။”')
,(6781,3,4,'ယူပြေးသည်။ အပြေးနှင်သည်။ အသော့နှင်သည်။','“ကမၠတ်ဂှ် ဒရေပ်ဏာဂၠဴအဲရ။” = “သူခိုးသည် ကျွန်တော့်နွားကိုယူပြေးသွားသည်။” || “(သေဋ္ဌဳ) ကာလမကလေၚ်စဴ ဒေါဝ်တြဴညာတ်ကမၠတ် ဟွံဒိုအ်ဒေါဝ်တြဴတက်ဒရေပ်ဂၠဴဗွဲပရဟ် စဴစိုပ်သ္ၚိဇကု—။” (ဇ—၁ဝ၃။ အစွောံ။) = “သူဋ္ဌေးသည် အိမ်ပြန်လာရာလမ်းခုလတ်­ ခိုးသူတို့ကိုမြင်၍ လမ်းခုလတ်­မရပ်နားဘဲ နွားကိုရိုက်ကာ အသော့နှင်၍ အိမ်သို့ပြန်ရောက်၏။” || “(ကုကောန်ၚာ်ဂှ် ကလော်ဗြဴဂှ် ဍေံစဟွံဂတာပ်တုဲ ဍေံဒရိပ်ဏာ—။” ဇ—၅၁၃။) = “ဘီလူးမသည် ကလေးငယ်ကို စား၍မမီသဖြင့် ယူပြေးသွား၏။” || ‘ဒြေပ်/ဒြိပ်’ (ကြိ) လည်းရှု။')
,(6782,3,1,'အိမ်နံရံကြွက်လျှောက်။ ကြွက်နံ။',NULL)
,(6783,3,1,'စကားအသွားအလာ။ စကားအရိပ်အခြည်။ အရိပ်အမြွက်။',NULL)
,(6784,3,1,'ကျီ။','ဒရာံသြောအ် = စပါးကျီ။')
,(6784,3,1,'ကျီ။','‘ဇရာံ’ ရှု။')
,(6785,3,4,'ခြောက်လှန့်သည်။ ပြေးအောင်မောင်းသည်။','“မၞိဟ်ဂမၠိုၚ် ဗိုၚ်ၜုၚ်ဒရာံကၠုၚ် ပ္ဍဲခြုံ ဒြာဲနန္ဒိယဂှ်ရ။” (ဇ—၃၈၅။ အစွောံ။) = “လူများသည် နန္ဒိယသမင်ရှိရာချုံံကို လာ၍ဝိုင်းရံရိုက်ပုတ်ခြောက်လှန့်၏။” || “မၞိဟ်တံဂှ် ဗိုၚ်ဒရာမ်ပၠောပ်ဏာ (ဒြာဲဂမၠိုၚ်) ပ္ဍဲခရိုၚ်ဥဒျာန်ဂှ်တုဲ ဒဝ်လဗိုန်လဝ်တရၚ်—။” (ဇ—၃၈၅။ အစွောံ။) = “လူတို့သည် သမင်အပေါင်းကို ဥယျာဉ်ခြံဝင်းထဲသို့ဝိုင်းရံခြောက်လှန့်မောင်းသွင်း၍ ဥယျာဉ်တံခါးကို ပိတ်လိုက်ကြကုန်၏။” || “မၞိဟ်ဂမၠိုၚ်ၜုၚ်ဒရာမ်တုဲ ဒြာဲဂှ် ဂၠာဲရံၚ်ဂၠံၚ်တိတ်ရ။” (ဇ—၅၁၃။ အစွောံ။) = “လူများသည် (တောချုံတို့ကို) ရိုက်ပုတ်ခြောက်လှန့်ကြရာ သမင်သည် ထွက်ပြေးရန်လမ်းကိုရှာ၏။”')
,(6786,3,4,'၁။ စည်းဝေးသည်။ ဆွေးနွေးသည်။ နှီးနှောသည်။ (ပါဠိ—သာကစ္ဆတိ)','“(ဒေဝတဴတၠဣဒ္ဓိတံဂှ်) မလောပ်အာဒရီု ပ္ဍဲသဘၚ်ကောန်ဒေဝတဴဂမၠိုၚ်တုဲ မဟွံဂွံမၠာ်မွဲဒဒိုက်တြုံမပြဲရောၚ်သ္ဂးဟာ။” (ဇ—၁၉၄။ အစွောံ။) = “တန်ခိုးရှင်နတ်တို့သည် နတ်များသဘင်­ စည်းဝေးရန်ဝင်သွားသဖြင့် ဤယောကျာ်းမြတ်၏ ဆင်းရဲဒုက္ခကို မကြည့်ရှုရခြင်းပေလော။” || “ယြဴဇြပ်ဒရီုမွဲဂှ် တၠပညာတံ ဟွံဂွံဆိုက်ညန်ဂှ် ဟွံဒှ်ဇြပ်ဒရီုရ။” (ဇ—၅၃၇။ အစွောံ။) = “ပညာရှိတို့ မတက်ရောက်သောသဘင်သည် စုဝေးဆွေးနွေးရာသဘင်မမည်။” (ဇြပ်ဒရီု = စည်းဝေးတိုင်ပင်ရာခန်းမ (အစည်းအဝေးခန်းမ) || “ပိုဲဓရီုဂၠုအာတုဲရ။ စဴကၠာရ။” (အကြီုရာဇာဓိရာဇ်) = “ငါတို့စည်းဝေးကြသည်မှာ မိုးချုပ်သွားပြီ။ ပြန်ပါဦးမည်။”')
,(6786,3,4,'၁။ စည်းဝေးသည်။ ဆွေးနွေးသည်။ နှီးနှောသည်။ (ပါဠိ—သာကစ္ဆတိ)','“ထပိုဲဗုဒ္ဓသာမိဂှ် ကောန်တၠညးစိၚ်ဗ္တာၚ်သၟိက်ဓရီုစၚ်ခြၚ်ညိ။” (အကြီုရာဇာဓိရာဇ်) = “ကိုရင်ဗုဒ္ဓသာမိကို ဆင်ဖြူရှင့်သားတော် ဆွေးနွေးတိုင်ပင်လိုပါသည်။”')
,(6786,3,4,'၂။ ပေါင်းဖက်သည်။ မှီဝဲဆည်းကပ်သည်။','“ပူဂဵုမဒှ်မိတ်ဂှ်တုန် ဂကောံပူဂဵုသမၠီုဂှ် ဍေံဟွံဒရီု။” (ဇ—၄၇၃။ အစွောံ။) = “အဆွေခင်ပွန်းဖြစ်သောပုဂ္ဂိုလ်သည် သူမိုက်နှင့်တကွ မပေါင်းဖက်မဆည်းကပ်။”')
,(6786,3,4,'၃။ စုရုံးသည်။ စုဝေးသည်။','“ဒၞာဲထာန်ၜိုပ်ၜါမဒရီုဒၟံၚ်ဂှ် ထာန်ဒေါဝ်ဂၞဴဗတဳဂှ်ဟေၚ် အနာဂတ်သဒှ်ဍုၚ်ဇၞော်ရာဇာဓနဳမွဲ။” (ရာဇာထ္ၜုတ်) = “ဟင်္သာနှစ်ခုတို့စုဝေးနေရာ သဲသောင်ပြင်လယ်အရပ်သည် အနာဂတ်­ မင်းနေပြည်တော်မြို့ကြီးဖြစ်လတ္တံ့။”')
,(6787,3,4,'အနားကွပ်သည်။',NULL)
,(6787,3,1,'၁။ အနားအကွပ်။ အနားအစွန်း။','ဒရီုန = တောင်းအနားအကွပ်။ || ဒရီုတၟအ် = ကျောက်အနားအစွန်း။ || ဒရီုယာတ် = စောင်အနားသတ်။')
,(6787,3,1,'၂။အဝန်းအဝိုင်း။ အကြား။','“ပ္ဍဲလတူဇံၚ်မောဝ် သၟဝ်ဒရီုကၞာၚ်အံၚ်ရေၚ် ဖျေၚ်ဖျေံက္ဍိုပ်ဒိုဟ်သၟဝ်ကျာ နသတိက်မဟွံဂွံက္တဵုဒှ်ၜါဝါပၠန်ဂှ် ကျာ်တြဲတၠလျးတရဴသတိက်ရ။” (ဇ—၉၅။ အစွောံ။) = “အစုံဖြစ်သော အင်ကြင်းပင်ပျိုတို့၏အကြား­ မြောက်သို့ဦးခေါင်းပြု၍ ခင်းအပ်သောညောင်စောင်း­ မထသောကျိန်းစက်တော်မူခြင်းဖြင့် (မြတ်စွာဘုရား) ကျိန်းစက်တော်မူ၏။” (ညောင်ကန်) || “ယွံမၞးတံ၊ တၞံဆုမဒၟံၚ်ပ္ဍဲဝါတဂါ မွဲတၞံၜါတၞံဂှ် မၞးတံလ္ပဒၟံၚ်ညိ။ ပ္ဍဲဒရီုဓိတာန်ဝုတ်ဒိုဟ်အဲဝွံဂှ် မၞးတံဒၟံၚ်ရ။” (ဇ—၇၄။ အစွောံ။) = “အချင်းတို့၊ လွင်ပြင်အရပ်­တည်သော တစ်ပင်နှစ်ပင်သောသစ်ပင်တို့­သင်တို့မနေကြကုန်လင့်။ ငါ၏အင်ကြင်းပင်ပတ်လည်အဝန်းအဝိုင်း­ သင်တို့နေကြကုန်လော့။”')
,(6787,3,1,'၃။ ကျက်စားရာနယ်မြေ။','“ပ္ဍဲဂြိုပ်ဂၞိၚ်ဇီု၊ ဒရီုကၟီကၠ။” (လိက်သၟိၚ်အသး။ နန္ဒသာရ။) = “ဝံ၊ကျားစသည်တို့၏ ကျက်စားရာနယ်မြေဖြစ်သော တောမြိုင်နှင့်ရွှံ့ညွန်တောတို့­။” || ‘ဒမြီု’ (န) လည်းရှု။')
,(6788,3,4,'စည်းဝေးတိုင်ပင်သည်။ ဆွေးနွေးသည်။','“သာ်ဝွံမၞိဟ်ကၠတ်စတံဂှ် ကၠုၚ်ဒရီုဟီုရအဴ” (ဇ—၂၆။ အစွောံ။) = “ဤကဲ့သို့ခိုးသူတို့သည်လာ၍ စည်းဝေးတိုင်ပင်ကြကုန်၏။” || “ညးမဒှ်ဓမ္မကထိုက်ဂှ် နမဒရီုဟီုဓဝ်ဂှ် တိုၚ်ဟွံပေၚ်တရိုပ်စိုတ်။” (ဇ—၄ဝ၂။ အစွောံ။) = “တရားဟောပုဂ္ဂိုလ်သည် (တရားဓမ္မ) ဆွေးနွေးခြင်းဖြင့် မရောင့်ရဲခြင်း။” (ညောင်ကန်) || ဒရှ်စာၚ် = ကြက်အတက်။ || “သပဝ်တက်သၟဟ်၊ ကဵုဒရှ်ရ။” (လိက်သၟိၚ်ဇဲယဒတ္တ) = “ဂဠုန်သည် အတက်ဖြင့်ရိုက်ခတ်၏။”')
,(6789,3,4,'တွန်းသည်။','“(ဗြဴဂှ်) ဍေံဒရိုဟ်ဖျေံဏာ (ဗောဓိသတ်) ပ္ဍဲလပါ်တၟအ်တေံရ။” (ဇ—၁၉၃။ အစွောံ။) = “မယားသည် ဘုရားလောင်းအား တောင်ကမ်းပါးပြတ်သို့တွန်းချလိုက်၏။” || “ဍိက်ဗြဴဂှ် တဲဍေံၜါ သီုဒြဟတ် ရပ်ပ္ဍဲတကေတ်ဍုတ်ၚဴတြုံကမၠတ်ဂှ်တုဲ ဇရိုဟ်ဖျေံပ္ဍဲကမၠိုၚ်ဂှ်ရ။” (ဇ—၄၁၉။ အစွောံ။) = “ထိုကျွန်မသည် လက်နှစ်ဖက်တို့ဖြင့် ထိုခိုးသူကိုတင်သား­ကိုင်၍ ရေတွင်းထဲသို့ တစ်အားတွန်းချလိုက်၏။” || “ညးသ္အာၚ်မွဲကၠုၚ်တုဲ ရပ်မၚ်ဗၠာဲမာဃဂှ်တုဲ ဇရိုဟ်ဏာကၠေံတုဲ ဂ္ဇအ်ဒၞာဲဂှ်ရ။” (ဇ—၃၁။ အစွောံ။) = “အခြားသူတစ်ယောက်လာ၍ မာဃလုလင်ကို ကိုင်၍တွန်းလိုက်ပြီးလျှင် ထိုနေရာ­ထိုင်၏။” || “(ဍိက်တအ်ဂှ် ကုကောန်ဗြဴသေဋ္ဌဳဒမြိုဟ်ဂှ်) ဇရိုဟ်ထောံကၠေံပ္ဍဲဍာ်တုဲ သီုဖအိုတ်တိုန်ကၠုၚ်ရ။” (ဇ—၆၃။ အစွောံ။) = “ကျွန်အမှုလုပ်တို့သည် ကြမ်းကြုတ်သောသူဋ္ဌေးသမီးအား မြစ်ရေထဲသို့တွန်းပစ်ပြီးလျှင် အားလုံးတက်လာကြကုန်၏။” || “ဗှ်ေဓရိုဟ်ဖတုံဖျေံအဲ ပ္ဍဲဗပါ်တၟအ်ဂှ် ဗှ်ေဝိုတ်အာရဟာ။” (ဇ—၁၉၃။ အစွောံ) = “တောင်ကမ်းပါးပြတ်­ ငါ့ကို နင်တွန်းချပစ်ခဲ့သည်ကို နင်မေ့သွားပြီလား။”')
,(6790,3,1,'ကနုတံ။ သံဃာတော်များ ကုဋီတက်ရာတွင် သုံးသောတုတ်ချောင်း။','“မပ္တံကဵုဒရိုအ်ကြံၚ်မ္ၚိုဟ်။” (ပြကိုဟ်ဒ္ဂေတ်ပဋိပတ်သာမဏဳ။ မာံရွှေငိုး။) = “မာကြမ်းသောကနုတံစသော။”')
,(6791,3,1,'‘ဒြဟတ်’ ရှု။',NULL)
,(6792,3,4,'၁။ မှောင်စေသည်။ မှောင်မိုက်စေသည်။','“သၟိၚ်ဂိတု သီုအရံၚ်အံၚ်သူလျးဂှ်ဒှ်တုဲ ရာဟုစောန်စိုတ်တုဲ ရပ်ဒလုကၠေံပၠန်ရောၚ်သွံ။” (ဇ—၄ဝ၆။ အစွောံ။) = “အလင်းရောင်ခြည်နှင့်တကွသောလမင်းကို ရာဟုသည်ငြူစူ၍ ဖမ်း၍မှောင်မိုက်စေ၏။”')
,(6792,3,4,'၂။ သတိလစ်စေသည်။ သတိလစ်ဟင်းအောင်လုပ်သည်။','“ဍေံဒလုလဗြဴဗျုဂှ်တုဲ ကေတ်ဏာကၠေံသၠုဲညးရ။” = “အဖွားအိုကို သတိလစ်ဟင်းအောင်လုပ်ပြီး အဖွားအို၏ပိုက်ဆံကို သူအလစ်သုတ်သွားသည်။”')
,(6792,3,1,'အမှောင်။အမိုက်မှောင်။','“(သၟိၚ်သပဝ်) က္တဵုဗဒှ်ဒလုပၠန် ဂၠုအာညံၚ်လတိုပ်—။” (ဇ—၃၆ဝ။ အစွောံ။) =“ဂဠုန်မင်းသည် မိမိအာနုဘော်အားဖြင့် အမိုက်မှောင်ကိုပြု၍—။” (ညောင်ကန်)|| ‘ဒမၠု’ (န) လည်းရှု။')
,(6793,3,1,'မိုက်မှောင်သောစိတ်။ မောဟဖုံးလွှမ်းသောစိတ်။','‘ဒမၠုစိုတ်’ (န) ရှု။')
,(6794,3,4,'မျက်စိကိုလှည့်စားသည်။ မျက်လှည့်ပြသည်။','“ဍေံမန်ဒလုမတ်ရောၚ်—။” (ဇ—၄၈၉။ အစွောံ။) = “မန္တရားကိုမန်း၍ မျက်စိကိုလှည့်စား၏။” || ‘ဒမၠုမတ်’ (နဝိ) လည်းရှု။')
,(6795,3,4,'၁။ အလျားလိုက်ထိုးသွင်းသည်။','“ဒုန်တၞုၚ်ဂမၠိုၚ်ဂှ် ဒလူပၠောပ်လဝ်သၟဝ်သ္ၚိညိ။”= “ဝါးချောင်းများကို အိမ်အောက်တွင် အလျားလိုက် ထိုးသွင်းထားလိုက်ပါ။”')
,(6795,3,4,'၂။ရှေ့သို့အလျားလိုက် ဆွဲထုတ်သည်။—တွန်းသည်။','“ပတ်ကအ်စဏာဒၟိက်ဂှ်တုဲ ဗှ်ေတံဒလူပ္တိတ်ကၠေံညိ။” (ဇ—၄၉၇။ အစွောံ။) = “ထိုဒွန်းစဏ္ဍားယုတ်အား လည်ပင်းညှစ်၍ သင်တို့ဆွဲထုတ်ပစ်ကြကုန်လော့။” || “သာမဏဳဂှ် — စုက်ဒလူဏာထေရ်ဗျုမဒှ်မဂှ်ရ။” (ဇ—၃၁၂။ အစွောံ။) =“သာမဏေသည် အဘဖြစ်သောရဟန်းအိုကြီးကို (ခေါင်းနှင့်တိုက်၍) ရှေ့သို့တွန်းထိုးလိုက်၏။”')
,(6795,3,4,'၃။ ရှေ့သို့အလျားလိုက် အရှိန်ဖြင့်ရွေ့လျားသည်။','“(ကၠိက်ဂှ်) ဒြေပ်ဒလူကၠုၚ်ဒလူအာ။” (ဇ—၁၈၆။ အစွောံ။) = “ထိုဝက်သည် အရှိန်ဖြင့် ထိုမှဤမှပြေး၏။” || “ကကၟက်အာကြဴ ကဗြဴအာဂတ ကဗြဴဂွံသမူဇာတုဲ ကဗြဴဆေဝ်ကၠေံ ကကၟက်ဓလူအာဒးဇာ—။” (ဇ—၂၁၆။ အစွောံ။) = “ငါးဖိုသည် နောက်မှသွား၍ ငါးမသည် ရှေ့မှသွား၏။ ငါးမသည် ကွန်နံ့ရသည်ရှိသော် ကွေ့ရှောင်ဖယ်သွား၏။ ငါးဖိုသည်ကား အရှိန်ဖြင့်ရှေ့တိုး၍သွားရာ ကွန်­ငြိ၏။”')
,(6796,3,4,'ဒယီးဒယိုင်သွားသည်။','“သုရာမ္ဂးဂှ် ယာံညးမဒးသုၚ်ဍေံတုဲ ဇကုကွာ်ဒလူတဆူအာ ဇၟာပ်ဒၞာဲရောၚ်။” (ဇ—၅၁၂။ အစွောံ။) = “သုရာမည်သည်ကို သောက်သောသူသည် နေရာတကာ ကိုယ်ဒယီးဒယိုင်ဖြင့် လျှောက်သွား၏။” || ‘ဆူဒလူ’ လည်းရှု။')
,(6797,3,4,'‘ဂလုက်’ ရှု။',NULL)
,(6798,3,4,'လှုပ်ရှားသည်။',NULL)
,(6799,3,4,'(ထိုင်ရာ၊ လျောင်းရာမှ) ထသည်။','“ညးဗၞိက်လီုမလုလန်ဂှ် ထေဝ်ကၠေံထးဂှ်ပ္ဍဲတိတုဲ သီုပၞတ်မဒလိုက်က္တဵုအာရ။” (ဇ—၃။ အစွောံ။) = “လောဘရမ္မက်ကြီးသော ထိုရွဲကုန်သည်သည် ထိုခွက်ကို မြေ­လွှင့်ပစ်၍ စိတ်ဆိုးလျက် ထသွားလေ၏။” || “ဍေံညာတ်အ္စာဍေံကၠုၚ်ဗက် ခြုဟ်ဍေံဒလိုက်က္တဵုရ။” = “သူ့ဆရာလာသည်ကို သူမြင်သည်နှင့် ရုတ်တရက်သူထလိုက်သည်။” || “နူဂယးပြဟ်ဟေၚ် ဂလိုက်က္တဵုတုဲ—။” (ဇ—၄၄၆။ အစွောံ။) = “နံနက်စောစောကသာလျှင် ထ၍—။” (ညောင်ကန်)')
,(6800,3,4,'ရောဂါပျောက်ခါစဖြစ်သည်။ နာလန်ထသည်။','ညးမဒလိုက်က္တဵုနူယဲ= ရောဂါပျောက်စလူ။ နာလန်ထသူ။ (ပါဠိ—ဥလ္လာယ)')
,(6801,3,4,'(ရဟန်းသံဃာ) ဝါတွင်းမှထွက်သည်။ ဝါထွက်သည်။',NULL)
,(6802,3,1,'၁။ လေးလံထိုင်းမှိုင်းခြင်း။ အဆီယစ်ခြင်း။','“မိသီုကောန်ဗြဴဟာပ်စပုၚ်သွမွဲစွံတုဲ (မိဍေံဂှ်) တၞဟ်နလဒံကၠေံဒလိုက်ဒလာၚ်ကာယရ သတိက်ဒၟံၚ်ရ။” (ဇ—၁၇၁။ အစွောံ။) = “(မိခင်နှင့်သမီးသည် ထမင်းဟင်းအတူစားကြပြီးနောက်) ထမင်းဆီယစ်ခြင်း (ခန္ဓာကိုယ်၏လေးလံထိုင်းမှိုင်းခြင်း) ကို ဖြေဖျောက်အံ့သောငှာ အိပ်လျက်နေ၏။” (ညောင်ကန်)')
,(6802,3,1,'၂။ ပူပန်ခြင်း။ စိုးရိမ်ခြင်း။ ဆင်းရဲခြင်း။ ပင်ပန်းခြင်း။ (ပါဠိ—ဒရထ)','“ယွံမပိုဲ၊ ဣသိဝွံ —လမုဟ်ပြိုက်တဴဂှ်ဒှ်တုဲ ပ္ဍဲပဏ္ဏသာပိုဲဝွံ ကဵုလုပ်ညိ။ လမုဟ်ကီု ဒလိုက်ဒလာၚ်ကီု လလံကၠေံညိ။” (ဇ—၂၅ဝ။ အစွောံ။) = “ဖခင်၊ ဤရသေ့သည် ချမ်းအေးခြင်းဘေးသည် နှိပ်စက်အပ်သည်ဖြစ်၍ဤကျောင်းသို့ဝင်စေသတည်း။ အလုံးစုံသော ချမ်းခြင်းကို၄င်း ဆင်းရဲခြင်းကို၄င်း ဖျောက်စေသတည်း။” (ညောင်ကန်) || “ဟိုတ်နူမဂွံသုၚ်လဝ် ရှ်ဓဝ်မပြဲတုဲ ဒလိုက်ဒလာၚ်ပ္ဍဲကိလေသဂှ် ဟွံဂွံဒှ်ရောၚ်။” (ဇ—၃၆၃။ အစွောံ။) = “(တရားအမြိုက်အရသာကို) သောက်သောသူသည် ကိလေသာဟူသော ပူပန်ခြင်းမရှိသည်ဖြစ်၏။” (ညောင်ကန်) || “(ဗောဓိသတ်) တၞဟ်နသၟိက်လလံကၠေံဒလိုက်ဒလာၚ်ဂှ် က္တဵုဒက်ဒၟံၚ်ထဝဲါရ။” (ဇ—၃၇၈။ အစွောံ။) (လလံကၠေံဒလိုက်ဒလာၚ် = ပူပန်ခြင်းကိုငြိမ်းစေသည်) = “ဘုရားလောင်းသည် — အတန်ငယ်အိပ်၍ ငြိမ်းသောပူပန်ခြင်းရှိသည်ဖြစ်၍ ထ၍ကျောက်ဖျာ­ ထက်ဝယ်ဖွဲ့လျက်နေ၏။” (ညောင်ကန်) || “ကိလေသဒရာထာနံ၊ န်ဒလိုက်ဒလာၚ် ဒတူတလာဲ ဂမ္တဴဂမ္တာန်ကိလေသဂမၠိုၚ်။” (ဓမ္မဒဳပနဳ။ မာံရွှေငိုး။) = “ကိလေသာ၏ဆင်းရဲခြင်း၊ ပူပန်ခြင်း၊ ပူလောင်ခြင်းများ။”')
,(6803,3,4,'တုန်လှုပ်သည်။ လှုပ်ရှားသည်။','“ပ္ဍဲကာလဗောဓိသတ် စှ်ေတန်ပဋိသန္ဓိဂှ် စှ်လ္ၚီလောကဓါတ် ချဳသရပ်ဒလိုက်ဒလာၚ်တဴရ။” (အနာဂတာဝၚ်။ လောကသဳရိ။) = “ဘုရားလောင်းပဋိသန္ဓေတည်သောကာလ­ လောကဓါတ်တိုက်တစ်သောင်းသည် လှုပ်ရှားတုန်လှုပ်၏။” || “ဥပ္ပးဂှ် ဇၞော်ပၟဝ်တဴဓဝ်ဘာဝနာ မၞုံကဵုအိန်ရဳ ဟွံဂွံချဳဒၠိုက်ဒၠာၚ်ဂှ် ဒေဝတဴတအ်ညာတ်တုဲ သ္ဍိုက်မၠိုက်တဴရ။” (သၚ်္ခါရဘေဒနဳ။ ဝိန္ဒသာရ။) = “မလှုပ်မရှက် ငြိမ်သက်သောဣန္ဒြေရှိသော၊ ဘာဝနာတရားကို ပွားများနေသော ထိုသီတင်းသည်ကိုမြင်၍ နတ်တို့သည် ချစ်ခင်နှစ်သက်ကုန်၏။” || “ၜိုန်ကျာဇီုလပိုက်လေဝ် ဟွံချဳဒရာၚ်ဒလိုက်ဒလာၚ်။” (သုဓမ္မဒေသနာ။ဂရိုက်သာံ။) = “လေတိုက်ခတ်သော်လည်း မလှုပ်မရှက်မတုန်မလှုပ်။”')
,(6804,3,4,'လှုပ်ရှားသည်။ ရွေ့ရှားသည်။',NULL)
,(6805,3,1,'၁။ တင်ပုတ်ပလ္လင်။',NULL)
,(6805,3,1,'၂။ ဒေါင်းလန်း။ ပန်းကလပ်။ ကြုတ်။ ပန်းတောင်း။ (ပါဠိ—စၚ်္ကောဋက)','ဒလာၚ်ဂဥုဲ = ဆေးပန်းတောင်း။ (ပါဠိ—ဘေသဇ္ဇစၚ်္ကောဋက) || “(ဗောဓိသတ်သဳဓတ်) တတ်သော်ဝန်ဇတာ ပတ္တနာပအဓိထာန်တုဲ ဗိုတ်ပ္တိုန်နာသော် လတူအကာသရ။ သၟိၚ်အိန်ဒုၚ်ကေတ်ကဵုဒလာၚ်ထဝ်တုဲ—။” (ရာဇာဝံသသံခိပ်။ အစွောံ။) = “အလောင်းတော်သိဒ္ဓတ္တသည် ဆံကျစ်တော်ကိုဖြတ်ပြီးလျှင် ဆုတောင်းအဓိဋ္ဌာန်၍ ကောင်းကင်ထက်သို့ ပစ်တင်၏။ သိကြားမင်းက ရွှေပန်းတောင်းဖြင့် ခံယူလိုက်၏။”')
,(6805,3,1,'၃။ မျက်နှာပြင်။',NULL)
,(6805,3,1,'၄။ သင်းချိုင်းအုတ်ဂူ။',NULL)
,(6806,3,1,'နဖူးပြင်။','“လပုဟ်တဲစှ် ပ္ဍဵုလဝ်လတူဒလာၚ်ကၞေၚ် လ္ၚောဝ်ဒိုဟ်စှ်တုဲ—။” (ဇ—နာရဒ။ အစွောံ။) = “လက်ဆယ်ချောင်းကို နဖူးပြင်ထက်တင်လျက် အရပ်ဆယ်မျက်နှာကို ရှိခိုး၏။”')
,(6807,3,4,'သယ်သည်။ လူနှစ်ယောက် တစ်ဖက်ဆီပင့်၍သယ်သည်။','“ဇွသုန္ဓရဳဂှ် စုတ်ပ္ဍဲဇံၚ်တုဲ ဒလိၚ်ပၠောပ်ပ္ဍဲဍုၚ်သာရဝှ်—။” (ဇ—၂၈၅။ အစွောံ။) = “သုန္ဒရီ၏အလောင်းကို ညောင်စောင်း­တင်၍ သာဝတ္ထိမြို့သို့ ထမ်း၍သွင်းကုန်၏။” || “ကဂှ် တမ္ၚာတံဂွံတုဲ တၞဟ်နသွံဂှ် ဒလိၚ်ပၠောပ်ဏာဍုၚ်ရ။” (ဇ—၂၈၈။ အစွောံ။) = “တံငါတို့သည် ထိုငါးကိုရ၍ ရောင်းရန်အတွက်မြို့သို့သယ်သွင်းသွား၏။”')
,(6807,3,1,'ထမ်းစင်။ လူထမ်းယာဉ်။','ဍိုက်ဓလိၚ် = ထမ်းစင်စီးသည်။ || “သီုသေထဳလ္ၚီ ကွဳကဵုကွဳ ဓလိၚ်ကဵုဓလိၚ် အလာံကေုာံဗဵုဂမၠိုၚ် — ဇက်ဂၠောဲတသဵုအာ ဍုၚ်မိတ္ထဵုရ။” (ဇ—မဟောဟ်သဓ။ အစွောံ။) = “သူဋ္ဌေးတစ်ထောင်နှင့်တကွ လှည်းလှည်းချင်း ထမ်းစင်ချင်း ပြည့်နှက်လျက် အလံတော်များနှင့် ဗိုလ်ပါအခြံအရံများဖြင့် မိတ္ထိလာမြို့သို့ စုရုံးထွက်ချီသွားကြကုန်၏။” || “သီုဂၞကျာ်လေဝ်၊ ဨကရာဇ်ၜါ။ တူဒလိၚ်ကွေံ၊ ဒ္ၚဳတိုန်က္ဍိုက်အာ။” (လိက်ဇိဝှစက္က) = “မင်းမိဖုရားနှစ်ပါးတို့သည် ထမ်းစင်ပေါ်­ အသာအယာတက်စီးသွားကြ၏။”')
,(6808,3,1,'ငါးရှဉ့်။',NULL)
,(6809,3,4,'ယက်ကန်းချည်ရှယ်သည်။','“မၚ်ဗၠာဲဘိမ္ဗသေဏဒလုၚ်ဒၟံၚ်တုတ်” (ဇ—၈ဝ။ အစွောံ။) || ‘ဂလုၚ်တုတ်’ ဟုလည်းရေးသည်။')
,(6810,3,1,'ထမ်းပိုး။','“ဂွံဖျုန်ဒြာဲတုဲ မွဲဒလေၚ်ဂၠေၚ်ဖျဴရ။” (ဇ—၅၁၅။ အစွောံ။) = “သမင်သားကိုရ၍ တစ်ထမ်းထမ်း၍ ယူပြန်၏။” || “ဒးယိုက်ဒးဂၠေၚ်၊ ဓလေၚ်ညးမှာ။” (လိက်လက္ခဏပိ) = “သူတစ်ပါး၏ထမ်းပိုးကို မချွတ်သယ်ရထမ်းရ၏။” || “ဂၠေၚ်ယိုက်ဖျဴဟေၚ်၊ ဆဂလေၚ်ပါ။” (လိက်ဝိဓူရ) || ‘ဂၠေၚ်’ (ကြိ) လည်းရှု။')
,(6811,3,1,'မြက်ရိတ်သမား။ မြက်ထမ်းသမား။','(မၚ်ဗၠာဲအာစိုပ်ဒလေၚ်ကၟတ်တံ “တ္ၚဲဝွံကၟတ်မွဲမွဲစန် မၞးတံပရအ်ကဵုအဲညိ။—” မၚ်ဗၠာဲဂး “ဂွံရ” ဒလေၚ်ကၟတ်တံဂး။) (ဇ—၄။ အစွောံ။) = (လုလင်သည်သွား၍) မြက်ရိတ်ယောကျာ်းတို့ကို “ယနေ့ငါ့အား မြက်တစည်းတစည်းစီ ပေးကုန်လော။—” ဟုဆို၏။ မြက်ရိတ်ယောကျာ်းတို့သည် “ကောင်းပြီ” ဟုဝန်ခံ၍—။ (ညောင်ကန်)')
,(6812,3,1,'ဝန်ရှိသောထမ်းပိုး။','ဒၠေၚ်ဒၟာ်ၜါဒိုဟ် = နှစ်ဖက်ဝန်ရှိသောထမ်းပိုး။ (ပါဠိ—ဥဘတောကာဇ)')
,(6813,3,1,'ထင်းခွေ၍ထမ်း၍ အသက်မွေးသူ။ ထင်းခွေယောကျာ်း။','“မၚ်ဗၠာဲဒလေၚ်အှ်ောမွဲဂှ် ဂၠေၚ်အှ်ောကဵုသၟိၚ်လၟိုန်ရ။” (ဇ—၂၈၄။ အစွောံ။) = “တစ်ယောက်သောထင်းခွေလုလင်သည် မင်းအတွက် ထင်းတို့ကို အမြဲထမ်း၍ပေး၏။”')
,(6814,3,1,'ချူတံ။ တံချူ။','“(ဣသိတၞဟ်နအာဂၠာဲသတ်ဆု) သီုဒလောၚ်ပရေဟ်ဂိုၚ်ကေတ်တုဲ (အာရ။)” (ဇ—၁၇၃။ အစွောံ။) = “ရသေ့သည် သစ်သီးရှာထွက်ရန်အလို့ငှာ တံချူနှင့်ခြင်းတောင်းကို ယူ၍သွား၏။” || “ဂိုၚ်ကေတ်တွဵု၊ နပရေဟ်၊ ဒလောၚ်တုဲ နဇကုမွဲဟေၚ်လုပ်အာဂြိုပ်ရ။” (ဇ—၅၁၉။ အစွောံ။) = “တူရွင်း၊ ခြင်းတောင်း၊ တံချူတို့ကို ယူဆောင်၍ မိမိတစ်ယောက်တည်း တောသို့ဝင်သွား၏။” || “ဂွံနဂလောၚ်၊ ဂၠောၚ်ပ္ကဴနတဲ။” (လိက်ပဒုမဝတဳ) = “တောင်းနှင့်တံချူကိုရပြီး ပန်းများကို လက်ဖြင့်ချူ၏။” || ‘ဂၠောၚ်’ (ကြိ) လည်းရှု။')
,(6815,3,4,'ကြိတ်သည်။ (ပါဠိ—ခေါဒတိ)',NULL)
,(6816,3,1,'သလဲသီး။',NULL)
,(6816,3,4,'စိုက်ကြည့်သည်။ ပြူးကြည့်သည်။','ဒလန်မတ် = မျက်လုံးပြူးကြည့်သည်။ || “ကၠဂှ် ဓလန်ပတိုန်မတ် သ္ၚဳကၠိက်တံဂှ်ရ။” (ဇ—၄၉၂။ အစွောံ။) =“ကျားသည် မျက်လုံးတို့ကိုပြူး၍ ဝက်တို့ကိုစိုက်ကြည့်၏။”')
,(6816,3,3,'(မျက်လုံး) ပြူးသော။','မတ်ဒလန် = မျက်လုံးပြူးသည်။ || ‘မတ်ဗှ်ေလေဝ်ဒလန်။’ (ဇ—မဟောဟ်သဓ။ အစွောံ။) =‘သင့်မျက်လုံးလည်းပြူး၏။’ || “အာဒှ်ကလော်၊ မတ်ဇၞော်ဒလန်။” (လိက်ပ္တံပါရမဳ။ အစွောံ။) =“ဘီလူးဖြစ်၍ မျက်လုံးကြီး၍ပြူး၏။” || ‘မတ်ဍေံတံဒလန်—။’ (ဇ—၄၉၇။ အစွောံ။) || “(လကိုဟ်ဗြဴဂှ်) သော်ဂှ်လေဝ်ကရန်၊ မတ်ဂှ်လေဝ်ဓလန်၊ ဂၞဴလေဂဗှ်ေ၊ ဂၞေဟ်တိတ်ကဝါၚ်။” (သၠပတ်စန္ဒဝတဳ) = “ဘီလူးမသည် ဆံပင်ကလည်းတွန့်ကောက်၊ မျက်လုံးကလည်းပြူး၊ ဗိုက်ကလည်းပူ၊ အစွယ်ကလည်း ကော့ကွေးထွက်နေ၏။”')
,(6817,3,4,'တိမ်းစောင်းသည်။ ချွတ်ယွင်းသည်။','“(တၠပညာဝိဓူရဂှ်) ညးနွံသဳလာ၊ ဟွံဂွံဒလိန်၊သီုအိန်ရိယာ။ ညံၚ်လအာစိ၊ မူဏိရာဇာ။” (လိက်ဝိဓူရ) = “ဝိဓူရပညာရှိသည် မချွတ်မယွင်းသောသီလနှင့်ဣန္ဒြေရှိ၏၊ မုနိရာဇာဘုရားရှင်အလားဖြစ်၏။”')
,(6818,3,4,'မိတ်ဆွေအဖြစ် ရင်းနှီးကျွမ်းဝင်သည်။ ကြင်ဖော်ကြင်ဖက်အဖြစ်ချစ်ကျွမ်းဝင်သည်။','“မိသုဝဏ္ဏ၊ ၜါတလညး။ ဒလိန်ဒလာဲ၊ ဟွံမိက်ရှာဲပြး။” (လိက်သၟိၚ်အသး။နန္ဒသာရ။) = “မယ်သုဝဏ္ဏနှင့်ဘုရင်တို့နှစ်ဦးသည် မကွဲမကွာလို ချစ်ကျွမ်းဝင်ကြကုန်၏။” || “ဂၠိုၚ်ဂိတုတ္ၚဲ၊ အဲၜါကဵုနာဲ။ ဒလိန်ဒလာဲ၊ နာဲသၟုဲလေၚ်။” (လိက်ဗြရတ်ဣဏၚ်ကၚ်ရဳ) = “ရက်လများစွာပင် ငါနှင့်သခင် ချစ်သူနှစ်ဦးတို့သည် ကြင်ဖော်ကြင်ဖက်အဖြစ် ချစ်ကျွမ်းဝင်ကြ၏။” || “ဒလိန်ဒလာဲ၊ နာဲကဵုမှာယျ။” (လိက်ဗြရတ်ဣဏၚ်ကၚ်ရဳ) || “ဗြဴဂှ်မဂး၊ ဇၞော်ကၠးရနာဲ။ — ယဝ်သ္ဂောံဆာန်ကၟိန်၊ ဓလိန်ဓလာဲ။ ညိဟွံဂွံဒိုက်၊ သိုက်ဘိုက်ရာၚ်ချာဲ။” (လိက်ကကၠာ်။ ကောန်ဍး။) = “ထိုမိန်းမမျိုးကား ဂုဏ်ကြီးမားသူတည်း၊ အကယ်၍ချစ်ခင်စုံမက် အကျွမ်းဝင်ပေါင်းဖက်ရသော် လုံးဝမဆင်းရဲဘဲ ချမ်းသာကြွယ်ဝတင့်တယ်ပါလိမ့်မည်။”')
,(6819,3,4,'လျှိုသည်။','“ဇုက်ဂှ် ချအ်စုတ်ပ္ဍဲထၟောၚ်ဒုန်ဂှ်တုဲ ဒလောန်ဏာလ္ပာ်တေံညိ။” =“ကြိုးကို ဝါးပေါက်ထဲထိုးသွင်းပြီး ဟိုဖက်သို့လျှိုလိုက်ပါ။”')
,(6820,3,4,'ရိုက်ဖွပ်သည်။ ဆောင့်ရိုက်သည်။','“(လၟာဲဂှ်) ပ္ဍဲဗတဗောဓိသတ် (သၟိၚ်နာ်) ဂှ် ဍေံၜုၚ်ဒလိုန်ညံၚ်ညးၜုၚ်ယာတ်ကီု ဍေံၜုၚ်ဒလိုန်ဖ္ဍူကၠေံရ။” (ဇ—ဘူရိဒတ်။ အစွောံ။) = “အလမ္ပာယ်သည် ဘုရားလောင်းနဂါးမင်း၏အမြီးကို ပုဆိုးဖွပ်သကဲ့သို့ ရိုက်ဖွပ်ပြီးလျှင် အတွင်းကြေကြေအောင် ရိုက်ဖွပ်၏။”')
,(6821,3,4,'မှားယွင်းသည်။','“ကၠောန်ကလောန်မ္ဂး လ္ပကဵုဒလပ်ညိ။” = “အလုပ်လုပ်လျှင် မမှားယွင်းပါစေနှင့်။”')
,(6822,3,1,'၁။ အပွင့်များသောစံပယ်ပန်းတစ်မျိုး။',NULL)
,(6822,3,1,'၂။ သင်ပင်။ သင်ဖြူး။ ကဲလားသင်ဖြူး။','ဒကဝ်ဒလုမ် = သင်ဖြူးဖျာ။ (ပါဠိ—ကဋသာရက)')
,(6823,3,1,'၁။ ပုံးရည်။ ကစီရည်။',NULL)
,(6823,3,1,'၂။ ကောက်ညှင်းထုပ်။ မုယောမုန့်။ (ပါဠိ—ကုမ္မာသ)','ဒလောမ်ဍာ်ဗံၚ် = ပြာရည်ကောက်ညှင်းထုပ်။ || ဒလောမ်ဗြာတ် = ငှက်ပျောသီးဋ္ဌာပနာထားသောကောက်ညှင်းထုပ်။ || “သၟတ်ဗြဴညာတ်ကျာ်တုဲ ဒလောမ်ပိဂှ်ဟေၚ် ကဵုဒါန်ကုကျာ်ရ။” (ဇ—၄၁၅။အစွောံ။) = “သတို့သမီးငယ်သည် မြတ်စွာဘုရားကိုမြင်သော် သုံးဆုပ်သောမုယောမုန့်တို့ကိုပေးလှူ၏။”')
,(6824,3,4,'ဖုံးသည်။ ခြုံသည်။','‘ဂလီု’ ရှု။')
,(6825,3,1,'တံကဲ။ ပလ္လင်နောက်မှီ။ အမှီ။ မှီစရာ။','“ခုၚ်ဂ္ဇအ်ဂှ် မၞုံကဵုဇိုၚ်ပန်၊ ဒလာဲမွဲ၊ လၜက်တဲၜါရ။” = “ထိုထိုင်ခုံသည် အခြေလေးခု၊ အမှီတစ်ခုနှင့် လက်တၚ်စရာနှစ်ခုရှိသည်။”')
,(6825,3,4,'မှီသည်။','“ဣသိဗျုမွဲ ဒလာဲဒၟံၚ်ပ္ဍဲတၞံတာ။” (ဇ—၁၇၃။ အစွောံ။) = “ဤရသေ့သည်ထန်းတုံးကို မှီ၍နေ၏။” (ညောင်ကန်) || “ယဝ်ဒါန်ဟွံမွဲ၊ ပ္ဍဲဘဴတမၠာ။ စးကဵုစးဗ္ဒာဲ၊ ဒလာဲလဝ်ကၠာ။ ဟွံဂွံလးလေၚ်၊ ရောၚ်ဟွံသေၚ်ဟာ။” (လိက်ဗြရတ်ဣဏၚ်ကၚ်ရဳ) = “ရှေးဘဝက ရေစက်မရှိပါက ကျောချင်းကပ်၍ မှီထားကြလင့်ကစား အတူမမွေ့လျော်ကြရသည် မဟုတ်လော။” || “ဒလာဲဗောဓိ၊ မူဏိသိက္ခာ။” (လိက်ဝိဓူရ) = “မြတ်စွာဘုရားရှင်သည် ဗောဓိပင်ကို မှီတော်မူ၏။”')
,(6826,3,4,'(ထီး) ဆောင်းသည်။','ဒလဝ်က္ဍိုၚ် = ထီးဆောင်းသည်။ || ဒလဝ်ခၟံက် = ခမောက်ဆောင်းသည်။ || ဒလဝ်အထုပ် = ဦးထုပ်ဆောင်းသည်။ || “နက္ဍိုၚ်သၠဂွေါအ်ဂှ်ဟေၚ် မဒလဝ်ရ။” (ဇ—၃၉ဝ။ အစွောံ။) = “သစ်ရွက်ထီးကိုသာလျှင် ဆောင်း၏။” || ဂိတုဒလဝ်က္ဍိုၚ် =လထီးဆောင်းသည်။ || တ္ၚဲဒလဝ်က္ဍိုၚ် = နေထီးဆောင်းသည်။')
,(6827,3,4,'‘ဓလဵု’ ရှု။',NULL)
---------
,(6828,3,4,'နောက်ပြန်မလှည့်ဘဲ တစ်ကြိုးတည်းထွက်ပြေးသည်။ တစ်ရှိန်တည်းတန်းပြေးသည်။','“(ခမဳကောကာလိကဝွံဂှ် တွံဓဝ်ဂးတုဲ တိုန်အာလတူပၞၚ်ဓဝ် တွံဓဝ်ဟွံဒး ဂွကဵုညးလောန်တုဲ) သီုမဒဇပ်ဇတဝ် ဆင်စှ်ေနူပၞၚ်ဓဝ်တုဲ ဒလိုဟ်ကြၚ်အာကၠေံတုဲ စဴအာပြဝိုန်ဇကုရ။” (ဇ—၁၇၂။ အစွောံ။) = “ကောကာလိကမည်သောရဟန်းသည် တရားဟောအံ့ဆိုကာ တရားပလ္လင်ထက်သို့တက်၍ တရားမဟောတတ်ဘဲ ရှက်စနိုးသည်ဖြစ်၍ တုန်တုန်ရီရီဖြင့် တရားပလ္လင်ထက်မှ ခုန်ဆင်း၍ တစ်ကြိုးတည်းပြေးကာ မိမိ၏ပရိဝုဏ်သို့ ပြန်သွားလေ၏။”')
,(6828,3,4,'နောက်ပြန်မလှည့်ဘဲ တစ်ကြိုးတည်းထွက်ပြေးသည်။ တစ်ရှိန်တည်းတန်းပြေးသည်။','“(ကၠဵုညးကေတ်ဏာကၠေံဂှ်) သ္ဂာဗ္တံဂှ် ကၠဵုဂှ်စကၠေံဇုက်သၞာံ မဒက်လဝ်ကအ်ဇကုဂှ်တုဲ ဒလောဟ်စဴအာကဵုတၠဇကုပၠန်ရ။” (ဇ—၂၄၂။ အစွောံ။) = “သူတစ်ပါးယူသွားသောခွေးသည် သန်းခေါင်းယံ­ မိမိလည်­ ချည်ထားသောသားရေကြိုးကို ကိုက်ဖြတ်စားပစ်ပြီးလျှင် မိမိသခင်ဆီသို့ တစ်ကြိုးတည်းပြေးပြန်သွား၏။”')
,(6828,3,4,'နောက်ပြန်မလှည့်ဘဲ တစ်ကြိုးတည်းထွက်ပြေးသည်။ တစ်ရှိန်တည်းတန်းပြေးသည်။','“သၟာန်ကျာ်တြဲဂှ် ပြဘာတ်သှ်ဟွံမာန်တုဲ ဒလောဟ်ဒဴအာရ။” (ဇ—၂၄၄။ အစွောံ) = “ထိုပရိဗိုဇ်သည် မြတ်စွာဘုရား၏မေးခွန်းကို မဖြေဆိုနိုင်ဘဲ တစ်ကြိုးတည်းပြေးလေ၏။”')
,(6828,3,4,'နောက်ပြန်မလှည့်ဘဲ တစ်ကြိုးတည်းထွက်ပြေးသည်။ တစ်ရှိန်တည်းတန်းပြေးသည်။','“ဍေံတံဒလိုဟ်ဒဴအာရ။” (ရာဇာထ္ၜုတ်)')
,(6829,3,1,'သွန်သင်ချက်။','ဂလာန်ဒလောအ်အ္စာ = ဆရာ၏သွန်သင်သောစကား။ သြဝါဒစကား။')
,(6830,3,1,'ဆုံးမသွန်သင်ချက်။ အဆုံးအမ။','“နလၟေၚ်ဒၠောံဗ္တောန်ဗောဓိသတ်ဂှ် သၟိၚ်ဒ္ဂေတ်ဗက်တုဲ—။” (ဇ—၄ဝ၇။ အစွောံ။) = “မင်းသည် ဘုရားလောင်း၏အဆုံးအမကို လိုက်နာ၍—။”')
,(6830,3,1,'ဆုံးမသွန်သင်ချက်။ အဆုံးအမ။','“ဂလာန်ဒၠောံဗ္တောန်မဂှ် ကောန်တံတၞဟ်နပလီုကၠေံဂှ် ဟွံဂပ်ဂဝ်ဟေၚ်ရ။” (ဇ—၃၇၁။ အစွောံ။) = “ဖခင်၏အဆုံးအမစကားကို သားတို့ဖျက်ဆီးခြင်းငှာ မသင့်။”')
,(6830,3,1,'ဆုံးမသွန်သင်ချက်။ အဆုံးအမ။','(ကြိ) သွန်သင်သည်။ ပဲ့ပြင်ဆုံးမသည်။')
,(6830,3,1,'ဆုံးမသွန်သင်ချက်။ အဆုံးအမ။','“ဗောဓိသတ်တုန်လေဝ် ဒၠောံဗ္တောန်တဴညးမသုန်ရ။” (ဇ—၃၅၄။ အစွောံ။) = “ဘုရားလောင်းသည်လည်း ထိုသူငါးယောက်တို့ကို သွန်သင်ဆုံးမ၏။”')
,(6830,3,1,'ဆုံးမသွန်သင်ချက်။ အဆုံးအမ။','“အဲဟီုဒလောံဗ္တောန်မရှာဇ်ညိဂးတုဲ အဲမကၠုၚ်ရောၚ်” ဒေဝတဴဂး။ (ဇ—၅၂ဝ။ အစွောံ။) = “အသင်မင်းမြတ်ကို ပြောဆိုဆုံးမအံ့သောငှာ ငါလာ၏” ဟုနတ်ဆို၏။')
,(6831,3,4,'စကားပြောထစ်သည်။ စကားပြောရာတွင် အထစ်အထစ် ဖြစ်သည်။ စကားသံတုံ့ဆိုင်းတုံ့ဆိုင်းဖြစ်သည်။','“ဟီုဟွံကၠးအဴ၊ ဓလိုအ်တဴပၠန်။” (လိက်ပ္တံပါရမဳ။ အစွောံ။) = “စကားပြောမပီ အထစ်အထစ်ဖြစ်သည်။”')
,(6832,3,4,'စကားပြောထစ်သည်။ စကားသံတုံ့ဆိုင်းတုံ့ဆိုင်းဖြစ်သည်။','“ဟီုအရေဝ် ပွမဒၠောံဒၠာဲတဴဂှ် ဒှ်လက်သန်မၞိဟ်ဟီုအရေဝ်ခိုဟ်မွဲ ဟွံသေၚ်ရ။” =“စကားပြောရာတွင် စကားထစ်ခြင်းသည် စကားပြောကောင်းသူတစ်ဦး၏ လက္ခဏာမဟုတ်ပါ။”')
,(6832,3,4,'စကားပြောထစ်သည်။ စကားသံတုံ့ဆိုင်းတုံ့ဆိုင်းဖြစ်သည်။','“မၞုံရမျှာၚ်မဟီုကၠးဖ္ဍး ဟွံဂွံဒၠောအ်ဒၠာဲ။” (ဓမ္မဒဳပနဳ။ မာံရွှေငိုး။) = “စကားမထစ် ပီသသောအသံရှိ၏။”')
,(6832,3,4,'စကားပြောထစ်သည်။ စကားသံတုံ့ဆိုင်းတုံ့ဆိုင်းဖြစ်သည်။','(ပါဠိ—မမ္မန)')
,(6833,3,1,'ပူပၚ်သောက။ စိုးရိမ်ခြင်း။','ဒှ်ဒဝိၚ် = ပူပၚ်သည်၊ စိုးရိမ်သည်။')
,(6833,3,1,'ပူပၚ်သောက။ စိုးရိမ်ခြင်း။','“ဒှ်တဴဒဝိၚ်၊ ဂွိၚ်တဴကဵုမိ။” (လိက်သုပိဏ္ဏကုမ္မာ။ မၚ်သၚ်ကြာ။) = “မိခင်အတွက်စိုးရိမ်၍ စိုးရိမ်ပူပန်ခြင်းဖြစ်၏။”')
,(6834,3,1,'သောကပူပန်မှု။ စိုးရိမ်ကြောင့်ကြမှု။','“ဂါမနိစန္ဒ ဂွံဇၞးအမှုအိုတ်တုဲမိပ်စိုတ်စရိုတ် ဒွိၚ်ဒွဲါဟဲအာရ။” (ဇ—၂၅၇။ အစွောံ။) = “ဂါမနိစန္ဒသည် အလုံးစုံသောအမှုတို့­တရားနိုင်၍ ဝမ်းမြောက်ရွှင်လန်းကာ ပူပန်သောကငြိမ်းလေ၏။”')
,(6834,3,1,'သောကပူပန်မှု။ စိုးရိမ်ကြောင့်ကြမှု။','“ပွမဟၟဲကဵုအစံၚ်အတူဒဝိၚ်ဒဝဲါဂှ်မွဲ။” (ဓမ္မဒေသနာ။ မာံရွှေငိုး။) = “သောကပူပန်မှုမရှိခြင်းသည်လည်းတစ်ခု။”')
,(6835,3,5,'၁။ စွဲစွဲမြဲမြဲ။ နှစ်ခြိုက်စွာ။','“သုၚ်ဗ္ၜူဒၟံၚ်ဒဝိုၚ် လ္ပပညိ။” (ဇ—ဝိဓုရ။ အစွောံ။) = “စွဲစွဲမြဲမြဲ သောက်စားမူးယစ်နေခြင်းကို မပြုပါနှင့်။”')
,(6835,3,5,'၁။ စွဲစွဲမြဲမြဲ။ နှစ်ခြိုက်စွာ။','“ပိုန်မၞိဟ်ဒဝိုၚ်၊ စသိုၚ်တုဲဂျ။အာယုက်သၞုဲ၊ အိုတ်အာတုဲရ။” (လိက်ပ္တံပါရမဳ။ အစွောံ။) = “လူ့စည်းစိမ်ကို နှစ်ခြိုက်စွာစံစားပြီးနောက် အသက်ကုန်၍ ကွယ်လွန်၏။”')
,(6835,3,5,'၁။ စွဲစွဲမြဲမြဲ။ နှစ်ခြိုက်စွာ။','“ပိုဲချပ်ဒဝိုၚ်၊ ဂၠိုၚ်တ္ၚဲတုဲဂၠ။ ပိုဲသၟိက်ခၞံကၠာ၊ ဍုၚ်မွဲထာဏ။” (လိက်သၟိၚ်အသး။ နန္ဒသာရ။) = “ဤနေရာ­မြို့တည်ရန် ရက်ပေါင်းများစွာ ငါတို့စွဲမြဲစွာတိုင်ပင်ကြပြီးပြီ။”')
,(6835,3,5,'၁။ စွဲစွဲမြဲမြဲ။ နှစ်ခြိုက်စွာ။','၂။ အမြဲ။ အမြဲတစေ။')
,(6835,3,5,'၁။ စွဲစွဲမြဲမြဲ။ နှစ်ခြိုက်စွာ။','“ပွမဂ္ညိဂ္ညာတ်ဒဝိုၚ် ပွမေၚဝ်ရုပ်ပ္ဍဲဒ္ၚောဝ်လၟိုန်။” (သၠပတ်ကုလဇာတ်) = “အမြဲတစေတန်ဆာဆင်ခြင်း၊ အမြဲတစေမှန်ကြည့်ခြင်း။”')
,(6835,3,5,'၁။ စွဲစွဲမြဲမြဲ။ နှစ်ခြိုက်စွာ။','“သာ်ဝွံဒဝိုၚ်၊ဂၠိုၚ်သၞာံကာလ။” (လိက်မေဃကောန်ဒြာဲ) = “ဤသို့အမြဲတစေ နှစ်ကာလများစွာ။”')
,(6836,3,1,'(= ဂဥုဲဒဝါန်) အုံဆေး။',NULL)
,(6837,3,1,'အပြောက်အကျား။','“ကၠဵုနရက်တံဂှ် မၞုံဒဝါန်မသုန်သာ်တုဲ ဗၞတ်တၟာစိၚ်တံဂှ်မဒှ်။” (ဇ—၅၂၂။ အစွောံ။) = “ငရဲခွေးတို့သည် ငါးမျိုးသောအပြောက်အကျားရှိ၍ ဆင်အရွယ်ပမာဏရှိ၏။”')
,(6837,3,1,'အပြောက်အကျား။','(နဝိ) အကွက်အပြောက်ဖြစ်သော။ ပြောက်ကျားသော။')
,(6837,3,1,'အပြောက်အကျား။','“(တၞံဇြဲသုံဂှ် တၞးဍေံဂမၠိုၚ် မၞိဟ်ပေါဟ်ပထောၚ်လဝ်ကဵုကြေဟ်တုဲ) သမၞိၚ်မသိၚ်ဒဝါန်ဒၟံၚ်။” (ဇ—၁ဝ၇။ အစွောံ။) =“ထိုပညောင်ပင်၏အရွက်များကို ကျောက်စရစ်ခဲဖြင့် ပစ်ဖောက်ထားသဖြင့် အရိပ်ကျိုးတိုးကျဲတဲဖြစ်၍ အကွက်အပြောက်ဖြစ်နေ၏။”')
,(6837,3,1,'အပြောက်အကျား။','“ဂၞကျာ်ပဇာပတိဂေါတမဳ သ္ပအဓိဋ္ဌာန်တုဲ တၞံတောဝ်ထဝ်ကၠုတ်တိုန်ရ။ ပ္ကဴဍေံဂှ်တုန် တုပ်ကဵုပ္ကဴမၠဵုရ၊ သတ်ဍေံဂှ်ပၠန်တုန် တုပ်ကဵုသာ်မၞိက်ဒဝါန်ရ။” (အနာဂတာဝၚ်။ လောကသဳရိ။) = “မိဒွေးတော်ဂေါတမီသည် အဓိဋ္ဌာန်ပြု၍ ရွှေဂွမ်းပင်ပေါက်လာ၏။ပန်းပွင့်သည်ကား စံပယ်ပန်းနှင့်တူ၏။ အသီးသည်ကား ပြောက်ကျားသောပတ္တမြားနှင့်တူ၏။”')
,(6837,3,1,'အပြောက်အကျား။','“ကၠဵုကၠိၚ်ဗကေတ်ဒဝါန်တံဂှ် ဟုပ်ကၠုၚ်ထမက်ကိတ်စ (သတ်နရက်တံဂှ်ရ။)” (ဇ—၅၃ဝ။ အစွောံ) = “အနီရောင်ပြောက်ကျားသော ငရဲခွေးတို့သည် ငရဲသားများကို ဝိုင်းအုံလာ၍ ကိုက်စားကြကုန်၏။”')
,(6837,3,1,'အပြောက်အကျား။','“(ကလော်ဂှ်) မုက်ဍေံကိုဟ်ဂွု၊ ဇကုဍေံဒဝါန်၊ ဇိုၚ်တဲဍေံလစံက်—။” (ဇ—၅၅။ အစွောံ။) = “(ထိုဘီလူးသည်) ဖြူသောမျက်နှာရှိသည် ပြောက်ကျားသောဝမ်းရှိသည် ညိုသောလက်ခြေရှိသည်ဖြစ်၍—။” (ညောင်ကန်)')
,(6837,3,1,'အပြောက်အကျား။','လစံက်ဒဝါန်၊ လမ်စံက်ဒဝါန် = ပြောက်ကျားမည်းညိုသော။ မည်းညစ်ပြောက်ကျားဖြစ်သော။')
,(6837,3,1,'အပြောက်အကျား။','“ညံၚ်သာ်အပြံက်၊ လစံက်ဓဝါန်။” (လိက်ပဒုမဝတဳ) = “ဖြူနီကြောင်ကျား မည်းညိုပြောက်ကျားသောအရောင်ကဲ့သို့။”')
,(6837,3,1,'အပြောက်အကျား။','(ပါဠိ—သဗလ)')
,(6838,3,16,'‘ဒဝါန်—၂’ နှင့်အတူတူ။',NULL)
,(6839,3,4,'လွှဲသည်။ ရှေ့နောက်ဘယ်ညာ လူးလာလှုပ်ရှားစေသည်။','ဒဝုဲသရေၚ် = ပုခက်လွှဲသည်။')
,(6839,3,4,'လွှဲသည်။ ရှေ့နောက်ဘယ်ညာ လူးလာလှုပ်ရှားစေသည်။','“(ကၞုဲဒမၠာန်ဂှ်) ရပ်ဒြၚ်ဗောဓိသတ် (ပြေၚ်) တုဲ ဒဝုယ်ဝေၚ်ဇကုရ။ ရပ်ဗတတုဲ ပဝေၚ်သရေၚ်ဇုက်ဒဝုယ်ရ။” (ဇ—၂၇၈။ အစွောံ။) = “ထိုလျှပ်ပေါ်သောမျောက်သည် ဘုရားလောင်းကျွဲ၏ ချိုတို့­ကိုင်၍ ကိုယ်ကိုတွဲလျားလွှဲကစား၏။ အမြီးတို့ကိုကိုင်၍ လွှဲစရာပုခက်ကြိုးကဲ့သို့ ပြု၍ကစား၏။”')
,(6839,3,4,'လွှဲသည်။ ရှေ့နောက်ဘယ်ညာ လူးလာလှုပ်ရှားစေသည်။','“ရပ်ကၞာၚ်ဇြဲတုဲ၊ ဒဝုဲနၚ်ဏာ။” (လိက်ဟတ္ထိပါလ။ အစွောံ။) = “ညောင်ကိုင်းကိုကိုင်၍ ထိုဘက်ဤဘက် လွှဲသွားလွှဲလာပြု၏။”')
,(6839,3,4,'လွှဲသည်။ ရှေ့နောက်ဘယ်ညာ လူးလာလှုပ်ရှားစေသည်။','“စုတ်သရေၚ်တုဲ၊ ဒဝုဲဖလှိၚ်။” (လိက်သုပိဏ္ဏကုမ္မာ။ မၚ်သၚ်ကြာ။) = “(သားငယ်ကို) ပုခက်ထဲထည့်ကာ လွှဲ၍ချော့သိပ်၏။”')
,(6840,3,1,'‘ဂဝုဲကဝါ်’ ရှု။',NULL)
,(6841,3,10,'(နဝိ) ဆယ်ခုမြောက်ဖြစ်သော။',NULL)
,(6842,3,1,'အဆိပ်ပြင်းသောပိုးတစ်မျိုး။','(ကြိ) တပ်မက်သည်။ တွယ်တာသည်။')
,(6842,3,1,'အဆိပ်ပြင်းသောပိုးတစ်မျိုး။','“(ညံၚ်ရဴစာၚ်ပ္ဍဲခြိုၚ်ဂှ်ကီု) အရီုမသုန်မတွံဂး သ္ၚုဂၞာဍာ်ဂၞာဂှ် သတ္တံဂမၠိုၚ်ဒသိုက်သန်။” (သၠပတ်သတိပထာန်) =“လှောင်ချိုင့်ထဲမှကြက်ကဲ့သို့ အာရုံငါးပါးတည်းဟူသော (စားဖိုမှူးကပေးသော) ရေခွက်ဆန်ခွက်ကို သတ္တဝါအပေါင်းတို့သည် တပ်မက်ကြကုန်၏။”')
,(6843,3,1,'အနှောင်အဖွဲ့။ ထိတ်တုံး။','‘တသိၚ်’ ရှု။')
,(6844,3,4,'‘တသိုၚ်’ ရှု။',NULL)
,(6845,3,1,'အမြိတ်။ အဆာ။ အမြိတ်အဆာ။ (ပါဠိ—ဒသာ)','“ယာတ်မၞုံကဵုဒသာဲ။” =“အမြိတ်အဆာရှိသောအဝတ်။”')
,(6846,3,4,'ညည်းညူသည်။ (တံ ဂရံအန)','“(ခဍာ်ဂှ် သၟိက်ဂွံစကဖျုန်တံဂှ်တုဲ ဟွံအာဂၠာဲစစၞ) ပလွေဟ်မယဲ ဒသဝ်ဒအိက်ဒၟံၚ် သတိက်ဒၟံၚ်ရ။” (ဇ—၄၂။ အစွောံ။) = “ကျီးသည် ငါးအမဲတို့ကိုစားလို၍ အစာရှာမထွက်ဘဲ ဖျားချင်ဟန်ဆောင်ပြီး ညည်းညူလျက်အိပ်၏။”')
,(6846,3,4,'ညည်းညူသည်။ (တံ ဂရံအန)','“(ခ္ဍာ်ကၠတ်စဂှ် ဂြောဝ်ရပ်ဂွံပိုက်ကၠေံတသော် အလုံဇကုတုဲ) ခဍာ်တုန် ဒဒှ်ဒုက္ခဝေဒနာ ဇြဟတ်မရာန်သကိုတ် သီုမဒသဝ်ဒအိက်ဒၟံၚ်ဂှ် သ္တိက်သီုဒဒိုက်ရ။” (ဇ—၄၂။ အစွောံ။) = “ခိုးစားသောကျီးကိုထမင်းချက်သည်ဖမ်း၍ ကိုယ်အလုံး­ အတောင်တို့ကိုနုတ်၍ ကျီးသည် သည်းစွာသောဝေဒနာနှိပ်စက်သည်ဖြစ်၍ ညည်းညူလျက်အိပ်၏။” (ညောင်ကန်)')
,(6847,3,4,'‘တသဝ်နရာတ်’ ရှု။',NULL)
,(6848,3,4,'အနူးအညွတ် ခွင့်ပန်သည်။ အခွင့်တောင်းသည်။','“ယွံအာစာ၊ တ္ၚဲဝွံပကီုနက်သတ်နွံ ကြိုက်မန်ဗဂူဒြပ် ကဵုကမၠတ်တံ သဗလးဇကုပိုဲရ” သာ်ဝွံမတန်ဒသဝ်ပါန်ကဵုအာစာရောၚ်၊ သာ်ဂှ်ဟွံဂွံဂး။ (ဇ—၄၈။ အစွောံ။) = “ဆရာ၊ ယနေ့ နက္ခတ်၏ယှဉ်ခြင်းရှိ၏၊ မန္တရားကိုမန်း၍ ဥစ္စာမိုးကိုရွာစေ၍ ခိုးသားတို့အားပေးကာ ငါတို့ကိုယ်ကို လွှတ်ကြအံ့” ဟုဤသို့ဆရာ့ကို အနူးအညွတ် ခွင့်တောင်းသင့်ခဲ့၏။ သို့သော် ထိုသို့မဆို။')
,(6849,3,4,'၁။ ပူပန်သည်။ ပူလောင်ခံစားရသည်။','‘တဟး’ (ကြိ—၂) နှင့်အတူတူ။')
,(6849,3,4,'၁။ ပူပန်သည်။ ပူလောင်ခံစားရသည်။','“သာ်ဝွံဝေသန္တဝ် ဒဟးဒၟံၚ်ပ္ဍဲကောန်ရ။” (ဇ—ဝေသန္တဝ်။ အစွောံ။) = “ဤကဲ့သို့ ဝေဿန္တရာမင်းသည်သားသမီးတို့­ ပူလောင်ခံစားနေရ၏။”')
,(6849,3,4,'၁။ ပူပန်သည်။ ပူလောင်ခံစားရသည်။','၂။ အသက်ရှူထုတ်သည်။ မှုတ်ထုတ်သည်။')
,(6849,3,4,'၁။ ပူပန်သည်။ ပူလောင်ခံစားရသည်။','“နကဵုကျာမုဟ် ယီုဟွံဂတာပ်တုဲ နကဵုကျာပါၚ် ဒဟးပ္တိတ်တုဲ မဂွံယီုရောၚ်—။” (ဇ—ဝေသန္တဝ်။ အစွောံ။) = “နှာခေါင်းလေဖြင့် အသက်မရှူနိုင်ဘဲ ပါးစပ်လေဖြင့်မှုတ်ထုတ်၍ အသက်ရှူရ၏။”')
,(6850,3,1,'မွတ်သိပ်ခြင်း။','ဒဟက်ဍာ် = ရေမွတ်သိပ်ခြင်း။ ရေငတ်ခြင်း။ ရေသောက်လိုခြင်း။')
,(6850,3,1,'မွတ်သိပ်ခြင်း။','(ကြိ) မောလုံးဆို့သည်။')
,(6850,3,1,'မွတ်သိပ်ခြင်း။','“ယွီုဒဟက်၊ ပလက်ဇွောဝ်ဍေၚ်။ သော်လာဲဒဗြိုဟ်၊ ဂြိုဟ်ဒှ်ထေၚ်ထေၚ်။” (လိက်ပတ္တစာရဳ။ နာဲထဝ်စိုပ်။) = “မောလုံးဆို့သောအသက်ရှူသံဖြင့် ချွေးထွက်လျက်ဆံပင်ဖိုးရိုးဖားယားပြေကျ၍ အသည်းထိတ်၏။”')
,(6851,3,4,'ငေါက်ငမ်းသည်။ အမျက်ထွက်သည်။','‘လဟုက်’ (ကြိ) နှင့်အတူတူ။')
,(6852,3,4,'အမျက်ချောင်းချောင်းထွက်သည်။ မာန်မူသည်။ (ပါဠိ—နိဒ္ဒါပုဗ္ဗ)','မၞုံဇာတိမဒဟုက်ဒဟက် = အမျက်တဟုန်းဟုန်းဖြင့် မာန်မူတတ်သောသဘောရှိသည်။ (ပါဠိ—ဟုံဟုၚ်္ကဇာတိက)')
,(6852,3,4,'အမျက်ချောင်းချောင်းထွက်သည်။ မာန်မူသည်။ (ပါဠိ—နိဒ္ဒါပုဗ္ဗ)','“ဗမၞးမွဲ မလေပ်ဒဟုက်ဒဟက်တုဲ ဟုံဟုံကဂးယၟု။” (ဗုဒ္ဓဝၚ်။ မာံရွှေငိုး။) = “တစ်ယောက်သောပုဏ္ဏားသည် အမျက်တဟုန်းဟုန်းထွက်တတ်သဖြင့် ဟုံဟုံကဟု အမည်တွင်၏။”')
,(6853,3,1,'အမှီအထောက်။ အထောက်အပံ့။ အထောက်အကူ။','“ညံၚ်ဆုမဟၟဲကဵုကြက်ဒၟံၚ်ဒေါဝ်ဝါဂှ်ရ ကာလကျာဇၞော်မပိုက်ကၠုၚ်ဂှ် ဟွံမွဲကဵုဒဟံက်ထံက်ပၚ်တုဲ ရဴမဒေါမ်တၟိုၚ်အာကီု။” (ဇ—၉၂။ အစွောံ။) = “လွင်ပြင်လယ်­ပေါက်သော အနှစ်မရှိသောသစ်ပင်သည် လေပြင်းတိုက်ခတ်လတ်သော် အမှီအထောက်မရှိခြင်းကြောင့် ကျိုးပြတ်လဲပြိုသွားရဘိသကဲ့သို့။”')
,(6853,3,1,'အမှီအထောက်။ အထောက်အပံ့။ အထောက်အကူ။','“လၟဂှ် ပ္ဍဲပါၚ်ကတိုၚ်ဂှ် ဍေံလးစုတ်ဂတဵုတုဲ ဆုဒဟံက် ဍေံထံက်ပခိုၚ်လဝ်ဂတဵုဂှ်ရ။” (ဇ—၅၁၄။ အစွောံ။) = “မုဆိုးသည် တွင်း၏အဝ­ ပျဉ်ချပ်ကိုခင်း၍ သစ်အထောက်ဖြင့် ခိုၚ်အောင်ထောက်ကန်ထား၏။”')
,(6853,3,1,'အမှီအထောက်။ အထောက်အပံ့။ အထောက်အကူ။','“မဂွံဒုန်ကၞဳ၊ ဆုဂွံကၟဳထံက်။ ဂွံဆုတဟံက်၊ ညးထံက်ရောသၟိၚ်။” (လိက်ကောန်သၟိၚ်ပိ။ မာံခစုန်အံက်။) = “အမိုးကိုထောက်ရန်သစ်နှင့် ကြမ်းခင်းဝါးကိုရ၍ အမှီအထောက်သစ်ကိုရ၏။”')
,(6854,3,4,'ထွက်သည်။ (?)','“(ကုသတ်နရက်တံဂှ်) ပၟၚ်နရက်တံဂှ် အာထောံဖျေံ ပ္ဍဲကတိုၚ်နရက်ဂုဓ မသသ္အုဲ ဗၞတ်ကၠံယောဇနာဂှ်တုဲ မသသ္အုဲဒၟံၚ် လမျီုညံၚ်ဒဟံက်တိတ်အာကီုရ။” (ဇ—၅၃ဝ။အစွောံ။) = “ငရဲသားများအား ငရဲထိန်းတို့သည် ယူဇနာတစ်ရာရှိ ပုပ်ဟောင်နံစော်နေသောမစင်ဘင်ပုပ်တွင်း­ ပစ်ချကြကုန်၏။ ပုပ်ဟောင်နံစော်နေသည်မှာ (ငရဲသားတို့သည်) အသက်ထွက်အံ့သကဲ့သို့ဖြစ်ကုန်၏။”')
,(6855,3,1,'လှည်းထောက်။',NULL)
,(6856,3,4,'‘ဂဟတ်ကရာတ်’ နှင့်အတူတူ။ (ဇ—၂၂၉။ အစွောံ။) ဒဟုဲ (ကြိ) ‘လဟုဲ’ ရှု။',NULL)
,(6857,3,1,'ဟန်အမူအရာ။ ကိုယ်အမူအရာ။','“ခါညာတ်ဒဟုဲဒဟးသၟိၚ်ဗြာဇ္ဇ တၠညး (ဖရၚ်မၚ်ဂံၚ်) ဟီုထိုၚ်သးသန်။ — ကြိုက်မဒှ်ဒကိုပ်ပၞာန်ကွေံရ နွံအသံ။” (အကြီုရာဇာဓိရာဇ်) = “ဘုရင်မင်းခေါင်သည် သမိန်ဗြာဇ္ဇ၏ ဟန်အမူအရာကို မြင်သည်ရှိသော် အလွန်ချီးမွမ်း၏။ စစ်ဗိုလ်ချုပ်ဖြစ်သည်မှာ ထိုက်သင့်လှပါပေ၏ဟု အမိန့်ရှိ၏။”')
,(6858,3,4,'၁။ (မီး၊ ဒေါသမီး) တောက်လောင်သည်။','“ကောန်ၚာ်ဂမၠိုၚ် ညာတ်သ္ၚိမတူတိုန် ဒဟဵုဒၟံၚ်တုဲ ဖေက်ဂၟံက်နရိုအ်ယာံတုဲ ဒြေပ်ဒဴအာရ။” (ဇ—တေမဳ။ အစွောံ။) = “ကလေးများသည် အိမ်မီးလောင်၍ မီးတောက်နေသည်ကိုမြင်လျှင် ထိတ်လန့်ငိုကြွေးကုန်လျက် လွတ်ရာပြေးကုန်၏။”')
,(6858,3,4,'၁။ (မီး၊ ဒေါသမီး) တောက်လောင်သည်။','“(ခမဳမဇၞော်ဒေါသဂှ်တုန်) ဂလာန်မအောန်ၜိုန်ညးဟီုတဴကီု ပၞတ်ဒဟဵုတဴ—။” (ဇ—၄၄၃။ အစွောံ။) = “ထိုဒေါသကြီးသောရဟန်းသည် သူတစ်ပါးတို့ အနည်းငယ်မျှပြောသော်လည်း အမျက်ဒေါသမီးတောက်လောင်တတ်၏။”')
,(6858,3,4,'၁။ (မီး၊ ဒေါသမီး) တောက်လောင်သည်။','၂။ အလျင်စလို၊ အလောတစ်ကြီး သွား')
,(6858,3,4,'၁။ (မီး၊ ဒေါသမီး) တောက်လောင်သည်။','လာသည်။ တက်သုတ်နှင်သည်။')
,(6858,3,4,'၁။ (မီး၊ ဒေါသမီး) တောက်လောင်သည်။','“လၟညာတ်ဗောဓိသတ် (သၟိၚ်ၜိုပ်ထဝ်) လကဲမံၚ်ပ္ဍဲဒၞက်ဂှ်တုဲ မိပ်စိုတ်တုဲ လဗိုန်ဇကုတုဲ ရပ်လေံဒန်တုဲ ဍေံဒဟဵုကၠုၚ်ရ။” (ဇ—၅၃၄။ အစွောံ။) = “မုဆိုးကြည့်လတ်သော် ကျော့ကွင်းတံဖျား­ တွဲလျားဆွဲလျက်မိသော ဘုရားလောင်းရွှေဟင်္သာမင်းကိုမြင်၍ ဝမ်းမြောက်သည်ဖြစ်၍ အောက်ပိုးကျိုက်လျက် ဆောက်ပုတ်ကိုကိုင်၍ တက်သုတ်နှင်လျက်လာ၏။”')
,(6858,3,4,'၁။ (မီး၊ ဒေါသမီး) တောက်လောင်သည်။','“(လၟ) ရပ်ကေတ်ဗၞုဟ်ဇမ္ကေက်ဂှ်တုဲ ဍေံဒြေပ်ဒဟဵုကၠုၚ်ရ။” (ဇ—၅ဝ၁။ အစွောံ။) = “မုဆိုးသည်ထက်စွာသောလှံကိုကိုင်လျက် အလျင်စလိုပြေးလာ၏။”')
,(6858,3,4,'၁။ (မီး၊ ဒေါသမီး) တောက်လောင်သည်။','၃။ (လက်နက်) ဝင့်သည်။ ပင့်ချီသည်။ (?)')
,(6858,3,4,'၁။ (မီး၊ ဒေါသမီး) တောက်လောင်သည်။','“ရပ်သၞာ်တုဲ ဒဟဵုတဴလွဟ်။” (ဇ—၅၁၂။ အစွောံ။) = “သန်လျက်ကိုကိုင်၍ (ခုတ်ရန်) လက်နက်ကို ပင့်ချီ၏။”')
,(6859,3,4,'လူစုလူဝေးနှင့် ဆူညံသံပြုသည်။','“ပုရိသာတ်ဂၠိုၚ် ထဥဒၟံၚ်ရ။” = “ပရိသတ်များ၍ အုန်းအုန်းကျွက်ကျွက် ဆူညံနေသည်။”')
,(6860,3,4,'ကြွေးကြော်သည်။ အုတ်အုတ်ကျက်ကျက်အသံပြုသည်။',NULL)
,(6861,3,4,'လူစုလူဝေးနှင့် ဆူညံသံပြုသည်။ အုတ်အုတ်ကျက်ကျက်အသံပြုသည်။','ဗရုညးမသုန်ကၠံ မဒဥကၠံၚ်မံၚ်ဂှ် ကျာ်တြဲမိၚ်တုဲ “ယွံအနန်၊ မူဗရုကၠံၚ်မံၚ်ဂှ်သ္ဂးရော” ကျာ်တြဲသၟာန်။ (ဇ—၁၈၃။ အစွောံ။) = ငါးရာကုန်သောသူတို့၏ အုတ်အုတ်ကျက်ကျက် ဆူညံသံကိုကြားတော်မူ၍ မြတ်စွာဘုရားသည် “အာနန္ဒာ၊ ဘာဆူညံသံနည်း” ဟုမေးတော်မူ၏။')
,(6861,3,4,'လူစုလူဝေးနှင့် ဆူညံသံပြုသည်။ အုတ်အုတ်ကျက်ကျက်အသံပြုသည်။','“ညးဂမၠိုၚ်ဗဵုရုပ်ညးၜါဂှ် ထဥကၠံၚ်ဒၟံၚ်ရ။” (ပေါရဏာံပေါရဒံါ။ အစွောံ။) = “လူအများသည် ထိုသူနှစ်ဦးတို့၏ရုပ်အဆင်းကို လာရောက်ကြည့်ရှုကြရာ သောသောညံလျက်ရှိ၏။”')
,(6861,3,4,'လူစုလူဝေးနှင့် ဆူညံသံပြုသည်။ အုတ်အုတ်ကျက်ကျက်အသံပြုသည်။','“ညးကဵုသာဓု၊ထဥကၠံၚ်တဴ။” (လိက်မ္ၚဵုပိစှ်ောဒစာံ။ မာံထဝ်စိုပ်။) = “လူအပေါင်းကောင်းချီးပေးရာ ဆူညံနေ၏။”')
,(6862,3,4,'လူစုလူဝေးနှင့် အုတ်အုတ်ကျက်ကျက်အသံပြုသည်။','“ဂွံမိၚ်ဗရုထဥတမ္ညဝ်။” (အကြီုရာဇာဓိရာဇ်) = “လူစုလူဝေး၏ အုတ်အုတ်ကျက်ကျက်အသံကို ကြားရ၏။”')
,(6862,3,4,'လူစုလူဝေးနှင့် အုတ်အုတ်ကျက်ကျက်အသံပြုသည်။','“ဝေၚ်သဘၚ် (၇) တ္ၚဲ တွိၚ်တွိုက်ထဥတမ္ညဝ်တဴ။” (အာန်ဇုနာန်) = “ခုနစ်ရက်တိုင် ပွဲသဘင်ကစားရာ တူရိယာသံများဖြင့် အုန်းအုန်းကျွက်ကျွက်ဆူညံနေ၏။”')
,(6863,3,1,'အပုံ။','တိဒအုန် = မြေအပုံ။')
,(6864,3,4,'သန်းသည်။','‘ဂအာပ်’ ရှု။')
,(6865,3,4,'အပုံဖြစ်အောင်ပုံသည်။',NULL)
,(6866,3,10,'(န) အလှူပေးခြင်း။ ဒါန။',NULL)
,(6867,3,11,'(န) ဒါယကာ။ ပေးလှူသူ။',NULL)
,(6868,3,1,'ဒကာမ။ ဒါယိကာမ။','‘ဒကာဗျန်’ နှင့်အတူတူ။')
,(6869,3,1,'ပေးလှူသောအမျိုးသမီး။ ဒါယိကာမ။',NULL)
,(6870,3,10,'(န) ကျွန်။',NULL)
,(6871,3,10,'(န) ကျွန်မိန်းမ။',NULL)
,(6872,3,4,'၁။ (ဦးချိုဖြင့်) ဝှေ့သည်။','“ဂၠဴၜါဒိရၚ်သ္ကအ်။” = “နွားနှစ်ကောင်ဝှေ့ကြသည်။”')
,(6872,3,4,'၁။ (ဦးချိုဖြင့်) ဝှေ့သည်။','၂။တိုက်သည်။ တိုက်မိသည်။ ခတ်မိသည်။')
,(6872,3,4,'၁။ (ဦးချိုဖြင့်) ဝှေ့သည်။','“ဗမၞးမွဲ ဂၠေၚ်ကၠုၚ်ထမှာဲပုၚ် မွဲဒလေၚ်ဂှ် ကောန်သၟိၚ်ဒိဒးတုဲ ထမှာဲပုၚ်ဒတုံစှ်ေပါ်အာရ။” (ဇ—၄၅၆။ အစွောံ။) = “ထမင်းအိုးကို ထမ်း၍လာသောတယောက်သောပုဏ္ဏားကို မင်းသားသည်တိုက်မိ၍ ပုဏ္ဏား၏ထမင်းအိုး ကျကွဲသွား၏။”')
,(6873,3,10,'(န) ဒိသာပါမောက္ခ။ (အရပ်လေးမျက်နှာတွင် ထင်ရှားသော ရှေးခေတ်တက္ကသိုလ်ဆရာကြီး။','“ဗောဓိသတ်ပိုဲ ဒှ်အ္စာဒိသာပါမောက္ခ ပ္ဍဲဍုၚ်ဗာရာဏသဳဂှ်ကီုရ။” (ဇ—၃၇၇။ အစွောံ။) = “ဘုရားလောင်းသည် ဗာရာဏသီပြည်­ ဒိသာပါမောက္ခဆရာဖြစ်၍—။” (ညောင်ကန်)')
,(6873,3,10,'(န) ဒိသာပါမောက္ခ။ (အရပ်လေးမျက်နှာတွင် ထင်ရှားသော ရှေးခေတ်တက္ကသိုလ်ဆရာကြီး။','‘ပါတိမောက္ခ’၊ ‘ပါတိမုက္ခ’ ဟုလည်းရေးသည်။')
,(6874,3,1,'၁။ ဒီ။ (လ၏ဆွဲငင်မှုကြောင့် ဖြစ်ပေါ်လာသော ပင်လယ်ရေအတက်အကျ။) (မြန်မာဝေါဟာရ ‘ဒီ’ သည် မွန်ဝေါဟာရ ‘ဒဳ’ မှ ဆင်းသက်လာသည်။)','ဍာ်ဒဳ = ဒီရေ။')
,(6874,3,1,'၁။ ဒီ။ (လ၏ဆွဲငင်မှုကြောင့် ဖြစ်ပေါ်လာသော ပင်လယ်ရေအတက်အကျ။) (မြန်မာဝေါဟာရ ‘ဒီ’ သည် မွန်ဝေါဟာရ ‘ဒဳ’ မှ ဆင်းသက်လာသည်။)','၂။ပေါင်။')
,(6874,3,1,'၁။ ဒီ။ (လ၏ဆွဲငင်မှုကြောင့် ဖြစ်ပေါ်လာသော ပင်လယ်ရေအတက်အကျ။) (မြန်မာဝေါဟာရ ‘ဒီ’ သည် မွန်ဝေါဟာရ ‘ဒဳ’ မှ ဆင်းသက်လာသည်။)','ထာၚ်ဒဳ = တင်ပါး။')
,(6874,3,1,'၁။ ဒီ။ (လ၏ဆွဲငင်မှုကြောင့် ဖြစ်ပေါ်လာသော ပင်လယ်ရေအတက်အကျ။) (မြန်မာဝေါဟာရ ‘ဒီ’ သည် မွန်ဝေါဟာရ ‘ဒဳ’ မှ ဆင်းသက်လာသည်။)','(ကြိ) မောင်းသည်။ မောင်းနှင်သည်။')
,(6874,3,1,'၁။ ဒီ။ (လ၏ဆွဲငင်မှုကြောင့် ဖြစ်ပေါ်လာသော ပင်လယ်ရေအတက်အကျ။) (မြန်မာဝေါဟာရ ‘ဒီ’ သည် မွန်ဝေါဟာရ ‘ဒဳ’ မှ ဆင်းသက်လာသည်။)','ဒဳကွဳ = လှည်းမောင်းသည်။')
,(6874,3,1,'၁။ ဒီ။ (လ၏ဆွဲငင်မှုကြောင့် ဖြစ်ပေါ်လာသော ပင်လယ်ရေအတက်အကျ။) (မြန်မာဝေါဟာရ ‘ဒီ’ သည် မွန်ဝေါဟာရ ‘ဒဳ’ မှ ဆင်းသက်လာသည်။)','‘ဒြာဲမဂၠိုၚ် ပိုဲသ္အာဒဳနၚ် ပၠောပ်လဝ်ပ္ဍဲခရိုၚ်—။’ (ဇ—၁၂။ အစွောံ။) = ‘သမင်များစွာကိုငါတို့သွားမောင်းယူလာပြီး နှောင်အိမ်ထဲသို့ သွင်းထားကြမည်။’')
,(6875,3,1,'ဒီးဒုတ်ငှက်။ (?)','“တေဝ်တောဝ်ဒဳဒုတ်၊ ဂဍုတ်ဇိုၚ်ကြုၚ်။” (လိက်သောဝိန်ဇဲယ။ မာံရောဂေါ။) = “တစ်တီတူးနှင့်ဒီးဒုတ်ငှက်များသည် ချောင်းစပ်­ ကစားကျီစယ်ကုန်၏။”')
,(6876,3,10,'(န) ဒီပနီ။ (အကြောင်းရပ်တို့ကို အကျယ်တဝင့် ရှင်းလင်းဖွင့်ပြသောကျမ်း။)',NULL)
,(6877,3,14,'(န) ဒီမိုကရေစီ။ (ပြည်သူတို့၏ဆန္ဒအရ ပြည်သူ့ကိုယ်စားလှယ်များဖြင့် နိုင်ငံအုပ်ချုပ်သောစနစ်။) (အင်္ဂလိပ်၊ ္ၜဒမေံၚရအၚယ္ၜ)',NULL)
,(6878,3,11,'(န) မကောင်းမှု။ ဒုစရိုက်။ ပါဏာတိပါတစသည်ကို ကျူးလွန်သောအမှု။ (၁၊ သူ့အသက်သတ်ခြင်း။ ၂၊ သူ့ဥစ္စာခိုးခြင်း။ ၃၊ သူတစ်ပါးသားမယား ပြစ်မှာခြင်း။ (ကာယဒုစရိုက်သုံးပါး။) ၄၊ လိမ်လည်ခြင်း။ ၅၊ ကုန်းတိုက်ခြင်း။ ၆၊ ဆဲရေးတိုင်းထွာခြင်း။ ၇၊ အကျိုးမရှိသောစကားကို ပြောဆိုခြင်း။ (ဝစီဒုစရိုက်လေးပါး) ၈၊ သူတစ်ပါးကို မကောင်းကြံခြင်း။ ၉၊သူတစ်ပါးပျက်စီးအောင်ကြံခြင်း။ ၁ဝ၊ အယူမှားခြင်း။ (မနောဒုစရိုက်သုံးပါး) ဟူ၍ ဒုစရိုက်ဆယ်ပါးရှိသည်။)','(ပါဠိ—ဒုစ္စရိတ)')
,(6879,3,10,'(နဝိ) နှစ်ခုမြောက်။ ဒုတိယ။',NULL)
,(6880,3,12,'(န) ဗုံကြီးတစ်မျိုး။',NULL)
,(6881,3,10,'(န) နာရေးကိစ္စ။ ဒုမင်္ဂလ။','‘သုမၚ်္ဂလ’ (န) လည်းရှု။')
,(6882,3,1,'ဘီဒို။','(ကြိ) (ဒူးခေါင်းဖြင့်) တိုက်သည်။')
,(6882,3,1,'ဘီဒို။','ဒူကဵုတံၚ်က္ၜံၚ် = ဒူးဖြင့်တိုက်သည်။')
,(6883,3,1,'ကျော။ ကျောကုန်း။','“(ကၠဵုဂှ်) ဒၚ်လေံဒးဒူစးတုဲ—။” (ဇ—မဟောဟ်သဓ။ အစွောံ။) = “ထိုခွေးသည် ဒုန်းခနဲကျောပေါ်သို့တုတ်ကျ၍—။”')
,(6883,3,1,'ကျော။ ကျောကုန်း။','“နူဂှ်တိုန်ဒး၊ ဒူစးပိုဲဏအ်။” (လိက်ဇမ္ဗူပတိ။ မာံဒေံဍောတ်။)')
,(6884,3,10,'(န) တမန်တော်။',NULL)
,(6885,3,1,'ဒူးရင်းသီး။','“ဒူရေန်မၚ်ဂုတ်၊ သတ်မံၚ်ဟွံခြာ။” (လိက်ကကၠာ်။ ကောန်ဍး။) = “ဒူးရင်းမင်းဂွတ်တို့သည် မခြားမလပ်သီးနေကုန်၏။”')
,(6886,3,1,'ပခြုပ်။ ပူတာ။ (အဖုံးပါသည့် ထည့်စရာကျည်တောက်) (ပါဠိ—သမုဂ္ဂ)',NULL)
,(6887,3,12,'(န) လှူဖွယ်ဝတ္ထု။ လှူအပ်သောပစ္စည်း။ (ပါဠိ—ဒေယျဓမ္မ)','“ဝတ္ထုမဒှ်ဒေယျဓဝ်ဂှ်လေဝ် ဆဗၞတ်မွဲမွဲကီု ၝောံတံဟွံကဵုပိုဲမွဲလှ်ေသွံ။” (ဇ—၅၃၁။ အစွောံ။) = “လှူဖွယ်ဝတ္ထုပစ္စည်း တစ်စုံတစ်ခုကိုမျှလည်း ရှင်မတို့သည် ငါတို့အားမပေးစဖူး။”')
,(6888,3,10,'(န) နတ်။ ဒေဝါ။',NULL)
,(6889,3,11,'(န) နတ်။',NULL)
,(6890,3,1,'၁။ ဖူးစာရေးနတ်။','၂။ ဦးထိပ်နတ်။ ရိုသေလေးမြတ်အပ်သောသူ။')
,(6890,3,1,'၁။ ဖူးစာရေးနတ်။','“တၠအဲမဒှ်ကျာ်ပိုဲရ၊ တၠအဲမဒှ်ဒေဝတဴကသူကၞေၚ်ပိုဲရ၊ မဒှ်မိမပိုဲရ။” (အာန်ဇုနာန်) = “အရှင်သည် အကျွန်ုပ်တို့၏ဘုရားတည်း၊ အရှင်သည် အကျွန်ုပ်တို့၏ဦးထိပ်နတ်တည်း၊ အကျွန်ုပ်တို့၏မိဘတည်း။”')
,(6891,3,1,'လောကကိုစောင့်ရှောက်သောနတ်။ လောကပါလနတ်။',NULL)
,(6892,3,1,'မိုးနတ်သား။',NULL)
,(6893,3,1,'သစ်ပင်­တည်မှီသောနတ်။ ရုက္ခစိုးနတ်။',NULL)
,(6894,3,1,'လောကလူတို့ကို စောင့်ရှောက်တတ်သောနတ်မင်းကြီးလေးပါး။ (၁၊ ကုဝေရ (= ဝေဿဝဏ) ၊ ၂၊ ဓတရဋ္ဌ၊ ၃၊ ဝိရူပက္ခ၊ ၄၊ ဝိရူဠက။)',NULL)
,(6895,3,1,'အိမ်စောင့်နတ်။',NULL)
,(6896,3,1,'အာကာသစိုးနတ်။',NULL)
,(6897,3,11,'(န) နတ်ထင်းရူး။ (သစ်မွှေးတစ်မျိုး) (ပါဠိ—ဒေဝဒါရု)',NULL)
,(6898,3,11,'(န) ဒေဝဒတ်။ (ဂေါတမမြတ်စွာဘုရားကို ဖက်ပြိုင်အန်တုသောရဟန်း။)',NULL)
,(6899,3,11,'(န) နတ်ပြည်။ နတ်ဘုံလောက။ ဒေဝလောက။',NULL)
,(6900,3,10,'(န) ၁။ နတ်သမီး။ ဒေဝီ။','၂။ ဒေဝီ။ မိဖုရား။')
,(6901,3,1,'ယစ်ငှက်။ (ပါဠိ—ကိကိ)','“ညံၚ်ရဴဂစေံစေတ်ကွေတ် ဂစေံဒေဝေတ် မၚ်မွဲကၟာဲကီုကျာ်တြဲမမၚ်မွဲတဴခမဳဂမၠိုၚ်ရ။” (ဇ—၄ဝ၈။ အစွောံ။) = “ယစ်မသည် အဥကို စောင့်ရှောက်သကဲ့သို့ (မြတ်စွာဘုရားသည် ရဟန်းတို့ကို စောင့်ရှောက်တော်မူ၏။)” (ညောင်ကန်) (ဂစေံစေတ်ကွေတ် = ဂစေံဒေဝေတ်)')
,(6903,3,10,'(န) အရပ်။ ဒေသ။','“ဋ္ဌာန်ဒေသဂှ်တုန် မဒှ်ဥဿဒနရက်ရောၚ်။” (ဇ—၄၃၉။ အစွောံ။) = “ထိုအရပ်ဒေသသည် ဥဿဒငရဲဖြစ်၏။”')
,(6904,3,11,'(န) အရပ်တို့ကိုလှည့်လည်ခြင်း။ ဒေသစာရီ။','“ကျာ်တြဲဂ္ၚေၚ်အာဒေသစရိတ်တုဲ—။” (ဇ—၉၅။ အစွောံ။) = “မြတ်စွာဘုရားသည် ဒေသစာရီကြွချီတော်မူသည်။”')
,(6905,3,10,'(န) မြတ်စွာဘုရားဟောကြားသည့် တရားတော်။ တရားဒေသနာ။','(ကြိ) (ရဟန်း) အာပတ်ဖြေသည်။ ဒေသနာကြားသည်။')
,(6906,3,1,'ဝၚ်ရိုးစွန်းဒေသ။ (ကမ္ဘာမြေကြီး၏ တောင်ဘက်နှင့်မြောက်ဘက်ရှိ အစွန်ဆုံးဒေသ။)',NULL)
,(6907,3,10,'(န) ဒေသအလိုက် ပြောဆိုသုံးနှုန်းသောစကား။ ဒေသိယဝေါဟာရ။',NULL)
,(6908,3,10,'(န) တစ်ပါးသောအရပ်။ အရပ်တစ်ပါး။ အရပ်အထူး။','(နဝိ) ဒေသတစ်ပါးနှင့်ဆိုင်သော။')
,(6908,3,10,'(န) တစ်ပါးသောအရပ်။ အရပ်တစ်ပါး။ အရပ်အထူး။','“တၞဟ်နလ္ၚတ်ဒေသန္တရတုဲ ပိုဲအာစိုပ်ဍုၚ်ဗကာံရ။” = “ဒေသန္တရဗဟုသုတကို လေ့လာရန်အလို့ငှာ ကျွန်တော်တို့ ပုဂံမြို့သို့သွားကြသည်။”')
,(6909,3,1,'လူ၏အင်အား။ အသက်ရှင်နိုင်ရန်ခွန်အား။','“တ္ၚအဲမၞုံဒြဟတ်ဒဲလ္ၚီ ညးမပ္တိုန်မာန်ဂှ် ဇိုန်ကဵုကၟိန်ဍုၚ်ရအဴ။” (ဇ—မှာဇနက်။ အစွောံ။) (ဒဲ = ဒြဟတ်) = “လူဗိုလ်ခြေတစ်ထောင်အားရှိသော ငါ၏လေးကို တင်နိုင်သောသူအား တိုင်းပြည်ကိုအပ်နှင်းလော့။”')
,(6909,3,1,'လူ၏အင်အား။ အသက်ရှင်နိုင်ရန်ခွန်အား။','အိုတ်ဒဲ၊ ဒဲပၠိုတ် =သေသည်။ ဇီဝိန်ချုပ်သည်။')
,(6909,3,1,'လူ၏အင်အား။ အသက်ရှင်နိုင်ရန်ခွန်အား။','“သ္ကန်ကဵုအိုတ် ဒဲကဵုပၠိုတ်အာကီု။” (ဓမ္မဒေသနာ။ မာံရွှေငိုး။) =“အသက်ကုန်၍ ဇီဝိန်ချုပ်သွားစေကာမူ။”')
,(6910,3,10,'(န) ဒေါမနဿ။','‘ဒေါမၞုဟ်’ နှင့်အတူတူ။')
,(6911,3,11,'(န) စိတ်မချမ်းသာခြင်း။ နှလုံးမသာယာခြင်း။ ဒေါမနဿ။','“သၟိၚ်မတၠအဲက္တဵုဒှ်ဒေါမၞုဟ်ကဵုတၠအဲ ကၠာတေံဂှ် ဣနာဲဟီုကၞဳကၞံဗၠးရ” မှာဒေဝဳဂးကဵုဗညာနဲ။ (အကြီုရာဇာဓိရာဇ်) = “တူတော်မောင်၏ ခမည်းတော်မင်းကြီးက ယခင်တူတော်မောင်အား ဒေါမနဿဖြစ်ခဲ့သည်ကို အရီးတော်ပြောဆိုစေ့စပ်ပေး၍ ငြိမ်းသွားလေပြီ” ဟုမဟာဒေဝီက ဗညားနွဲ့အားပြော၏။')
,(6912,3,10,'(န) ၁။ အမျက်ထွက်ခြင်း။ ဒေါသ။','၂။ (စာပေ၊ ကျောက်မျက်စသည်၏) အပြစ်အနာအဆာ။')
,(6913,3,10,'(န) ဒေါသကြောင့်ဖြစ်သော အဂတိတရား။ ဒေါသာဂတိ။',NULL)
,(6914,3,4,'ပြေးရှောင်သည်။ ရှောင်ရှားသည်။ စွန့်ခွါသည်။','“ပ္ဍဲကာလဒေံဇကုတြဴမလှိၚ်အာဂှ် ဗောဓိသတ်ဂွံသမ္ဘာဇကုတုဲ ဒဴအာကၠေံရ။” (ဇ—၁၉၃။ အစွောံ။) = “ညီတော်ခြောက်ယောက်တို့အိပ်ပျော်စဉ် ဘုရားလောင်းသည် မိမိမယားကိုယူ၍ ပြေး၏။”')
,(6914,3,4,'ပြေးရှောင်သည်။ ရှောင်ရှားသည်။ စွန့်ခွါသည်။','“သဘဴသကိုပ်သာကွဳတံတုန်ယာံကျာပိုက်ကၠုၚ်နူဂတမုက်ဂှ် ဒဴလမၠိုက်လက်ကၠိုက်တုဲ ဂတညးအိုတ်ဟေၚ်မအာရ။” (ဇ—၁။အစွောံ။) = “လှည်းကုန်သည်ခေါင်းဆောင်တို့၏အလေ့သည် မျက်နှာချင်းဆိုင်အရပ်မှ လေတိုက်လတ်သော် မြူဖုံမှုန့်တို့မှ ရှောင်ရှားအံ့သောငှာ ရှေ့ဆုံးမှသွား၏။”')
,(6914,3,4,'ပြေးရှောင်သည်။ ရှောင်ရှားသည်။ စွန့်ခွါသည်။','“ဒဴဂရိုဟ်ဇန်တံတုဲ (ဗောဓိသတ်) မဒးပါန်လမျီု (ကဵုပုဏ္ဏက) ရောၚ်။” (ဇ—ဝိဓုရ။ အစွောံ။) = “လူတို့၏ကဲ့ရဲ့ခြင်းမှရှောင်ရှားရန် ဘုရားလောင်းသည် အသက်ချမ်းသာပေးရန် ပုဏ္ဏကအား တောင်းပန်ခြင်းဖြစ်၏။”')
,(6914,3,4,'ပြေးရှောင်သည်။ ရှောင်ရှားသည်။ စွန့်ခွါသည်။','“(သေဋ္ဌဳမဂမ္တက်ဂှ် အၚပ်သၟိက်ဂွံသုၚ်သုရာ) ဒဴမသ္ဒးကဵုညးသုၚ် မလုပ်အာပ္ဍဲဒေါဝ်သ္ပောဟ်ခြုံတုဲ မွဲဇကုမလုပ်အောပ်သုၚ်။” (ဇ—၇၈။ အစွောံ။) = “ထိုစေးနှဲသောသူဋ္ဌေးသည် အရက်သောက်လိုသော ချင်ခြင်းဖြစ်၍ သူတစ်ပါးတို့အား ပေးသောက်ရမည်မှရှောင်ရှားရန် (ပေးသောက်ရမည်စိုး၍) ချုံပုတ်ထဲသို့ဝင်ကာ တစ်ယောက်တည်း ပုန်း၍သောက်၏။”')
,(6914,3,4,'ပြေးရှောင်သည်။ ရှောင်ရှားသည်။ စွန့်ခွါသည်။','“တဟၚ်အၚပ်တၠအဲမွဲမွဲနွံသ္ဂးဟာ” သေဋ္ဌဳဗြဴသၟာန်၊ သေဋ္ဌဳကၞပ်သ္ၚံဒၟံၚ် ဒဴဒြပ်မဟုတ်။ (ဇ—၇၈။ အစွောံ။) =“တစ်စုံတစ်ခုသော သင်၏ချင်ခြင်းသည် ရှိပါသလော” ဟုသူဋ္ဌေးမမေးလတ်သော် ထို (စေးနှဲသော) သူဋ္ဌေးသည် ဥစ္စာကုန်အံ့သည်မှရှောင်ရှားရန် (ဥစ္စာကုန်မည်စိုး၍) ဆိတ်ဆိတ်နေ၏။')
,(6914,3,4,'ပြေးရှောင်သည်။ ရှောင်ရှားသည်။ စွန့်ခွါသည်။','“(တမ္ၚာဂှ်) ထောံသၞန်ထဍိၚ်ဒးဓဂဵု ဒးကဇၞော်ရောၚ်ဂးတုဲ ဒဴမဒးပရအ်ကဵုညးဝုတ်ဒိုဟ်တံဂှ် (ကဵုသမ္ဘာဇကုဗ္ဂန်ကၠေံသွေက်ဇွဵု ညးဝုတ်ဒိုဟ်တံဂှ်ရ။)” (ဇ—၁၃၉။ အစွောံ။) = “ထိုတံငါသည်သည်ငါးမျှားချိတ်ချရာ ၚုတ်­ငြိသည်ကို ငါးကြီးမိပြီဟုထင်မှတ်ကာ အိမ်နီးချင်းတို့အား (ငါးကို) ဝေပေးရမည်မှရှောင်ရှားရန် (ဝေပေးရမည်စိုး၍) မိမိမယားကို အိမ်နီးချင်းတို့နှင့် ခိုက်ရန်ပြုစေ၏။”')
,(6915,3,4,'ပျောက်ကွယ်စွန့်ခွါသည်။','“လဆောဝ်ဂှ်ဇကုဂျိုၚ်တဴ ပိုန်ဒြပ်တံဂှ် ဍေံကၠေံဒဴအာကၠာကီု။” (ဇ—၃၅၁။ အစွောံ။) = “တစ်ခါတစ်ရံ မိမိသည်အသက်ရှင်လျက် ဥစ္စာတို့သည် အလျင်ပျောက်ကွယ်စွန့်ခွါသွားတတ်၏။”')
,(6916,3,4,'သေလွန်စွန့်ခွါသည်။','“လဆောဝ်ပိုန်ဒြပ်ဂှ်နွံတဴ ဇကုချိုတ်ဒဴအာကၠာလေဝ်ဒှ်ကီု။” (ဇ—၃၅၁။ အစွောံ။) = “တစ်ခါတစ်ရံ ဥစ္စာတို့သည်ကျန်ရှိလျက် မိမိသည် အလျင်သေလွန်စွန့်ခွါသွားရတတ်၏။”')
,(6917,3,4,'(ဥစ္စာ) ဆုံးရှုံးစွန့်ခွါသည်။','“ဇကုနွံတဴ၊ ဒြပ်လေၚ်ဒဴအာ။” (လိက်ပယးအနိစ္စ) =“မိမိရှိလျက်လည်း မိမိဥစ္စာတို့သည် မိမိကိုစွန့်ခွါဆုံးရှုံးသွားတတ်၏။”')
,(6918,3,1,'မှူးကြီးမတ်ကြီး။ မှူးကြီးမတ်ရာ။','“အိုတ်ကဵုအမာတ်သကိုပ်ပၞာန် ဒဴဗညာသေနာပတိသီုဖအိုတ်တံဂှ် ဆဗၞတ်ညးမွဲကီု အေၚ်ဒုၚ်ဟွံမာန်တုဲ ဂတေဝ်ယာံတဴအိုတ်ရ။” (ဇ—၉၅။ အစွောံ။) = “အားလုံးသောအမတ်စစ်သူကြီး မှူးကြီးမတ်ရာသေနာပတိတို့သည် တစ်စုံတစ်ဦးမျှလည်း မအောင့်အည်းမမျိုသိပ်နိုင်ကြဘဲ သည်းစွာငိုကြကုန်၏။”')
,(6919,3,4,'မိမိကိုယ် ဘေးအန္တရာယ်မှလွတ်ရန် ထွက်ပြေးသည်။ အသက်လွတ်ရုန်းသည်။','“သၟိၚ်ဂှ်ကျအာပၞာန်ညးတုဲ တၞဟ်နဒဴဗလးဇကု ဍိုက်ကေတ်ချေံတုဲ ဒဴအာရ။” = “မင်းသည် ရန်သူ့စစ်ကိုရှုံးသွားပြီးနောက် အသက်လွတ်ရုန်းရန် မြင်းစီး၍ပြေး၏။”')
,(6920,3,4,'စစ်ဘေးမှရှောင်ပြေးသည်။',NULL)
,(6921,3,4,'၁။ ထိသည်။','“ဇိုၚ်ဗှ်ေဂှ် လ္ပကဵုဒးဇကုအဲညိ။” = “မင်းခြေထောက် ငါ့ကိုယ်ကို မထိပါစေနှင့်။”')
,(6921,3,4,'၁။ ထိသည်။','၂။ မှန်သည်။')
,(6921,3,4,'၁။ ထိသည်။','“အရေဝ်အဲ ဒးဟာဗၠေတ်ဟာ။” = “ငါ့စကားမှန်သလား မှားသလား။”')
,(6921,3,4,'၁။ ထိသည်။','(စည်း) ၁။ (ကြိရှေ့ဆက်) မလွှဲရှောင်သာခြင်းအနက်ဖြင့် ကြိယာကိုထောက်ပံ့သောစကားလုံး။—ရသည်။')
,(6921,3,4,'၁။ ထိသည်။','ဒးအာ = သွားရမည်။')
,(6921,3,4,'၁။ ထိသည်။','ဒးကၠောန် = လုပ်ရမည်။')
,(6921,3,4,'၁။ ထိသည်။','ဒးချိုတ် = သေရမည်။')
,(6921,3,4,'၁။ ထိသည်။','၂။ (ကြိနောက်ဆက်) အမှတ်မထင် ပြုမူခဲ့ခြင်းသဘောကို ပြသောစကားလုံး။—မိသည်။')
,(6921,3,4,'၁။ ထိသည်။','ဆဵုဒးကဵုအ္စာ = ဆရာနှင့်တွေ့မိသည်။')
,(6921,3,4,'၁။ ထိသည်။','ဟီုဒးအာ = ပြောလိုက်မိသည်။')
,(6921,3,4,'၁။ ထိသည်။','ရာန်ဒးကအုဲအုဲ =ပုပ်နေသောငါးကို ဝယ်မိသည်။')
,(6921,3,4,'၁။ ထိသည်။','၃။ (ကြိရှေ့ဆက်) ပြုမူခဲ့ခြင်းကို မသင့်ဟုထင်၍ နောင်တရသည့်သဘောဖြင့် သုံးသောစကားလုံး။—မိသည်။')
,(6921,3,4,'၁။ ထိသည်။','“မၚ်ဗၠာဲမိတ္တဝိန္ဒကဂှ် ဟိုတ်သရာံပါပ်မဒးထၞိက်စုတ်မိတုဲ ဒးဒုၚ်နရက်ဂျိုၚ်ဂျိုၚ်ရ။” = “မိတ္တဝိန္ဒကလုလင်သည် မိခင်ကို ကန်ကျောက်မိသောမကောင်းမှုကြောင့် အရှင်လတ်လတ်ငရဲခံရ၏။” (မှတ်ချက်။ ယနေ့ခေတ်တွင် ကြိရှေ့ဆက်အစား ကြိနောက်ဆက်အဖြစ် သုံးနေကြသည်။)')
,(6922,3,4,'နားနှင့်တွေ့သည်။ ကြိုက်နှစ်သက်သည်။','“ဍေံဟီုအရေဝ်အဲကလၚ်ဟွံဒးကတောဝ်ကွေံကွေံရ။” = “သူစကားပြောသည်မှာ ကျွန်တော့်နားနှင့်မတွေ့ပါ။”')
,(6922,3,4,'နားနှင့်တွေ့သည်။ ကြိုက်နှစ်သက်သည်။','“ဂလာန်ဟီုသွံ၊ ဟွံဒးက္တောဝ်ၜါ။” (လိက်ဇိဝှစက္က) = “ပြောသောစကားကား နားနှင့်မတွေ့ မနှစ်သက်။”')
,(6923,3,4,'အချိန်တန်သည်။ အချိန်ကျသည်။ အချိန်ရောက်သည်။','“ယွံသၟိၚ်မပြဲ၊ ပ္ဍဲကာလဝွံဒးကာလသဘၚ်မ္ၚဵု မကဵုမ္ၚဵုစိၚ်ရသွံအဴ” ဗမၞးတအ်ဂး။ “ဒးကာလကွေံရ” သၟိၚ်ဂး။ (ဇ—၁၆၃။ အစွောံ။) = “မြတ်သောမင်းကြီး၊ ယခုအခါသည် ဆင်မင်္ဂလာပြုရန် အချိန်ရောက်ပြီ” ဟုပုဏ္ဏားတို့ဆိုကုန်၏။ “အချိန်ရောက်သည်မှန်၏” ဟုမင်းဆို၏။')
,(6923,3,4,'အချိန်တန်သည်။ အချိန်ကျသည်။ အချိန်ရောက်သည်။','“လၟုဟ်ဝွံအဲသဒဴအာ ဒးကာလရ”ကမၠတ်ဂှ်ချပ်။ (ဇ—၃၁၈။ အစွောံ။) = “ယခုငါသည် ပြေးခြင်းငှာ အချိန်တန်ပြီ။”')
,(6924,3,4,'အကျိုးဖြစ်ထွန်းရန် အချိန်ကျရောက်သည်။',NULL)
,(6925,3,4,'အလုပ်လုပ်ရသည်။','“ယွံကော၊ ပိုဲညးၜါဒုၚ်ဒၟံၚ် ဒးကေၚ်ကာညးဂှ် ဆံက်ကၟတ်သၠဒုန်ရောၚ်မဂွံစ၊ ကၠိက်မုဏိကဂှ် ဍေံဟွံဒးကေၚ်ကာ ပုၚ်ယာဂု ဍေံမဂွံစရောၚ်သွံကော” ဂၠဴဒေံဂှ်ဟီုကဵုဂၠဴကောဂှ်ရ။ (ဇ—၃ဝ။ အစွောံ။) = “အစ်ကို၊ ငါတို့နှစ်ဦးသည် အလုပ်လုပ်ရသော်လည်းကောက်ရိုး၊ မြက်၊ ဝါးရွက်တို့ကိုသာ စားရ၏။ မုဏိကမည်သောဝက်သည်ကား အလုပ်မလုပ်ရဘဲ ယာဂုထမင်းကို စားရ၏” ဟုညီနွားသည် အစ်ကိုနွားအားပြော၏။')
,(6926,3,4,'သဘောတွေ့သည်။ ကြိုက်သည်။','“ဗှ်ေစကာဍေံမ္ဂး ကာလဒးကဵုစိုတ်ဍေံ ဍေံကၠောန်ရ။ ကာလဟွံဒးကဵုစိုတ်ဍေံမ္ဂး ဍေံဟွံကၠောန်ရ။”= “နင်သူ့ကိုခိုင်းလျှင် သူသဘောတွေ့သောအခါ သူလုပ်ပေးသည်။ သူသဘောမတွေ့သောအခါ သူမလုပ်ပါ။”')
,(6927,3,4,'တရားနည်းလမ်းကျသည်။','“ဂလာန်မဒးကဵုသၞောဝ်ဂၠံၚ်ဂှ်ဟေၚ် ဟီုညိ။ ဂလာန်ဟွံဒးကဵုသၞောဝ်ဂၠံၚ်ဂှ် လ္ပဟီုညိ။” = “တရားနည်းလမ်းကျသော စကားကိုသာလျှင် ပြောဆိုပါ။ တရားနည်းလမ်းမကျသောစကားကို မပြောဆိုပါနှင့်။”')
,(6928,3,4,'ခံတွင်းတွေ့သည်။ ကြိုက်နှစ်သက်သည်။','“သွကဏအ် အဲဒးကအ်ကွေံရ။” =“ဤငါးဟင်းကို ကျွန်တော်တကယ်ခံတွင်းတွေ့သည်။”')
,(6929,3,4,'လိုရာစံနှုန်းနှင့်ညီသည်။ လိုအင်နှင့်ညီသည်။','‘စရာဲရုပ် ညံၚ်ကဝ်လဗဗြိုက်မဒးကၞာတ်—။’ (ဇ—ဝိဓုရ။ အစွောံ။) = ‘ရုပ်အဆင်းအသရေသည် လိုအင်နှင့်အညီဖြစ်သော နတ်­ဖြစ်သောပဒေသာပင်ကဲ့သို့တည်း။’')
,(6929,3,4,'လိုရာစံနှုန်းနှင့်ညီသည်။ လိုအင်နှင့်ညီသည်။','“ပါရမဳကာန်၊ လိက်ဋ္ဌာန်လစောန်။ ဗၟာတအ်သမတ်၊ ပပြာကတ်လောန်။ လိက်ဗမာသွံ၊ ကၠာဲကလောအ်မန်။ ဝေါဟာမန်ဂး၊ ကဵုစဳပျးဆန်။ အၚ်ဝစေတ်ကိုင်၊ ကဝိဂၠိုၚ်သန်။ ပျးဟွံဒးကၞာတ်၊ လိက်ဂှ်ဝါတ်သန်။” (လိက်ပါရမဳကာန်။ အစွောံ။) = “ပါရမီခန်းပျို့သည် နက်နဲခက်ခဲလှသောကြောင့် လိုရာစံနှုန်းနှင့်အညီ ပီပြင်အောင်မပြန်ဆိုနိုင်ကြ။”')
,(6929,3,4,'လိုရာစံနှုန်းနှင့်ညီသည်။ လိုအင်နှင့်ညီသည်။','“ဂေါဝ်ဂပ်ဒးကၞာတ်၊ ပြာသာတ်မတၟေၚ်။” (လိက်ဗြရတ်ဣဏၚ်ကၚ်ရဳ) = “တင့်တယ်လှပ၍ စံနှုန်းနှင့်ညီသော ထူးခြားသောပြာသာဒ်။”')
,(6930,3,4,'လေဖြတ်ခံရသည်။','“ထဴဗျုဂှ် ဒးအာကျာတုဲ ကွာ်ဟွံဂွံရ။” = “အဖိုးအိုသည် လေဖြတ်ခံရသဖြင့် လမ်းလျှောက်၍မရတော့ပါ။”')
,(6931,3,4,'အအေးမိသည်။ နှာစေးသည်။','“ဒးချာံသ္ဍက်ဂၠိုၚ်သန်။” (လိက်လက္ခဏဒိပ္ပဗိန္ဒော)')
,(6932,3,4,'နှစ်သက်သည်။ အလိုရှိသည်။','“ပ္ဍဲကာလဟိုတ်ကိစ္စမွဲမွဲမက္တဵုဒှ်ဂှ် တၠပညာဟေၚ် ညးမဒးဂၞပ်ရ။” (ဇ—၉၂။ အစွောံ။) = “နက်နဲသောပြဿနာသည် ဖြစ်လတ်သော်လည်း ပညာရှိကိုအလိုရှိကုန်၏။” (ညောင်ကန်)')
,(6932,3,4,'နှစ်သက်သည်။ အလိုရှိသည်။','“ဟာဲလဗၚ်တံ၊ ပွဗှ်ေတံ ဟွံဒးဂၞပ်အဲဟေၚ်။” (ဇ—၅၃။ အစွောံ။) = “ဟယ်သေသောက်ကြူးတို့၊ သင်တို့၏အမူအရာကို ငါမနှစ်သက်။”')
,(6932,3,4,'နှစ်သက်သည်။ အလိုရှိသည်။','“(ပြဝမၞးတံညးၜါဂှ်) ဟွံဒးဂၞပ်အဲသက်က်ရ။” (ဇ—၁၉၉။ အစွောံ။) = “သင်တို့နှစ်ယောက်၏အပြုအမူကို လုံးဝငါမနှစ်သက်။ (ဝါ) ငါ့အကြိုက်နှင့်မတွေ့။”')
,(6933,3,4,'အခါအခွင့်သင့်သည်။ အချိန်အခါသင့်သည်။','“သရာံပါပ်ဂှ် ဟွံဒးဂွာံကာလ ဍေံဟွံဂွံကဵုဖဵုဏီရောၚ်။” (သၠပတ်အနမတဂ္ဂသံသာရကထာ) = “ထိုမကောင်းမှုကံသည်အခါအခွင့်မသင့်သေး၍ အကျိုးမပေးရသေး။”')
,(6933,3,4,'အခါအခွင့်သင့်သည်။ အချိန်အခါသင့်သည်။','“ဒးဂွာံကာလ အမာတ်လ္ၚောဝ်ပ္တီသၟိၚ်ရ။” (ပေါရဏာံပေါရဒံါ။ အစွောံ။) = “အခါအခွင့်သင့်၍ အမတ်သည် မင်းအားရှိခိုးလျှောက်တင်၏။”')
,(6933,3,4,'အခါအခွင့်သင့်သည်။ အချိန်အခါသင့်သည်။','“တ္ၚဲဂၠုဒးဂွာံ၊ ညန်သာံမယ။” (လိက်သောဝါနနဟောၚ်) = “မိုးချုပ်၍အချိန်အခါသင့် အခါသမယနီးလတ်သော်။”')
,(6933,3,4,'အခါအခွင့်သင့်သည်။ အချိန်အခါသင့်သည်။','‘ဂွာံ’ (န) လည်းရှု။')
,(6934,3,4,'ဂိုဏ်းသင့်သည်။ (ရိုသေအပ်သည်ကို ပြစ်မှားမိ၍ ဘေးဖြစ်သည်။)','ဒးစရဲအ္စာ = ဆရာဂိုဏ်းသင့်သည်။')
,(6934,3,4,'ဂိုဏ်းသင့်သည်။ (ရိုသေအပ်သည်ကို ပြစ်မှားမိ၍ ဘေးဖြစ်သည်။)','ဒးစရဲရတ်ပိပြကာ = ရတနာသုံးပါးဂိုဏ်းသင့်သည်။')
,(6935,3,4,'လိမ္မာစွာပြောဆိုသည်။ နှုတ်ရေးကောင်းသည်။ နှုတ်ဂုဏ်မြောက်သည်။','“ပတၠပါၚ်ရ ဟီုကဵုဒးစရာဲပါၚ် ဇၟာပ်ပေဲါညိ။” (ဇ—၂၈။ အစွောံ။) = “လိမ္မာသောနှုတ်ရှင်ဖြစ်၍ ပွဲတိုင်း­ နှုတ်ဂုဏ်မြောက်အောင် ပြောဆိုပါလေ။”')
,(6936,3,4,'ကြိုက်သည်။ စိတ်တွေ့သည်။ သဘောကျသည်။','“ယာတ်ဏအ် အဲဒးစိုတ်ကွေံရ။”= “ဤအဝတ်ကို ကျွန်တော်အလွန်ကြိုက်သည်။”')
,(6937,3,4,'ဒုက္ခဖြစ်သည်။ ဒုက္ခတွေ့သည်။','“ဂစေံမဂိုၚ်ဖျုန်ဂှ် ဒးဒဒိုက်ဗွဲမလောန်ရ။” (ဇ—၄ဝ၈။ အစွောံ။) = “အသားကိုချီသောငှက်သည် အလွန်ဒုက္ခဖြစ်ရ၏။”')
,(6938,3,4,'လောင်းရိပ်မိသည်။',NULL)
,(6939,3,4,'ဒေသမှန်သည်။ ဒေသလျော်ညီသည်။','“ညးၜါအာတ်နၚ်ဓါတ်သော်မသုန်တၞုၚ်ကေတ်ဖျဴနၚ်ရးမန်ပိထာန် ဒၞာဲမဒးဒေသဂှ် — ဒၞာဲမဒး ထာပဏာလဝ်ရ။” (ရာဇာထ္ၜုတ်) =“နှစ်ယောက်သားတို့သည် ဆံတော်ငါးဆူကို တောင်းခံယူလာပြီးလျှင် မန်ဋ္ဌာနသုံးရပ်သို့ ပင့်ဆောင်လာကာ ဒေသလျော်ညီရာနေရာ­ ဋ္ဌာပနာထား၏။”')
,(6939,3,4,'ဒေသမှန်သည်။ ဒေသလျော်ညီသည်။','“ထာန်ဝွံဒးဒေသ၊ ကၠောန်ဍုၚ်ကၠာရသ္ဒဟ်။” (လိက်ဂၞကျာ်ဝိသာခါ) = “ဤအရပ်သည် ဒေသလျော်ညီ၏၊ မြို့တည်ကြအံ့။”')
,(6940,3,4,'အပြစ်ဒဏ်ခံရသည်။','“မၞးတံညးၜါဂှ် အာမံၚ်ကေတ်နူဂယး ဒဵုသဝ်တ္ၚဲရောၚ်သွံ။ မၞးတံဒးဒဏ်ရောၚ်။” (ဇ—၄၆၁။ အစွောံ။) = “သင်တို့နှစ်ယောက်သည် မနံက်မှသည် ညနေအထိ (အချိန်လွန်အောင်) သွားနေခဲ့ကြ၏။ သင်တို့အပြစ်ဒဏ်ခံကြရလိမ့်မည်။”')
,(6941,3,4,'နေရာကျသည်။ အရာဟုတ်သည်။','“သ္ပအ္စာတက်ဝေတ်ကွးမ္ဂး ကဵုဒးဒၞာဲညိ။ တက်ဝေတ်ဟွံဒးဒၞာဲမ္ဂး အ္စာဂှ်သြဇာစှ်ေရောၚ်။” = “ဆရာလုပ်၍ တပည့်အား ရိုက်ပုတ်ဆုံးမလျှင် နေရာမှန်ပါစေ။ အရာမဟုတ်သည်­ ရိုက်ပုတ်ဆုံးမလျှင် ဆရာသိက္ခာကျလိမ့်မည်။”')
,(6942,3,4,'၁။ ရိုက်နှက်အပြစ်ပေးခြင်း ခံရသည်။','“ဒးဒွဵုကၠံလစုတ်။” = “အချက်တစ်ရာ အရိုက်ခံရသည်။”')
,(6942,3,4,'၁။ ရိုက်နှက်အပြစ်ပေးခြင်း ခံရသည်။','၂။ ဒဏ်ရာရသည်။ လက်နက်ဒဏ်သင့်သည်။')
,(6942,3,4,'၁။ ရိုက်နှက်အပြစ်ပေးခြင်း ခံရသည်။','“ပ္ဍဲဋ္ဌာန်စၞေဟ်) ချေံသိန္ဓဴဒးစုတ်ဒွဵုတုဲ ဆီညံၚ်ဇၟောဝ်ဍာ်ကီု။” (ဇ—၂၃။ အစွောံ။) = “သိန္ဓောမြင်းသည် စစ်မြေပြင်­ ထိခိုက်ဒဏ်ရာရ၍ ရေအယဉ်ကဲ့သို့ သွေးယိုစီး၏။”')
,(6942,3,4,'၁။ ရိုက်နှက်အပြစ်ပေးခြင်း ခံရသည်။','“လၟုဟ်ဝွံကဵုခပက်ဂစိုတ်လ္ဂန်အိန် ဒးဒွဵုဗွဲမဂၠိုၚ်ဝွံ ဟွံဒွး” ဖရၚ်မၚ်ဂံၚ်ဂး။ (အကြီုရာဇာဓိရာဇ်) = “ယခုလဂွန်းအိန်အား ထိုးသတ်စေ၍များစွာဒဏ်ရာရအောင်ပြုခြင်းမှာမမှန်” ဟုဘုရင်မင်းခေါင်ဆို၏။')
,(6943,3,4,'အလှည့်ကျသည်။','“(ခမဳကောကာလိကဂှ်) တ္ၚဲဝွံဒးဓဝါ (သွက်ဂွံတွံဓဝ်) ဂးရ။” (ဇ—၁၇၂။ အစွောံ။) = “ကောကာလိကမည်သောရဟန်းသည် ယနေ့တရားဟောရန် အလှည့်ကျ၏ဟုဆို၏။”')
,(6944,3,4,'ငရဲကျသည်။','“—၊ လ္ၚဵုဒးနရက် လ္ၚဵုဒှ်ပြိုတ် လ္ၚဵုဒှ်ကလော် လ္ၚဵုဒှ်တိရစ္ဆာန်ရ။” (ဇ—၉၁။ အစွောံ။)')
,(6945,3,4,'အချိန်အခါတန်သည်။','“ပ္ဍဲဂှ် ဒးပယာံအခါရဂးတုဲ သၟိၚ်အလဳမာမၚ် (ဇက်တိတ်အာကဵုမဂဒူရ) ။” (အကြီုရာဇာဓိရာဇ်) = “ထို­အချိန်အခါတန်ပြီဟုဆိုကာ အလိမ္မာမင်းသည် မဂဒူးရှိရာသို့ ထွက်ချီသွား၏။”')
,(6945,3,4,'အချိန်အခါတန်သည်။','“သၟိၚ်သူရိယျ၊ တလစက်ထဝ်။ ဒးပယာံဟေၚ်၊ မာတ်မစေၚ်သဝ်။” (လိက်သောဝိန်ဇဲယ။ မာံရောဂေါ။) = “ရွှေစက်ဝန်းရှင် သူရိယနေမင်းသည် စောင်းကျချိန်တန်လတ်သော်။”')
,(6946,3,4,'လိုအင်နှင့်ကိုက်ညီသည်။ အကြိုက်တွေ့သည်။','“နူတၠအာယုက်ညးဇမၞော်ဂှ်ပ္တီ ဗညာမိၚ်ဒးကဵုပၟိက်ဗွဲမလောန် ကဵုလာဘ်ပဿကာ ကဵုတၠအာယုက်ဂှ်။” (အကြီုရာဇာဓိရာဇ်) = “ထိုအသက်ကြီးသူပြောသည်ကို ဗညားနွဲ့သည် အကြိုက်တွေ့၍ ထိုသူကို ဆုလာဘ်များစွာပေး၏။”')
,(6947,3,4,'အကျဉ်းချခံရသည်။ ဖမ်းဆီးချုပ်နှောင်ထားခြင်းခံရသည်။','မၞိဟ်မဒးပၟၚ် = အချုပ်သား။ ထောင်သား။ ဖမ်းဆီးချုပ်နှောင်ခံထားရသူ။ အကျဉ်းသား။')
,(6948,3,4,'မှန်သောအပြုအမူဖြစ်သည်။ သင့်သောအမှုဖြစ်သည်။ သင့်သည်။','“သဘဴကောန်မ္ဂး စှ်ေစးဂလာန်မိကဵုမမ္ဂး ဟွံဒးပွသွံ။” (ဇ—၂၄၃။ အစွောံ။) = “သားသမီးမည်သည်မိဘစကားကို လွန်ဆန်ခြင်းသည် မသင့်သောအမှုပါတကား။”')
,(6948,3,4,'မှန်သောအပြုအမူဖြစ်သည်။ သင့်သောအမှုဖြစ်သည်။ သင့်သည်။','“ဋ္ဌာန်ရသိပြဲ၊ ဟွံစိုပ်မွဲဝါ။ သီုကောန်ၚာ်ၜါ၊ အာရောၚ်ဒးပွ။” (လိက်မိဒေဝကိနနရဳ။ နာဲသိုက်ဇု။) = “ရသေ့မြတ်ထံပါးသို့တစ်ကြိမ်မျှမရောက်သေး။ ကလေးနှစ်ယောက်ကိုပါ ခေါ်ဆောင်၍သွားခြင်းသည် သင့်သောအမှု ဖြစ်၏။”')
,(6948,3,4,'မှန်သောအပြုအမူဖြစ်သည်။ သင့်သောအမှုဖြစ်သည်။ သင့်သည်။','“သာ်ဂှ်အဲသ္ပ၊ ဒးပြဝရောၚ်။” (လိက်ဟတ္ထိပါလ။ အစွောံ။) = “ထိုသို့ပြုခြင်းသည်မှန်သောအမှုဖြစ်၏။”')
,(6948,3,4,'မှန်သောအပြုအမူဖြစ်သည်။ သင့်သောအမှုဖြစ်သည်။ သင့်သည်။','“ကၟန်စဴပြဟ်၊ ဂှ်ရောၚ်ဒးပွ။” (လိက်ကောန်သၟိၚ်ဝါရဝေါၚ်သ။ အစွောံ။) = “အမြန်ပြန်ခြင်းသည်သာလျှင် သင့်သောအမှုဖြစ်၏။”')
,(6948,3,4,'မှန်သောအပြုအမူဖြစ်သည်။ သင့်သောအမှုဖြစ်သည်။ သင့်သည်။','“လၟုဟ်ပိုဲဒၟံၚ်အာသာ်ဝွံ ဟွံဒးပွ။” (ရာဇာထ္ၜုတ်) = “ယခုငါတို့တွေ ဤအတိုင်းနေသွားပါက မသင့်။”')
,(6949,3,4,'ကျည်ထိမှန်သည်။ မြှားထိမှန်သည်။','“ဒြာဲဂှ် ဒးပွန်လၟတုဲ ချိုတ်အာရ။” = “သမင်သည် မုဆိုး၏မြှားချက်ကိုထိမှန်၍ သေသွား၏။”')
,(6949,3,4,'ကျည်ထိမှန်သည်။ မြှားထိမှန်သည်။','“ဇဲယသူရဒှ်ဒကိုပ်ပၞာန် ဒးပဝန်ချိုတ်အာပၠန်။” (အကြီုရာဇာဓိရာဇ်) = “စစ်သူကြီးဖြစ်သော ဇေယျသူရသည် ကျည်ထိမှန်၍ သေပြန်၏။”')
,(6950,3,4,'နေခြည်ထိုးသည်။','“ပ္ဍဲကၟေၚ်လ္ပာ်လက်ကြဴသ္ၚိဂှ် ကာလတ္ၚဲစေၚ် ဒးဒၟံၚ်ပွန်တ္ၚဲရ။ (ဝါ) ဒးဒၟံၚ်ဗပန်တ္ၚဲရ။” = “အိမ်နောက်ပိုင်းကပြင်တွင် နေစောင်းသောအခါ နေခြည်ထိုးနေသည်။”')
,(6950,3,4,'နေခြည်ထိုးသည်။','“ဂၞကျာ်မွဲဒးပွန်တ္ၚဲ သြေၚ်ဖ္ဍီုအာ။” (ဓမ္မသာတ်။ MDT VII) = “မိဖုယားသည် နေခြည်ထိုးခံရ၍ ညှိုးနွမ်းသွား၏။”')
,(6951,3,4,'အတွဲညီသည်။ လိုက်ဖက်ညီသည်။','“လ္ဂန်အိန်လေဝ်ဂံၚ် သဒဵုလေဝ်ဂံၚ် ဒကိုပ်ပၞာန်ၜါဝွံ ဒးဖွက်ကွေံ။” (အကြီုရာဇာဓိရာဇ်) = “လဂွန်းအိန်လည်း ရဲရင့်၏။ သတိုးလည်း ရဲရင့်၏။ (မွန်နှင့်ဗမာ) စစ်ဗိုလ်နှစ်ဦးတို့သည် တကယ်လိုက်ဖက်ညီ၏။”')
,(6952,3,4,'၁။ အတော်ကျသည်။','“သွကဍုန်လဝ်ဂှ် ဟွံပ္ဍုၚ်လောန် ဟွံဖျးလောန် စဒးဗစပ်ကွေံရ။” = “ချက်ထားသောငါးဟင်းသည် မၚန်လွန်း မချဉ်လွန်း စား၍အတော်ကျသည်။”')
,(6952,3,4,'၁။ အတော်ကျသည်။','၂။အဆင်သင့်သည်။')
,(6952,3,4,'၁။ အတော်ကျသည်။','“အဃောစပုၚ်စိုပ်ကၠုၚ် ဒးဗစပ်ရ။ စပုၚ်တုဲစဴမူဒှ်ရော။” = “ထမင်းစားနေတုန်း ရောက်လာသည်။ အဆင်သင့်တာဘဲ ထမင်းစားပြီးမှပြန်ပါလား။”')
,(6953,3,4,'အဖက်အစပ် အတော်ကျသည်။','“သွဂှ် ဖၞုၚ်ဗစးဒးဗစပ်ပရာပ်ကွေံ။” =“ထိုဟင်းသည် အချဉ်အၚန်အဖက်အစပ် တကယ်အတော်ကျသည်။”')
,(6954,3,4,'ဝန်းရံခြင်းခံရသည်။ အဝိုင်းခံရသည်။','“ကၞုဲဂမၠိုၚ်မဒးဗဝိုၚ်မၞိဟ်တံဝွံ ဒှ်ပရိုက်အိုတ်ရောၚ်သွံ။” (ဇ—၁၇၇။ အစွောံ။) = “လူတို့၏ဝိုင်းရံထားခြင်းကို ခံရသောမျောက်များသည် ဘေးတွေ့နေကြကုန်ပြီတကား။”')
,(6955,3,4,'ပုံစံကျသည်။ ဟန်ကျသည်။ အဆင်ပြေသည်။','“ကလောန်ဒးဗီုဒၟံၚ်ရဟာ။” = “အလုပ်အဆင်ပြေပါသလား။”')
,(6955,3,4,'ပုံစံကျသည်။ ဟန်ကျသည်။ အဆင်ပြေသည်။','“ဖျေံလဝ်ဒပ်အဏံဂှ်လေဝ် ဟွံဒးဗီုဏီ။” (အကြီုရာဇာဓိရာဇ်) =“ဤနေရာ­ တပ်စခန်းချထားသည်မှာလည်း ပုံစံမကျသေး။”')
,(6956,3,4,'အနေတော်ဖြစ်သည်။ အလောတော်ဖြစ်သည်။ မယုတ်မလွန်ဖြစ်သည်။ အံကိုက်ဖြစ်သည်။','“သၟတ်တြုံဂှ် ဟွံသၠုၚ်လောန် ဟွံသဝ်လောန် မၞုံကဵုသမၠုၚ်ဒတဴမဒးဗၞတ်ရ။” = “ထိုသူငယ်သည် မမြင့်လွန်း မနိမ့်လွန်း အရပ်အမောင်း အနေတော်ဖြစ်သည်။”')
,(6956,3,4,'အနေတော်ဖြစ်သည်။ အလောတော်ဖြစ်သည်။ မယုတ်မလွန်ဖြစ်သည်။ အံကိုက်ဖြစ်သည်။','“သၟတ်ဗြဴဂှ် ဟွံဗ္တာၚ်လောန် ဟွံဒျိုၚ်လောန် မၞုံသာ်ဇကုမဒးဗၞတ်ရ။” = “ထိုသူငယ်မသည် မဖြူလွန်း မမည်းလွန်း၊အသားအရောင် အနေတော်ဖြစ်သည်။”')
,(6956,3,4,'အနေတော်ဖြစ်သည်။ အလောတော်ဖြစ်သည်။ မယုတ်မလွန်ဖြစ်သည်။ အံကိုက်ဖြစ်သည်။','“မပပြဘိုက်အဟာဒးဗၞတ် ဟွံဂၠိုၚ်ဟွံအောန်ဂှ်ကီု။” (ဇ—၃၉၄။ အစွောံ။) = “မများလွန်းမနည်းလွန်း အနေတော်ပမာဏဖြစ်သော အာဟာရကို သုံးဆောင်၍လည်းကောင်း။”')
,(6956,3,4,'အနေတော်ဖြစ်သည်။ အလောတော်ဖြစ်သည်။ မယုတ်မလွန်ဖြစ်သည်။ အံကိုက်ဖြစ်သည်။','“ပ္ဍဲကာလဂှ် သၟတ်ဗြဴဂှ် ဆီဥတုဆဒးဗၞတ် ဟွံခန်လောန်ဟွံဆာလောန်မဒှ်ရ။” (ဇ—၄၉၇။ အစွောံ။) = “ထိုအခါ­ ထိုအမျိုးသမီးငယ်၏ ရာသီသွေးသည် မပျစ်လွန်းမကျဲလွန်း အနေတော်ဖြစ်၏။”')
,(6956,3,4,'အနေတော်ဖြစ်သည်။ အလောတော်ဖြစ်သည်။ မယုတ်မလွန်ဖြစ်သည်။ အံကိုက်ဖြစ်သည်။','“ပ္ဍဲသုတ်ဇာတ်ဝွံဂှ် ဗောဓိသတ်ဝေတ်ညးဟွံဒးဗၞတ်တုဲ မဒးပကာဂစိုတ်ရ။” (ဇ—၄၉၇။ အစွောံ။) = “ဤဇာတ်တော်­ ဘုရားလောင်းသည် သူတစ်ပါးအားဆုံးမရာ­ အံကိုက်မဖြစ်သဖြင့် သေရလေ၏။”')
,(6956,3,4,'အနေတော်ဖြစ်သည်။ အလောတော်ဖြစ်သည်။ မယုတ်မလွန်ဖြစ်သည်။ အံကိုက်ဖြစ်သည်။','“ဇရေၚ်မိမ ဇရေၚ်အ္စာဂှ်ဒၟံၚ် ရံၚ်ဒ္ဂေတ်ညးခိုဟ်ဒးဗၞတ်ဂှ် ဂပ်ဂဝ်ဂိုၚ်လ္ၚတ်ကေတ်ညိ—။” (ဇ—၁၁၉။ အစွောံ။) = “မိဘအထံ­၄င်း ဆရာ့အထံ­၄င်းနေ၍ မယုတ်မလွန်ကောင်းသောအကျင့်ကို ကြည့်ရှု၍ လေ့လာဆည်းပူးအပ်၏။”')
,(6957,3,4,'ငရဲကြီးသည်။ ငရဲတွင်ခံရသည်။','“ဒးဘဝသ္ကဲ၊ မွဲတဲဟေၚ်ရ။ ဒးနရက်အဵု၊ တွဵုတ္ၚဲဂျ။” (လိက်ကကၠာ်။ ကောန်ဍး။) = “တစ်ကြိမ်တစ်ခါငရဲကြီး၍ ထိုနေ့မှစ၍ ငရဲကျခံရ၏။”')
,(6958,3,4,'ဘေးတွေ့သည်။ ဘေးသင့်သည်။','“ပိုဲၚဴမဒးဘဲဂဍာ်ရောၚ်။” (ဇ—၅၂ဝ။ အစွောံ။) =“ငါတို့ဖားမျိုးတို့သည် ကျီးဘေးသင့်ကုန်၏။”')
,(6959,3,4,'မျက်စိပသာဒဖြစ်သည်။ မျက်စိအကြိုက်တွေ့သည်။ နှစ်သက်သည်။','“ညာတ်ရုပ်ဒးမတ်။ စိုတ်ဒးကၠတ်ဆာန်။” (လိက်မေဃသန်) = “မျက်စိပသာဒဖြစ်သော ရုပ်လွှာကိုမြင်၍ တိတ်တခိုးချစ်မိသည်။”')
,(6960,3,4,'ကောင်းမွန်သည်။ သင့်လျော်သည်။ လျောက်ပတ်သည်။','“ဒးရးတဴပြဲ၊ တ္ၚဲဏံအဲသ္အာ။” (လိက်ဇိဝှစက္က) = “ကောင်းမွန်သင့်လျော်ပေစွ၊ ယနေ့အကျွန်ုပ်သွားပါမည်။”')
,(6961,3,5,'ကောင်းစွာ။ လျောက်ပတ်စွာ။','“ယွံဗဂေါဝ်၊ — ဇြုံဂှ် အဲဒလောံဗတောန်ဒးရးထေက်တုဲရ၊ မၞးလ္ပဖေက်ရ” ဣသိဂး။ (ဇ—၁၆၅။ အစွောံ။) = “မြွေပါ၊ ထိုမြွေကို ငါသည်ကောင်းစွာဆုံးမအပ်ပြီ၊ သင်မကြောက်လင့်” ဟုရသေ့ဆို၏။')
,(6961,3,5,'ကောင်းစွာ။ လျောက်ပတ်စွာ။','‘ထေက်ဒးရး’ နှင့်အတူတူ။')
,(6962,3,4,'‘ဒးဝပ်’ နှင့်အတူတူ။','အဖမ်းခံရသည်။ ဖမ်းဆီးခြင်းခံရသည်။')
,(6962,3,4,'‘ဒးဝပ်’ နှင့်အတူတူ။','ဂိတုဒးလွပ်ရာဟု= “လသည် ရာဟုဖမ်းခြင်းခံရသည်။ လကြတ်သည်။ လၚပုပ်ဖမ်းသည်။”')
,(6962,3,4,'‘ဒးဝပ်’ နှင့်အတူတူ။','“အဲပသၟိၚ်လၟုဟ်ဝွံဂှ်ရာၚ်ဆာဲဒၟံၚ် ပ္ဍဲဒေါဝ်ပိုန်ဟာန်ယဿပတ်ရ။ ယဝ်ရညးသ္အာၚ်ထဏေန်စိုတ် ပ္ဍဲကၟိန်ဍုၚ်တုဲ ရပ်ဒလုကၠေံအဲ ညံၚ်ရဴဂိတုမဒးလွပ်ဘဲရာဟုဂှ်ကီုရသွံ။” (ဇ—၄ဝ၆။ အစွောံ။) = “ယခုငါမင်းပြုသည်မှာစည်းစိမ်ဥစ္စာအလယ်­ တင့်တယ်၍နေ၏။ အကယ်၍ တစ်ပါးသူတို့သည် တိုင်းနိုင်ငံ­ တပ်မက်မောသည်ရှိသော် ငါ့ကိုလည်း ရာဟုဖမ်းသောလကဲ့သို့ မှောင်မိုက်စေလတ္တံ့။”')
,(6962,3,4,'‘ဒးဝပ်’ နှင့်အတူတူ။','“(ဗာဇ္ဇခါတ်ဂှ်) ဍေံတိုန်ရပ်ရ၊ ဥပ္ပရာဇာ။ ဒက်ဂၞိၚ်ကၠေၚ်ဂြဲ၊ သီုကဵုတဲၜါ။ ဥပ္ပရာဇာ၊ ခါဂှ်ဒးလွပ်။ ဟွံတီဒုဟ်ကၞပ်၊ချပ်ဇကုမွဲ။” (လိက်ကောန်သၟိၚ်ပိ။ မာံခစုန်အံက်။) = “မင်း၏အာဏာပါးကွက်သားသည် တက်လာပြီးလျှင် ဥပရာဇာအိမ်ရှေ့မင်းသားအားဖမ်း၍ လက်နှစ်ဖက်စလုံးကို လက်ပြန်ကြိုးတုပ်၏။ဥပရာဇာသည် အဖမ်းခံရပြီး မိမိအပြစ်ကိုမသိဘဲ တစ်ကိုယ်တည်းစဉ်းစား၏။”')
,(6963,3,4,'လက်နက်ထိမှန်သည်။','“(စိၚ်ဇၟူဂှ် ပ္ဍဲဋ္ဌာန်စၞေဟ်) ဒးလွဟ်မဂၠိုၚ် ဖေက်ဘဲဂစိုတ်တုဲဆုတ်တိတ်ကၠုၚ်ရ။” (ဇ—၁၈၂။ အစွောံ။) = “ဆင်ပြောင်ကြီးသည် စစ်မြေပြင်­ များစွာလက်နက်ထိမှန်၍ သေဘေးမှကြောက်သဖြင့် ထွက်ဆုတ်ခဲ့၏။”')
,(6964,3,4,'‘ဒးလွပ်’ နှင့်အတူတူ။','အဖမ်းခံရသည်။ ဖမ်းဆီးခြင်းခံရသည်။')
,(6964,3,4,'‘ဒးလွပ်’ နှင့်အတူတူ။','“ပ္ဍဲဗ္တံဝွံ တၠညးဒးဝပ်လောပ်အာသ္ကေံတဲသတြုသွံအဴ။” (ဇ—၂၈၉။ အစွောံ။) = “ညဉ့်တုန်းက အရှင်မင်းကြီးသည်အဖမ်းအဆီးခံရ၍ ရန်သူ့လက်တွင်းသို့ရောက်သွားရ၏။”')
,(6964,3,4,'‘ဒးလွပ်’ နှင့်အတူတူ။','“ကောန်အဲဘူရိဒတ်မွဲ တိုန်မၚ်သဳပ္ဍဲဋ္ဌာန်မၞိဟ်တေံဂှ် ဟွံသေၚ်ဒးဝပ်လၟာဲဟာ ဟွံသေၚ်ဒးဝပ်သ္ပဝ်ဟာ။” (ဇ—ဘူရိဒတ်။ အစွောံ) =“ငါ့သားဘူရိဒတ်နဂါးသည် လူတို့ဋ္ဌာနေ­ တက်၍ဥပုသ်သီလစောင့်သည်မှာ အလမ္ပာယ်၏ဖမ်းဆီးခြင်းကိုလျှင် ခံရပြီလော၊ ဂဠုန်၏ဖမ်းဆီးခြင်းကိုလျှင် ခံရပြီလော။”')
,(6964,3,4,'‘ဒးလွပ်’ နှင့်အတူတူ။','“တၠသ္ၚိဇကုဒးဝပ်ဂတာံရောၚ်တုဲ သ္ဍိုက်တၠသ္ၚိတုဲ (စိၚ်ဗြဴဂှ်) ဟွံဒြေပ် ဒေါအ်ဒၟံၚ်သ္ကဲသြၚ်လစဂှ်—။” (ဇ—၂၆၇။ အစွောံ။) =“မိမိ၏လင်သည် ရွှေဗုဇွန်၏ဖမ်းခြင်းကို ခံရသည်ဖြစ်သဖြင့် လင်ကိုချစ်သော ထိုဆင်မသည် မပြေးဘဲ အိုင်နံဘေး­သာ နေ၏။”')
,(6964,3,4,'‘ဒးလွပ်’ နှင့်အတူတူ။','“ညံၚ်ဂိတုမပတၠရုပ်တဆိပ်ဗတာဲ ကာလမဒးဝပ်ရာဟု။” (သၠပတ်သတိပထာန်) = “ယုန်ရေးတံဆိပ်ရှိသောလကဲ့သို့ ရာဟုဖမ်းခြင်းခံရသောကာလ။”')
,(6964,3,4,'‘ဒးလွပ်’ နှင့်အတူတူ။','“ဒးဝပ်ရာဟု၊ သၟိၚ်ဂိတုပ္ညဳ။” (လိက်ကောန်သၟိၚ်ပိ။ မာံခစုန်အံက်။) = “လမင်းသည် ရာဟုဖမ်းခြင်းခံရ၏။”')
,(6965,3,4,'အချုပ်ကျသည်။','“မၞိဟ်ဒးသ္ၚိစာတ်တံဂှ် မွဲမွဲဂိုၚ်ပ္တိတ်နူသ္ၚိစာတ်တုဲ—။” (ဇ—၃၉၈။အစွောံ။) = “အချုပ်ကျသောလူတို့ကို တစ်ယောက်တစ်ယောက်စီ အချုပ်ခန်းမှထုတ်ဆောင်၍—။”')
,(6966,3,4,'အချိုးအစားကျသည်။ ပုံပန်းကျသည်။ လက်ရာမြောက်သည်။ စနစ်ကျသည်။ စံနှင့်ညီသည်။','“ညံၚ်ရဴပြာသာဒ် မဒးသၞတ်တဲအ္စာဝဍ္ဎကဳဗဳသကဝ်မသောန်ဗဂေါဝ်လဝ်—။” (ဇ—၄၁၁။ အစွောံ။) = “လက်သမားဆရာဗိသုကာ၏ အချိုးအစားကျလက်ရာမြောက်သော လှပစွာဆောက်လုပ်ထားသော ပြာသာဒ်ကဲ့သို့။”')
,(6966,3,4,'အချိုးအစားကျသည်။ ပုံပန်းကျသည်။ လက်ရာမြောက်သည်။ စနစ်ကျသည်။ စံနှင့်ညီသည်။','“ဇလိၚ်ကၠံဟတ်၊ ဒးသၞောတ်ဗီုပြၚ်။” (လိက်တပူ တဗဝ်။ အစွောံ။) = “အလျားအတောင်တစ်ရာရှိပြီး အချိုးအစားပုံပန်းကျသည်။”')
,(6966,3,4,'အချိုးအစားကျသည်။ ပုံပန်းကျသည်။ လက်ရာမြောက်သည်။ စနစ်ကျသည်။ စံနှင့်ညီသည်။','“တဳလဂှ်ဒ၊ ပတလမုဟ်။ ဂၠိၚ်လဂူသၟဟ်၊ ဆာဲမြဟ်ဒးသၞောတ်။” (လိက်ပထမဗောဓိ။ မၚ်ဍိက်လ။) = “ထိုအရှင်မြတ်သည် ရှည်ဖြောင့်ညဳညာတင့်တယ်သော အချိုးအစားကျသော နှာခေါင်းပိုင်ရှင်ဖြစ်တော်မူ၏။”')
,(6966,3,4,'အချိုးအစားကျသည်။ ပုံပန်းကျသည်။ လက်ရာမြောက်သည်။ စနစ်ကျသည်။ စံနှင့်ညီသည်။','“ရဴပြာသာတ်ဗိုတ်၊ ဒးသၞတ်အိုဿီု။” (လိက်ဗောဓိသတ်စှ်။ ပဏ္ဍိတ။) = “အလုံးစုံစံနှင့်ညီသော စိန်ပြာသာဒ်သဖွယ်။”')
,(6967,3,4,'တရားနှင့်အညီဖြစ်သည်။','“ယွံအ္စာ၊ ဂဗုတ်ညးပ္တုဲဟွံဒးသၞောဝ်ဂှ်အ္စာဂွံပ္တုဲဗဗွဲဓဝ်ရောၚ်ယး ညးမဟီုဂှ် ဒှ်ကွေံဟာ။” (ဇ—၂၂ဝ။ အစွောံ။) = “ဆရာ၊ သူတစ်ပါးတို့ မတရားသဖြင့် ဆုံးဖြတ်ထားသောအမှုကို ဆရာသည် တရားနှင့်အညီ ဆုံးဖြတ်ပေး၏ဟူသည် မှန်သလော။”')
,(6968,3,4,'အစပ်အဟပ်မိသည်။ အစပ်အဟပ်တည့်သည်။',NULL)
,(6969,3,4,'အချိန်ကျသည်။ အခါရောက်သည်။','“ဒးအခါတုဲ မခဲါဒယိုင်ရ။” (သၠပတ်ဒ္ၚောဝ်သၜောံ) = “အချိန်ကျသောအခါ တိုင်စိုက်ထူရန် တွင်းကိုတူး၏။”')
,(6969,3,4,'အချိန်ကျသည်။ အခါရောက်သည်။','“ကာလဒးအခါသတ်မုက်ဂှ်ဍုဟ်တုဲ ကၞုဲဂမၠိုၚ်ချပ် (ကၠုၚ်စရ။)” (ဇ—၁၇၇။ အစွောံ။) = “တည်သီးမှည့်သောအခါရောက်လတ်သော် မျောက်တို့သည် လာစားကြရန်ကြံကုန်၏။”')
,(6970,3,4,'အခန့်သင့်သည်။ နေရာကျသည်။ အလိုက်သင့်သည်။','“ၜုန်ဏအ် ရပ်ဟွံဒးအခိုက်မ္ဂး တဝ်ဍေံခလှောတ်တိတ်အာမာန်ရောၚ်။” = “ဤဓါးကိုကိုင်၍ အခန့်မသင့်လျှင် ဓါးရိုးကျွတ်ထွက်သွားနိုင်သည်။”')
,(6971,3,4,'အချိန်ကျသည်။ အချိန်ရောက်သည်။ အချိန်တန်သည်။',NULL)
,(6972,3,4,'အချိန်အခါကောင်းနှင့်ကြုံကြိုက်သည်။ အခါကောင်းကြုံသည်။',NULL)
,(6973,3,4,'မင်းဒဏ်သင့်သည်။ ရာဇဒဏ်သင့်သည်။','“ထပှ်ဝါ ကွာန်ဂှ်ဒးအမှုသၟိၚ်။” (ဇ—၄၁။ အစွောံ။) = “ထိုရွာသည် ခုနစ်ကြိမ် မင်းဒဏ်သင့်၏။”')
,(6974,3,4,'အလိုက်သင့်သည်။ အခါအခွင့်သင့်သည်။','“ညးမကော်ဝွံ ညးမဆာန်ဟွံသေၚ်၊ဒးအလိုက် ညးသ္ပဒဒိုက်ကဵုဇကုရောၚ်။” (အကြီုရာဇာဓိရာဇ်) = “သူခေါ်ခြင်းသည် သူချစ်၍မဟုတ်၊ အခါအခွင့်သင့်ပါက မိမိအား ဘေးဒုက္ခပေးရန်သာဖြစ်၏။”')
,(6975,3,4,'အလှည့်ကျသည်။','“တ္ၚဲယးတေံ သ္ၚိပိုဲဒးအလန်ပိဏ္ဍပါတ်ရ။” = “မနက်ဖြန်ခါငါတို့အိမ် ဆွမ်းအလှည့်ကျသည်။”')
,(6976,3,4,'(ရဟန်းသံဃာများ) အာပတ်သင့်သည်။',NULL)
,(6977,3,4,'၁။ ချည်သည်။ ချည်နှောင်သည်။ နှောင်ဖွဲ့သည်။','‘ (လမာဲဂှ်) ဒက်လဝ်ကၞုဲဂှ်တုဲ—။’ (ဇ—၃၆၅။ အစွောံ။) = ‘အလမ္ပာယ်သည် မျောက်ကို ချည်နှောင်ထား၏။’')
,(6977,3,4,'၁။ ချည်သည်။ ချည်နှောင်သည်။ နှောင်ဖွဲ့သည်။','၂။ တည်ဆောက်သည်။ ဆောက်လုပ်သည်။')
,(6977,3,4,'၁။ ချည်သည်။ ချည်နှောင်သည်။ နှောင်ဖွဲ့သည်။','ဒက်ကၟာၚ် = တံတိုင်းဆောက်သည်။')
,(6977,3,4,'၁။ ချည်သည်။ ချည်နှောင်သည်။ နှောင်ဖွဲ့သည်။','ဒက်ကျာ် = ဘုရားတည်သည်။')
,(6977,3,4,'၁။ ချည်သည်။ ချည်နှောင်သည်။ နှောင်ဖွဲ့သည်။','ဒက်ခပေဲါ = (ငှက်) သိုက်အုံဆောက်သည်။')
,(6977,3,4,'၁။ ချည်သည်။ ချည်နှောင်သည်။ နှောင်ဖွဲ့သည်။','သာဲဒက်သ္ၚိ = ပျားအုံဆောက်သည်။')
,(6978,3,11,'(နဝိ) လက်ယာရစ်လည်သော။','ကၞုသၚ်ဒက္ခိဏဝဝ် = လက်ယာရစ်လည်သောခရုသင်း။')
,(6979,3,10,'(န) ဒက္ခိဏသာခါ။ (မဟာဗောဓိပၚ်၏ တောင်ဘက်အကိုင်းမှ အသားကိုထုလုပ်သည့် ဗုဒ္ဓရုပ်ပွားတော်။ ယင်းရုပ်ပွားတော်၏ပုံအတိုင်း ထုလုပ်ကိုးကွယ်သည့် ဗုဒ္ဓရုပ်ပွားတော်။)',NULL)
,(6980,3,4,'(တစ်ဦးနှင့်တစ်ဦး အပြန်အလှန်) ကတိသစ္စာပြုသည်။ ကတိပြုခြင်းဖြင့် နှောင်ဖွဲ့သည်။','“ဒက်ကတ္တိက၊ သ္ပမိတ်ပြဝါ။” (လိက်ဇိဝှစက္က) = “ကတိသစ္စာပြု၍ မိတ်ဖွဲ့ကြ၏။”')
,(6981,3,4,'လည်ပင်းကို ကြိုးကွင်းစွပ်၍ သေကြောင်းကြံသည်။ ကြိုးဆွဲချသည်။','‘ပူဂဵုမဒက်ကအ်ဂစိုတ်ဇကု။’ = ‘ကြိုးဆွဲချ၍ မိမိကိုယ်ကို သေကြောင်းကြံသောသူ။’')
,(6982,3,4,'ခါးတောင်းကျိုက်သည်။ အောက်ပိုးကျိုက်သည်။',NULL)
,(6983,3,4,'ချည်နှောင်သည်။ နှောင်ဖွဲ့သည်။',NULL)
,(6984,3,4,'သူတစ်ပါးစိတ်ကို နှောင်ဖွဲ့ထားသည်။ ညှို့ယူဆွဲဆောင်သည်။','“(သၟတ်ဗြဴဂှ်) ဍေံမၞုံရမျှာၚ်မလလောၚ်ဓမြိၚ် မဒက်ဂြေန်လဝ်စိုတ်ညး—။” (ဇ—၅ဝ၇။ အစွောံ။) = “ထိုမိန်းမပျိုသည် အောင်သောဟိန်းသောအသံရှိ၍ သူတစ်ပါးစိတ်ကို ညှို့ယူဆွဲဆောင်ထားနိုင်၏။”')
,(6985,3,4,'ဖွဲ့ချည်သည်။ ချည်နှောင်သည်။',NULL)
,(6986,3,4,'ဖမ်းဆီးချုပ်နှောင်သည်။','“စက္ကဝဝ်ဗြဴပန် နာဲအဲဒက်ဂၠုဲကေတ်ဖျဴဏာတုဲရ။” (ဇ—မဟောဟ်သဓ။ အစွောံ။) = “လေးဦးသောမင်းမျိုးမိန်းမတို့အား ငါတို့သခင်ဘုရင်သည် ဖမ်းဆီးချုပ်နှောင် ခေါ်ဆောင်သွားလေပြီ။”')
,(6986,3,4,'ဖမ်းဆီးချုပ်နှောင်သည်။','“ထပှ်စှ်ောကီု၊ သၟိၚ်ယီုဒက်ဂၠုဲ။” (လောကသိဒ္ဓိ။ အစွောံ။) = “အသက်ခုနစ်ဆယ်­ သေမင်းဖမ်းဆီးခေါ်ဆောင်၏။”')
,(6987,3,1,'ခါးတောင်းကျိုက်သည်။ အောက်ပိုးကျိုက်သည်။ (ပါဠိ—ကစ္ဆဗန္ဓန)',NULL)
,(6988,3,4,'အငြိုးအတေးထားသည်။ ရန်ငြိုးဖွဲ့သည်။','“အဲဟီုဗၟက်ဝေၚ်ရောၚ်၊ လ္ပဒက်စိုတ်ကဵုအဲညိ။” = “ကျွန်တော်ကျီစယ်ပြောဆိုခြင်းသာဖြစ်သည်၊ ကျွန်တော့်ကို အငြိုးမထားပါနှင့်။”')
,(6989,3,4,'မာယာပရိယာယ်ဖြင့် လှည့်စားရန် အကွက်ဆင်သည်။','“အဲဍိက်လ္ၚောဝ်ပ္တီ၊ ခပ်သီဒဒှ်။ နဲယျဥပ္ပဲါ၊ ဒက်စၞာဲဂှ်။” (လိက်ကောန်သၟိၚ်ပိ။ မာံခစုန်အံက်။) = “နည်းနာမာယာဥပါယ်ဖြင့်လှည့်စားရန်အကွက်ဆင်သော ခပ်သိမ်းသောအကြောင်းကို ကျွန်တော်မျိုးရှိခိုးလျှောက်တင်ပါ၏။”')
,(6989,3,4,'မာယာပရိယာယ်ဖြင့် လှည့်စားရန် အကွက်ဆင်သည်။','“ဍေံဒက်စၞာဲ၊ ဍေံမဂၠာဲပ။” (လိက်သောဝိန်ဇဲယ။ မာံရောဂေါ။) = “ဥပါယ်မာယာဖွဲ့၍ လှည့်စားရန် သူအကွက်ဆင်၏။”')
,(6990,3,4,'တင်ပျဉ်ခွေသည်။ ထက်ဝယ်ဖွဲ့သည်။','“—၊ သၟိၚ်တိုန်ဒက်ထဝဲါ ပ္ဍဲအကာသရ။” (ဇ—၃ဝ၃။ အစွောံ။) = “မင်းသည် ကောင်းကင်­ ထက်ဝယ်ဖွဲ့သဖြင့်နေ၏။”')
,(6991,3,4,'မြည်တမ်းသည်။ ဆိုမြည်တမ်းသည်။','“ဟိုတ်နူသာမဏေဂှ် ပကၠေံကာဂစိုတ်ဂှ်ရ ထေရ်ဗျုဂှ် က္တဵုဒှ်ယဲပူမဟ်တုဲ ယာံဒက်ဒန်တဴတုဲ ဂ္ၚေၚ်တဴရ။” (ဇ—၄၁ဝ။ အစွောံ။) =“ထိုရဟန်းကြီးသည် ထိုသာမဏေသေသည်ရှိသော် (ပူဆွေးသောကဖြစ်၍) ငိုကြွေးမြည်တမ်းလျက်သွား၏။” (ညောင်ကန်)')
,(6991,3,4,'မြည်တမ်းသည်။ ဆိုမြည်တမ်းသည်။','“ညးမွဲပကာဂစိုတ်တုဲဂှ် ပွမယာံဒက်ဒေါန်တဴဂှ် သဘဴမကလိဂွံပၠန်ဂှ် ဟွံမွဲရ။” (ဇ—၃၇၂။ အစွောံ။) = “သေသောသူအား ငိုကြွေးမြည်တမ်းခြင်းဖြင့် ပြန်ရရိုးမရှိ။”')
,(6991,3,4,'မြည်တမ်းသည်။ ဆိုမြည်တမ်းသည်။','“ပၞောဝ်ပိုဲညးၜါ မယာံဒက်ဒေါန်တဴဂှ် မူရဴညးမွဲဟေၚ် မသ္ဒိုဟ်က္ဍၚ်လောန်ရော။” (ဇ—၄၄၉။ အစွောံ။) = “ငိုမြည်တမ်းသောငါတို့နှစ်ဦးအနက် အဘယ်သူက ပို၍မိုက်သနည်း။”')
,(6991,3,4,'မြည်တမ်းသည်။ ဆိုမြည်တမ်းသည်။','“ဗရုမဖျိုက်ကဵုကတောဝ်အဲသာ်ဝွံဂှ် ဍေံဟီုဒက်ဒေါန်လစောန်ရဏောန် မိပ်သ္ၚိပ်လောန်သန်သွံ။ မူဗရုဂှ်သ္ဂးရော။” (ဇ—၅ဝ၇။ အစွောံ။) = “ငါ၏နားကိုချမ်းသာစေသော သာယာစွာဆိုမြည်တမ်းသော ဤအသံသည်ကား မွေ့လျော်နာပျော်ဖွယ်ရှိစွ။ အဘယ်မည်သောအသံပါနည်း။”')
,(6991,3,4,'မြည်တမ်းသည်။ ဆိုမြည်တမ်းသည်။','“ပ္ဍဲဇရေၚ်အဲအဏအ်ဂှ် သြဝ်ကဵုဍေံကၠုၚ်ဒယှ်ေဒက်ဒေါန်ညိ။” (ဇ—၅ဝ၇။ အစွောံ။) = “ငါ၏အပါး­သူ့ကိုလာစေ၍ သီဆိုမြည်တမ်းပါစေလော့။”')
,(6992,3,4,'တည်ဆောက်သည်။ တည်ထောင်သည်။','“သမလကဵုဝိမလ ကောကဵုဒေံၜါ ဒက်ပ္တန်ဍုၚ်ဟံသာဝတဳ။” = “သမလနှင့်ဝိမလ ညီနောင်နှစ်ဦးတို့ ဟံသာဝတီပြည်ကို တည်ထောင်ခဲ့ကြသည်။”')
,(6993,3,4,'မိတ်ဖွဲ့သည်။ အဆွေခင်ပွန်းဖွဲ့သည်။','“မူပတၠအဲမပမိတ်ပြဝါကဵုဍေံဝွံရော။ လ္ပဒက်မိတ်ကဵုပူဂဵုဝွံညိ။” (ဇ—၁၂၁။ အစွောံ။) = “အဘယ့်ကြောင့်ထိုသူနှင့် မိတ်ဖွဲ့ခြင်းကိုပြုသနည်း၊ မပြုလင့်။” (ညောင်ကန်)')
,(6993,3,4,'မိတ်ဖွဲ့သည်။ အဆွေခင်ပွန်းဖွဲ့သည်။','“မဒက်မိတ်ပြဝါဂှ် ပူဂဵုယုတ် ဂကူပြဲ နွံကဵုပိုန် ဟွံမွဲကဵုပိုန်ဂှ် လ္ပဂးညိ။ ပူဂဵုမၞုံကဵုပညာ ပူဂဵုဂှ် ဂပ်ဂဝ်ဒက်မိတ်ရ။” (ဇ—၁၂၁။ အစွောံ။) = “အဆွေခင်ပွန်းဖွဲ့ရာ­ အမျိုးယုတ်သည်မြတ်သည်ကို၄င်း၊ ဥစ္စာရှိသည်မရှိသည်ကို၄င်းမဆိုလေနှင့်။ ပညာရှိသောသူနှင့်သာလျှင် မိတ်ဖွဲ့ရာ၏။”')
,(6993,3,4,'မိတ်ဖွဲ့သည်။ အဆွေခင်ပွန်းဖွဲ့သည်။','“ပိုဲညးၜါ ဒက်မိတ်ပြဝါ ဒၟံၚ်မွဲစွံရ။” (ဇ—၁၅၂။ အစွောံ။) = “ငါတို့နှစ်ဦးမိတ်ဖွဲ့၍ အတူတကွနေကြမည်။”')
,(6993,3,4,'မိတ်ဖွဲ့သည်။ အဆွေခင်ပွန်းဖွဲ့သည်။','“ညးဗၞိက်ၜါဂှ် ဒက်မိတ်သဟာဲတုဲ — အာပဗၞိက်ရ။” (ဇ—၂၁၈။ အစွောံ။) = “ကုန်သည်နှစ်ယောက်တို့သည် အဆွေခင်ပွန်းဖွဲ့ကုန်ပြီးလျှင် ကုန်အရောင်းအဝယ်သွားကြ၏။”')
,(6994,3,4,'ရန်ငြိုးဖွဲ့သည်။','“(သေနာပတိဂှ်) ဍေံဒက်လဝ်ဝဲကဵုဗောဓိသတ်။” (ဇ—၂၂ဝ။ အစွောံ။) = “သေနာပတိသည် ဘုရားလောင်းအား ရန်ငြိုးဖွဲ့၏။”')
,(6994,3,4,'ရန်ငြိုးဖွဲ့သည်။','“ပြောဟိတ်ထေဲတုဲ ဒက်လဝ်ဝဲပ္ဍဲခဍာ်ဂှ်ရ။” (ဇ—၁၄ဝ။ အစွောံ။) = “(ပုရောဟိတ်) ပုဏ္ဏားသည် အမျက်ထွက်၍ ကျီးတို့­ရန်ငြိုးဖွဲ့၏။” (ညောင်ကန်)')
,(6994,3,4,'ရန်ငြိုးဖွဲ့သည်။','“ပ္ဍဲမဟွံသေၚ်ကဵုဟိုတ်ဂှ် ဒေဝဒတ်ဒက်လဝ်ဝဲကုကျာ်တြဲ—။” (ဇ—၃၂၉။ အစွောံ။) = “ဒေဝဒတ်သည် ဘုရားအား အရာမဟုတ်သည်­ ရန်ငြိုးဘွဲ့၍—။” (ညောင်ကန်)')
,(6995,3,4,'ရန်ငြိုးဖွဲ့သည်။','‘ဒက်ဝဲ’ နှင့်အတူတူ။')
,(6996,3,4,'ဥပါယ်ပြုသည်၊ ဥပါယ်ဖွဲ့သည်။',NULL)
,(6997,3,4,'ကျယ်အောင်လုပ်သည်။ (ကျွဲချိုကားအောင်လုပ်သည်။)',NULL)
,(6998,3,4,'ရိုက်သည်။ ဆော်သည် (ဘန်းစကား) ။','ဒုက်ကဵုလေံ = တုတ်နှင့်ရိုက်သည်။')
,(6998,3,4,'ရိုက်သည်။ ဆော်သည် (ဘန်းစကား) ။','လေံဒုက် = ရိုက်ရန်တုတ်။')
,(6999,3,10,'(န) ဆင်းရဲခြင်း။ ဒုက္ခ။',NULL)
,(7000,3,11,'(န) ဘုရားဖြစ်ရန်ကျင့်ရသော ဒုက္ကရစရိယာကျင့်စဉ်။','“တၞဟ်နဂွံဒှ်ကျာ်ကောန်သၟိၚ်သဳဓတ် ဒးဒ္ဂေတ်တဴဒုက္ခစရိယာတ် လုကဴ (၆) သၞာံရ။” = “ဘုရားဖြစ်ရန် သိဒ္ဓတ္တမင်းသားသည် (၆) နှစ်တိုင်တိုင် ဒုက္ကရစရိယာကျင့်ရသည်။”')
,(7000,3,11,'(န) ဘုရားဖြစ်ရန်ကျင့်ရသော ဒုက္ကရစရိယာကျင့်စဉ်။','“ကျာ်တြဲဒိဗ္ဗၚ်ကဵုတုန်လေဝ် — အယုက်ကျာ်တြဲမွဲလက် ပဒုက္ခစရိယာတ် စှ်ဂိတုရ။” (ဗုဒ္ဓဝၚ်။ မာံရွှေငိုး။)')
,(7001,3,10,'(န) ဒုက္ခဝေဒနာ။','“(သၟိၚ်ၜိုပ်ထဝ်ဒးဓနက်တုဲ ရုန်လဝ်တုဲ) ဆီဇွောဝ်ဒၟံၚ်သီုဒုက္ခဝေဒနာရ။” (ဇ—၅၃၃။ အစွောံ။) = “ရွှေဟင်္သာမင်းသည် ကျော့ကွင်းမိပြီးနောက် ရုန်းထားသဖြင့် သွေးယိုစီးလျက် ကြီးစွာသောဝေဒနာဖြစ်၏။”')
,(7002,3,10,'(န) ကိုယ်အင်္ဂါချို့တဲ့သူ။ မစွမ်းမသန်သူ။ ဒုက္ခိတ။','“ဒုက္ခိတအဵု၊ ပူဂဵုသေၚ်ဟာ။” (လိက်သုဝဏ္ဏသာံ။ မာံသေၚ်။) = “ဒုက္ခိတပုဂ္ဂိုလ်မဟုတ်ပါလော။”')
,(7003,3,10,'(န) မကောင်းသောလားရာ။ ဒုဂ္ဂတိ။',NULL)
,(7004,3,11,'(န) ဒုဂ္ဂတိဘုံ။ အပါယ်ဘုံ။',NULL)
,(7005,3,4,'လျော့သည်။ လိုသည်။ မပြည့်စုံဖြစ်သည်။','မသုန်ကၠံဒေက်မွဲဘဝ = ဘဝပေါင်းငါးရာတစ်ဘဝလျော့။ လေးရာကိုးဆယ့်ကိုးဘဝ။')
,(7005,3,4,'လျော့သည်။ လိုသည်။ မပြည့်စုံဖြစ်သည်။','“ဗၠးနူနရက်ဂှ်တုဲ ပွညးမကုတ်ဒၟံၚ်ကအ်အဲဂှ် မသုန်ကၠံဒေက်မွဲဘဝတုဲရ။ ပ္ဍဲတ္ၚဲဝွံဂှ် ပေၚ်မသုန်ကၠံဘဝရ” ဗ္ၜေအ်ဂး။ (ဇ—၁၈။ အစွောံ။) = “(ငရဲမှလွတ်ပြီးနောက်) ငါသည် လေးရာ့ကိုးဆယ့်ကိုးဘဝတို့­ ခေါင်းပြတ်ခြင်းသို့ ရောက်လေပြီ။ ဤဘဝသည်ကား အဆုံးစွန်­တည်သော ငါးရာတို့၏ပြည့်ကြောင်းဖြစ်သောဘဝတည်း။” (ညောင်ကန်)')
,(7005,3,4,'လျော့သည်။ လိုသည်။ မပြည့်စုံဖြစ်သည်။','“မသုန်စှ်ောယေက်၊ ဟွံဂွံဒေက်ပြဲ။” (လိက်မေဃသန်) = “မလျော့မလို မပိုမလွန်ယူဇနာငါးဆယ်အတိရှိ၏။”')
,(7006,3,4,'အသက်မွေးဝမ်းကြောင်း ဆင်းရဲကျပ်တည်းသည်။ အသက်မွေးမှုချို့ငဲ့သည်။','“မူပမၞးတံဒမၠစရော” သၟိၚ်သၟာန်၊ “ပိုဲဍိက်ဒေက်ဂယိုင်လမျီုတုဲ မဒးဒမၠစရောၚ်အဴ” ဒမၠတံဂှ်ဂး။ (ဇ—၅၁။ အစွောံ။) = “ဘာကြောင့်သင်တို့ ဓါးပြတိုက်စားရကုန်သနည်း” ဟု ဘုရင်မေးသော် “ကျွန်တော်မျိုးတို့ အသက်မွေးမှုချို့ငဲ့သောကြောင့် ဓါးပြတိုက်စားရပါ၏” ဟုဓါးပြများဆို၏။')
,(7007,3,4,'အာဟာရချို့တဲ့သည်။','ယဲဒေက်ဓါတ်အဟာရ = အာဟာရဓါတ်ချို့တဲ့သောရောဂါ။')
,(7008,3,4,'၁။ ဆင်းရဲသည်။ ခက်ခဲသည်။ ကျပ်တည်းသည်။','“မိမပိုဲဒိုက်အာတုဲရ။” (ဇ—၂၁၁။အစွောံ။) = “ငါ့မိဘတို့သည် ဆင်းရဲသွားပြီ။”')
,(7008,3,4,'၁။ ဆင်းရဲသည်။ ခက်ခဲသည်။ ကျပ်တည်းသည်။','ဒိုက်ဇွောအ်အဟာ (ဇ—၂၉၉။ အစွောံ။) =“အစာရေစာဆင်းရဲခက်ခဲသည်။”')
,(7008,3,4,'၁။ ဆင်းရဲသည်။ ခက်ခဲသည်။ ကျပ်တည်းသည်။','“ကေုာံပူဂဵုသမၠီုဂှ် မၞးနှဴရဴမ္ဂး ဒိုက်သန်ရ။” (ဇ—၄၃၅။ အစွောံ။) = “သူမိုက်နှင့်တကွ ပေါင်းဖော်ခြင်းသည် အလွန်ဆင်းရဲ၏။”')
,(7008,3,4,'၁။ ဆင်းရဲသည်။ ခက်ခဲသည်။ ကျပ်တည်းသည်။','၂။ ရှားပါးသည်။')
,(7008,3,4,'၁။ ဆင်းရဲသည်။ ခက်ခဲသည်။ ကျပ်တည်းသည်။','“ပ္ဍဲဥတုကသီု ဍာ်ဟွံဒိုက်ရ။” = “မိုးဥတုတွင် ရေမရှားပါးပါ။”')
,(7008,3,4,'၁။ ဆင်းရဲသည်။ ခက်ခဲသည်။ ကျပ်တည်းသည်။','(သၟိၚ်ဟွံဂွံဖျုန်တုဲ “အဲဨကရာတ် ဒိုက်ဒၟံၚ်ဖျုန်ရောၚ်ဟာ” သၟိၚ်ဂး။) (ဇ—၂၂ဝ။ အစွောံ။) = (မင်းသည် အမဲဟင်းလျာကိုမရသည်ရှိသော် “ငါရှင်ဘုရင်က အမဲသားရှားရလေသလား” ဟုမင်းဆို၏။)')
,(7008,3,4,'၁။ ဆင်းရဲသည်။ ခက်ခဲသည်။ ကျပ်တည်းသည်။','“ပ္ဍဲဍုၚ်သေံအဴ၊ဒိုက်ဒၟံၚ်ဗြဴဟာ။” (လိက်ဇိဝှစက္က) = “ယိုးဒယားပြည်မှာ မိန်းမ၊ရှားပါးနေလေသလား။”')
,(7009,3,4,'ဝမ်းစာရေးခက်ခဲသည်။ အသက်မွေးမှု ဆင်းရဲကျပ်တည်းသည်။','“ယွံကောန်တၠ၊ ဂတနူဝွံဂှ် အဲဍိက်ဒိုက်ဂယိုင်လမျီုကွေံအဴ။” (ဇ—၃၉၈။ အစွောံ။) = “အရှင်၊ ယခုမှရှေ့­ အကျွန်ုပ်အား အသက်မွေးမှုသည် ဆင်းရဲခက်ခဲလတ္တံ့။”')
,(7010,3,1,'သူဆင်းရဲ။ ဆင်းရဲသား။','“မၚ်ဗၠာဲဒိုက်ဂတ်ဂှ်—။” (ဇ—၁ဝ၉။ အစွောံ။) = “ထိုသူဆင်းရဲလုလင်သည်—။”')
,(7010,3,1,'သူဆင်းရဲ။ ဆင်းရဲသား။','“မိမဗောဓိသတ်ဂှ် ဒှ်မံၚ်ဒိုက်ဂတ်ရောၚ်။” (ဇ—၃၈၇။ အစွောံ။) =“ဘုရားလောင်း၏မိဘတို့သည် သူဆင်းရဲများဖြစ်ကုန်၏။”')
,(7010,3,1,'သူဆင်းရဲ။ ဆင်းရဲသား။','“ဗောဓိသတ်ပိုဲ ဒှ်ကောန်ဒိုက်ဂတ်—။” (ဇ—၃၉၈။ အစွောံ။) = “ဘုရားလောင်းသည် ဆင်းရဲသောအမျိုး­ဖြစ်၏။” (ညောင်ကန်)')
,(7010,3,1,'သူဆင်းရဲ။ ဆင်းရဲသား။','“ညံၚ်ဒိုက်ဂတ်မကလိဂွံနိဓိကီု။” (သၠပတ်စန္ဒဝတဳ) = “ရွှေအိုးကိုရသော သူဆင်းရဲကဲ့သို့။”')
,(7010,3,1,'သူဆင်းရဲ။ ဆင်းရဲသား။','“ညံၚ်ဒိုက်ဂတ်ကၠာ၊ မြာဂွံနိဓိ။” (လိက်ပထမဗောဓိ။ မၚ်ဍိက်လ။)')
,(7011,3,4,'ကုန်းကောက်စရာမရှိအောင် ဆင်းရဲနွမ်းပါးသည်။','“ကဵုဒးဒိုက်ဂြာတ်၊အာတ်စကဵုဗောတ်။” (လိက်ပတ္တစာရဳ။ နာဲထဝ်စိုပ်။) = “ကုန်းကောက်စရာမရှိအောင် ဆင်းရဲနွမ်းပါး၍ အိုးဗုတ်နှင့်တောင်းစားရစေကာမူ—။”')
,(7011,3,4,'ကုန်းကောက်စရာမရှိအောင် ဆင်းရဲနွမ်းပါးသည်။','“ကမၠၚ်ဒိုက်ဂြာတ်၊ မၞိဟ်ဂၠာဲအာတ်စ။” (လိက်ပ္တံပါရမဳ။ အစွောံ။) = “အလွန်ဆင်းရဲအထီးကျန်၍ လိုက်လံတောင်းရမ်းစားရသောလူ။”')
,(7011,3,4,'ကုန်းကောက်စရာမရှိအောင် ဆင်းရဲနွမ်းပါးသည်။','“လဆောဝ်ဒိုက်ဂြာတ်၊ ကြၚ်အာတ်စကၠာ။ လဆောဝ်ဒှ်သၟိၚ်၊ ဂွံသိုက်လှိၚ်မာ။” (လိက်ကောန်သၟိၚ်ပိ။မာံခစုန်အံက်။) = “ရံခါဆင်းရဲမွဲတေ၍ လိုက်လံတောင်းရမ်းစားရ၏၊ ရံခါမင်းဖြစ်၍ သုခစည်းစိမ်ခံစားစံစားရ၏။”')
,(7011,3,4,'ကုန်းကောက်စရာမရှိအောင် ဆင်းရဲနွမ်းပါးသည်။','“လဆောဝ်ဒိုက်ဒြာတ်၊ ဒးအာတ်စကြၚ်။” (လိက်ရတနပဇ္ဇောတ)')
,(7012,3,4,'စိတ်ဆင်းရဲသည်။ စိတ်ဒုက္ခဖြစ်သည်။','“ယွံယက္ခ၊ တၠအဲလ္ပဒိုက်စိုတ်ရ။—လ္ပဒွိၚ်ရ။” ဗောဓိသတ်ဂး။ (ဇ—၃၉၈။ အစွောံ။) = “ယက္ခဘီးလူး၊ သင်စိတ်မဆင်းရဲပါနှင့်၊ မစိုးရိမ်ပါနှင့်။”')
,(7012,3,4,'စိတ်ဆင်းရဲသည်။ စိတ်ဒုက္ခဖြစ်သည်။','“ယွံစိၚ်ဗြဴ၊ လ္ပဒွိၚ် လ္ပဒိုက်စိုတ်ရ။” (ဇ—၄ဝ၉။ အစွောံ။) = “ဆင်မ၊ မစိုးရိမ်ပါနှင့်၊စိတ်မဆင်းရဲပါနှင့်။”')
,(7012,3,4,'စိတ်ဆင်းရဲသည်။ စိတ်ဒုက္ခဖြစ်သည်။','‘ဗဒိုက်စိုတ်’ (ကြိ) လည်းရှု။')
,(7013,3,4,'ဆင်းရဲသည်။ နွမ်းပါးသည်။','“လၟုဟ်ဝွံဂှ် ယဲပဏ္ဍုရောဂ က္တဵုဒှ်ကဵုအဲရ။ အဲလေဝ်ဒိုက်ဒိန်လောန်အာတြ။” (ဇ—၂၅၇။ အစွောံ။) = “ယခုတမူကား အကျွန်ုပ်သည် ဖျော့တော့သောရောဂါ စွဲသည်မူလည်းဖြစ်၏။ ဆင်းရဲသည်လည်းဖြစ်၏။” (ညောင်ကန်)')
,(7013,3,4,'ဆင်းရဲသည်။ နွမ်းပါးသည်။','“မိကဵုမၜါဂှ်ဒိုက်ဒိန်အာရ။” (ဇ—သုဝဏ္ဏသာံ။ အစွောံ။) = “မိဘနှစ်ပါးတို့သည် ဆင်းရဲနွမ်းပါးသွားကုန်၏။”')
,(7013,3,4,'ဆင်းရဲသည်။ နွမ်းပါးသည်။','“ဗောဓိသတ်ပိုဲ ဒှ်ပ္ဍဲဂကူသၟာလှ်ေ ဒိုက်ဒိန်ကာဲကၞာဲလောန် ဂၠာဲဂ္ၚေၚ်အာတ်စတုဲ မဂွံဂျိုၚ်လမျီုရောၚ်။” (ဇ—၂၁၂။ အစွောံ။) = “ဘုရားလောင်းသည် ကချေသည်အမျိုး­ဖြစ်၍ အလွန်ဆင်းရဲမွဲတေ၏။ လှည့်ပတ်တောင်းစား၍ အသက်မွေးရ၏။”')
,(7013,3,4,'ဆင်းရဲသည်။ နွမ်းပါးသည်။','“(ကောန်သေဋ္ဌဳဂှ် ဆဝေၚ်ဂြိုၚ်သုၚ်စဂှ် ဒြပ်တံဂှ်အိုတ်အာတုဲ) ဒိုက်ဒိန်ကၠၚ်ကၠောန်အာရ။ ဒးသပိုၚ်ယာတ်ခမၞက် ကြိုင်တဴရ။” (ဇ—၂၉၁။ အစွောံ။) = “ထိုသူဋ္ဌေးသားသည် ပျော်ပါးသောက်စားခြင်းဖြင့်သာလျှင် ဥစ္စာတို့သည်ကုန်၍ ဆင်းရဲအထီးကျန်သည်ဖြစ်၍ ပုဆိုးနွမ်းကိုဝတ်လျက် သွားရ၏။”')
,(7014,3,4,'‘ဒိုက်ဂြာတ်’ ရှု။',NULL)
,(7015,3,4,'ဆင်းရဲနွမ်းပါးသည်။','“ပြောဟိတ်ဆဇကုမွဲ ဒိုက်သာလအိတ်ဟေၚ်။” (သၠပတ်ဒ္ၚောဝ်သၜေံါ) = “ပုရောဟိတ်သည် တစ်ကိုယ်တည်းအထီးကျန်၍ အလွန်အမင်း ဆင်းရဲနွမ်းပါး၏။”')
,(7015,3,4,'ဆင်းရဲနွမ်းပါးသည်။','“ဗမၞးမွဲမကၠုၚ်နူဍုၚ်ကလိၚ်ကရးတေံ ဒိုက်သာလောန် ဗျုလောန်—။” (ဇ—ဝေသန္တဝ်။အစွောံ။) = “ကာလိင်္ဂတိုင်းမှလာသော တစ်ယောက်သောပုဏ္ဏားသည် အလွန်ဆင်းရဲ၍ အလွန်အို၏။”')
,(7015,3,4,'ဆင်းရဲနွမ်းပါးသည်။','“ကောန်ဗြဴသေဋ္ဌဳမွဲဂှ် မိကဵုမဟၟဲတုဲ ဒိုက်သာအာ။” (ဓမ္မဒဳပနဳ။ မာံရွှေငိုး။) = “တစ်ယောက်သောသူဋ္ဌေးသမီးသည် မိဘများမရှိသည့်နောက် ဆင်းရဲနွမ်းပါးသွား၏။”')
,(7016,3,5,'ဆင်းရဲအတူ ချမ်းသာအတူ။ အေးအတူပူအမျှ။','“တြုံကဵုဗြဴညးၜါဂှ်ရေၚ်ကာန်တဴမွဲစွံ ဒိုက်သၟဟ်သိုက်သၟဟ်ရ။” = “လင်မယားနှစ်ယောက်တို့သည် အေးအတူပူအမျှ အတူတကွပေါင်းဖက်နေထိုင်ကြ၏။”')
,(7016,3,5,'ဆင်းရဲအတူ ချမ်းသာအတူ။ အေးအတူပူအမျှ။','(နဝိ) အေးအတူပူအမျှဖြစ်သော။ ဆင်းရဲအတူ ချမ်းသာအတူဖြစ်သော။')
,(7016,3,5,'ဆင်းရဲအတူ ချမ်းသာအတူ။ အေးအတူပူအမျှ။','“မိတ်သဟာဲမဒိုက်သၟဟ်သိုက်သၟဟ်။” = “အေးအတူပူအမျှဖြစ်သောမိတ်ဆွေ။”')
,(7016,3,5,'ဆင်းရဲအတူ ချမ်းသာအတူ။ အေးအတူပူအမျှ။','“ဗြဴမဒိုက်သၟဟ်သိုက်သၟဟ်ကေုာံတၠသ္ၚိဂှ် သမ္ဘာသာ်ဂှ် ပြဲလောန်နူသမ္ဘာသ္အာၚ် ကၠံဆလ္ၚီဆရ။” (ဇ—၃၂ဝ။ အစွောံ။) = “လင်နှင့်တကွ အေးအတူပူအမျှရှိသောမိန်းမသည် အခြားသောမယားတို့ထက် အဆတစ်ရာ အဆတစ်ထောင်မြတ်၏။”')
,(7016,3,5,'ဆင်းရဲအတူ ချမ်းသာအတူ။ အေးအတူပူအမျှ။','‘သိုက်သၟဟ်ဒိုက်သၟဟ်’ နှင့်အတူတူ။')
,(7017,3,1,'ပုခုံးနောက်ပြင်။ ပုခုံး။',NULL)
,(7018,3,4,'ဆန့်သည်။ ဖြန့်သည်။','ဒါၚ်သၞေၚ် = အတောင်ဖြန့်သည်။')
,(7019,3,1,'မွန်အကတစ်မျိုး။','ဒိၚ်သၟိၚ်ၜိုပ်ထဝ် = ရွှေဟင်္သာမင်းအက။')
,(7020,3,4,'အံ့အားသင့်သည်။ တွေဝေသည်။','“ဖျဳလလဳဒှ် ဂဂဵုဂတး သြေံပန်စှ်ေဒးဒလေၚ်မဂဒူ— မဂဒူဒတဴဒိၚ်ဒၚ်ဒၟံၚ်။” (အကြီုရာဇာဓိရာဇ်) = “လျှပ်စီးဖြစ်ပေါ်၍ ဒိုင်းခနဲမိုးကြိုးပစ်ချရာ မဂဒူး၏ထမ်းပိုးကို ထိမှန်၏။ မဂဒူးသည် အံ့အားသင့်တွေဝေလျက် ရပ်နေ၏။”')
,(7020,3,4,'အံ့အားသင့်သည်။ တွေဝေသည်။','“မတ်ဂေတ်ဒိၚ်ဒၚ်၊ ကွာ်ဘိၚ်ဘၚ်စဴ။” (လိက်သၚ်ဂဒါ။ သဳလဝန္တ။) = “မူးနောက်တွေဝေကာ ကြက်သေသေလျက် လျှောက်ပြန်လာ၏။”')
,(7020,3,4,'အံ့အားသင့်သည်။ တွေဝေသည်။','“နာဲပဒိၚ်ဒၚ်၊ စၚ်ခြၚ်ရံၚ်ညိ။” (လိက်သၟိၚ်အသး။ နန္ဒသာရ။) =“သင်မတွေဝေပါနှင့် ချင့်ချိန်ဆင်ခြင်ကြည့်ပါ။”')
,(7021,3,5,'တဒုန်ဒုန်း (မြည်သည်) ။','“ညးဍုၚ်ဗဵုကၠံၚ်၊ မံၚ်ဗြုဒိၚ်ဒိၚ်။” (လိက်ပယးအနိစ္စ) =“မြို့သူများသည် ဆူညံလျက်ကြည့်ကြကုန်၏၊ မောင်းသံလည်း တဒုန်ဒုန်းမြည်နေ၏။”')
,(7022,3,4,'‘ဒေၚ်ဗျောံ’ နှင့်အတူတူ။',NULL)
,(7023,3,4,'ကြံမှိုင်သည်။ စိတ်ထိခိုက်သည်။','‘ဒေၚ်သၠၚ်’ နှင့်အတူတူ။')
,(7023,3,4,'ကြံမှိုင်သည်။ စိတ်ထိခိုက်သည်။','“ဇတဝ်ဖျုန်ဂြိုဟ်၊ မုက်ဖျိုဟ်ဒိၚ်သၠၚ်။” (လိက်ကာကဒိပ္ပ။ မဟာကြၚ်။) = “နှလုံးတုန်ကာ မျက်နှာဖျော့တော့၍ ကြံမှိုင်လျက်နေ၏။”')
,(7024,3,4,'၁။ ခံသည်။ ခံယူသည်။','“ဇဖန်ဗြဲဂူ ဒုၚ်ဍာ်။” = “မိုးရွာတုန်း ရေခံ။”')
,(7024,3,4,'၁။ ခံသည်။ ခံယူသည်။','၂။လက်ခံသည်။ လက်ခံရယူထားသည်။')
,(7024,3,4,'၁။ ခံသည်။ ခံယူသည်။','“သၟိၚ်ဒုၚ်လဝ်ပရၚ်တံဂှ်ရ။” (ဇ—၅၃၁။ အစွောံ။) =“မင်းသည် လက်ဆောင်ပစ္စည်းတို့ကို လက်ခံယူထား၏။”')
,(7024,3,4,'၁။ ခံသည်။ ခံယူသည်။','“သၟိၚ်မရဏတေံ မဒုၚ်ကြန်သမွဲကီုဟာ။” (ဇ—၅ဝ၉။ အစွောံ။) = “သေမင်းက အချိန်းအချက်ကို လက်ခံပါမည်လော။”')
,(7024,3,4,'၁။ ခံသည်။ ခံယူသည်။','၃။ ခံသည်။ သည်းခံသည်။ ခံနိုင်စွမ်းရှိသည်။')
,(7024,3,4,'၁။ ခံသည်။ ခံယူသည်။','“ထေဗျုတက်ဂၠိုၚ်တုဲ သာမဏဳဒုၚ်ဟွံမာန်တုဲ ရာံကၠေံစဴအာရ။” (ဇ—၂၄၉။ အစွောံ။) = “ရဟန်းအိုကြီး ရိုက်နှက်ပါများသဖြင့် သာမဏေသည် မခံနိုင်၍ လူထွက်၍ပြန်သွား၏။”')
,(7024,3,4,'၁။ ခံသည်။ ခံယူသည်။','“တမာတ်ဂမၠိုၚ် ဒးဗြဲကျာတ္ၜိုဟ်လောန် ဒုၚ်ဟွံမာန်တုဲ ပဝ်ပ္ၚောအ်အာဇူဒီု ပ္ဍဲဋ္ဌာန်မၞိဟ်တေံရ။” = “လင်းတငှက်များသည် မိုးလေထိ၍ အလွန်ချမ်းသဖြင့် (အအေးဒဏ်ကို) မခံနိုင်၍ လူ့ရပ်ဋ္ဌာနေသို့ ပျံသန်းသွားရောက်နားခိုကြကုန်၏။”')
,(7024,3,4,'၁။ ခံသည်။ ခံယူသည်။','“ဆဒြထဝ်မွဲကီု ဒုၚ်လဝ်သဇိုၚ်ကၠေၚ်အယိၚ်ဇာဒိသိုၚ်ဂှ်မာန်။” (ဇ—၅၃၇။ အစွောံ။) = “ရွှေခွက်သာလျှင် ခြင်္သေ့ဆီ၏ဝန်ကို ခံထားနိုင်စွမ်းရှိသည်။”')
,(7024,3,4,'၁။ ခံသည်။ ခံယူသည်။','၄။ အောင့်အည်းခံသည်။')
,(7024,3,4,'၁။ ခံသည်။ ခံယူသည်။','ဒုၚ်ကၠောဝ်၊ ဒုၚ်အေၚ်စၞ = အစာအငတ်ခံသည်။')
,(7024,3,4,'၁။ ခံသည်။ ခံယူသည်။','၅။ တာရှည်ခံသည်။ ခိုင်ခံ့သည်။')
,(7024,3,4,'၁။ ခံသည်။ ခံယူသည်။','“နာဍဳအဲဏအ် အဲစကာဒၟံၚ်စှ်သၞာံပြၚ်ရ။ ဒုၚ်ကွေံဍေံဟွံလီုဏီရ။” = “ငါ့နာရီကို ငါသုံးလာခဲ့သည်မှာ ဆယ်နှစ်ကျော်ပြီ၊ တကယ်ခံသည်။ ယခုထိမပျက်သေးပါ။”')
,(7024,3,4,'၁။ ခံသည်။ ခံယူသည်။','၆။ (ရန်သူ့စစ်ကို) ကြံ့ကြံ့ခံသည်။ ခုခံသည်။')
,(7024,3,4,'၁။ ခံသည်။ ခံယူသည်။','“ဍုၚ်ဂှ် ခိုၚ်ကၠိုက်ဗိုန်ဇၟအ်လောန် ဒုၚ်ပၞာန်သတြုမာန်ရ။” = “ထိုမြို့သည် အလွန်ခိုင်ခံ့၏။ ရန်သူ့စစ်ကို ခုခံနိုင်စွမ်းရှိ၏။”')
,(7024,3,4,'၁။ ခံသည်။ ခံယူသည်။','၇။ ကြိုသည်။ သွားကြို၍ ခေါ်ဆောင်လာသည်။')
,(7024,3,4,'၁။ ခံသည်။ ခံယူသည်။','“တ္ၚဲဏအ် ကောအဲစိုပ် အဲဒးအာဒုၚ်ညး ပ္ဍဲသၞေဟ်က္ၜၚ်ရောၚ်။” = “ယနေ့ကျွန်တော့်အစ်ကို ရောက်မည်ဖြစ်၍ သင်္ဘောဆိပ်တွင်သူ့ကိုကျွန်တော်သွားကြိုရမည်။”')
,(7024,3,4,'၁။ ခံသည်။ ခံယူသည်။','“တၠကောန်တြုံတံ ဒုၚ်ဏာသၟတ်ဗြဴဂှ်ရ။” (ဇ—၃၅၉။ အစွောံ) = “ယောကျာ်းရှင်ဘက်မှ ထိုမိန်းမပျိုကို ကြို၍ခေါ်ဆောင်သွား၏။”')
,(7025,3,9,'(ကြိရှေ့ဆက်) အပြုခံရကြောင်းကို ပြသောစကားလုံး။','ဒုၚ်ချိုတ် = အသေခံသည်။')
,(7025,3,9,'(ကြိရှေ့ဆက်) အပြုခံရကြောင်းကို ပြသောစကားလုံး။','ဒုၚ်ဂစိုတ် = အသတ်ခံသည်။')
,(7025,3,9,'(ကြိရှေ့ဆက်) အပြုခံရကြောင်းကို ပြသောစကားလုံး။','ဒုၚ်လေၚ်= အဆုံးရှုံးခံသည်။')
,(7025,3,9,'(ကြိရှေ့ဆက်) အပြုခံရကြောင်းကို ပြသောစကားလုံး။','ဒုၚ်စဳရေၚ် = စီရင်ခြင်းကိုခံယူသည်။ အစီအရင်ခံသည်။')
,(7025,3,9,'(ကြိရှေ့ဆက်) အပြုခံရကြောင်းကို ပြသောစကားလုံး။','ဒုၚ်စဳရေၚ်ဂဗုတ် = အစီအရင်အဆုံးအဖြတ်ခံယူရန် အမှုလာရောက်တိုၚ်တန်းသည်။')
,(7025,3,9,'(ကြိရှေ့ဆက်) အပြုခံရကြောင်းကို ပြသောစကားလုံး။','ဒုၚ်သဳကၠဳ = (ဘုရင်) အခစားခံသည်။ ခစားခြင်းကိုခံယူသည်။')
,(7026,3,4,'အရှုံးပေးသည်။ အရှုံးခံသည်။','“ဟာဲကၠိက်အယုတ် — ဗှ်ေကယဳဒၟံၚ်ကဵုအသုဘ ဂပ်ဂဝ်က္ဍုဟ်ရောၚ်။ — ဇာဒိသိုၚ်ဂွံဇၞးကၠိက်မ္ဂး ညးဂှ် ပအသဝ်ကဵုအဲရော။ အဲဒုၚ်ကယျဗှ်ေရ” ဇာဒိသိုၚ်ဂး။ (ဇ—၁၅၃။ အစွောံ။) = “ဟယ်ဝက်ယုတ်၊ သင်သည် စက်ဆုပ်ဖွယ်ရာ မစင်အလိမ်းလိမ်းကပ်၏။ ခြင်္သေ့က ဝက်ကိုအနိုင်ရလျှင်လည်း ငါ့ကို မည်သူအံ့သြချီးမွမ်းမည်နည်း။ သင့်ကိုငါအရှုံးပေးပါ၏” ဟုခြင်္သေ့ဆို၏။')
,(7026,3,4,'အရှုံးပေးသည်။ အရှုံးခံသည်။','“တၠအဲထ္ၜးဒး ပိုဲဒုၚ်ကယျရ။” (ရာဇာထ္ၜုတ်) = “သင်အမှန်ပြနိုင်လျှင် ငါတို့အရှုံးပေးပါမည်။”')
,(7027,3,4,'တာဝန်ခံသည်။ အာမခံသည်။','“ဍိုက်ပေၚ်ညဳညပ်၊ တိုၚ်လ္ၚပ်နာဲ။ တြုံမွဲဗက်ကၠုၚ်၊ဒုၚ်ကဝါန်ဂၠာဲ။” (လိက်ဝိဓူရ) = “သမီးတော်၏ချင်ခြင်းလိုအင်အတိုင်း ပြည့်စုံရအောင် တာဝန်ခံရှာပေးရန် ယောကျာ်းတစ်ယောက်လိုက်လာ၏။”')
,(7027,3,4,'တာဝန်ခံသည်။ အာမခံသည်။','“ကောန်ဗြဴညးပြဲ၊ အဝဲဂေါဝ်သ္ဇုၚ်။ ညးဇိုန်ကဵုပ၊ ကမၠောန်ပ္ညုၚ်။ အပ်ကဵုသီုဍုၚ်၊ ညးဒုၚ်ကဝါန်။” (လိက်ဝိဓူရ) = “ရုပ်ရည်တင့်တယ်လှပသော သူ့သမီးတော်ကို အလုပ်အကျွေးအဖြစ် အပ်နှင်းမည့်အပြင် ပြည်အလုံးကိုလည်း အပ်ပေးမည်ဟု သူအာမခံ၏။”')
,(7027,3,4,'တာဝန်ခံသည်။ အာမခံသည်။','“ယွံပုဏ္ဏက၊ ဟာဲမမၚ်ဗၠာဲ။ ဒုၚ်လဝ်ကဝါန်၊ ဂလာန်စိုပ်ဒၞာဲ။ တိုန်ဍုၚ်မၞိဟ်တုဲ၊ သွက်ဂဥုဲသာဲ။ ဂြိုဟ်ဝိဓူရ၊ ပဍာ်ပလာဲ။ ကေတ်ကဵုဂွံဟေၚ်၊ လၟေၚ်အာဂၠာဲ။ သောၚ်လဟီုဂှ်၊ ဟွံဒှ်သွံနာဲ။” (လိက်ဝိဓူရ) = “ဟယ်ပုဏ္ဏကလုလင်၊ ဝိဓူရ၏အသည်းကို နေရာအရောက်ရအောင်ယူပေးပါမည်ဟု သင်အာမခံထားသော်လည်း သင့်အပြောအတိုင်း မဖြစ်လာပါလား။”')
,(7028,3,4,'အမှုထမ်းသည်။ အခိုင်းအစေခံသည်။','ဒုၚ်ကာသၟိၚ် = မင်းမှုထမ်းသည်။')
,(7028,3,4,'အမှုထမ်းသည်။ အခိုင်းအစေခံသည်။','“လ္ပဒုၚ်ကာကဵုလောဘညိ။” (ဇ—၁၄၈။ အစွောံ။) = “လောဘတရား၏ကျေးကျွန် မဖြစ်ပါစေနှင့်။” (လောဘ၏ခိုင်းစေခြင်းကို မခံပါနှင့်။)')
,(7028,3,4,'အမှုထမ်းသည်။ အခိုင်းအစေခံသည်။','“အဲဍိက်ဒုၚ်ကာတၠညးဂှ်—။” (ဇ—၃၄၃။ အစွောံ။) =“အကျွန်ုပ်သည် အရှင်မင်းကြီး၏ အမှုတော်ကိုထမ်းရာ­—။”')
,(7028,3,4,'အမှုထမ်းသည်။ အခိုင်းအစေခံသည်။','“အဲဍိက်မဒုၚ်ကာကလုတ်အဴ။” (ဇ—၄ဝ၉။ အစွောံ။) = “အကျွန်ုပ်သည် တမန်အမှုကို ထမ်းဆောင်၏။”')
,(7028,3,4,'အမှုထမ်းသည်။ အခိုင်းအစေခံသည်။','“ဒုၚ်ကာခၠေဝ်ရော်ဂုဏ်နာဲ။” (အကြီုရာဇာဓိရာဇ်) = “အမှုတော်ကိုထမ်း၍ သခင့်ကျေးဇူးကိုဆပ်သည်။”')
,(7028,3,4,'အမှုထမ်းသည်။ အခိုင်းအစေခံသည်။','“သၟတ်ဂှ်ဇၞော်ဂေါဝ်အာ ဒုၚ်ကာမာန်—။” (အကြီုရာဇာဓိရာဇ်) = “ထိုသူငယ်သည် ကြီးပြင်း၍ အမှုထမ်းနိုင်သော အရွယ်ရောက်သည်။”')
,(7028,3,4,'အမှုထမ်းသည်။ အခိုင်းအစေခံသည်။','“ပိုဲဍိက်တံပေၚာအ်ကၠုၚ် ဒုၚ်ကာပဍိက်တၠတိဇၞော်ရောၚ်အဴ။” (အကြီုရာဇာဓိရာဇ်) = “ရေမြေ့အရှင်ထံ­ အမှုထမ်းကျွန်ခံလို၍ ကျွန်တော်မျိုးတို့ လာရောက်ခြင်းဖြစ်ပါသည်။”')
,(7029,3,4,'အမှုထမ်းသည်။ အမှုကိစ္စကို တာဝန်ခံဆောင်ရွက်သည်။','“ပဟိုတ်ကဵုအမာတ် မဒုၚ်ကိစ္စသၟိၚ်ပဿိုန်မွဲဂှ်တုဲ မိတ္တာမိတ္တဇာတ် ကျာ်တြဲတွံ။” (ဇ—၄၇၃။ အစွောံ။) = “ကောသလမင်း၏ ကိစ္စကိုဆောင်ရွက်သော တစ်ယောက်သောအမတ်ကို အကြောင်းပြု၍ မိတ္တာမိတ္တဇာတ်ကိုမြတ်စွာဘုရားဟောတော်မူ၏။”')
,(7030,3,4,'လက်ခံယူသည်။','“ပတွဵုနူဂှ်တုဲ ကသာပ်ညးသ္အာၚ်ဂှ် (ဗြဴစရာဲဍုၚ်) သဳရိမာဂှ် ဟွံဂွံဒုၚ်ကေတ်ရ။” (ဇ—၃၁၈။ အစွောံ။) = “ထိုအခါမှစ၍ ပြည့်တန်ဆာမ၊သာမာသည် သူတစ်ပါးတို့ထံမှ အဘိုးအခအသပြာကို လက်ခံယူခြင်းမရှိတော့။”')
,(7031,3,4,'ကမ်းပေးသည်။','‘ဗဒုၚ်ကဵု’ ရှု။')
,(7032,3,4,'လည်စဉ်းခံသည်။',NULL)
,(7033,3,4,'ဝန်ခံကတိပြုသည်။','“ပ္ဍဲတ္ၚဲဍေံက္တဵုဒှ်မၞိဟ်ဂှ် အဲကဵုပရၚ်တဲမွဲရောၚ် အဲဒုၚ်လဝ်ကအ်ပါၚ်ရ။” = “သူ့မွေးနေ့မှာ လက်ဆောင်တစ်ခု သူ့ကိုပေးမည်ဟု ငါဝန်ခံကတိပြုထားသည်။”')
,(7034,3,4,'ခေါင်းခံသည်။ တာဝန်ခံသည်။',NULL)
,(7035,3,4,'ဧည့်ခံသည်။',NULL)
,(7036,3,4,'ပျူငှာလောကဝတ်ပြုသည်။ ပဋိသန္ထာရပြုသည်။ ဧည့်ဝတ်ပြုသည်။',NULL)
,(7037,3,4,'အနံ့ခံသည်။','“(ခမဳဂှ်) ဆုၚ်ဒုၚ်ကျာအမြာဲဒကှ်ဂှ်ရ။” (ဇ—၃၉၂။ အစွောံ။) =“ထိုရဟန်းသည် ကြာပန်း၏ရနံ့ကို နမ်း၍အနံ့ခံ၏။”')
,(7038,3,4,'အမှာကြားခံသည်။','“သီုညးမသုန် ဗက်ပလံၚ်သြဳဝါသုဒေဝါန် ဒုၚ်ဂကန်လ္ၚောဝ်ဇိုၚ်သြဳဝါသုဒေဝါန်။” (အာန်ဇုနာန်) = “ငါးယောက်စလုံး သရီဝါသုဒေဝါန်ကို လိုက်လံပို့ဆောင်ကာ အမှာကြားခံပြီးလျှင် သရီဝါသုဒေဝါန်အား ရှိခိုး၏။”')
,(7039,3,4,'(တစ်စုံတစ်ဦး၏ တောင်းဆို','ပန်ကြားချက်ကို) ပြုလုပ်')
,(7039,3,4,'(တစ်စုံတစ်ဦး၏ တောင်းဆို','ဆောင်ရွက်ပေးမည်ဟုဝန်ခံသည်။ လက်ခံသည်။')
,(7039,3,4,'(တစ်စုံတစ်ဦး၏ တောင်းဆို','“ဗှ်ေတတ်ကၠေံက္ဍိုပ်သၟိၚ်တုဲ တိုပ်ကၠေံဇွသၟိၚ်ဂှ်တုဲ ဗှ်ေစဴကၠုၚ်ရ” ဂၞကျာ်ဂး။ “သာဓုဂွံရ” ပရန္တပဂှ်ဂးတုဲ ဍေံဒုၚ်လဝ်ဂလာန်ဂၞကျာ်ရ။ (ဇ—၄၁၆။ အစွောံ။) =“သင်သည် မင်းအား ခေါင်းဖြတ်သတ်၍ မင်း၏အလောင်းကို မြေ­မြှုပ်၍ သင်ပြန်ခဲ့လော့” ဟုမိဖုရားဆို၏။ ပရန္တပသည် “ကောင်းပြီ” ဟုဆိုကာ မိဖုရားစကားကို ဝန်ခံ၏။')
,(7039,3,4,'(တစ်စုံတစ်ဦး၏ တောင်းဆို','“မၞးတံပေၚာံဋ္ဌာန်မၞိဟ် ကာလဗြဲလောန်တုဲ ပၠန်ဇရေၚ်အဲရ” ဣသိအ္စာဂှ်ဂး။ “ဂွံရအဴ” ဣသိဂမၠိုၚ် ဒုၚ်လဝ်ဂလာန်ဒၠောအ်အ္စာတုဲ—။” (ဇ—၈၁။ အစွောံ။) = “သင်တို့သည် လူ့ရပ်ဋ္ဌာနေသို့သွား၍ မိုးတွင်းကာလလွန်သော် ငါ့ထံပြန်လာကြလော့” ဟု ဆရာရသေ့ဆို၏။ “ကောင်းပါပြီ” ဟု ရသေ့များ')
,(7041,3,4,'ခံတိုက်သည်။ ယှဉ်ပြိုင်တိုက်ခိုက်သည်။ အာခံသည်။','“နာဲဒပ်ပိတၠ ဒုၚ်ဂဟတ်ဂှ်တၠညးဒးဂၞပ်သန်။” (အကြီုရာဇာဓိရာဇ်) = “(ရန်သူကို) ယှဉ်ပြိုင်ခံတိုက်မည့် တပ်မှူးသုံးဦးတို့ကို ဘုရင်ရာဇာဓိရာဇ် အလွန်နှစ်သက်၏။”')
,(7041,3,4,'ခံတိုက်သည်။ ယှဉ်ပြိုင်တိုက်ခိုက်သည်။ အာခံသည်။','“မလ္ဂန်ဒှ်ဒေံသၟိၚ်လိုက်ဖြာ တဴတံဇိုၚ်တၠညးစိၚ်ဗတာၚ် ဒုၚ်ဂဟတ်ကဵုတၠညး။” (အကြီုရာဇာဓိရာဇ်) = “ဗညားဦးမင်းခြေရင်း­နေသော သမိန်လောက်ဖြား၏ညီဖြစ်သော မလဂွန်းသည် ဗညားဦးမင်းကို အာခံအန်တု၏။”')
,(7041,3,4,'ခံတိုက်သည်။ ယှဉ်ပြိုင်တိုက်ခိုက်သည်။ အာခံသည်။','‘ဂဟတ်’ (ကြိ) လည်းရှု။')
,(7042,3,4,'အနာခံသည်။ အနစ်နာခံသည်။',NULL)
,(7043,3,4,'ခံယူသည်။',NULL)
,(7044,3,4,'တောင်းပန်သည်။','“ဗှ်ေဟီုဒုၚ်ဂုန်ဍေံရ။” (ဇ—၃၅၇။ အစွောံ။) = “သူ့ကိုနင်ပြောဆိုတောင်းပန်ပါ။”')
,(7045,3,4,'၁။ (မိမိမလုပ်တော့ဘဲ) သူတစ်ပါးလုပ်သည်ကို လက်ခံသည်။','“ဗှ်ေအာမ္ဂး အဲဒုၚ်စရ၊အဲဟွံဒးအာရ။” = “နင်သွားလျှင် လုံလောက်သည်ဟု ငါခံယူသည်။ ငါသွားရန်မလိုတော့ပါ။”')
,(7045,3,4,'၁။ (မိမိမလုပ်တော့ဘဲ) သူတစ်ပါးလုပ်သည်ကို လက်ခံသည်။','၂။ အရာတစ်ခုကိုပြုလုပ်ပြီး၍ လုံလောက်သည်ဖြစ်၍ နောက်အရာတစ်ခုကို မပြုလုပ်တော့ဘဲရောင့်ရဲ၍နေသည်။')
,(7045,3,4,'၁။ (မိမိမလုပ်တော့ဘဲ) သူတစ်ပါးလုပ်သည်ကို လက်ခံသည်။','“ပိုဲစလဝ်ကွာၚ်ဖဲတုဲရ၊ ပိုဲဟွံစပုၚ်ရ၊ ပိုဲဒုၚ်စရ။” = “ဝမ်းဝသည်အထိ ငါတို့မုန့်စားထားပြီးပြီ၊ ငါတို့ထမင်းမစားတော့ပါ၊ မုန့်စားထားသည်နှင့်သာ ငါတို့ရောင့်ရဲ၍နေသည်။”')
,(7045,3,4,'၁။ (မိမိမလုပ်တော့ဘဲ) သူတစ်ပါးလုပ်သည်ကို လက်ခံသည်။','၃။ (အကျိုး) ခံစားရသည်။')
,(7045,3,4,'၁။ (မိမိမလုပ်တော့ဘဲ) သူတစ်ပါးလုပ်သည်ကို လက်ခံသည်။','“ဂွံပ္တုဲလဝ်ကၠာ၊ မဟာကုသဵု။ ဘဝဝွံသွံ၊ ဂွံဒုၚ်စအဵု။” (လိက်မ္ၚဵုပိစှ်ောဒစာံ။ မာံထဝ်စိုပ်။) = “မဟာကုသိုလ်ပြုထားခဲ့ရသဖြင့် ဤဘဝတွင် အကျိုးခံစားရ၏။”')
,(7046,3,4,'အကျိုးခံစားသည်။','“မၞးတံဂွံဒုၚ်စဖဵုဇၞော်ကၠးသန်ရ။” (ဇ—မဟောဟ်သဓ။ အစွောံ။) = “သင်တို့သည် ကြီးစွာအကျိုးခံစားရ၏။”')
,(7046,3,4,'အကျိုးခံစားသည်။','“ဆပူဂဵုမဒှ်ဒကာမွဲဂှ် မဂွံဒုၚ်စဖဵုရ။” (သၠပတ်သတိပထာန်) = “ဒကာဖြစ်သောပုဂ္ဂိုလ်တစ်ဦးသာ အကျိုးခံစားရ၏။”')
,(7047,3,4,'(ဘုရင်) ညီလာခံဝၚ်သည်။ အခစားခံသည်။','“တုဲသၟိၚ်စသက သ္အးမုက္ခဝါတုဲ ဝတ်မဒုၚ်စမုက်ပယတ် သၟိၚ်တိတ်အာရ။” (သၠပတ်ဒ္ၚောဝ်သၜောံ) = “ပြီးနောက် မင်းသည် တံပူစား (သွားတိုက်) မျက်နှာသစ်ပြီးလျှင် ပြုနေကျဝတ္တရားအတိုင်း ညီလာခံဝင်ရန် ထွက်သွား၏။”')
,(7047,3,4,'(ဘုရင်) ညီလာခံဝၚ်သည်။ အခစားခံသည်။','“သၟိၚ်ဇၞော်မိၚ်တုဲ ဒးပယာံမပပြဘိုက်တုဲ တိတ်ကၠုၚ်ဒုၚ်စမုက် ပ္ဍဲမုက်ရၚ်တုဲ—။” (ဇ—ဝေသန္တဝ်။အစွောံ။) = “မင်းကြီးကြား၍ စားတော်ခေါ်ချိန်အပြီး­ ထွက်လာ၍ မင်းရင်ပြင်­ အခစားခံ၏။”')
,(7047,3,4,'(ဘုရင်) ညီလာခံဝၚ်သည်။ အခစားခံသည်။','“ကြဴဝွံတၠစိၚ်ဗ္တာၚ် (ယဲက္ဍၚ်အာ) တိတ်ဒုၚ်စမုက်ဟွံဒှ်။” (အကြီုရာဇာဓိရာဇ်) = “နောက်အဖို့­ ဆင်ဖြူရှင်ဗညားဦးမင်းသည် ရောဂါသည်း၍ ထွက်၍အခစားမခံဖြစ်ဘဲရှိ၏။”')
,(7047,3,4,'(ဘုရင်) ညီလာခံဝၚ်သည်။ အခစားခံသည်။','“တၠညးရာဇာဓိရာဇ် ကသဳသၞာတသိုက် တိတ်ဒုၚ်စမုက် ပ္ဍဲကဵုကၠတ်ထဝ် လ္တူရာဇာပလ္လၚ်။” (အကြီုရာဇာဓိရာဇ်) = “ဘုရင်ရာဇာဓိရာဇ်သည် ထိုင်ရာမှထတော်မူ၍ ရာဇပလ္လင်အထက် နန်းခမ်းမဆောင်­ အခစားခံတော်မူ၏။”')
,(7048,3,4,'ခံ့သည်။ တောင့်တင်းခိုင်မာသည်။ ကျန်းခံ့သည်။','ဒုၚ်စရၚ်ပ္ဍဲကေၚ်ကာ = အမှု­ခံ့သည်။ တောင့်တင်းခိုင်မာသည်။ (ပါဠိ—ကမ္မည')
,(7048,3,4,'ခံ့သည်။ တောင့်တင်းခိုင်မာသည်။ ကျန်းခံ့သည်။','ကမ္မနိယ)')
,(7048,3,4,'ခံ့သည်။ တောင့်တင်းခိုင်မာသည်။ ကျန်းခံ့သည်။','“စိုတ်ထတ်မိက်ဂွံအာဒၟံၚ်ကီုလေဝ်ဟိုတ်ကာယဟွံဒုၚ်စရၚ် အာဟွံမာန်ရ။” = “သွားလိုသောစိတ်ပြင်းပြနေသော်လည်း ခန္ဓာကိုယ်က မကျန်းခံ့သောကြောင့် မသွားနိုင်။” (စိတ်သွားတိုင်းကိုယ်မပါ။)')
,(7048,3,4,'ခံ့သည်။ တောင့်တင်းခိုင်မာသည်။ ကျန်းခံ့သည်။','မၞုံစိုတ်မဒုၚ်စရၚ် = ခံ့သောစိတ်ရှိသည်။ တောင့်တင်းသောစိတ်ရှိသည်။ (ပါဠိ—ကလ္လစိတ္တ)')
,(7049,3,4,'အများကိစ္စကို လက်ခံဆောင်ရွက်သည်။','“သၟိၚ်ဨကရာတ် ဂပ်ဂဝ်ဒုၚ်စရၚ်ညးဟေၚ်။” (ဓမ္မသာတ်။ MDT-VII) = “မင်းဧကရာဇ်သည် (တိုင်းသူပြည်သား) အများကိစ္စတို့ကို လက်ခံဆောင်ရွက်အပ်သည်။”')
,(7050,3,4,'(ဒုက္ခ၊ သုခ) ခံစားသည်။','‘စသိုၚ်’ ရှု။')
,(7051,3,4,'အစီအရင် (အဆုံးအဖြတ်) ကို ခံယူသည်။ စီရင်ခြင်းကို ခံယူသည်။','“ကၜါဒှ်ဝါတ်ဂါတ်ရေၚ်သ္ကံရ။ — ညးၜါအာဒုၚ်စဳရေၚ်ကဵုကၞုဟ်ရ။” (ဇ—၂ဝ၅။ အစွောံ။) = “နှစ်ခုသောငါးတို့သည် အချင်းချင်း အငြင်းအခုံဖြစ်၍ လိပ်၏စီရင်ဆုံးဖြတ်ခြင်းကို ခံရန်သွားကြ၏။”')
,(7052,3,4,'(တစ်စုံတစ်ဦး၏အပြစ်စသည်ကို) အစားခံယူသည်။ ကိုယ်စားခံသည်။','“ယာံရလၟဟွံကဵုအခေါၚ်တုဲ ဇကုအဲဒုၚ်စၞးတုဲ ဇကုတၠအဲ ကဵုဂွံဗၠးညိရအဴ” ဒြာဲဗြဴဂးကဵုသၟိၚ်ဒြာဲထဝ်။ (ဇ—၃၅၉။အစွောံ။) = “အကယ်၍မုဆိုးသည် အခွင့်မပေးသည်ရှိသော် အကျွန်ုပ်သည် ကိုယ်စားခံ၍ အရှင့်ကိုလွတ်စေအံ့” ဟုသမင်မသည် (ကျော့ကွင်းမိသော) ရွှေသမင်မင်းအားပြော၏။')
,(7052,3,4,'(တစ်စုံတစ်ဦး၏အပြစ်စသည်ကို) အစားခံယူသည်။ ကိုယ်စားခံသည်။','“ယွံကောလၟ၊ — ဇကုအဲဍိက်ဗြဴဂှ် ဒုၚ်စၞးတၠသ္ၚိအဲသၟိၚ်ဒြာဲထဝ်ဝွံရ။—” ဒြာဲဗြဴဂး။ (ဇ—၃၅၉။ အစွောံ။) =“အစ်ကိုမုဆိုးသား၊ အကျွန်ုပ်သည် လင်ဖြစ်သောရွှေသမင်မင်း၏ ကိုယ်စားခံပါမည်” ဟုသမင်မဆို၏။')
,(7052,3,4,'(တစ်စုံတစ်ဦး၏အပြစ်စသည်ကို) အစားခံယူသည်။ ကိုယ်စားခံသည်။','“အဲသ္အာဒုၚ်စၞးသၟိၚ်မရ။” (ဇ—၅၁၃။ အစွောံ။) = “ခမည်းတော်ကိုယ်စား အကျွန်ုပ်သွား၍ ကိုယ်စားခံပါအံ့။”')
,(7053,3,4,'အချစ်ကိုလက်ခံသည်။ ချစ်ရေးဆိုလာသည်ကို ကြည်ဖြူလက်ခံသည်။','“မိပဟီုပၠဳ၊ ပၠံလွဳရိယ။ မိဒုၚ်ဇြဟာန်၊ ပရေၚ်ဒါန်မ။ လမျီုခန္ဓ၊ ကောပတမှာဲ။” (လိက်သၟိၚ်ဇဲယဒတ္တ) =“အမိအချိန်ဆွဲ၍ ရှည်ဝေးအောင်ပြောလေနှင့်၊ ဝီရိယမလျှော့လေနှင့်။ မောင့်ဖူးစာဖြစ်၍ မောင့်အချစ်ကိုလက်ခံပါ၊ အသက်နှင့်ခန္ဓာကို မောင်ဆက်နှင်းပါမည်။”')
,(7054,3,4,'၁။ (ပေးသောအရာကို) ရယူလက်ခံသည်။','“ယြဴပူဇဴသကာ ပဏ္ဏာကာရအိုဿီု မၞးတံမကဵုကုအဲဂှ် အဲဟွံဒုၚ်တဲရ။” (ဇ—ဝေသန္တဝ်။ အစွောံ။) = “သင်တို့ပေးကုန်သော အလုံးစုံသောပူဇော်သက္ကာရ လက်ဆောင်ပဏ္ဏာတို့ကို ငါလက်မခံပါ။”')
,(7054,3,4,'၁။ (ပေးသောအရာကို) ရယူလက်ခံသည်။','၂။ သဘောတူလက်ခံသည်။')
,(7054,3,4,'၁။ (ပေးသောအရာကို) ရယူလက်ခံသည်။','“ကသပ်လညာတ်အဲဂှ် ညးဒုၚ်တဲရ။” = “ငါ့အမြင်ကို သူလက်ခံသည်။”')
,(7054,3,4,'၁။ (ပေးသောအရာကို) ရယူလက်ခံသည်။','၃။ (ရန်သူစစ်စသည်၏) တိုက်ခိုက်မှု လက်ရုံးလက်စွမ်းကို ခုခံနိုင်စွမ်းရှိသည်။')
,(7054,3,4,'၁။ (ပေးသောအရာကို) ရယူလက်ခံသည်။','“ညးဂှ် ဒုၚ်တဲသၟိၚ်ကလိၚ်မာန်ရော။ သၟိၚ်ကလိၚ်ဇၞး သၟိၚ်အဿကကျရ” သၟိၚ်အိန်ဂး။ (ဇ—၃ဝ၁။ အစွောံ။) = “အဘယ်သူသည် ကာလိင်္ဂမင်း၏လက်ရုံးလက်စွမ်းကို ခံနိုင်ငြားအံ့နည်း။ ကာလိင်္ဂမင်းသည် အောင်လတ္တံ့။အဿကမင်းသည် ရှုံးလတ္တံ့။”')
,(7055,3,4,'ဒိုင်ခံသည်။ တစ်ဦးတစ်ယောက်တည်း တစ်ဖွဲ့တည်းက တာဝန်ယူလုပ်ကိုင်သည်။','“ဂကောံသၟတ်ကွာန်ပိုဲ ဒုၚ်တိုၚ်တုဲ တ္ၚဲဏအ်ကဵုဒါန်ဖာပ်သၚ်ရ။” = “ငါတို့ရွာမှ လူငယ်အဖွဲ့ကဒိုင်ခံ၍ သံဃာတော်များအား ယနေ့ဆွမ်းကပ်လှူသည်။”')
,(7056,3,4,'ကြိုဆိုသည်။',NULL)
,(7057,3,4,'ဒကာခံသည်။ ပေးလှူသည်။ ကျွေးမွေးသည်။',NULL)
,(7058,3,4,'ခရီးဦးကြိုသည်။',NULL)
,(7059,3,4,'ဒုက္ခခံသည်။','“ဒုၚ်ဒဒိုက်ဟွံမာန်မ္ဂး ဟွံဂွံတသိုက်ရ။” = “ဒုက္ခမခံနိုင်လျှင် ချမ်းသာကိုမရ။”')
,(7059,3,4,'ဒုက္ခခံသည်။','“ပိုဲညးဂမၠိုၚ်ဝွံ ထောံကၠေံကိလေသကာမ ဝတ္ထုကာမတုဲ တိတ်ပခမဳဒုၚ်ဒဒိုက်ရ”ဣသိတံဂး။ (ဇ—၂၁၃။ အစွောံ။) = “ငါတို့သည် ကိလေသာကာမ ဝတ္ထုကာမတို့ကိုစွန့်၍ ရဟန်းပြုဒုက္ခခံ၏။”')
,(7059,3,4,'ဒုက္ခခံသည်။','“ကျာ်ဒုၚ်ဒဒိုက်၊ ဂၠာဲဖျိုက်မှာဇန်။” (လိက်ရတနပဇ္ဇောတ) = “မြတ်စွာဘုရားသည် လူအပေါင်းတို့ချမ်းသာစေခြင်းငှာ ဒုက္ခခံ (ကယ်ချွတ်) တော်မူ၏။”')
,(7060,3,4,'အကျော်အစောခံသည်။','“မၚ်ဗၠာဲသဥ္ဇိဝ — မဟွံဗစာရဏာ သၟိက်ဒုၚ်ဒယှ် ပ္ဍဲမၚ်ဗၠာဲမသုန်ကၠံတေံ ဇၞော်စိုတ်တုဲ မက္တဵုဇွကၠဂှ်—။” (ဇ—၁၅ဝ။ အစွောံ။) = “သဥ္ဇိဝလုလင်သည် မစဉ်းစားမဆင်ခြင်ဘဲ အဖော်လုလင်ငါးရားတို့­ အကျော်အစောခံလိုသောစိတ်ကြီးမား၍ကျားသေကို နိုးထစေ၏။”')
,(7061,3,4,'အမှီခံသည်။ (သူတစ်ဦးလဲမကျသွားအောင်) ထောက်ကူခံထားသည်။','“(ဗောဓိသတ်ဒြာဲဒးဓနက်တုဲ ဒြာဲစိတ္တဒေံဗောဓိသတ်ဂှ်) ဗွဲသ္ကဲသ္တုံဗောဓိသတ်ဂှ် ပြာပ်အာတုဲ စှ်ေဒုၚ်လဝ်ဒလာဲ ပခိုၚ်လဝ်ဗောဓိသတ်။” (သၠပတ်ဗြဟ္မဒတ္တ ဂၞကျာ်ခေမာဝတဳ) = “ဘုရားလောင်းသမင်ကျော့ကွင်းမိသောအခါ ညီဖြစ်သောစိတ္တသမင်သည် ဘုရားလောင်း၏လက်ယာဘက်နံပါးသို့သွားကာ ဆင်း၍အမှီခံလျက် ဘုရားလောင်းအား ခိုင်ခိုင်ရပ်နိုင်အောင် ထောက်ကူဖေးမပေးထား၏။”')
,(7061,3,4,'အမှီခံသည်။ (သူတစ်ဦးလဲမကျသွားအောင်) ထောက်ကူခံထားသည်။','“(ဒေံဗြဴသုထာဏာဂှ်) ဗွဲဒိုဟ်သ္ကဲဇွိဗောဓိသတ်ဂှ် လုပ်ထပ်ဒုၚ်ဒလာဲ ပခိုၚ်လဝ်ကောဇကုရ။” (သၠပတ်ဗြဟ္မဒတ္တ ဂၞကျာ်ခေမာဝတဳ)')
,(7062,3,4,'အဆုံးအမကို ခံယူသည်။ အဆုံးအမခံသည်။','“ညးပိဂှ် ဒုၚ်လဝ်ဒလောံဗ္တောန်ဗောဓိသတ်—။” (ဇ—၃၁၆။ အစွောံ။) = “သုံးယောက်ကုန်သောသူတို့သည် ဘုရားလောင်း၏ အဆုံးအမကိုခံ၍—။ ”')
,(7063,3,4,'အလှူခံသည်။ အလှူကိုခံယူသည်။','“သၚ်မ္ဂးဝွံ မတဴမ္ၚးသရာံပါပ်တုဲ ထေက်ဒုၚ်ဒါန်ညးအိုတ်သီုရ။” = “သံဃာမည်သည် မကောင်းမှုကို အပပြုပြီးသည်ဖြစ်၍ အလုံးစုံသောသူတို့၏အလှူကို ခံယူထိုက်၏။”')
,(7064,3,4,'ကြံ့ကြံ့ခံသည်။ ခံချိသည်။ ခံနိုင်ရည်ရှိသည်။','“ပၞာန်သတြုဝွံ ဒြဟတ်ဇၞော်လောန်၊ပၞာန်ပိုဲဒုၚ်ဒဝ်ဟွံမာန်ရ။” = “ရန်သူ့စစ်သည် အလွန်အင်အားကြီး၏။ ငါတို့စစ်သည် ကြံ့ကြံ့မခံနိုင်ပါ။”')
,(7064,3,4,'ကြံ့ကြံ့ခံသည်။ ခံချိသည်။ ခံနိုင်ရည်ရှိသည်။','“ဍေံပျဲဒၟံၚ်အဲနာနာသာ်ဂှ် အဲဒုၚ်ဒဝ်ဟွံမာန်ရ။” = “ငါ့ကို သူအမျိုးမျိုးနှိပ်စက်နေသည်ကို ငါခံနိုင်ရည်မရှိတော့ပါ။”')
,(7064,3,4,'ကြံ့ကြံ့ခံသည်။ ခံချိသည်။ ခံနိုင်ရည်ရှိသည်။','“ကောန်တြုံသၟိၚ်ဝွံ ၜိုန်သွတ်တဴဏီလေဝ် မ္ငိုဟ်ထဍိုဟ်ကြံသကာတ်ကြံကြတဴရောၚ်။ ကောန်တြုံသၟိၚ် ကာလဇၞော်အာ ပကၚ်ရၚ်ကၟိန်ဍုၚ်တုဲ သိက်ပိုဲဒုၚ်ဒဝ်မာန်ရော” ညးဍုၚ်ရးတံဂမၠိုၚ်ဂး။ (ဇ—၁၄၉။ အစွောံ။) = “ဤမင်းသားငယ်သည် ငယ်ရွယ်သေးသော်လည်း ခက်ထန်ကြမ်းကြုတ်ရုန့်ရင်း၏။ ကြီးပြင်း၍ မင်းလုပ်အုပ်ချုပ်သောအခါ ငါတို့သည် အဘယ်သို့ခံချိနိုင်ပါမည်နည်း။”')
,(7065,3,4,'ဗျာဒိတ်ခံသည်။','“အလံၚ်ကျာ်တြဲဂေါတမ နူဘဝမဒှ်ရသိသုမေဓတေံဂှ် ဂွံဒုၚ်ပယျးဒိုဟ် နူဇရေၚ်ကျာ်တြဲဒိဗ္ဗၚ်ကဵုရ။” = “ဂေါတမဘုရားလောင်းလျာသည် သုမေဓါရှင်ရသေ့ဘဝမှ ဒီဗင်ကရာမြတ်စွာဘုရားအထံတော်တွင် ဗျာဒိတ်ခံယူ၏။”')
,(7066,3,4,'ပဥ္စင်းခံသည်။ ရဟန်းပြုသည်။','“(သၟတ်ဗြဴဂှ်) တိတ်ပကၠေံခမဳ ဒုၚ်ကၠေံပယၚ်ရ။” (ဇ—၃၅၉။ အစွောံ။) = “ထိုအမျိုးသမီးငယ်သည် ကျောင်းသို့ထွက်၍ ရဟန်း ပြု၊ ပဥ္စင်းခံ၏။”')
,(7067,3,4,'အဘိသိက်ခံသည်။ အဘိသိက်သွန်းခြင်းကိုခံသည်။','“ဗောဓိသတ်ပေၚ်အာယုက်ထပှ်သၞာံတုဲ ဒုၚ်ပသေက်ဘိသေခ ဒုၚ်ယၟုအလဳနစိတ္တရာဇာ ဂွံပကၚ်ရၚ်ဍုၚ်ရ။” (ဇ—၁၅၆။ အစွောံ။) = “ဘုရားလောင်းသည် အသက်ခုနစ်နှစ်ပြည့်လတ်သော် အဘိသိက်ခံ၍ အလီနစိတ္တအမည်ဖြင့် တိုင်းပြည်အုပ်ချုပ်၏။”')
,(7067,3,4,'အဘိသိက်ခံသည်။ အဘိသိက်သွန်းခြင်းကိုခံသည်။','“သၟိၚ်ဒုၚ်ပသေက်ရာဇာဘိသေက ပဨကရာဇ်။” (အကြီုရာဇာဓိရာဇ်) = “မင်းသည် ရာဇာဘိသေက အဘိသိက်ခံ၍ မင်းပြု၏။”')
,(7068,3,4,'(သူတစ်ပါးအပ်နှံသောဥစ္စာကို) သိမ်းဆည်းစောင့်ရှောက်ပေးရန် လက်ခံသည်။ အအပ်နှံခံသည်။','‘ပသိုန်’ (န) လည်းရှု။')
,(7069,3,4,'အပူဇော်ခံသည်။','“အ္စာသဝ်ဂှ် ဂွံဒုၚ်ပူဇဴသကာညးရ။” = “ထိုသမားတော်သည် လူတကာ၏ပူဇော်ခြင်းကိုခံရသည်။”')
,(7070,3,4,'ဝန်ခံကတိပေးသည်။ လက်ခံကတိပြုသည်။ နှုတ်ကတိပြုသည်။','“ဆဗၞတ်ညးမွဲကီုဟွံဂံၚ်ဒုၚ်ပါၚ်—။” (ဇ—၃၉၈။ အစွောံ။) = “တစ်ယောက်သောသူမျှ လက်ခံကတိပေးခြင်းမပြုဝံ့။”')
,(7071,3,4,'(နှုတ်အားဖြင့်၄င်း လည်ညှိတ်၍၄င်း) သဘောတူသည်။ ဝန်ခံခွင့်ပြုသည်။','“သၟိၚ်တိဿဒုၚ်ပါၚ်လာၚ်ကအ် ကဵုဗဗၞးမိစ္ဆာဒိဋ္ဌိတံရ။” (မိတၠထဝ်။ ပါလိတ။) = “တိဿမင်းသည် မိစ္ဆာအယူရှိသောပုဏ္ဏားတို့ကို သဘောတူခွင့်ပြုလိုက်၏။”')
,(7072,3,4,'ရန်သူ့စစ်ကိုခုခံသည်။','“ပေက်ဒဴချာဲပြး ဒုၚ်ပၞာန်ညးဟွံမာန်တုဲ မရာတ်ကၠုၚ်စိုပ်ပိုဲဍိက်သ္ဂးဟာ။” (ဇ—ဝေသန္တဝ်။ အစွောံ။) = “ကစဉ့်ကလျားထွက်ပြေး၍ ဖရိုဖရဲဖြင့် ရန်သူ့စစ်ကို မခုခံနိုင်သောကြောင့် အကျွန်ုပ်တို့ဆီ အရှင်မင်းမြတ်ရောက်လာသလော။”')
,(7073,3,4,'ဖက်ပြိုင်သည်။ ယှဉ်ပြိုင်သည်။ ယှဉ်ပြိုင်ဘက်အဖြစ်လက်ခံသည်။','“သဗ္ဗညုမပတၠပညာသ္ဇိုဟ်လောန် ညံၚ်မှာသၟိတ်ဟွံဂံၚ်ဒုၚ်ဖဝှက်—။” (ဇ—မဟောဟ်သဓ။အစွောံ။) = “သဗ္ဗညုမြတ်စွာဘုရားသည် အလွန်နက်ရှိုင်းသောပညာရှိ၏။ မဟာသမုဒ္ဒရာသည်လည်း ဖက်ပြိုင်ခြင်းငှာမဝံ့။”')
,(7073,3,4,'ဖက်ပြိုင်သည်။ ယှဉ်ပြိုင်သည်။ ယှဉ်ပြိုင်ဘက်အဖြစ်လက်ခံသည်။','“သဗ္ဗညုမပတၠပညာသတီုလောန်သန် သတီုတိ သတီုဍာ် သတီုကျာ ဟွံဂံၚ်ဒုၚ်ဗဝှက်—။” (ဇ—မဟောဟ်သဓ။ အစွောံ။) = “သဗ္ဗညုမြတ်စွာဘုရားသည် အလွန်ထူထဲသောပညာရှိ၏။ မြေထုရေထုလေထုတို့သည်လည်း ဖက်ပြိုင်ခြင်းငှာမဝံ့။”')
,(7074,3,4,'(ရဟန်းသံဃာ) လှူဖွယ်ပစ္စည်းဆက်ကပ်သည်ကို လက်ခံယူသည်။',NULL)
,(7075,3,4,'အရှုစားခံသည်။ ပြသသည်။','“သီုကျာ်သြဳစရာဲလျးတၟး ရဴမဒုၚ်ဗဗဵုဨကရာတ်ဂမၠိုၚ်လတူနန်ထဝ်ကီု။” (အာန်ဇုနာန်) = “ကျက်သရေအလင်းရောင်နှင့်တကွ ရွှေနန်းပေါ်­ မင်းဧကရာဇ်တို့အား ပြသအရှုစားခံစေသကဲ့သို့။”')
,(7076,3,5,'မိုးရွာမရှောင် နေလောင်မမှု အပင်ပန်းခံလျက်။','“ဒုၚ်ဗြဲစဲတ္ၚဲတုဲ အပါပိုဲဒးကၠောန်ဗ္ၚ တၞဟ်နဂယိုင်လမျီုရ။” = “ငါတို့အဖေသည် အသက်မွေးဝမ်းကြောင်းအတွက် မိုးရွာမရှောင်နေလောင်မမှု အပင်ပန်းခံလျက် လယ်လုပ်ရသည်။”')
,(7077,3,4,'မိမိ၏နောက်လိုက်အဖြစ် လက်ခံသည်။','“(ကောန်ဇကုမပ္တုဲဝတ်ကၠောန်ၜိုတ်ဒၟံၚ်ကဵုဇကုလၟိုန်ဂှ် နတဲဇကုဟေၚ်မဂစိုတ်ကၠေံရောၚ်မ္ဂး ကသပ်လဟီုပွယဗြဴဝွံ) ညးဒြိုဟ်ဒဇန်သဟာသဳသ္အာၚ်မွဲ မဂံၚ်ဒုၚ်ဗွက်နွံရော။” (ဇ—၆၁။ အစွောံ။) = “မိမိအား နေ့စဉ်နှင့်အမျှ ပြုစုလုပ်ကိုင်ပေးနေသော မိမိ၏သားကို မိမိလက်ဖြင့်ပၚ်သတ်အံ့ဟု ကြံစည်ပြောဆိုပြုမူသော ထိုမိန်းမအိုကြီးကို အခြားတစ်ပါးသော အဘယ်ရက်စက်ကြမ်းကြုတ်သောသူတို့သည် နောက်လိုက်အဖြစ်လက်ခံဝံ့ပါမည်နည်း။”')
,(7078,3,4,'အတွေ့ခံသည်။ မျက်နှာချင်းဆိုင်သည်။ ရင်ဆိုင်သည်။','“(သၟိၚ်ဂှ်) သတြုဇၟာပ်ဒိုဟ်မသ္ဂံၚ်ဒုၚ်မုက်ဟွံမွဲ ဇၞော်ကဵုကြဳဇှ်။” (ပြကိုဟ်ဂဝမ္ပတိ) = “ထိုမင်းသည် ဘုန်းတန်ခိုးကြီး၏။ အရပ်ရပ်မှရန်သူများ မျက်နှာချင်းမဆိုင်ဝံ့ကုန်။”')
,(7078,3,4,'အတွေ့ခံသည်။ မျက်နှာချင်းဆိုင်သည်။ ရင်ဆိုင်သည်။','“စန္ဒဝတဳဟွံဒုၚ်မုက် အောပ်ကၠေံရ။” (သၠပတ်စန္ဒဝတဳ) = “စန္ဒဝတီသည် မျက်နှာအတွေ့မခံဘဲ ပုန်းလိုက်၏။”')
,(7079,3,4,'ပရိတ်ရွတ်မင်္ဂလာပွဲ ကျင်းပသည်။',NULL)
,(7080,3,4,'အမည်ခံသည်။','“ယွံမအံက်၊ အဲမဒှ်ဂၞကျာ်ဂှ် ဆမဂွံဒုၚ်ယၟုဂၞကျာ်ညိကီု လာဘသက္ကာရ ပိုန်ဟာန်ဣန်သွဵုပူဇဴသကာ အဲဟွံကလိဂွံ—” ဂၞကျာ်ဂး။ (ဇ—၂၂၃။ အစွောံ။) = “ဖခင်၊ အကျွန်ုပ်သည် မိဖုယားဖြစ်သည်မှာ အမည်ခံမိဖုယားမျှသာတည်း။ လာဘ်လာဘစည်းစိမ်အာဏာမရှိ” ဟုမိဖုယားဆို၏။')
,(7081,3,4,'အရသာခံသည်။',NULL)
,(7082,3,4,'အဆုံးအမခံသည်။ အသၚ်ခံသည်။','“လတေံစိၚ်ဇၟူ ဒၟံၚ်တဴပ္ဍဲဂြိုပ်ဗြာတ် ဟွံဒုၚ်လၟေတ်ဗဝ်သၟဝ်တုဲ ကွေံသဂွံဒုၚ်ဖ္ဍိုက်သၟိၚ်မန္ဓာတ်စက္ကဝဝ်ဟာ။” (ဇ—မဟောဟ်သဓ။ အစွောံ။) (ဗဝ်သၟဝ် = ဗဝ်မှဝ် = အ္စာစိၚ်) = “ငှက်ပျောတော­နေသောဆင်ပြောင်သည် ဆင်ဆရာ၏အဆုံးအမကိုမခံပါက အဘယ်မှာလျှင် မင်းမန္ဓာတ်စကြဝတေးမင်း၏ စီးတော်ယာဉ်ဖြစ်ရလတ္တံ့နည်း။”')
,(7082,3,4,'အဆုံးအမခံသည်။ အသၚ်ခံသည်။','“ဒုၚ်လၟေတ်ကၠာ၊ စိုတ်သဒ္ဓါလောန်။” (လိက်ဝိဓူရ) = “သဒ္ဓါစိတ်ကြီး၍ အဆုံးအမခံသည်။”')
,(7083,3,4,'တာဝန်ခံသည်။ အာမခံသည်။','“ယွံနန္ဒ၊ ပၟဝ်ဓဝ်ခမဳတုဲ ဂွံ (ဗြဴအဆေဝ်သွဝ်ဂမၠိုၚ်) ဗိုန်ရ။ အဲသဒုၚ်လယိုင်ရ” ကျာ်တြဲဂး။ (ဇ—၁၈၂။ အစွောံ။) = “နန္ဒ၊ ရဟန်းတရားကို အားထုတ်ပါက နတ်သမီးများကို တကယ်ရလိမ့်မည်။ ငါဘုရားအာမခံတော်မူသည်။”')
,(7084,3,4,'ဝန်ခံသည်။',NULL)
,(7085,3,4,'ဝန်ထမ်းသည်။ အမှုထမ်းသည်။ တာဝန်ယူ၍ ဆောင်ရွက်ပေးသည်။','“သဘဴအမာတ်မွဲ မဒုၚ်သဇိုၚ်သၟိၚ်မ္ဂးဂှ် (ဒး) ညာတ်အတိက်အနာဂတ်ပစ္စုပ္ပန်ဂတကြဴရောၚ်။” (ဇ—၇၉။ အစွောံ။) = “မင်းမှုထမ်းအမတ်မည်သည် အတိတ်၊ အနာဂတ်၊ ပစ္စုပ္ပန်၊ ရှေ့နောက်တို့ကို မြော် မြင်တတ်ရပါမည်။”')
,(7085,3,4,'ဝန်ထမ်းသည်။ အမှုထမ်းသည်။ တာဝန်ယူ၍ ဆောင်ရွက်ပေးသည်။','“ဇၟာပ်ဍိက်သ္ကံသီုဖအိုတ် မကၠောန်ၜိုတ်မဒုၚ်သဇိုၚ်တံဂှ် (ကောန်ဗြဴသေဋ္ဌဳဂှ်) တ္ၜေဟ်လက်တက်ၜုၚ်ဒၟံၚ်လၟိုန်ဟေၚ်။” (ဇ—၆၃။ အစွောံ။) = “ထိုသူဋ္ဌေးသမီးသည် လုပ်ကိုင်အမှုထမ်းကုန်သော ကျွန်အမှုလုပ်တို့ကို အမြဲတစေ ဆဲရေးရိုက်ပုတ်နေ၏။”')
,(7085,3,4,'ဝန်ထမ်းသည်။ အမှုထမ်းသည်။ တာဝန်ယူ၍ ဆောင်ရွက်ပေးသည်။','“အလန်ဏံ ဗညာဓရေမ်ဒုၚ်သဇိုၚ် ကိစ္စက္ဍိုၚ်ဗ္တာၚ်ဍုၚ်ပိုဲညးဂမၠိုၚ်ရောၚ် ဟွံသေၚ်ဟာ” ဖရၚ်မၚ်ဂံၚ်ဂး။ (အကြီုရာဇာဓိရာဇ်) = “ယခုအကြိမ်­ သမိန်ဗရမ်းသည် ငါတို့တိုင်းပြည်ထီးနန်းကိစ္စကို တာဝန်ခံထမ်းဆောင်ပေးသည် မဟုတ်လော” ဟုဘုရင်မင်းခေါင်ဆို၏။')
,(7085,3,4,'ဝန်ထမ်းသည်။ အမှုထမ်းသည်။ တာဝန်ယူ၍ ဆောင်ရွက်ပေးသည်။','“ကိစ္စတၠအဲ အဲဒုၚ်သဇိုၚ်ရ။” (အာန်ဇုနာန်) = “သင့်ကိစ္စကို ငါတာဝန်ခံဆောင်ရွက်မည်။”')
,(7086,3,4,'သာဓုခေါ်သည်။','“ပိုဲဒုၚ်သာဓု၊ တ္ၚဲဝွံရကောန်။” (လိက်သုဝဏ္ဏသာံ။ မာံသေၚ်။) = “ချစ်သား၊ ယနေ့ပင် ငါတို့သာဓုခေါ်ပါ၏။”')
,(7086,3,4,'သာဓုခေါ်သည်။','‘ကဵုသာဓုကာ’ (ကြိ) လည်းရှု။')
,(7087,3,4,'သက်သေခံသည်။',NULL)
,(7088,3,4,'ကံစီမံရာကို ခံရသည်။','“(ဇၟာပ်သတ္တအ်အိုတ်သီု) နလၟေၚ်ပရေၚ်ကံအတိက် မဒးပ္တုဲလဝ်ဂှ် မဒးဒုၚ်သၞောဝ်ကံဂှ်ရ။” (ဇ—၃၆၈။ အစွောံ။) = “သတ္တဝါအပေါင်းတို့သည် အတိတ်ကပြုခဲ့သောကံအတိုင်း ကံစီမံရာကို ခံကြရကုန်၏။”')
,(7089,3,4,'ကျိန်သည်။ ကျိန်ဆိုသည်။','‘ဒုၚ်သွဴ’ နှင့်အတူတူ။')
,(7089,3,4,'ကျိန်သည်။ ကျိန်ဆိုသည်။','‘ (ညးၜါ) ဒုၚ်သွာပသစာတုဲ ဗွဲကြဴသ္ဍိုက်မၠိုက်အာပၠန်။’ (ဇ—မဟောဟ်သဓ။ အစွောံ။) = ‘ထိုသူနှစ်ဦးတို့သည် ကျိန်ဆိုသစ္စာပြု၍ နောင်ချစ်ခင်သွားကြပြန်၏။’')
,(7089,3,4,'ကျိန်သည်။ ကျိန်ဆိုသည်။','“မိတိတ်ဒုၚ်သွာ၊ မိၚ်ဟာကြက်ဗိုတ်။” (လိက်ပတ္တစာရဳ။ နာဲထဝ်စိုပ်။) ဒုၚ်သွဴ (ကြိ) ကျိန်သည်။ ကျိန်ဆိုသည်။')
,(7089,3,4,'ကျိန်သည်။ ကျိန်ဆိုသည်။','“ညးပန်ဂှ်ဒုၚ်သွဴ—။” (ဇ—၃၄၄။ အစွောံ။) = “လေးယောက်သောသူတို့သည် ကျိန်ကြကုန်၏။”')
,(7090,3,4,'ဟောကိန်းထုတ်ခြင်းခံရသည်။ (?)','“ဗောဓိသတ်ဒှ်မၞိဟ်တုဲ ဒုၚ်သွာပ်ဗမၞးဘာရဇကုမဒှ်ကျာ်။” (သၠပတ်ရာဇာဓိရာဇ်) = “ဘုရားလောင်းသည် ဖွားမြင်ပြီးနောက် မိမိဘုရား ဖြစ်မည်ဟု ပုဏ္ဏား၏ဟောကိန်းထုတ်ခြင်းခံရ၏။”')
,(7091,3,4,'အခွန်ဆောင်သည်။','“ဗ္ဂဲမွဲကၠုၚ်ရပ်စကၞိ ကၞိဟီုကဵုဗ္ဂဲဂှ်ရ ‘မရသ္စအဲ မွဲဝါမသ္ဂောံစရ၊ မရဗလးအဲ ဖျုန်ဂကောံအဲမစ သၟဟ်ဂလိုၚ် အဲသ္ဒုၚ်အခေါန်မရ။’—” (သၠပတ်ရာဇာသာန်) =“ကြောင်တစ်ကောင်က ကြွက်ကိုလာဖမ်းစားရာ ကြွက်သည်ကြောင်အားပြော၏၊ ‘သင်ငါ့ကိုစားပါက တစ်ကြိမ်သာသင်စားရမည်။ ငါ့ကိုသင်လွှတ်ပါက ငါစားမည့်အသားထဲမှ တစ်ဝက်ကို သင့်ကိုငါအခွန်ဆောင်ပါမည်။’—”')
,(7092,3,4,'တာဝန်ခံသည်။ တာဝန်ယူသည်။','“တၞးတာပဿ၊ ဂၠးကာယျအဲ။ လုပ်ဒုၚ်အတာ၊လွဳပရာမၚ်မွဲ။” (လိက်သုဝဏ္ဏသာံ။ မာံသေၚ်။) = “ရသေ့ကိုယ်စား ငါ့ကိုယ်ကာယဖြင့် တာဝန်ယူ၍ မွေးမြူစောင့်ရှောက်ပါမည်။”')
,(7092,3,4,'တာဝန်ခံသည်။ တာဝန်ယူသည်။','“သောၚ်လဟီုဂှ်၊ ဒှ်ဍာံညိဟာ။ ဒှ်ဍာံပဂွိၚ်၊ သၟိၚ်ဒုၚ်အတာ။” (လိက်သုဝဏ္ဏသာံ။ မာံသေၚ်။) = “ထိုအပြောသည် အမှန်ဖြစ်ပါမည်လော။ အမှန်ဖြစ်ပါမည် မစိုးရိမ်လင့်ဟု မင်းသည်တာဝန်ခံ၏။”')
,(7093,3,4,'အတိုင်ပင်ခံသည်။ အကြံဉာဏ်ရယူသည်။','“အမှုဇဇၞော်ကီုသွတ်ကီု လုတ်ကီုဒးကီုဂှ် မအံက်တၠအဲ ဒုၚ်အတိုၚ်အဗၚ် ချပ်စၚ်ခြၚ်ကဵုအဲဖအိုတ်ရောၚ်—။” (သၠပတ်သုရသာ) = “အမှုကြီးငယ်ကို၄င်း အမှားအမှန်ကို၄င်း သင့်ခမည်းတော်သည် ငါ့အား အတိုင်ပင်ခံဆွေးနွေးတိုင်ပင်မြဲဖြစ်၏။”')
,(7094,3,4,'ဒဏ်ခံသည်။ အနွံအတာခံသည်။ ဖိစီးနှိပ်စက်မှုကို ခံရသည်။','“တြုံဏအ်သုၚ်အရက်ဝေၚ်ၛၚ် ပၠေၚ်ဗဒိုက်တဴဒၟံၚ်အဲဂှ် အဲဒုၚ်အဘဳဟွံမာန်ရ။” = “ဤယောကျာ်းသည် အရက်သောက်လောင်းကစား၍ ကျွန်မအား ဖြုန်းတီးနေသည်ကို ကျွန်မအနွံအတာ မခံနိုင်တော့ပါ။”')
,(7095,3,4,'ဝန်ခံကတိပေးသည်။ အာမခံသည်။ (ပါဠိ—အာမ၊ မန်—ဒုၚ်)','“သၟိၚ်တလဍုၚ်၊ဒုၚ်လဝ်အာမ။” (လိက်သုဝဏ္ဏသာံ။ မာံသေၚ်။) = “ပြည့်ရှင်မင်းသည် အာမခံထား၏။”')
,(7096,3,4,'ဟုတ်ပေ၏ဟုဝန်ခံသည်။ နာခံမည်ဟုဝန်ခံသည်။','“အမာတ်တအ်ရ၊ အဂ္ဂသေဏာ။ ဂဇအ်ဒစိုၚ်၊ ဒုၚ်အာမန္တာ။” (လိက်ဇိဝှစက္က) = “အမတ်သေနာပတိတို့သည် ဦးညွတ်ထိုင်ကာ (မင်းအမိန့်တော်ကို) နာခံမည်ဟုဝန်ခံကုန်၏။”')
,(7097,3,4,'အကုန်ခံသည်။',NULL)
,(7098,3,4,'အမွေခံသည်။',NULL)
,(7099,3,4,'ကျင်သည်။','ဇိုၚ်ဒေၚ် = ခြေထောက်ကျင်သည်။')
,(7099,3,4,'ကျင်သည်။','(န) ဒိုင်လူကြီး။')
,(7099,3,4,'ကျင်သည်။','“(ပ္ဍဲပေဲါလက်ပၠုဲဂှ်) ညးစာဲအဲစာဲ၊ သြာဲတိတ်သာသာ။ ထုဲဓရုဲအာ၊ ဒေၚ်ၜါပြာ်တံၚ်။” (လိက်ဗြရတ်ဣဏၚ်ကၚ်ရဳ) = “လက်ဝှေ့ပွဲ­ တစ်ယောက်တစ်ပြန်စီ ထိုးကြိတ်ကြရင်း ဖြည်းဖြည်းသာသာ ခွာထွက်၏၊ လုံးထွေးသွားကြပြန်သောအခါ ဒိုင်လူကြီးနှစ်ဦးတို့က ဆွဲ၍ဖျဉ်လိုက်၏။”')
,(7100,3,4,'မှိုင်ငေးသည်။ ကြံမှိုင်သည်။','“(ပံက်စၞာဲဂှ်) အာစိုပ်လစ ပ္ဍဲလအိတ်ဍာ်သ္ကဲသြၚ် ချပ်စံၚ်တူဒေၚ်ဒၟံၚ်တုဲ တန်ဒၟံၚ်ရ။ ကဂမၠိုၚ်ညာတ် ‘ယွံနာဲပိုဲ၊ မူကသပ်ချပ်ဟွံစဴစိုတ်တုဲ မစံၚ်တူမဒေၚ်ဒၟံၚ်ရော’ ကဂမၠိုၚ်သၟာန်။” (ဇ—၃၈။ အစွောံ။) = “ဗျိုင်းစဉ်းလဲသည် ရေအိုင်သို့သွားရောက်၍ကမ်းနံဘေးရေစပ်­ ပူပန်းငေးမှိုင်လျက် ကြံ၍နေ၏။ ငါးများမြင်၍ ‘အရှင်ဗျိုင်း၊ အဘယ်အကြံ ဖြင့် စိတ်ကြံတိုင်းမဖြစ်၍ ပူပန်ငေးမှိုင်လျက်နေပါသနည်း’ ဟုငါးများမေး၏။”')
,(7101,3,4,'တွေဝေငေးမှိုင်သည်။ စိတ်ပျက်၍မှိုင်သည်။','“ယွံကောန်အဲ၊ — မူရဴဟိုတ်မွဲတုဲ ကောန်ဂ္ဇံဒေၚ်လ္ၚုၚ်တဴရော။” (ဇ—၄၃၅။ အစွောံ။) = “ချစ်သား၊ သင်သည် မှိုင်လျက်သာလျှင် အဘယ့်ကြောင့်နေသနည်း။” (ညောင်ကန်)')
,(7101,3,4,'တွေဝေငေးမှိုင်သည်။ စိတ်ပျက်၍မှိုင်သည်။','“ဍေံဒဴအာ ဂၠာဲဟွံဂွံတုဲရအဴ” အမာတ်တံဂး။ ပြောဟိတ်အစာသၟိၚ်မိၚ်တုဲ ချပ်ဒေၚ်ၚုၚ်ဒၟံၚ်—။ (ဇ—၄၈၁။ အစွောံ။) = “သူထွက်ပြေးသွားလေပြီ၊ ရှာ၍မရတော့ပါ” ဟု အမတ်တို့ဆိုသည်ရှိသော် မင်းဆရာပုရောဟိတ်ကြား၍ေၚးမှိုင်တွေဝေလျက်နေ၏။')
,(7101,3,4,'တွေဝေငေးမှိုင်သည်။ စိတ်ပျက်၍မှိုင်သည်။','“မုက်မတ်ဟွံမြဴ၊ ညံၚ်ပ္ကဴဇြကှ်။ ဂဇံဒေၚ်လ္ၚုၚ်၊ ပုၚ်စဟွံဒှ်။” (လိက်သၟိၚ်အသး။ နန္ဒသာရ။) = “မျက်နှာမလန်း ပန်းကဲ့သို့ညှိုးခြောက်၏။ ထိုင်ငေးမှိုင်လျက် ထမင်းမစားနိုင်။”')
,(7102,3,4,'‘သ္ဒေၚ်သ္ဒ’ ရှု။',NULL)
,(7103,3,4,'ကြံမှိုင်သည်။ငေးငိုင်သည်။ နှလုံးမသာမယာဖြစ်သည်။','“သၟိၚ်ကျအာ (ပး) တုဲ သၟိၚ်စံၚ်တူဒေၚ်ဗျောံတဴရ။” (ဇ—ဝိဓုရ။ အစွောံ။) = “—မင်းသည် အန်ရှုံးခဲ့သော် ပြင်းစွာနှလုံးမသာဖြစ်၏။” (မင်းပူးဦးသြဘာသ)')
,(7103,3,4,'ကြံမှိုင်သည်။ငေးငိုင်သည်။ နှလုံးမသာမယာဖြစ်သည်။','“ဗန်တဲဒေၚ်ဗျောံ၊ သ္ၚောံပူဆာ။” (လိက်နဲယသမုဒ္ဒြဳ။ အစွောံ။) = “လက်ပိုက်ကြံမှိုင်လျက် စိုးရိမ်ပူပန်၏။”')
,(7103,3,4,'ကြံမှိုင်သည်။ငေးငိုင်သည်။ နှလုံးမသာမယာဖြစ်သည်။','“ဗန်တဲဒေၚ်ဗျောံ၊ ဒှ်တဴဟောံဇြ။” (လိက်ဗောဓိသတ်စှ်။ ပဏ္ဍိတ။) = “လက်ပိုက်ကြံမှိုင်လျက် နှလုံးမသာမယာဖြစ်၏။”')
,(7103,3,4,'ကြံမှိုင်သည်။ငေးငိုင်သည်။ နှလုံးမသာမယာဖြစ်သည်။','“ဒေၚ်ဗျောံထ္ၜောအ်၊ စွံစိုတ်ရောတန်။” (လိက်ကောန်ဂစေံပိ။ နာဲဗျူ။) = “တွေဝေငေးငိုင်ကြံမှိုင်၍ စိတ်ကိုတည်ငြိမ်အောင် မထားနိုင်ဘဲရှိ၏။”')
,(7103,3,4,'ကြံမှိုင်သည်။ငေးငိုင်သည်။ နှလုံးမသာမယာဖြစ်သည်။','“နာဲပဟောံဇြ၊ နာဲပဒေၚ်ဗျောံ။” (လိက်သောဝိန်ဇဲယ။ မာံရောဂေါ။) = “သင်မပူဆွေးလေနှင့်၊ သင်မကြံမှိုင်လေနှင့်။”')
,(7104,3,4,'တွေဝေငေးမှိုင်သည်။ ကြံမှိုင်သည်။ စိတ်ထိခိုက်သည်။','“ယွံကဂမၠိုၚ်၊အဲချပ်စံၚ်တူကဵုမၞးတံညးဂမၠိုၚ်တုဲ အဲမဍောၚ်စိုတ် မဒးဒေၚ်သၠၚ်ဒၟံၚ်ရောၚ်” ပံက်စၞာဲဂး။ (ဇ—၃၈။အစွောံ။) = “အိုငါးအပေါင်းတို့၊ ငါသည် သင်တို့အတွက် တွေးကြံပူပန်လျက် စိတ်မောသည် ဖြစ်၍ ငေးမှိုင်နေရခြင်းဖြစ်ပါသည်” ဟုဗျိုင်းစဉ်းလဲဆို၏။')
,(7104,3,4,'တွေဝေငေးမှိုင်သည်။ ကြံမှိုင်သည်။ စိတ်ထိခိုက်သည်။','“ညံၚ်ကၞုဲသမၠီု မဟုတ်အာနူသတ်မာ်မဂၠိုၚ်ဂှ်တုဲ ကၞုဲမဒးဒေၚ်သၠၚ်တဴရ။” (ဇ—၁၇၆။ အစွောံ။) = “များစွာသောကုလားပဲမှ ဆုံးရှုံးသွားရသော မိုက်မဲသောမျောက်ကဲ့သို့ တွေဝေငေးမှိုင်နေရ၏။”')
,(7104,3,4,'တွေဝေငေးမှိုင်သည်။ ကြံမှိုင်သည်။ စိတ်ထိခိုက်သည်။','“မိတိုန်စိုပ်သြၚ်၊ ဒေၚ်သၠၚ်စိတ္တ။ ဟွံညာတ်ကောန်ဍောတ်၊ ရမတ်ဖျဖျ။ အသီဗိုတ်ဏာ၊ တူအကာသ။” (လိက်ပတ္တစာရဳ။နာဲထဝ်စိုပ်။) = “မယ်ပဋာစာရီသည် ကမ်းခြေသို့ရောက်လေသော် သားငယ်ကို စွန်ချီသွားသ ဖြင့် သားငယ်ကိုမမြင်ရ၍ စိတ်ထိခိုက်ကြံမှိုင်ကာ မျက်ရည်ဖြိုင်ဖြိုင်ကျ၏။”')
,(7105,3,4,'ကြံမှိုင်သည်။ တွေဝေငေးမှိုင်သည်။','“ကြောတ်ထဝ်မွဲဟေၚ်၊ရေၚ်မတ်နာနာ။ ဟဳဒစးကၠုၚ်၊ ဒေါဝ်ဖၞုၚ်ဂၚ်္ဂါ။ ညးဂမၠိုၚ်ရော၊ ၜိၚ်တိတ်ဟောဒြာ။ ဗက်ဟံၚ်ဟွံဂွံ၊ဒေၚ်သ္ၜောံသိၚ်သာ။” (လိက်သောဝါနနဟောၚ်) = “ကျောက်မျက်အမျိုးမျိုး စီခြယ်ထားသောရွှေအိုးငယ်သည် ရေၚန်မြစ်လယ်­ မျောဆန်တက်လာရာ လူအများသည် ဆူညံစွာကူးထွက်သွားကြ၏။ လိုက်ဆယ်၍မရသဖြင့် ကြံမှိုင်လျက် နှလုံးမသာမယာရှိကုန်၏။”')
,(7106,3,1,'နတ်ကတော်။ နတ်ဝင်မ။','“ဒေါၚ်ဗြဴဇၞော်မွဲဂှ် (ကောန်တြုံသၟိၚ်) ကဵုအာကော်နၚ်တုဲ—။” (ဇ—၁၂၆။ အစွောံ။) = “မင်းသားသည် တစ်ယောက်သော နတ်ကတော်မကြီးကို ခေါ်လာစေ၍—။”')
,(7107,3,1,'နတ်ကတော်။ နတ်ဝင်သည်။','“ကော်နၚ်ဒေါၚ်ယာ ကၠုၚ်ဗမ္ၚိက်ဗမ္ၚာဲဒၟံၚ်ပၠန်။” (သၠပတ်သတိပထာန်) = “နတ်ဝင်သည်တို့ကို ခေါ်ဆောင်လာပြီး နတ်ကနားပေးနေပြန်၏။”')
,(7107,3,1,'နတ်ကတော်။ နတ်ဝင်သည်။','“သၟာန်ဒေါၚ်ယာဟွံဗၠေၚ်၊ လၟေၚ်လ္ပအ်သာ်ဝွံမှာ။” (လိက်သၠပတ်သၟိၚ်ပဿိုန်) = “ဤသို့သောအိပ်မက်ဖြစ်စဉ်ကို မနှေးနတ်ဝင်သည်အားမေး၏။”')
,(7107,3,1,'နတ်ကတော်။ နတ်ဝင်သည်။','“ဇတဝ်ဇကု၊ အနုဒေါၚ်ယာ။” (လိက်သောဝိန်ဇဲယ။ မာံရောဂေါ။) = “နတ်ဝင်သည်လို ကိုယ်တုန်နေ၏။”')
,(7108,3,4,'ခုန်သည်။ ခုန်ကျော်သည်။','“ချေံဂှ် ဒံၚ်လုပ်အာဒၞးဂှ်ရ။” = “ထိုမြင်းသည် စည်းရိုးကိုခုန်ကျော်၍ ဝင်သွားသည်။”')
,(7109,3,4,'ခုန်ပေါက်သည်။','“ကောန်ၚာ်တအ် ဝေၚ်ဒံၚ်စလာ်ဒၟံၚ် ပ္ဍဲဍာ်ဗြဲရ။” = “ကလေးများသည် မိုးရေထဲတွင် ခုန်ပေါက်ကစားနေကြသည်။”')
,(7110,3,4,'ယောၚ်ချာချာဖြစ်သည်။ ယောၚ်လည်လည်ဖြစ်သည်။','“သၟတ်မန်တအ်လ္ၚဵု မူဂွံကၠောန်ဂှ် ကေတ်ဟွံဒးတုဲ ဒံၚ်ယံၚ်အိုတ်ဒၟံၚ်အခိၚ်ကဵု ကလောန်ဟွံမွဲကဵုဂုန်ဖဵုတံဂှ်ရ။” = “အချို့မွန်လူငယ်များသည် ဘာလုပ်ရမည်ကိုမသိ၍ ယောင်လည်လည်ဖြင့် အကျိုးမရှိသောအလုပ်များတွင် အချိန်ဖြုန်းနေကြသည်။”')
,(7111,3,1,'ဘုမ္မတီးငှက်။ သင်တိုင်းဝတ်ငှက်။ ငှက်ကြီးဒုံးစပ်။ (ပါဠိ—ကၚ်္က)',NULL)
,(7112,3,1,'သပိတ်လွယ်ငှက်။ (ပါဠိ—ခဥ္ဇရဳဋ','ခဥ္စရိတ')
,(7112,3,1,'သပိတ်လွယ်ငှက်။ (ပါဠိ—ခဥ္ဇရဳဋ','ပတ္တကဏူဌ)')
,(7113,3,1,'ငှက်ကြီးဝံပို။ ထီးလှိုင်ငှက်။ ( a pelican)',NULL)
,(7114,3,1,'ရုံးဖြူပင်။','(ကြိ) ဓါးနှင့်ထစ်သည်။ ဓါးနှင့်ထစ်ရာပေးသည်။')
,(7114,3,1,'ရုံးဖြူပင်။','“ညံၚ်ညးမဒတ်ဆုသၜိုတ်ကီု။” (သၠပတ်သတိပထာန်) = “အစေးရှိသောသစ်ပင်ကို ဓါးနှင့်ထစ်သကဲ့သို့။”')
,(7115,3,4,'ကျေးဇူးကန်းသည်။ ကျေးဇူးချေဖက်သည်။','“ပူဂဵုမွဲ နဂလာန်မစၞာဲ လှန်ပတ်ဒြပ်ညးတုဲ ပွဒတ်ကၠေံဂုန်ညးပၠန်။” (သၠပတ်စှ်ၜါရာသဳ) = “သူတစ်ပါးဥစ္စာကိုလှည့်စားဖြားယောင်းယူ၍ သူတစ်ပါး၏ကျေးဇူးကို ချေဖျက်ပြန်သောသူ။”')
,(7116,3,10,'(န) တွေးခေါ်မြော်မြင်မှုပညာရပ်။ ဒဿနိကဗေဒ။',NULL)
,(7117,3,4,'ပုတ်သည်။ ရိုက်သည်။','“ကဂျိုၚ်ဂျိုၚ်ဂှ် ဍေံဒါတ်ကဵုအပၠာမြတုဲ ဂစိုတ်ကၠေံရ။” =“ငါးအရှင်ကို ဓါးအပြားဖြင့် သူရိုက်၍သတ်ပစ်သည်။”')
,(7117,3,4,'ပုတ်သည်။ ရိုက်သည်။','“(လၟာန်မာန်နုၚ်ထၟာဲတံဂှ်တုဲ) ကၠာနူဍေံဟွံဂွံကှ်ဂှ် ဍေံတက်ဒါတ်ဖျိပ်ပၠန်ရ။” (ဇ—၄ဝ၆။ အစွောံ။) = “အိုးသမားသည် အိုးတို့ကိုလုပ်ပြီးလျှင် မခြောက်သေးမီ စေ့အောင်ရိုက်ပုတ်ရပြန်၏။”')
,(7117,3,4,'ပုတ်သည်။ ရိုက်သည်။','“ဒဇဲဒမာတ်၊ သောန်ဒါတ်ၜုန်မြ။” (လိက်သောဝိန်ဇဲယ။ မာံရောဂေါ။) = “လက်သမား၊ ပန်းပဲတို့သည် ဓါး၊ ဓါးမတို့ကို သွန်းထုပြုလုပ်၏။”')
,(7118,3,4,'(အံ့သြ၍) ရင်ဘတ်တီးသည်။',NULL)
,(7119,3,10,'(နဝိ) မျက်မှောက်ဖြစ်သော၊ မျက်မြင်ဖြစ်သော။ ဒိဋ္ဌဖြစ်သော။',NULL)
,(7120,3,5,'မျက်ဝါးထင်ထင်။ မျက်မှောက်ဒိဋ္ဌ။','“ဗြဴစိဉ္စမာဏဴဂှ် ဟိုတ်နူမှာအာဒုဟ် ပ္ဍဲကျာ်တြဲတုဲ ပ္ဍဲဒိဋ္ဌဂတမတ်ဂှ်ဟေၚ် တိၚိတ်ဖျေံဏာရ။” (သၚ်္ခါရဘေဒနဳ။ ဝိန္ဒသာရ။) = “စိဉ္စမာဏသည် မြတ်စွာဘုရားရှင်အား ပြစ်မှားကျူးလွန်မိသောကြောင့် မျက်မှောက်ဒိဋ္ဌ­ပင် မြေမျိုသွား၏။”')
,(7121,3,10,'(ကြိဝိ) မျက်မှောက်ထင်ထင်။ ဒိဋ္ဌဓမ္မ။',NULL)
,(7122,3,10,'(န) ၁။ အမြင်။ အယူအဆ။','၂။ မှားသောအယူကို ယူသောသူ။ ဒိဋ္ဌိ။')
,(7123,3,16,'(န) ၁။ လမ်းကြောင်း။','“ဒိဋ္ဌဳဍာန်စက်ဂိတုတ္ၚဲၜါဂှ် ဍေံစၞောန်ထ္ၜးတဴကုအဲရ။” (ဇ—၄၄၉။ အစွောံ။) = “နေလအစုံတို့၏ သွားရာလမ်းကြောင်းသည် ငါ့အားထင်ရှား၏။”')
,(7123,3,16,'(န) ၁။ လမ်းကြောင်း။','၂။ ရက်။ လဆန်းလဆုတ်ရက်။ (a lunar day)')
,(7123,3,16,'(န) ၁။ လမ်းကြောင်း။','“ကောန်တြုံသၟိၚ်ဂှ် ပ္ဍဲတ္ၚဲဒိတ္ထဳနက်သတ်မခိုဟ်ဂှ်အ္စာကဵုကတ်ကွတ်ရ။” (ဇ—၂၅၂။ အစွောံ။) = “ဆရာသည် ရက်ကောင်းနက္ခတ်ကောင်းဖြင့်မင်းသားအား အတတ်ကိုသင်စေ၏။”')
,(7123,3,16,'(န) ၁။ လမ်းကြောင်း။','“အဲကၠုၚ်လၟုဟ်ဝွံ ဒိဋ္ဌဳနက်သတ်ခိုဟ်ရောၚ်။” (ဇ—၄၇၅။အစွောံ။) = “ငါလာသောခုအခါသည် နက္ခတ်ကောင်းသော (မင်္ဂလာရှိသော) နေ့တည်း။”')
,(7123,3,16,'(န) ၁။ လမ်းကြောင်း။','“ရံၚ်ဒိဋ္ဌဳနကျှတ်တုဲ—။” (ဇ—၄၇၉။ အစွောံ။) = “နေ့ရက်နက္ခတ်ကို ကြည့်သည်ရှိသော်—။”')
,(7123,3,16,'(န) ၁။ လမ်းကြောင်း။','“(သၟိၚ်ကျိုၚ်ကျဝ်တုဲ မတိတ်ကၠုၚ်ဂှ်) ညံၚ်စၠးဂိတုပုဏ္ဏမဳ မဍိုက်ပေၚ်တဴကဵုဒိတ္ထဳစှ်သုန်မမံက်တုဲ ရဴမရာၚ်ဆာဲ ပ္ဍဲဒေါဝ်သၟန်သၞံၚ်နက်သတ်ဂမၠိုၚ်ကီု။” (ဇ—၅၂၇။ အစွောံ။) = “တန်ဆာဆင်၍ ထွက်လာသောမင်းသည် လဆန်းဆဲ့ငါးရက်လပြည့်ဝန်းက ကြယ်နက္ခတ်အပေါင်းတို့၏အလယ်­ တင့်တယ်နေသကဲ့သို့။”')
,(7123,3,16,'(န) ၁။ လမ်းကြောင်း။','“ပါတ်ဗိဇ္ဇနာ၊ လၟေၚ်နာဍဳ။ တရဴစှ်ောသ္ကဲ၊ ပ္ညပ်မွဲဒိတ္ထဳ။ ပိစှ်ောဒိတ္ထဳ၊ ပ္ညဳမွဲဂိတု။” (လိက်ဗောဓိသတ်စှ်။ ပဏ္ဍိတ။) = “ပါတ်၊ ဗဳဇနာ၊ နာရီစဉ်အရ (ရေတွက်သော်) နာရီခြောက်ဆယ်သည် တစ်ရက်ဖြစ်၍ ရက်သုံးဆယ်သည် တစ်လဖြစ်၏။” (မှတ်ချက်။ နာရီ ခြောက်ဆယ်တစ်ရက်ဆိုသည်မှာ ရှေးသုံးနာရီတည်း။')
,(7123,3,16,'(န) ၁။ လမ်းကြောင်း။','မွဲဒိတ္ထဳ = တစ်ရက်။)')
,(7124,3,3,'ကြီးသော။','“ရံၚ်စမ်တေတေံ ဇြုံမွဲဒုတ်။” = “ဟောဟိုမှာကြည့်စမ်း၊ မြွေတစ်ကောင်အကြီးကြီး။”')
,(7125,3,1,'ဒီးဒုတ်ငှက်။','“ဒုတ်ဒူအဟုက်၊ အောပ်ဂၠုက်ပ္ဍဲဗိုၚ်။” (လိက်ဗြရတ်ဣဏၚ်ကၚ်ရဳ) =“ဒီးဒုတ်ငှက်သည် ကိုင်းပင်များကြားတွင် ပုန်းအောင်းနေ၏။” (အဟုက် = ?)')
,(7126,3,4,'ကဲ့ရဲ့သည်။ အပြစ်ဆိုသည်။','“မာတ်သၟိၚ်ကၞပ်ရော၊ ဒုတ်ဒေါကမၠေဝ်။” (လိက်ဗောဓိသတ်စှ်။ ပဏ္ဍိတ။) = “ဘုရင်စကားမဆို ဆိတ်ဆိတ်နေသဖြင့် (မောင်းမတို့သည်) အပြစ်ဆိုဆူညံလျက်ရှိကြ၏။”')
,(7126,3,4,'ကဲ့ရဲ့သည်။ အပြစ်ဆိုသည်။','“လိုက်တအ်ဒုတ်ဒေါ၊ ညးစောဒနာ။” (လိခ်မဒံက်ခေဝ်) =“လူအပေါင်းတို့သည် ပြောဆိုကဲ့ရဲ့ကုန်၏။”')
,(7126,3,4,'ကဲ့ရဲ့သည်။ အပြစ်ဆိုသည်။','“သၟိၚ်တုန် တၞဟ်နသၟိက်ဂွံဂိုၚ်ပ္တိုန်သၟတ်ဗြဴပၠန်လေဝ် ဖေက်ညးဒုတ်ဒေါစောဒနာ။” (ဇာတ်ပဥ္စပါပဳ။ နာဲမန်ၜိုပ်ထဝ်။) = “မင်းသည် ထိုမိန်းမပျိုကို ဆောင်ယူတင်မြှောက်လိုသော်လည်း လူအများအပြစ်ဆိုကဲ့ရဲ့မည်စိုး၏။”')
,(7126,3,4,'ကဲ့ရဲ့သည်။ အပြစ်ဆိုသည်။','“အမာတ်ဒဴဗညာ ဒုတ်ဒေါတဴအိုတ်ရ။ တီညးစောဒနာဍေံတုဲ—။” (ပြကိုဟ်နဝဗျတ္တိ) = “အမတ်မှူးကြီးမတ်ကြီးတို့ ဆိုမြည်ကဲ့ရဲ့ကြကုန်၏။ သူတစ်ပါးတို့ အပြစ်ဆိုသည်ကို သူကြား၍—။”')
,(7126,3,4,'ကဲ့ရဲ့သည်။ အပြစ်ဆိုသည်။','“စောန်စိုတ်ဒုဒ္ဒေါ၊ ဟီုစောဒနာ။” (လိက်ဓနဥ္ဇယျကုမ္မာ။ အစွောံ။)')
,(7127,3,5,'တိုးတိုးတိတ်တိတ်။ တီးတိုး။','“ဒုတ်ဒုတ်ဒီုဒီု၊ ဂၠာဲဟီုဒက်ဒေါန်။” (ဝၚ်ပ္တန်ဍုၚ်ပဒုမ်ဋ္ဌာနဳ) = “တိုးတိုးတိတ်တိတ် ရှာကြံပြောဆိုမြည်တမ်း၏။”')
,(7127,3,5,'တိုးတိုးတိတ်တိတ်။ တီးတိုး။','“အကြာဍုၚ်ကွာန်၊ ဂလာန်ဝါစဳ။ ဒုတ်ဒုတ်ဒီုဒီု၊ ညးဟီုတဴဇဳ။” (လိက်ပတ္တစာရဳ။ နာဲထဝ်စိုပ်။) = “ထိုအကြောင်းကိုရပ်ရွာအကြား­ လူအများတီးတိုးပြောကြကုန်၏။”')
,(7127,3,5,'တိုးတိုးတိတ်တိတ်။ တီးတိုး။','“သာ်ဝွံဒုတ်ဒုတ်ဒီုဒီု ညးဟီုကဵုအဲ အဲဟီုကဵုညးအိုတ်ရ။” (သၠပတ်စန္ဒဝတဳ) = “ဤသို့တိုးတိုးတိတ်တိတ် အချင်းချင်းပြောဆိုကြကုန်၏။”')
,(7127,3,5,'တိုးတိုးတိတ်တိတ်။ တီးတိုး။','“ဒုတ်ဒုတ်ဒီုဒီု၊ ကသေဲဟီုအာ။” (လိက်လက္ခဏပိ) = “နှစ်ကိုယ်ကြားတီးတိုးပြောဆိုသည်။”')
,(7128,3,4,'တီးတိုးပြောသည်။','“ပရောညးၜါဂှ် ထောံရၚ်သ္ကအ်ဂှ် ညးဟီုဒုတ်ဒီုဒၟံၚ် အလုံကွာန်မွဲရ။” = “သူတို့နှစ်ဦးပြတ်စဲသည့်အကြောင်းကို တစ်ရွာလုံးက တီးတိုးပြောဆိုနေကြသည်။”')
,(7128,3,4,'တီးတိုးပြောသည်။','“ဂလာန်ဒုတ်ဒီု၊ ဟီုဇီုသၟဟ်သၟန်။” (လိက်သၚ်ဂဒါ။ သဳလဝန္တ။) = “အချင်းချင်းညီညွတ်စွာ တီးတိုးစကားဆိုကြ၏။”')
,(7128,3,4,'တီးတိုးပြောသည်။','“တ္ၚေက်သာရိကာ၊ ပူပါဗဂီု၊ ဒုတ်ဒီုထဥ။” (ကောန်ဖေန်ကောန်ၛၚ်) =“ကျေး၊ သာရိကာ၊ ချိုး၊ ချိုးစိမ်းငှက်တို့သည် အတူစုရုံးလျက် တီးတိုးဆိုမြည်နေကြကုန်၏။”')
,(7129,3,10,'(န) သီလမရှိသောသူ။ အကျင့်ယုတ်သောသူ။ ဒုဿီလ။','“သမ္ဘာဥပ္ပးဂှ် ဒှ်ဒၟံၚ်ဒုဿဳလ ဟွံမွဲကဵုသဳလစာရဝတ်။” (ဇ—၆၄။ အစွောံ။) = “ထိုသီတင်းသည်၏မယားသည် ဒုဿီလ ဖြစ်၍ အကျင့်သီလမရှိ။”')
,(7129,3,10,'(န) သီလမရှိသောသူ။ အကျင့်ယုတ်သောသူ။ ဒုဿီလ။','“မၚ်ဗၠာဲဒုဿဳလဂမၠိုၚ်ဂှ် ဟိုတ်နူသဳလဇကုဟွံမွဲတုဲ ကောန်ဗြဴအ္စာ တၠစရာဲရုပ်ဂှ် ဟွံကလိဂွံရ။” (ဇ—၃ဝ၅။ အစွောံ။) = “ဒုဿီလလုလင်တို့သည် မိမိတို့၏သီလမရှိ ခြင်းကြောင့် ရုပ်အဆင်းရှင်ဖြစ်သော ဆရာ့သမီးကို မရကုန်။”')
,(7129,3,10,'(န) သီလမရှိသောသူ။ အကျင့်ယုတ်သောသူ။ ဒုဿီလ။','“ပူဂဵုဒုဿဳလတံဂှ်ကီု တမ္ၚာလၟတံဂှ်ကီု။” (ဇ—၃၅၆။ အစွောံ။) = “ဒုဿီလပုဂ္ဂိုလ်တို့ကို၄င်း တံငါ၊ မုဆိုးတို့ကို၄င်း။”')
,(7130,3,11,'(န) ၁။ ဒဏ်။ ကျရောက်သောဘေးအန္တရာယ်။ ဖိစီးနှိပ်စက်မှု။','ဘဲဒဏ်= ဘေးဒဏ်။')
,(7130,3,11,'(န) ၁။ ဒဏ်။ ကျရောက်သောဘေးအန္တရာယ်။ ဖိစီးနှိပ်စက်မှု။','၂။ ကျူးလွန်မိသောအပြစ်အတွက် စည်းကမ်းဥပဒေအရ ခံယူရသောအပြစ်။ဒဏ်။')
,(7130,3,11,'(န) ၁။ ဒဏ်။ ကျရောက်သောဘေးအန္တရာယ်။ ဖိစီးနှိပ်စက်မှု။','ဒဏ်သြန် = ငွေဒဏ်။')
,(7130,3,11,'(န) ၁။ ဒဏ်။ ကျရောက်သောဘေးအန္တရာယ်။ ဖိစီးနှိပ်စက်မှု။','ဒဏ်ထံၚ် = ထောင်ဒဏ်။ (ပါဠိ—ဒဏ္ဍ)')
,(7131,3,4,'၁။ ခုတ်စဉ်းသည်။','ဒန်ဖျုန် = အသားကိုခုတ်စဉ်းသည်။')
,(7131,3,4,'၁။ ခုတ်စဉ်းသည်။','၂။ မြည်တွန်သည်။')
,(7131,3,4,'၁။ ခုတ်စဉ်းသည်။','‘ဒေါန်’ ရှု။')
,(7132,3,4,'အကြောင်းမဲ့မြည်တွန်သည်။',NULL)
,(7133,3,1,'အပြစ်ဒဏ်။','“မဒးပ္ကီုပၠန်၊ ဒန်စန်ဟေၚ်ရ။ ပၠေဲကၠေံနူရး၊ မ္ၚးဋ္ဌာန။” (လိက်မာဃဒေဝါန်) = “ပြည်မှနှင်ထုတ်၍ အပြစ်ဒဏ်ပေးရမည်။”')
,(7134,3,11,'(န) ဒန္တဋ္ဌာန်။ (ဒန္တအက္ခရာများဖြစ်ရာ သွားအရပ်) (ပါဠိ—ဒန္တဋ္ဌာန)',NULL)
,(7135,3,4,'တည်းဖြတ်သည်။','ညးမဒါန်လိက် = စာတည်းဖြတ်သူ။ စာတည်း။')
,(7136,3,11,'(န) အလှူဒါန။',NULL)
,(7137,3,1,'ရေစက်။ ရှေးရေစက်။','“ဗောဓိသတ် ချိုန်မမိၚ်ပရိုၚ်လဟီုညးဂှ်ရ ဟိုတ်ဒှ်ဒါန်တမၠာ ဟိုတ်ဒှ်မိတ်ဒါန်ဂၠိုၚ်ကဵုဝါဂှ်ရ နူမိၚ်ဗက်စိုတ်စပ်အာ (ပ္ဍဲသၟတ်ဗြဴ) ရ။” (ဇ—၃၈၇။ အစွောံ။) =“ဘုရားလောင်းသည် သူတကာတို့၏ဆိုစကားကို ကြားသည်ရှိသော် အကြိမ်ကြိမ်ပေါင်းဖက်ဖူးသော ဖူးစာကြင်ဘက် ရှေးရေစက်ဖြစ်ခြင်းကြောင့် ကြားကြားချင်းပင် မိန်းမပျို­ တပ်မက်တွယ်တာသွား၏။”')
,(7137,3,1,'ရေစက်။ ရှေးရေစက်။','(သုဇာတာညာတ်တုဲ) သၟိၚ်အိန်ဂှ် အစောံဒှ်ဒါန်တမၠာ သံဝါသမွဲစွံတုဲ ဇြဟာန်ပဳတိသ္ဍိုက်စိုတ်ဂှ် လဴဂလီုဍိုက်ပ္ဍဲစိုတ်တုဲ “တြုံဝွံ ဒးဂၞပ်စိုတ်အဲရ” ဂးတုဲ ဇမန်ပ္ကဴဂှ် သၠိုက်စုတ်ပ္ဍဲကံအိန်ဂှ်တုဲ ရပ်ကံတဲသၟိၚ်အိန်ရ။ (ဇ—၃၁။ အစွောံ။) = သုဇာတာမြင်သည်ရှိသော် သိကြားမင်းသည်အတူတကွပေါင်းဖက်ဖူးသော ရှေးရေစက်ဖြစ်သောအစွမ်းဖြင့် ချစ်နှစ်သက်ခြင်းပီတိက စိတ်နှလုံးကို စေ့ဆော်လွှမ်းမိုးသည်ဖြစ်၍ “ဤယောကျာ်းသည်လျှင် ငါ့စိတ်အလိုကျဖြစ်၏” ဟုဆို၍ ပန်းကုံးကို သိကြားမင်း၏လည်­ စွပ်ထည့်ပြီးလျှင် သိကြားမင်း၏လက်ကောက်ဝတ်ကို ကိုင်၏။')
,(7138,3,5,'အလျှံညီးညီး။ တောက်လောင်လျက်။','“လ္ၚသၞစိုတ်၊ ပလိုတ်ဟွံမာန်၊ ဂဵုမံၚ်ဒါန်ဒါန်၊တူသၠာန်ရရဴ။” (လိက်မာဃဒေဝါန်) = “စိတ်အပူမီးသည် မငြိမ်းမသတ်နိုင်။ အလျှံညီးညီးတောက်လောင်၍ ပူလောင်ခံစားနေရ၏။”')
,(7138,3,5,'အလျှံညီးညီး။ တောက်လောင်လျက်။','“သ္ၚိကၟိန်ဝွံအဴ၊ ဂဵုတဴဒါန်ဒါန်။ ပၟတ်ရာဂစံၚ်၊ ပၠဒၟံၚ်သန္ထာန်။” (လိက်ဟတ္ထိပါလ။ အစွောံ။) = “အိမ်ထောင်မည်သည်ကား အလျှံညီးညီးတောက်လောင်နေသောရာဂမီးတည်း။”')
,(7138,3,5,'အလျှံညီးညီး။ တောက်လောင်လျက်။','“ဆအဲမွဲအဴ၊ ယာံတဴဒါန်ဒါန်။” (လိက်ပ္တံပါရမဳ။ အစွောံ။) =“ငါတစ်ကိုယ်တည်း သောကအလျှံညီးညီးဖြင့် ငိုးကြွေးနေရ၏။”')
,(7139,3,1,'အစဉ်အဆက်ပေးလာခဲ့သောအလှူဒါန။ လှူမြဲသောအလှူ။','“လအ်အဲမကလေၚ်စိုပ်ဂှ်ဒါန်ဝတ်အဲ လ္ပကဵုသ္ဂုတ် ပ္တုဲဒၟံၚ်လၟိုန်ညိ” ဗမၞးဂး။ (ဇ—၄၄၂။ အစွောံ။) = “ငါပြန်ရောက်သည့်တိုင်အောင် ငါ၏လှူမြဲသောအလှူကို မပြတ်လပ်ပါစေနှင့်။ အစဉ်ပေးမြဲပေးလော့။”')
,(7140,3,1,'ဆင်က။ ဆင်ပေါင်းက။',NULL)
,(7141,3,1,'ဝါး။','ဒုန်ကရာပ် = ညှပ်ဝါး။')
,(7141,3,1,'ဝါး။','ဒုန်ကရေက် = ဝါးခြမ်း။')
,(7141,3,1,'ဝါး။','ဒုန်ကလိ = ဝါးပိုးဝါး။')
,(7141,3,1,'ဝါး။','ဒုန်ဇလ = ကြခတ်ဝါး။')
,(7141,3,1,'ဝါး။','(ကြိ) လှော်ခတ်သည်။')
,(7141,3,1,'ဝါး။','ဒုန်ဂၠုၚ် = လှေလှော်သည်။')
,(7142,3,1,'ချောတိုင်။ ပျော်ပွဲရွှင်ပွဲတွင် တက်ရန် အဆီသုတ်လိမ်းထားသောဝါးပိုးတိုင်။',NULL)
,(7143,3,1,'ထိုးဝါး။ လှေရွေ့အောင် ထိုးစိုက်တွန်းကန်ရသောဝါးလုံး။','“အရိတ္တဗလေန၊ဟိုတ်နူအစောံဒုန်ဆူ။” (အဘိဓမ္မတ္ထဒဳပနဳ။ ဂရိုက်သာံ။) = “ထိုးဝါး၏အစွမ်းကြောင့်။”')
,(7144,3,1,'ခေါင်းအတွင်း လူသေအလောင်းဘေးနှစ်ဖက်­ ထားရှိသောဝါးခြမ်းပြား။',NULL)
,(7145,3,10,'(န) ရခဲခြင်း။ ဒုလ္လဘ။ (၁၊ ဘုရားပွင့်သည့်ကာလကို ရခဲခြင်း။ ၂၊ လူအဖြစ်ကို ရခဲခြင်း။ ၃၊ သဒ္ဓာပြည့်စုံမှုကို ရခဲခြင်း။ ၄၊ ရဟန်းအဖြစ်ကို ရခဲခြင်း။ ၅၊ သူတော်ကောင်းတရားနာရမှုကို ရခဲခြင်းဟူ၍ ဒုလ္လဘတရား ငါးပါးရှိသည်။)',NULL)
,(7146,3,1,'ကွပ်ပျစ်။ ညောင်စောင်း။ အိပ်ရာ။','“ဒေန်ထဝ်မတၟုဲတဴ နရတ်ထပှ်ပြကာ။” (ဇ—၉၅။အစွောံ။) = “ရတနာခုနစ်ပါးဖြင့်ပြီးသော ရွှေညောင်စောင်း။”')
,(7146,3,1,'ကွပ်ပျစ်။ ညောင်စောင်း။ အိပ်ရာ။','“ယွံအာစာ (ပြောဟိတ်) ၊ ညံၚ်တိုန်လတူဒေန်အဲဝွံရ” ဂၞကျာ်ဂး။ (ဇ—၁၂ဝ။ အစွောံ။) = “ပုဏ္ဏား၊ လာလော့၊ အိပ်ရာသို့တက်လော့” ဟုမိဖုယားဆို၏။ (ညောင်ကန်) ဒေန်ကၞပ်၊ ဒေန်ခၠၚ် (ကြိ)ငေးငိုင်သည်။')
,(7147,3,1,'ညောင်စောင်း။','“ကောန်ဒေဝတဴဗြဴလ္ၚဵုဂှ် ဂွံကဵုလဝ်ဒါန်ဇံၚ်ဒေန်သဝါန်—။” (ဇ—၂၄၃။ အစွောံ။) = “အချို့နတ်သမီးတို့သည် ခုတင်ညောင်စောင်းတို့ကို အလှူပေးခဲ့ရကုန်၏။”')
,(7147,3,1,'ညောင်စောင်း။','“ဒေန်သဝါန်ပ္ညဳ၊ ဖုန်ဒၞီသဗ္ဗ။” (လိက်သၟိၚ်ဇဲယဒတ္တ) = “အလုံးစုံသောညောင်စောင်း၊ မွေ့ရာ၊ခေါင်းအုံးများ။”')
,(7148,3,1,'ညောင်စောင်း။ အိပ်ရာ။','“ပ္ဍဲဒေန်သၞာမပြဲ—။” (ဇ—၃၈၂။ အစွောံ။) = “မြတ်သောအိပ်ရာ­။”')
,(7149,3,1,'၁။ လှံရှည်။','“ထပက်ကဵုဒေါန်ဗၞုဟ် ဂစိုတ်ကၠေံဍေံညိ။” (ဇ—၄၄၅။ အစွောံ။) =“သူ့အား လှံဖြင့်ထိုး၍ သတ်ပစ်လော့။”')
,(7149,3,1,'၁။ လှံရှည်။','“ဓဝ်ကာမဂုန်ဂှ် မတုပ်တဴရဴမုဟ်ဒေါန်သၞာ်သ္ကေက်ကီု။” (ဇ—၅၂၇။ အစွောံ။) = “ကာမဂုဏ်တို့သည် ထက်စွာသောလှံတံသန်လျက်ဖျားနှင့် တူကုန်၏။”')
,(7149,3,1,'၁။ လှံရှည်။','၂။ ဆင်၏ခြေ­ထိုးသောသံစူး။')
,(7149,3,1,'၁။ လှံရှည်။','(ကြိ) တောက်တီးမြည်တွန်သည်။ အပြစ်တင်ဆိုမြည်သည်။')
,(7149,3,1,'၁။ လှံရှည်။','“ကရေၚ်ဗျုတှ်ေကၠောန် မန်ဗျုတှ်ေဒေါန်။”= “ကရင်အိုလျှင် အလုပ်လုပ်၍ မွန်အိုလျှင် တောက်တီးမြည်တွန်သည်။” (မွန်စကားပုံ)')
,(7150,3,1,'ရှေးခေတ်လှံတံကိုင်မြင်းစီးသူရဲ။ (?)','“ဗဵုလဗး၊ သရာဲသခက်၊ ညးဂမံၚ်၊ ဒေါန်စမြင်။” (ဇ—ဝေသန္တဝ်။ အစွောံ။)')
,(7151,3,1,'၁။ အကာအရံ။ စောင်းရန်း။ စည်းရိုး။','ဒပ်ကၠအ် = ခြံစည်းရိုး။')
,(7151,3,1,'၁။ အကာအရံ။ စောင်းရန်း။ စည်းရိုး။','(ကြိ) ခြံစည်းရိုးကာရံသည်။')
,(7151,3,1,'၁။ အကာအရံ။ စောင်းရန်း။ စည်းရိုး။','“ကၠအ်သၞေဝ်ဂှ် ဒပ်ထောံညိ။” = “ဟင်းရွက်ခြံကို စည်းရိုးကာရံလိုက်ပါ။”')
,(7152,3,1,'တပ်။ တပ်စခန်း။','ဒပ်ပၞာန် = စစ်တပ်။')
,(7152,3,1,'တပ်။ တပ်စခန်း။','ဒပ်ယာ = ခံတပ်။')
,(7152,3,1,'တပ်။ တပ်စခန်း။','“သၟိၚ်အဿကလ္ၚောဝ်ဣသိတုဲ စဴအာဒပ်ဇကုရ။” (ဇ—၃ဝ၁။ အစွောံ။) = “အဿကမင်းသည် ရသေ့ကို ရှိခိုးပြီးနောက် မိမိတပ်စခန်းသို့ ပြန်သွား၏။”')
,(7153,3,12,'(န) ဒဗ္ဗဂုဏ်ဆေးကျမ်း။','“ဆဒပ်ဗျဂုန်ပြဲ၊ ဒှ်မွဲကၞပ်တုန်ကၠာ။” (လိက်လက္ခဏာဒိပ္ပဗိန္ဒော)')
,(7154,3,1,'နေရာ။ အရပ်။','“ဂြိုပ်ဗြေဟ်ဂြိုပ်က္ဍိုၚ်၊ ဇိုၚ်ဂၞိၚ်ဇိုၚ်လှာ။ ဂၠာဲကဵုဇဳဇပ်၊ အိုတ်ဇၟာပ်ဒပ်ယာ။” (လိက်ပဒုမဝတဳ) = “တောမြိုင်အကြား အင်းအိုင်အကြား အလုံးစုံသောနေရာအနှံ့ စုံလၚ်အောင်ရှာပါ။”')
,(7155,3,11,'(နဝိ) နတ်­ဖြစ်သော။ (ပါဠိ—ဒိဗ္ဗ)','မတ်ဒိပ် = နတ်မျက်စိ။ ဒိဗ္ဗစက္ခု။')
,(7155,3,11,'(နဝိ) နတ်­ဖြစ်သော။ (ပါဠိ—ဒိဗ္ဗ)','ကတောဝ်ဒိပ် = နတ်နား။')
,(7155,3,11,'(နဝိ) နတ်­ဖြစ်သော။ (ပါဠိ—ဒိဗ္ဗ)','တၟတ်ဒိပ် = သိမ်မွေ့သော နတ်၏အထိအတွေ့။')
,(7155,3,11,'(နဝိ) နတ်­ဖြစ်သော။ (ပါဠိ—ဒိဗ္ဗ)','ပုၚ်ဒိပ်၊ ရှ်ဒိပ်၊ စၞဒိပ် = နတ်သြဇာ။ နတ်သုဒ္ဓါ။')
,(7155,3,11,'(နဝိ) နတ်­ဖြစ်သော။ (ပါဠိ—ဒိဗ္ဗ)','ယာတ်ဒိပ် = နတ်­ဖြစ်သောအဝတ်။')
,(7155,3,11,'(နဝိ) နတ်­ဖြစ်သော။ (ပါဠိ—ဒိဗ္ဗ)','“ဍာ်ဒိပ်မပြဲပြဲဂှ် (ဂၞကျာ်) ဖုံဗလိုပ် (သၟာတွိၚ်) တုဲ မြမောဝ်ဒိပ်ဂှ် ကဵုဟုံဗြံက်ဗြတုဲ ယာတ်ဒိပ်ဂှ် ကဵုၜးဗိုက်ကျိုၚ်ကျဝ်တုဲဘောဇိုန်ဒိပ်တံဂှ် ကဵုဟာပ်စပပြဘိုက် ပ္ကဴမြမောဝ်ဒိပ်တံဂှ် ကဵုဗြံက်ဗြတုဲ ပ္ဍဲသၞာဒိပ်ဂှ် ကဵုသတိက်တုဲဂၞကျာ်ကဵုသၟာတဝိၚ် လှိၚ်တဴမွဲသၞာရ။” (ဇ—၃၆ဝ။ အစွောံ။) = “မိဖုရားသည် စောင်းသမားအားမြတ်သောနတ်­ဖြစ်သောရေကို ချိုးစေ၍ နတ်­ဖြစ်သောအမွှေးနံ့သာကို လိမ်းကျံစေ၍ နတ်­ ဖြစ်သောအဝတ်ကို ဝတ်ဆင်စေ၍ နတ်­ဖြစ်သောဘောဇဉ်တို့ကို သုံးဆောင်စေ၍ နတ်­ဖြစ်သောပန်းတို့ကို ပန်ဆင်စေ၍ နတ်­ဖြစ်သောအိပ်ရာ­ အိပ်စေ၍ မိဖုရားနှင့်စောင်းသမားသည်အတူမွေ့လျော်အိပ်စက်၏။”')
,(7156,3,4,'ညှို့သည်။ ဆွဲဆောင်သည်။','“ကောန်ဗြဴမာပိ လၟိတ်ဗဒှ်ရုပ်မကမွဲ ရုပ်မဒိပ်မဗ္ၜူကၠေံစိုတ်ညး—။” (ဇ—၁၃၂။ အစွောံ။) = “မာရ်နတ်သမီးသုံးယောက်တို့သည် သူတကာတို့၏စိတ်ကို ညှို့ယူဆွဲဆောင်ယစ်မူးစေတတ်သော ရုပ်အသွင်အမျိုးမျိုးကို ဖန်ဆင်း၏။”')
,(7157,3,4,'၁။ ချစ်ကြင်နာသည်။ ကရုဏာသက်သည်။','“ဂကောံဒေံဗြဴ၊ လအ်သ္ဂောံသၞဴဂၠိန်။ စိုတ်လၚ်ဂပူ၊ တူဂၠိုက်လနိန်။ သၟိက်ဂွံဆာန်ကၟိန်၊ ဂၠိန်သၞဴဒိပ်ဒဲါ။” (မာဃဒေဝါန်) = “ချစ်သူနှမနှင့်တကွ ကြည်ဖြူရောယှက်ခွင့်မရသေးခင် ချစ်သူမောင်၏စိတ်နှလုံး­ ပူဆွေးလောင်မြိုက်ဖိစီးနေ၍ချစ်ခင်ကြင်နာ ရောယှက်ပေါင်းဖက်ချင်လှပါပြီ။”')
,(7157,3,4,'၁။ ချစ်ကြင်နာသည်။ ကရုဏာသက်သည်။','“ယဝ်သ္ဂောံဒိပ်ဒဲါ၊ ကောကွာဲလမျီု။” (လိက်မေဃသန်) = “ချစ်နှမကို ချစ်ကြင်နာရပါမူ ချစ်သူမောင်အသက်ဆက်နှင်းပါမည်။”')
,(7157,3,4,'၁။ ချစ်ကြင်နာသည်။ ကရုဏာသက်သည်။','“ဆာန်ကၟိန်ဒိပ်ဒဲါ၊ က္ၜူမာဲလီၜန်။” (လိက်နဲယသမုဒ္ဒြဳ။ အစွောံ။) = “ချင်ခင်ကြင်နာ၍ ချစ်သူနှစ်ဦးတို့သည် အချင်းချင်းပူးယှက်ကာ သာယာကြည်နူးကြ၏။”')
,(7157,3,4,'၁။ ချစ်ကြင်နာသည်။ ကရုဏာသက်သည်။','၂။ ခိုလှုံသည်။ မှီဝဲဆည်းကပ်သည်။')
,(7157,3,4,'၁။ ချစ်ကြင်နာသည်။ ကရုဏာသက်သည်။','“ညးဇိုန်ဇကုသတိုန်စှ်ေဒိပ်ဒဲါဗ္ဒာဲဓလာဲ ယုတ်ပြဲလ္ပဂး၊ ညံၚ်သၞေဟ်ဇၞော်ဟွံရုဲစှ်ဂၠုၚ် မဒုၚ်ဗဒိုပ်ကီု ဒုၚ်ဗ္ဒာဲဂိုၚ်စွံသက်သဳ ပဗော်ကဵုဂေါဝ်ဆာဲညိ။” (ဇ—၁၄၃။ အစွောံ။) = “မိမိထံတွင် လာရောက်ခိုလှုံမှီခိုခစားသောသူအား ဆိပ်ကမ်းသည် လှေကိုမရွေးဘဲ ကမ်းအကပ်ခံသကဲ့သို့ အယုတ်အမြတ်မရွေးဘဲ ကောင်းမွန်စွာ လက်ခံသိမ်းဆည်းထားပါလေ။”')
,(7157,3,4,'၁။ ချစ်ကြင်နာသည်။ ကရုဏာသက်သည်။','“ယြဴသၟိၚ်မွဲမပိုၚ်တိ — မဂၠိုၚ်ကဵုလောဘ သၟိၚ်ဂှ်လေဝ် မလ္ပဒိပ်ဒဲါညိ။” (ဇ—၄၇၇။ အစွောံ။) = “ရေမြေကိုပိုင်စိုးသော အကြင်မင်းသည် လောဘရမ္မက်ကြီးပါက ထိုမင်းကိုလည်း မမှီဝဲမဆည်းကပ်လေနှင့်။”')
,(7157,3,4,'၁။ ချစ်ကြင်နာသည်။ ကရုဏာသက်သည်။','“ညးဇၞော်ဒးကၠုၚ်ဒိပ်ဒဲါကဵုဇကုရ။” (လောကသိဒ္ဓိ။ အစွောံ။) = “လူကြီးက မိမိထံလာရောက်ခိုလှုံရလိမ့်မည်။”')
,(7157,3,4,'၁။ ချစ်ကြင်နာသည်။ ကရုဏာသက်သည်။','“ပရိုက်ဂၠိုၚ်လောန်၊ တုပ်လက်သန်ဂြာဲ။ ဒေါဝ်ဝါလ္ၚု၊ သက္ကုဒိပ်ဒဲါ။” (လိက်ပရေၚ်ခန္ဓ) = “ဘေးရန်အလွန်များသော ကွင်းပြောင်အလယ်ရှိသမင်ပမာ ခိုလှုံရာမဲ့၏။”')
,(7158,3,10,'(န) ဒိဗ္ဗစက္ခု။ နတ်မျက်စိ။ နတ်မျက်စိကဲ့သို့ ထွင်းဖောက်မြင်နိုင်သောအဘိညာဉ်။',NULL)
,(7159,3,11,'(န) မကောင်းသဖြင့်ဆိုအပ်သောစကား။ မကောင်းသောစကား။ (ပါဠိ—ဒုဗ္ဘာသိတ)','‘သုဘာသိုတ်’ (န) လည်းရှု။')
,(7160,3,11,'(န) ဒုဗ္ဘိက္ခန္တရကပ်။ အစာငတ်မွတ်ခေါင်းပါးသောကပ်။',NULL)
,(7161,3,4,'သိမ်းဆည်းသည်။ (နောင်အသုံးလိုသောအခါသုံးရန်) သိုမှီးသိမ်းထားသည်။','“ထမှာဲကီု ကၠေၚ်သ္ၚုၜဵုကီု ဂၠာဲပကောံလဝ်တုဲ ဒေပ်လဝ်ရ။” (ဇ—၁၃၈။ အစွောံ။) = “အိုးကို၄င်း ဆီ၊ဆန်၊ ဆားတို့ကို၄င်း ရှာစုဆောင်းထားပြီးလျှင် သိမ်းထား၏။”')
,(7161,3,4,'သိမ်းဆည်းသည်။ (နောင်အသုံးလိုသောအခါသုံးရန်) သိုမှီးသိမ်းထားသည်။','“ဂြောဝ်ဂှ် ဒေပ်လဝ်ဖျုန်တုဲဟိုတ်မာဲအာတုဲ ကၠဵုပ္ဍဲသ္ၚိဂှ်စကၠေံရ။” (ဇ—၅၃၇။ အစွောံ) = “စားတော်ချက်သည် အသားကိုသိမ်းထားရာ မေ့လျော့သဖြင့် အိမ်မှာရှိသောခွေးက စားပစ်လိုက်၏။”')
,(7161,3,4,'သိမ်းဆည်းသည်။ (နောင်အသုံးလိုသောအခါသုံးရန်) သိုမှီးသိမ်းထားသည်။','“ဗောဓိသတ်ကလိဂွံ (ဖျုန်) အရၚ်ဇကုတုဲ အရၚ်သမ္ဘာဇကုကီု ဒေပ်လဝ်ဟွံစ။” (ဇ—၁၉၃။ အစွောံ။) = “ဘုရားလောင်းသည် မိမိ၏ဝေစုကို၄င်း မိမိမယား၏ဝေစုကို၄င်းရ၍ မစားဘဲ သိမ်းထား၏။”')
,(7161,3,4,'သိမ်းဆည်းသည်။ (နောင်အသုံးလိုသောအခါသုံးရန်) သိုမှီးသိမ်းထားသည်။','“အပ္ဍဲဂှ်ဗှ်ေဒေပ်လဝ်ဂျိလောဘဒေါသတုဲ မ္ၚးဂှ် ဗှ်ေသ္ၚဳလလံတဴရောၚ်သွံ။” (ဇ—၃၂၅။ အစွောံ) = “သင်သည် အတွင်း­ လောဘဒေါသအဆိပ်ကို သိုဝှက်သိမ်းဆည်းထားပြီးလျှင် အပြင်အပ­မူ ငြိမ်သက်တည်ကြည်ဘိသကဲ့သို့ နေ၏။”')
,(7162,3,4,'သိမ်းဆည်းသည်။','“ပယေဝ်စုတ်ဗပေၚ်လဝ်သ္ကာံတုဲ ဍေံတံဒေပ်ဂဍေပ်လဝ်—။” (သၠပတ်ဒ္ၚောဝ်သၜောံ) = “မီးဖို­ ဖွဲအပြည့်ထည့်၍ သူတို့သိမ်းဆည်းထားကုန်၏။”')
,(7162,3,4,'သိမ်းဆည်းသည်။','“ဂှ်ဒြပ်တံဂှ် ဒြပ်ဇကုရလဝ်စိုတ်တုဲ စုတ်လဝ်ပ္ဍဲတိုက်ဖလူတၟိတြေံ ဒေပ်စဍေပ်လဝ်ရ။” (သၠပတ်သတိပထာန်) = “ထိုဥစ္စာတို့ကို မိမိဥစ္စာဟု သဘောထားကာ ဥစ္စာတိုက်အသစ်အဟောင်းတို့­ ထည့်၍သိမ်းဆည်းထား၏။”')
,(7163,3,4,'×စိတ်ထားရှိသည်။ (ကောင်းသည့်ဘက်ရော မကောင်းသည့်ဘက်ရော လိုရာအဓိပ္ပါယ်ဖြင့် အကန့်အသတ်မရှိ တွဲစပ်သုံးစွဲနိုင်သည်။ အောက်ပါပြယုဂ်များကို နည်းယူပါ။)',NULL)
,(7164,3,4,'ယုတ်ညံ့ညစ်ညူးသောစိတ်ကို မွေးမြူထားရှိသည်။','“ယုတ်ညံ့ညစ်ညူးသောစိတ်ကို မွေးမြူထားရှိ၍ သီလမဲ့သောအလဇ္ဇီဖြစ်၏။')
,(7165,3,4,'စိတ်ထားကောက်ကျစ်သည်။ ကောက်ကျစ်သောစိတ်ရှိသည်။','ပူဂဵုမဒေပ်စိုတ်စၞာဲ = စိတ်ထားကောက်ကျစ်သူ။')
,(7165,3,4,'စိတ်ထားကောက်ကျစ်သည်။ ကောက်ကျစ်သောစိတ်ရှိသည်။','“ဒေပ်စၞာဲဟေၚ်၊ ဥပ္ပဲါတၟေၚ်တၟဟ်။” (လိက်ဏာဝဏ္ဏ) = “ထူးထွေသောဥပါတ်တံမျဉ်ဖြင့် ကောက်ကျစ်စဉ်းလဲသောမာယာရှိသည်။”')
,(7166,3,4,'စိတ်ထားဖြောင့်မတ်သည်။ ရိုးသားဖြောင့်မှန်သောစိတ်ရှိသည်။','“ညးဗၞိက်လီုတၠပညာ မလေပ်ဒေပ်စိုတ်တမ္ၚူတုန် ဒဒှ်ထဝ်ၜိုန်တၠဒြပ်ဟွံတီကီု ထးဝွံ ၚုဟ်ထဝ်မွဲလက်ဟေၚ်မတန် မဟီုကဵုတမ္ၚူရ။” (ဇ—၃။ အစွောံ) = “ပညာရှိရွဲကုန်သည်သည် ဖြောင့်မတ်သောစိတ်ရှိသည်ဖြစ်၍ ဥစ္စာရှင်က ရွှေဖြစ်မှန်းမသိသော်ငြားလည်း ဤခွက်သည် အဘိုးတစ်သိန်းထိုက်သောရွှေခွက်ဖြစ်ကြောင်း အမှန်အတိုင်း ရိုးသားစွာပြောပြ၏။”')
,(7166,3,4,'စိတ်ထားဖြောင့်မတ်သည်။ ရိုးသားဖြောင့်မှန်သောစိတ်ရှိသည်။','“ဒေပ်စိုတ်တမ္ၚူ၊ စိုတ်ကဵုလ္ဂူသ္အး။” (လိက်လၞုဟ်ပန်) = “ဖြောင့်မှန်သောစိတ်ထားရှိပြီး စိတ်ကိုဖြောင့်မတ်စင်ကြယ်ပါစေ။”')
,(7167,3,4,'စိတ်ကောင်းရှိသည်။ စိတ်ကောင်းထားသည်။','“ယွံမၞးတံ၊ မၞးတံဒေပ်စိုတ်ထမှိက်ညိ။” (ဇ—၄၆၈။ အစွောံ) = “အချင်းတို့၊ သင်တို့တွေ စိတ်ကောင်းရှိကြပါ။”')
,(7168,3,4,'ရက်စက်သောစိတ်ရှိသည်။','“မရာတ်ဒေပ်စိုတ်ဒဇန် ပန်ဂစိုတ်တၠသ္ၚိသ္ဍိုက်အဲ—” ခနှောဝ်ဗြဴဂးကဵုသၟိၚ်။ (ဇ—၄၈၅။ အစွောံ) = “အရှင်မင်းကြီးသည် ရက်စက်သောစိတ်ထားဖြင့် အကျွန်ုပ်၏ချစ်လင်အား ပစ်သတ်ဘိ၏” ဟုကိနနရီမ၊ဆို၏။')
,(7169,3,4,'ကြမ်းကြုတ်သောစိတ်ရှိသည်။ ပြစ်မှားတတ်သောစိတ်ရှိသည်။','“ယွံသၟိၚ်၊ဟိုတ်တၠအဲမဒးဂၞပ်ကဵုအဲတုဲ တၠသ္ၚိအဲတြုံမပြဲ ဟွံမွဲကဵုဒုဟ်ဂှ် တၠအဲဒေပ်စိုတ်ဒမြိုဟ်တုဲ မပန်ဂစိုတ်ကၠေံတုဲဂှ် ဂကောံတြုံဒမြိုဟ်ဂှ် မူဂှ်အဲလှိၚ်စိုတ်နွံတုန်ရော” ခနှောဝ်ဗြဴဂး။ (ဇ—၄၈၅။ အစွောံ။) = “အို—မင်း၊ သင်သည် အကျွန်ုပ်ကိုနှစ်သက်သောကြောင့် ကြမ်းကြုတ်သောစိတ်ဖြင့် အပြစ်မဲ့သောယောကျာ်းမြတ်ဖြစ်သော အကျွန်ုပ်လင်အား ပစ်သတ်ခဲ့ပြီးနောက် အကျွန်ုပ်သည် ထိုကြမ်းကြုတ်သောယောကျာ်းနှင့်တကွ အဘယ်မှာလျှင် မွေ့လျော်ပျော်ပိုက်ခြင်း ရှိပါငြားအံ့နည်း” ဟုကိနနရီမဆို၏။')
,(7170,3,4,'ယုတ်မာသောစိတ်ထားသည်။','“ဟိုတ်ဒှ်ဝဲရော၊ ဗောဓိသတ္တာ။ — ဂၞကျာ်ဂှ်ရ၊ ဗဒှ်သာ်လွာ။ ဒေပ်စိုတ်ဒၟိက်ဟေၚ်၊ က္တဵုဒှ်သေၚ်ဟာ။” (လိက်ဏာဝဏ္ဏ) = “ဘုရားလောင်း၏ရန်ငြိုးဖြစ်ခြင်းကြောင့် ထိုမိဖုရားသည် ယုတ်မာသောစိတ်ထားကာ ပြုမူခြင်းဖြစ်၏။”')
,(7171,3,4,'ရန်စိတ်ထားသည်။ အငြိုးအတေးထားသည်။','“(ဍိက်သၚ်္ခသေဋ္ဌဳတံဂှ် ဗှ်ကဵုတၠမဇိုန်ကဵုပဍိက်ပိလိယသေဋ္ဌဳ မဒးပိၚ်ပှ်အာ ကၟိန်ဍုၚ်က္ဍိုၚ်ဗ္တာၚ်တၞဟ်တုဲ တန်ဒက်စိုတ်ဒေပ်စိုတ်ဒြေၚ်သၠသာ်ဂှ် ဟွံဂွံပ။” (ဇ—၁၃၁။ အစွောံ။) = “သင်္ခသူဋ္ဌေး၏ကျွန်တို့သည် မိမိသခင်က မိမိတို့အား ပိလိယသူဋ္ဌေးထံ­ ကျွန်ခံခိုင်း၍ တိုင်းတစ်ပါးသို့ ရောက်သွားရကုန်သော်လည်း သခင့်အပေါ် ရန်ငြိုးဖွဲ့ခြင်း အငြိုးအတေးထားခြင်း မပြုကြကုန်။”')
,(7172,3,4,'သူတော်ကောင်းစိတ်ရှိသည်။','“ဒြာဲၜါဂှ် ဒေပ်စိုတ်ထမိက် ဒေပ်စိုတ်သပ္ပရိုဟ်တုဲ ဒၟံၚ်ကေတ်ဂကောံအဲရောၚ်” သၟိၚ်ဒြာဲထဝ်ဂးကဵုလၟရ။ (ဇ—၅ဝ၁။ အစွောံ။) = “ထိုနှစ်ခုကုန်သောသမင်တို့သည် စိတ်ကောင်းစိတ်မြတ် သူတော်ကောင်းစိတ်ရှိသည်ဖြစ်၍ အကျွန်ုပ်အပါး­နေ၏” ဟုရွှေသမင်မင်းက မုဆိုးအားပြော၏။')
,(7173,3,4,'ယုတ်မာပက်စက်သောစိတ်ထားရှိသည်။','“မာဒေပ်စိုတ်သၟာ်၊ အယုက်ကျာ်တြဲ။ ပြာပ်ကၠုၚ်အာတ်ရ၊ နွံကာလမွဲ။” (လိက်ပထမဗောဓိ။ မၚ်ဍိက်လ။) = “မာရ်နတ်သည်ယုတ်မာပက်စက်သောစိတ်ထားဖြင့် တစ်နေ့သ­လာရောက်၍ မြတ်စွာဘုရား၏အသက်တော်ကိုတောင်း၏။”')
,(7174,3,4,'စိတ်နှစ်မျိုးထားရှိသည်။ မရိုးသား။','“ဗ္ဒန်မတ်တြုံရ၊ တလသ္ၚိက္ဍၚ်။ ဟွံကၠတ်စိုတ်ရ၊ သစ္စဗိုန်မၚ်။ ဟွံဒေပ်စိုတ်ၜါ၊ မိတ်ၜါလၚ်လၚ်။ ဝွံဝတ်ဗြဴမွဲ၊ ကျာ်တြဲတွံဆင်။” (လိက်ကာကဒိပ္ပ။ မဟာကြၚ်။) = “လင်ယောကျ်ား၏မျက်ကွယ်­ လင်ကိုမလှည့်စား မြဲစွာသစ္စာစောင့်၍စိတ်နှစ်မျိုးမထား လင်နှစ်ယောက်မထားခြင်းသည် မယားဝတ်တစ်ပါးဟု မြတ်စွာဘုရားဟောတော်မူ၏။”')
,(7174,3,4,'စိတ်နှစ်မျိုးထားရှိသည်။ မရိုးသား။','“ပါၚ်တြုံတအ်သွံ၊ ပ္တေဟ်စဂွံဟာ။ ပါၚ်ကောအမြိုတ်၊ ဒေပ်လဝ်စိုတ်ၜါ။” (လိက်သၟိၚ်ဇဲယဒတ္တ) = “ယောကျာ်းသားတို့၏စကားကို ယုံစား၍ရမည်လော။ အမြိုက်အရသာရှိသောစကားဖြင့် မယ့်မောင်သည် မရိုးသားဘဲ စိတ်နှစ်မျိုးထား၏။”')
,(7175,3,4,'လင်မြှောင်ထားသည်။ အပျော်လင်ထားသည်။','“ဒှ်လဗၚ်ဗြဴ၊ ဒေပ်တဴတြုံကျာ။” (လိက်သၟိၚ်ဇဲယဒတ္တ) = “ဖောက်ပြားသောမိန်းမဖြစ်၍ အပျော်လင်ထား၏။”')
,(7176,3,4,'(တရားဝင်လင်ရှိလျက်) လင်ငယ်နေသည်။ လင်မြှောင်ထားသည်။','“ၝောံဒေပ်တြုံသကဲရောၚ်သွံ” ဗမၞးဂး။ (ဇ—၆၂။ အစွောံ။) = “ရှင်မ၊ သင်သည် လေငယ်နေသည်တကား။”')
,(7176,3,4,'(တရားဝင်လင်ရှိလျက်) လင်ငယ်နေသည်။ လင်မြှောင်ထားသည်။','“ဗမၞိဟ်ဗြဴဂှ် ဒေပ်တြုံသ္ကဲရောၚ်။” (ဇ—၁၃ဝ။ အစွောံ။) = “ထိုပုဏ္ဏေးမသည် လင်မြှောင်ထား၏။”')
,(7177,3,4,'သိမ်းဆည်းသည်။ သိုမှီးသိမ်းဆည်းသည်။ (ဒေပ်နေပ် = ဂိုၚ်ဒေပ်) (ပါဠိ—ပဋိသာမေတိ) ဒေပ်ဖ္ဍေပ် (ကြိ) ‘ဒေပ်သ္ဍေပ်’ ရှု။',NULL)
,(7178,3,4,'မိန်းမယူထားသည်။ မယားရှိသည်။ မယားနှင့်နေသည်။','“ယွံဝိဓုရ၊ ပူဂဵုမဒှ်ဒမုၚ်ဒါန်ပိုဲမပြဲဂှ် ပဒတဴသ္ၚိကၟိန်ဟာ ဒေပ်ဗြဴကီုဟာ” သၟိၚ်သၟာန်။ (ဇ—၄၉၅။ အစွောံ။) = “ဝိဓုရ၊ ငါတို့၏မြတ်သောအလှူခံပုဂ္ဂိုလ်သည် အိမ်ထောင်­နေသလော၊ မိန်းမထားသလော။”')
,(7179,3,4,'(တရားဝင်မယားရှိလျက်) မယားငယ်နေသည်။',NULL)
,(7180,3,4,'(တရားဝင်မယားရှိလျက်) မယားငယ်နေသည်။','“ယွံတၠညး၊ ပိုဲဗြဴဂှ် ညံၚ်တၠသ္ၚိဒေပ်ဗြဴအဗၠံက် ဒေပ်ဗြဴကမၠောန်ဂှ် ဒှ်ဒဒိုက်စိုတ်လောန်ရအဴ” ဂၞကျာ်ဂး။ (ဇ—၄၈၉။ အစွောံ။) = “အရှင်မင်းကြီး၊ လင်တယောက်တည်း­ မယားအများရှိခြင်းသည် မိန်းမတို့အား အလွန်ဆင်းရဲ၏” ဟုမိဖုရားဆို၏။ (ညောင်ကန်)')
,(7181,3,4,'သိမ်းဆည်းသည်။ သိုမှီးသည်။','“ခမဳမွဲဂှ် နူကဵုဇၞးပိုတ်တေံ ကၠုၚ်စိုပ်ဘာဇေတဝန်တုဲ ဒေပ်ရၚ်ပရိက္ခရာဇကုတုဲ အာလ္ၚောဝ်ကျာ်တြဲရ။” (ဇ—၃၃၇။ အစွောံ။) = “ထိုရဟန်းသည် ဇနပုဒ်မှ ဇေတဝန်ကျောင်းတော်သို့သွား၍ သပိတ်သင်္ကန်းကိုသိုမှီး၍ ဘုရားကိုရှိခိုး၍—။” (ညောင်ကန်)')
,(7181,3,4,'သိမ်းဆည်းသည်။ သိုမှီးသည်။','“နူဂယးပြဟ်က္တဵုတုဲ ဒေပ်ရၚ်တွံၚးအဿမာပိုတ်ဂှ်တုဲ ဍာ်သွုၚ်ကီု ဍာ်လွပ်ကီု တုက်ဗပေၚ်လဝ်ရ။” (ဇ—၅၁၉။ အစွောံ။) = “နံနက်စောစောထ၍ ကျောင်းသင်္ခမ်းကိုသိမ်းဆည်းလှည်းကျင်း၍ သောက်ရေကို၄င်း သုံးရေကို၄င်း ခပ်ဖြည့်ထား၏။”')
,(7181,3,4,'သိမ်းဆည်းသည်။ သိုမှီးသည်။','“ယွံတၠအဲ၊ မၞိက်ဝွံဂှ်ရ ဒေပ်ရေၚ်လေပ် ဒေပ်ရေၚ်ဒးဂှ် ခိုဟ်ရ။ ဒေပ်ရေၚ်ဟွံလေပ် ဒေပ်ရေၚ်ဟွံဒးတုဲဂှ် ဂုန်မၞိက်ဝွံဒှ်လေၚ်ရောၚ်။” (ဇ—ဘူရိဒတ်။ အစွောံ။) = “ငါ့ရှင်၊ ဤပတ္တမြားသည်ကား သိုမှီးတတ် သီုမှီးမှန်လျှင်ကား ကောင်း၏။ သီုမှီးမတတ် သိုမှီးမမှန်လျှင် ဤပတ္တမြားကြောင့် ဘေးဖြစ်လိမ့်မည်။”')
,(7182,3,4,'အသွင်ယူတုပသည်။ ဟန်ဆောင်လှည့်စားသည်။','“မတုဲတေံသွံ၊ ဟွံဂွံဒေပ်လွေဟ်။ ဝါဝွံကောမိ၊ အံသဝ်ဝိသှ်ေ။ ဒေပ်ဥပ္ပါယ်လွေဟ်၊ ကဵုအဲကွေံသွံ။” (လိက်ပထမဗောဓိ။မၚ်ဍိက်လ။) = “မယ့်မောင်သည် ရှေးယခင်က ဟန်မဆောင်မလှည့်စားစဖူးပါ။ ယခုအခါ မယ့်မောင်သည် အံ့ဖွယ်ထူးဆန်းစွာ မယ့်အား ဥပ္ပါယ်ဖြင့် ဟန်ဆောင်လှည့်စားခဲ့ပြီတကား။”')
,(7182,3,4,'အသွင်ယူတုပသည်။ ဟန်ဆောင်လှည့်စားသည်။','“ဍိက်မဒေပ်လွေဟ်၊ မပ္တေဟ်တလ။” (လိက်သောဝိန်ဇဲယ။ မာံရောဂေါ။) = “သခင့်ကိုယုံကြည်ဟန်ဆောင်သောကျွန်။”')
,(7183,3,4,'သိမ်းဆည်းသည်။ သိုမှီးသည်။ (?)','“သၟိၚ်အမာတ်တံ ကေတ်ထဝ်သြန်ကဵုညးဒိုက် ဒေပ်သ္ဍေပ်ကျိုၚ်ကျဝ်စဟာပ်ရ။” (ရာဇာဝၚ်အၚ်ဝ—ဟံသာဝတဳ) = “မင်းအမတ်တို့သည် သူဆင်းရဲများထံမှ ရွှေငွေကိုယူ၍ သိုမှီးဆင်ယင်စားသောက်ကုန်၏။”')
,(7183,3,4,'သိမ်းဆည်းသည်။ သိုမှီးသည်။ (?)','“ဂိုၚ်ကေတ်ထဝ်သြန်တံဂှ်တုဲ ဒေပ်ဖ္ဍေပ်လဝ်ရ။” (ရာဇာဝၚ်အၚ်ဝ—ဟံသာဝတဳ)')
,(7184,3,4,'သိမ်းဆည်းသည်။ သိုမှီးသည်။','“ကာလဗြဲရတ်ဂူ ဟွံဂွံလပှ်ဂိုၚ်ဒေပ်သၞေပ်လဝ်တုဲ ကာလဒိုက်ဒိန်ကာဲကဏာဲ ကရောတ်ကဵုဗြဲရတ် လ္ပကဵုဒှ်ညိ။” (သၠပတ်အနမတဂ္ဂသံသာရကထာ) = “ရတနာမိုးရွာစဉ် မကောက်စုမသိုမှီးထားဘဲ ဆင်းရဲနွမ်းပါသောအခါမှရတနာမိုးကို တောင့်တညည်းညူခြင်း မဖြစ်ပါစေနှင့်။”')
,(7184,3,4,'သိမ်းဆည်းသည်။ သိုမှီးသည်။','“ပ္ကီုလွဳဂၠာဲဇ္ၚဳဒြပ် ဒြပ်ဂွံတုဲဒေပ်သဏေပ်လဝ် ဟွံဂွံပ္တုဲကုသဵု ဟွံဂွံကဵုလဝ်ဒါန် ဒေပ်သၞေပ်လဝ်သွက်ညးသၟး ဇကုမစဴဒှ်လ္ၚုရ။” (သၠပတ်ပုံပမာ။ အစွောံ။) = “အားထုတ်ဥစ္စာရှာ၍ ဥစ္စာရပြီးနောက် သိုမှီးသိမ်းဆည်းထားပြီး ကုသိုလ်ဒါနမပြုရဘဲ သူတစ်ပါးအတွက်သာ သိုမှီးသိမ်းဆည်းထား၏၊ မိမိမှာမူ အချည်းနှီးသာဖြစ်ရ၏။”')
,(7185,3,4,'၁။ ခိုက်နေသည်။ သောင်တင်သည်။','“က္ၜၚ်ပိုဲဒိုပ်အာသံၚ်ရ။” = “ကျွန်တော်တို့၏သင်္ဘော သောင်တင်သွားသည်။”')
,(7185,3,4,'၁။ ခိုက်နေသည်။ သောင်တင်သည်။','၂။ အနည်ထိုင်သည်။')
,(7185,3,4,'၁။ ခိုက်နေသည်။ သောင်တင်သည်။','“ကောန်တိပ္ဍဲဍာ်ဂှ် ဒိုပ်စှ်ေအာတုဲ ဍာ်ဂှ်ကေဝ်သ္ဇုၚ်တိုန်ရ။” = “ရေရှိမြေသားများ အနည်ထိုင်သွားပြီးနေက် ရေသည် ကြည်လင်လာသည်။”')
,(7185,3,4,'၁။ ခိုက်နေသည်။ သောင်တင်သည်။','၃။ အေးခဲသည်။')
,(7185,3,4,'၁။ ခိုက်နေသည်။ သောင်တင်သည်။','“ဟိုတ်နူဂံက်လောန်တုဲ ဍာ်ဒိုပ်အာတုဲ ဒှ်အာဍာ်ကလိုအ်ရ။” =“အေးလွန်းသောကြောင့် ရေသည်အေးခဲပြီး ရေခဲဖြစ်သွားသည်။”')
,(7186,3,4,'သောင်တင်သည်။ ကမ်းကပ်သည်။','“ဟးသော်မပြဲ၊ အဲစကာဏာ။ မူဒၞာဲဒိုပ်ဒဝ်၊ ဒေါဝ်ၜဳဂၚ်ဂါ။” (လိက်မိဍောၚ်ကှ်ေထဝ်) = “(မယ်ရွှေခရေပွင့်က အဓိဋ္ဌာန်ပြု၍ ရေမျှောလိုက်သောဆံပင်ကို မယ်ရွှေခရေပွင့်က ဤသို့ဆို၏။) အို—မြတ်သောဆံပင်၊ သင့်ကိုငါခိုင်းစေလိုက်ပြီး မြစ်ပင်လယ်အလယ် အဘယ်အရပ်­ သောင်တင်')
,(7186,3,4,'သောင်တင်သည်။ ကမ်းကပ်သည်။','ကမ်းကပ်ပါသနည်း။”')
,(7187,3,3,'(တိရစ္ဆာန်) ငယ်ရွယ်သော။','ဂၠဴဒမ် = နွားပေါက်။ နွားပျို။')
,(7187,3,3,'(တိရစ္ဆာန်) ငယ်ရွယ်သော။','ဗတာဲဒမ် = ယုန်ပေါက်။ယုန်ပျို။')
,(7187,3,3,'(တိရစ္ဆာန်) ငယ်ရွယ်သော။','“ညးမဒ္ဂူလောန်မွဲ စဴကၠုၚ်နူဂြိုပ် ကေတ်နၚ်ဗတာဲဒမ်မွဲ။” (ဇ—၄၄ဝ။ အစွောံ။) =“တစ်ယောက်သောရိုးလွန်းသူသည် တောမှအပြန် တစ်ခုသောယုန်ပေါက်ကို ယူလာ၏။”')
,(7187,3,3,'(တိရစ္ဆာန်) ငယ်ရွယ်သော။','“ရဴဂၠဴဒမ်သၟတ် မစလာ်ကၠုၚ်ကဵုၝောံကီု။” (ဇ—ဝေသန္တဝ်။ အစွောံ။) = “နွားပေါက်ငယ်လေးသည် မိခင်နွားမကြီးဆီသို့ ခုန်ပေါက်၍လာသကဲ့သို့။”')
,(7187,3,3,'(တိရစ္ဆာန်) ငယ်ရွယ်သော။','ကောန်စိၚ်ဒမ် = ဆင်ငယ်။ ဆင်ပေါက်။ ဆင်လတ်။ ဆင်ရွေ။ (ပါဠိ—ဟတ္ထိကလဘ)')
,(7188,3,1,'လောင်းရိပ်။','ဒးဒမျံက် = လောင်းရိပ်မိသည်။')
,(7188,3,1,'လောင်းရိပ်။','“ဆုဂွံဗၠးသ္ဂုဲ၊ ဒမျံက်တုဲမှာ။သ္ဂောံပ္တိုန်ဗၠိုၚ်ဗၠ၊ ကၞာၚ်သၠသ္အဳဗ္ဂာ။” (လိက်ဓနဥ္ဇယျကုမ္မာ။ အစွောံ။) = “သစ်ပင်သည် လောင်းရိပ်လွတ်ပြီးမှသာ အညွန့်အတက်တို့ကိုထုတ်၍ အခက်အရွက်များဝေဆာ၏။”')
,(7188,3,1,'လောင်းရိပ်။','“ရဴတၞံဆုမဗၠးနူလမှဳဒမျံက်တုဲ မဂွံပ္တိုန်ဗၠိုၚ်ဗၠသၠကၟဝ်ကသဝ်ပ္ကဴတုဲ—။” (သၠပတ်ပုံပမာ။ အစွောံ။) = “ပင်စည်လောင်းရိပ်မှ လွတ်သောသစ်ပင်သည် အညွန့်အတက်အရွက်အဖူးအပွင့်တို့ကို ထုတ်ဆောင်နိုင်သကဲ့သို့။”')
,(7189,3,3,'မည်းသော။ မည်းညိုသော။ မည်းနက်သော။ (Black)','ချးဒမျိုၚ် = မည်းသောမီးသွေး။')
,(7189,3,3,'မည်းသော။ မည်းညိုသော။ မည်းနက်သော။ (Black)','“ကၞုဲဇၞော်ဒမျိုၚ်မုက်မွဲ။” (ဇ—၂၉၈။ အစွောံ။) = “မျက်နှာမည်းသောမျောက်ကြီး။” (abig black-faced monkey)')
,(7189,3,3,'မည်းသော။ မည်းညိုသော။ မည်းနက်သော။ (Black)','‘ဂၠဴဒမျိုၚ်ပန်။’ (ဇ—၇၇။ အစွောံ။) = ‘နွားနက်လေးကောင်။’')
,(7189,3,3,'မည်းသော။ မည်းညိုသော။ မည်းနက်သော။ (Black)','“လ္ပာ်သၟိၚ်ကလိၚ်ဂှ် ဒေဝတဴမမၚ်မွဲသၟိၚ်ကလိၚ်ဂှ် ပရုပ်ဂၠဴဥဿဘဗ္တာၚ်တုဲ လ္ပာ်သၟိၚ်အဿကဂှ် ဒေဝတဴမမၚ်မွဲသၟိၚ်အဿကဂှ် ပရုပ်ဂၠဴဥဿဘဒမျိုၚ်တုဲ ဍေံဇဵုရေၚ်သ္ကံရ။” (ဇ—၃ဝ၁။ အစွောံ။) =“ကာလိင်္ဂမင်း၏ အစောင့်အရှောက်နတ်သည် အလုံးစုံဖြူသော ဥသဘဖြစ်၏။ အဿကမင်း၏အစောင့်အရှောက်နတ်သည် အလုံးစုံမည်းသော ဥသဘဖြစ်၏။ (အချင်းချင်းဝှေ့ကြကုန်၏။)” (ညောင်ကန်) (a perfectly black bull)')
,(7189,3,3,'မည်းသော။ မည်းညိုသော။ မည်းနက်သော။ (Black)','“(ကောန်ဒေဝတဴ) မာတလိ ပၠေၚ်ကၠေံရုပ်ကလော်ဂှ်တုဲက္တဵုဗဒှ်ရုပ်ကၠဵုဒမျိုၚ်မွဲ တမာချေံဇၞော်ပၠန်—။” (ဇ—၄၆၉။ အစွောံ။) = “မာတလိနတ်သားသည်ဘီလူးရုပ်အသွင်ကိုဖျောက်၍ မြင်းကြီးပမာဏရှိသော ခွေးနက်ကြီးရုပ်အသွင်ကို ဖန်ဆင်းပြန်၏။” (a huge black hound)')
,(7189,3,3,'မည်းသော။ မည်းညိုသော။ မည်းနက်သော။ (Black)','“ကွဴဗြဴဝုတ်ဒမျိုၚ်ၜါဂှ်—။” (ဇ—၅၃၆။ အစွောံ။) = “နှစ်ခုသောမည်းသောဥသြပျိုမ။”')
,(7189,3,3,'မည်းသော။ မည်းညိုသော။ မည်းနက်သော။ (Black)','(န) မည်းညစ်ခြင်း။ ညစ်ညူးခြင်း။')
,(7189,3,3,'မည်းသော။ မည်းညိုသော။ မည်းနက်သော။ (Black)','ဒမျိုၚ်ဒုစရိုတ် = အကုသိုလ်ဒုစရိုက်၏မည်းညစ်မှု။')
,(7189,3,3,'မည်းသော။ မည်းညိုသော။ မည်းနက်သော။ (Black)','“ဟာဲအစေလက၊ — ဗှ်ေမၞုံကဵုဒမျိုၚ်ဒုစရိုတ်ရောၚ်။” (ဇ—၅၁၈။အစွောံ။)')
,(7189,3,3,'မည်းသော။ မည်းညိုသော။ မည်းနက်သော။ (Black)','‘ဒျိုၚ်’ (ကြိ) လည်းရှု။')
,(7190,3,1,'မှိုင်းညိုခြင်း။ တိမ်ညိုအဆင်းရှိခြင်း။','“စိုပ်က္ဍိုပ်တၟအ်ဂှ်တုဲ စမဳရံၚ်တၞံဇြဲသုံမွဲမၞုံသလုၚ်ထပှ်ယောဇနာတုဲ မၞုံဗၠိုၚ်ဒစာံလ္ၚီဂှ်ရ၊ ညာတ်ဒမျောံဇြဲသုံ ညံၚ်ရဴဒမျောံမတ်ဗြဲကီုဂှ်ရ။” (ဇ—၅၁၄။ အစွောံ။) = “ထိုတောင်ထိပ်သို့ရောက်၍ လှမ်းမျှော်ကြည့်သည်ရှိသော် အမြင့်ခုနစ်ယူဇနာရှိသော ရှစ်ထောင်သောပါးပျဉ်းရှိသော တိမ်ညိုအဆင်းကဲ့သို့သော ပညောင်ပင်၏ညိုမှိုင်းခြင်းကို မြင်ရလတ္တံ့။”')
,(7190,3,1,'မှိုင်းညိုခြင်း။ တိမ်ညိုအဆင်းရှိခြင်း။','“သၟးမဇြဟောံ၊ ဒေါဝ်ဒမျောံဂြိုပ်။” (လိက်ရတနပဇ္ဇောတ) = “တော၏မှိုင်းညိုခြင်းအလယ်­ နှလုံးမသာမယာရှိသကဲ့သို့။”')
,(7190,3,1,'မှိုင်းညိုခြင်း။ တိမ်ညိုအဆင်းရှိခြင်း။','“ညာတ်တၞံဆုဗိုန်၊ ဗှ်တိုန်နာဲဇု။ ပ္ဍဲဒမျောံဆု၊ လ္ၚုစံၚ်တူ။” (လိက်သၟိၚ်ဇဲယဒတ္တ) = “သစ်ပင်ကိုမြင်သော် ချစ်သူသခင်ကို သတိရ၏၊မှိုင်းညိုသောသစ်ပင်ဝယ် တစ်ကိုယ်တည်း ပူပန်နေရ၏။”')
,(7190,3,1,'မှိုင်းညိုခြင်း။ တိမ်ညိုအဆင်းရှိခြင်း။','‘ဒယောံ')
,(7190,3,1,'မှိုင်းညိုခြင်း။ တိမ်ညိုအဆင်းရှိခြင်း။','ဒယောမ်’ (ကြိ) လည်းရှု။')
,(7191,3,1,'နေဝင်ရီတရော။',NULL)
,(7192,3,1,'မိုးတိမ်ညိုထု။',NULL)
,(7193,3,1,'အနက်။','(နဝိ) နက်ရှိုင်းသော။')
,(7193,3,1,'အနက်။','ဍာ်ဒမျိုဟ် = နက်သောရေ။')
,(7193,3,1,'အနက်။','“တုပ်ပၟာညံၚ်ကျာံနွံပ္ဍဲဝၚ်ဒမျိုဟ်။” (အကြီုရာဇာဓိရာဇ်) = “ရေနက်သောမြစ်ကွေ့­ရှိသော မိကျောင်းနှင့်ပမာတူ၏။”')
,(7194,3,1,'အသံ။','‘ဗရု’ ရှု။')
,(7195,3,4,'ကြောက်၍တုန်သည်။ ကြက်သီးထသည်။','ဇကုဒရဴ = ကြက်သီးတဖျန်းဖျန်းထသည်။')
,(7195,3,4,'ကြောက်၍တုန်သည်။ ကြက်သီးထသည်။','တသော်ဇကုဒမြဴ = ကြက်သီးမွေးညှင်းထသည်။ (ပါဠိ—လောမဟံသန)')
,(7195,3,4,'ကြောက်၍တုန်သည်။ ကြက်သီးထသည်။','“ဆဗၞတ်သော်ဇကုညိ ဟွံဂွံဒမြဴ။” (သၠပတ်အနမတဂ္ဂသံသာရကထာ) = “အနည်းငယ်မျှလည်း ကြက်သီးမွေးညှင်းမထ။”')
,(7195,3,4,'ကြောက်၍တုန်သည်။ ကြက်သီးထသည်။','“ခါဂွံမိၚ်တဴ၊ ဒမြဴဇကု။” (လိက်ဝိဓူရ) = “ကြားရသောအခါ ကိုယ်ကြက်သီးမွေးညှင်းထ၏။”')
,(7195,3,4,'ကြောက်၍တုန်သည်။ ကြက်သီးထသည်။','“သၟိၚ်ဂွံမိၚ်အဴ၊ ဒမြဴဇကု။” (လိက်သုဝဏ္ဏသာံ။ မာံသေၚ်။)')
,(7196,3,4,'ကြုံးဝါးသည်။ အမွှမ်းတင်သည်။ (?)','“ဍေံတက်ကၞက်၊ ဒမြက်ဇကု။ အဲဇၞးအဲဇၞး၊ဍေံဂးထဥ။” (လိက်ဝိဓူရ) = “သူသည် လက်ပမ်းပေါက်ခတ်လျက် ငါနိုင်ပြီငါနိုင်ပြီဟု မိမိကိုယ်ကို အမွှမ်းတင်ကြုံးဝါး၏။”')
,(7197,3,3,'များပြားသော။ မြားမြောင်သော။','“ဒ္ဂေတ်ဝေါဟာ၊ ဗက်ဘာသာလိုက်။ လအ်ညိတုဲအဴ၊ ကောန်စဴဒမြိုက်။” (ဝၚ်ပ္တန်ဍုၚ်ပဒုမ်ဋ္ဌာနဳ) = “လောကအစဉ်အလာကိုလိုက်၍ လက်ထပ်ထိမ်းမြားကြပြီးလျှင် ကာလကြာရှည်လတ်သော် မြားမြောင်သောမြေးများရလာကုန်၏။”')
,(7198,3,4,'မိုးချုန်းသကဲ့သို့ အသံမြည်သည်။ မြည်ဟီးသည်။ ထစ်ချုန်းသည်။',NULL)
,(7199,3,1,'‘ဒရိၚ်’ (န) ရှု။',NULL)
,(7200,3,3,'ပြင်းထန်သော။ ကြမ်းတမ်းသော။ ရုန့်ရင်းသော။','ကျာဒမြာတ် = လေပြင်း။')
,(7200,3,3,'ပြင်းထန်သော။ ကြမ်းတမ်းသော။ ရုန့်ရင်းသော။','အရေဝ်ဒမြာတ် = ရုန့်ရင်းသောစကား။ ကြမ်းတမ်းသောစကား။')
,(7200,3,3,'ပြင်းထန်သော။ ကြမ်းတမ်းသော။ ရုန့်ရင်းသော။','“ဒှ်ကောဇြဟာန်မချိုတ်အာဂှ် မူပဟွံယာံရော။ ကာလမဂျိုၚ်တဴတေံဂှ် တက်ၜုၚ်ဟီုဂးအရေဝ်ဒမြာတ်ဂၠိုၚ်တုဲ ဟွံဂွံယာံသ္ဂးဟာ။” (ဇ—၃၅၄။ အစွောံ။) = “ချစ်လှစွာသောအစ်ကိုသေသည်ကို အဘယ်ကြောင့် မငိုပါသနည်း။ အသက်ရှင်စဉ်ကာလ­ သင့်အားရိုက်ပုတ်၍ ကြမ်းတမ်းသောစကားကို ဆိုသည်ဖြစ်၍ မငိုကြွေးခြင်းပေလော။”')
,(7201,3,1,'ကြေးသတ္တု။','‘ဗမြိုတ်’ ရှု။')
,(7202,3,1,'တစ်ချက်။ တစ်ခဏ။ တစ်မှိတ်။','မွဲဒမြိပ်မတ် = မျက်စိတစ်မှိတ်။')
,(7202,3,1,'တစ်ချက်။ တစ်ခဏ။ တစ်မှိတ်။','‘မွဲဒမြိပ်’ (ကြိဝိ) လည်းရှု။')
,(7203,3,1,'၁။ ရွှံ့ညွန်တော။ စိမ့်တောလွင်ပြင်။','“(မဂဒူ) ဒဴတိတ်မံၚ် ဆဒမြီုပါ်ဝးကၠာ ပ္ဍဲကာလဂှ်ရ။” (အကြီုရာဇာဓိရာဇ်) = “(မဂဒူးသည်) သောက္ကတဲမြို့မှ ထွက်ပြေးလေ၏။ ပိုက်ဝါမည်သော စိမ့်တောလွင်ပြင်စခန်းသို့ရောက်လျှင်—။” (ရာဇာဓိရာဇ်အရေးတော်ပုံကျမ်း။ နိုင်ပန်းလှ။)')
,(7203,3,1,'၁။ ရွှံ့ညွန်တော။ စိမ့်တောလွင်ပြင်။','၂။ အဝန်းအဝိုင်း။ ဝန်းကျင်။')
,(7203,3,1,'၁။ ရွှံ့ညွန်တော။ စိမ့်တောလွင်ပြင်။','“ပ္ဍဲဨသာန်တိဗ္ၚဂှ် ပ္ဍဲစရုဲတၟံမွဲဂှ် ဒမြိုမ်ဂြိုပ်ကြိက်မွဲနွံ။” (ဇ—၄၈၄။ အစွောံ။) = “လယ်၏အရှေ့မြောက်အရပ်­ တစ်ခုသောတောင်ထိပ်မြေပြင်­ လက်ပံတောအဝန်းအဝိုင်းသည်ရှိ၏။”')
,(7203,3,1,'၁။ ရွှံ့ညွန်တော။ စိမ့်တောလွင်ပြင်။','“ပ္ဍဲအရှာံကီု၊ ဒမြီုရုက္ခ။” (လိက်သၚ်ဂဒါ။ သဳလဝန္တ။) =“သစ်တောအဝန်းအဝိုင်းအာရာမ်­။”')
,(7203,3,1,'၁။ ရွှံ့ညွန်တော။ စိမ့်တောလွင်ပြင်။','“ဒမြီုဓိတာန်၊ နွံဥဒျာန်မွဲ။” (လိက်ပထမဗောဓိ။ မၚ်ဍိက်လ။) = “အင်ကြင်းပင်အဝန်းအဝိုင်း­ ဥယျာဉ်တစ်ခုရှိ၏။”')
,(7203,3,1,'၁။ ရွှံ့ညွန်တော။ စိမ့်တောလွင်ပြင်။','‘ဒရီု—၂ (န) ၂) ’ နှင့်အတူတူ။')
,(7204,3,4,'‘ဒရီု’ (ကြိ) နှင့်အတူတူ။',NULL)
,(7205,3,4,'စည်းဝေးတိုင်ပင်သည်။','‘ဒရီုဟီု’ နှင့်အတူတူ။')
,(7205,3,4,'စည်းဝေးတိုင်ပင်သည်။','“ကမၠတ်တံဂှ် ဒမြီုဟီုတုဲ ဍေံအာကၠေံရ။” (ဇ—၂၆။ အစွောံ။) = “ခိုးသူတို့သည် စည်းဝေးတိုင်ပင်ကုန်၍ သွားကြကုန်၏။”')
,(7206,3,4,'တဖြုတ်ဖြုတ်ကျသည်။ တဖြုတ်ဖြုတ်ကြွေလွင့်သည်။','“စုဏ္ဏာနိ။ ၚ်ကြကောတ်ဂမၠိုၚ်ရဴသၠာဒိုၚ်။ ပတန္တိ။ ပ္ဍံဒတုံဓမြုဲစှ်ေအိုတ်ရ။” (တြာဲဝိနယသၚ်ရိုဟ်ဂြဳ။ စန္ဒိမာ။) = “ဗောက်ဖတ်ကဲ့သို့သော အမှုန်များသည် တဖြုတ်ဖြုတ်ကြွေလွင့်ကျကုန်၏။”')
,(7207,3,3,'ကြမ်းကြုတ်သော။ ခက်ထန်သော။','ကလော်ဒမြိုဟ် = ကြမ်းကြုတ်သောဘီလူး။')
,(7207,3,3,'ကြမ်းကြုတ်သော။ ခက်ထန်သော။','ကၠဒမြိုဟ် = ကျားဆိုး။')
,(7207,3,3,'ကြမ်းကြုတ်သော။ ခက်ထန်သော။','ချေံဒမြိုဟ် = မြင်းဆိုး၊ မြင်းကြမ်း။')
,(7207,3,3,'ကြမ်းကြုတ်သော။ ခက်ထန်သော။','မၞိဟ်ဒမြိုဟ် = ရက်စက်ကြမ်းကြုတ်သောလူ။')
,(7207,3,3,'ကြမ်းကြုတ်သော။ ခက်ထန်သော။','ဒေပ်စိုတ်ဒမြိုဟ် = ကြမ်းကြုတ်သောစိတ်ရှိသည်။')
,(7207,3,3,'ကြမ်းကြုတ်သော။ ခက်ထန်သော။','“စိၚ်တၠသဳလဂှ် ဟွံမွဲတုဲစိၚ်ဒမြိုဟ်မွဲ ကၠုၚ်စိုပ်ဒၞာဲဂှ်ရ။” (ဇ—၂၇၈။ အစွောံ။) = “ထိုသီလရှိသောဆင်မရှိသည့်နောက်တစ်ခုသောကြမ်းသောဆင်သည် ထိုနေရာသို့လာရောက်၏။”')
,(7207,3,3,'ကြမ်းကြုတ်သော။ ခက်ထန်သော။','“ကလော်ဂမၠိုၚ် ထေဲပၞတ်ကဵုဗောဓိသတ်တုဲ ကလော်ဂမၠိုၚ် ပြာပ်အာဂြိုပ်ဟေမဝန်တုဲ အာကော်နၚ်ကလော်ဒမြိုဟ်မွဲတုဲ ကဵုကၠုၚ်ဂစိုတ်ဗောဓိသတ်ရ။” (ဇ—၃၄၇။ အစွောံ။) = “ဘီလူးတို့သည် ဘုရားလောင်းအား အမျက်ထွက်၍ ဟိမဝန္တာ­ ဘီလူးအစည်းအဝေးသို့သွား၍ ဘုရာလောင်းကို သတ်စိမ့်သောငှာ ကြမ်းကြုတ်သောဘီလူးတယောက်ကို စေကုန်၏။” (ညောင်ကန်)')
,(7207,3,3,'ကြမ်းကြုတ်သော။ ခက်ထန်သော။','“ဣသိဒမြိုဟ်မွဲ ဍေံဟွံမွဲကဵုဓဝ်ကရုဏာပ္ဍဲသတ်ဂှ် ဂ္ၚေၚ်ကၠုၚ်စိုပ်ဋ္ဌာန်သဝ်ရဝကာ်ရ။” (ဇ—၄၃၈။ အစွောံ။) = “ကြမ်းကြုတ်သောကရုဏာတရားကင်းသော တစ်ယောက်သောရသေ့သည် လှည့်လည်လတ်သော် ထိုခါငှက်ရှိရာအရပ်သို့ ရောက်လာ၏။”')
,(7207,3,3,'ကြမ်းကြုတ်သော။ ခက်ထန်သော။','“အပသုံဝွံ ပကဵုဍေံပသၟိၚ် ဍေံဝွံ လက်သန်မၞိဟ်ဒမြိုဟ်ရောၚ်”တၠညးစိၚ်ဗ္တာၚ်ဂး။ (အကြီုရာဇာဓိရာဇ်) = “အပသုံကို မင်းမပြုစေနှင့်။ သူသည် ကြမ်းကြုတ်သောလူ၏လက္ခဏာရှိ၏။”')
,(7207,3,3,'ကြမ်းကြုတ်သော။ ခက်ထန်သော။','‘ဒြိုဟ်’ (ကြိ) လည်းရှု။')
,(7208,3,1,'ဓါးပြ။ ဒမြ။','(ကြိ) ဓါးပြတိုက်သည်။ ဒမြတိုက်သည်။')
,(7208,3,1,'ဓါးပြ။ ဒမြ။','“ဒမၠမသုန်ကၠံဂှ် ဍေံကၠုၚ်ဒမၠကွဳဂှ်—။” (ဇ—၇၆။ အစွောံ။) = “ငါးရာကုန်သောဓါးပြတို့သည် ထိုလှည်းကို ဓါးပြတိုက်အံ့သောငှာ လာ၏။”')
,(7208,3,1,'ဓါးပြ။ ဒမြ။','ဒမၠစ = ဓါးပြတိုက်စားသည်။')
,(7208,3,1,'ဓါးပြ။ ဒမြ။','“မၞိဟ်မရာတ်ပအောဝ်ဏာတုဲ ကဵုအာဒမၠစပ္ဍဲမုဟ်ရးကၠာရအဴ” အမာတ်ဂး။ (ဇ—၅၁။ အစွောံ။) = “အရှင်မင်းကြီး၏ လူများကိုစေလွှတ်၍တိုင်းစွန်အရပ်တို့­ သွား၍ဓါးပြတိုက်စေလော့” ဟုအမတ်ဆို၏။')
,(7209,3,5,'အမြဲ။ ထာဝစဉ်။','“ကဵုတဴဒါန်ဒမၠိရ။” (ဓမ္မဒဳပနဳ။ မာံရွှေငိုး။) = “အမြဲအလှူပေး၏။”')
,(7209,3,5,'အမြဲ။ ထာဝစဉ်။','“တဝှ်ဗုဒ္ဓ၊ သၟတ်မၚ်မွဲညိ။ ဒမၠိကာလ။” (လိက်သောဝိန်ဇဲယ။ မာံရောဂေါ။) = “ဗုဒ္ဓ၏ဟောကြားချက်ကို မဖြစ်မနေအားထုတ်၍ အစဉ်အမြဲစောင့်စည်းပါ။”')
,(7210,3,1,'အမှောင်။ မှောင်မဲခြင်း။ မှောင်မိုက်ခြင်း။','ဗ္တမ်ဒမၠု = မှောက်မိုက်သောည။')
,(7210,3,1,'အမှောင်။ မှောင်မဲခြင်း။ မှောင်မိုက်ခြင်း။','ဂၠံဒမၠု = အမှောင်ထု။')
,(7210,3,1,'အမှောင်။ မှောင်မဲခြင်း။ မှောင်မိုက်ခြင်း။','‘ပျးကၠေံဒမၠု’ = ‘အမှောင်ကိုခွင်း၍ လင်းစေသည်။’')
,(7210,3,1,'အမှောင်။ မှောင်မဲခြင်း။ မှောင်မိုက်ခြင်း။','“ကျာ်သ္ဍဴလောက၊ ပျးလဝ်ဒမၠု။” (လိက်ဗောဓိသတ်စှ်။ ပဏ္ဍိတ။) = “လောကမီးရှူးတန်ဆောင်ဖြစ်တော်မူသော မြတ်စွာဘုရားသည် (မောဟ) အမှောင်ကိုခွင်း၍ လင်းစေတော်မူ၏။”')
,(7211,3,1,'စိတ်အမှောင်။ မှောင်မိုက်သောစိတ်။ မောဟဖုံးလွှမ်းသောစိတ်။','“ဒလုစိုတ်ညး၊ သၟိက်စဳပျးလဝ်။” (လိက်ဗောဓိသတ်စှ်။ ပဏ္ဍိတ။) = “သူတစ်ပါးတို့၏ မောဟစိတ်အမှောင်ကို အလင်းပြလိုပါ၏။”')
,(7212,3,1,'မျက်မမြင်။ မျက်စိကန်းသူ။','“(ဗောဓိသတ်သၟိၚ်စိၚ်) ဥပ္ပကာတဴမိဒမၠုမတ်ရ။” (ဇ—၄၅၅။ အစွောံ။) = “ဘုရားလောင်းဆင်မင်းသည် မျက်မမြင်မိခင်ကို ပြုစုလုပ်ကျွေး၏။”')
,(7212,3,1,'မျက်မမြင်။ မျက်စိကန်းသူ။','“ဂုတ္တိလကုမာဝွံ ဥပ္ပကာဒၟံၚ်မိကဵုမ ဒမၠုမတ်ၜါရ။” (ဇ—၂၄၃။ အစွောံံ။) = “ဂုတ္တိလလုလင်သည်မျက်မမြင်မိဘနှစ်ပါးကို မွေးမြူပြုစုနေ၏။”')
,(7212,3,1,'မျက်မမြင်။ မျက်စိကန်းသူ။','“ညံၚ်ရဴဒမၠုမတ် မဟွံမွဲကဵုဒစုန်ပသဲဂှ်ကီု။” (ဇ—၅၂၁။ အစွောံ။) = “တောင်ဝှေးမရှိသော မျက်မမြင်သောသူကဲ့သို့။”')
,(7213,3,3,'ဆော့သော။ လျှပ်ပေါ်သော။','“ကၞုဲဒမၠာန်မွဲဂှ် ဍေံပြာပ်ကၠုၚ်ပ္ဍဲဘာဣသိတံတုဲ ဍေံရိုဟ်ထောံကၠေံ သၠကမဳပဏ္ဏသာဘာဣသိတံ—။” (ဇ—၁၇၅။ အစွောံ။) = “တစ်ခုသောဆော့သောမျောက်သည် ရသေ့တို့၏ကျောင်းသင်္ခမ်းသို့လာ၍ ကျောင်းသင်္ခမ်း၏ သစ်ရွက်အမိုးကို ဖြိုဖျက်ပစ်၏။”')
,(7213,3,3,'ဆော့သော။ လျှပ်ပေါ်သော။','‘ဂၠာန်’ (ကြိ) လည်းရှု။')
,(7214,3,4,'ခြုံသည်။ လွှမ်းအုပ်သည်။','‘ဂလီု')
,(7214,3,4,'ခြုံသည်။ လွှမ်းအုပ်သည်။','ဒလီု’ (ကြိ) နှင့်အတူတူ။')
,(7214,3,4,'ခြုံသည်။ လွှမ်းအုပ်သည်။','“ဒမၠီုယာတ်ပိက်၊ တိက်ဒၟံၚ်အပ္ဍဲ။” (လိက်သုပိဏ္ဏကုမ္မာ။ မၚ်သၚ်ကြာ။) = “ပိတ်စောင်ကိုခြုံ၍ အထဲမှာအိပ်နေ၏။”')
,(7214,3,4,'ခြုံသည်။ လွှမ်းအုပ်သည်။','“က္တဵုလုပ်တိက်ကၞပ်၊ ယာတ်ဥုပ်ဒမၠီု။” (လိက်သုပိဏ္ဏကုမ္မာ။ မၚ်သၚ်ကြာ။)')
,(7215,3,4,'ချုပ်နှောင်သည်။ နှောင်ဖွဲ့သည်။','“(နလဟီုရမျှာၚ်) ဒှ်သာယေန်ကတောဝ်ညး ရဴမဂၟာ်ဒါမ်လဝ်စိုတ်ညးကီု။” (ဇ—ဝေသန္တဝ်။ အစွောံ။) = “သာယာနာပျော်ဖွယ်သောစကားဖြင့် သူတစ်ပါးစိတ်ကို ချိတ်၍နှောင်ဖွဲ့ထားဘိသကဲ့သို့။”')
,(7216,3,9,'မီးစသည်ကို ရေတွက်ရာတွင် သုံးသောစကားလုံး။ အပါး။ အဖြာ။','တေဇောမွဲဒေမ် = တေဇောမီးတစ်ဖြာ။')
,(7217,3,1,'မီးအိမ်။',NULL)
,(7218,3,4,'လဲသည်။ လဲကျသည်။','‘တၞံဆုဒေါမ်စှ်ေ။’ = ‘သစ်ပင်လဲကျသည်။’')
,(7219,3,4,'လဲပြိုကျိုးကျသည်။ ကျိုးပြတ်လဲကျသည်။','“တၞံဆုမဒၟံၚ်ပ္ဍဲဝါတဂါ မွဲတၞံၜါတၞံတံဂှ် ကျာဇၞော်ပိုက်ကၠုၚ်တုဲ ဒးဒေါမ်ကဝ်အာဟေၚ်။” (ဇ—၇၄။ အစွောံ။) = “လွင်ပြင်တွင်ရှိသော တစ်ပင်နှစ်ပင်တည်းသော သစ်ပင်တို့သည် လေပြင်းတိုက်ခတ်လာသော် ကျိုးပြတ်လဲကျသွားရ၏။”')
,(7220,3,4,'လဲပြိုဖိမိသည်။','“ဒးလဗိုတ်ကျာ တၞံဆုကဝ်အာ တၞံဆုဒေါမ်ဍိုက်ဒးတုဲသ္ၚိတာဲဂှ် လီုသရိုဟ်အာရ။” = “လေမုန်တိုင်းသင့်၍ သစ်ပင်ကျိုးကျရာ သစ်ပင်လဲပြိုဖိမိသဖြင့်တဲအိမ်ပြိုပျက်သွား၏။”')
,(7221,3,4,'လဲပြိုသည်။','“ညံၚ်တၞံဗြာတ်ထဝ် မဒးဂဝဝ်မုက်ကျာဝေရံၚ် ကျာဗရာတ်တုဲ ရဴမဒေါမ်တၟဝ်စှ်ေအာကီုရ။” (ဇ—နာရဒ။ အစွောံ။) = “လေပြင်းထိသောရွှေငှက်ပျောပင်သည် လဲပြိုကျသွားရသကဲ့သို့။”')
,(7222,3,4,'တည်းခိုသည်။ နားနေသည်။','“(နူဂြိုပ်ဟေမဝန်ဂှ် ဣသိ) စဴကၠုၚ်ဍုၚ်ဗာရာဏသဳ ဒီုဒၟံၚ်ပ္ဍဲဥဒျာန်သၟိၚ်။” (ဇ—၁၄၉။ အစွောံ။) = “ရသေ့သည် ဟိမဝန္တာတောမှ ဗာရာဏသီပြည်သို့ ပြန်လာပြီးလျှင် မင်း၏ဥယျာဉ်­ တည်းခိုနားနေ၏။”')
,(7222,3,4,'တည်းခိုသည်။ နားနေသည်။','“တ္ၚဲဝွံ ယာံဗမၞးဒီုဒေါဝ်တရဴမ္ဂး ဗမၞးဒးချိုတ်ရ။” (ဇ—၄ဝ၂။ အစွောံ။) = “အကယ်၍ပုဏ္ဏားသည် ယနေ့လမ်းခုလတ်­နားနေသော် ပုဏ္ဏား သေရလတ္တံ့။”')
,(7222,3,4,'တည်းခိုသည်။ နားနေသည်။','“ပ္ဍဲဇြပ်ဂှ် ခါရဒးဂၞပ် အာဒီုဂွံရ။” (ဇ—၁၅၅။ အစွောံ။) = “ထိုဇရပ်­ အကယ်၍အလိုရှိပါမူ သွား၍တည်းခိုနိုင်ပါ၏။”')
,(7223,3,4,'(လမ်းခရီးတွင်) ခေတ္တတည်းခိုသည်။ နားခိုသည်။','“ညးကၠုၚ်အာဒီုဒက် ပ္ဍဲဇြပ်ဂှ်တုဲပုၚ်ကွာၚ်ယာဂုကဵုဒါန်—။” (ဇ—၃၁။ အစွောံ။) = “ထိုဇရပ်­ သွားလာတည်းခိုသူများအား ထမင်း၊ မုန့်၊ ယာဂုတို့ကို အလှူပေး၏။”')
,(7223,3,4,'(လမ်းခရီးတွင်) ခေတ္တတည်းခိုသည်။ နားခိုသည်။','“ဂြောဝ်သေဋ္ဌဳဗာရာဏသဳဂှ် သွက်သတ္တံမဒီုဒက်ဂှ် နပရေဟ်မွဲ ဍေံကွက်လဝ်ရ။” (ဇ—၃၇၅။ အစွောံ။) = “ဗာရာဏသီသူဋ္ဌေး၏စားဖိုမှူးသည် ငှက်သတ္တဝါများနားခိုရန်အတွက် အသိုက်တောင်းတစ်ခုကို ချိတ်ဆွဲထား၏။”')
,(7223,3,4,'(လမ်းခရီးတွင်) ခေတ္တတည်းခိုသည်။ နားခိုသည်။','“ပ္ဍဲကၞာၚ်ဗောဓိတံဂှ်ဂစေံကၠုၚ်ဒီုဒက်ဒၟံၚ်—။” (ဓမ္မဒဳပနဳ။ မာံရွှေငိုး။) = “ဗောဓိပင်အကိုင်းတို့­ ငှက်များလာရောက်ခိုနားနေကြ၏။”')
,(7224,3,5,'တိုးသောအသံဖြင့်။ တိုးတိုး။','“ညးဂမၠိုၚ်သ္ဂောံမိၚ် ဟီုရမ်သာၚ်ထတ်တ်ညိ၊ လ္ပဟီုဒၟံၚ်ဒီုဒီုညိ။” = “လူအများကြားအောင် အသံကျယ်ကျယ်ဖြင့်ပြောပါ၊ တိုးတိုးမပြောပါနှင့်။”')
,(7224,3,5,'တိုးသောအသံဖြင့်။ တိုးတိုး။','“အဲဂွံမိၚ်ကွေံ၊ ဗှ်ေဟီုဒီုဒီု။” (လိက်သၟိၚ်ဇဲယဒတ္တ) = “နင်တိုးတိုးပြောသည်ကို ငါတကယ်ကြားရသည်။”')
,(7225,3,4,'ငှက်ကဲ့သို့အိပ်စက်သည်။',NULL)
,(7226,3,1,'ပိုက်ဆံအိတ်ပါသောခါးပတ်။ အိတ်။','“ထဝ်သြန်ပေၚ်ဒဲါ ယိုက်ပ္တိုန်နၚ်။” (ဇ—မဟောဟ်သဓ။ အစွောံ။) = “ရွှေငွေအိတ်အပြည့် သယ်ဆောင်ယူတင်လာ၏။”')
,(7226,3,1,'ပိုက်ဆံအိတ်ပါသောခါးပတ်။ အိတ်။','“ယာံအဲချိုတ်ရ၊ ယက္ခစၞာဲ။ ဖျုန်ဂြိုဟ်ကြုတ်အဲ၊ ဍေံပြိုက်ပ္ဍဲဒဲါ။” (လိက်ဝိဓူရ) = “ငါသေလျှင် ဤဘီလူးစဉ်းလဲသည်ငါ့အသားအသည်းအအူတို့ကို အိတ်ထဲထည့်လိမ့်မည်။”')
,(7227,3,1,'လူပျိုကြီး။ အပျိုကြီး။','ဗၠာဲဇၞော်ဒုဲ = အရွယ်လွန်သောလူပျိုကြီး။ လူပျိုဟိုင်း။')
,(7227,3,1,'လူပျိုကြီး။ အပျိုကြီး။','ဝုတ်ဇၞော်ဒုဲ = အရွယ်လွန်သောအပျိုကြီး။ အပျိုဟိုင်း။')
,(7228,3,1,'ဆောက်ပုတ်တစ်မျိုး။','လေံဒုဲပသဲ = သံဆောက်ပုတ်။')
,(7229,3,4,'ပိတ်သည်။ ဖုံးသည်။ ကာသည်။','ဒဝ်တရၚ် = တံခါးပိတ်သည်။')
,(7229,3,4,'ပိတ်သည်။ ဖုံးသည်။ ကာသည်။','ဒဝ်မတ် = မျက်စိကို ပိတ်ဖုံးသည်။')
,(7229,3,4,'ပိတ်သည်။ ဖုံးသည်။ ကာသည်။','ဒဝ်ကတောဝ် = နားကိုပိတ်သည်။')
,(7229,3,4,'ပိတ်သည်။ ဖုံးသည်။ ကာသည်။','ဒဝ်မုက် = မျက်နှာကိုဖုံးသည်။')
,(7229,3,4,'ပိတ်သည်။ ဖုံးသည်။ ကာသည်။','“ညးဒဝ်ကၠေံတရၚ်ဍုၚ်တုဲ လောပ်ဟွံဂွံ—။” (ဇ—၂၈၄။ အစွောံ။) = “မြို့တံခါးပိတ်လိုက်ပြီဖြစ်သဖြင့် ဝင်ခွင့်မရ။”')
,(7229,3,4,'ပိတ်သည်။ ဖုံးသည်။ ကာသည်။','“(သၟတ်ဗြဴဂှ်) ဍေံဒဝ်ကၠေံမုက်ဗမၞး—။” (ဇ—၆၂။ အစွောံ။) = “သူငယ်မသည် ပုဏ္ဏား၏မျက်နှာကို (အဝတ်ဖြင့်) ဖုံး၏။”')
,(7229,3,4,'ပိတ်သည်။ ဖုံးသည်။ ကာသည်။','“တမ္ၚာဂှ်လေဝ် (မတ်ဒွံဒးစုတ်ဓဂဵုဆု) စသိုၚ်ဒုက္ခဝေဒနာ မဇၞော်ကဵုဒြဟတ် ဒဝ်မတ်တိုန်ကၠုၚ်နူဍာ်—။” (ဇ—၁၃၉။ အစွောံ။) = “တံငါသည်သည်လည်း မျက်စိတို့သည် သစ်ၚုတ်နှင့်ခတ်မိ၍ ကြီးစွာသောဝေဒနာကို ခံစားရင်း မျက်စိတို့ကိုပိတ်ကာ ရေမှတက်လာ၏။”')
,(7229,3,4,'ပိတ်သည်။ ဖုံးသည်။ ကာသည်။','“(ညးဍုၚ်အိုတ်သီု) ဒ္ဂေတ်ဗက်ဂလာန်ဗောဓိသတ်တုဲ ဒဝ်ကၠေံကတောဝ်ဖအိုတ်ရ။” (ဇ—၂၄၁။ အစွောံ။) = “မြို့သူအပေါင်းတို့သည် ဘုရားလောင်းစကားကိုလိုက်နာ၍ အားလုံးနားတို့ကို ပိတ်ကြကုန်၏။”')
,(7230,3,4,'ပိတ်ဖုံးသည်။ ပိတ်ဆီးသည်။ ဖုံးကွယ်သည်။','“သၟိၚ်ဇၞော်မိၚ်ရော၊ ဒေါသဇတဝ်။ညံၚ်လံၚ်ဂျိဟော၊ မောဟဒဝ်က္ဍဝ်။ ဟွံဗစာအဴ၊ ကြဴဂတဓဝ်။” (လိက်ကောန်သၟိၚ်ပိ။ မာံခစုန်အံက်။) = “မင်းကြီးကြားသော် ဒေါသမာန်ဖြင့်တုန်လှုပ်ကာ အဆိပ်လောင်းသည့်နှယ် မောဟပိတ်ဖုံး၍ ရှေ့နောက်ကိုမဆင်ခြင်နိုင်။”')
,(7230,3,4,'ပိတ်ဖုံးသည်။ ပိတ်ဆီးသည်။ ဖုံးကွယ်သည်။','“ယွံအမာတ်မပ၊ တိက္ခပညာ။ ပသာ်ပိုဲသ္ပ၊ လေသမွဲမာ။ပိုဲသ္ဂောံတိုန်စိုပ်၊ ဗဒိုပ်ကညာ။ အမာတ်တိက္ခာ၊ မပိုၚ်ခြာလဝ်။ ဟီုကဵုညိရ၊ လ္ပဒဝ်က္ဍဝ်။” (လိက်ပဒုမဝတဳ) = “ထက်မြက်သောပညာရှိဖြစ်သော အိုအမာတ်၊ ကညာပျိုရှိရာအရပ်သို့ သွားရောက်နိုင်ရန် အဘယ်ဥပါယ်တံမျဉ်ကို ပြုရပါအံ့နည်း၊ အသင်ထက်မြက်သောအမတ် ဆင်ခြင်ပိုင်းခြားထားသည်ကို မပိတ်ဆီးမဖုံးကွယ်ဘဲ ငါ့အားပြောကြားပါလော့။”')
,(7230,3,4,'ပိတ်ဖုံးသည်။ ပိတ်ဆီးသည်။ ဖုံးကွယ်သည်။','“ဗွဲအဆတ်ရ၊ ဟီုပဒဝ်က္ဍဝ်။”= “အဟုတ်အမှန်အတိုင်း မဖုံးကွယ်ဘဲပြောပါ။”')
,(7231,3,1,'အလယ်။','‘ပ္ဍဲဒေါဝ်မှာသၟိတ်။’ (ဇ—၃၂၇။ အစွောံ။) = ‘သမုဒ္ဒရာလယ်­။’')
,(7231,3,1,'အလယ်။','(နဝိ) အလယ်ဖြစ်သော။')
,(7231,3,1,'အလယ်။','(ဝိ) အလယ်။')
,(7232,3,4,'မွေ့လျော်သည်။ ပျော်ရွှင်သည်။','“တၠအဲတံမကၠုၚ်ဍုၚ်လၚ်ကာဝွံ အဒဿဂြဳလေဝ် တၠအဲတံဇၞး၊ တမိန်ဍုၚ်လၚ်ကာလေဝ် တၠအဲတံသ္ဂောံ၊ ဂၞကျာ်သဳဒါ မစိုန်ဒှ်တဴသ္ဍိုက်တၠအဲလေဝ် တၠအဲသ္ဂောံဒေါဝ်မွဲသၞာရ” လၟဂးကဵုသၟိၚ်ရာံရ။ (သၠပတ်ဒ္ၚောဝ်သၜောံ) = “လင်္ကာပြည်သို့ သင်တို့လာသည်မှာ ဒဿဂီရိကိုလည်း သင်တို့အောင်နိုင်၏။ လင်္ကာပြည်ကိုလည်း သင်တို့ရ၏။ သင့်ချစ်သူဖြစ်သော သီဒါမိဖုရားနှင့်လည်း သင်အတူမွေ့လျော်ရ၏” ဟုမုဆိုးသည် ရာမမင်းအားပြော၏။')
,(7232,3,4,'မွေ့လျော်သည်။ ပျော်ရွှင်သည်။','“(သၟိၚ်ရာံ) သ္ဂောံဒေါဝ်ရေၚ်ကာန်မွဲသၞာ ဖဴဂၞကျာ်သဳဒါ အိုဟ်တၟိုဟ်စိုတ်သန်—။” (သၠပတ်ဒ္ၚောဝ်သၜောံ) = “ရာမမင်းသည် သီဒါမိဖုရားနှင့်တကွ အတူမွေ့လျော်ပေါင်းဖက်ရသဖြင့် အလွန်ဝမ်း မြောက်၏။”')
,(7233,3,1,'လမ်းခုလတ်။ သွားလာသည့် ခရီးလမ်းအကြား တစ်နေရာရာ။ လမ်းအကြား။','“စဴစိုပ်ဒေါဝ်တြဴဇူဒၟံၚ်—။” (ဇ—၂၂၃။ အစွောံ။) = “ပြန်လာရာလမ်းခုလတ်­ နားနေ၏။”')
,(7233,3,1,'လမ်းခုလတ်။ သွားလာသည့် ခရီးလမ်းအကြား တစ်နေရာရာ။ လမ်းအကြား။','“အဲအာဗၟတ်ဒၟံၚ်ဒေါဝ်တရဴဂှ်ရ။” (ဇ—၃၄၈။ အစွောံ။) = “ငါသွား၍ လမ်းအကြား­စောင့်နေမည်။”')
,(7233,3,1,'လမ်းခုလတ်။ သွားလာသည့် ခရီးလမ်းအကြား တစ်နေရာရာ။ လမ်းအကြား။','“ပ္ဍဲတရဴသၟိၚ်ၜိုပ်ထဝ် မဂ္ၚေၚ်ကၠုၚ်အာတဴဂှ် ပ္ဍဲဒေါဝ်တရဴဂှ် ဆုဗပုၚ်ဇၞော်မွဲတၞံနွံ။” (ဇ—၃၇ဝ။ အစွောံ။) = “ရွှေဟင်္သာမင်း သွားလာရာခရီး­ လမ်းခုလတ်­ ပေါက်ပင်ကြီးတစ်ပင်ရှိ၏။”')
,(7233,3,1,'လမ်းခုလတ်။ သွားလာသည့် ခရီးလမ်းအကြား တစ်နေရာရာ။ လမ်းအကြား။','‘ဘာ်တရဴ’ (န) လည်းရှု။')
,(7234,3,1,'နေ့လယ်။',NULL)
,(7235,3,1,'အလယ်။','‘ထဍဲဟာန်')
,(7235,3,1,'အလယ်။','သ္ဍဲဟာန်’ (န) ရှု။')
,(7236,3,1,'ပရိသတ်လေးပါးအလယ်။',NULL)
,(7237,3,1,'အလယ်။ အဝန်းအဝိုင်းအလယ်။ အသိုင်းအဝိုင်းအလယ်။','“ကောန်ဂဒေံမွဲက္တဵုဒှ်မၞိဟ် — ဒေါဝ်ဗၞဳပိုန်တသိုက်ရောၚ်။” (သၠပတ်စန္ဒဝတဳ) = “သမီးထွေးတော်တစ်ပါးသည်စည်းစိမ်ဘုံလယ်­ ဖွားမြင်လာ၏။”')
,(7237,3,1,'အလယ်။ အဝန်းအဝိုင်းအလယ်။ အသိုင်းအဝိုင်းအလယ်။','“ဒေါဝ်ဗနဳပုရိသာတ်ပန်။” = “ပရိသတ်လေးပါးအလယ်­။”')
,(7238,3,1,'၁။ တောင်။','ဒဵုတၟအ် = ကျောက်တောင်။')
,(7238,3,1,'၁။ တောင်။','၂။ ကုန်းကြည်း။')
,(7238,3,1,'၁။ တောင်။','သတ်ပ္ဍဲဒဵုဒစိတ်ကိုတ် =ကုန်းကြည်း­နေသော ကိုးကုဋေသောသတ္တဝါ။')
,(7239,3,1,'တောင်ကတုံး။ တောင်ဦးပြည်း။ သစ်ပင်မြက်ပင်များမပေါက်သောတောင်။ (ပါဠိ—မုဏ္ဍပဗ္ဗတ)',NULL)
,(7240,3,1,'မီးတောင်။',NULL)
,(7241,3,6,'တိုင်အောင်။ အထိ။','“ပိုဲအာစိုပ်ဒဵုဍုၚ်အဝရ။” = “ကျွန်တော်တို့သည် မန္တလေးမြို့တိုင် ရောက်သွားသည်။”')
,(7241,3,6,'တိုင်အောင်။ အထိ။','(သဗဓ) တိုင်အောင်။')
,(7241,3,6,'တိုင်အောင်။ အထိ။','“ညးမၚ်ဒၟံၚ်ဒဵုကဵုနာဍဳတက်ပိရ။” = “နာရီသုံးချက်တီးသည့်တိုင်အောင် သူစောင့်နေသည်။”')
,(7241,3,6,'တိုင်အောင်။ အထိ။','“စဒဵုကဵုအိုတ်ညိ။” = “ကုန်သည့်တိုင်အောင်စားပါ။”')
,(7241,3,6,'တိုင်အောင်။ အထိ။','“အာဒဵုစိုပ်ညိ။” = “ရောက်သည့်တိုင်အောင် သွားပါ။”')
,(7242,3,4,'ဖြစ်သည်။','“ဍေံဂှ် ဒှ်ဒေံအဲအရၚ်ရ။” = “သူသည် ကျွန်တော့်ညီအရင်းဖြစ်သည်။”')
,(7243,3,9,'၁။ ပြုနိုင်စွမ်း၊ ဖြစ်နိုင်စွမ်းရှိသည်ကို ပြသောစကားလုံး။ တတ်သည်။ (ကြိနောက်ဆက်)','“ကောန်ၚာ်ဗှ်ေကွာ်ဒှ်ရဟာ။” = “နင့်ကလေး လျှောက်တတ်ပြီလား။”')
,(7243,3,9,'၁။ ပြုနိုင်စွမ်း၊ ဖြစ်နိုင်စွမ်းရှိသည်ကို ပြသောစကားလုံး။ တတ်သည်။ (ကြိနောက်ဆက်)','၂။ ပြုလေ့ပြုထ ဖြစ်လေ့ဖြစ်ထရှိသည်ကို ပြသောစကားလုံး။ တတ်သည်။—လေ့ရှိသည်။ (ကြိနောက်ဆက်)')
,(7243,3,9,'၁။ ပြုနိုင်စွမ်း၊ ဖြစ်နိုင်စွမ်းရှိသည်ကို ပြသောစကားလုံး။ တတ်သည်။ (ကြိနောက်ဆက်)','“သ္ၚိရဲဍေံမာံမန်ဆာန်ဂှ် ဍေံအာဝေၚ်စဒှ်ရ။” = “သူ့သူငယ်ချင်း မင်းမွန်ချမ်းအိမ်ကို သူသွားလည်တတ်သည်။”')
,(7243,3,9,'၁။ ပြုနိုင်စွမ်း၊ ဖြစ်နိုင်စွမ်းရှိသည်ကို ပြသောစကားလုံး။ တတ်သည်။ (ကြိနောက်ဆက်)','“ယွံခမဳ၊ တၠပၞောတ်ဒှ်ဂှ် ဆလၟုဟ်ဝွံဟွံသေၚ်၊ ပ္ဍဲဘဝမတုဲတေံလေဝ် ပၞောတ်ဒှ်တုဲရ” ကျာ်တြဲဂး။ (ဇ—၂၅၂။ အစွောံ။) = “ဤရဟန်းသည် ယခုအခါ­သာလျှင် အမျက်ထွက်တတ်သည်မဟုတ်သေး။ ရှေး­လည်း အမျက်ထွက်တတ်သည်သာလျှင်တည်း။” (ညောင်ကန်)')
,(7243,3,9,'၁။ ပြုနိုင်စွမ်း၊ ဖြစ်နိုင်စွမ်းရှိသည်ကို ပြသောစကားလုံး။ တတ်သည်။ (ကြိနောက်ဆက်)','၃။ ဆောင်ရွက်မှုတစ်စုံတစ်ရာ ထမြောက်ကြောင်းဖော်ပြသည့်စကားလုံး။ ဖြစ်သည်။ (ကြိရှေ့ဆက်)')
,(7243,3,9,'၁။ ပြုနိုင်စွမ်း၊ ဖြစ်နိုင်စွမ်းရှိသည်ကို ပြသောစကားလုံး။ တတ်သည်။ (ကြိနောက်ဆက်)','“တ္ၚဲဏအ် ဗှ်ေဒှ်အာဘာကီုဟာ။” = “ဒီနေ့ နင်ကျောင်းသွားဖြစ်သလား။”')
,(7243,3,9,'၁။ ပြုနိုင်စွမ်း၊ ဖြစ်နိုင်စွမ်းရှိသည်ကို ပြသောစကားလုံး။ တတ်သည်။ (ကြိနောက်ဆက်)','“ဍေံဟွံဒှ်ကၠုၚ်ရောၚ်။” = “သူမလာဖြစ်တော့ပါ။”')
,(7243,3,9,'၁။ ပြုနိုင်စွမ်း၊ ဖြစ်နိုင်စွမ်းရှိသည်ကို ပြသောစကားလုံး။ တတ်သည်။ (ကြိနောက်ဆက်)','၄။ ထောက်ထားငဲ့ညှာခြင်းမရှိဟူသော အနက်ဖြင့် ကြိယာကိုထောက်ကူသောစကားလုံး။—ရက်သည်။')
,(7243,3,9,'၁။ ပြုနိုင်စွမ်း၊ ဖြစ်နိုင်စွမ်းရှိသည်ကို ပြသောစကားလုံး။ တတ်သည်။ (ကြိနောက်ဆက်)','“မူဟိုတ်သၟိၚ်မရံၚ်ဗဵု ဒဒိုက်ကောန်ၜါဒှ်ရော။” (ဇ—ဝေသန္တဝ်။ အစွောံ။) = “သားသမီးတော်နှစ်ယောက်တို့၏ဒုက္ခကို ဖခမည်းတော် အဘယ်ကြောင့်ကြည့်ရက်လေသနည်း။”')
,(7243,3,9,'၁။ ပြုနိုင်စွမ်း၊ ဖြစ်နိုင်စွမ်းရှိသည်ကို ပြသောစကားလုံး။ တတ်သည်။ (ကြိနောက်ဆက်)','“ပသာ်သၟိၚ်မ ဓဇန်ကဵုပိုဲကောန်ၜါဒှ်ရော။” (ဇ—ဝေသန္တဝ်။ အစွောံ။) = “ခမည်းတော်မင်းသည် သားသမီးတော်ဖြစ်သော အကျွန်ုပ်တို့နှစ်ဦးအား အဘယ်ကြောင့်ရက်စက်နိုင်ရက်လေသနည်း။”')
,(7244,3,4,'အငတ်ဘေးဆိုက်သည်။ အငတ်ဘေးကြုံသည်။',NULL)
,(7245,3,4,'အကြွေးတင်သည်။',NULL)
,(7246,3,4,'ပြဿနာဖြစ်သည်။ အငြင်းအခုံဖြစ်သည်။ အမှုအခင်းဖြစ်ပွားသည်။',NULL)
,(7247,3,4,'ပြဿနာဖြစ်သည်။ အငြင်းအခုံဖြစ်သည်။ အချင်းများသည်။','“(သမ္ဘာတမ္ၚာဂှ်) သေက်ဇဵုကဵုညး (ဝုတ်ဒိုဟ်) ဒှ်ဂလာန်စိုပ်တလခွာ ကျဂဗုတ် ညးရပ်ဒက်လဝ်။” (ဇ—၁၃၉။ အစွောံ။) = “တံငါသည်မယားသည် အိမ်နီးချင်းတို့နှင့် ခိုက်ရန်ပြု၍ အချင်းများကြရာ ရွာစားထံသို့ရောက်၍ တရားရှုံးသဖြင့် ဖမ်းဆီးချုပ်နှောင်ခြင်းခံရ၏။”')
,(7248,3,4,'အကျိုးဖြစ်သည်။ ကျေးဇူးဖြစ်သည်။',NULL)
,(7249,3,4,'အကျိုးဖြစ်ထွန်းသည်။ ကောင်းကျိုးဖြစ်သည်။',NULL)
,(7250,3,4,'ဆန္ဒချင်းတူညီသည်။ တစ်စိတ်တစ်ဝမ်းတည်းဖြစ်သည်။ စိတ်တူသဘောတူဖြစ်သည်။','“ပ္ဍဲဍုၚ်သာရဝှ် ကောန်သေဋ္ဌဳၜါဂှ် မဒှ်သဟာဲကဵုရၚ်သ္ကံဂှ်ရ၊ မဒှ်ဂၞပ်မွဲတုဲ ဂရၚ်နၚ်ညးဍုၚ်ဂမၠိုၚ်တုဲနဒါန်ပရိက္ခရာအိုဿီုဂှ် စဳရေၚ်လဝ်တုဲ (ကဵုဒါန်ကျာ်ကေုာံသၚ်ရ။)” (ဇ—၁၈ဝ။ အစွောံ။) = “သာဝတ္ထိပြည်­ သူကြွယ်သားဖြစ်ကုန်သော အဆွေခင်ပွန်းနှစ်ဦးတို့သည် တစ်စိတ်တစ်ဝမ်းတည်းဖြစ်ကုန်၍ မြို့သားများကိုနှိုးဆော်ကာ ခပ်သိမ်းကုန်သောပရိက္ခရာတို့ကို စီရင်ကုန်၍ ဘုရားနှင့်တကွ သံဃာတော်များအား အလှူဒါနပြု၏။”')
,(7250,3,4,'ဆန္ဒချင်းတူညီသည်။ တစ်စိတ်တစ်ဝမ်းတည်းဖြစ်သည်။ စိတ်တူသဘောတူဖြစ်သည်။','‘ဒှ်မွဲဂၞပ်’ (ကြိ) လည်းရှု။')
,(7251,3,4,'ခိုက်ရန်ဖြစ်သည်။',NULL)
,(7252,3,4,'စိတ်ပင်ပန်းသည်။ စိတ်ဆင်းရဲသည်။',NULL)
,(7253,3,4,'ချမ်းသာသည်။',NULL)
,(7254,3,4,'ကိုယ်ချမ်းသာသည်။',NULL)
,(7255,3,4,'စိတ်ချမ်းသာသည်။',NULL)
,(7256,3,4,'အိမ်ထောင်ကျသည်။','“ဒေံတြုံဂှ် စဳရေၚ်ကဵုဒှ်တၠဂယိုင်တုဲ—။” (ဇ—၃၉ဝ။ အစွောံ။) = “ညီအား စီရင်အိမ်ထောင်ပြုစေပြီးလျှင်—။”')
,(7256,3,4,'အိမ်ထောင်ကျသည်။','“ညးၜါဂှ် ဒှ်တၠဂယိုင် ဒၟံၚ်မွဲစွံရ။” (ဇ—၄၂၁။ အစွောံ။) = “ထိုသူနှစ်ဦးတို့သည် အိမ်ထောင်ကျ၍ အတူတကွနေကြ၏။”')
,(7257,3,4,'အတည်ဖြစ်သည်။ အထမြောက်သည်။','“ဂလာန်ညးပၠန်၊ အန်ကဵုပညာ။ ဒှ်ဒတန်ကၠာ၊ ဗိုန်ဗတ်အာရ။” (လိက်သၠပတ်သၟိၚ်ပဿိုန်) = “ပညာနည်းသောသူတို့၏စကားသည် အတည်ဖြစ်၍ မြဲမြံသွားကုန်၏။”')
,(7258,3,4,'အကြံအောင်သည်။ ကြံစည်ထားသည့်အတိုင်း အပြီးသို့ရောက်သည်။',NULL)
,(7259,3,4,'အကျိုးဖြစ်သည်။ အကျိုးရှိသည်။',NULL)
,(7260,3,4,'ဒုက္ခဖြစ်သည်။ ဒုက္ခရောက်သည်။',NULL)
,(7261,3,4,'စိတ်ဆင်းရဲသည်။',NULL)
,(7262,3,4,'ဒေါသဖြစ်သည်။ ဒေါသထွက်သည်။',NULL)
,(7263,3,4,'အပြစ်ဖြစ်သည်။ အပြစ်ကျူးလွန်သည်။',NULL)
,(7264,3,4,'(ဥစ္စာ) စုဆောင်းရရှိသည်။ စုမိသည်။','“ပၠေၚ်အောန်က္ဍၚ် ဒှ်ဒြပ်ဂၠိုၚ်က္ဍၚ်ရ။” = “အသုံးအဖြုန်းနည်းလေလေ ဥစ္စာစုဆောင်းရမှု များလေလေဖြစ်သည်။”')
,(7265,3,4,'၁။ (အနာ) ပြည်တည်သည်။ ပြည်ဖြစ်သည်။','ဒှ်သရပတိုဟ် = အနာပြည်တည်သည်။')
,(7265,3,4,'၁။ (အနာ) ပြည်တည်သည်။ ပြည်ဖြစ်သည်။','၂။ မှိုစွဲသည်။ မှိုတက်သည်။')
,(7265,3,4,'၁။ (အနာ) ပြည်တည်သည်။ ပြည်ဖြစ်သည်။','“ပုၚ်ပ္ဍဲဘာဇနဂှ် သအုဲကၟုဒှ်အာပ္တိုဟ်ရောၚ်။” (ဇ—၂၅၁။အစွောံ။) = “သပိတ်ထဲမှထမင်းသည် ပုပ်သိုး၍မှိုတက်ကုန်၏။”')
,(7266,3,4,'(တစ်ဦးနှင့်တစ်ဦး) ပြဿနာဖြစ်သည်။ အချင်းများသည်။ စကားများသည်။','“သစ္ဆုထမၞာတ် ကတၚ်အာမ္ဂး ဋ္ဌာန်ဂှ် ဒှ်ပရူပရာရ။” (လောကသိဒ္ဓိ။ အစွောံ။) =“ချိုသောသစ်သီး ခါးသွားပါက ထိုအရပ်တွင် ပြဿနာဖြစ်လိမ့်မည်။”')
,(7267,3,4,'ဘေးဖြစ်သည်။ ဘေးတွေ့သည်။',NULL)
,(7268,3,4,'စိတ်အနှောက်အရှက်ဖြစ်သည်။ စိတ်ဆင်းရဲသည်။',NULL)
,(7269,3,4,'အိမ်ထောင်ကျသည်။ လင်သားရသည်။','“ကၠာနူကောန် (ဗြဴ) ပိဝွံ ဟွံဒှ်ပရေၚ်တၠသ္ၚိဂှ် ဗောဓိသတ်ပကာဂစိုတ်။” (ဇ—၁၃၆။ အစွောံ။) = “ထိုသုံးယောက်ကုန်သော သမီးတို့သည် လင့်အိမ်သို့မရောက်မီလျှင် ဘုရားလောင်းသည် စုတေ၍—။” (ညောင်ကန်)')
,(7270,3,4,'စစ်ဖြစ်သည်။ စစ်မက်ဖြစ်ပွားသည်။',NULL)
,(7271,3,4,'ပမာဏဖြစ်သည်။ လက်ခံလောက်သည်။ ယုတ္တိတန်သည်။','“ဂလာန်ဂှ် ဟွံဒှ်ဗၞတ်ရ။” = “ထိုစကားသည် ယုတ္တိမတန် လက်ခံနိုင်လောက်သည့် အတိုင်းအတာမဖြစ်။”')
,(7272,3,4,'(ယောကျာ်းလေး) အရွယ်ရောက်သည်။ လူပျိုဖြစ်သည်။',NULL)
,(7273,3,4,'လူဖြစ်သည်။ မွေးဖွားလာသည်။','‘တ္ၚဲဒှ်မၞိဟ်’ = ‘မွေးနေ့။’')
,(7273,3,4,'လူဖြစ်သည်။ မွေးဖွားလာသည်။','“ပၟတ်ပ္ဍဲတ္ၚဲမဒှ်မၞိဟ်ဂှ်မိမ (ဗောဓိသတ်) ဂိုၚ်လဝ်ရ။” (ဇ—၁၄၄။ အစွောံ။) = “ဘုရားလောင်း၏ ဖွားသောနေ့­ မိဘတို့သည် ဖွားသောနေ့မီးကို ယူ၍ထားကုန်၏။” (ညောင်ကန်)')
,(7273,3,4,'လူဖြစ်သည်။ မွေးဖွားလာသည်။','“ညးၜါဒှ်မၞိဟ်မွဲတ္ၚဲရောၚ်။” (ဇ—၄၁၁။ အစွောံ။) = “နှစ်ဦးသောသူတို့သည် တစ်နေ့တည်းဖွားမြင်၏။”')
,(7274,3,4,'၁။ (အိမ်ထောင်ရှိလျက် အခြားသူနှင့်) အလိုတူဖောက်ပြားသည်။','“(သမ္ဘာဗောဓိသတ်ဂှ် စိုတ်ဍေံစပ်အာကဵုတြုံပိုတ်ဂှ်တုဲ) ဍေံညးၜါဒှ်အာမွဲဂၞပ်တုဲ ဍေံချပ်ဂစိုတ်ဗောဓိသတ်ပၠန်ရ။” (ဇ—၁၉၃။ အစွောံ။) = “ဘုရားလောင်း၏မယားသည် ထိုၚပြတ်နှင့်တကွ တပ်စွန်းသောစိတ်ရှိသည်ဖြစ်၍ သူတို့နှစ်ဦးသည် အလိုတူဖောက်ပြားကာ ဘုရားလောင်းအား သတ်ရန်ကြံ၏။”')
,(7274,3,4,'၁။ (အိမ်ထောင်ရှိလျက် အခြားသူနှင့်) အလိုတူဖောက်ပြားသည်။','၂။ (လင်မယားအဖြစ်) အလိုတူပေါင်းဖက်သည်။')
,(7274,3,4,'၁။ (အိမ်ထောင်ရှိလျက် အခြားသူနှင့်) အလိုတူဖောက်ပြားသည်။','“ယွံကောန်၊ သဘဴပိုဲဗြဴဂှ် ဗၞတ်မွဲဗ္တံကီု ဒှ်မွဲဂၞပ်ဂကောံတြုံတုဲမ္ဂး မဒးဗက်ဗွဲဗလောဲစိုတ်တြုံဂှ်ရောၚ်။” (ဇ—၅၃၁။ အစွောံ။) = “ချစ်သမီး၊ ငါတို့မိန်းမသားဆိုသည်မှာ တစ်ညတာမျှ လင်ယောကျ်ားနှင့်တကွ အလိုတူပေါင်းဖက်ပြီးလျှင် ထိုယောကျာ်း၏စိတ်အလိုသို့ လိုက်ရ၏။”')
,(7274,3,4,'၁။ (အိမ်ထောင်ရှိလျက် အခြားသူနှင့်) အလိုတူဖောက်ပြားသည်။','‘ဒှ်ဂၞပ်မွဲ’ လည်းရှု။')
,(7275,3,4,'(မကောင်းသော) တစ်စုံတစ်ခုဖြစ်ပေါ်သည်။ အရေးအကြောင်းပေါ်ပေါက်သည်။',NULL)
,(7276,3,7,'ထိုသို့တပြီးကား။ သို့ဖြစ်လျှင်။ ဒါဖြင့်။ ဒါဆိုရင်။','“ယွံတၠညး၊ တ္ၚဲယးဂတဏအ် ဂပ်ဂဝ်ဂစိုတ်ကၠေံပြဘာတ်ရ” အမာတ်တံဂး။ “သာဓုဒးရးရ၊ ဒှ်ရသာ်ဂှ် သၞာ်အဲဝွံ မၞးတံဂိုၚ်လဝ်ရ” သၟိၚ်ဂး၊ (ဇ—၅၂၈။ အစွောံ။) = “မင်းမြတ်၊ မနက်ဖြန်­ ထိုပရိဗိုဇ်ရဟန်းအားသတ်ပစ်ခြင်းငှာသင့်၏” ဟု အမတ်တို့ဆိုကုန်၏။ “ကောင်းပြီ၊ ထိုသို့တပြီးကား ငါ၏သန်လျက်တော်ကို သင်တို့ယူသွားကုန်လော့” ဟုမင်းဆို၏။')
,(7276,3,7,'ထိုသို့တပြီးကား။ သို့ဖြစ်လျှင်။ ဒါဖြင့်။ ဒါဆိုရင်။','“ယွံတၠညး၊ ဗမၞးပၠံၚ်ဒြပ်သၟိၚ်အဴ” ဍေံဂး။“ဒှ်ရသာ်ဂှ် ဒးပရာဇာဒဏ်ရ” သၟိၚ်ဂး။ (ဇ—၈၆။ အစွောံ။) = “အရှင်မင်းကြီး၊ ပုဏ္ဏားသည်မင်း၏ဥစ္စာကို လုယက်၏” လျှောက်တင်၏။ “သို့ဆိုလျှင် ရာဇဒဏ်ပြုရမည်” ဟုမင်းဆို၏။')
,(7276,3,7,'ထိုသို့တပြီးကား။ သို့ဖြစ်လျှင်။ ဒါဖြင့်။ ဒါဆိုရင်။','“ပ္ဍဲက္ဍိုပ်တၟံသြန်တေံ မြာ်ထဝ်မွဲနွံ မအဲဟီုပ္ညုၚ်လဝ်အဴ” ကောန်လၟဂး။ “ဒှ်ရသာ်ဂှ် မပံါညံၚ်ဂွံညိ”သၟိၚ်ဂး။ (ဇ—၁၅၉။ အစွောံ။) = “ထိုငွေတောင်ထိပ်­ ရွှေဥဒေါင်းရှိကြောင်း အကျွန်ုပ်၏ဖခင် ပြောပြလမ်းညွှန်ထားပါ၏” ဟုမုဆိုးသားဆို၏။ “သို့ဆိုလျှင် သင်မိအောင်ဖမ်းလော့” ဟုမင်းဆို၏။')
,(7277,3,4,'ဆုံးရှုံးသည်။ ဆိုးကျိုးဖြစ်သည်။',NULL)
,(7278,3,4,'စိတ်သောကဖြစ်သည်။ သောကရောက်သည်။',NULL)
,(7279,3,4,'အငြင်းအခုံဖြစ်သည်။ အငြင်းပွားသည်။ ဝါဒကွဲသည်။',NULL)
,(7280,3,4,'၁။ အငြင်းအခုံဖြစ်သည်။ (ဝါတ် = ဝါဒ)','“ကလောကဵုကလောမ္ဂးဂှ် — ဟွံဂပ်ဂဝ်သဒှ်ဝါတ်သွေက်ဇွဵုကဵုရၚ်သ္ကံရောၚ်။” (ဇ—၇၄။ အစွောံ။) = “ဆွေမျိုးအချင်းချင်း ငြင်းခုံခိုက်ရန်မဖြစ်သင့်။”')
,(7280,3,4,'၁။ အငြင်းအခုံဖြစ်သည်။ (ဝါတ် = ဝါဒ)','၂။ အခက်ကြုံသည်။ အခက်တွေ့သည်။')
,(7280,3,4,'၁။ အငြင်းအခုံဖြစ်သည်။ (ဝါတ် = ဝါဒ)','“ပ္တေဟ်ပြဟ်ဒှ်ဝါတ်။” = “အယုံစောလျှင် အခက်ကြုံလိမ့်မည်။” (မွန်စကားပုံ)')
,(7280,3,4,'၁။ အငြင်းအခုံဖြစ်သည်။ (ဝါတ် = ဝါဒ)','“အဲပတှ်ေအမာတ်တုဲ အဲဒှ်ဝါတ်တုဲရ” သၟိၚ်ဂး။ (ဇ—၃ဝ၁။ အစွောံ။) = “အမတ်ကိုယုံ၍ ငါအခက်ကြုံရလေပြီ” ဟုမင်းဆို၏။')
,(7280,3,4,'၁။ အငြင်းအခုံဖြစ်သည်။ (ဝါတ် = ဝါဒ)','“တၠညးတီတုဲပိုဲဒှ်ဝါတ်ရောၚ်။” (ဇ—၅၃၁။ အစွောံ။) = “မင်းကြီးသိသွားလျှင် ငါတို့အခက်ကြုံလိမ့်မည်။”')
,(7281,3,4,'၁။ အငြင်းအခုံဖြစ်သည်။ ခိုက်ရန်ဖြစ်သည်။','“ဖျုန်ကၠဖျုန်ဇာဒိသိုၚ်တံဂှ် ဖျုန်ညးၜါဂှ် အဲဟွံဂွံစဏီရ။ အဲဗျဵုတုဲ ညးၜါဒှ်ဝါတ်ဂါတ်သေက်ဇဵုတုဲ ဍေံဂစိုတ်ရေၚ်သ္ကံတုဲ အဲဂွံစဖျုန်ဍေံရ” ကၠဵုဂြိုပ်ဂှ်ချပ်။ (ဇ—၃၆၁။ အစွောံ။) = “ကျားသားနှင့်ခြင်္သေ့သားနှစ်မျိုးတို့ကို ငါမစားဖူးသေး။ ငါသည် ကုန်းချောရန်တိုက်၍ ငြင်းခုံခိုက်ရန်ဖြစ်စေ၍ အချင်းချင်းသတ်ကြသောအခါ၄င်းတို့အသားကို ငါစားရအံ့” ဟုမြေခွေးကြံ၏။')
,(7281,3,4,'၁။ အငြင်းအခုံဖြစ်သည်။ ခိုက်ရန်ဖြစ်သည်။','၂။ အခက်အခဲဖြစ်သည်။')
,(7281,3,4,'၁။ အငြင်းအခုံဖြစ်သည်။ ခိုက်ရန်ဖြစ်သည်။','“က္တဵုဒှ်ဝါတ်ဂါတ်မ္ဂး မိက်မံၚ်ညးမၞုံကဵုပညာအိုတ်ရ။” = “အခက်အခဲကြုံသောအခါ ပညာရှိသောသူကို အလိုရှိကုန်၏။”')
,(7281,3,4,'၁။ အငြင်းအခုံဖြစ်သည်။ ခိုက်ရန်ဖြစ်သည်။','‘ဝါတ်ဂါတ်’ (န) လည်းရှု။')
,(7282,3,4,'၁။ (မိန်းကလေး) အရွယ်ရောက်သည်။ အပျိုဖြစ်သည်။','“ကောန်ဗြဴအဲ ဒှ်ဝုတ်ရ။”= “ငါ့သမီးအပျိုဖြစ်ပြီ။”')
,(7282,3,4,'၁။ (မိန်းကလေး) အရွယ်ရောက်သည်။ အပျိုဖြစ်သည်။','၂။ ရာသီလာသည်။ ရာသီပန်းပွင့်သည်။')
,(7282,3,4,'၁။ (မိန်းကလေး) အရွယ်ရောက်သည်။ အပျိုဖြစ်သည်။','“ဂိတုဏအ် ကောန်ဗြဴဒှ်ဝုတ်တုဲရဟာ။” = “သည်လမှာ သမီးရာသီလာပြီးပြီလား။”')
,(7283,3,4,'စိုးရိမ်ပူပန်သည်။ နောင်တရသည်။','“ဟွံဂွံဝဳပရာလဝ်မိမမ္ဂး ကာလမိမတံချိုတ်အာတုဲ ကြက်ဒးဒှ်သၠိုက်သ္ၚောမ်ရ။” = “မိဘတို့ကို မမွေးမြူထားရလျှင် မိဘသေလွန်သောအခါ ပူဆွေးနောင်တဖြစ်ကြရလိမ့်မည်။”')
,(7284,3,4,'ချစ်ခင်နှစ်သက်သည်။',NULL)
,(7285,3,4,'ရန်ဖြစ်သည်။',NULL)
,(7286,3,4,'အငြင်းအခုံဖြစ်သည်။ ခိုက်ရန်ဖြစ်သည်။',NULL)
,(7287,3,4,'ပြဿနာဖြစ်သည်။ ပြဿနာတက်သည်။','“ဍေံတအ်ညးၜါ က္တဵုဒှ်ဟိုတ်ဇၞော်ကဵုဒြဟတ်ရ။” = “သူတို့နှစ်ယောက် အကြီးအကျယ် ပြဿနာဖြစ်ကြသည်။ (အငြင်းအခုံခိုက်ရန်ဖြစ်ကြသည်။)”')
,(7288,3,4,'အနိစ္စရောက်သည်။ သေဆုံးသည်။',NULL)
,(7289,3,4,'ပြဿနာဖြစ်သည်။ အငြင်းအခုံဖြစ်သည်။ အမှုအခင်းဖြစ်ပွားသည်။',NULL)
,(7290,3,4,'အန္တရာယ်ဖြစ်သည်။ အနှောက်အယှက်ဖြစ်သည်။',NULL)
,(7291,3,11,'(န) အပြစ်။ (ပါဠိ—ဒေါသ)',NULL)
,(7292,3,1,'ပြစ်ချက်။ အပြစ်အနာအဆာ။','“ၜိုန်ဟွံမွဲကဵုဒုဟ်တၚ် ညးနၚ်ဒုဟ်ဘဝက် ဗက်ကၠေံဟွံကဵုဒၟံၚ်—။” (ဇ—ဝေသန္တဝ်။ အစွောံ။) = “ပြစ်ချက်တစ်စုံတစ်ရာမရှိပါဘဲလျက် သူတစ်ပါးတို့သည် နှင်ထုတ်ခြင်းအပြစ်ကိုပြု၍ မနေစေဘဲ နှင်ထုတ်ပေ၏။”')
,(7292,3,1,'ပြစ်ချက်။ အပြစ်အနာအဆာ။','“ပွမၞုံဇကုဂပ်ဂဝ်ဗဵုဒ္ၚေါဝ် ဟၟဲကဵုဒုဟ်တၚ်ဂှ်မွဲ။” (ဓမ္မဒေသနာ။ မာံရွှေငိုး။) = “ရှုချင်စဖွယ်သောကိုယ်ရှိ၍ အပြစ်အနာအဆာ မရှိခြင်းသည်လည်းတစ်ပါး။”')
,(7292,3,1,'ပြစ်ချက်။ အပြစ်အနာအဆာ။','“အံက်ဟွံချပ်ဒြၚ်၊ ဒုဟ်တၚ်ညိည။” (လိက်ပဒုမဝတဳ) = “ပြစ်ချက်အနည်းငယ်ကိုမျှ ဖခင်မဆင်ခြင်။”')
,(7293,3,11,'(န) အရပ်မျက်နှာ။ (ပါဠိ—ဒိသာ)','ဒိုဟ်ဗၟံက် = အရှေ့အရပ်။')
,(7293,3,11,'(န) အရပ်မျက်နှာ။ (ပါဠိ—ဒိသာ)','ဒိုဟ်သၟဝ်ကျာ= မြောက်အရပ်။')
,(7293,3,11,'(န) အရပ်မျက်နှာ။ (ပါဠိ—ဒိသာ)','ဒိုဟ်ပလိုတ် = အနောက်အရပ်။')
,(7293,3,11,'(န) အရပ်မျက်နှာ။ (ပါဠိ—ဒိသာ)','ဒိုဟ်သၠုၚ်ကျာ = တောင်အရပ်။')
,(7294,3,4,'မိုက်မဲသည်။','‘သဒိုဟ်’ ရှု။')
,(7295,3,4,'(သောၚ်) ထွန်းသည်။','“တိဒိုဟ်တိတ်အာနူသြၚ်ၜဳရ။” = “မြစ်ကမ်းမှ သောင်ထွန်းလာသည်။”')
,(7296,3,4,'(ဗေဒင်) ဟောသည်။ ဟောကိန်းထုတ်သည်။','“ဝေၚ်အာနူသၟိၚ်ကုသမွဲတုဲ တြုံမွဲသ္အာၚ် မဂွံဒှ်တၠသ္ၚိပြဘာဝတဳဂှ် ပ္ဍဲဂၠးဇမ္ဗုဒိပ်ဝွံဂှ် ဟွံမွဲရ။ နကွတ်ဗေဒၚ်အဲဂှ်လေဝ် သာ်ဂှ်မဒိုဟ်လဝ်ရ” သၟိၚ်ကုသဂး။ (ဇ—၅၃၁။ အစွောံ။) = “ဤဇမ္ဗူဒိပ်တစ်ခွင်­ ကုသမင်းမှတစ်ပါး ပဘာဝတီ၏လင်ဖြစ်ရန် အခြားသောယောကျာ်းမည်သည် မရှိပြီ။ ငါ၏ဗေဒင်အတတ်အရလည်း ထိုသို့ပင်ဟောထား၏” ဟုကုသမင်းဆို၏။')
,(7296,3,4,'(ဗေဒင်) ဟောသည်။ ဟောကိန်းထုတ်သည်။','“ကောန်တြုံဂှ် သတ်တၠကုသဵုရောၚ် ဗမၞးမလေပ်ဗိုတ်ပိတံဂှ်မဒိုဟ်လဝ်။” (ဇ—၁၅၆။ အစွောံ။) = “(ဖွားမြင်အံ့သော) ဤမင်းသားသည် ဘုန်းကံရှင်တည်းဟု ဗေဒင်တတ်သောပုဏ္ဏားတို့ ဟောထားကုန်၏။”')
,(7297,3,9,'တစ်စုံမှတစ်ဖက်။ တစ်ရှဉ်းမှတစ်ခု။','ဂၠဴမွဲဒိုဟ် = နွားတစ်ဖက်။ နွားတစ်ကောင်။')
,(7297,3,9,'တစ်စုံမှတစ်ဖက်။ တစ်ရှဉ်းမှတစ်ခု။','ဒၞပ်မွဲဒိုဟ် = ဖိနပ်တစ်ဖက်။')
,(7298,3,4,'(မျောက်) အော်သည်။','“ကၞုဲလေဝ်ဒိုဟ် ပြိပ်ဂှ်လေဝ်ဂဒတ်။” (သၠပတ်စန္ဒဝတဳ) =“မျောက်လည်း မျောက်သံဖြင့်အော်မြည် ရှဉ့်လည်း ရှဉ့်သံဖြင့်အော်မြည်၏။”')
,(7299,3,1,'အရပ်မျက်နှာ။','တလိၚ်အာဒိုဟ်ကၠၚ် = အရပ်မျက်နှာကို အမှတ်မှားသည်။ အရပ်မျက်နှာကို မသိဖြစ်သည်။')
,(7300,3,3,'မိုက်မဲထုံထိုင်းသော။ ဉာဏ်ပညာနုန့်သော။','“ၝအဒိုက်ဂၠိက် ပညာဒိုဟ်ဂွိုၚ်၊ အပါၝဒှ်စိၚ်ဟာ ၝဂွံဟီုဏာတ်ဖါတ်ကဵုစိၚ်သာ်ဂှ်—” တၠညးရာဇာဓိရာဇ် ဂးကဵုဂမာစိၚ်။ (အကြီုရာဇာဓိရာဇ်) = “ဟယ်ငတုံးငမိုက်၊ ဆင်နှင့် မင်းဒီလိုအချိန်းအချက်လုပ်ရအောင် မင်းအဖေက ဆင်မို့လား” ဟုဘုရင်ရာဇာဓိရာဇ်က ဆင်ထိန်းအားပြော၏။')
,(7301,3,1,'အောင်း။ (ပါဠိ—တရစ္ဆ) (ရဟန်းတို့မစားအပ်သော အသားဆယ်မျိုးတွင် ပါဝင်သည်။)','“ကၟီ၊ ကၠ၊ သိတ်၊ စိၚ်၊ တၠိၚ်၊ က္ၜိုၚ်၊ ဒြာဲ၊ ဗတာဲ၊ ပှ်၊ မၚ်၊ ဂၠဴ၊ ပြေၚ်၊ ဒိုဟ်ဒး။” (သၠပတ်စန္ဒဝတဳ)')
,(7301,3,1,'အောင်း။ (ပါဠိ—တရစ္ဆ) (ရဟန်းတို့မစားအပ်သော အသားဆယ်မျိုးတွင် ပါဝင်သည်။)','“ဒိုဟ်ဒးကၠကၟီ၊ ဂဟီဗြုကြီု။” (လိက်မေဃကောန်ဒြာဲ) = “အောင်း၊ ကျား၊ဝက်ဝံတို့သည် ကျယ်လောင်စွာ အော်မြည်ကြုံးဝါးကုန်၏။”')
,(7302,3,4,'ယိမ်းယိုင်သည်။ ဒယီးဒယိုင်သွားသည်။ ချွတ်ချော်မှားယွင်းသည်။','“ယွံဗမၞး၊ မူဒှ်မကွာ်ဒိုဟ်ဒးဒၟံၚ်ရော။” (ဇ—၄၁၆။ အစွောံ။) = “ပုဏ္ဏား၊ အဘယ်ကြောင့် ဒယိမ်းဒယိုင်နှင့်လျှောက်နေသနည်း။”')
,(7302,3,4,'ယိမ်းယိုင်သည်။ ဒယီးဒယိုင်သွားသည်။ ချွတ်ချော်မှားယွင်းသည်။','“ပညာနွံတုဲ၊ ဒှ်ဒတုဲဇန်။ ယာံပညာအောန်၊ လုလောန်ဒိုဟ်ဒး။” (လောကသိဒ္ဓိ။ အစွောံ။) = “ပညာရှိက လူ့ကောင်းကျိုးကို ပြီးမြောက်စေနိုင်၏။ ပညာနည်းပါးပါကမှားယွင်းချွတ်ချော်တတ်၏။”')
,(7303,3,3,'(ခြေ) ထိုင်းသော။ လေးကန်သော။','“သဳပဒဳ။ န်ညးမၞုံဇိုၚ်မဒိုဟ်ဒေၚ်။” (တြာဲဝိနယသၚ်ရိုဟ်ဂြဳ။ စန္ဒိမာ။) = “ခြေထိုင်းသောသူ။”')
,(7303,3,3,'(ခြေ) ထိုင်းသော။ လေးကန်သော။','“(ဍာ်ရမတ်) ဒဇူပေၚ်သြိုဟ်၊ ဒိုဟ်ဒေၚ်ကၠၚ်ပြဵု။” (လိက်မၚ်ဗၠာဲသ္ၚိတူ) = “ရၚ်ကိုပြည့်အောင် မျက်ရည်ယိုကာ ထိုင်းမှိုင်းပူပန်၏။”')
,(7304,3,4,'မိုက်မဲသည်။ ထုံအသည်။ ဉာဏ်နုန့်သည်။','“ဗွဲအတိုၚ်မဒိုဟ်ဓီု ဗွဲအတိုၚ်မဝိဝိၚ်။” (ပြကိုဟ်ဒ္ဂေတ်ပဋိပတ်သာမဏဳ။ မာံရွှေငိုး။) = “မိုက်မဲထုံအသောအားဖြင့်၊ တွေဝေသောအားဖြင့်။”')
,(7304,3,4,'မိုက်မဲသည်။ ထုံအသည်။ ဉာဏ်နုန့်သည်။','“တီသ္ဒိုဟ်ဓီုသန်၊ တီအန်ပညာ။” (လိက်ဘောဂရေန်) = “မိုက်မဲကြောင်းပညာနည်းကြောင်းသိ၏။”')
,(7304,3,4,'မိုက်မဲသည်။ ထုံအသည်။ ဉာဏ်နုန့်သည်။','“ပူဂဵုဒိုဟ်ဓီု၊ သမၠီုတေံပၠန်။ ဝေၚ်ပဲါညိရ၊ လ္ပပြာပ်ညန်။” (လိက်ကကၠာ်။ ကောန်ဍး။) = “ထုံအသောပုဂ္ဂိုလ် ထိုသူမိုက်ကို ရှောင်တိမ်းပါလေ မချဉ်းကပ်လေနှင့်။”')
,(7305,3,1,'ညီ။ ညီမ။ နှမ။',NULL)
,(7306,3,1,'ညီ၊ ညီမအရင်းအချာ။',NULL)
,(7307,3,1,'ညီ။','“ဒေံတြုံနွံမွဲ။” (ဇ—၃၉ဝ။ အစွောံ။) = “ညီတစ်ယောက်ရှိ၏။”')
,(7308,3,1,'ညီမ။ နှမ။',NULL)
,(7309,3,1,'ညီယောက်ဖ။ လင်','မယား၏ညီ၊ ညီမ။ ယောက်မ။ ခယ်မ။')
,(7309,3,1,'ညီယောက်ဖ။ လင်','‘ဝတ်ကောယဴကဵုဒေံသဳဂၞဳ။’ (အကြီုရာဇာဓိရာဇ်) = ‘အစ်ကိုယောက်ဖနှင့်ညီယောက်ဖတို့၏ဝတ္တရား။’')
,(7309,3,1,'ညီယောက်ဖ။ လင်','“ၝောံဒဴကလဝ်ညဳကံၚ်သိန် ပဟိုတ်ဒှ်ဒေံသဳဂၞဳ တၠညးဟွံဂစိုတ်။” (အကြီုရာဇာဓိရာဇ်) = “ညီကောင်းသိန်၏မယားဖြစ်သောမွေ့ဒေါကို ခယ်မဖြစ်သောကြောင့် သူ့ရှင်မသတ်။”')
,(7309,3,1,'ညီယောက်ဖ။ လင်','“ညာတ်ဒေံသဳဒၞဳ၊ ဍိုန်ဒ္ၚဳသ္ၚိတ်သ္ၚဲ။” (လိက်သောဝိန်ဇဲယ။ မာံရောဂေါ။)')
,(7310,3,1,'အငယ်ဆုံး အကြီးဆုံးမဟုတ်သော အလယ်အလတ်ညီ၊ ညီမ။',NULL)
,(7313,3,4,'ပူပန်သည်။ စိတ်ဆင်းရဲသည်။','“မံၚ်ဇကုမွဲ၊ တူယဲဒေံါသ္ၚီ။” (လိက်မာဃဒေဝါန်) = “တစ်ကိုယ်တည်းအထီးကျန်၍ စိတ်ဆင်းရဲပူပန်နေရ၏။”')
,(7313,3,4,'ပူပန်သည်။ စိတ်ဆင်းရဲသည်။','“မိဒးဒှ်လၞီ၊ ဒေံါသ္ၚီကၚ်ဇတ်။ ဂၚ်ဗလာဲမတ်၊ တီဇတ်ရောကောန်။” (လိက်ကောန်သၟိၚ်ဝါရဝေါၚ်သ။ အစွောံ။) = “မိခင်ခမျာ သောကပွား၍ဆင်းရဲပူပန်၏။ မျက်ဝန်းအိမ်မှ မျက်ရည်မြစ်သည် ဘယ်သောအခါမှ ခန်းပါမည်နည်း။”')
,(7313,3,4,'ပူပန်သည်။ စိတ်ဆင်းရဲသည်။','“ဒှ်တဴလၞီ၊ ဒေံါသ္ၚီရရဴ။” (လိက်ကောန်သၟိၚ်ပိ။ မာံခစုန်အံက်။) = “သောကဖြစ်ကာ ပူပန်ဆင်းရဲ၏။”')
,(7313,3,4,'ပူပန်သည်။ စိတ်ဆင်းရဲသည်။','“ဒှ်တဴလၞီ၊ ဒေံါသ္ၚီဂၠိုၚ်ရာ။” (လိက်ပဒုမဝတဳ)')
,(7314,3,4,'ရပ်သည်။ ရပ်တန့်သည်။','“ပ္ဍဲဇရေၚ်တၞံဆု မၞုံသ္ကဲဍာ်ဂှ် ဗမၞးဒိုအ်ဒၟံၚ်တုဲ—။” (ဇ—၄ဝ၂။ အစွောံ။) = “ရေစပ်နံဘေး­ရှိသော သစ်ပင်နား­ ပုဏ္ဏားရပ်တန့်၍နေ၏။”')
,(7314,3,4,'ရပ်သည်။ ရပ်တန့်သည်။','“ဒိုအ်ဒၞာဲဝွံရ” လၟဂးတုဲ ဗဒိုအ်လဝ်ဂၠုၚ်—။ (ဇ—၄ဝ၇။ အစွောံ။) = “ဤနေရာတွင် ရပ်လော့” ဟုမုဆိုးဆို၍ လှေကိုရပ်တန့်စေ၏။')
,(7315,3,4,'လက်လျှော့သည်။','“နူဒှ်ကောန်ယာဲ၊ ယာဲဂွံလွဳပရာ။ ဟွံဂွံခၠေဝ်ဂုန်၊ ဒေံါတဲကီုဟာ။” (လိက်သၚ်ဂဒါ။ သဳလဝန္တ။) = “မယ်တော့်သားဖြစ်၍ မယ်တော်မွေးမြူထားသောမယ်တော့်ကျေးဇူးကို မဆပ်ရဘဲ သားတော်လက်လျှော့ရိုးမရှိ။”')
,(7316,3,4,'ရပ်တန့်သည်။','“(ပၞာန်ဗမာ) စိုပ်ဒပ်မန် ဗမာဟွံဒိုအ်ဒဝ် ဗ္ဒာဲကၞိန်ဟုပ်လုပ်ဗတိုက်—။” (အကြီုရာဇာဓိရာဇ်) = “ဗမာစစ်တပ်သည် မွန်တပ်စခန်းသို့ ရောက်လာပြီးလျှင် မရပ်တန့်ဘဲ လှေကားထောင်ကာ စုအုံဝင်တိုက်၏။”')
,(7317,3,4,'၁။ ကြည့်သည်။','“ဗောဓိသတ်တုန်လေဝ် ပ္ဍဲသၟိၚ်မဟီုဂလာန်ဂၠိုၚ်ၚ်ဂှ် တၞဟ်နသၟိက်ကဵုအောန်ဂလာန်ဂှ်တုဲ ဥပဲါမွဲ ဂၠာဲဂ္ၚေၚ်ဒ္ၚဳတဴရ။” (ဇ—၂၁၅။ အစွောံ။) = “ဘုရားလောင်းသည်လည်း စကားများစွာပြောတတ်သောမင်းကို စကားနည်းစေလို၍ တစ်ခုသောအကြောင်းဥပါယ်ကိုစုံစမ်းရှာကြည့်လျက်နေ၏။')
,(7317,3,4,'၁။ ကြည့်သည်။','‘သ္ၚဳ’ (ကြိ) လည်းရှု။')
,(7317,3,4,'၁။ ကြည့်သည်။','၂။ မှီသည်။ (?)')
,(7317,3,4,'၁။ ကြည့်သည်။','“(အမာတ်ဆန်တုန်) မဒ္ၚဳလဝ်ပြဘိုက်တရၚ်တုဲ တိက်ဒၟံၚ်ဂှ်။” (ဗုဒ္ဓဝၚ်။ မာံရွှေငိုး။) = “ဆန္ဒအမတ်သည် တံခါးတိုင်ကိုမှီ၍ အိပ်နေ၏။”')
,(7317,3,4,'၁။ ကြည့်သည်။','(ကြိဝိ) ညင်သာစွာ။ ဖြည်းညင်းစွာ။ အသာအယာ။')
,(7317,3,4,'၁။ ကြည့်သည်။','“(ဂၞကျာ်မဒ္ဒဳလောတ်သ္ၚဳဒၟံၚ်ဂှ်) ယာံဒွံဍာ်အနဂ္ဃမန်ဂးကီုရ ဂၞကျာ်သမ္ၚုဟ်တိုန် ကလိဂွံအသာရဝါတ်တုဲ ဒ္ၚဳဒလိုက်က္တဵု—။” (ဇ—ဝေသန္တဝ်။ အစွောံ။) = “မေ့မြောလဲနေသောမဒ္ဒီမိဖုရားသည် အစွမ်းထက်သော အနဂ္ဃရေမန်းကို ထိသည်နှင့်တစ်ပြိုင်နက် သတိပြန်လည်၍ သက်သာရာရ၍ အသာအယာထ၏။”')
,(7318,3,4,'သေချာစွာရှာသည်။','‘သ္ၚဳဂၠာဲ’')
,(7318,3,4,'သေချာစွာရှာသည်။','‘ဂၠာဲသ္ၚဳ’ ရှု။')
,(7319,3,5,'ညင်သာစွာ။ ဖြည်းညင်းစွာ။ ဖြည်းဖြည်းသာသာ။ တဖြည်းဖြည်း။ (ပါဠိ—သဏိက)','“(မိဂှ်) ပြာပ်အာဒ္ၚဳဒ္ၚဳ ဇရေၚ်ကောန်ဂှ်တုဲ—။” (ဇ—၄၄၆။ အစွောံ။) = “အမိသည် သားထံပါးသို့ ဖြည်းညင်းစွာ ချဉ်းကပ်သွား၏။”')
,(7319,3,5,'ညင်သာစွာ။ ဖြည်းညင်းစွာ။ ဖြည်းဖြည်းသာသာ။ တဖြည်းဖြည်း။ (ပါဠိ—သဏိက)','“ဂပ္ဘဂှ်ကၠာ၊ ကြံၚ်အာဒ္ၚဳဒ္ၚဳ။” (လိက်ရတနပဇ္ဇောတ) =“ထိုကိုယ်ဝန်သည် တဖြည်းဖြည်း ရင့်သွား၏။”')
,(7319,3,5,'ညင်သာစွာ။ ဖြည်းညင်းစွာ။ ဖြည်းဖြည်းသာသာ။ တဖြည်းဖြည်း။ (ပါဠိ—သဏိက)','“ကောန်တြုံသၟိၚ်ကၠာ၊ ဇၞော်အာဒ္ၚဳဒ္ၚဳ။” (လိက်ဘောဂရေန်) = “ဘုရင့်သားတော်သည် တဖြည်းဖြည်းကြီးပြင်းလာ၏။”')
,(7320,3,5,'ညင်သာစွာ။ ဖြည်းညင်းစွာ။ ဖြည်းဖြည်းသာသာ။','“ဒ္ၚဳဒ္ၚဳညှာညှာ၊ ကွာ်အာလျလျ။” (ဝၚ်ပ္တန်ဍုၚ်ပဒုမ်ဋ္ဌာနဳ) = “ဖြည်းဖြည်းသာသာ လျှောက်သွားသည်။”')
,(7321,3,4,'ကြည့်သည်။','‘သ္ၚဳမွဲ’ ရှု။')
,(7322,3,4,'စုံစမ်းသည်။ သေချာစွာလိုက်လံမေးမြန်းသည်။',NULL)
,(7323,3,4,'ထင်းခွေသည်။','‘ၚဳအှ်ော’ ရှု။')
,(7324,3,4,'‘လ္ၚုၚ်လ္ၚ’ ရှု။',NULL)
,(7325,3,1,'အံသွား။','‘အၚာပ်’ ရှု။')
,(7326,3,4,'ကြည့်သည်။','‘ဒ္ၚေါဝ်’ ရှု။')
,(7327,3,5,'အပြိုင်။ အစုံ။','“ကျာ်တြဲထ္ၜးဣဒိပါဋိဟာ ပၟတ်ဍာ်ဒ္ၚဝ်ဒ္ၚဝ်ရ။” = “မြတ်စွာဘုရားသည် ရေမီးအစုံ (ရေမီးအပြိုင်) တန်ခိုးပါဋိဟာ ပြတော်မူသည်။”')
,(7328,3,1,'မှန်။ ကြည့်မှန်။ ကြေးမုံ။ (ပါဠိ—အာဒါသ)','ရံၚ်ဒ္ၚောဝ် = မှန်ကြည့်သည်။')
,(7329,3,4,'ကြည့်သည်။ ရှုစားသည်။','“ယွံမိခနှောဝ်ဗြဴ၊ — တၞဟ်နသၟိက်ဂွံဒ္ၚောဝ်ရုပ်မိတုဲဂှ်အဲမဒးပန်စုတ်တၠသ္ၚိမိကွေံရ” သၟိၚ်ဂး။ (ဇ—၄၈၅။ အစွောံ။) = “ရှင်မကိနနရီ၊ ငါသည် နှမ၏ရုပ်အဆင်းကို ရှုစားလိုသည်ဖြစ်၍ နှမ၏လင်အား အမှန်ပင်ပစ်ခတ်မိပါသည်” ဟုမင်းဆို၏။')
,(7329,3,4,'ကြည့်သည်။ ရှုစားသည်။','‘ဗဵုဒ္ၚောဝ်’ (ကြိ) လည်းရှု')
,(7330,3,1,'၁။ မျက်မှန်။','စုတ်ဒ္ၚေါဝ်မတ် = မျက်မှန်တပ်သည်။')
,(7330,3,1,'၁။ မျက်မှန်။','၂။ မျက်ရှု။ ရှုမငြီးသောအရာ။ ရှုမဝသောအရာ။')
,(7330,3,1,'၁။ မျက်မှန်။','“(သၟတ်ဗြဴသုဇာတာဂှ်) ဒၞာဲညးမညာတ်သ္ဇုၚ်သ္ဍိုက်မၠိုက် ဂပ်ဂဝ်ဒးဗဵုဒ္ၚဝ်ဟေၚ် ရဴဗြဴအဆေဝ်သွဝ်ကီု နဲကိနနရဳဗြဴ ဃောတွိုန်စရာဲ မပတၠရုပ် ဒ္ၚောဝ်မတ်ဇန်ဂမၠိုၚ် ရဴမဒှ်ကီု။” (ဇ—၁၉၄။ အစွောံ။) = “သုဇာတာသတို့သမီးသည် မြင်သူတိုင်းချစ်ခင်နှစ်သက်၍ ရှုချင်စဖွယ်ရှိ၏။ နတ်သမီးကဲ့သို့၄င်း ကိနနရီမကဲ့သို့၄င်း အလှဂုဏ်ကျက်သရေတက်တုန်းဖြစ်၍ မြင်သူတကာ့မျက်ရှုဖြစ်သော ရုပ်အဆင်းရှင်တည်း။”')
,(7330,3,1,'၁။ မျက်မှန်။','“ပဒှ်ဟုံဇြ၊ မံၚ်ရရုပ်ထဝ်။ ဒၟံၚ်ရရုပ်ထဝ်၊ ဒၚောဝ်မတ်မ။” (လိက်ပဒုမဝတဳ) = “မပူဆွေးမညှိုးငယ်ဘဲ နေပါလော့ရွှေရုပ်လွှာ၊ မောင့်မျက်ရှုရွှေရုပ်လွှာ နေပါလော့။”')
,(7331,3,1,'၁။ (ခရုစသည်၏) မာသောအခွံ။','ဒၞာကၞု = ခရုခွံ။')
,(7331,3,1,'၁။ (ခရုစသည်၏) မာသောအခွံ။','ဒၞာသတ်ဗြဴ = အုန်းမှုတ်။')
,(7331,3,1,'၁။ (ခရုစသည်၏) မာသောအခွံ။','၂။ (စောင်းစသည်၏) ကိုယ်ထည်။')
,(7331,3,1,'၁။ (ခရုစသည်၏) မာသောအခွံ။','ဒၞာထဏ = စောင်းကိုယ်ထည်။ စောင်းရိုး။')
,(7332,3,4,'တားသည်။ ကာသည်။','“ဂအာၚ်သ္ၚိဂှ် ညးဒၞာလဝ်ဒၞးပသဲရ။” = “ထိုအိမ်ခြံဝင်းကို သံစည်းရိုးဖြင့်ကာထားသည်။”')
,(7333,3,4,'တားဆီးသည်။',NULL)
,(7334,3,4,'ဖြတ်ပြီးတားသည်။ ကြိုတင်၍တားသည်။',NULL)
,(7335,3,1,'၁။ ခေါင်းအုံး။','ဒၞဳဒလာဲ = မှီအုံး။')
,(7335,3,1,'၁။ ခေါင်းအုံး။','၂။ ပေတုံး။')
,(7335,3,1,'၁။ ခေါင်းအုံး။','ဒၞဳဒမာတ် = ပန်းဘဲပေတုံး။')
,(7335,3,1,'၁။ ခေါင်းအုံး။','(ကြိ) (ခေါင်း) အုံးသည်။')
,(7335,3,1,'၁။ ခေါင်းအုံး။','“မၚ်ဗၠာဲစွံအှ်ောစန်ဂှ်တုဲ ဒၞဳအှ်ောဂှ်တုဲ သ္တိက်ဒၟံၚ်—။” (ဇ—၂၈၄။ အစွောံ။) = “ထိုလုလင်သည် ထင်းစည်းကိုချထားပြီးလျှင် ထင်းကိုခေါင်းအုံး၍ အိပ်နေ၏။')
,(7336,3,1,'ခြေတင်သောအုံး။',NULL)
,(7337,3,1,'ကြက်ငှက်အမောက်။',NULL)
,(7338,3,1,'ဝင်းခြံ၏အကာအရံ။ စောင်းရန်း။ စည်းရိုး။','ဒၞးဒုန် = ဝါးစောင်းရန်း။')
,(7338,3,1,'ဝင်းခြံ၏အကာအရံ။ စောင်းရန်း။ စည်းရိုး။','(ကြိ) ခြံစည်းရိုးကာရံသည်။')
,(7338,3,1,'ဝင်းခြံ၏အကာအရံ။ စောင်းရန်း။ စည်းရိုး။','“ကၠအ်ပိုဲဂှ် ဒၞးလဝ်ကဵုဒုန်ရ။” = “ကျွန်တော်တို့ခြံကို ဝါးဖြင့်စည်းရိုးကာရံထားသည်။”')
,(7339,3,1,'‘ဓနက်’ ရှု။',NULL)
,(7340,3,1,'ကန့်လန့်ကာ။','‘ဇနိက်’ ရှု။')
,(7341,3,1,'၁။ မြွေပါးပျဉ်း။','“ညံၚ်ဇြုံဇာတ် ညးမထဍဟ်စုတ်ကဵုလေံတုဲ ရဴယိုက်ပ္တိုန်ဒနံက်ဂှ်ကီုရ။” (ဇ—၂၅၁။ အစွောံ။) = “တုတ်နှင့်ထိုးဆွသည်ရှိသော် ပါးပျဉ်းကိုထောင်သောမြွေဟောက်ကဲ့သို့။”')
,(7341,3,1,'၁။ မြွေပါးပျဉ်း။','“(သၟိၚ်နာ်ဂှ်) ကဝးဗိုၚ်လဝ်ရသိတုဲ လတူကၞိပ်ရသိဂှ် ယိုက်လဝ်ဒၞံက်မဇၞော်တုဲ—။” (ဇ—၂၅၃။ အစွောံ။) = “နဂါးမင်းသည် ရသေ့ကို ရစ်ခွေပတ်၍ ရသေ့ဦးခေါင်းပေါ်­ပါးပျဉ်းကိုဆောင်း၍—။”')
,(7341,3,1,'၁။ မြွေပါးပျဉ်း။','“ဇြုံယိုက်ပ္တိုန်ဒၞော်မဇၞော်တုဲ ဇက်ကၠုၚ်ရ။” (ဇ—၃၈၉။ အစွောံ။) =“မြွေသည် ကြီးစွာသောပါးပျဉ်းကိုထောင်၍ ချီလာ၏။”')
,(7341,3,1,'၁။ မြွေပါးပျဉ်း။','၂။ (ဟင်းခပ်သော) ယောက်မ။')
,(7341,3,1,'၁။ မြွေပါးပျဉ်း။','“ထၟာဲပုၚ်ကီု ဒၞော်လၟဳကီု။” (ဇ—၄၁၇။ အစွောံ။) = “ထမင်းအိုးကို၄င်း ယောက်မစလောင်းဖုံးကို၄င်း။”')
,(7341,3,1,'၁။ မြွေပါးပျဉ်း။','“ပိဏ္ဍပါတ်မွဲဒၞံက်ကီု ယာဂုမွဲဗြံက်ကီု။” (သ္ကေံမိလိန္ဒဝတ္ထု) = “ဆွမ်းတစ်ယောက်မကို၄င်း ယာဂုတစ်မှုတ်ကို၄င်း။”')
,(7341,3,1,'၁။ မြွေပါးပျဉ်း။','‘ဂၞံက်’')
,(7341,3,1,'၁။ မြွေပါးပျဉ်း။','‘ဂၞော်’ ဟုလည်းရေးသည်။')
,(7342,3,1,'မျက်မှောင်။ မျက်ခုံး။ (ပါဠိ—ဘမုကာ)','သော်ဒၞေၚ်မတ် = မျက်ခုံးမွေး။')
,(7342,3,1,'မျက်မှောင်။ မျက်ခုံး။ (ပါဠိ—ဘမုကာ)','“ယွံဒေဝတဴ (ဗြဴ) မၞုံဒၞေၚ်မတ်မဆာဲ—။” (ဇ—၄၄၂။ အစွောံ။) = “တင့်တယ်သောမျက်ခုံးရှိသော အိုနတ်သမီး—။”')
,(7343,3,4,'မျက်ခုံးလှုပ်သည်။ (ဥပစာ) မိမိမကောင်းကြောင်းကို သူတစ်ပါးပြောဆိုသည့်အဓိပ္ပါယ်ဖြင့် သုံးလေ့ရှိသည်။',NULL)
,(7344,3,1,'စဉ်းတီတုံး။ စဉ်းနှီးတုံး။','“တဲရသိၜါဂှ် ပ္ဍဵုကဵုဒၞန်တုဲ ဗာတ်ဇခါတ်ဒန်ကၠေံကဵုမြပံၚ်ရ။” (ဇ—၃၁၃။ အစွောံ။) = “ခိုးသူသတ်သည် ပုဆိန်ကိုယူ၍ စဉ်းတီတုံး­ (ရသေ့၏) လက်နှစ်ဘက်တို့ကို ထားစေ၍ဖြတ်၏။” (ညောင်ကန်)')
,(7344,3,1,'စဉ်းတီတုံး။ စဉ်းနှီးတုံး။','“ဍေံပ္ဍဵုလဝ်ကအ်ဗောဓိသတ်ကဵုဓနန်တုဲ—။” (ဇ—၁၉၄။ အစွောံ။) = “မင်းချင်းတို့သည် ဘုရားလောင်း၏လည်ကို စဉ်းနှီးတုံး­ ဖိထားပြီးလျှင်—။”')
,(7344,3,1,'စဉ်းတီတုံး။ စဉ်းနှီးတုံး။','‘ဒန်’ (ကြိ) လည်းရှု။')
,(7345,3,1,'‘ဒနပ်’ ရှု။',NULL)
,(7346,3,1,'‘ဓနီ','ဒနီ’ ရှု။')
,(7347,3,1,'၁။ နေရာ။','“အပေါတ်ဂှ် စွံဒၞာဲဍေံညိ။” = “ထိုပစ္စည်းကို နေရာတကျထားပါ။”')
,(7347,3,1,'၁။ နေရာ။','၂။အရိုက်အရာ။')
,(7347,3,1,'၁။ နေရာ။','“သၟိၚ်မဇကုစုတိအာတုဲ ဗောဓိသတ်ဂွံဒှ်သၟိၚ်ဒၞာဲမရ။” (ဇ—၃၂၇။ အစွောံ။) =“အဘလွန်သဖြင့် ဘုရားလောင်းသည် အဘအရိုက်အရာ မင်းအဖြစ်ကိုဆက်ခံ၏။”')
,(7347,3,1,'၁။ နေရာ။','၃။ (အများအနက်) ဆိုလိုသောသူ။ ဆိုလိုသောအရာ။')
,(7347,3,1,'၁။ နေရာ။','“(သွက်ဂွံစၞေဟ်ကဵုကၠဂှ်) ကၠိက်ဒၞာဲဂံၚ် ဒၞာဲထတ်ဒၞာဲဂၞေဟ်ခိုဟ်ဂှ် ကဵုဒၟံၚ်ပ္ဍဲပါၚ်တရၚ်ဂေါဟ်ဂှ်—။” (ဇ—၂၈၃။ အစွောံ။) = “ကျားနှင့်စစ်ထိုးရန်အတွက် (တောဝက်များအနက်) ရဲရင့်သူ အားကောင်းသူ အစွယ်ကောင်းသူတို့ကို ဥမင်လိုဏ်ခေါင်းအဝ­ နေစေကုန်၏။”')
,(7348,3,1,'ခြေရာ။','“ညံၚ်ရဴကမအာပ္ဍဲဍာ်တုဲ ဂၠာဲဒၞာဲဇိုၚ်ဟွံဒးကီု။” (ဇ—၆၄။ အစွောံ။) = “ရေ­သွားသောငါး၏ခြေရာကို ရှာမတွေ့သကဲ့သို့။”')
,(7348,3,1,'ခြေရာ။','‘ကောန်မလိုန်ဒၞာဲဇိုၚ်အပါ။’ = ‘အဖခြေရာကိုနင်းသောသား။’')
,(7349,3,5,'ဘယ်နေရာ။','“မိက်ဂွံအာဒၞာဲလဵုရော။” = “ဘယ်နေရာ သွားချင်သလဲ။”')
,(7350,3,1,'နေရာ။ နေရာဋ္ဌာန။','စှ်ေဒၞာဲဝဲါ = နေရာကျသည်။')
,(7350,3,1,'နေရာ။ နေရာဋ္ဌာန။','“ယွံသၟာတွိၚ်၊ ဂၞကျာ်သ္ဍိုက်အဲဂှ်မူဒၞာဲမအာကၠေံဂှ်လေဝ် ဟွံတီညာတ်ဒၞာဲဝဲါရ” သၟိၚ်ဂး။ (ဇ—၃၆ဝ။ အစွောံ။) = “အိုစောင်းသမား၊ ငါ၏အချစ်တော်မိဖုရားသည် အဘယ်နေရာသို့ သွားလိုက်သည်မှာလည်း နေရာဋ္ဌာနကို သိမြင်သောသူဟူ၍ မရှိ။”')
,(7350,3,1,'နေရာ။ နေရာဋ္ဌာန။','“ထာဏဍုၚ်ကွာန်၊ သန်ထာန်ဒၞာဲဝဲါ။” (လိက်ဗြရတ်ဣဏၚ်ကၚ်ရဳ) =“ဋ္ဌာနမြို့ရွာအရပ်နေရာ။”')
,(7351,3,4,'တုတ်စသည်နှင့်ရိုက်သဖြင့် အသားအရေတွင် အရှိုး (အစင်းအကြောင်း) ထၚ်သည်။','“ကွးဘာကမြမ်ဂှ် ကျာ်ဇၞော်တက်ကဵုလေံၜဝ် စးဒၞောဝ်အာရ။” = “ထိုကျောင်းသားဆိုးကို ဆရာတော်က ကြိမ်လုံးနှင့်ရိုက်သဖြင့် ကျောတွင်အရှိုးထင်သွားသည်။”')
,(7352,3,1,'၁။ လေးပြည်တစ်စိတ် အခြၚ်အတွယ်တောင်း။','“ပ္ဍဲကာလရိုဟ်ဟ်တ္ၚဲ သ္ၚုမွဲမွဲဒၞိဟ်လၟိုန် သၟိၚ်ဇိုန်ကဵုတောံပုၚ် ကဵုကတအ်ရ။” (ဇ—၂၃၃။ အစွောံ။) = (မြန်မာညောင်ကန်မူ­‘တစ်အမ္ဗဏ’ ဟုဆိုသည်။)')
,(7352,3,1,'၁။ လေးပြည်တစ်စိတ် အခြၚ်အတွယ်တောင်း။','၂။ မီးဖိုနေရာ။ မီးတင်းကုပ်။')
,(7352,3,1,'၁။ လေးပြည်တစ်စိတ် အခြၚ်အတွယ်တောင်း။','“(ကၞုဲစၞာဲဝွံ) ဒနိဟ်ပိုဲရသိ ပၟတ်ယတ်ဂှ်လေဝ် ဍေံကဏေံစုတ်ရ။” (ဇ—၁၇၅။ အစွောံ။) = “(ဤမျောက်စဉ်းလဲသည်) ငါတို့၏မီးတင်းကုပ်ကိုလည်း ကျင်ကြီးစွန့်အပ်၏။” (ညောင်ကန်)')
,(7352,3,1,'၁။ လေးပြည်တစ်စိတ် အခြၚ်အတွယ်တောင်း။','၃။ (ကျွဲနွားမြင်းစသည်၏) စားခွက်။ စားကျင်း။')
,(7352,3,1,'၁။ လေးပြည်တစ်စိတ် အခြၚ်အတွယ်တောင်း။','ဒၞိဟ်ဍာ် = ရေထည့်စရာကျင်း။ (ပါဠိ—ဥဒကဒေါဏိ)')
,(7352,3,1,'၁။ လေးပြည်တစ်စိတ် အခြၚ်အတွယ်တောင်း။','“တၞဟ်နဗ္စချေံဂှ်သတ်မာ်ညးၜိုဟ်ကၠေံတုဲ ညးကေတ်နၚ်သကိုဟ်စုတ် ပ္ဍဲဒၞိဟ်ဂှ်ရ။” (ဇ—၁၇၆။ အစွောံ။) = “မြင်းတို့၏အကျိုးငှာ ကုလားပဲတို့ကို ပြုတ်ပြီးလျှင် ဆောင်ခဲ့ကုန်၍ မြင်းစားခွက်­ ထည့်ကုန်၏။” (ညောင်ကန်)')
,(7352,3,1,'၁။ လေးပြည်တစ်စိတ် အခြၚ်အတွယ်တောင်း။','“ယာဂုကဏန်သ္ၚုကယဳဂှ် သကောဟ်စုတ်ပ္ဍဲဒၞိဟ်ဂှ်တုဲ ကဵုသိန္ဓဴဂှ်စရ။” (ဇ—၂၅၄။အစွောံ။) = “မြင်းစားကျင်း­ ဆန်ခွဲယာဂုကိုလောင်း၍ (သိန္ဓောမြင်းကို) ပေး၏။” (ညောင်ကန်)')
,(7352,3,1,'၁။ လေးပြည်တစ်စိတ် အခြၚ်အတွယ်တောင်း။','၄။ (စောင်း၊ ဗုံစသည်၏) ကိုယ်ထည်။')
,(7352,3,1,'၁။ လေးပြည်တစ်စိတ် အခြၚ်အတွယ်တောင်း။','ဒၞိဟ်ထဏ = စောင်းကိုယ်ထည်။')
,(7352,3,1,'၁။ လေးပြည်တစ်စိတ် အခြၚ်အတွယ်တောင်း။','ဒၞိဟ်ဖံ = ဗုံ၏ကိုယ်ထည်။')
,(7352,3,1,'၁။ လေးပြည်တစ်စိတ် အခြၚ်အတွယ်တောင်း။','၅။ (လှေစသည်၏) ဝမ်းပိုင်း။ ကိုယ်ထည်။')
,(7352,3,1,'၁။ လေးပြည်တစ်စိတ် အခြၚ်အတွယ်တောင်း။','ဒၞိဟ်ဂၠုၚ် = လှေဝမ်း။')
,(7353,3,1,'ခြေဖနောင့်။',NULL)
,(7354,3,6,'ကြောင့်။','“ညးဒၟာအဲ၊ အဲဒၟာညး။ သ္ဒးဗ္ဂူဗြဲမတ်၊ ဟွံတီဇတ်ဍး။” = “သူ့ကြောင့်ငါ ငါ့ကြောင့်သူ မျက်ရည်မိုးရွာရသည်မှာ မခန်းနိုင်မစဲနိုင်ဖြစ်၏။”')
,(7355,3,6,'ကြောင့်။ (because of)','“ဒမာနူဗြဴဂှ် ဒဒိုက်ဇၞော်မဒးတုဲရသွံ။” (ဇ—၂ဝ၇။အစွောံ။) = “ထိုမိန်းမကြောင့် ကြီးစွာသောဒုက္ခ တွေ့ခဲ့ရဖူးပြီ။”')
,(7355,3,6,'ကြောင့်။ (because of)','“ယွံခမဳတံ၊ ကာလအဲမဒှ်ဇာဒိသိုၚ်ဂှ် ဒမာနူကဵုဂအတ်ကရီုအဲဂှ်တုဲ — (ကၠဵုဂှ်) ဖေက်လကိုတ်စိုတ်တုဲ ဖျုန်ဂြိုဟ်ဍေံပါ်အာ—။” ကျာ်တြဲဂး။ (ဇ—၁၅၂။ အစွောံ။) = “ရဟန်းတို့၊ ငါခြင်္သေ့ဖြစ်စဉ်အခါက ငါ၏ဟိန်းဟောက်သံကြောင့် ထိုမြေခွေးသည် ထိတ်လန့်သည်ဖြစ်၍ နှလုံးကွဲ၏။”')
,(7355,3,6,'ကြောင့်။ (because of)','(သဗဓ) အကြောင်းကြောင့်။ သောကြောင့်။ (because)')
,(7355,3,6,'ကြောင့်။ (because of)','“ဒၟာနူအဲဟွံအာဝေၚ်သ္ၚိညး စိုတ်ညးဟွံမိပ်ရ။” = “သူ့အိမ်သို့ ကျွန်တော်မသွားလည်သောကြောင့် သူစိတ်မကောင်းပါ။”')
,(7356,3,5,'သီသီကလေး။ ပွတ်ကာသီကာ။ လုနီး။','“ဒၟာနူညိရ ဆောတ်အာ။” (ဇ—၁၄၂။အစွောံ။) = “သီသီကလေး လွဲသွားသည်။”')
,(7356,3,5,'သီသီကလေး။ ပွတ်ကာသီကာ။ လုနီး။','“ဒၟာနူအပေါတ်ကယိုင်ဝွံဂှ် ဒၟာနူညိရ အဲဟွံချိုတ်” ဍိက်ဗြဴဂး။ (ဇ—၄၁၉။ အစွောံ။) = “ဤလက်ဝတ်တန်ဆာကြောင့် သီသီကလေးလွဲ၍ငါမသေခြင်းဖြစ်၏။”')
,(7357,3,1,'သူယုတ်။ သူယုတ်မာ။','“ဟာဲဒၟိက် ဟာဲခါခဏဳ၊—။” (ဇ—၄၉၇။ အစွောံ။) =“ဟယ်သူယုတ်မာ၊ ဟယ်ကျက်သရေမရှိသောသူယုတ်။”')
,(7357,3,1,'သူယုတ်။ သူယုတ်မာ။','(နဝိ) မကောင်းသော။ ယုတ်သော။')
,(7357,3,1,'သူယုတ်။ သူယုတ်မာ။','မၞိဟ်ဒၟိက် = လူယုတ်မာ။')
,(7357,3,1,'သူယုတ်။ သူယုတ်မာ။','“ဟာဲဗြဴဒၟိက်၊—။” (ဇ—၃ဝ၆။ အစွောံ။) = “ဟယ်မိန်းမယုတ်—။”')
,(7357,3,1,'သူယုတ်။ သူယုတ်မာ။','“ခဍာ်ဒမိက်အရိုၚ် ၜိုပ်ထဝ်ဒးဗိုၚ်သဳကၠဳ။” (လ္ပအ်သၟိၚ်ပဿိုန်) (ဇ—၇၇။ အစွောံ။) =“ယုတ်မာသောကျီးအရိုင်းကို ရွှေဟင်္သာတို့က ခြံရံခစားရသည်။” (ကောသလမင်းအိပ်မက်)')
,(7357,3,1,'သူယုတ်။ သူယုတ်မာ။','“ဟာဲဗမၞးဒမိက်ဒုဿဳလ၊—။” (ဇ—၃၂၆။ အစွောံ။) = “ဟယ်ပုဏ္ဏားယုတ်ဒုဿီလ—။”')
,(7357,3,1,'သူယုတ်။ သူယုတ်မာ။','“ဂလာန်တၠပညာဂှ် ဍေံဒ္ဂေတ်ဗက်။ ဒ္ဂေတ်ဒၟိက်ဂှ် ဍေံဝေၚ်ထောံ။” (ဇ—၄၇၃။ အစွောံ။) = “ပညာရှိစကားကို သူလိုက်နာ၏။ ယုတ်မာသောအကျင့်ကို သူရှောင်ကြဉ်၏။”')
,(7358,3,1,'နေထိုင်ရာ။ တည်နေရာ။','‘ဒမံၚ်’ ရှု။')
,(7358,3,1,'နေထိုင်ရာ။ တည်နေရာ။','(ကြိ) နေသည်။')
,(7358,3,1,'နေထိုင်ရာ။ တည်နေရာ။','“ယွံဣစဳ၊ ဒၟံၚ်အဏအ်မွဲခဏညိ။” = “အဒေါ်ခင်ဗျား၊ ဤမှာခဏလောက်နေပါ။”')
,(7358,3,1,'နေထိုင်ရာ။ တည်နေရာ။','(စည်း) ဆက်လက်ဖြစ်နေခြင်း၊ ပြုနေခြင်းကို ပြသောစကားလုံး။')
,(7358,3,1,'နေထိုင်ရာ။ တည်နေရာ။','စဒၟံၚ် = စားနေသည်။')
,(7358,3,1,'နေထိုင်ရာ။ တည်နေရာ။','တိက်ဒၟံၚ် = အိပ်နေသည်။')
,(7358,3,1,'နေထိုင်ရာ။ တည်နေရာ။','‘မံၚ်’နှင့်အတူတူ။')
,(7359,3,4,'နေသာသည်။ လျစ်လျူရှုသာသည်။','“ဣန်တလက္ဍိုၚ်၊ ကွေံဒၟံၚ်ပိုၚ်ဟာ။” (လိက်သၟိၚ်ဇဲယဒတ္တ) = “သိကြားနတ်မင်းသည် နေသာလျစ်လျူရှုသာမည်လော။”')
,(7359,3,4,'နေသာသည်။ လျစ်လျူရှုသာသည်။','‘ဒၟံၚ်ဟွံပိုၚ်’ (ကြိ) လည်းရှု။')
,(7360,3,4,'နေကောင်းသည်။ ကျန်းမာသည်။','ဒၟံၚ်ဟွံမိပ် = နေမကောင်း။ မကျန်းမာ။')
,(7361,3,1,'‘ဒမံၚ်သတိက်’ ရှု',NULL)
,(7362,3,4,'အိမ်ထောင်နေသည်။ အိမ်ရာထောင်သော လူတို့ဘောင်­နေသည်။',NULL)
,(7363,3,4,'မနေသာ။ လျစ်လျူမရှုသာ။','“(သၟတ်ဗြဴဂှ်) ချိုန်မမိၚ်ပါၚ်ဗောဓိသတ်ဗက်ဂှ်ရ ညံၚ်ရှ်အမြိုတ်ဗတဝ်သာဲ ညးမဖျုၚ်လဝ်ပ္ဍဲကတောဝ်ကီု ပ္ဍဲဂၠံဟဒယဖျုန်ဂြိုဟ်တေံဂှ် ဒဇပ်ဇတဝ်တဴတုဲ ဒၟံၚ်ဟွံပိုၚ် ပခိုၚ်စိုတ်ဟွံမာန်တုဲ (ကွာ်တိတ်ကၠုၚ်ကၟေၚ်သ္ၚိရ။)” (ဇ—၃၈၇။ အစွောံ။) = “ထိုမိန်းမပျိုသည် ဘုရားလောင်းနှုတ်သံကို ကြားရသည်နှင့် အမြိုက်အရသာပျားသကာကိုနားထဲတွင်သွန်းလောင်းသည့်နှယ် နှလုံးသည်းပွတ်­ လှုပ်ရှားတုန်လှုပ်လျက် မနေသာဘဲ စိတ်ကိုခိုၚ်အောင်မထားနိုင်ဘဲ အိမ်ကပြင်သို့ လျှောက်ထွက်လာ၏။”')
,(7363,3,4,'မနေသာ။ လျစ်လျူမရှုသာ။','“(ဗောဓိသတ်ဒှ်သၟိၚ်က ကော်ဒေဝတဴဗြဲ ဒေဝတဴဗြဲ) ဒၟံၚ်ဟွံပိုၚ် ပဗက်ဂလာန်ကတုဲ မဗဂူဖျေံဗြဲ—။” (ဇ—၇၅။ အစွောံ။) =“ဘုရားလောင်းသည် ငါးမင်းဖြစ်၍ မိုးနတ်သားကို ခေါ်သည်ရှိသော် မိုးနတ်သားသည် မနေသာဘဲ မိုးကိုရွာချစေ၏။”')
,(7364,3,1,'‘ဒမံၚ်အရာ’ ရှု။',NULL)
,(7365,3,4,'‘ဒမာန်’ ရှု။',NULL)
,(7366,3,1,'(လှေ) လှော်ခတ်ခြင်း။ အလှော်အခတ်။','“ဗ္ဂေၚ်ဍိုက်ယာန်ဒၟုန်၊ ဖျဳဖျဳဒုန်ဝေၚ်။” (လိက်မေဃသန်) = “လှော်ခတ်ရသောရေယာဉ် (လှေ) ကိုစီးလျက် ဖြည်းညင်းစွာလှော်ခတ်ကစား၏။”')
,(7366,3,1,'(လှေ) လှော်ခတ်ခြင်း။ အလှော်အခတ်။','‘ဒုန်’ (ကြိ) လည်းရှု။')
,(7367,3,1,'‘ဒမေပ်’ ရှု။',NULL)
,(7368,3,1,'အစာမစားပဲနေခြင်း၊ အစာရှောင်ခြင်း။','ဒၟိဟ်အဟာရ (၇) တ္ၚဲ = (၇) ရက်အစာမစားဘဲနေခြင်း။')
,(7369,3,1,'မြေနု။ မြေသစ်။',NULL)
,(7370,3,1,'ယိုးဒယားပြည်။',NULL)
,(7371,3,16,'မည်းသည်။—သော။ မည်းနက်သည်။—သော။','“အကၠဟ်ဝွံလေဝ် ဍေံဒျိုၚ်တဴကီု၊အဲလေဝ် ဒျိုၚ်တဴကီု” ခဍာ်ချပ်။ (ဇ—၂ဝ၄။ အစွောံ။) = “ဤတင်ကျီးသည်လည်း မည်းသောအဆင်းရှိ၏။ ငါသည်လည်း မည်းသောအဆင်းရှိ၏” ဟုကျီးသည်ကြံ၏။ (ညောင်ကန်)')
,(7371,3,16,'မည်းသည်။—သော။ မည်းနက်သည်။—သော။','“ဗောဓိသတ်ပိုဲ တန်ပဋိသန္ဓိ ပ္ဍဲဂၠံဂဝ်ဗမၞိဟ်ဗြဴ ဒးစှ်ဂိတု သၠးဂၠံဂဝ်ရ။ ဟိုတ်သာ်ဇကုမဒျိုၚ်တဴဂှ်ရ ပ္ဍဲတ္ၚဲမခုတ်ယၟုဂှ် ကဏှကုမ္မာ ညးခုတ်ခဴရ။” (ဇ—၄၄ဝ။ အစွောံ။) = “ဘုရားလောင်းသည် ထိုပုဏ္ဏား၏ ပုဏ္ဏေးမဝမ်း­ဖြစ်၏။ မည်းသောအဆင်းရှိသည်၏အဖြစ်ကြောင့်ကား ဘုရားလောင်းအား အမည်မှည့်သောနေ့­ ကဏှသတို့သားဟူသောအမည်ကို မှည့်ကုန်၏။” (ညောင်ကန်)')
,(7371,3,16,'မည်းသည်။—သော။ မည်းနက်သည်။—သော။','“ယွံတၠအဲ၊ညးတၠအဲရော။ တၠအဲမပတၠစရာဲရုပ်ဂေါဝ်လောန်။ မဟွံဂွံသၠုၚ်လောန် မဟွံဂွံသဝ်လောန်၊ မဟွံဂွံကြောအ်လောန် မဟွံဂွံဇြာဲလောန်၊ မဟွံဂွံဒျိုၚ်လောန် မဟွံဂွံဗ္တာၚ်လောန်၊ မပတၠရုပ်ဂေါဝ်လောန်သန်ရောၚ်သွံ” ရသိဍောတ်ဂးကဵုသၟတ်ဗြဴရ။ (ဇ—၅၂၃။ အစွောံ။) = “သင်မည်သူနည်း။ သင်သည် အလွန်တင့်တယ်သော ရုပ်အဆင်းရှိ၏။ မမြင့်လွန်း မနိမ့်လွန်း၊ မဝလွန်း မပိန်လွန်း၊ မမည်းလွန်း မဖြူလွန်း၊ အလွန်တင့်တယ်သော ရုပ်အဆင်းရှင်ပေတည်း။”')
,(7371,3,16,'မည်းသည်။—သော။ မည်းနက်သည်။—သော။','‘ဒမျိုၚ်’ (န')
,(7371,3,16,'မည်းသည်။—သော။ မည်းနက်သည်။—သော။','နဝိ) လည်းရှု။')
,(7372,3,4,'၁။ ပျံသည်။ ပျံဝဲသည်။','“ညံၚ်ကိနနရဳဗြဴ မၞုံဍုတ်သၞေၚ်မစိစောန် မဒျာန်ပဝ်အာလတူအကာသကီု။” (ဇ—ဝေသန္တဝ်။ အစွောံ။) = “ဆန်းကြယ်စွာသော အမြီးတောင်ရှိသော ကိနနရဳမသည် ကောင်းကင်ပြင်­ ဝဲပျံဘိသကဲ့သို့။”')
,(7372,3,4,'၁။ ပျံသည်။ ပျံဝဲသည်။','“(ထေတၠအရှန်ဂှ်) တူကာသဍာန်၊ ကလာၚ်ဒျာန်စဴ။” (လိက်ဗောဓိသတ်စှ်။ ပဏ္ဍိတ။) = “ထိုရဟန္တာမထေရ်သည် အာကာသလမ်းခရီးဖြင့် ပျံကြွတော်မူ၏။”')
,(7372,3,4,'၁။ ပျံသည်။ ပျံဝဲသည်။','“ပြာသာတ်ဂှ် ညံၚ်မၞုံကဵုစေတနာကီု ကလာၚ်တိုန်လတူအမှဲတုဲ ဒျာန်အာ—။” (သၠပတ်ရာဇာသာန်) = “ထိုပြာသာဒ်သည် စိတ်စေတနာရှိလေသကဲ့သို့ ကောင်းကင်ပေါ်ပျံတက်၍ ဝဲပျံသွား၏။”')
,(7372,3,4,'၁။ ပျံသည်။ ပျံဝဲသည်။','၂။ ထိစပ်သည်။')
,(7372,3,4,'၁။ ပျံသည်။ ပျံဝဲသည်။','“ကၞာၚ်ကဵုကၞာၚ်ဂျ၊ သၠကဵုသၠဒျာန်။” (လိက်မာဃဒေဝါန်) = “အကိုင်းအကိုင်းချင်း ပူးယှက်၍ အရွက်အရွက်ချင်း ထိစပ်သည်။”')
,(7372,3,4,'၁။ ပျံသည်။ ပျံဝဲသည်။','၃။ (လက်) မြှောက်ချီလှုပ်ရှားသည်။')
,(7372,3,4,'၁။ ပျံသည်။ ပျံဝဲသည်။','“လ္ၚဵုလှ်ေဟာန်၊ ဒျာန်တိုန်တဲၜါ။” (လိက်မိဍောၚ်ကှ်ေထဝ်) = “အချို့ကလက်နှစ်ဖက်တို့ကို မြှောက်ချီလှုပ်ရှားလျက် ကကြ၏။”')
,(7373,3,1,'အင်တုံ။',NULL)
,(7374,3,12,'(န) ပစ္စည်းဥစ္စာ။',NULL)
,(7375,3,1,'အား။ အင်အား။','အစောံဒြဟတ်၊ ဒြဟတ်အစောံ = စွမ်းအား။ အင်အား။ခွန်အား။')
,(7375,3,1,'အား။ အင်အား။','“ၜိုပ်ထဝ်ဝွံ ဒြဟတ်လေဝ်ထတ် ပရှ်လေဝ်ပြဟ် စိုတ်လေဝ်ခိုဟ်—။” (ဇ—၂၇ဝ။ အစွောံ။) = “ဤရွှေဟင်္သာသည် ခွန်အားလည်းသန်စွမ်း၏၊ အမြန်နှုန်းလည်းမြန်၏၊ စိတ်လည်းကောင်း၏။”')
,(7375,3,1,'အား။ အင်အား။','“ပၞောဝ်ဒြဟတ်ဂမၠိုၚ်ဂှ် ဒြဟတ်ညာန်ပညာမွဲ မဒှ်ကၞောတ်ရ။” (ဇ—၅၂၁။ အစွောံ။) = “အားတကာတို့အနက် ပညာအားသည် အထွတ်အဖျားတည်း။”')
,(7376,3,1,'ဆင်ပြောင်အား။','“ဗောဓိသတ် (သၟိၚ်ကၞုဲ) မၞုံကဵုဒြဟတ်စိၚ်ဇၟူရောၚ်။” (ဇ—၅၇။ အစွောံ။) = “ဘုရားလောင်း (မျောက်မင်း) သည် ဆင်ပြောင်အားနှင့်တူသောဗလရှိ၏။” (ညောင်ကန်)')
,(7377,3,1,'လူဗိုလ်ခြေတစ်ထောၚ်အား။','“တ္ၚအဲမၞုံဒြဟတ်ဒဲလ္ၚီ ညးမပ္တိုန်မာန်ဂှ် ဇိုန်ကဵုကၟိန်ဍုၚ်ရအဴ။” (ဇ—မှာဇနက်။ အစွောံ။) = “လူဗိုလ်ခြေတစ်ထောင်အားရှိသော ငါ၏လေးကို တင်နိုင်သောသူအား တိုင်းပြည်ကိုအပ်နှင်းလော့။”')
,(7378,3,1,'ခွန်အားအစွမ်း။','“ပိုဲညးၜါ နွံတဴကဵုဇြဟတ်အစောံ။” (ဇ—၁၆ဝ။ အစွောံ။) = “အကျွန်ုပ်တို့နှစ်ဦးသည် ခွန်အားအစွမ်းရှိကုန်၏။”')
,(7378,3,1,'ခွန်အားအစွမ်း။','“ဟာဲကၠ၊ — ဗှ်ေတၠဒြဟတ်အစောံရောၚ်သွံ၊ ဗှ်ေအာမွဲဝါရ (အာကိတ်နၚ်ကၠိက်ရ)” ရသိစၞာဲဂး။ (ဇ—၂၈၃။ အစွောံ။) = “ဟယ်ကျား၊ သင်သည် ခွန်အားအစွမ်းနှင့်ပြည့်စုံသူတည်း။ တစ်ဖန်သွားချေ၍ ဝက်တို့ကိုကိုက်၍ ယူလာဦးလော့” ဟုရသေ့စဉ်းလဲဆို၏။')
,(7379,3,5,'ဆင်းရဲစွာဖြင့်။ ပင်ပန်းလျက်။','“ဂုန်ကောန်သ္ဍိုက်၊ ဒဒိုက်ရိုဟ်တ္ၚဲ။ ဒဒိုက်ဒြဲဒြဲ၊ ဟွံမွဲအခိၚ်။” (လိက်သုပိဏ္ဏကုမ္မာ။ မၚ်သၚ်ကြာ။) = “ချစ်သားငယ်ကြောင့် နေ့တိုင်းဒုက္ခဖြစ်၏၊ဒုက္ခဖြင့်ပင်ပန်းလျက် (အလုပ်များ၍) အချိန်မရှိ။”')
,(7380,3,5,'‘ဂြောဂြော’ ရှု။',NULL)
,(7381,3,4,'ထိတ်လန့်သည်။',NULL)
,(7382,3,5,'ထိတ်လန့်တုန်လှုပ်လျက်။ ကြက်သီးမွေးညှင်းထလျက်။','“မတ်ၜါထၜိက်ဂၠု၊ ဇကုဒှ်တဴဂြဴဂြဴ။” (လိက်လက္ခဏဒိပ္ပဗိန္ဒော) = “မျက်စိနှစ်ကွင်းလည်း ပိတ်မှောင်၍ ကိုယ်လည်းကြက်သီးမွေးညှင်းထ၏။”')
,(7382,3,5,'ထိတ်လန့်တုန်လှုပ်လျက်။ ကြက်သီးမွေးညှင်းထလျက်။','“ဘိၚ်တလိၚ်ဒိုဟ်၊ ဖျုန်ဂြိုဟ်ဒြဴဒြဴ။” (လိက်သၟိၚ်ဇဲယဒတ္တ) =“ကြက်သေသေ၍ အရပ်မျက်နှာကို အမှတ်မှားလျက် စိတ်နှလုံးထိတ်လန့်တုန်လှုပ်၏။”')
,(7383,3,1,'ဦးချို။','ဒြၚ်ပြေၚ် = ကျွဲချို။')
,(7383,3,1,'ဦးချို။','ဒြၚ်စိၚ် = ဆင်စွယ်။')
,(7384,3,1,'ဗျိုင်း။ ဗျိုင်းအောက်မ။ (ပါဠိ—ဗလာကာ)','“ဟာဲဂစေံဂံက်ဒြၚ်မၞုံကဵုဂၠောန်၊ဗှ်ေညးဂှ်ရော။ ဗှ်ေကမၠတ် သပေဲါခ္ဍာ်အဲဂှ်ရောၚ်သွံ။ ဂံက်ဒြၚ်ဂှ်ဒှ်ကောန်စဴ မတ်ဗြဲဂှ်ဒှ်လဍေံရောၚ်။” (ဇ—၃၇၅။ အစွောံ။) = “ဦးစွန်းရှိသော နေရာတောင်းကိုခိုးသော မိုးဟူသောအဘိုးရှိသော ဤဗျိုင်းအောက်မသည် အဘယ်ဗျိုင်းအောက်မနည်း။” (ညောင်ကန်)')
,(7385,3,1,'၁။ ကျောက်ဆူး။','၂။ တောင်အစွန်း။')
,(7386,3,3,'‘ဂြၚ်ဖအက်’ ရှု။','‘တိဒြၚ်ဗအက်’ (န) လည်းရှု။')
,(7387,3,1,'ဒန့်ကျွဲပင်။',NULL)
,(7388,3,1,'လက်ကောက်။ လက်ဝတ်တန်ဆာ။','“ကောန်ဗြဴဝုတ်ဇကုမွဲဂှ် ကဵုကျိုၚ်ကျဝ်လစိန်လကံက်ဒြၚ်ဗံက်—။” (ဇ—၃၇၄။ အစွောံ။) = “မိမိ၏သမီးပျိုအား လက်စွပ်လက်ကောက် လက်ဝတ်တန်ဆာများကို ဝတ်စားဆင်ယင်စေ၏။”')
,(7389,3,1,'ကြောင်လျှာသီး။',NULL)
,(7390,3,1,'ကောက်နယ်တလင်း။ (ပါဠိ—ခလ','ခလမဏ္ဍလ)')
,(7390,3,1,'ကောက်နယ်တလင်း။ (ပါဠိ—ခလ','“ဂတာံထဝ်မွဲနွံ ဇၞော်လောန်ဇကုဍေံတမာဒြာၚ်ဇမၞော် ဍေံရပ်စစိၚ်လၟိုန်—။” (ဇ—၂၆၇။ အစွောံ။) = “ထိုဗုဇွန်ကြီးသည်ကောက်နယ်တလင်းဝန်းပမာဏရှိ၏။ (ဆင်တို့ကို အမြဲဖမ်းစား၏။)” (ညောင်ကန်)')
,(7391,3,1,'အိုးမဲ။ ကျပ်ခိုး။ ထမင်းအိုးမၚ်။','“မုက်လံက်ဒြိၚ်ပၠန်၊ ဂိုၚ်ပ္တန်လယ။” (လိက်ပဒုမဝတဳ)')
,(7392,3,1,'ရန်လိုခြင်း။ ရန်လိုသောစိတ်။ ရန်ငြိုး။','“တန်ဒက်စိုတ် ဒေပ်စိုတ်ဒြေၚ်သၟ သာ်ဂှ်ဟွံဂွံပ။” (ဇ—၁၃၁။ အစွောံ။) = “ရန်ငြိုးဖွဲ့၍ ရန်စိတ်ထားတန်ရာသော်လည်း ထိုကဲ့သို့မပြု။”')
,(7392,3,1,'ရန်လိုခြင်း။ ရန်လိုသောစိတ်။ ရန်ငြိုး။','“သီုၜါက္ဍိုၚ်ဗ္တာၚ် တုပ်ညံၚ်ကလိဂွံသမ္ပတ္တိသွဝ်မွဲစွံ ၜိုဟ်သြိုဟ်ဟွံမွဲဂမ္တံၚ်ဂမ္တဴ ဟွံဂွံဒှ်ဒြေၚ်သၟကဵုရၚ်သ္ကံဟွံမွဲ။” (အကြီုရာဇာဓိရာဇ်) = “တိုင်းပြည်ထီးနန်းနှစ်ခုလုံးသည် နတ်စည်းစိမ်ကို အတူတကွရရှိသည်နှင့်တူ၏။ ဆူပူခြင်းမရှိ အေးချမ်းသာယာ၍ အချင်းချင်းရန်လိုခြင်းမရှိ။”')
,(7392,3,1,'ရန်လိုခြင်း။ ရန်လိုသောစိတ်။ ရန်ငြိုး။','‘ဒြေၚ်သၠ’ဟုလည်းတွေ့ရသည်။')
,(7392,3,1,'ရန်လိုခြင်း။ ရန်လိုသောစိတ်။ ရန်ငြိုး။','“ညးမဒေပ်စိုတ်ဒမြိုဟ်ဒြေၚ်သၟ။” (သၠပတ်သတိပထာန်) = “ကြမ်းကြုတ်ရန်လိုသောစိတ်ထားရှိသောသူ။”')
,(7392,3,1,'ရန်လိုခြင်း။ ရန်လိုသောစိတ်။ ရန်ငြိုး။','“အာဟွံကလေၚ်၊ ဒေပ်စိုတ်ဒြေၚ်သ္မ။ ဒဇန်လောန်ကာဲ၊ကောဗၠာဲမှာယ။” (လိက်ကောန်သၟိၚ်ပိ။ မာံခစုန်အံက်။) = “သွားပြီးပြန်မလာ ရန်လိုသောစိတ်ထားရှိ၏၊ ချစ်သူမောင်သည် အလွန်ရက်စက်၏။”')
,(7393,3,4,'ကိုယ်ကိုမာအောင် တောင့်ထားသည်။','ကၞုဲအလံၚ်ဒေဝဒတ်ဂှ် “ဇကုအဲသ္ဇိုၚ်ဒၟံၚ်ဒြံၚ်လဝ် ရပ်ကဵုဗိုန်” ဍေံဂးတုဲ ဍေံဆင်စှ်ေပ္ဍဲစးဗောဓိသတ် (သၟိၚ်ကၞုဲ) ဂှ်တုဲ—။ (ဇ—၄ဝ၇။ အစွောံ။) = ဒေဝဒတ်လောင်းမျောက်က “ငါ၏ကိုယ်သည်ကား လေး၏။ သင်သည် ကိုယ်ကိုမာအောင်တောင့်ထားပြီး မြဲမြဲသာကိုင်ထားပေတော့” ဟုဆိုကာ ဘုရားလောင်းမျောက်မင်းကျောပေါ်သို့အဟုန်ဖြင့်ခုန်ချ၏။')
,(7394,3,4,'ကြဲသည်။ ကြဲပက်သည်။ (ပါဠိ—အာကိရတိ)','“ရတ်ထပှ်ပြကာလေဝ် ဒြာတ်ပပူဇဴရ။” (ဇ—၄၇၉။ အစွောံ။) = “ရတနာခုနစ်ပါးတို့ကိုလည်း ကြဲ၍ပူဇော်၏။”')
,(7395,3,4,'ပျိုးကြဲသည်။','“ပိုဲဒြာတ်မညိကၠာ။” (ဇ—၁၃၃။ အစွောံ။) = “အကျွန်ုပ်တို့ ပျိုးကြဲကုန်ဦးအံ့။”')
,(7396,3,4,'အလွန်အမင်းဆင်းရဲသည်။ ကုန်းကောက်စရာမရှိအောင် ဆင်းရဲသည်။','“ဒးဒိုက်ဒြုတ်ဒြာတ်၊ ယာတ်ကဲလဝဲ။ ညးပကုသဵု၊ ဆဵုဒဴထောံသ္ၚောဲ။” (လိက်သုပိဏ္ဏကုမ္မာ။ မၚ်သၚ်ကြာ။) = “ကုန်းကောက်စရာမရှိအောင်ဆင်းရဲ၍ အဝတ်ဖိုသီဖတ်သီဖြင့် သူတကာကုသိုလ်ပြုသည်ကိုမြင်လျှင် ဝေးဝေးကရှောင်ဖယ်၏။”')
,(7397,3,1,'ခြကောင်။ ခြပုန်း။','တၞအ်ဒြုန် = ခြတောင်ပို့။')
,(7397,3,1,'ခြကောင်။ ခြပုန်း။','“ညံၚ်ရဴဒြုန်ကမုမစိစောန် မပေၚ်ဒၟံၚ်နအသုဘ။” (ဇ—၁၃၈။ အစွောံ။) = “မစင်တို့ဖြင့်ပြည့်နေသော ဆန်းကြယ်လှပသော ဖြူသောပိုးခြကဲ့သို့။”')
,(7398,3,12,'(န) ၁။ ဓါတ်တော်ဝေသော ဒေါနပုဏ္ဏား၏ အခြၚ်အတွယ်ခြင်းတောင်း။ စရွတ်တလား။ စားခွက်။ ပက်ခွက်။ အိုး။','ဓါတ်ကျာ်ၜါဒြိုန် = ဘုရားဓါတ်တော်နှစ်တောင်း။')
,(7398,3,12,'(န) ၁။ ဓါတ်တော်ဝေသော ဒေါနပုဏ္ဏား၏ အခြၚ်အတွယ်ခြင်းတောင်း။ စရွတ်တလား။ စားခွက်။ ပက်ခွက်။ အိုး။','“သၟိၚ်နာဲပိုဲညးကောသလရးဝွံ သဒီုလောန်သန်ကွေံရောၚ်။ ဆမစဘောဇိုန်မွဲဒြိုန်ဂှ်ကီု မတီရောၚ်။” (ဇ—၄၉၂။ အစွောံ။) = “ဤကောသလမင်းသည် မိုက်စွတကား။ တအိုးမျှလောက်သော ထမင်းကိုသာလျှင် စားခြင်းငှာသိ၏။” (ညောင်ကန်)')
,(7398,3,12,'(န) ၁။ ဓါတ်တော်ဝေသော ဒေါနပုဏ္ဏား၏ အခြၚ်အတွယ်ခြင်းတောင်း။ စရွတ်တလား။ စားခွက်။ ပက်ခွက်။ အိုး။','၂။ (ဆန်၊ စပါးစသည်) ထားရာနေရာ။')
,(7398,3,12,'(န) ၁။ ဓါတ်တော်ဝေသော ဒေါနပုဏ္ဏား၏ အခြၚ်အတွယ်ခြင်းတောင်း။ စရွတ်တလား။ စားခွက်။ ပက်ခွက်။ အိုး။','ဒြိုန်သြောံ = စပါးထားရာနေရာ။ စပါးထားရာအင်းပျဉ်။')
,(7398,3,12,'(န) ၁။ ဓါတ်တော်ဝေသော ဒေါနပုဏ္ဏား၏ အခြၚ်အတွယ်ခြင်းတောင်း။ စရွတ်တလား။ စားခွက်။ ပက်ခွက်။ အိုး။','“(သၟိၚ်ကုသတုန်) ကာလသ္တိက်ဂှ် လတူဒြိုန်သြောံဂှ် ဂွံသတိက်ရ။” (ဇ—၅၃၁။ အစွောံ။)')
,(7398,3,12,'(န) ၁။ ဓါတ်တော်ဝေသော ဒေါနပုဏ္ဏား၏ အခြၚ်အတွယ်ခြင်းတောင်း။ စရွတ်တလား။ စားခွက်။ ပက်ခွက်။ အိုး။','၃။ (၁ဝ) ပြည်ပမာဏရှိသောတောင်း။')
,(7398,3,12,'(န) ၁။ ဓါတ်တော်ဝေသော ဒေါနပုဏ္ဏား၏ အခြၚ်အတွယ်ခြင်းတောင်း။ စရွတ်တလား။ စားခွက်။ ပက်ခွက်။ အိုး။','“(၂) တၠတ် ဒှ်မွဲတုံနာလဳ။ (၅) တုံနာလဳ ဒှ်မွဲဒြိုန်။” (သၠပတ်နိယမ (၅) နဲ (၁၅) ဒြပ်—၁ (န) ဥစ္စာ။')
,(7399,3,12,'(န) ဒြပ်။ အထည်ကိုယ်။ အကောင်အထည်။',NULL)
,(7400,3,1,'ပစ္စည်းဥစ္စာ။ စည်းစိမ်ဥစ္စာ။','“ဆဝတ္ထုဒြပ်ကသပ်နွံ ကဵုကၠေံဒါန်တုဲ—။” (ဇ—၃၁၂။ အစွောံ။) = “ရှိသမျှပစ္စည်းဥစ္စာတို့ကို အလှူပေး၍။”')
,(7400,3,1,'ပစ္စည်းဥစ္စာ။ စည်းစိမ်ဥစ္စာ။','“ယြဴပူဂဵုမွဲ မၞုံကဵုဒြပ်ကသပ်ရ။” (ဂလာန်ညးတမၠာ (၂၈) သာ်) ဒြပ်ဂလေံညး (န) သူတစ်ပါးထံမှ ချေးယူထားသောဥစ္စာ။')
,(7401,3,1,'မိမိ၏အင်္ဂါဇာတ်။ ယောကျာ်းအင်္ဂါဇာတ်။',NULL)
,(7402,3,1,'အရင်းအနှီး။','‘တံဒြပ်’ နှင့်အတူတူ။')
,(7403,3,1,'ဒြပ်နှော။ (ဓာတုဗေဒသုံး) (ဒြပ်စင်များ သာမန်အားဖြင့် မူလဂုဏ်များ ဓါတ်မပြောင်းဘဲ ရောနှောနေသောအရာ။)',NULL)
,(7404,3,1,'ဒြပ်ပေါင်း။ (ဓာတုဗေဒသုံး) (ဒြပ်စင်များ အချိုးမှန်ကန်စွာ မူလဂုဏ်များဓါတ်ပြောင်းကာ စုပေါင်းနေသောအရာ။)',NULL)
,(7405,3,1,'၁။ ဥစ္စာစည်းစိမ်။ အိမ်အသုံးအဆောင်ပစ္စည်း။','“မူစိဗၞတ်ဂမၠိုၚ်ဒြပ်ဝၚ် မကေတ်ဇွောအ်မရော” သၟိၚ်သၟာန်သၟာတ္ၚ။ ‘မွဲသၞာံဂှ် ဒြပ်မွဲမွဲလက် ဆဗၞတ်ဂှ် အဲဒးဂၞပ်ရ’ သၟာတ္ၚဂး။” (ဇ—၁၈၁။ အစွောံ။) = “အဘယ်မျှသောစည်းစိမ်ကို အဖိုးအခအဖြစ် အလိုရှိသနည်း’ ဟုမင်းသည် လေးသမားအားမေး၏။ “တစ်နှစ်လျှင် တစ်သိန်းသောဥစ္စာကို အလိုရှိပါ၏” ဟုလေးသမားဆို၏။')
,(7405,3,1,'၁။ ဥစ္စာစည်းစိမ်။ အိမ်အသုံးအဆောင်ပစ္စည်း။','“အဲတိတ်ပခမဳ သ္ဂောံဒှ်ဟွံမွဲကဵုဒြပ်ဝၚ်တုဲ — မသက္ကုပရိုက်ဘဲဂှ် မဂွံဒှ်ရောၚ်” သၟိၚ်ချပ်။ (ဇ—၄ဝ၈။ အစွောံ။) = “ငါသည် တောထွက်ရဟန်းပြု၍ စည်းစိမ်ဥစ္စာမရှိသည်ဖြစ်၍ဘေးအန္တရာယ်မရှိသည်ဖြစ်လတ္တံ့” ဟုမင်းကြံ၏။')
,(7405,3,1,'၁။ ဥစ္စာစည်းစိမ်။ အိမ်အသုံးအဆောင်ပစ္စည်း။','၂။ ခန်းဝင်ပစ္စည်း။ (လက်ထပ်မင်္ဂလာတွင်နှစ်ဖက်မိဘတို့က ချီးမြှင့်ပေးကမ်းသော ဥစ္စာပစ္စည်း။)')
,(7406,3,1,'ဒြပ်စၚ်။ (ဓာတုဗေဒသုံး) (ဓါတုဗေဒသဘောဖြင့် ထပ်မံ၍မခွဲစိတ်နိုင်တော့သောဒြပ် (ဒြပ်—၂ ရှု။)',NULL)
,(7407,3,4,'ပြေးသည်။','‘ဒြေပ်’ နှင့်အတူတူ။')
,(7408,3,4,'ပြေးသည်။',NULL)
,(7409,3,4,'ထွက်ပြေးသည်။ ပြေးရှောင်သည်။','“ကမၠတ်ဂှ် ဍေံဒြေပ်ဒဴအာကၠေံရ။” = “သူခိုးသည် ထွက်ပြေးသွား၏။”')
,(7410,3,4,'(ဆူးခက်စသည်ဖြင့်) ကာရံသည်။','“တၞံမုက်ဂှ် ညးခြိုၚ်ဒြာံခြံၚ်လဝ် ဗွဲမဗိုန်ရောၚ်။” (ဇ—၁၇၇။ အစွောံ။) = “ထိုတည်ပင်ကို လူတို့သည် (ဆူးခက်တို့ဖြင့်၄င်း ဝါးတို့ဖြင့်၄င်း) မြဲမြံစွာ ထွေးယှက်ကာရံထား၏။”')
,(7410,3,4,'(ဆူးခက်စသည်ဖြင့်) ကာရံသည်။','“ထဴဗျုမွဲဂှ် — ဒဝ်ကၠေံတရၚ်သ္ၚိတုဲ ဒြာံကၠေံဇလတုဲဖေက်ဗၠာဲသၟိၚ်တုဲ လုပ်အာဂြိုပ်ရ။” (ဇ—၅၂ဝ။ အစွောံ။) = “တစ်ယောက်သောလူအိုသည် အိမ်တံခါးကိုပိတ်၍ ဆူးခက်တို့ဖြင့်ကာရံ၍ မင်းချင်းတို့ကို ကြောက်သည်ဖြစ်၍ တောသို့ဝင်သွား၏။”')
,(7410,3,4,'(ဆူးခက်စသည်ဖြင့်) ကာရံသည်။','“ဖေက်ဗၠာဲသၟိၚ်တုဲ အဲမဒးဂြာံဇလကဵုသ္ၚိတုဲ မဒးဒဴဗၠာဲသၟိၚ်တံရောၚ်။” (ဇ—၅၂ဝ။ အစွောံ။) = “မင်းချင်းတို့ကိုကြောက်၍ ငါသည် အိမ်ကိုဆူးတို့ဖြင့်ကာရံ၍ မင်းချင်းတို့ကို ရှောင်ပြေးရ၏။”')
,(7410,3,4,'(ဆူးခက်စသည်ဖြင့်) ကာရံသည်။','“မ္ၚးကၟာဂှ် ဂြာံလဝ်ဇလရ။” (ဓမ္မဒေသနာ။ မာံရွှေငိုး။) = “ရေကန်၏အပြင်ဘက်­ ဆူးခက်ဖြင့်ကာရံထား၏။”')
,(7411,3,4,'(ဆူးခက်စသည်ဖြင့်) ပတ်ပတ်လည်ကာရံသည်။ ထက်ဝန်းကျင်မှကာရံသည်။ (ပါဠိ—ပရိက္ခိပတိ','ဂေါပေတိ)')
,(7411,3,4,'(ဆူးခက်စသည်ဖြင့်) ပတ်ပတ်လည်ကာရံသည်။ ထက်ဝန်းကျင်မှကာရံသည်။ (ပါဠိ—ပရိက္ခိပတိ','“ရုက္ခံ။ န်တၞံဆုသၚ်။ သာခါဟိ။ နကဵုကၞာၚ်ဇလဂမၠိုၚ်။ ပရိဝါရေတွာ။ဒြာံသ္ဍဴတုဲ။ ရက္ခတိ။ ပ္ဍံမၚ်မွဲလဝ်ရ။” (တြာဲဝိနယသၚ်ရိုဟ်ဂြဳ။ စန္ဒိမာ။) = “သံဃာ့သစ်ပင်အားဆူးကိုင်းဆူးခက်များဖြင့် (လုံခြုံအောင်) ကာရံ၍ စောင့်ရှောက်ထား၏။”')
,(7411,3,4,'(ဆူးခက်စသည်ဖြင့်) ပတ်ပတ်လည်ကာရံသည်။ ထက်ဝန်းကျင်မှကာရံသည်။ (ပါဠိ—ပရိက္ခိပတိ','“မၞိဟ်ဂမၠိုၚ်မတဴပ္ဍဲကွာန်ဇမၞော်တံဂှ်တုန် ဟိုတ်နူမဖေက်ဍိက်သၟိၚ်ဗၠာဲသၟိၚ်တုဲ ပ္ဍဲဝုတ်ဒိုဟ်သ္ၚိဇကုဂှ် ဒြာံသ္ဍဴလဝ်တုဲ ပ္ဍဲပထမအရှိုန်ဂှ် ဒဴလုပ်အာဂြိုပ်ရ။” (ဇ—၅၂ဝ။ အစွောံ။) = “လူတို့သည် မင်းသံတမန်မှ ကြောက်ကုန်သောကြောင့် အိမ်တို့ကို ဆူးခက်တို့ဖြင့်ခြံရံ၍ ညဉ့်­နေ၍ အရုဏ်တက်သောအခါကလျှင် တောသို့ပြေးဝင်ရကုန်၏။” (ညောင်ကန်)')
,(7412,3,4,'‘သြုန်ဂြာံ’ နှင့်အတူတူ။',NULL)
,(7413,3,5,'တထိတ်ထိတ်။ ရင်တမမ။ ရင်ဖိုလျက်။','“မိလောမ်လာဲတဴ၊ ကောဂၞဴဟွံတီ။ရိုဟ်ရိုဟ်မဗှ်၊ သြိုဟ်ဒှ်ဒြီဒြီ။” (လိက်သၟိၚ်ဇဲယဒတ္တ) = “မယ်ဝမ်းနည်းပူဆွေးနေရသည်ကို မောင်မသိလေယောင်တကား။ မယ်တွေးလေတိုင်း ရင်တထိတ်ထိတ် ရင်တမမဖြစ်ရ၏။”')
,(7414,3,5,'(လူစုလူဝေး) ကျယ်လောင်သောအသံဖြင့်။ အုတ်အုတ်သဲသဲသောအသံဖြင့်။','ကျာ်တြဲထအှ်တိုန်ရ။ “ယွံတဳလမၞုံကုပိုန်၊ တဳလမၞုံကုပိုန် ကဵုဂၠိၚ်အာယုက်ညိ’ ဂးတုဲ ဒြီုဒြီုခမဳတံဟီုတဴရ။” (ဇ—၁၅၅။ အစွောံ။) = (မြတ်စွာဘုရား) ချေတော်မူ၏။ ရဟန်းတို့သည် “အရှင်ဘုရား၊ ဘုန်းတော်ကြီးသောမြတ်စွာဘုရားသည် သက်တော်ရှည်စေသော” ဟု ကျယ်သောအသံအုတ်အုတ်သဲသဲသောအသံကို ပြုကုန်၏။ (ညောင်ကန်)')
,(7414,3,5,'(လူစုလူဝေး) ကျယ်လောင်သောအသံဖြင့်။ အုတ်အုတ်သဲသဲသောအသံဖြင့်။','“မှာဇန်တံညးဂမၠိုၚ် တိုက်တဲသဝဲယာတ် ကဵုသာဓုကာဒြီုဒြီု မကမွဲလ္ၚီတုဲ ပပူဇဴဗောဓိသတ်အိုတ်ရ။” (ဇ—၅၁၅။ အစွောံ။) =“လူများသည် ဟစ်ကြွေးကြော်ငြာ လက်ပမ်းပေါက်ခတ်လျက် ကောင်းချီးတထောင်ကိုပေး၍ (ဘုရားလောင်းအား ပူဇော်ကုန်၏။)” (ညောင်ကန်)')
,(7414,3,5,'(လူစုလူဝေး) ကျယ်လောင်သောအသံဖြင့်။ အုတ်အုတ်သဲသဲသောအသံဖြင့်။','“သမ္ဘာထပှ်ကၠံတံဂှ် ကၠုၚ်စိုပ်တုဲ ရပ်လဝ်ဇိုၚ်ဗောဓိသတ်တုဲ ယာံတဴဒြီုဒြီုအိုတ်ရ။” (ဇ—၅၂၅။ အစွောံ။) = “ဘုရားလောင်း၏ ခုနစ်ရာသောမိဖုရားတို့သည် လာလတ်ကုန်၍ ဘုရားလောင်းခြေတော်တို့ကိုကိုင်လျက် အုတ်အုတ်သဲသဲ ငိုကြွေးကြကုန်၏။”')
,(7414,3,5,'(လူစုလူဝေး) ကျယ်လောင်သောအသံဖြင့်။ အုတ်အုတ်သဲသဲသောအသံဖြင့်။','“မၞိဟ်ဒေဝတဴတံ ကဵုတဴသာဓုကာဂြီုဂြီုအိုတ်ရ။” (ဇ—၅၃၆။ အစွောံ။) =“လူနတ်အပေါင်းတို့သည် ကျယ်လောင်သောအသံဖြင့် ကောင်းချီးပေးကြကုန်၏။”')
,(7415,3,5,'စုစုရုံးရုံး။','“ဂြီုဂြီုကာန်ကာန်၊ ဗဵုပၞာန်ဂမၠိုၚ်။” (လိက်ဗြရတ်ဣဏၚ်ကၚ်ရဳ) = “စစ်သည်ဗိုလ်ပါများ စုစုရုံးရုံး။”')
,(7416,3,5,'သာယာနာပျော်ဖွယ်သောအသံဖြင့် ကျယ်လောင်စွာ။','“ဂစေံမကမွဲပြကာ မဗြုတမှိၚ်တမှဴဒၟံၚ် ညံၚ်ကွိၚ်သဒ္ဒါရီု ဒြီုဒြီုသြဳသြဳ—။” (ဇ—ဝိဓုရ။ အစွောံ။) = “ငှက်မျိုးစုံတို့သည်သဒ္ဒါရုံတူရိယာသဖွယ် သာယာနာပျော်ဖွယ်သောအသံဖြင့် ကျယ်လောင်စွာ မြည်ကြွေးနေကြကုန်၏။”')
,(7417,3,1,'သမင်။','“ဗောဓိသတ်ပိုဲ ဒှ်ဒြာဲထဝ်။” (ဇ—၃၅၉။ အစွောံ။) = “ဘုရားလောင်းသည်ရွှေသမင်ဖြစ်၏။”')
,(7418,3,1,'သမင်ပျံ။ (ပါဠိ—ဝါတမိဂ) (an antelope)','“ဒၞာဲဂှ် ဒြာဲကျာမွဲနွံ။” (ဇ—၃၉၈။ အစွောံ။) (မြန်မာညောင်ကန်မူ­ ‘ဧဏီမည်သောသား’ ဟုဆို၏။)')
,(7419,3,1,'ဆတ်တစ်မျိုး။ (ပါဠိ—မိဂမာတုကာ)',NULL)
,(7420,3,1,'စာမရီသားကောင်။',NULL)
,(7421,3,1,'စိုင်။','“ဒေဝတဴပန် ပရုပ်ဒြာဲမၚ် ဇက်ဏာကွဳရ။” (ဇ—ဝေသန္တဝ်။ အစွောံ။) = “နတ်သားလေးယောက်တို့သည် စိုင်လေးစီးအသွင်ဖန်ဆင်း၍ ရထားထမ်းပိုးခွင်သို့ဝင်ပြီးလျှင် ရုန်းဆောင်လေကုန်၏။” (မင်းပူးဦးသြဘာသ)')
,(7421,3,1,'စိုင်။','“ဒေဝတဴပန် ပတုပ်ရုပ်ဒြာဲမၚ်ပန် မယိုက်ဏာကွဳ—။” (ဇ—ဝေသန္တဝ်။ အစွောံ။) ဒြာဲသရဘ (န) သမင်ဆီးဆောက်။ (ပါဠိ—သရဘ')
,(7421,3,1,'စိုင်။','သရဘမိဂ)')
,(7421,3,1,'စိုင်။','“ဗောဓိသတ်ပိုဲ ဒှ်ဒြာဲသရဘ။” (ဇ—၄၈၃။ အစွောံ။) = “ဘုရားလောင်းသည် သမင်ဆီးဆောက်အမျိုး­ဖြစ်၍—။” (ညောင်ကန်)')
,(7422,3,1,'သမင်ငယ်။ ဧဏီမည်သောသား။ (ပါဠိ—ဨဏိမိဂ)','‘ဒြာဲဨမွဲဂှ်။’ (ဇ—၅ဝ၃။ အစွောံ။) = ‘တခုသောဧဏီမည်သောသားသည်—။’ (ညောင်ကန်)')
,(7423,3,1,'တယော (တူရိယာပစ္စည်း) ။',NULL)
,(7424,3,1,'ချက်ပြုတ်သည်။','(န) စားဖိုမှူး။ စားတော်ချက်။')
,(7425,3,4,'၁။ (ကလေး) ပူဆာသည်။ အငိုဆိုးသည်။','“ကောန်ၚာ်ဏအ် ဂြဟ်ကွေံရ။”= “ဤကလေးသည် အလွန်ပူဆာသည်။”')
,(7425,3,4,'၁။ (ကလေး) ပူဆာသည်။ အငိုဆိုးသည်။','၂။ (ခြင်္သေ့) ဟိန်းသည်။ ဟောက်သည်။')
,(7425,3,4,'၁။ (ကလေး) ပူဆာသည်။ အငိုဆိုးသည်။','“ဇာဒိသိုၚ်တိတ်ကၠုၚ်နူဂိုဟ်ထဝ် ညာတ်သၟိၚ် ဒြဟ်ဂစိုတ်ကၠေံရ။” (သၠပတ်ဒ္ၚောဝ်သၜောံ) = “ခြင်္သေ့သည် ရွှေဂူမှထွက်၍ မင်းကိုမြင်လတ်သော် ဟိန်းဟောက်၍ သေစေ၏။”')
,(7425,3,4,'၁။ (ကလေး) ပူဆာသည်။ အငိုဆိုးသည်။','“တ္ၚဲဇာဒိသိုၚ်ကလေၚ်ကၠုၚ်ပၠန်တုဲ ဒြဟ်မ္ဂး ပိုဲမဒးချိုတ်ရမၞးတံ” ကၠိက်ဂမၠိုၚ်ဂး။ (ဇ—၁၅၃။ အစွောံ။) = “ခြင်္သေ့ပြန်လာသောနေ့ ဟောက်သည်ရှိသော် ငါတို့သေရကုန်တော့မည်” ဟုဝက်များဆို၏။')
,(7426,3,4,'ပူဆာသည်။ ထပ်တလဲလဲတောင်းဆိုသည်။','“နာဲစဴရိုဟ်တ္ၚဲ၊ ဟွံဟီုမွဲဝါ။တ္ၚဲဝွံမူဒှ်၊ နာဲဟီုဒြဟ်စာ။” (လိက်သၚ်ဂဒါ။ သဳလဝန္တ။) = “နေ့တိုင်းသင်အိမ်ပြန်ရောက်၍ မပြောစဖူး။ ဤယနေ့­ အဘယ်ကြောင့် သင်တောင်းဆိုပူဆာရလေသနည်း။”')
,(7427,3,4,'(ကျေးဇူးရှင်၊ အဆွေခင်ပွန်းစသူအား) ပြစ်မှားသည်။ ကြမ်းကြုတ်စွာကြံစည်၊ပြောဆို၊ ပြုမူသည်။ နှိပ်စက်သည်။','“လ္ပဒြိုဟ်ကဵုတၠဂုန်ဇကုညိ။” = “မိမိ၏ကျေးဇူးရှင်အားမပြစ်မှားပါနှင့်။”')
,(7427,3,4,'(ကျေးဇူးရှင်၊ အဆွေခင်ပွန်းစသူအား) ပြစ်မှားသည်။ ကြမ်းကြုတ်စွာကြံစည်၊ပြောဆို၊ ပြုမူသည်။ နှိပ်စက်သည်။','“ပဟိုတ်ကဵုဒေဝဒတ် မဂြိုဟ်ကဵုကျာ်ဂှ်တုဲ ရုရုမိဂဇာတ် ကျာ်တြဲတွံ။” (ဇ—၄၈၂။ အစွောံ။) = “မြတ်စွာဘုရားအား ပြစ်မှားသောဒေဝဒတ်ကို အကြောင်းပြု၍ ရုရုမိဂဇာတ်ကို မြတ်စွာဘုရား ဟောတော်မူ၏။”')
,(7427,3,4,'(ကျေးဇူးရှင်၊ အဆွေခင်ပွန်းစသူအား) ပြစ်မှားသည်။ ကြမ်းကြုတ်စွာကြံစည်၊ပြောဆို၊ ပြုမူသည်။ နှိပ်စက်သည်။','“ယြဴပူဂဵုမွဲဂှ် ဂွံဂြၚ်ဂုန်ညး ဂွံခၠေဝ်ရော်ဂုန်ညး ဂွံဗှ်ဗၞုဟ်တဴဂုန်ညးလၟိုန်ဂှ် ပူဂဵုဂှ် သတြုဒြိုဟ်ဟွံမာန်ရ။” (ဇ—၃ဝ၂။ အစွောံ။) = “သူ့ကျေးဇူးကိုသိသော သူ့ကျေးဇူးကိုဆပ်သော သူ့ကျေးဇူးကို အစဉ်သတိရအောက်မေ့သောပုဂ္ဂိုလ်အား ရန်သူသည်မနှိပ်စက်နိုင်။”')
,(7427,3,4,'(ကျေးဇူးရှင်၊ အဆွေခင်ပွန်းစသူအား) ပြစ်မှားသည်။ ကြမ်းကြုတ်စွာကြံစည်၊ပြောဆို၊ ပြုမူသည်။ နှိပ်စက်သည်။','“ယွံရသိ၊ — ဟိုတ်တၠအဲမၞုံစိုတ်မဒြိုဟ် သၟိက်ဂွံစဖျုန်ပိုဲဂစေံဖရာပ်ရောၚ်။” ဗောဓိသတ်ဖရာပ်ဂး။ (ဇ—၂၇၇။ အစွောံ။) = “အိုရသေ့၊ သင်သည် ကြမ်းကြုတ်သောစိတ်ရှိ၍ ငါတို့ခိုငှက်မျိုး၏အသားကို စားလို၏” ဟုဘုရားလောင်းခိုငှက်ဆို၏။')
,(7427,3,4,'(ကျေးဇူးရှင်၊ အဆွေခင်ပွန်းစသူအား) ပြစ်မှားသည်။ ကြမ်းကြုတ်စွာကြံစည်၊ပြောဆို၊ ပြုမူသည်။ နှိပ်စက်သည်။','“ဍေံဒြိုဟ်ကဵုမိတ်ရောၚ်သွံ။” (ဇ—၄၂၅။ အစွောံ။) = “သူသည် အဆွေခင်ပွန်းကို ပြစ်မှား၏။”')
,(7427,3,4,'(ကျေးဇူးရှင်၊ အဆွေခင်ပွန်းစသူအား) ပြစ်မှားသည်။ ကြမ်းကြုတ်စွာကြံစည်၊ပြောဆို၊ ပြုမူသည်။ နှိပ်စက်သည်။','“ယွံဂမှဳတံ၊ ဒေဝဒတ်မဒြိုဟ်ဂစိုတ်အဲဂှ် ဆလၟုဟ်ဝွံဟွံသေၚ်။ ပ္ဍဲကာလအတိက်တေံလေဝ် ဒြိုဟ်ဂစိုတ်အဲတုဲရ” ကျာ်တြဲဂး။ (ဇ—၅၁၆။ အစွောံ။) = “ရဟန်းတို့၊ ဒေဝဒတ်သည် ငါဘုရားအား ယခုအခါ­သာလျှင် ပြစ်မှားလုပ်ကြံသည်မဟုတ်သေး။ ရှေး­လည်း ပြစ်မှားလုပ်ကြံဖူးသည်သာလျှင်တည်း။”')
,(7427,3,4,'(ကျေးဇူးရှင်၊ အဆွေခင်ပွန်းစသူအား) ပြစ်မှားသည်။ ကြမ်းကြုတ်စွာကြံစည်၊ပြောဆို၊ ပြုမူသည်။ နှိပ်စက်သည်။','‘ဒမြိုဟ်’ (နဝိ) လည်းရှု။')
,(7428,3,4,'ကြမ်းကြုတ်သည်။ ရုန့်ရင်းသည်။','“ယွံအမာတ်တံ၊ သၟိၚ်မၞးတံဒြိုဟ်စာဒဇန်သဟာသဳ ပွဟွံသေၚ်ကဵုသဘဴဓဝ်ဂှ်ပတုဲ မၞးတအ်ဂစိုတ်ကၠေံ မဒးချိုတ်အာတုဲရ” သၟိၚ်အိန်ဂး။ (ဇ—၁၉၄။ အစွောံ။) = “အိုအမတ်အပေါင်းတို့၊ ရုန့်ရင်းကြမ်းကြုတ်ရက်စက်လှသော တရားမစောင့်သောသင်တို့၏မင်းသည် သင်တို့သတ်၍ သေသွားရလေပြီ” ဟုသိကြားမင်းဆို၏။')
,(7428,3,4,'ကြမ်းကြုတ်သည်။ ရုန့်ရင်းသည်။','“ကၠဝွံဍေံဒြိုဟ်စာလောန်သန်။” (ဇ—၈ဝ။ အစွောံ။) = “ဤကျားသည် အလွန်ကြမ်းကြုတ်၏။”')
,(7428,3,4,'ကြမ်းကြုတ်သည်။ ရုန့်ရင်းသည်။','“လၟတံဝွံ ဍေံဒြိုဟ်စာဒဇန်ဇဟာသဳလောန်။” (ဇ—ဘူရိဒတ်။ အစွောံ။) = “မုဆိုးတို့မည်သည်ကား အလွန်ရက်စက်ကြမ်းကြုတ်ကုန်၏။”')
,(7428,3,4,'ကြမ်းကြုတ်သည်။ ရုန့်ရင်းသည်။','“မူပစိုတ်မဂွံဂြိုဟ်စာဂလိုၚ်ဝွံရော။” (ဇ—ဝိဓုရ။အစွောံ။) = “အဘယ်ကြောင့်သင်၏စိတ်သည် ဤမျှကြမ်းကြုတ်ရလေသနည်း။”')
,(7428,3,4,'ကြမ်းကြုတ်သည်။ ရုန့်ရင်းသည်။','“ကာလသၟိၚ်ဟွံမွဲကဵုဓဝ်ဂှ် မၞိဟ်သမၠီုသဟာသဳကြံကြဂြိုဟ်စာတံဂှ် ဂွံဒှ်သၟိၚ်ရ။” (ဇ—၇၇။ အစွောံ။) =“တရားမစောင့်သောမင်းတို့၏ခေတ်လာလ­ ရက်စက်ကြမ်းကြုတ်ကုန်သော မိုက်ကုန်သောလူတို့သည် မင်းဖြစ်ရကုန်၏။”')
,(7429,3,4,'ကလဲ့စားချေသည်။ ပြန်လည်၍ကြမ်းကြုတ်သည်။','“ညးဒြိုဟ်လဝ်ကဵုဇကုကီုလေဝ် ဇကုလ္ပဒြိုဟ်ပလန်ကဵုညးညိ။” = “မိမိအပေါ် သူကြမ်းကြုတ်ထားသော်လည်း သူ့အားပြန်လည်၍ ကလဲ့စားမချေပါနှင့်။”')
,(7430,3,4,'ပြစ်မှားကျူးလွန်သည်။ မကောင်းကြံဖျက်ဆီးသည်။','“ယွံအမာတ်၊ ပြဝအမာတ်ဂှ်ဒြိုဟ်ပလီုအဲရောၚ်သွံ” သၟိၚ်ဂး။ (ဇ—၅၁။ အစွောံ။) = “အိုအမတ်၊ သင်၏အမှုသည် ငါ့ကို မကောင်းကြံဖျက်ဆီးခြင်းပေတကား” ဟုမင်းဆို၏။')
,(7431,3,16,'ကြမ်းကြုတ်သည်၊—သော။ ရုန့်ရင်းသည်၊—သော။ ခက်ထန်သည်၊—သော။','“ပူဂဵုမနွံကဵုဒေါသမာန မဒြိုဟ်သ္ကာတ်တံဂှ် ပ္ဍဲလိုက်ဝွံဂှ်လေဝ် သ္ဍိုက်ဇြဟာန်ညးဟွံမွဲရ။” (ဇ—၁၄၉။ အစွောံ။) = “ဒေါသမာနကြီးကုန်သော ရုန့်ရင်းကြမ်းကြုတ်ကုန်သောသူတို့အား ဤလောက­လည်း ချစ်နှစ်သက်သောသူမရှိ။”')
,(7431,3,16,'ကြမ်းကြုတ်သည်၊—သော။ ရုန့်ရင်းသည်၊—သော။ ခက်ထန်သည်၊—သော။','“ကောန်ဍောတ်ဝွံဂှ် ဍေံဟွံခိုဟ် ဒြိုဟ်သ္ကာတ်ဒေါသလောန်။” (ဇ—၃ဝ၄။ အစွောံ။) = “ဤသားငယ်သည်ကား မကောင်း၊ ကြမ်းကြုတ်ရုန့်ရင်း၍ လွန်ကဲသောဒေါသရှိ၏။”')
,(7431,3,16,'ကြမ်းကြုတ်သည်၊—သော။ ရုန့်ရင်းသည်၊—သော။ ခက်ထန်သည်၊—သော။','“(စိၚ်ဂှ်) ဟိုတ်ဍေံမိၚ်ဒးဂလာန်ကမၠတ် မဒြိုဟ်သ္ကာတ်တံဂှ်တုဲစိုတ်ဍေံဒြိုဟ်သ္ကာတ်အာ ဍေံလပိုက်ဂစိုတ်ကၠေံဂၟာစိၚ်ရောၚ်။” (ဇ—၂၆။ အစွောံ။) = “ထိုဆင်သည် ကြမ်းကြုတ်သောခိုးသူတို့၏ စကားကိုကြား၍ (အတုလိုက်၍) ကြမ်းကြုတ်သွားကာ ဆင်ထိန်းအား ပုတ်ခတ်သတ်ပစ်လိုက်၏။”')
,(7432,3,1,'သစ်ခက်ခြောက်။ လောၚ်စာ။','“ယွံသၟိၚ်စိၚ်၊ ပ္ဍဲဂြိုပ်ဝွံဂှ် တၞံဆုအှ်ောဒြအ် နွံဂၠိုၚ်သန်။” (ဇ—၁ဝ၅။ အစွောံ။) = “ဆင်ပြောင်ကြီး၊ ဤတော­ သစ်ခက်ခြောက်တို့သည် များလှစွာ၏။”')
,(7432,3,1,'သစ်ခက်ခြောက်။ လောၚ်စာ။','“ဒြအ်မန်စံၚ်မန်။” = “မွန်၏လောင်စာက မွန်ကိုပြန်ရှို့သည်။” (မွန်ကြောင့် မွန်ပျက်စီးဆုံးရှုံးရသည်ဟူလို။)')
,(7433,3,4,'‘ဂၠိ’ ရှု။',NULL)
,(7434,3,1,'‘ဂၠး’ ရှု။',NULL)
,(7435,3,1,'ရေချိုးခန်း။ (တြာဲဝိနယသၚ်ရိုဟ်ဂြဳ။ စန္ဒိမာ။)',NULL)
,(7436,3,1,'၁။ သန္တာ။ ခရုကျောက်။','မဒွါ = ခရုလည်ဆွဲ။')
,(7436,3,1,'၁။ သန္တာ။ ခရုကျောက်။','၂။ (ပါ) (န) တံခါး။ အပေါက်။')
,(7436,3,1,'၁။ သန္တာ။ ခရုကျောက်။','ဒွါပိ = ကိုယ်၊ နှုတ်၊ နှလုံးသုံးပါး။')
,(7436,3,1,'၁။ သန္တာ။ ခရုကျောက်။','ဒွါတြဴ = ခန္ဓာကိုယ်၏တံခါးခြောက်ပေါက်။ ဒွါရခြောက်ခု။')
,(7437,3,1,'လည်ဆွဲ။ ဆွဲကြိုး။',NULL)
,(7438,3,1,'ရာသီအလိုက် သတ်မှတ်ထားသော အရုပ်ဆယ့်နှစ်မျိုး။ ဆယ့်နှစ်ရာသီရုပ်။ (၁၊ မိဟ် (မွန်) = ကြွက်ရုပ်။ မိဿ (မြန်မာ) = ဆိတ်ကုလား (သိုး) ရုပ်။ ၂၊ ဗြိုဟ် (မွန်) = နွားလားရုပ်။ ပြိဿ (မြန်မာ) နွားလားရုပ်။ ၃၊ မေထုန် (မွန်) = ကျားရုပ်။ မေထုန် (မြန်မာ) =မိန်းမ၊ ယောကျာ်းရုပ်။ ၄၊ ကြကတ် (မွန်) = ယုန်ရုပ်။ ကရကဋ် (မြန်မာ) = ပုစွန်လုံးရုပ်။၅၊ သိၚ် (မွန်) = နဂါးရုပ်။ သိဟ် (မြန်မာ) = ခြင်္သေ့ရုပ်။ ၆၊ ကန် (မွန်) = ခါငှက်ရုပ်','စက္ကဝက်ငှက်ရုပ်?။ ကန် (မြန်မာ) = လှေစီးသတို့သမီးရုပ်။ ၇၊ တူ (မွန်) = ဆိတ်ရုပ်။ တူ (မြန်မာ) = ချိန်ခွင်ကိုင်ယောကျာ်းရုပ်။ ၈၊ ဗိစ္ဆာ (မွန်) = မြင်းရုပ်။ ဗြိစ္ဆာ (မြန်မာ) = ကင်းမြီးကောက်ရုပ်။ ၉၊ ဓနု (မွန်) = မျောက်ရုပ်။ ဓနု (မြန်မာ) = လေးစွဲယောကျာ်းရုပ်။ ၁ဝ၊မကဝ် (မွန်) = ရေကြက်ရုပ်။ မကရ (မြန်မာ) = မကန်းရုပ်။ ၁၁၊ ကုံ (မွန်) = ခွေးရုပ်။ကုံ (မြန်မာ) = အိုးထမ်းယောကျာ်းရုပ်။ ၁၂၊ မိန် (မွန်) = ဝက်ရုပ်။ မိန် (မြန်မာ) = ငါးကြင်းပွတ်ရုပ်။) (မှတ်ချက်။ ဤမွန် (၁၂) ရာသီရုပ်တို့မှာ လောကသိဒ္ဓိကျမ်းမှလာသည်။ မွန် (၁၂) လရာသီဘွဲ့­ကား အရုပ်တို့မှာ မြန်မာနှင့်တူကြသည်။)')
,(7439,3,4,'လျင်မြန်သည်။ အဆောင်တလျင်ဖြစ်သည်။ ကမန်းကတန်းဖြစ်သည်။','“ပြဝသီုမဒွါနလာဒၟံၚ်ဂှ်ပတုဲ—။” (ဇ—၃၅၂။ အစွောံ။) = “အဆောတလျင်သောအမှုကိုပြုလျက်—။”')
,(7439,3,4,'လျင်မြန်သည်။ အဆောင်တလျင်ဖြစ်သည်။ ကမန်းကတန်းဖြစ်သည်။','“ဗွဲမဒွါနလာပြဟ်ပြေဟ်ဂှ်ဒှ်တုဲ—။” (ဇ—၃၅၆။ အစွောံ။) = “လျင်မြန်သောသဘောရှိသည်ဖြစ်၍—။” (ညောင်ကန်)')
,(7439,3,4,'လျင်မြန်သည်။ အဆောင်တလျင်ဖြစ်သည်။ ကမန်းကတန်းဖြစ်သည်။','ညာတ်ဍေံဒွါလလာကၠုၚ်ဂှ် ဇာဒိသိုၚ်သၟာန်တိုန်ရ၊ “ဟာဲကၠဵု၊ မူဗှ်ေမဒြေပ်ကၠုၚ် သီုဒွါလလာရော။” (သၠပတ်ပုံပမာ။ အစွောံ။) = မြေခွေးအဆောတလျင်လာသည်ကိုမြင်သော် ခြင်္သေ့မေး၏၊ “ဟယ်မြေခွေး၊ ဘာကြောင့်အဆောတလျင်နှင့် နင်ပြေးလာသနည်း။”')
,(7440,3,1,'နှုတ်ထွက်စကား။','“တြုံလၟသ္ဂောံမိၚ်ကေတ် ဒွါပါၚ်မၚ်ဗၠာဲဂှ်တုဲ သာ်လဵုသ္ဂးတိုန်ရော။” (မုနိန္ဒဒေသနာ) = “မုဆိုးသည် လုလင်၏နှုတ်ထွက်စကားကို ကြားရပြီးနောက် မည်သို့ဆိုပါသနည်း။”')
,(7440,3,1,'နှုတ်ထွက်စကား။','“ညံၚ်ပါၚ်ကောဒှ်၊ စိုတ်ကဵုဒှ်ညိ။ ဒွါပါၚ်ကောမိ၊ ပထောံညိသၟိၚ်။” (လိက်ကောန်သၟိၚ်ပိ။မာံခစုန်အံက်။) = “မောင်တော်၏နှုတ်စကားအတိုင်း နှလုံးထားပါ၊ မယ့်မောင်တော်၏နှုတ်ထွက်စကားကို မပစ်ပယ်ပါလေနှင့်။”')
,(7441,3,10,'(န) ၁။ ထွက်ရာဝၚ်ရာအပေါက်။ တံခါးပေါက်။','၂။ စိတ်စေတသိက်တို့ဖြစ်ရာ မျက်စိ၊နား၊ နှာခေါင်း၊ လျှာ၊ ကိုယ်၊ စိတ်တည်းဟူသော အပေါက်ခြောက်ခု။')
,(7441,3,10,'(န) ၁။ ထွက်ရာဝၚ်ရာအပေါက်။ တံခါးပေါက်။','၃။ အညစ်အကြေးထွက်ရာအပေါက်။')
,(7442,3,10,'(န) (သဒ္ဒါ) ဒွိလိၚ်။ အထီးအမသဘာဝ နှစ်မျိုးစလုံးနှင့်ဆိုင်သောနာမ်။',NULL)
,(7443,3,10,'(ဂဏန်း) နှစ်ခု။',NULL)
,(7444,3,1,'အမှန်။ မှန်ကန်ခြင်း။ မှန်သောအမှု။ အကောင်းအမှန်။','“ဒၞာဲမဒှ်မုတ်ဂှ် ကဵုစှ်ေပဲါ၊ ဒၞာဲမဒှ်ဒွး ကဵုဒ္ဂေတ်ဗက်ညိ။” (သၠပတ်ကာလထေ) = “အမှားကို ရှောင်ကြဉ်စေ၊ အမှန်ကို လိုက်နာစေ။”')
,(7444,3,1,'အမှန်။ မှန်ကန်ခြင်း။ မှန်သောအမှု။ အကောင်းအမှန်။','အရေဝ်ဒွး၊ လဟီုဒွး၊ ဂလာန်ဒွး = မှန်သောစကား။')
,(7444,3,1,'အမှန်။ မှန်ကန်ခြင်း။ မှန်သောအမှု။ အကောင်းအမှန်။','“ဂစေံဂမၠိုၚ်သၟေဟ်ဂှ် လဟီုဒွးတလပညာမဟီုဂှ်လေဝ်မိၚ်ဒၟံၚ် ဟွံရိုဟ်စ ဒၟံၚ်အာတုဲ မဒးအာစိုပ်ဂစိုတ်ဝွံရ။” (ဇ—၁၃၃။ အစွောံ။) =“ကျန်သောငှက်အပေါင်းတို့သည် ပညာရှိပြောသော မှန်သောစကားကို ကြားရသော်လည်း အလေးမထားဘဲနေသဖြင့် သေခြင်းသို့ရောက်ရကုန်၏။”')
,(7444,3,1,'အမှန်။ မှန်ကန်ခြင်း။ မှန်သောအမှု။ အကောင်းအမှန်။','“ပြဝဂှ် ဟွံဒှ်ဒွးသွံ။” (ဇ—၅ဝ၄။ အစွောံ။) = “ထိုအမှုသည် အမှန်မဟုတ်ပါလား။”')
,(7444,3,1,'အမှန်။ မှန်ကန်ခြင်း။ မှန်သောအမှု။ အကောင်းအမှန်။','“ပွမဟွံဒှ်ဒွးဂှ် ထောံကၠေံညိ။ ပွမဒှ်ထမိက်ဂှ်ဒ္ဂေတ်ညိ။” (ဇ—၅၂၁။ အစွောံ။) = “မမှန်သောအမှုကို ပယ်စွန့်လော့။ ကောင်းမြတ်သောအမှုကို ပြုလော့။”')
,(7444,3,1,'အမှန်။ မှန်ကန်ခြင်း။ မှန်သောအမှု။ အကောင်းအမှန်။','“တီဒုဟ်မလုတ်တုဲ ကလေၚ်ပၠန်ဒွးကဵုပြဟ်ညိ။” (ဇ—၆၃။ အစွောံ။) = “မှားသောအပြစ်ကိုသိပြီးလျှင် အမှန်သို့ အမြန်ပြန်လှည့်ပါလေ။”')
,(7444,3,1,'အမှန်။ မှန်ကန်ခြင်း။ မှန်သောအမှု။ အကောင်းအမှန်။','မုတ်ဒွး = အမှားအမှန်။')
,(7444,3,1,'အမှန်။ မှန်ကန်ခြင်း။ မှန်သောအမှု။ အကောင်းအမှန်။','“ယြဴဂလာန်မွဲ မုတ်ကီု ဒွးကီု ညးမဟီုဂှ် ဇကုမဂွံမိၚ်ဂလာန်ဂှ်တုဲ ဂွံဗစာရဏာ—။” (သၠပတ်ဒ္ၚောဝ်သၜောံ) = “သူတစ်ပါးပြောသော အကြင်စကားသည် အမှားသော်၄င်း အမှန်သော်၄င်း မိမိကြားရပြီးလျှင် ဆင်ခြင်ရပါမည်။”')
,(7444,3,1,'အမှန်။ မှန်ကန်ခြင်း။ မှန်သောအမှု။ အကောင်းအမှန်။','‘မုတ်ဒွး’ (န) လည်းရှု။')
,(7445,3,1,'အနှောင်အဖွဲ့။ ချည်နှောင်ခြင်း။','“ကမၠတ်မဂၠိုၚ်ညးရပ်နၚ် — ညးအာဒက်လဝ်နဒွက်တသိၚ် နဒွက်ဇုက် နဒွက်ဇရေဟ် ညးမဒက်လဝ်ဗွဲမဗိုန်ရ။” (ဇ—၂ဝ၁။ အစွောံ။) = “ထိုခိုးသူတို့ကို — ခြေထိတ်အနှောင်အဖွဲ့၊ ကြိုးအနှောင်အဖွဲ့၊ သံခြေချင်းအနှောင်အဖွဲ့တို့ဖြင့် နှောင်ဖွဲ့စေ၏။”')
,(7445,3,1,'အနှောင်အဖွဲ့။ ချည်နှောင်ခြင်း။','“ယွံၝောံ၊ ကောန်ပိုဲသောဏဝွံဂှ် ပိုဲဒက်လဝ် ပ္ဍဲဒွက်သ္ၚိသၟိန်ရၝောံ” ဗမၞးဂးကဵုသမ္ဘာ။ (ဇ—၅၃၂။ အစွောံ။) = “အိုပုဏ္ဏေးမ၊ သားဖြစ်သော သောဏသတို့သားကို အိမ်ထောင်ခြင်းဟူသော အနှောင်အဖွဲ့ဖြင့် နှောင်ဖွဲ့ကုန်အံ့။” (ညောင်ကန်)')
,(7445,3,1,'အနှောင်အဖွဲ့။ ချည်နှောင်ခြင်း။','‘ဒက်’ (ကြိ) လည်းရှု။')
,(7446,3,1,'ကိလေသာ၏အနှောင်အဖွဲ့။',NULL)
,(7447,3,1,'တဏှာ၏အနှောင်အဖွဲ့။',NULL)
,(7448,3,1,'ဆံထုံး။',NULL)
,(7449,3,1,'သံသရာ၏အနှောင်အဖွဲ့။',NULL)
,(7450,3,1,'အိမ်ထောင်ခြင်း၏အနှောင်အဖွဲ့။ သံယောဇဉ်။','“ယွံၝောံ၊ ကောန်ပိုဲသောဏဝွံဂှ်ပိုဲဒက်လဝ်ပ္ဍဲဒွက်သ္ၚိသၟိန်ရၝောံ။” (ဇ—၅၃၂။ အစွောံ။) = “အိုပုဏ္ဏေးမ၊ သားဖြစ်သော သောဏသတို့သားကို အိမ်ထောင်ခြင်းဟူသော အနှောင်အဖွဲ့ဖြင့် နှောင်ဖွဲ့ကုန်အံ့။” (ညောင်ကန်)')
,(7451,3,1,'သီချင်း။',NULL)
,(7452,3,1,'၁။ အခွ။','“ကာလစိုပ်ဂၠံၚ်ၜါဒွါ်ဂှ်။” (ဇ—၅၃၇။ အစွောံ။) = “လမ်းနှစ်ခွသို့ရောက်သောအခါ။”')
,(7452,3,1,'၁။ အခွ။','“ပ္ဍဲဂၠံၚ်ဇၞော်မၞုံတရဴၜါဒွါ်ဂှ် တၞအ်မွဲနွံရ။” (ဇ—၅၂၄။ အစွောံ။) = “ခရီးနှစ်ခွရှိသောလမ်းကြီး­ တောင်ပို့တစ်ခုရှိ၏။”')
,(7452,3,1,'၁။ အခွ။','၂။ ဘက်။')
,(7452,3,1,'၁။ အခွ။','“ကွတ်ဗြဴဂၠိုၚ်ဒွါ်၊ လေပ်ဂၠိုၚ်သာ်ရ။” (လိက်သောဝိန်ဇဲယ။ မာံရောဂေါ။) = “ဘက်ပေါင်းစုံမှ အမျိုးမျိုးသော မိန်းမတို့၏အတတ်ကို တတ်၏။”')
,(7452,3,1,'၁။ အခွ။','‘ဂွါ်’ (န) ရှု။')
,(7452,3,1,'၁။ အခွ။','(ကြိ) (နှစ်ခွ၊ သုံးခွစသည်) ခွဲထွက်သည်။')
,(7452,3,1,'၁။ အခွ။','“ဒွိဓာဘိနနဋ္ဌာနေဝါ။ ပ္ဍဲဋ္ဌာန်မဒွါ်တိတ်ၜါလွးကီု။” (တြာဲဝိနယသၚ်ရိုဟ်ဂြဳ။ စန္ဒိမာ။) = “လမ်းနှစ်ခွခွဲထွက်သောအရပ်­။”')
,(7452,3,1,'၁။ အခွ။','‘ဇွာ်’ (န) လည်းရှု။')
,(7453,3,1,'သဘာဝရေကန်။','‘ကွိက်’ ရှု။')
,(7454,3,1,'ထုထောင်းရိုက်နှက်ခြင်း။ ရိုက်နှက်ချက်။','ဒးဒွိုက် = ထုထောင်းရိုက်နှက်ခံရသည်။')
,(7454,3,1,'ထုထောင်းရိုက်နှက်ခြင်း။ ရိုက်နှက်ချက်။','“(ဗောဓိသတ်တုန်) ခါမဒးဒွိုက် ဂလာန်ပန်စွံဟေၚ်မဟီုရ။” (ဇ—၆၃။ အစွောံ။) = “ဘုရားလောင်းသည် ရိုက်နှက်ထုထောင်းခြင်း ခံရသောအခါ အချက်လေးချက်ပါသော စကားကိုသာဆို၏။”')
,(7454,3,1,'ထုထောင်းရိုက်နှက်ခြင်း။ ရိုက်နှက်ချက်။','‘ဒွဵုဒွိုက်’ (န) လည်းရှု။')
,(7455,3,3,'ယုတ်သော။ ယုတ်မာသော။ ယုတ်ညံ့သော။ ဆိုးယုတ်သော။','“ဟာဲအယုတ်၊ဟာဲဗြဴဒွိုက်—။” (ဇ—၄၈၁။ အစွောံ။) = “ဟယ်အယုတ်မ၊ ဟယ်မိန်းမယုတ်—။”')
,(7455,3,3,'ယုတ်သော။ ယုတ်မာသော။ ယုတ်ညံ့သော။ ဆိုးယုတ်သော။','“ဟာဲ—ၚဴဒွိုက်၊ ဗှ်ေတံဒှ်သတ်တိရစ္ဆာန်ရောၚ်။ သိက်ပသၟိၚ်မဂွံမၚ်မွဲဗှ်ေတံမာန်ရော။ မူဟိုတ်ဗှ်ေတံမဂွံလက်သၟိၚ်ဂှ်ရော။” (ဇ—၅၂ဝ။ အစွောံ။) = “ဟယ်ဖားယုတ်၊ နင်တို့သည် တိရစ္ဆာန်များဖြစ်၏။ မင်းသည် နင်တို့ကို အဘယ်သို့စောင့်ရှောက်နိုင်မည်နည်း။ နင်တို့ဘာကြောင့် မင်းကိုဆဲဆိုရပါသနည်း။”')
,(7455,3,3,'ယုတ်သော။ ယုတ်မာသော။ ယုတ်ညံ့သော။ ဆိုးယုတ်သော။','“ဟာဲ—မၞိဟ်ဒမိက်၊ ဗှ်ေလ္ပမံၚ် ဗှ်ေအာကၠေံ၊ ဗှ်ေမၞိဟ်ဒွိုက်ရောၚ် ဗှ်ေလ္ပဒၟံၚ်။” (ဇ—၃၆၁။ အစွောံ။) = “ဟယ်လူယုတ်၊ သင်ဤမှာမနေလင့် သင်သွားလေလော့။ သင်သည် လူယုတ်မာတည်း။ သင်ဤမှာမနေလင့်။”')
,(7455,3,3,'ယုတ်သော။ ယုတ်မာသော။ ယုတ်ညံ့သော။ ဆိုးယုတ်သော။','“လ္ပကၠုၚ်ဆိုက်၊ ဗြဴဒွိုက်ပါပ။” (လိက်မိဍောၚ်ကှ်ေထဝ်) = “ဟယ်သူယုတ်မာမ၊ အနားမကပ်လာလေနှင့်။”')
,(7455,3,3,'ယုတ်သော။ ယုတ်မာသော။ ယုတ်ညံ့သော။ ဆိုးယုတ်သော။','“ပ္ဍဲဂကူဒွိုက်၊ ပိုန်ဘိုက်လေအောန်။ မက္တဵုဒှ်ပၠန်၊ ယုတ်သန်သေၚ်ဟာ။” (လိက်ပုညကာရဳ) = “ယုတ်ညံ့သောအမျိုး­ဖြစ်၍ စည်းစိမ်ဥစ္စာလည်းနည်း၏၊ အလွန်ယုတ်စွာ ဖြစ်ရပြန်၏။”')
,(7456,3,1,'ယုတ်လျော့ခြင်း။ ချိုင့်။',NULL)
,(7457,3,1,'(= ကတိုၚ်မတ်) မျက်တွင်း။ (ပါဠိ—အက္ခိကူပ) ဒွိၚ် (ကြိ) ‘ဂွိၚ်’ ရှု။',NULL)
,(7458,3,4,'‘ဂွိၚ်ဂွဲါ’ ရှု။',NULL)
,(7459,3,1,'‘ဂွိုၚ်’ ရှု။',NULL)
,(7460,3,1,'နည်းပရိယာယ်။ ဗျူဟာ။ တိုက်ဟန်။','“မၞိဟ်တက်လက်ပၠုဲ ဒးနွံကဵုဒွန်ရောၚ်။” =“လက်ဝှေ့သမားမည်သည် ပရိယာယ်ရှိရမည်။”')
,(7460,3,1,'နည်းပရိယာယ်။ ဗျူဟာ။ တိုက်ဟန်။','“သၟိၚ်ဂစိုတ်ပၠန်၊ သီုဒွန်ရံၚ်တဴ။” (လိက်ပရေၚ်ခန္ဓ) = “သေမင်းသည် ပရိယာယ်မာယာဖြင့်ကြည့်၏။”')
,(7461,3,4,'(နေရာယူ၍) အသင့်အနေအထားဖြင့်စောင့်သည်။',NULL)
,(7462,3,4,'တိုက်ဟန်အသစ်၊ နည်းပရိယာယ်အသစ်ကို ယူ၍တိုက်ခိုက်သည်။','“(တၠညး) ကေတ်ဒွန်တၟိ ၜံက်ကရာၚ်ဂတးလုပ် ဗဇဵုစိၚ်မပေတ်နဲ။” (အကြီုရာဇာဓိရာဇ်) = “ဘုရင်ရာဇာဓိရာဇ်သည် နည်းဗျူဟာသစ်ဖြင့် ချွန်းကိုချိတ်သွင်း၍ ဗျည်းနွဲ့နှင့် ဆင်စီးချင်းတိုက်၏။”')
,(7463,3,4,'ပုံစံကျသည်။ ကိုက်ညီသည်။','“အဲယိုက်ဏာကွေံ၊ ဂှ်ရောၚ်ဒးဒွန်။” (လိက်ဒေဝကိနနရဳ။ နာဲသိုက်ဇု။) = “ငါချီပိုးသယ်ဆောင်သွားသည်ကသာ ကိုက်ညီလိမ့်မည်။”')
,(7464,3,11,'(န) အစုံ။ အတွဲ။ (ပါဠိ—ဒွန္ဒ)','ညးၜါမွဲဒွန် = နှစ်ယောက်တစ်တွဲ။')
,(7464,3,11,'(န) အစုံ။ အတွဲ။ (ပါဠိ—ဒွန္ဒ)','ညးပိမွဲဒွန် = သုံးယောက်တစ်တွဲ။')
,(7464,3,11,'(န) အစုံ။ အတွဲ။ (ပါဠိ—ဒွန္ဒ)','“ဇုတ်က္ဍိုပ်မၞိဟ်အဴ၊ တြုံဗြဴသီုဒွန်။ ကဵုတီဗိုန်က္ညန်၊ ပကဵုခၠန်မှာ။ စိုပ်မှုဟ်သဓ၊ တလပညာ။” (လိက်နဲယသမုဒ္ဒြဳ။ အစွောံ။) = “ယောကျာ်းမိန်းမတို့၏ ဦးခေါင်းခွံအစုံကို မမှားစေဘဲ အမှန်ကိုသိရန် ပညာရှိမဟောသဓာထံသို့ ရောက်လာ၏။”')
,(7464,3,11,'(န) အစုံ။ အတွဲ။ (ပါဠိ—ဒွန္ဒ)','“ရုဲကညာသၟဟ်၊ထပှ်မွဲဒွန်။” (လိက်ကောန်သၟိၚ်ပိ။ မာံခစုန်အံက်။) = “ခုနစ်ယောက်တစ်တွဲ ကညာပျိုများကိုရွေးချယ်၏။”')
,(7464,3,11,'(န) အစုံ။ အတွဲ။ (ပါဠိ—ဒွန္ဒ)','‘မွဲဒွန်’ (ကြိဝိ) လည်းရှု။')
,(7465,3,1,'နားနေခြင်း။ နားနေရာ။','“စိုတ်တုပ်ညဳသာ၊ ညးၜါမွဲဂွီု။” (လိက်ကောန်ဂစေံပိ။ နာဲဗျူ။) = “တစ်စိတ်တစ်ဝမ်းတည်းဖြစ်၍ နှစ်ယောက်သားအတူတကွနေ၏။”')
,(7465,3,1,'နားနေခြင်း။ နားနေရာ။','“အာစိုပ်စဴစိုပ်၊သၞေဟ်ဗဒိုပ်ဒွီု။” (လိက်သောဝါနနဟောၚ်) = “နားနေရာစခန်းသို့ သွားရောက်ပြန်ရောက်၏။”')
,(7465,3,1,'နားနေခြင်း။ နားနေရာ။','“လမုဟ်ပိုဲၜါ၊ ဒးခြာၜါဒွီု။ ဂးတုဲဗြဴရတ်၊ ရမတ်သီုသီု။” (လိက်ပဒုမဝတဳ) = “ယခုငါတို့နှစ်ဦးသည် တစ်နေရာစီကွဲ၍ ခိုနားရာနှစ်ခုဖြစ်ခဲ့လေပြီ။ ဤသို့ဆိုကာ အလှရတနာမယ်သည် မျက်ရည်ဖြိုင်ဖြိုင်ကျ၏။”')
,(7465,3,1,'နားနေခြင်း။ နားနေရာ။','‘ခြာဒွီု’ (ကြိ) လည်းရှု။')
,(7466,3,4,'‘ဂွါန်’ ရှု။',NULL)
,(7467,3,4,'တားဆီးသည်။',NULL)
,(7468,3,1,'၁။ ဒဏ်ရာ။ ဒဏ်ချက်။','၂။ ကြိမ်ဒဏ်။ ရိုက်နှက်ချက်။')
,(7468,3,1,'၁။ ဒဏ်ရာ။ ဒဏ်ချက်။','“ဒွဵုကၠံလစုတ် မဒးကဵုကၠာရောၚ်။” (ဇ—၃၈၆။ အစွောံ။) = “ကြိမ်ဒဏ်အချက်တစ်ရာ ဦးစွာပေးရမည်။”')
,(7468,3,1,'၁။ ဒဏ်ရာ။ ဒဏ်ချက်။','“ယဝ်ရဟွံတီ၊ဒွဵုလ္ၚီကဵုဒန်။” (လိက်ကောန်သၟိၚ်ပိ။ မာံခစုန်အံက်။) = “မသိပါက ကြိမ်ဒဏ်တစ်ထောင်အပြစ်ဒဏ်ပေးရမည်။”')
,(7469,3,4,'ဒဏ်ရာရသည်။ ရိုက်နှက်ဒဏ်ခတ်ခြင်းခံရသည်။','“(ပ္ဍဲဋ္ဌာန်စၞေဟ်) ချေံသိန္ဓဴဒးစုတ်ဒွဵုတုဲ ဆီညံၚ်ဇၟောဝ်ဍာ်ကီု။” (ဇ—၂၃။ အစွောံ။) = “စစ်မြေပြင်­ သိန္ဓောမြင်းသည် ဒဏ်ရာရ၍သွေးယိုစီးလျက်ရှိ၏။”')
,(7469,3,4,'ဒဏ်ရာရသည်။ ရိုက်နှက်ဒဏ်ခတ်ခြင်းခံရသည်။','“(ပ္ဍဲဋ္ဌာန်စၞေဟ်) ချေံဇၞော်မွဲဂှ် ဒးဒွဵုကအ်ကၠောဟ်အာ။” (ဇ—၂၄။ အစွောံ။) = “စစ်မြေပြင်­ မြင်းကြီးသည် ဒဏ်ရာရ၍ လည်ပင်းပေါက်သွား၏။”')
,(7469,3,4,'ဒဏ်ရာရသည်။ ရိုက်နှက်ဒဏ်ခတ်ခြင်းခံရသည်။','“(မၞိဟ်ဂမၠိုၚ်ရပ်ၜုၚ်တက်) ချးဂှ်ဒးဒွဵု က္တဵုဟွံမာန်တုဲ သီုသတိက်ဒၟံၚ်ဂှ် ပကာဂစိုတ်ရ။” (ဇ—၁၈၉။ အစွောံ။) = “လူများဖမ်းဆီးရိုက်ပုတ်၍ ထိုမြည်းသည် ဒဏ်ရာရ၍ မထနိုင်ဘဲ လျောင်းအိပ်လျက်ပင်သေလေ၏။”')
,(7470,3,4,'ရိုက်နှက်သည်။ ပုတ်ခတ်ထုထောင်းသည်။','“ဍေံဝွံမဒှ်ကမၠတ်ရဂးတုဲ ကဵုဒွဵုတုဲ ရပ်နၚ်သၟာန်ဍေံရ။” (ဇ—၉၂။ အစွောံ။) = “ဤသူသည် ခိုးသူဖြစ်လတ္တံ့ဟု လိုက်၍ ထိုသူကိုဖမ်းကုန်၍ ပုတ်ခတ်ပြီးလျှင်— (မေးမြန်း၏။)” (ညောင်ကန်)')
,(7470,3,4,'ရိုက်နှက်သည်။ ပုတ်ခတ်ထုထောင်းသည်။','“(ဗောဓိသတ်) ကဵုဒွဵုတုဲ တ္ၜေဟ်လက်တုဲ ဗလးကၠေံညးၜါဂှ်ရ။” (ဇ—၁၉၉။ အစွောံ။) = “ဘုရားလောင်းသည် ထိုသူနှစ်ဦးတို့ကိုသတ်ပုတ်ထုထောင်း၍ ဆဲရေးပြီးလျှင် လွှတ်လိုက်၏။”')
,(7471,3,4,'နားမခံသာအောင်ပြောသည်။ ကြမ်းတမ်းစွာပြောသည်။',NULL)
,(7472,3,1,'စိတ်ဒဏ်ရာ။','“လ္ပပျဲပျာံကောန်ၚာ် ဒဵုကဵုဍေံဒးဒှ်အာဒွဵုစိုတ် မွဲအာယုက်ညိ။” = “ကလေးကို တစ်သက်ပတ်လုံး စိတ်ဒဏ်ရာဖြစ်သွားရသည်အထိ မညှဉ်းဆဲပါနှင့်။”')
,(7473,3,1,'ဘေးဒဏ်။ အပြစ်ဒဏ်။ ရိုက်နှက်ချက်။','“ပ္ဍဲဍုၚ်ဗၟာဂှ် ပၞာန်အပ္ဍဲဍုၚ်က္တဵုဒှ်ဒၟံၚ် လုကဴဗၞတ်ထပှ်စှ်ောသၞာံဂှ်ဒှ်တုဲ ကောန်ဍုၚ်ကွာန်ဂမၠိုၚ် ဒးဆဵုညာတ်တဴဘဲဒွဵုဒွိုက်ပၞာန်အိုတ်ရ။”= “မြန်မာနိုင်ငံတွင် အနှစ်ခုနစ်ဆယ်ကြာ ပြည်တွင်းစစ်ဖြစ်ပွားနေရာ ပြည်သူများသည် စစ်ဘေးစစ်ဒဏ်ကို တွေ့ကြုံခံစားခဲ့ကြရသည်။”')
,(7473,3,1,'ဘေးဒဏ်။ အပြစ်ဒဏ်။ ရိုက်နှက်ချက်။','“ကောန်ၝိုဲဂှ်မာ၊ အာထောံကၠေံပြဟ်။ ခါဟွံထောံကွေံ၊ၝိုဲဒးလၟုဟ်။ နဒွဵုဒွိုက်အဲ၊ ဘဲလေံတံဂှ်။” (လိက်ကောန်သၟိၚ်ပိ။ မာံခစုန်အံက်။) = “ညည်းသားငယ်ကို အမြန်သွားစွန့်ပစ်လော့။ မစွန့်ပစ်ပါက ငါ့ရိုက်နှက်ချက်တုတ်ချက်ဒဏ်တို့ကို ယခုပင်ညည်းခံရလိမ့်မည်။”')
,(7474,3,4,'ရိုက်ပုတ်သည်။ ရိုက်နှက်ဒဏ်ခတ်သည်။',NULL)
,(7475,3,4,'ရိုက်ပုတ်ဒဏ်ပေးခြင်းခံရသည်။','“(ဒကိုပ်ကမၠတ်ဂှ် ရပ်ဗောဓိသတ်တုဲ) နမပ္တံတၚ်တဲ ပဘဲတမာဂစိုတ်ရ။ ဗောဓိသတ်တုန် ခါမဒးဒွဵုဒွိုက် ဂလာန်သ္အာၚ်ဟွံဂွံဂးတုဲ မွဲဂလာန်ဗောဓိသတ်သ္ဂးပၠန်ရ။” (ဇ—၆၃။ အစွောံ။) = “ခိုးသားခေါင်းဆောင်သည် ဘုရားလောင်းကိုဖမ်း၍ တံတောင်စသည်ဖြင့် သေလုနီးပါးမျှ ရိုက်ပုတ်ထုထောင်း၏။ ရိုက်ပုတ်ထုထောင်းခံရသောအခါဘုရားလောင်းသည် အခြားစကားကိုမဆိုဘဲ တစ်ခုသောစကားကိုသာဆို၏။”')
,(7475,3,4,'ရိုက်ပုတ်ဒဏ်ပေးခြင်းခံရသည်။','‘ဒွဵုကွိုက်’ ဟုလည်း အနည်းအားဖြင့် တွေ့ရသည်။')
,(7476,3,1,'နှုတ်အားဖြင့် သူတစ်ပါးနာကျင်ရအောင် ပြောဆိုခြင်း။ နှုတ်အားဖြင့်ပြုသောဒဏ်ရာဒဏ်ချက်။','“(ပူဂဵု) မကဵုဒွဵုပါၚ်ဒွဵုတဲကဵုညးဂှ် ဟွံဂပ်ဂဝ်ပတှ်ေ ဟွံဂပ်ဂဝ်ဒက်မိတ်။” (သၠပတ်စှ်ၜါရာသဳ) = “နှုတ်အားဖြင့်၄င်း လက်အားဖြင့်၄င်း သူတစ်ပါးနာကျင်ဒဏ်ရာရအောင် ပြုသောသူအား မယုံကြည်အပ်၊ မိတ်မဖွဲ့အပ်။”')
,(7477,3,1,'ဒဏ်ရာ။ အနာ။','“ကွာန်စလေဝွံ နွံပၞာန်ချေံ ဒွအ်စုတ်သရာဲပိုဲ ဒှ်ဒွဵုသရသာ်ဝွံ—။” (အကြီုရာဇာဓိရာဇ်) = “စလေရွာသည် ရန်သူ့မြင်းတပ်ရှိ၍ ငါတို့၏သူရဲသူခက်တို့ကို တိုက်ခိုက်သဖြင့် ဤသို့ဒဏ်ရာအနာတရဖြစ်ရ၏။”')
,(7478,3,4,'ထိသည်။ တိုက်သည်။ ထိတွေ့သည်။ ထိခတ်သည်။','“ညံၚ်ပ္တေၚ်မပက်ဏာဒစးကျာတုဲ ညံၚ်ဍေံမကလေၚ်ကၠုၚ်ဒွံဇကုပၠန်ကီု။” (ဇ—၄ဝ၆။ အစွောံ။) = “လေဆန်အရပ်သို့ ပက်ကြဲလိုက်သောပြာသည် မိမိဆီပြန်လာထိခတ်သကဲ့သို့။”')
,(7478,3,4,'ထိသည်။ တိုက်သည်။ ထိတွေ့သည်။ ထိခတ်သည်။','“နတဲအဲ ဟွံဒွံဍေံရ။” (ဇ—၄၅၄။ အစွောံ။) = “ငါ့လက်ဖြင့် သူ့ကိုငါမထိပါ။”')
,(7478,3,4,'ထိသည်။ တိုက်သည်။ ထိတွေ့သည်။ ထိခတ်သည်။','“ဂွံညာတ်နမတ် ဒွံနတဲ။” (ဇ—၅၆။ အစွောံ။) =“မျက်စိဖြင့်မြင်၍ လက်ဖြင့်ထိတွေ့သည်။”')
,(7478,3,4,'ထိသည်။ တိုက်သည်။ ထိတွေ့သည်။ ထိခတ်သည်။','“ဗောဓိသတ်အာက္ၜၚ် ဍာ်ဖနုၚ်ဒွံဒးမတ်တုဲ မတ်လီုအာသီုၜါရ။” (ဇ—၄၆၃။ အစွောံ။) = “ဘုရားလောင်းသည် သင်္ဘောသွားသောအမှုကိုပြုရာဆားၚန်ရေဖြင့် ခတ်မိသည်ဖြစ်၍ မျက်စိနှစ်ဖက်တို့သည် ပျက်ကုန်၏။” (ညောင်ကန်)')
,(7478,3,4,'ထိသည်။ တိုက်သည်။ ထိတွေ့သည်။ ထိခတ်သည်။','“ယွံမၞးတံ၊ မမိက်ကဵုညးမွဲကီု ကျာဗြဲဒွံဇကုမၞးတံဟာ” ဗောဓိသတ်သၟာန်၊ “ဟွံဒွံ” ညးဂမၠိုၚ်ဂး။ (ဇ—၁။ အစွောံ။) = “အချင်းတို့၊ (သင်တို့အနက်မှ) တစ်စုံတစ်ယောက်သောသူအား ကိုယ်ကို မိုးသက်လေသည် ခတ်သလော” ဟုဘုရားလောင်းမေး၏၊ “မခတ်” ဟု လူအများဆိုကုန်၏။')
,(7478,3,4,'ထိသည်။ တိုက်သည်။ ထိတွေ့သည်။ ထိခတ်သည်။','“ရှ်ကြုက်ဂှ် ယာံဒွံဒးလတာ်အဲတုဲ အလုံလတေၚ်ထပှ်လ္ၚီဂှ် ဗျာပ်အာတုဲ ဗျဵုတဟၚ်ဗၠးအိုတ်ရ။” (ဇ—၅၁၁။ အစွောံ။) = “ထိုသရက်သီးအရသာသည် ငါ၏လျှာဖျား­ထိသည်နှင့် အကြောပေါင်းခုနစ်ထောင်လုံးသို့ စိမ့်၍ပျံ့နှံ့သွားကာ မွတ်သိပ်ခြင်းသည် ပြေပျောက်ကုန်၏။”')
,(7478,3,4,'ထိသည်။ တိုက်သည်။ ထိတွေ့သည်။ ထိခတ်သည်။','“ဗောဓိသတ် (တၟာတ်) ဒွံဒးပးဒၞက်—။” (ဇ—၃၉၉။ အစွောံ။) = “ဘုရားလောင်းလင်းတသည် ကျော့ကွင်းကိုတိုက်မိ၏။”')
,(7479,3,1,'လောင်းကြေးငွေ။ လောင်းတမ်း။ လောင်းကစားခြင်း။ (ပါဠိ—အဗ္ဘုတ)','“မမာ်သီုသ္ကေံဂှ် ဒတုံစှ်ေအာသီုဖအိုတ်တုဲ ကၞုဲဂှ် ကဏပ်ဇဝ်ဒၟံၚ် ညံၚ်ညးမကျဒြပ်ဒွအ်လ္ၚီကသာပ်ကီု။” (ဇ—၁၇၆။ အစွောံ။) = “လက်ထဲမှ ကုလားပဲဆုပ်အားလုံး ကျသွားသဖြင့် ထိုမျောက်သည်လောင်းကစားရာ­ (တရားတွေ့ရာ­')
,(7479,3,1,'လောင်းကြေးငွေ။ လောင်းတမ်း။ လောင်းကစားခြင်း။ (ပါဠိ—အဗ္ဘုတ)','ညောင်ကန်) တစ်ထောၚ်သောဥစ္စာကို ရှုံးသောသူကဲ့သို့မှိုင်လျက်နေ၏။”')
,(7479,3,1,'လောင်းကြေးငွေ။ လောင်းတမ်း။ လောင်းကစားခြင်း။ (ပါဠိ—အဗ္ဘုတ)','ကျဒွအ် = လောင်းကစားရာတွင် လောင်းကြေးကိုရှုံးသည်။')
,(7479,3,1,'လောင်းကြေးငွေ။ လောင်းတမ်း။ လောင်းကစားခြင်း။ (ပါဠိ—အဗ္ဘုတ)','(ကြိ) လောင်းကြေးလောင်းသည်။ လောင်းကစားသည်။')
,(7479,3,1,'လောင်းကြေးငွေ။ လောင်းတမ်း။ လောင်းကစားခြင်း။ (ပါဠိ—အဗ္ဘုတ)','“တြုံသမၠီုမဒွံလဝ်ထဝ်လ္ၚီဂှ် ကျအာရ။” (သၠပတ်ကုလဇာတ်) = “ရွှေသားတစ်ထောင် လောင်းကြေးလောင်းထားသော ယောကျာ်းမိုက်သည် ရှုံးသွား၏။”')
,(7480,3,4,'ဒုက္ခတွေ့သည်။','“ကာလဒွအ်ဒဒိုက် ဗှ်သၞာမိမရ။” = “ဒုက္ခတွေ့သောအခါ မိဘကိုသတိရသည်။”')
,(7480,3,4,'ဒုက္ခတွေ့သည်။','“ပ္ဍဲလိုက်ဝွံ ယြဴပူဂဵုမွဲ မဒွံဒဒိုက် တလိၚ်ဒိုဟ်မ္ဂး ဟွံချပ်သ္ၚဳဂၠာဲဥပ္ပါယ် မသ္ဂောံဗၠးဒဒိုက်တုဲ မသ္ဂောံဗၠးနူဒဒိုက်ဂှ် ဟွံမွဲရ။” (ဇ—၁၁၈။ အစွောံ။) = “လောက­ အကြင်သူသည် ဒုက္ခတွေ့သောအခါ၊ ဒုက္ခမှလွတ်မြောက်စေမည့် ဥပါယ်တမျဉ်ကို မရှာကြံဘဲ ထိုဘေးဒုက္ခမှ လွတ်မြောက်ရိုးမရှိ။”')
,(7481,3,4,'ထိခိုက်သည်။ ထိတိုက်သည်။ ထိပါးသည်။','(ဗောဓိသတ်) ကာလမဒြေပ်ဝေၚ်ဒှ်ဂှ် အာဝေၚ်ဖဴကောန်ၚာ်တံဂမၠိုၚ်တုဲ ကာလမဒွံဒွါစုတ်ညးဂှ် “ဍေံဏအ်မွဲ ကောန်ဟွံမွဲကဵုမရောၚ်။မကၠုၚ်ဝေၚ်ဖဴပိုဲရောၚ်” ညးဂး။ (ဇ—၇။ အစွောံ။) = ဘုရားလောင်းသည် ပြေးကစားတတ်သောအရွယ်သို့ရောက်၍ ကလေးများနှင့်တကွ ကစားသည်ရှိသော် ကစားဖော်တို့အား ထိခိုက်တိုက်မိသောအခါ “ဤကလေးသည် ဖခင်မရှိသောသားတည်း။ ငါတို့နှင့်တကွ လာကစား၏”ဟုဆိုကုန်၏။')
,(7481,3,4,'ထိခိုက်သည်။ ထိတိုက်သည်။ ထိပါးသည်။','“ဗောဓိသတ်ပမှာလီ ဍိုက်က္ၜၚ်ညးလၟိုန်ရ။ ဟိုတ်နွံကဵုပညာဂှ်ရ ဒၞာဲအာဂှ် က္ၜၚ်ဟွံဂွံဒွံဒွါ ဟွံလၞၚ်မွဲလှ်ေ။” (ဇ—၄၆၃။ အစွောံ။) = “ဘုရားလောင်းသည် သင်္ဘောသူကြီးဖြစ်၍အမြဲသင်္ဘောလိုက်၏။ ပညာရှိခြင်းကြောင့် သွားလေရာ သင်္ဘောတိုက်မိခြင်း သောင်တင်ခြင်းတစ်ခါမျှမရှိစဖူး။”')
,(7481,3,4,'ထိခိုက်သည်။ ထိတိုက်သည်။ ထိပါးသည်။','“သတြုတၟမွဲမွဲ လ္ပကဵုဒွံဒွါညိဂးတုဲ ဗွဲဂတသၟိၚ်ကွဴဂှ် ကွဴဝုတ်မသုန်ကၠံ ကဵုပဝ်အာဂတရ။” (ဇ—၅၃၆။ အစွောံ။) = “တစ်ခုခုသောရန်သူတို့သည် ဥသြမင်းအား မထိပါးပါစေသတည်းဟု ငါးရာကုန်သောဥသြပျိုမတို့ကို ဥသြမင်းရှေ့မှ ပျံသွားစေကုန်၏။”')
,(7481,3,4,'ထိခိုက်သည်။ ထိတိုက်သည်။ ထိပါးသည်။','“စိၚ်စှ်ေကၠေၚ်နွံဂၠိုၚ်သန်။ ဍေံကုဍေံ ဒွံဒွါရၚ်သ္ကံပၠန်တုန်—။” (အကြီုရာဇာဓိရာဇ်) = “မုန်ယိုသောဆင်များစွာရှိ၍ အချင်းချင်းထိုးခတ်ကြကုန်၏။”')
,(7481,3,4,'ထိခိုက်သည်။ ထိတိုက်သည်။ ထိပါးသည်။','“မပ္တံကဵုနိမိတ်သၞဲမွဲမွဲဂှ် ဍေံဒွံဒွါကၟိန်ဍုၚ်က္ဍိုၚ်ဗ္တာၚ် မောင်မဂၞကျာ်လေဝ်ကီု ဇကုတၠတိဇၞော်လေဝ်ကီု ဍုၚ်ရးနိဂီုကဵုသတ္တံဂမၠိုၚ်လေဝ်ကီု မရှာတ်ညာတ်ညိကီုဟာအဴ။” (သၠပတ်သုရသာ) = “တိုင်းပြည်ထီးဖြူ မောင်းမမိဖုရားများကိုဖြစ်စေ၊ ဘုရင်ကိုယ်တိုင်ကိုလည်းဖြစ်စေ၊ ပြည်ရွာနိဂုံးနှင့်လူများကိုလည်းဖြစ်စေ ထိခိုက်စေမည့် တစ်စုံတစ်ခုသောနိမိတ်ကိုသင်မင်းမြတ်မြင်သလော။”')
,(7481,3,4,'ထိခိုက်သည်။ ထိတိုက်သည်။ ထိပါးသည်။','“ကောန်မရှာတ်ဝွံ ယဝ်ရမရှာတ်စွံလဝ် ပ္ဍဲဍုၚ်မ္ဂးဝွံ ——၊ ဟွံသေၚ်ဒွံဒွါမရာတ်ဟာ၊ ဟွံသေၚ်ဒွံဒွါဂၞကျာ်ဟာ ဒှ်ဗိုန်ရ။” (သၠပတ်သုရသာ) = “အရှင်မင်းမြတ်၏သားတော်ကို တိုင်းနိုင်ငံ­ထားပါက အရှင်မင်းမြတ်အားသော်၄င်း သို့တည်းမဟုတ် မိဖုရားအားသော်၄င်း ထိခိုက်လိမ့်မည်အမှန်တည်း။”')
,(7482,3,4,'ဘေးသင့်သည်။ ဘေးတွေ့သည်။ ဘေးအန္တရာယ်ကြုံတွေ့သည်။','“ညးဂှ် မဒွံဘဲဝွံရော။” (ဇ—၅၃၄။ အစွောံ။) = “အဘယ်သူသည် ဘေးတွေ့လေသနည်း။”')
,(7482,3,4,'ဘေးသင့်သည်။ ဘေးတွေ့သည်။ ဘေးအန္တရာယ်ကြုံတွေ့သည်။','“ကောပိုဲဝွံ ဒွံဘဲပရိုက်တုဲရ။” = (ဇ—၅ဝ၁။ အစွောံ။) = “ငါတို့နောင်တော်သည် ဘေးသင့်ခဲ့လေပြီ။”')
,(7482,3,4,'ဘေးသင့်သည်။ ဘေးတွေ့သည်။ ဘေးအန္တရာယ်ကြုံတွေ့သည်။','“လၟုဟ်ကောပိုဲလအ်၊ ဒွအ်ဘဲဆတ္တဝ်။” (လိက်ကောန်သၟိၚ်ပိ။ မာံခစုန်အံက်။) = “ယခုငါတို့နောင်တော် ကြာနေသည်မှာ ဘေးသင့်သည်အမှန်တည်း။”')
,(9556,3,4,'စကားထာဝှက်သည်။',NULL)
,(9557,3,1,'အိပ်ရာ။',NULL)
,(9558,3,1,'အိမ်၏အရှေ့တောင်ထောင့်ရှိ နတ်ခြင်းဆွဲသောတိုင်။ အိမ်ဦးတိုင်။',NULL)
,(9559,3,1, '(ကြက်ငှက်စသည်၏) အတက်။',NULL)
;